-- Part A: exercise_catalog rows (Your Move browse-mode catalog).
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4c55ca15-3665-4db7-b11d-7d4273263f66','1 Leg Broad Jump','1-leg-broad-jump-c982db','Starting position: Stand on one leg with a slight bend in the knee, torso hinged forward, and arms drawn back behind you. Execution: Explosively swing your arms forward and drive off the standing leg to jump forward as far as possible, landing softly on the same or opposite leg and absorbing the impact through the hip, knee, and ankle.',ARRAY['Balance on one leg with knee slightly bent and hinge at the hips, swinging arms back.','Load the standing leg by lowering into a partial single-leg squat.','Drive the arms forward and explode off the leg to jump forward horizontally.','Extend the hip, knee, and ankle fully for maximum distance.','Land softly with a bent knee, absorbing force and stabilizing the landing.','Reset and repeat for the desired reps before switching legs.']::text[],ARRAY['Land softly with a bent knee to protect the joints and control momentum.','Use a powerful arm swing to maximize jump distance.','Keep your core braced and chest up to maintain balance on landing.','Fully extend the hip and drive through the foot for explosive power.']::text[],'glutes',ARRAY['calves','core','adductors']::text[],'bodyweight','plyometric','advanced',ARRAY['plyometric','functional','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ecf8bc6c-e7c9-4dcb-949a-e04f6e0c93bb','1 Leg Lateral Broad Jump','1-leg-lateral-broad-jump-c0bf1f','Starting position: Balance on one leg with a slight bend in the knee, keeping the core engaged and the opposite foot lifted off the floor. Execution: Explosively push off the standing leg to jump laterally as far as possible, landing softly on the same leg with a controlled bend to absorb the impact and maintain balance.',ARRAY['Stand on one leg with a slight knee bend and the other foot raised.','Load the standing leg by dipping into a mini quarter-squat and swinging the arms back.','Drive explosively sideways, propelling your body laterally through the air.','Land softly on the same leg, bending the knee and hip to absorb the impact.','Stabilize your balance before resetting or performing the next jump.']::text[],ARRAY['Land with a soft, controlled knee bend to protect the joints.','Keep your core braced and chest up to maintain balance throughout.','Ensure the knee tracks in line with the toes on landing.','Use your arms to generate momentum and aid stabilization.']::text[],'quads',ARRAY['glute_med','hip_flexors','tibialis_anterior']::text[],'bodyweight','plyometric','advanced',ARRAY['plyometric','balance','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c2fbe7d4-e9a5-41f8-b8eb-d903948d268b','1 Leg Left Right Hop over Cone','1-leg-left-right-hop-over-cone-36621e','Starting position: Balance on one leg with the other knee lifted, standing beside a cone with knees softly bent and arms ready to assist. Execution: Explosively hop laterally over the cone from side to side, landing softly on the same single leg while maintaining balance and control.',ARRAY['Stand on one leg next to a cone with the opposite knee bent and lifted.','Bend the standing knee slightly and swing your arms to generate power.','Hop sideways over the cone, pushing off the ground with your standing leg.','Land softly on the same leg on the other side, absorbing impact through the knee and hip.','Immediately stabilize and hop back over the cone to the starting side.','Continue hopping side to side for the prescribed reps, keeping balance throughout.']::text[],ARRAY['Land softly with a bent knee to absorb impact and protect the joint.','Keep your core engaged to maintain balance on the single leg.','Use your arms to help drive momentum and control landings.','Stay light on your feet and minimize ground contact time.']::text[],'quads',ARRAY['gastrocnemius','soleus','glute_med','tibialis_anterior']::text[],'cone','plyometric','intermediate',ARRAY['plyometric','cardio','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4a816d4c-e7b1-4e18-823f-64d0c4eee38b','4 Square Drill','4-square-drill-d45871','Starting position: Stand upright beside or within a four-square grid marked on the floor, feet hip-width apart, core braced, elbows bent and hands up in an athletic guard. Execution: Explosively hop from quadrant to quadrant in a set pattern, landing softly on the balls of the feet while driving the knees up and rapidly repositioning the feet, maintaining balance and speed throughout.',ARRAY['Set up the four-square grid on the floor and stand in an athletic stance with knees slightly bent.','Push off the balls of your feet and hop into the next square, staying light and quick.','Drive your knees up and pump your arms to control momentum with each jump.','Land softly, absorbing impact through your ankles, knees, and hips.','Continue moving through the square pattern in sequence at a rapid, controlled pace.','Repeat for the prescribed time or number of rounds.']::text[],ARRAY['Land softly on the balls of your feet to reduce joint impact.','Keep your core tight and torso slightly forward for balance.','Maintain quick, light foot contacts rather than heavy stomping.','Use your arms to help drive and stabilize each hop.']::text[],'quads',ARRAY['calves','glutes','hip_flexors']::text[],'bodyweight','plyometric','intermediate',ARRAY['plyometric','cardio','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','71bf8e65-38ff-4145-b42c-341c8d574b59','8 Count Body Builder','8-count-body-builder-4da68d','Starting position: Stand upright with feet together, arms relaxed at your sides, and core engaged. Execution: Squat down to place hands on the floor, kick both feet back into a plank, perform a push-up, jump feet apart and back together, then jump feet toward hands and explosively jump up. Completing the eight-count sequence.',ARRAY['Begin standing tall with feet together and arms at your sides.','Squat down and place both hands flat on the floor in front of you.','Kick both feet back to land in a high plank position, then lower into a push-up.','Push back up, jump your feet apart and then back together while in plank.','Jump your feet forward toward your hands into a low squat.','Explosively jump straight up reaching overhead, then land softly and repeat.']::text[],ARRAY['Keep your core braced throughout to protect your lower back during the plank and push-up phases.','Maintain a straight line from head to heels in the plank. Avoid sagging hips.','Land softly from the jump with bent knees to absorb impact.','Move through each count with control before increasing speed.']::text[],'full_body',ARRAY['cardiovascular_system','hip_flexors','calves','abs']::text[],'bodyweight','cardio','advanced',ARRAY['cardio','plyometric','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3620635f-3fcb-4552-8959-dc6ec09d9ea2','A steps','a-steps-576b25','Starting position: Stand tall with feet hip-width apart, arms bent at 90 degrees, core engaged. Execution: Drive one knee up explosively to hip height while pumping the opposite arm forward, then quickly switch to a rhythmic marching or skipping pattern coordinating opposite arm and leg.',ARRAY['Stand tall with your chest up, core braced, and elbows bent at 90 degrees.','Drive one knee up powerfully toward hip height while pumping the opposite arm up.','Return the leg to the ground with a light, springy foot contact.','Immediately drive the opposite knee up, coordinating the opposite arm swing.','Maintain an upright posture and rhythmic tempo throughout each repetition.']::text[],ARRAY['Keep your torso tall and avoid leaning back as you drive the knee.','Coordinate opposite arm to opposite leg for balanced rhythm.','Land softly on the balls of your feet to absorb impact.','Drive the knee to hip height for full range and power.']::text[],'hip_flexors',ARRAY['hamstrings','tibialis_anterior','front_deltoids']::text[],'bodyweight','cardio','intermediate',ARRAY['cardio','plyometric','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ee79ed25-3455-4730-acd9-5173de6085c9','Ab Bridge Complex','ab-bridge-complex-895db8','Starting position: Lie face down and prop yourself up on your forearms with elbows directly beneath your shoulders, feet together and toes tucked under. Execution: Lift your hips off the floor to form a straight line from head to heels, brace your core, and hold the bridge position while breathing steadily.',ARRAY['Position your forearms flat on the mat with elbows under your shoulders and hands clasped or parallel.','Extend your legs behind you, resting on the balls of your feet with toes tucked.','Lift your hips and knees off the floor until your body forms a straight line from head to heels.','Brace your abdominals, squeeze your glutes, and keep your neck neutral looking down.','Hold the position for the prescribed time while breathing steadily.','Lower back to the floor with control to finish.']::text[],ARRAY['Keep your body in one straight line. Avoid sagging hips or piling up at the hips.','Draw your navel toward your spine to keep the core fully engaged.','Keep elbows stacked directly under your shoulders to protect the joints.','Breathe steadily rather than holding your breath throughout the hold.']::text[],'core',ARRAY['front_deltoids','spinal_erectors','glute_max','quads']::text[],'bodyweight','core','beginner',ARRAY['core','isometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5058baec-15c8-4278-afa5-9621bb4e15b5','Alternating Dumbbell Curl','alternating-dumbbell-curl','Starting position: Sit or standing holding a dumbbell in each hand with palms facing forward. Execution: Flex one elbow to lift one dumbbell toward shoulder, alternating with the other hand each repetition.',ARRAY['Sit or stand and maintain a straight posture with core engaged','Hold dumbbells with arms fully extended at your sides, palms facing forward','Curl one dumbbell up by bending at the elbow, keeping your upper arm stationary against your torso','Squeeze your bicep at the top of the movement, then slowly lower the weight back to starting position','Repeat the same motion with the opposite arm while keeping the rested arm still','Continue alternating arms for the desired number of repetitions']::text[],ARRAY['Keep your core tight and avoid swinging or using momentum to lift the weights','Maintain control throughout the entire range of motion, especially during the lowering phase','Keep your elbows close to your torso and avoid letting them drift forward or backward','Focus on squeezing the bicep at the top of each curl for maximum muscle activation','Choose a weight that allows you to maintain proper form throughout all repetitions']::text[],'biceps','{}'::text[],'dumbbell','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7a94a32f-40d9-42eb-b03d-afe76c71ea36','Alternating Side Reaches','alternating-side-reaches-3254e9','Starting position: Sit tall on a chair with feet flat on the floor, hips and knees at about 90 degrees, and both arms extended overhead. Execution: Reach one arm up and over to the side, lengthening through the torso and lateral trunk, then return to center and repeat on the opposite side in an alternating fashion.',ARRAY['Sit upright on the chair with feet planted and spine tall.','Extend both arms straight overhead, keeping shoulders relaxed.','Reach and lean gently to one side, feeling a stretch along the opposite ribcage and waist.','Return smoothly to the upright center position.','Repeat the reach to the other side, alternating with controlled movement.','Continue alternating for the prescribed reps or time.']::text[],ARRAY['Keep your hips grounded and avoid lifting off the seat as you lean.','Move slowly and lengthen the spine rather than crunching to the side.','Breathe out as you reach and inhale as you return to center.','Keep the neck relaxed and gaze forward throughout.']::text[],'obliques',ARRAY['front_deltoids','core']::text[],'chair','stretching','beginner',ARRAY['stretching','mobility','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9acaf8fd-1e81-4106-8d86-921b013f36c0','Arch Skydiver','arch-skydiver-a5f177','Starting position: Lie prone on a mat with your legs bent at the knees and lifted, arms extended forward overhead, and chest resting on the mat. Execution: Simultaneously lift your chest, arms, and upper body off the floor by contracting your lower back and glutes, hold briefly, then lower with control back to the start.',ARRAY['Lie face down on the mat with arms extended overhead and knees bent, feet lifted.','Engage your core and glutes to stabilize the spine.','Raise your chest, arms, and shoulders off the mat by squeezing your lower back.','Hold the arched position briefly at the top.','Lower your upper body back down with control.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your neck neutral by gazing at the floor throughout.','Lift using your back and glutes rather than jerking your neck.','Avoid overextending the lower back; move within a comfortable range.','Maintain steady breathing, exhaling as you lift.']::text[],'erector_spinae',ARRAY['glute_max','rhomboids','lower_traps']::text[],'bodyweight','core','beginner',ARRAY['strength','core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d06c3d04-aeb4-4b94-9a43-24e95201239c','Archer push up','archer-push-up','Starting position: Begin in a wide push-up position with hands placed significantly wider than shoulder-width apart, arms fully extended. Execution: Lower your body by bending one arm while keeping the other arm straight, shifting your weight toward the bent arm side, then push back to the starting position and alternate sides.',ARRAY['Start in a wide push-up position with hands placed significantly wider than shoulder-width apart and feet hip-width apart\','Lower your body by shifting your weight to one side, bending that arm while keeping the opposite arm straight','Descend until your chest nearly touches the ground near your bent arm, with the straight arm extended to the side','Push back up by driving through your bent arm while maintaining the straight arm position','Return to the starting position and repeat on the opposite side','Alternate sides for each repetition or complete all reps on one side before switching']::text[],ARRAY['- Keep your core engaged and body in a straight line throughout the movement','- The straight arm should remain locked out and act as a support, not assist with pushing','- Start with regular push-ups and single-arm assisted variations before attempting archer push-ups','- Focus on controlled movement rather than speed to maximize muscle engagement and prevent injury','- If too difficult, elevate your hands on a sturdy surface or perform on your knees']::text[],'chest','{}'::text[],'bodyweight','chest','advanced',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5ba69aaa-7f7a-4564-940e-c6fb7da55c26','Arm swings','arm-swings-34a3a3','Starting position: Stand tall with feet hip-width apart, knees soft, core engaged, and arms relaxed at your sides. Execution: Swing both arms horizontally across the front of your body and then back out to the sides in a continuous, rhythmic motion to loosen the shoulders and upper body.',ARRAY['Stand with feet hip-width apart and maintain a tall, neutral spine.','Raise your arms to roughly chest height in front of you.','Swing both arms horizontally across your chest so they cross over.','Reverse the movement, swinging your arms back out to the sides.','Continue swinging in a smooth, controlled rhythm without locking the elbows.']::text[],ARRAY['Keep your core braced and avoid twisting excessively through the torso.','Maintain soft knees and relaxed shoulders throughout the swings.','Control the momentum rather than letting your arms flail.','Breathe steadily and keep the movement fluid.']::text[],'shoulders',ARRAY['traps','serratus_anterior','forearms']::text[],'bodyweight','warmup','beginner',ARRAY['warmup','mobility','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','52fb4e42-549e-4af2-a83d-f0c6c76f38ae','Armpit Opener','armpit-opener-e8e10d','Starting position: Sit upright on a chair with feet flat on the floor, spine tall and hands resting on the thighs. Execution: Raise the arms out to the sides and open them wide, drawing the shoulder blades together to stretch and open the armpit and chest region, then return under control.',ARRAY['Sit tall on the chair with feet flat and shoulders relaxed away from the ears.','Lift both arms out to the sides, keeping the chest lifted.','Open the arms wide and draw the shoulder blades together to feel a stretch across the chest and armpits.','Hold the open position briefly while breathing deeply.','Slowly bring the arms back to the starting position with control.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep the spine tall and avoid arching the lower back.','Move slowly and avoid forcing the range of motion.','Relax the shoulders down away from the ears throughout.','Breathe steadily, exhaling as you open the arms.']::text[],'chest',ARRAY['biceps','rotator_cuff','traps']::text[],'chair','mobility','beginner',ARRAY['mobility','stretching','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','109f6115-f03d-48da-802a-2e2aa385678d','Back Extension - Hyperextension','back-extension-hyperextension-9e0c7f','Starting position: Position yourself face down on the hyperextension machine with your hips at the pad edge and feet secured. Execution: Lower your torso by hinging at the hips, then extend back up to the starting position.',ARRAY['Position yourself face down on the hyperextension machine','Place your hips at the front edge of the pad','Secure your feet under the foot pads','Cross your arms over your chest or behind your head','Lower your torso by hinging at the hips slowly','Extend back up to the starting position']::text[],ARRAY['Keep your spine neutral throughout the entire movement','Focus on hinging at the hips rather than rounding your back','Avoid hyperextending beyond a straight line with your body','Control the descent to maximize muscle activation and prevent injury','Engage your glutes and hamstrings along with your lower back muscles']::text[],'back',ARRAY['glute_max','hamstrings','core']::text[],'machine','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4061bcd4-25a4-48ce-abbe-765986eb91e5','Back Extension on Ball','back-extension-on-ball-ed3d35','Starting position: Lie face down with your hips and lower abdomen resting on a stability ball, feet extended behind and toes on the mat, hands placed lightly behind the head with torso flexed forward over the ball. Execution: Engage your lower back and glutes to extend the spine, lifting your chest and upper body upward until your body forms a straight line, then lower under control back to the starting position.',ARRAY['Position your hips and lower stomach over the stability ball with feet anchored on the floor.','Place your hands gently behind your head and let your torso curve over the ball.','Squeeze your glutes and contract your lower back to raise your chest and upper body.','Extend until your body is in a straight line from head to heels.','Pause briefly at the top, then lower slowly back to the start.','Repeat for the desired number of repetitions.']::text[],ARRAY['Move in a controlled manner and avoid hyperextending the spine.','Keep your neck neutral and avoid pulling on your head with your hands.','Engage your glutes and core throughout to protect the lower back.','Keep feet firmly anchored for stability.']::text[],'erector_spinae',ARRAY['glute_max','hamstrings','abs']::text[],'stability ball','core','beginner',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4d4779ae-ab3c-4f3b-8c9f-566a23c80437','Back Shuffle','back-shuffle-1e4dbe','Starting position: Stand in an athletic stance with knees slightly bent, hips hinged, torso leaning slightly forward, and arms bent at your sides. Execution: Quickly shuffle backwards using short, rapid steps, staying light on the balls of your feet while keeping your core engaged and knees soft throughout the movement.',ARRAY['Adopt an athletic stance with knees bent and torso leaning slightly forward.','Keep your weight on the balls of your feet with arms bent for balance.','Push off and take quick, small steps to travel backward.','Maintain a low, stable hip position as you shuffle.','Keep your core tight and eyes forward to control direction.','Continue shuffling for the prescribed time or distance.']::text[],ARRAY['Stay low and keep knees soft to protect the joints.','Take short, rapid steps rather than large strides.','Keep your chest up and avoid rounding the lower back.','Maintain balance by keeping weight on the balls of the feet.']::text[],'cardiovascular_system',ARRAY['calves','quads','hip_flexors']::text[],'bodyweight','cardio','beginner',ARRAY['cardio','plyometric','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','854b33d7-6d88-4a67-a5d5-4e7e2983b140','back stretch','back-stretch-5ab5be','Starting position: Stand tall facing a stable bench or chair placed at about arm''s length in front of you, feet hip-width apart and arms relaxed at your sides. Execution: Hinge forward at the hips and reach your hands toward the bench, allowing your spine to lengthen and your back to gently stretch as you hold the position, then return to standing.',ARRAY['Stand facing a sturdy bench with your feet hip-width apart.','Hinge at the hips and reach both hands forward toward the bench surface.','Let your head and neck relax as your spine lengthens into the stretch.','Hold the stretch, breathing deeply and feeling tension release along the back.','Slowly rise back to standing by reversing the movement.']::text[],ARRAY['Keep a slight bend in the knees to avoid overloading the hamstrings.','Hinge from the hips rather than rounding excessively through the spine.','Move smoothly and avoid bouncing during the stretch.','Breathe steadily and relax deeper into the position with each exhale.']::text[],'lower_back',ARRAY['hamstrings','glutes','upper_back']::text[],'chair','stretching','beginner',ARRAY['stretching','cooldown','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','80b6b175-77a8-48ac-9a09-495d114d88ef','Backward lunges','backward-lunges','Starting position: Stand tall with feet hip-width apart, hands on hips or at your sides, core engaged and shoulders back. Execution: Step one foot backward into a lunge position, lowering your hips until both knees are bent at approximately 90 degrees, then push through your front heel to return to the starting position.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Step your right foot backward about 2-3 feet, landing on the ball of your foot','Lower your hips straight down until your front thigh is parallel to the floor and your back knee nearly touches the ground','Keep your front knee aligned over your ankle and avoid letting it drift forward past your toes','Push through your front heel to drive yourself back to the starting position','Repeat for desired reps, then switch legs']::text[],ARRAY['Keep your torso upright throughout the movement to maintain proper form and maximize quad engagement','Control the descent slowly rather than dropping down quickly to prevent injury and increase muscle activation','Ensure your front knee stays aligned with your toes and doesn''t cave inward during the movement','Focus your weight on your front leg as this is the working leg that targets the quadriceps','Take a large enough step backward to allow both knees to bend to 90 degrees comfortably']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fa45710a-ee56-4648-811c-5eeaaeaff098','Band Leg press','band-leg-press-6f6bfd','Starting position: Lie on your back on a mat with the resistance band looped around the soles of your feet and the ends held firmly in your hands near your chest. Bend your knees toward your torso. Execution: Press both feet away from your body against the band resistance until your legs are nearly straight and extended upward at an angle, then slowly bend the knees to return to the start.',ARRAY['Lie supine on the mat and wrap the band around the balls of both feet, holding the ends by your chest.','Draw your knees in toward your chest to create tension in the band.','Press your feet away against the band resistance until your legs are almost fully extended.','Pause briefly at full extension while keeping the core braced.','Slowly bend the knees to lower back to the starting position under control.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your lower back pressed into the mat to protect the spine.','Move slowly and control the band on both the press and the return.','Maintain steady tension in the band throughout the range of motion.','Avoid letting the knees flare out; keep them tracking in line with the feet.']::text[],'quads',ARRAY['glute_max','hamstrings','abs']::text[],'band','strength','beginner',ARRAY['strength','rehabilitation','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1dda1f16-d715-4a4f-a12b-d75b7dca81e7','Banded Lateral Walks','banded-lateral-walks-e6e162','Starting position: Place a resistance loop band around your lower legs or ankles, feet hip-width apart, knees slightly bent in a quarter-squat with hands on hips and chest upright. Execution: Step laterally to one side against the band''s resistance, then bring the trailing foot in to reset the tension, keeping the band taut and hips level throughout the walk.',ARRAY['Loop the band around your ankles and set feet hip-width apart to create initial tension.','Bend the knees into a slight squat and place hands on your hips for stability.','Step one foot out to the side while maintaining constant band resistance.','Bring the trailing foot in, stopping before the band goes slack.','Continue stepping in one direction, then repeat leading with the other leg.']::text[],ARRAY['Keep constant tension on the band and avoid letting the knees cave inward.','Maintain a stable athletic squat position with chest up and core braced.','Move from the hips, not by bouncing the torso side to side.','Keep steps controlled and hips level throughout the set.']::text[],'glute_med',ARRAY['glute_max','adductors','quads']::text[],'band','strength','beginner',ARRAY['strength','functional','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9a68f965-4e58-4b5b-87d5-c44929dd1f39','Banded squat','banded-squat-10268f','Starting position: Stand with feet shoulder-width apart, a resistance band looped around your thighs just above the knees, and hands clasped in front of your chest. Execution: Push your hips back and bend your knees to lower into a squat while pressing your knees outward against the band, then drive through your heels to return to standing.',ARRAY['Place the band around your thighs above the knees and set feet shoulder-width apart.','Clasp your hands in front of your chest and brace your core.','Push your hips back and bend your knees to lower into a squat.','Actively press your knees outward against the band to keep them tracking over your toes.','Drive through your heels to stand back up, squeezing your glutes at the top.','Maintain constant tension on the band throughout the set.']::text[],ARRAY['Keep your chest lifted and back neutral, avoiding rounding.','Do not let your knees cave inward against the band.','Push your knees out and keep weight on your heels.','Descend until thighs are roughly parallel to the floor.']::text[],'quads',ARRAY['calves','erector_spinae','hip_flexors']::text[],'band','strength','beginner',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a64ffb04-76a7-431a-a9a5-6addeab61813','Barbell Ab Rollout','barbell-ab-rollout','Starting position: Kneel on the floor with a barbell placed on the ground in front of you, gripping the bar with both hands shoulder-width apart. Execution: Slowly roll the barbell forward while maintaining a straight line from your knees to your head, then pull it back to the starting position using your core muscles.',ARRAY['Kneel on a mat or soft surface with the barbell positioned directly in front of your knees','Grip the barbell with both hands using an overhand grip, hands positioned shoulder-width apart','Engage your core and maintain a neutral spine as you slowly roll the barbell forward','Extend only as far as you can while maintaining proper form and control','Use your abdominal muscles to pull the barbell back to the starting position','Complete the movement in a slow, controlled manner throughout the entire range of motion']::text[],ARRAY['Keep your hips stable and avoid letting them sag or pike upward during the movement','Start with a shorter range of motion and gradually increase as your core strength improves','Stop immediately if you feel any lower back pain or discomfort','Breathe out as you roll forward and breathe in as you return to starting position','Focus on using your core muscles rather than your arms to control the barbell']::text[],'core','{}'::text[],'barbell','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','31a0d4f4-2ad8-4f51-b47f-e7dc05e787f3','Barbell Ab Rollout - On Knees','barbell-ab-rollout-on-knees','Starting position: Kneel on the floor with a barbell placed in front of you, gripping the bar with both hands shoulder-width apart, arms extended. Execution: Roll the barbell forward by extending your hips and shoulders while maintaining a straight line from your knees to your head, then pull back to the starting position using your core muscles.',ARRAY['Kneel on a mat or soft surface with the barbell positioned directly in front of your knees','Grip the barbell with both hands using an overhand grip, hands placed shoulder-width apart','Engage your core and maintain a neutral spine before beginning the movement','Roll the barbell forward slowly by extending at the hips and shoulders, keeping arms straight','Lower your body until you feel a strong stretch in your abs, stopping before your hips sag','Pull the barbell back toward your knees by contracting your core muscles and reversing the movement']::text[],ARRAY['Keep your core tight throughout the entire movement to prevent lower back hyperextension','Only roll out as far as you can while maintaining proper form and control','Avoid letting your hips sag or pike up during the exercise','Focus on slow, controlled movements rather than speed or range of motion','Stop immediately if you feel any lower back pain or discomfort']::text[],'core','{}'::text[],'barbell','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','65e95132-e6bb-41e8-af7d-0eda931a1693','Barbell Back Squat','barbell-back-squat','Starting position: Place a barbell on your upper back and position feet shoulder-width apart. Execution: Lower your body into a deep squat while keeping your back straight, then push up to return to the starting position.',ARRAY['Set the barbell at chest height in the squat rack and position safety bars just below your lowest squat position','Step under the bar and position it on your upper traps, gripping the bar with hands evenly placed wider than shoulder-width','Unrack the bar by standing up and take 2-3 steps backward, then set your feet shoulder-width apart with toes slightly turned out','Initiate the movement by pushing your hips back and bending your knees, keeping your chest up and core engaged','Descend until your hip crease is just below your knee caps while maintaining a neutral spine','Drive through your heels and push the floor away to return to the starting position, fully extending your hips and knees']::text[],ARRAY['Keep your knees tracking in line with your toes throughout the entire movement to prevent knee valgus','Maintain a tight core and neutral spine position - avoid excessive forward lean or rounding of the back','Control the descent and avoid bouncing at the bottom of the movement to prevent injury','Focus on driving through your heels rather than your toes to properly activate the posterior chain','Ensure full hip and knee extension at the top of each rep before beginning the next repetition']::text[],'quads','{}'::text[],'barbell','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','69b5e89d-e2d4-4e9a-8ab7-4c28cff1f3e1','Barbell Bench Press','barbell-bench-press-122b71','Starting position: Lie flat on a bench with feet planted on the floor, eyes under the barbell, and grip the bar slightly wider than shoulder-width with a full grip. Retract the shoulder blades and maintain a slight arch in the lower back. Execution: Unrack the bar and hold it over the chest with arms extended, then lower it under control to the mid-chest before pressing back up to full extension.',ARRAY['Set up on the bench with eyes under the bar and grip slightly wider than shoulder-width.','Retract and depress your shoulder blades, planting your feet firmly on the floor.','Unrack the bar and position it directly over your chest with arms fully extended.','Lower the bar under control to touch your mid-chest, keeping elbows at about 45 degrees.','Press the bar back up in a slight arc to full lockout without bouncing off the chest.','Repeat for the desired reps, then rack the bar safely.']::text[],ARRAY['Keep your shoulder blades retracted and wrists stacked over your elbows.','Avoid flaring elbows fully out to protect the shoulders.','Maintain full-body tension with feet driving into the floor.','Do not bounce the bar off the chest; control the eccentric.']::text[],'chest',ARRAY['front_deltoids','triceps','forearms']::text[],'barbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d552a696-bf87-4bf7-9597-fa425d617874','Barbell Bench Press decline','barbell-bench-press-decline-0f5470','Starting position: Lie back on a decline bench with feet secured, grip the barbell slightly wider than shoulder-width, and unrack it so the bar is held over the lower chest with arms extended. Execution: Lower the bar under control to the lower chest, then press it back up powerfully until the arms are fully extended, keeping the elbows tucked at a moderate angle.',ARRAY['Set the bench to a decline angle and lie back with feet locked under the pads.','Grip the barbell just wider than shoulder-width and unrack it over your lower chest.','Lower the bar slowly to touch the lower chest while keeping elbows controlled.','Press the bar back up explosively until arms are fully extended.','Pause briefly at the top and repeat for the desired reps.','Rerack the bar carefully after completing the set.']::text[],ARRAY['Keep your wrists straight and stacked over your elbows throughout.','Maintain shoulder blade retraction and avoid flaring elbows excessively.','Control the descent and avoid bouncing the bar off the chest.','Keep feet anchored and hips down on the bench for stability.']::text[],'lower_chest',ARRAY['triceps_lateral_head','front_deltoids','serratus_anterior']::text[],'barbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b853fd08-4739-4239-a825-8c31826d54ba','Barbell calf raises','barbell-calf-raises','Starting position: Stand upright with feet hip-width apart, holding a barbell across your upper back in the same position as a back squat, with the balls of your feet on a stable platfor. Execution: Rise up onto your toes by contracting your calf muscles to lift your heels as high as possible, pause briefly at the top, then slowly lower your heels below the starting position for a full stretch.',ARRAY['Position the barbell securely on your upper back using proper rack positioning and ensure the safety bars are set at an appropriate height','Maintain an upright torso with core engaged and knees slightly bent throughout the movement','Rise up smoothly by pushing through the balls of your feet until you reach maximum heel height','Hold the peak contraction briefly, then lower your heels slowly below the platform level for a full stretch','Keep your weight balanced and avoid bouncing at the bottom of the movement']::text[],ARRAY['Use a full range of motion by getting a deep stretch at the bottom and maximum contraction at the top','Keep the movement slow and controlled to maximize muscle tension and prevent injury','Ensure the platform is stable and non-slip to maintain balance with the loaded barbell','Start with lighter weight to master the balance and form before progressively adding load']::text[],'calves','{}'::text[],'barbell','legs','beginner',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','71cd3500-6a12-4ad9-b9c4-5b4c20f33deb','Barbell Curl 21s','barbell-curl-21s','Starting position: Stand holding an EZ bar with hands in a medium grip position. Execution: Perform 7 reps of curls from bottom to midpoint, 7 from midpoint to top, and 7 full repetitions.',ARRAY['Stand upright with core engaged and shoulders back, gripping the barbell with palms facing forward','Keep elbows close to your sides throughout all three phases of the exercise','First, perform 7 reps curling only from full extension to 90 degrees (bottom half)','Immediately perform 7 reps curling from 90 degrees to full contraction (top half)','Finish with 7 complete full range-of-motion reps from bottom to top','Maintain controlled tempo and avoid swinging or using momentum throughout all 21 repetitions']::text[],ARRAY['Keep wrists straight and maintain a firm grip to prevent the barbell from rolling in your hands','Focus on squeezing the biceps at the top of each rep, especially during the partial and full contractions','Avoid leaning back or swaying your body to lift the weight as this reduces bicep activation','Control the negative portion of each rep rather than letting the weight drop quickly','This is an advanced technique that creates significant muscle fatigue, so reduce weight compared to standard barbell curls']::text[],'biceps','{}'::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1158c681-55e9-4db0-bb73-3dab32d99aa5','Barbell Curls','barbell-curls','Starting position: Stand upright with feet shoulder-width apart, holding a barbell with an underhand grip at arm''s length in front of your thighs. Execution: Curl the barbell upward by flexing your biceps until your forearms touch your biceps, then slowly lower back to the starting position.',ARRAY['Stand holding bar with underhand grip','Arms at sides, shoulder-width grip','Curl bar toward shoulders','Squeeze biceps at top','Lower with control']::text[],ARRAY['Keep elbows at sides','Don''t swing or use momentum','Full extension at bottom','Full contraction at top','Keep wrists straight']::text[],'biceps',ARRAY['brachialis','brachioradialis','forearm_flexors']::text[],'barbell','arms','beginner',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7d31d648-432b-4edd-97bc-afc2a3e9e59a','Barbell Deadlift','barbell-deadlift','Starting position: Stand with feet shoulder-width apart and a barbell in your hands in front of your thighs. Execution: Hinge forward at the hips lowering the bar toward the ground while maintaining a straight back and slightly bent knees, then slowly return to the starting position.',ARRAY['Position your feet hip-width apart with the barbell over the middle of your feet','Hinge at the hips and bend your knees to grip the bar with hands just outside your legs','Keep your chest up, shoulders back, and maintain a neutral spine throughout the movement','Drive through your heels and push the floor away as you stand up, extending hips and knees together','Keep the bar close to your body as it travels up your shins and thighs','Lower the weight by pushing your hips back first, then bending your knees once the bar passes them']::text[],ARRAY['Maintain a neutral spine throughout the entire movement to prevent back injury','Keep the barbell as close to your body as possible during both the lifting and lowering phases','Engage your core muscles and keep your shoulders pulled back and down','Start with lighter weight to master proper form before progressing to heavier loads','Avoid rounding your back or letting your knees cave inward during the lift']::text[],'full_body',ARRAY['core','forearms','adductors','upper_back']::text[],'barbell','full body','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2fb79823-a759-4ceb-8b16-a26ab3cfb440','Barbell Deadlift','deadlift-88','Starting position: Stand with feet hip-width apart, hinge at the hips and bend knees slightly while keeping your back straight and chest up. Execution: Drive through your heels and push your hips forward to return to standing position, squeezing your glutes at the top.',ARRAY['Position feet hip-width apart with toes pointing slightly outward','Hinge at the hips by pushing your buttocks back while keeping knees slightly bent','Lower your torso by continuing the hip hinge movement until you feel a stretch in your hamstrings','Keep your chest up and maintain a neutral spine throughout the movement','Drive through your heels and push your hips forward to return to the starting position','Squeeze your glutes at the top and stand tall with shoulders back']::text[],ARRAY['Keep the movement initiated from your hips, not your knees or back','Maintain a neutral spine throughout the entire range of motion','Focus on feeling the stretch in your hamstrings during the lowering phase','Avoid rounding your back or letting your knees cave inward','Control the descent and use your posterior chain muscles to power the return movement']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','069c1e6b-05f4-4390-a1c7-9b740e0bec4a','Barbell Front Raise','barbell-front-raise','Starting position: Stand holding a barbell with a pronated grip (palms down). Execution: Raise the bar forward until it reaches shoulder height, then slowly lower.',ARRAY['Stand with feet hip-width apart, holding a barbell with an overhand grip, hands shoulder-width apart, arms extended down in front of your thighs','Engage your core and maintain a slight bend in your knees with shoulders pulled back and down','Keeping your arms straight with a slight elbow bend, slowly lift the barbell forward and up until it reaches shoulder height','Pause briefly at the top position, then slowly lower the barbell back to the starting position with control','Repeat for desired repetitions while maintaining proper form throughout the movement']::text[],ARRAY['Keep your core engaged throughout to prevent arching your back','Use a weight that allows you to maintain control - avoid swinging or using momentum','Stop at shoulder height to prevent shoulder impingement','Maintain a neutral spine and avoid leaning backward during the lift','Focus on smooth, controlled movement both up and down']::text[],'shoulders','{}'::text[],'barbell','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0e5f29cd-ff79-428a-bb1c-1753a9047f32','Barbell Full Squat','barbell-full-squat','Starting position: Stand with feet shoulder-width apart, barbell resting on your upper trapezius muscles (high bar position), core engaged and chest up. Execution: Lower your body by pushing hips back and bending knees until thighs are parallel to the floor or below, then drive through your heels to return to starting position.',ARRAY['Position the barbell on your upper trapezius muscles (high bar) or rear deltoids (low bar), step back from the rack, and set feet shoulder-width apart with toes slightly turned out.','Engage your core, keep your chest up and spine neutral, then initiate the movement by pushing your hips back and bending at the knees.','Lower your body until your hip crease drops just below your knee caps, maintaining weight distributed evenly across your feet.','Drive through your heels and push the floor away to return to starting position, keeping your knees tracking over your toes throughout the movement.','Complete the rep by fully extending your hips and knees while maintaining proper posture.']::text[],ARRAY['Always use a squat rack with safety bars set just below your lowest squat position','Keep your knees aligned with your toes - avoid letting them cave inward','Maintain a neutral spine throughout the entire movement - avoid rounding your back','Control the descent and avoid bouncing at the bottom of the squat','Start with bodyweight or an empty barbell to master the movement pattern before adding weight']::text[],'quads',ARRAY['calves','hip_flexors','abs']::text[],'barbell','legs','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b43b051d-cd66-41c7-8772-f81797ce872c','Barbell Glute Bridge','barbell-glute-bridge','Starting position: Lie on your back with knees bent, feet flat on the floor hip-width apart, and a barbell positioned across your hip crease with hands gripping the bar for stability. Execution: Drive through your heels to lift your hips up by squeezing your glutes, creating a straight line from knees to shoulders, then lower back down with control.',ARRAY['Lie on back, knees bent, feet flat','Drive hips up by squeezing glutes','Form straight line from shoulders to knees','Lower with control']::text[],ARRAY['Squeeze glutes hard at top','Don''t hyperextend lower back','Drive through heels','Hold at top briefly','Foundation for hip thrusts']::text[],'glutes','{}'::text[],'barbell','legs',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','74c36be0-d1e4-4703-8c54-612c2da1dcc1','Barbell Good Morning','barbell-good-morning','Starting position: Stand with a barbell resting on your upper back, feet shoulder-width apart. Execution: Hinge forward at the hips while maintaining a straight back and slightly bent knees, then slowly return to the starting position.',ARRAY['Position the barbell across your upper traps and grip it with hands wider than shoulder-width apart','Stand with feet hip-width apart, knees slightly bent, and core engaged','Initiate the movement by pushing your hips back while keeping your chest up and spine neutral','Lower your torso forward until you feel a good stretch in your hamstrings, typically to about 45-degree angle','Drive your hips forward and squeeze your glutes to return to the upright starting position','Maintain control throughout the entire range of motion']::text[],ARRAY['Keep your knees slightly bent throughout the movement to protect your knee joints','Focus on the hip hinge movement pattern rather than bending at the waist to properly target the hamstrings','Maintain a neutral spine and avoid rounding your back, especially at the bottom of the movement','Start with lighter weight to master the movement pattern before progressing to heavier loads','Stop the descent when you feel a good stretch in your hamstrings rather than forcing excessive range of motion']::text[],'hamstrings',ARRAY['glute_max','adductors','upper_back']::text[],'barbell','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5990deac-a91d-4531-8c2f-a708fc95fd1f','Barbell Hip Thrust','barbell-hip-thrust','Starting position: Lie face up with shoulders supported on a bench and feet flat on the floor. Execution: Lift your hips upward by squeezing your glutes, then lower slowly to the starting position.',ARRAY['Upper back on bench, bar over hips','Feet flat on floor, knees bent','Drive hips up by squeezing glutes','Form straight line from shoulders to knees','Lower with control']::text[],ARRAY['Pad the bar for comfort','Chin slightly tucked','Drive through heels','Full hip extension at top','Don''t hyperextend lower back']::text[],'glutes','{}'::text[],'barbell','legs',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','de7f1e4f-cb03-446d-b768-4a93baae1ab2','Barbell Incline Bench Press - Medium Grip','barbell-incline-bench-press-medium-grip','Starting position: Lie on an incline bench set at 30-45 degrees with feet flat on the floor, gripping the barbell with hands positioned slightly wider than shoulder-width apart. Execution: Lower the barbell in a controlled manner to your upper chest, then press it back up to the starting position while maintaining proper form.',ARRAY['Set bench to 30-45 degrees','Lie back, grip bar slightly wider than shoulders','Unrack, position bar over upper chest','Lower to upper chest/clavicle area','Press up with control']::text[],ARRAY['Targets upper chest','Don''t set bench too steep (becomes shoulder press)','Keep shoulder blades retracted','Touch chest, don''t bounce','Control the negative']::text[],'chest','{}'::text[],'barbell','chest',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','714b176e-2963-43f0-ae0f-c71643cbe426','Barbell Lunge','barbell-lunge','Starting position: Place a barbell across your upper back and position one foot forward in a lunge stance while the other foot remains behind. Execution: Lower your body toward the floor by bending both knees, then push up to return to the starting position and repeat with the other leg.',ARRAY['Bar on upper back','Stand with feet together','Step forward into lunge','Lower until back knee near floor','Push back to starting position','Alternate legs or complete one side']::text[],ARRAY['Keep torso upright','Front knee tracks over toes','Don''t let front knee shoot past toes','Control the descent','Step back, not forward if balance is hard']::text[],'quads','{}'::text[],'barbell','legs',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','dd57e914-d0ef-4d6f-8724-d72f220b7422','Barbell Lunges','barbell-lunges-336de0','Starting position: Stand tall with a barbell resting across your upper back and traps, hands gripping the bar wider than shoulder-width, feet hip-width apart and core braced. Execution: Step forward with one leg and lower your body until both knees are bent at roughly 90 degrees, with the rear knee approaching the floor, then push through the front heel to return to standing and repeat on the other side.',ARRAY['Position the barbell across your upper traps and grip it firmly with both hands.','Step forward with one leg, keeping your torso upright and core engaged.','Lower your hips until the front thigh is parallel to the floor and the rear knee nearly touches the ground.','Drive through the front heel to return to the starting position.','Alternate legs or complete all reps on one side before switching.']::text[],ARRAY['Keep your torso upright and avoid leaning forward.','Ensure the front knee tracks over the toes and does not cave inward.','Control the descent and avoid slamming the rear knee down.','Brace your core throughout to maintain balance and protect the spine.']::text[],'quads',ARRAY['glute_med','adductors','calves']::text[],'barbell','strength','intermediate',ARRAY['strength','functional','balance']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c0bd82fb-5ad6-4390-a060-dd46c1a6bea2','Barbell Overhead Press','barbell-overhead-press-fc0760','Starting position: Stand tall with feet shoulder-width apart, holding a barbell racked across the front of the shoulders with hands just outside shoulder width and elbows slightly forward. Execution: Brace the core, then press the barbell overhead in a straight line until the arms are fully extended, and lower it back to the shoulders under control.',ARRAY['Set up with the barbell resting on your front deltoids, hands just outside shoulder width.','Brace your core and squeeze your glutes to create a stable base.','Press the bar straight overhead, moving your head slightly back to clear the path.','Lock out the elbows with the bar over the mid-line of your body.','Lower the bar under control back to the starting position on the shoulders.']::text[],ARRAY['Keep your core tight and avoid arching the lower back excessively.','Do not use leg drive; keep the movement strict from the shoulders.','Move your head back as the bar clears your face, then bring it forward at lockout.']::text[],'shoulders',ARRAY['triceps_long_head','serratus_anterior','upper_traps']::text[],'barbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f71ef5e3-8944-40df-b9ea-00a7b0e6c5cc','Barbell Push Press','barbell-push-press-aee15e','Starting position: Stand with feet hip-width apart holding a barbell racked across the front of your shoulders with elbows up and hands just outside shoulder width. Execution: Perform a shallow dip by bending the knees, then explosively drive through the legs to propel the bar upward, pressing it overhead until arms are fully extended before lowering it back to the shoulders.',ARRAY['Rack the barbell on your front shoulders with elbows pointing forward and hands slightly wider than shoulders.','Brace your core and perform a quick, shallow dip by bending the knees and hips.','Explosively extend your legs to drive the bar off your shoulders.','As the bar rises, press it overhead until your arms are locked out.','Lower the bar under control back to the shoulder rack position and reset for the next rep.']::text[],ARRAY['Keep the dip shallow and vertical, avoiding forward knee travel.','Drive with the legs first, then finish with the arms for maximum power transfer.','Keep the core tight and torso upright throughout the movement.','Finish with the bar directly overhead, aligned over your midfoot.']::text[],'shoulders',ARRAY['triceps','quads','core','upper_traps']::text[],'barbell','strength','intermediate',ARRAY['strength','functional','plyometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','be7a8c2a-db1b-405f-a61f-96f26c628c6c','Barbell Romanian Deadlift','barbell-romanian-deadlift-5c76c6','Starting position: Stand upright holding a barbell with an overhand grip at hip level, feet hip-width apart, knees slightly bent, and shoulders pulled back. Execution: Hinge at the hips, pushing your glutes backward while lowering the barbell along the front of your legs until you feel a stretch in your hamstrings, then drive your hips forward to return to standing.',ARRAY['Stand tall gripping the barbell with hands shoulder-width apart at your thighs.','Set a slight bend in your knees and brace your core.','Hinge at the hips, pushing your buttocks back and lowering the bar down your legs.','Keep the bar close to your body and back flat as you descend.','Lower until you feel a stretch in the hamstrings, keeping the spine neutral.','Drive your hips forward to return to the upright starting position.']::text[],ARRAY['Maintain a neutral spine throughout; avoid rounding the lower back.','Keep the barbell close to your legs during the entire movement.','Lead the movement with your hips, not by squatting down.','Keep a soft, fixed bend in the knees rather than bending them further.']::text[],'hamstrings',ARRAY['glute_max','spinal_erectors','forearm_flexors']::text[],'barbell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','dbf6a8e4-19dc-4d01-8014-f195a1eb817c','Barbell Rows','barbell-rows','Starting position: Stand with feet hip-width apart, holding a barbell with an overhand grip slightly wider than shoulder-width, arms extended and torso hinged forward at the hips. Execution: Pull the barbell up toward your lower chest by driving your elbows back and squeezing your shoulder blades together, then lower with control.',ARRAY['Set up with the barbell on the floor or rack at about mid-shin height','Hinge at the hips to lean forward approximately 45 degrees while maintaining a neutral spine','Grip the barbell with hands slightly wider than shoulder-width using an overhand grip','Engage your core and pull the barbell toward your lower chest by driving elbows back','Squeeze shoulder blades together at the top of the movement','Lower the barbell slowly and under control to the starting position']::text[],ARRAY['Keep your core engaged throughout the movement to protect your lower back','Focus on pulling with your back muscles rather than just your arms','Maintain a consistent torso angle throughout the exercise','Avoid using momentum or swinging the weight up']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4e4377e1-ab91-4015-84ac-27b3274b549f','Barbell Shoulder Press -  Barbell Overhead Press - Barbell Military Press','barbell-shoulder-press-barbell-overhead-press-barbell-military-press','Starting position: Stand with feet shoulder-width apart, holding a barbell at shoulder level with hands positioned slightly wider than shoulder-width, elbows slightly forward. Execution: Press the barbell straight overhead until arms are fully extended, then lower the weight back to the starting position at shoulder level in a controlled manner.',ARRAY['Set up with the barbell in a rack at shoulder height and position yourself with feet shoulder-width apart','Grip the bar with hands slightly wider than shoulders using an overhand grip','Unrack the bar and position it at shoulder level with elbows directly beneath the bar','Engage your core and maintain a neutral spine throughout the movement','Press the bar straight up overhead until arms are fully extended without arching your back excessively','Lower the bar slowly back to shoulder level while maintaining control']::text[],ARRAY['Keep your core tight and avoid excessive back arching to prevent lower back injury','Press the bar in a straight line directly overhead rather than forward to maintain proper bar path','Ensure elbows stay under the bar at the bottom position to maximize stability and power transfer','Use a full grip around the bar rather than a thumbless grip for better control and safety','Start with lighter weight to master the movement pattern before progressing to heavier loads']::text[],'shoulders','{}'::text[],'barbell','shoulders',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a363775e-2aa5-49cb-ac17-7aa137d5d47b','Barbell Shrug','barbell-shrug','Starting position: Stand upright with feet hip-width apart, holding a barbell with an overhand grip at arm''s length in front of your thighs. Execution: Lift your shoulders straight up toward your ears as high as possible, hold briefly, then lower them back down in a controlled manner.',ARRAY['Hold bar at thighs, arms straight','Feet shoulder-width apart','Shrug shoulders straight up toward ears','Hold at top briefly','Lower with control']::text[],ARRAY['Don''t roll shoulders (straight up and down)','Keep arms straight throughout','Hold the squeeze 1-2 seconds','Don''t bend elbows','Let traps fully stretch at bottom']::text[],'shoulders',ARRAY['rhomboids','forearms']::text[],'barbell','shoulders','beginner',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','709f2fe5-f590-401b-aa94-d5f6dc67165b','Barbell Sit-Up','barbell-sit-up','Starting position: Lie on your back and hold a barbell with both hands. Execution: Flex your torso lifting the barbell toward your thighs while keeping your legs on the ground.',ARRAY['Lie down with knees bent at 90 degrees and feet firmly planted on the ground','Hold the barbell with both hands across your upper chest, keeping your grip secure','Engage your core and slowly curl your torso up, leading with your chest rather than your neck','Rise up until your torso is at approximately 45 degrees from the floor','Slowly lower yourself back down to the starting position with control','Maintain steady breathing throughout the movement, exhaling on the way up']::text[],ARRAY['Keep your lower back pressed against the floor during the lowering phase to prevent injury','Focus on using your abdominal muscles rather than pulling with your neck or using momentum','Start with a lighter weight barbell to master the form before progressing to heavier loads','Keep your feet planted throughout the entire movement to maintain stability','Control the descent portion of the movement as this provides significant muscle activation']::text[],'core','{}'::text[],'barbell','core','intermediate',ARRAY['strength','core']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d0a73aa8-dc45-49dd-951d-de4825a74ada','Barbell Skull Crushers','barbell-skull-crushers-f97e8d','Starting position: Lie flat on a bench holding a barbell with an overhand grip, arms extended straight up over your chest or slightly angled back toward your head. Execution: Bend at the elbows to lower the bar toward your forehead, keeping your upper arms stationary, then extend your elbows to press the bar back to the starting position, squeezing the triceps.',ARRAY['Lie flat on a bench and grip the barbell shoulder-width or slightly narrower with an overhand grip.','Extend your arms so the bar is above your chest with a slight backward angle.','Keeping upper arms fixed, bend your elbows to lower the bar toward your forehead.','Stop just above your forehead, feeling the stretch in your triceps.','Extend your elbows to press the bar back up to the starting position.','Repeat for the desired number of repetitions with controlled tempo.']::text[],ARRAY['Keep your upper arms stationary and elbows pointed forward, avoid flaring them out.','Lower the bar under control to protect your elbows and forehead.','Do not lock out aggressively; keep tension on the triceps throughout.','Maintain a stable core and keep your back flat on the bench.']::text[],'triceps',ARRAY['forearm_flexors','front_deltoids','core']::text[],'barbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c8f3362d-fb00-481e-b428-e0b17f4ae681','Barbell Sumo Squat','barbell-sumo-squat-c8f3362d','Starting position: Place a barbell on your upper back with feet wider than shoulder-width and toes slightly pointed out. Execution: Lower your body into a deep squat while keeping your back straight, then push up to return to starting position.',ARRAY['Position the barbell securely on your upper trapezius muscles and grip it with hands slightly wider than shoulder-width','Set your feet 1.5 times shoulder-width apart with toes angled outward and engage your core','Initiate the movement by pushing your hips back while keeping your chest up and spine neutral','Descend by bending at the hips and knees simultaneously until your thighs reach parallel to the floor','Drive through your heels and push the floor away to return to the starting position','Maintain the wide stance throughout the entire movement and avoid letting knees cave inward']::text[],ARRAY['Keep your knees tracking in line with your toes throughout the entire range of motion to prevent knee injury','Maintain a proud chest position and avoid rounding your back under the weight','The wider stance targets the inner quads and glutes more effectively than a traditional squat','Focus on flexibility in your hip adductors as the wide stance requires good mobility','Control the descent and avoid bouncing at the bottom of the movement']::text[],'quads','{}'::text[],'barbell','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1ffaf9e8-fe94-44e8-a20b-012ea58eba46','Barbell Sumo Squat','barbell-sumo-squat','Starting position: Place a barbell on your upper back with feet wider than shoulder-width and toes pointed slightly outward. Execution: Lower your body into a deep squat while keeping your back straight, then push up to return to starting position.',ARRAY['Position the barbell securely on your upper trapezius muscles and grip the bar with hands wider than shoulder-width','Set your feet in a wide stance with toes turned out 30-45 degrees and engage your core','Initiate the movement by pushing your hips back and bending your knees while keeping your chest upright','Descend until your thighs are parallel to the floor or as low as your mobility allows','Drive through your heels and push the floor away to return to the starting position','Maintain tension in your glutes and core throughout the entire movement']::text[],ARRAY['Keep your knees aligned with your toes throughout the movement to prevent knee valgus and potential injury','Maintain a neutral spine by keeping your chest up and avoiding excessive forward lean','The wider stance targets the inner thighs and glutes more than a conventional squat while still engaging the quadriceps','Focus on pushing through your heels rather than your toes to maximize glute activation and maintain balance']::text[],'quads','{}'::text[],'barbell','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6e9512fe-74b9-4c8a-bae2-a54361937b0e','Barbell Thruster - Straight Bar Thruster','barbell-thruster-straight-bar-thruster','Starting position: Stand with feet shoulder-width apart, holding a barbell at shoulder height in a front rack position with hands slightly wider than shoulders. Execution: Perform a front squat by dropping into a deep squat, then explosively drive through your heels to stand while simultaneously pressing the barbell overhead in one fluid motion.',ARRAY['Set up with the barbell in a front rack position, resting on your front deltoids with elbows pointing forward','Keep your core tight and chest up as you initiate the movement by sitting back into a squat','Descend until your hip crease is below your knee caps while maintaining an upright torso','Drive explosively through your heels to stand up while beginning to press the barbell overhead','Complete the movement by fully extending your arms overhead with the barbell directly above your shoulders','Lower the barbell back to the front rack position with control to complete one repetition']::text[],ARRAY['Maintain a strong front rack position throughout the squat portion to prevent the bar from rolling forward','Keep your knees tracking over your toes during the squat to protect your knee joints','Use the momentum from your leg drive to assist with the overhead press portion of the movement','Ensure full hip and knee extension at the top before pressing the weight overhead for maximum power transfer','Start with lighter weight to master the coordination between the squat and press movements']::text[],'quads','{}'::text[],'barbell','legs','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ae8be22d-584f-4c34-add8-d25383ba90de','Barbell walking lunges','barbell-walking-lunges','Starting position: Stand upright with feet hip-width apart, holding a barbell across your upper back and shoulders in a high bar position. Execution: Step forward into a lunge position, lowering your back knee toward the ground, then bring the trailing leg forward to meet the leading leg and repeat with alternating legs.',ARRAY['Bar on upper back','Stand with feet together','Step forward into lunge','Lower until back knee near floor','Push back to starting position','Alternate legs or complete one side']::text[],ARRAY['Keep torso upright','Front knee tracks over toes','Don''t let front knee shoot past toes','Control the descent','Step back, not forward if balance is hard']::text[],'quads','{}'::text[],'barbell','legs',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','eb37d0a0-1a45-482c-9c6a-1aef9744661c','Barbell Wrist Curl','barbell-wrist-curl-caeaac','Starting position: Sit on a bench and rest your forearms on your thighs with your wrists just past your knees, holding a barbell with an underhand (supinated) grip, palms facing up. Let the barbell roll down toward your fingertips. Execution: Curl your wrists upward by flexing them, lifting the barbell as high as possible, then slowly lower back down under control.',ARRAY['Sit on a bench and place your forearms on your thighs with wrists extending just beyond your knees.','Hold the barbell with a supinated grip, palms facing upward, and let it lower toward your fingers.','Flex your wrists to curl the barbell upward as high as possible.','Pause briefly at the top and squeeze the forearm muscles.','Slowly lower the barbell back down under control to the starting position.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your forearms firmly pressed against your thighs throughout the movement.','Use a controlled tempo and avoid using momentum to lift the weight.','Allow the bar to roll to the fingertips at the bottom for full range of motion.','Move only at the wrists, keeping the rest of your arms stationary.']::text[],'forearm_flexors',ARRAY['wrist_flexors','forearm_extensors']::text[],'barbell','strength','beginner',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','47ab9d26-7959-46bb-9744-1e48695f5e70','Bear crawl into explosive jumps','bear-crawl-into-explosive-jumps','Starting position: Begin in a bear crawl position with hands and feet on the ground, knees hovering just above the floor, core engaged. Execution: Crawl forward 3-4 steps maintaining the bear crawl position, then explosively jump up with arms reaching overhead before returning to the starting position.',ARRAY['Start in bear crawl position with hands shoulder-width apart, knees bent and hovering 2-3 inches off the ground','Keep your core tight and back straight as you crawl forward 3-4 steps using opposite hand and foot coordination','After completing the crawl steps, place both feet firmly on the ground and prepare for the explosive movement','Drive through your heels and jump up explosively, extending your arms overhead','Land softly with bent knees and immediately return to the bear crawl starting position','Repeat the sequence for the desired number of repetitions']::text[],ARRAY['Maintain a neutral spine throughout the bear crawl portion to protect your lower back','Keep knees low during the crawl but avoid letting them touch the ground','Focus on a controlled landing after the explosive jump to prevent injury','Engage your core throughout the entire movement to maintain stability','Start with shorter crawl distances and lower jump intensity until you master the coordination']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c4d91f02-e796-4992-a08d-531b1d4bb16b','Bear crawl shoulder tap to pike push up','bear-crawl-shoulder-tap-to-pike-push-up','Starting position: Begin in a bear crawl position with hands planted shoulder-width apart, knees hovering just above the ground, and core engaged. Execution: Perform a shoulder tap by lifting one hand to touch the opposite shoulder, then transition into a pike position and perform a push-up before returning to the starting bear crawl position.',ARRAY['Start in bear crawl position with hands shoulder-width apart and knees hovering 2-3 inches off the ground','Lift your right hand and tap your left shoulder while maintaining balance on three points of contact','Return your right hand to the ground, then repeat the shoulder tap with your left hand to right shoulder','While keeping legs straight to transition into a downward dog or pike position','Perform one pike push-up by lowering your head toward the ground between your hands and pressing back up','Walk your feet back out to return to the starting bear crawl position and repeat the sequence']::text[],ARRAY['Keep your core tight throughout the entire movement to maintain stability and protect your lower back','Minimize hip rotation during shoulder taps by engaging your glutes and maintaining a strong plank position','Focus on controlled movements rather than speed to maximize muscle engagement and reduce injury risk','Ensure proper pike push-up form by keeping your legs straight and targeting the shoulders rather than letting your hips sag','Start with fewer repetitions and build up gradually as this exercise requires significant upper body and core strength']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','accf9858-fd32-4f43-aa4d-0bd0f53d7498','Bear crawl to pike push up','bear-crawl-to-pike-push-up','Starting position: Begin in a bear crawl position with hands and feet on the ground, knees hovering just above the floor, maintaining a straight back. Execution: Crawl forward 3-4 steps, then walk your feet toward your hands while keeping legs straight, transitioning into a downward dog position before performing a pike push-up by lowering your head toward the ground between your hands.',ARRAY['Start in bear crawl position with hands shoulder-width apart, core engaged, and knees hovering 2-3 inches off the ground','Take 3-4 controlled steps forward, moving opposite hand and foot together while maintaining neutral spine','Stop crawling and begin walking your feet toward your hands, keeping legs as straight as possible','Continue until you reach an inverted V position with weight distributed between hands and feet','Lower your head toward the ground between your hands by bending your elbows, keeping them close to your body','Push back up to the pike position and repeat the sequence']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your lower back and maintain proper form','Maintain steady breathing and avoid holding your breath during the transition from bear crawl to pike position','Focus on controlled movements rather than speed, especially when transitioning between positions','Ensure adequate shoulder mobility before attempting pike push-ups, as this exercise requires significant overhead shoulder flexibility','Start with fewer repetitions and gradually increase as your strength and coordination improve']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','214c3916-f02f-456f-9750-70fd0679295a','Bear crawls','bear-crawls','Starting position: Begin on hands and knees with wrists under shoulders, knees under hips, and lift knees 2-3 inches off the ground. Execution: Move forward by stepping the right hand and left foot simultaneously, then alternate with left hand and right foot while maintaining the low position.',ARRAY['Start on hands and knees with wrists directly under shoulders and knees under hips','Lift your knees 2-3 inches off the ground while keeping your back flat and core engaged','Move your right hand forward while simultaneously stepping your left foot forward','Follow with your left hand and right foot, maintaining the opposite arm-leg pattern','Keep your knees close to the ground throughout the entire movement','Move slowly and controlled, focusing on coordination rather than speed']::text[],ARRAY['Keep your core tight and back flat to avoid sagging hips or arching your spine','Maintain steady breathing throughout the movement and avoid holding your breath','Move in small steps to maintain better control and reduce strain on wrists and shoulders','Keep your head in a neutral position looking slightly ahead rather than up or down','Start with short distances and gradually increase as your strength and coordination improve']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5d6d9ca4-1ace-4dc9-b408-6ced49b753e7','Bear hold','bear-hold-1ffd16','Starting position: Begin on all fours with your hands stacked directly under your shoulders and knees under your hips, toes tucked. Execution: Lift your knees a couple of inches off the floor and hold, keeping your back flat and core braced while maintaining steady breathing.',ARRAY['Set up on hands and knees with wrists under shoulders and knees under hips.','Tuck your toes and brace your core to create tension throughout your torso.','Lift both knees one to two inches off the mat while keeping your back flat.','Hold the hover position without letting your hips rise or sag.','Keep your neck neutral and gaze slightly ahead of your hands.','Lower your knees under control to finish the hold.']::text[],ARRAY['Keep your back flat like a tabletop, avoiding any rounding or arching.','Press firmly through your palms to protect your shoulders and engage the serratus.','Keep knees hovering low and hips level, not piking upward.','Breathe steadily and brace your abs throughout the hold.']::text[],'core',ARRAY['front_deltoids','triceps','glutes','erector_spinae']::text[],'bodyweight','core','intermediate',ARRAY['core','isometric','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b21be739-d8af-416f-83e4-fc65509a9a28','Bear plank ankle taps into jumps','bear-plank-ankle-taps-into-jumps','Starting position: Begin in a bear plank position with hands directly under shoulders, knees hovering 1-2 inches off the ground, and core engaged. Execution: Tap one ankle with the opposite hand while maintaining the plank position, then explosively jump both feet toward your hands before returning to the starting bear plank position.',ARRAY['Start in bear plank with hands under shoulders, knees bent and hovering just off the ground','Keep your core tight and back flat throughout the entire movement','Tap your right ankle with your left hand, then return to center and tap left ankle with right hand','After completing ankle taps, explosively jump both feet forward toward your hands while keeping hands planted','Immediately jump your feet back to the starting bear plank position','Maintain control and proper form throughout all transitions']::text[],ARRAY['Keep knees consistently hovering 2-3 inches off the ground during the bear plank portions','Engage your core throughout to prevent your hips from sagging or pike up too high','Land softly on the balls of your feet during the jump phases to protect your joints','Move with control during ankle taps to avoid compromising your plank position','Start slowly to master the coordination before increasing speed or intensity']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','plyometric','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c2a135e7-1383-47c1-9757-4868ae9a8c55','Bear plank Shoulder taps','bear-plank-shoulder-taps','Starting position: Begin in a bear plank position with hands directly under shoulders, knees bent at 90 degrees and hovering 1-2 inches off the ground, maintaining a straight line from head to hips. Execution: Alternate lifting one hand to tap the opposite shoulder while maintaining the bear plank position and minimizing hip movement.',ARRAY['Set up in a tabletop position with hands directly under shoulders and knees under hips','Lift your knees 1-2 inches off the ground while keeping them bent at 90 degrees','Engage your core and maintain a straight line from head to tailbone','Slowly lift your right hand and tap your left shoulder, keeping hips level','Return your right hand to the ground and repeat the movement with your left hand tapping your right shoulder','Continue alternating sides while maintaining proper form and breathing steadily']::text[],ARRAY['Keep your hips as still as possible to maximize core engagement and avoid rotating','Maintain equal weight distribution on your feet and supporting hand during each tap','Focus on slow, controlled movements rather than speed to ensure proper muscle activation','Keep your shoulders directly over your wrists throughout the entire movement','If the exercise is too challenging, start by holding the bear plank position before adding shoulder taps']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f2fef2bc-353c-4f3b-b7c3-ee5d63e2a87b','Bear plank shoulder taps - 30','bear-plank-shoulder-taps-30','Starting position: Begin in a plank position with hands directly under shoulders and feet hip-width apart, maintaining a straight line from head to heels. Execution: Lift one hand off the ground and tap the opposite shoulder, then return to plank and repeat with the other hand, alternating for the specified repetitions.',ARRAY['Start in a tabletop position with hands under shoulders and knees under hips','Lift knees 1-2 inches off the ground while keeping knees bent at 90 degrees','Engage your core and maintain a neutral spine position','Slowly lift your right hand and tap your left shoulder while keeping hips square','Return right hand to the ground and repeat with left hand tapping right shoulder','Continue alternating sides while maintaining the bear plank position throughout']::text[],ARRAY['Keep hips level and avoid rotating or swaying from side to side during the shoulder taps','Maintain steady breathing and avoid holding your breath during the movement','Keep knees hovering consistently off the ground throughout the entire exercise','Focus on slow, controlled movements rather than rushing through the repetitions','Distribute weight evenly between your hands and balls of your feet for better stability']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','63603235-6df6-4c55-b0fe-c417fee626b8','Bear plank side tap sidewalks','bear-plank-side-tap-sidewalks','Starting position: Begin in a bear plank position with hands directly under shoulders, knees hovering 2-3 inches off the ground, and core engaged. Execution: Step laterally to one side by moving the opposite hand and foot simultaneously, then return to center and repeat on the other side in a controlled walking motion.',ARRAY['Start in bear plank with hands directly under shoulders and knees hovering just off the ground','Engage your core and maintain a neutral spine throughout the movement','Step your right hand and right foot simultaneously to the right about 12 inches','Follow with your left hand and left foot to return to starting width','Reverse the pattern by stepping left hand and left foot to the left, followed by right hand and foot','Continue alternating directions for the prescribed number of repetitions or time']::text[],ARRAY['Keep your knees consistently hovering 2-3 inches off the ground throughout the entire movement','Maintain a strong plank position without letting your hips sag or pike upward','Move slowly and controlled to maximize core engagement and maintain proper form','Keep your head in neutral position looking down at the ground to protect your neck','Ensure hands stay directly under shoulders as you move laterally']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','638616d3-100b-4b14-8516-ff9e4b3e80f2','Bear plank steps and hops','bear-plank-steps-and-hops','Starting position: Begin in a bear plank position with hands under shoulders, knees hovering 1-2 inches off the ground, and core engaged. Execution: Alternate between stepping feet laterally and performing small explosive hops while maintaining the bear plank position throughout the movement.',ARRAY['Start in bear plank with wrists aligned under shoulders and knees hovering just above the ground','Engage your core and maintain a neutral spine throughout the entire movement','Step or hop your right foot out to the side while keeping your left foot planted','Return your right foot to starting position, then repeat with your left foot','Keep your hips level and avoid rotating your torso during the lateral movements','Breathe steadily and maintain control rather than rushing through the repetitions']::text[],ARRAY['Keep your knees close to the ground throughout the movement to maintain proper bear plank form','Focus on keeping your hips square and avoiding any twisting or tilting','Start with stepping motions before progressing to hopping to build strength and stability','Maintain even weight distribution between your hands to prevent wrist strain','Stop immediately if you cannot maintain proper form or if your knees touch the ground']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','plyometric','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c794e5f9-f603-4f1a-a108-1989ff2b8215','Bear plank toe taps','bear-plank-toe-taps','Starting position: Begin in a bear plank position with hands planted under shoulders, knees bent at 90 degrees and hovering 1-2 inches off the ground, maintaining a neutral spine. Execution: Alternate lifting one foot off the ground and tapping the toe forward while keeping the opposite knee hovering, then return to starting position and repeat on the other side.',ARRAY['Start in a tabletop position with hands under shoulders and knees under hips','Lift knees 2-3 inches off the ground while keeping core engaged and back straight','Engage your core and maintain neutral spine alignment throughout the movement','Lift your right foot and tap it out to the right side, keeping the knee low','Return right foot to starting position and immediately repeat with left foot to the left side','Continue alternating toe taps while maintaining the bear plank position']::text[],ARRAY['Keep knees hovering consistently at the same height throughout the entire movement','Maintain a strong core contraction to prevent lower back sagging or hip hiking','Move with control rather than speed to maximize core engagement and stability','Keep your head in neutral position looking down at the floor to maintain proper spine alignment','Breathe steadily throughout the movement and avoid holding your breath']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','59887212-af71-41e1-9b3f-afe352ba1979','Bear toe taps','bear-toe-taps','Starting position: Begin in a bear crawl position with hands under shoulders, knees under hips hovering 2-3 inches off the ground, and core engaged. Execution: Alternate lifting one hand to tap the opposite foot while maintaining the stable bear position.',ARRAY['Start in bear crawl position with hands planted firmly under shoulders and knees hovering just off the ground','Engage your core and maintain a neutral spine throughout the movement','Lift your right hand and reach across to tap your left foot while keeping hips level','Return right hand to starting position and immediately switch to tap left hand to right foot','Keep knees hovering throughout the entire exercise without letting them touch the ground','Perform taps in a controlled manner focusing on stability rather than speed']::text[],ARRAY['Keep hips square and avoid rotating or tilting to one side during the toe taps','Maintain steady breathing and avoid holding your breath during the movement','Start with shorter sets and build endurance gradually as this exercise is very demanding on the core','Focus on quality over quantity - proper form is more important than speed or number of repetitions','Keep shoulders stable and avoid shifting weight dramatically from side to side']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['core','calisthenics','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fc721ada-0004-40d7-9e1e-634dc9b34877','Behind the Head Curl with Cable','behind-the-head-curl','Starting position: Stand with your back to a cable machine, grasping the low pulley cable attachment with an underhand grip, arms extended behind your head. Execution: Curl the cable forward and up by flexing your biceps while keeping your upper arms stationary behind your head.',ARRAY['Set the cable pulley to the lowest position and attach a straight bar or EZ-curl bar attachment','Stand with your back to the cable machine, feet shoulder-width apart for stability','Reach behind your head and grasp the attachment with an underhand grip, arms extended','Keep your upper arms stationary and parallel to the floor throughout the movement','Curl the weight forward and up by contracting your biceps until your forearms are vertical','Slowly lower the weight back to the starting position with control']::text[],ARRAY['This exercise places significant stress on the shoulder joint, so use lighter weight than standard bicep curls','Maintain strict control throughout the movement to avoid shoulder impingement','Keep your core engaged and avoid arching your back excessively','Stop immediately if you feel any shoulder discomfort or pain','Consider shoulder mobility limitations before attempting this exercise']::text[],'biceps','{}'::text[],'cable','arms','advanced',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ab1681a6-93a1-4e51-ac8c-c76f02ef3737','Behind the Neck Rope Pulldown','behind-the-neck-rope-pulldown','Starting position: Sit at a pulldown machine with a rope attached to the pulley. Execution: Pull the rope toward the back of the neck, separating the rope ends at the end of the movement, then slowly return to starting position.',ARRAY['Adjust the cable machine to the highest position and attach a rope handle','Sit on the bench facing away from the machine and grasp both ends of the rope with an overhand grip','Position the rope at the base of your neck, ensuring your head is in a neutral position and shoulders are mobile','Pull the rope down and apart by driving your elbows down toward your sides while squeezing your shoulder blades together','Hold the contracted position briefly, feeling the tension in your upper back muscles','Slowly return to the starting position with control, maintaining tension throughout the entire range of motion']::text[],ARRAY['Only perform this exercise if you have adequate shoulder mobility and no neck or shoulder injuries','Keep your core engaged and maintain an upright torso throughout the movement to protect your lower back','Focus on the mind-muscle connection with your rhomboids and middle trapezius rather than using excessive weight','Stop immediately if you feel any discomfort in your neck or shoulders during the movement']::text[],'back','{}'::text[],'cable','back','advanced',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','051a5802-da89-415d-a912-93162c89a4bf','Behind the Neck Shoulder Press Machine','behind-the-neck-press','Starting position: Sit upright on the machine with your back against the pad, grasping the handles behind your neck with arms bent at 90 degrees. Execution: Press the handles straight up overhead until your arms are fully extended, then slowly lower back to the starting position behind your neck.',ARRAY['Adjust the seat height so the handles align properly with your shoulder level','Sit with your back firmly against the pad and engage your core for stability','Grasp the handles with an overhand grip, positioning your hands slightly wider than shoulder-width','Press the weight straight up in a controlled motion until your arms are fully extended overhead','Lower the weight slowly back to the starting position, stopping when your upper arms are parallel to the floor','Maintain proper posture throughout the entire movement without arching your back excessively']::text[],ARRAY['Keep your core engaged and maintain a neutral spine throughout the exercise','Avoid lowering the bar too far behind your neck as this can stress the shoulder joints','Use a controlled tempo on both the lifting and lowering phases','Ensure adequate shoulder mobility and warm-up before performing this exercise','Stop the movement if you feel any shoulder discomfort or impingement']::text[],'shoulders','{}'::text[],'machine','shoulders','advanced',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','79084f10-c317-4c40-ae0c-45d0b760298d','Bench Dips','bench-dips-197282','Starting position: Sit on edge of bench with hands gripping beside hips, legs extended forward. Execution: Lower body by bending elbows, then press back up to starting position.',ARRAY['Sit on bench edge with hands gripping beside hips','Extend legs forward with heels on ground','Lower body by bending elbows to ninety degrees','Keep back close to the bench throughout movement','Press through palms to return to starting position']::text[],ARRAY['Keep shoulders down and back to avoid impingement','Stop lowering when elbows reach 90 degrees to protect shoulders','Maintain straight torso alignment throughout the movement','Bend knees to make the exercise easier for beginners']::text[],'bodyweight','{}'::text[],'bodyweight',null,null,ARRAY['calisthenics','strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','48b2c98e-b82f-49aa-b847-b871a69e1b95','Bench Dips','bench-dips-784d8d','Starting position: Sit on the edge of a bench with hands gripping the edge beside your hips, fingers pointing forward, and slide your hips off the bench with legs extended forward and heels on the floor. Execution: Bend your elbows to lower your body until your upper arms are roughly parallel to the floor, then press through your palms to extend your arms and return to the starting position.',ARRAY['Grip the edge of the bench with hands shoulder-width apart and slide your hips off the front of the bench.','Extend your legs out in front with heels on the floor and torso upright.','Bend your elbows to lower your body until your upper arms are parallel to the floor.','Keep your elbows pointing straight back and close to your body.','Press through your palms to straighten your arms and lift your body back up.','Repeat for the desired number of repetitions without locking out harshly.']::text[],ARRAY['Keep your back close to the bench to reduce shoulder strain.','Lower only until upper arms are parallel to avoid overstressing the shoulder joint.','Keep elbows tracking backward, not flaring out to the sides.','Maintain a controlled tempo and avoid using momentum.']::text[],'triceps',ARRAY['front_deltoids','pectoralis_major','core']::text[],'bodyweight','strength','beginner',ARRAY['strength','calisthenics']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4402c7a1-0845-4da2-882d-4e06fc275b8b','Bench Jump','bench-jump','Starting position: Stand facing a sturdy bench or platform that is approximately knee height, with feet hip-width apart and arms at your sides. Execution: Explosively jump up onto the bench landing softly with both feet, then step or jump back down to return to the starting position.',ARRAY['Ensure the bench or platform is stable and can support your body weight before beginning','Bend your knees and swing your arms back to generate momentum before jumping','Land softly on the balls of your feet with knees bent to absorb impact','Step down backwards one foot at a time rather than jumping down to reduce joint stress','Maintain control throughout the entire movement and pause briefly on top of the bench']::text[],ARRAY['Focus on landing softly with bent knees to protect your joints from impact','Keep your core engaged throughout the movement to maintain balance and stability','Choose an appropriate bench height that challenges you without compromising form or safety','Always step down rather than jump down to minimize risk of injury','Ensure adequate space around the bench for safe movement in all directions']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','58d0fe05-1a66-4b80-a6d8-2dc2f0d73169','Bench Press','bench-press','Starting position: Lie on a flat bench with a barbell in your hands, arms extended upward with an overhand grip. Execution: Lower the bar to your chest, then press upward to return to the starting position.',ARRAY['Position bench under bar','Align bar over mid-chest','Unrack, lower bar to chest','Press up to full extension (don''t lock)','Repeat for reps, rack safely']::text[],ARRAY['Bar path is fixed - position bench properly','Keep feet flat on floor','Shoulder blades squeezed','Control the descent','Good for training to failure (can rack anytime)']::text[],'chest','{}'::text[],'barbell','chest',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','53f37f4b-c486-4ebb-846b-953078455bfe','Bent leg v-sit into punches','bent-leg-v-sit-into-punches','Starting position: Sit on the floor with knees bent at 90 degrees, feet lifted off the ground, and lean back slightly while balancing on your glutes with arms at your sides. Execution: Maintain the V-sit position while alternating rapid punches forward, keeping your core engaged and legs stable throughout the movement.',ARRAY['Sit on the floor and lift your feet off the ground with knees bent at 90 degrees','Lean back slightly until you feel your core muscles engage and find your balance point','Keep your chest up and shoulders back while maintaining the V-sit position','Begin alternating punches forward with controlled speed, extending one arm fully while the other returns','Maintain steady breathing and keep your legs stable throughout the punching motion','Continue for the prescribed time or repetitions while focusing on form over speed']::text[],ARRAY['Keep your core constantly engaged to maintain balance and protect your lower back','Focus on controlled punching movements rather than speed to maintain proper V-sit form','If you cannot maintain the leg position, place your feet lightly on the ground for support','Keep your shoulders relaxed and avoid hunching forward during the punching motion','Stop immediately if you feel strain in your lower back and reassess your form']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['core','cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','059690e8-f60d-4099-b3ae-93d18358a59a','Bent Over Barbell Row','bent-over-barbell-row','Starting position: Stand with your torso bent forward and grip a barbell with a pronated grip (palms down). Execution: Pull the bar toward your chest while keeping your back straight, then slowly lower to the starting position.',ARRAY['Stand with feet hip-width apart, holding a barbell with an overhand grip slightly wider than shoulder-width','Hinge at the hips and bend forward until your torso is at about a 45-degree angle, keeping knees slightly bent','Let the barbell hang with arms fully extended, maintaining a neutral spine and engaged core','Pull the barbell up to your lower chest/upper abdomen by driving your elbows back and squeezing your shoulder blades together','Pause briefly at the top, then slowly lower the barbell back to the starting position with control','Complete the desired number of repetitions while maintaining proper form throughout']::text[],ARRAY['Keep your core engaged and maintain a neutral spine throughout the entire movement to protect your lower back','Focus on pulling with your back muscles rather than your arms - initiate the movement by retracting your shoulder blades','Avoid using momentum or allowing your torso to rise up during the pulling motion','Control the negative (lowering) portion of the movement - don''t let the weight drop','Start with lighter weight to master the form before progressing to heavier loads']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6e4be416-7097-4301-bfb9-f62bc69f1fa7','Bent Over Barbell Row Overhand Grip','bent-over-barbell-row-overhand-grip','Starting position: Stand with a barbell in hands using an overhand grip (palms facing down) with hands shoulder-width apart. Execution: Pull the bar toward your lower chest, keeping elbows close to your body, then slowly lower to the starting position.',ARRAY['Set up with feet hip-width apart and grip the barbell with hands slightly wider than shoulders using an overhand grip','Hinge at the hips and bend forward while keeping your back straight and core engaged, allowing the bar to hang at arm''s length','Initiate the pull by squeezing your shoulder blades together and driving your elbows back toward your ribs','Pull the barbell up toward your lower chest or upper abdomen while maintaining your bent-over position','Pause briefly at the top of the movement, then slowly lower the bar back to the starting position with control','Maintain tension in your back muscles throughout the entire range of motion']::text[],ARRAY['Keep your back straight and core engaged throughout the movement to protect your spine','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Maintain a consistent hip-hinge position without standing up or dropping your chest during the exercise','Control the weight on both the lifting and lowering phases to maximize muscle engagement and prevent injury','Keep your head in a neutral position aligned with your spine rather than looking up or down']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','716ba91e-0ab4-4f1f-bbd9-dd06e25e0da6','Bent Over Barbell Row Underhand Grip','bent-over-barbell-row-underhand-grip','Starting position: Stand with a barbell in your hands using an underhand grip (palms facing up), hands at shoulder width. Execution: Pull the bar toward your lower chest, keeping elbows close to your body, then slowly lower to the starting position.',ARRAY['Set up with feet hip-width apart and grip the barbell with palms facing up, hands slightly wider than shoulders','Hinge at the hips and lean forward maintaining a neutral spine with knees slightly bent','Keep your core engaged and chest up as you initiate the pull by driving your elbows back','Pull the barbell toward your lower chest while squeezing your shoulder blades together','Pause briefly at the top of the movement feeling the contraction in your back muscles','Lower the barbell slowly and under control back to the starting position']::text[],ARRAY['Keep your back straight throughout the entire movement to prevent injury and maximize muscle activation','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Maintain a slight bend in your knees and avoid standing completely upright during the exercise','Control the negative portion of the lift to increase time under tension and improve muscle development','Keep the barbell close to your body throughout the movement path for optimal biomechanics']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','de70b78c-7dec-4a91-acc7-d75ae27eb765','Bent Over Dumbbell Rear Delt Raise','bent-over-dumbbell-rear-delt-raise','Starting position: Stand with torso bent forward, holding a dumbbell in each hand with palms facing inward. Execution: Raise the dumbbells out to the sides until they reach shoulder height, then slowly lower.',ARRAY['Hold light dumbbells with a neutral grip and stand with feet hip-width apart','Hinge at the hips and bend forward 45-60 degrees while keeping your back straight and core engaged','Let the dumbbells hang straight down with arms slightly bent and palms facing each other','Raise the weights out to the sides in a controlled arc until your arms are parallel to the floor','Squeeze your shoulder blades together at the top of the movement','Slowly lower the dumbbells back to the starting position with control']::text[],ARRAY['Use lighter weights than other shoulder exercises as the rear delts are smaller muscles','Keep a slight bend in your elbows throughout the entire movement to protect your joints','Focus on squeezing your shoulder blades together rather than just lifting your arms','Maintain the hip-hinged position throughout the set without standing up between reps','Control the lowering phase as much as the lifting phase to maximize muscle engagement']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7ab0bece-90eb-45f1-9b22-3fd86c376aa1','Bent Over Dumbbell Reverse Fly','bent-over-dumbbell-reverse-fly','Starting position: Stand, lean your torso forward and hold a dumbbell in each hand with palms facing inward. Execution: Raise the dumbbells to the sides until they reach shoulder height, then slowly lower.',ARRAY['Stand with feet hip-width apart holding a dumbbell in each hand with palms facing each other','Hinge forward at the hips about 45 degrees while maintaining a neutral spine and slight bend in the knees','Allow the dumbbells to hang naturally below your chest with arms slightly bent','Raise the dumbbells out to the sides in a wide arc until your arms are parallel to the floor','Squeeze your shoulder blades together at the top of the movement','Slowly lower the weights back to the starting position with control']::text[],ARRAY['Keep your core engaged throughout the movement to protect your lower back','Focus on squeezing your shoulder blades together rather than just lifting the weights','Use a controlled tempo with a 2-second lift and 3-second lowering phase','Avoid using momentum or swinging the weights up','Start with lighter weights to master the form before progressing to heavier loads']::text[],'shoulders',ARRAY['rhomboids','middle_traps','erector_spinae']::text[],'dumbbell','shoulders','beginner',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c7c76fa8-908a-4ee0-977c-35f12057676d','Bent over Dumbbell Tricep Extension','bent-over-db-tricep-extension','Starting position: Stand with feet hip-width apart, holding a dumbbell with both hands, hinge at the hips to lean forward at about 45 degrees with arms extended overhead behind you. Execution: Keep your upper arms stationary while bending at the elbows to lower the dumbbell behind your head, then extend back to the starting position.',ARRAY['Hold a dumbbell with both hands using a neutral grip and stand with feet hip-width apart','Hinge at the hips and lean your torso forward at approximately 45 degrees while keeping your back straight','Extend your arms overhead and back behind your body, keeping upper arms parallel to the floor','Lower the dumbbell by bending only at the elbows until you feel a stretch in your triceps','Press the weight back up by extending your elbows to return to the starting position','Maintain the bent-over position throughout the entire movement']::text[],ARRAY['Keep your upper arms completely stationary throughout the movement to isolate the triceps effectively','Maintain a neutral spine and avoid rounding your back while in the bent-over position','Control the weight on both the lowering and lifting phases to maximize muscle engagement','Use a weight that allows you to maintain proper form rather than going too heavy too quickly','Keep your core engaged throughout the exercise to support your spine in the bent-over position']::text[],'triceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','43c81170-5fc1-46dd-92b0-6a308c22cec1','Bent Over One-Arm Long Bar Row','bent-over-one-arm-long-bar-row','Starting position: Stand with feet hip-width apart, holding one end of a barbell with one hand while the other end is secured or braced against a wall or rack, hinge at hips with slight knee bend and maintain neutral spine. Execution: Pull the barbell end toward your ribcage by driving your elbow back and squeezing your shoulder blade, then slowly lower back to starting position.',ARRAY['Secure one end of the barbell against a wall corner or in a landmine attachment to prevent movement','Grip the free end with one hand using an overhand grip, step back to create tension','Hinge at the hips while keeping your back straight and core engaged, allowing a slight bend in your knees','Pull the barbell toward your lower ribcage by driving your elbow back along your side','Squeeze your shoulder blade at the top of the movement and hold briefly','Lower the weight slowly and under control back to the starting position']::text[],ARRAY['Keep your core tight throughout the movement to protect your lower back and maintain stability','Focus on pulling with your back muscles rather than just your arm by initiating the movement with your shoulder blade','Maintain a neutral spine position and avoid rounding your back during the rowing motion','Control the eccentric portion of the lift to maximize muscle engagement and prevent injury','Keep your elbow close to your body rather than flaring it out to properly target the latissimus dorsi and rhomboids']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ad8e32a3-091a-4b10-a316-8984807ce817','Bent Over Two-Arm Long Bar Row - 105','bent-over-two-arm-long-bar-row-105','Starting position: Stand with feet hip-width apart, holding a barbell with an overhand grip slightly wider than shoulder-width, hinge at the hips to lean forward with a straight back and knees slightly bent. Execution: Pull the barbell up toward your lower chest by squeezing your shoulder blades together and driving your elbows back, then slowly lower the weight back to the starting position with control.',ARRAY['Set up with feet hip-width apart and grip the barbell with hands slightly wider than shoulder-width using an overhand grip','Hinge at the hips to lean forward approximately 45 degrees while maintaining a neutral spine and slight bend in the knees','Engage your core and let the barbell hang at arm''s length with shoulders pulled back and down','Pull the barbell toward your lower chest by driving your elbows back and squeezing your shoulder blades together','Pause briefly at the top of the movement, then slowly lower the barbell back to the starting position','Maintain proper posture throughout the entire range of motion and avoid using momentum']::text[],ARRAY['Keep your back straight and core engaged throughout the movement to protect your lower back','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Avoid rounding your shoulders forward or allowing your back to arch excessively','Control the weight on both the lifting and lowering phases to maximize muscle engagement','Keep your head in a neutral position aligned with your spine rather than looking up or down']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7aaad2c1-c499-40dd-84e5-a66b910e6f8b','Bent Over Two-Dumbbell Row With Palms In','bent-over-two-dumbbell-row-with-palms-in','Starting position: Stand with feet hip-width apart, holding a dumbbell in each hand with palms facing your body, hinge at the hips to lean forward with a straight back and slight knee bend. Execution: Pull both dumbbells up toward your lower ribs by driving your elbows back, squeeze your shoulder blades together, then slowly lower the weights back to the starting position.',ARRAY['Hinge at the hips and lean forward until your torso is at approximately 45 degrees, keeping your back straight and core engaged','Hold dumbbells with a neutral grip, palms facing inward toward your body, arms hanging straight down','Initiate the pull by driving your elbows back and up toward the ceiling, keeping them close to your sides','Squeeze your shoulder blades together as you pull the dumbbells toward your lower rib cage','Hold the contraction briefly at the top, then slowly lower the weights back to the starting position with control','Maintain the hip-hinged position throughout the entire set']::text[],ARRAY['Keep your core tight and maintain a neutral spine throughout the movement to protect your lower back','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Avoid using momentum or swinging the weights - control the movement in both directions','Keep your head in a neutral position aligned with your spine, avoiding looking up or down excessively','Start with lighter weights to master the form before progressing to heavier loads']::text[],'back','{}'::text[],'dumbbell','back','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','87a9f879-77ef-4dbe-8e8e-b15fea5052a7','Bicycle punches','bicycle-punches','Starting position: Lie on your back with hands behind your head, elbows wide, and legs lifted with knees bent at 90 degrees. Execution: Alternate bringing opposite elbow to knee while extending the other leg, adding punching motions with your arms as you rotate your torso.',ARRAY['Lie flat on your back with hands lightly placed behind your head, avoiding interlacing fingers','Lift your shoulders off the ground and raise both legs with knees bent at 90-degree angles','Bring your right elbow toward your left knee while extending your right leg straight out','As you rotate, punch across your body with the working arm while bring your other arm back','Continue alternating sides in a controlled, rhythmic motion while maintaining core engagement']::text[],ARRAY['Keep your lower back pressed against the floor throughout the movement to protect your spine','Focus on rotating from your core rather than pulling on your neck with your hands','Maintain controlled movements rather than rushing through the exercise for better muscle activation','Keep your extended leg hovering just above the ground without touching down','Breathe steadily, exhaling as you crunch and punch across your body']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['core','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b771f714-b1dc-49f8-8df5-9f8ae35bbbae','Bird Dog','bird-dog-d1070c','Starting position: Begin on hands and knees in tabletop position with neutral spine. Execution: Simultaneously extend opposite arm and leg while maintaining core stability.',ARRAY['Start in tabletop position with hands under shoulders','Keep knees directly under hips and spine neutral','Slowly extend right arm forward and left leg back','Hold the position while engaging your core muscles','Return to starting position with control','Repeat with opposite arm and leg']::text[],ARRAY['Keep hips level and avoid rotating during the movement','Maintain a straight line from extended hand to extended foot','Engage core muscles throughout to protect lower back','Move slowly and focus on balance rather than speed','Stop if you feel pain in your lower back']::text[],'bodyweight',ARRAY['obliques','glute_max','rotator_cuff','transverse_abdominis']::text[],'bodyweight','core','beginner','{}'::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a36c63b9-c3d4-432d-a135-1ca81a162d35','Boat hold','boat-hold','Starting position: Sit on the floor with knees bent, feet flat on the ground, and hands placed lightly behind your thighs for support. Execution: Lean back slightly, lift your feet off the ground, and balance on your sit bones while maintaining a straight spine and holding this V-shaped position.',ARRAY['Sit on the floor with knees bent and feet flat on the ground','Place hands lightly behind your thighs for initial support','Engage your core and lean back slightly while keeping your chest lifted','Slowly lift your feet off the ground, bringing your shins parallel to the floor','Balance on your sit bones and hold the position while breathing steadily','For added challenge, extend your arms forward parallel to the ground or straighten your legs']::text[],ARRAY['Keep your spine straight and avoid rounding your back throughout the hold','Focus on balancing on your sit bones rather than your tailbone to protect your lower back','Start with shorter holds and gradually increase duration as your core strength improves','Breathe steadily throughout the exercise rather than holding your breath','If you experience lower back pain, keep your hands behind your thighs for support or lower your feet closer to the ground']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e396f5be-9c22-44ff-b825-d754d807f5fd','Boat pose','boat-pose','Starting position: Sit on the floor with knees bent, feet flat, and hands resting beside your hips. Execution: Lift your feet off the ground while balancing on your sit bones, extending your legs and arms to form a V-shape with your body.',ARRAY['Sit on the floor with knees bent and feet flat.','Lean back slightly and lift your feet off the floor.','Extend your arms forward, parallel to the floor.','Straighten your legs to form a V-shape with your body.']::text[],ARRAY['Keep your spine straight, avoid rounding the back.','Engage your core to maintain balance.','Breathe steadily and hold for 5-10 breaths.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','core','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','42ee935a-8052-4d1b-bde6-d64bb2389e57','Bodyweight Squat','bodyweight-squat-6bf863','Starting position: Stand with feet shoulder-width apart, toes slightly turned out, chest up and core braced. Execution: Bend at the hips and knees to lower your body until your thighs are at least parallel to the floor, extending your arms forward for balance, then drive through your heels to return to standing.',ARRAY['Stand tall with feet shoulder-width apart and toes slightly pointed out.','Extend your arms forward and brace your core as you begin the descent.','Push your hips back and bend your knees to lower until thighs reach parallel.','Keep your chest up and knees tracking over your toes at the bottom.','Drive through your heels to extend the hips and knees back to standing.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your heels flat on the floor throughout the movement.','Maintain a neutral spine and avoid rounding your lower back.','Ensure knees track in line with your toes, not caving inward.','Descend to at least parallel depth for full range of motion.']::text[],'quads',ARRAY['hamstrings','adductors','erector_spinae','calves']::text[],'bodyweight','strength','beginner',ARRAY['strength','functional','calisthenics']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f28e1faf-4677-453e-9007-8329d7a67e2d','Bodyweight Squat (air squat)','bodyweight-squat-air-squat','Starting position: Stand with feet shoulder-width apart, toes slightly turned out, arms at your sides or extended forward for balance. Execution: Lower your body by pushing your hips back and bending your knees until your thighs are parallel to the floor, then drive through your heels to return to the starting position.',ARRAY['Feet shoulder-width, toes slightly out','Arms forward for balance','Squat down until thighs parallel or below','Drive up through heels']::text[],ARRAY['Keep chest up, back flat','Knees track over toes','Full depth if mobility allows','Don''t let knees cave','Foundation for all squats']::text[],'quads','{}'::text[],'bodyweight','legs',null,ARRAY['strength','functional','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','33869887-32ab-4c66-b033-3bef9e5de372','Bodyweight Triceps Extension (with bar)','barbell-triceps-extension','Starting position: Stand arm''s length away from a barbell rack, place hands on the barbell with arms extended, and lean your body forward at an angle with feet planted firmly behind you. Execution: Lower your body by bending only at the elbows while keeping your body straight, then push back up to the starting position by extending your arms.',ARRAY['Position yourself arm''s length from a bar or secured barbell at about chest height with hands shoulder-width apart','Lean forward keeping your body in a straight line from head to heels with arms fully extended','Lower your body slowly by bending only at the elbows until your forehead nearly touches the bar','Keep your core engaged and body rigid throughout the entire movement','Push yourself back up to the starting position by straightening your arms','Maintain control on both the lowering and lifting phases of the exercise']::text[],ARRAY['Keep your body in a straight plank position throughout the movement to protect your lower back','Focus on bending only at the elbows while keeping your shoulders stationary to properly target the triceps','Adjust the difficulty by changing your foot position - closer feet make it easier, further feet increase difficulty','Ensure the barbell is securely positioned and cannot roll or move during the exercise','Stop immediately if you feel any shoulder pain and reassess your form and positioning']::text[],'triceps','{}'::text[],'bodyweight','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4c799907-a832-42b2-b9b3-bfb75a68c840','Bow pose','bow-pose','Starting position: Lie face down on the floor with arms at your sides and legs extended straight back. Execution: Simultaneously lift your chest and legs off the ground while reaching back to grasp your ankles, creating a bow-like arch in your spine.',ARRAY['Lie face down on your mat with arms alongside your body.','Bend your knees and reach back to grab your ankles.','Inhale and lift your chest and thighs off the floor simultaneously.','Hold the pose, breathing steadily, then release on an exhale.']::text[],ARRAY['Keep knees hip-width apart throughout.','Press your ankles into your hands to lift higher.','Avoid compressing the lower back by engaging your core.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ffded4df-0bf5-4522-8c94-cf15492a8271','Box Jump','box-jump-b15eac','Starting position: Stand facing a sturdy plyo box with feet hip-width apart, knees slightly bent and arms ready to swing. Execution: Hinge at the hips, swing the arms back, then explosively jump onto the box, landing softly in a partial squat before standing tall and stepping or jumping back down.',ARRAY['Stand a short distance in front of the box with feet hip-width apart.','Lower into a quarter squat while swinging your arms back to load.','Explode upward, driving through the legs and swinging your arms forward.','Land softly on top of the box with knees bent and hips back to absorb impact.','Stand fully upright to complete the rep, then step down and reset.','Repeat for the desired number of repetitions.']::text[],ARRAY['Land quietly with soft knees to reduce impact on joints.','Fully extend your hips at the top before stepping down.','Step down rather than jump down to protect your knees and Achilles.','Keep your chest up and core braced throughout the movement.']::text[],'quads',ARRAY['calves','core','erector_spinae']::text[],'box','plyometric','intermediate',ARRAY['plyometric','functional','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','768c2a0e-5824-42f9-8175-b296f0433c02','Box jumps','box-jumps-0edbf7','Starting position: Stand facing a sturdy box with feet shoulder-width apart, knees slightly bent, and arms ready to swing. Execution: Hinge at the hips into a quarter squat, swing the arms back, then explosively drive up and forward to jump onto the box, landing softly with both feet and knees bent before standing tall and stepping back down.',ARRAY['Stand facing the box a short distance away with feet hip- to shoulder-width apart.','Bend your knees and hips into a partial squat while swinging your arms behind you.','Explosively extend the hips and knees, swinging your arms forward to jump onto the box.','Land softly in the center of the box with both feet flat and knees bent to absorb impact.','Stand fully upright on the box, then step down one foot at a time and reset.','Repeat for the desired number of repetitions.']::text[],ARRAY['Land softly with bent knees to reduce impact on joints.','Keep your chest up and core braced throughout the movement.','Use a box height you can clear safely and step down rather than jumping down.','Drive through the balls of your feet and use your arms for momentum.']::text[],'quads',ARRAY['calves','hamstrings','erector_spinae']::text[],'box','plyometric','intermediate',ARRAY['plyometric','cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0e19fa47-7a77-4fdf-86a0-66258725fa3d','Box Toe Tap','box-toe-tap-2f0e73','Starting position: Stand upright facing a low plyo box with feet hip-width apart, weight on the balls of your feet and elbows bent with hands in front for balance. Execution: Quickly tap the top of the box with the toes of one foot, then switch and tap with the other foot, alternating rapidly in a light bouncing rhythm while keeping your core braced and torso upright.',ARRAY['Stand facing a low box with feet hip-width apart and knees slightly bent.','Lightly tap the top of the box with the toes of one foot.','Quickly switch feet, bringing the other foot up to tap while lowering the first.','Continue alternating in a fast, bouncing rhythm.','Keep your arms bent and moving to help maintain rhythm and balance.','Land softly on the balls of your feet throughout the set.']::text[],ARRAY['Stay light on your feet and land softly to reduce joint impact.','Keep your chest up and core engaged to avoid leaning too far forward.','Maintain a quick, controlled tempo rather than heavy stomping.','Only tap the box lightly with your toes, not your full foot.']::text[],'quads',ARRAY['calves','hip_flexors','tibialis_anterior']::text[],'box','cardio','beginner',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c4f2aff0-d474-473a-ad7d-559033aac8b3','Bridge march','bridge-march-4dfe22','Starting position: Lie on your back with knees bent, feet flat on the mat hip-width apart, arms resting alongside your body. Execution: Lift your hips into a bridge position, then while keeping the pelvis level and stable, march by lifting one knee toward your chest, lower it back, and alternate legs without letting the hips drop.',ARRAY['Lie on your back with knees bent and feet flat, arms at your sides.','Press through your heels and lift your hips to form a straight line from shoulders to knees.','Brace your core and lift one foot off the floor, driving the knee up while keeping hips level.','Lower the foot back down under control without dropping the pelvis.','Repeat with the opposite leg, alternating in a marching rhythm.','Continue for the prescribed reps, then lower your hips to the mat.']::text[],ARRAY['Keep hips lifted and level throughout. Avoid tilting or dropping the pelvis.','Squeeze your glutes and brace your core the entire time.','Move slowly and with control rather than rushing the march.','Keep your neck and shoulders relaxed on the mat.']::text[],'glutes',ARRAY['erector_spinae','quads','transverse_abdominis']::text[],'bodyweight','core','intermediate',ARRAY['strength','core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','31f0a2a6-2d44-4c33-bf3a-2d0687b748a4','Bridge pose','bridge-pose','Starting position: Lie on your back with knees bent, feet flat on the floor hip-width apart, and arms at your sides with palms down. Execution: Squeeze your glutes and lift your hips up creating a straight line from knees to shoulders, then lower back down with control.',ARRAY['Lie on your back with knees bent and feet flat on the floor, hip-width apart.','Place arms alongside your body with palms facing down.','Press your feet into the floor and lift your hips toward the ceiling.','Hold at the top, then slowly lower back down.']::text[],ARRAY['Keep knees aligned over ankles.','Engage your glutes and core to support the lift.','Avoid turning your head while in the pose.']::text[],'glutes',ARRAY['hamstrings','erector_spinae','core']::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ca5187cf-f9c2-4ad3-b932-4dccc2e47f7e','Broad jumps','broad-jumps','Starting position: Stand with feet shoulder-width apart, knees slightly bent, and arms at your sides. Execution: Swing your arms back while lowering into a quarter squat, then explosively jump forward as far as possible, swinging your arms forward for momentum and landing softly on both feet.',ARRAY['Stand with feet shoulder-width apart and toes pointing slightly outward','Lower into a quarter squat position while swinging your arms back behind your body','Explosively drive through your heels and jump forward as far as possible','Swing your arms forward and upward to generate maximum momentum','Land softly on the balls of your feet with knees bent to absorb impact','Step back to starting position and reset before the next repetition']::text[],ARRAY['Focus on landing softly with bent knees to protect your joints from impact','Use your arms actively to generate momentum and maintain balance throughout the movement','Keep your core engaged during takeoff and landing to maintain stability','Aim for maximum horizontal distance rather than height to optimize the broad jump technique','Ensure adequate space ahead of you before jumping to prevent injury from obstacles']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cd6edab4-3f1e-477f-8a88-54f9c683c9de','Bulgarian split squat','bulgarian-split-squat','Starting position: Stand 2-3 feet in front of a bench or elevated surface with your back foot elevated on the surface behind you, weight distributed on your front leg. Execution: Lower your body by bending your front knee until your thigh is parallel to the ground, then push through your front heel to return to the starting position.',ARRAY['Rear foot on bench behind you','Front foot forward','Lower until front thigh parallel','Drive up through front heel','Complete reps, switch legs']::text[],ARRAY['Most weight on front leg','Torso stays upright','Front knee tracks over toes','Go deep for glute activation','Balance is challenging at first']::text[],'quads',ARRAY['glute_max','hamstrings','adductors']::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional','balance']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','74a22260-8090-40b6-a13a-4d366c0d5fd6','Bulgarian split squat - with Barbell','bulgarian-split-squat-with-barbell','Starting position: Place a barbell across your upper back and position one foot forward in a lunge stance while the other foot rests on a bench behind you. Execution: Lower your body into a squat while keeping your back straight, then push up to return to the starting position and repeat with the other leg.',ARRAY['Position the barbell securely across your upper trapezius muscles, not on your neck','Step forward 2-3 feet from the bench and place your rear foot on top of the bench','Keep most of your weight on your front leg throughout the entire movement','Lower your body until your front thigh is parallel to the ground or as low as mobility allows','Drive through your front heel to return to the starting position','Complete all repetitions on one leg before switching to the other side']::text[],ARRAY['Keep your torso upright and avoid leaning too far forward to prevent lower back strain','Focus the majority of your weight on your front leg - the rear leg should only provide light balance support','Ensure your front knee tracks in line with your toes and doesn''t cave inward during the movement','Start with bodyweight only to master the movement pattern before adding the barbell','Maintain control throughout the entire range of motion, avoiding bouncing at the bottom position']::text[],'quads','{}'::text[],'barbell','legs','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d81d953b-b29d-438a-aeee-610523bca09d','Bulgarian split squat with Dumbbell','bulgarian-split-squat-with-dumbbell','Starting position: Stand 2-3 feet in front of a bench or elevated surface, holding a dumbbell in each hand at your sides, with your rear foot elevated behind you on the bench. Execution: Lower your body by bending your front knee until your thigh is parallel to the ground, then push through your front heel to return to the starting position.',ARRAY['Rear foot on bench behind you','Front foot forward, dumbbells at sides','Lower until front thigh parallel','Drive up through front heel','Complete reps, switch legs']::text[],ARRAY['Most weight on front leg','Torso stays upright','Front knee tracks over toes','Go deep for glute activation','Balance is challenging at first']::text[],'quads',ARRAY['glute_med','hip_flexors','erector_spinae']::text[],'dumbbell','legs','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','24030adc-de07-4547-a916-24acee3d5a3e','Burpee','burpee','Starting position: Stand upright with feet shoulder-width apart and arms at your sides. Execution: Drop into a squat, place hands on the floor, jump feet back into plank position, perform a push-up, jump feet forward to squat, then explosively jump up with arms overhead.',ARRAY['Begin standing with feet shoulder-width apart and engage your core','Drop down into a deep squat position and place both hands flat on the floor in front of you','Jump or step both feet back simultaneously to assume a plank position with straight body alignment','Perform one push-up by lowering chest to the floor and pressing back up','Jump or step both feet forward back to the squat position under your torso','Explosively jump straight up reaching both arms overhead, then land softly to complete one repetition']::text[],ARRAY['Maintain proper plank alignment during the push-up phase to protect your lower back','Land softly on the balls of your feet when jumping back and forward to reduce joint impact','Keep your core engaged throughout the entire movement sequence','Modify by stepping instead of jumping or eliminating the push-up component if needed','Focus on controlled movement quality over speed, especially when learning the exercise']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b160ea44-725a-415f-919a-4edad64d3ce3','Burpee (No jump)','burpee-no-jump','Starting position: Stand upright with feet hip-width apart and arms at your sides. Execution: Perform a controlled sequence of squatting down, stepping back into plank position, performing a push-up, stepping forward, and standing up without jumping.',ARRAY['Stand with feet hip-width apart, then squat down and place your hands on the floor in front of you','Step your right foot back into plank position, then step your left foot back to join it','Maintain a straight line from head to heels and perform one controlled push-up','Step your right foot forward toward your hands, then step your left foot forward to return to squat position','Stand up slowly and controlled, bringing your arms overhead to complete the movement','Repeat the sequence maintaining steady breathing throughout']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Step back and forward one foot at a time rather than jumping to reduce impact on joints','Maintain proper push-up form with straight body alignment and full range of motion','Control the tempo of each phase rather than rushing through the movement','Focus on smooth transitions between each position to maximize muscle engagement']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a4715d5c-446e-4937-a25a-254652773990','Burpee (No jump) into high plank with shoulder tabs','burpee-no-jump-into-high-plank-shoulder-a4715d5c','Starting position: Stand tall with feet hip-width apart, arms at your sides. Execution: Perform a modified burpee without the jump, transitioning into a high plank and then tapping each shoulder alternately with opposite hands.',ARRAY['Squat down and place hands on the floor in front of your feet','Step or jump both feet back into a high plank position with hands directly under shoulders','Hold the plank position while lifting your right hand to tap your left shoulder','Return right hand to the floor, then lift left hand to tap right shoulder','Step or jump both feet forward toward your hands','Stand up to return to the starting position']::text[],ARRAY['Keep your core engaged throughout the entire movement to prevent lower back strain','Maintain a straight line from head to heels during the plank portion','Minimize hip rotation when performing shoulder taps by engaging your glutes','Keep hands firmly planted and shoulders stable when tapping opposite shoulder','Control the tempo throughout - avoid rushing through the movement to maintain proper form']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['cardio','core','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c424ec91-5260-4a23-800d-1a5e140f8320','Butt bridges','butt-bridges','Starting position: Lie on your back with knees bent and feet flat on the floor, hip-width apart, arms at your sides for stability. Execution: Drive through your heels to lift your hips up by squeezing your glutes, creating a straight line from knees to shoulders, then lower back down with control.',ARRAY['Lie on your back with knees bent at 90 degrees and feet flat on the floor','Place your arms at your sides with palms down for stability','Engage your core and squeeze your glutes as you drive through your heels','Lift your hips up until your body forms a straight line from knees to shoulders','Hold the top position briefly while maintaining the glute squeeze','Lower your hips back down slowly and with control, stopping just before touching the ground']::text[],ARRAY['Focus on driving the movement through your heels rather than pushing with your toes','Avoid overarching your lower back at the top position by keeping your core engaged','Squeeze your glutes at the top of each repetition to maximize muscle activation','Keep your knees pointing forward and avoid letting them cave inward','Maintain steady breathing throughout the exercise, exhaling as you lift up']::text[],'glutes','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1effe46b-4944-4308-b0d3-dd87a0c71bc2','Butt kickers','butt-kickers','Starting position: Stand upright with feet hip-width apart, arms at your sides or bent at 90 degrees. Execution: Run in place while kicking your heels up toward your glutes, alternating legs in a quick, rhythmic motion.',ARRAY['Stand tall with your core engaged and maintain good posture throughout the movement','Begin by lifting one heel toward your glute while staying on the ball of your opposite foot','Alternate legs quickly, focusing on bringing your heels as close to your glutes as possible','Keep your thighs pointing toward the ground and avoid bringing your knees up high','Pump your arms naturally as if you were running to maintain rhythm and balance','Land softly on the balls of your feet to minimize impact on your joints']::text[],ARRAY['Focus on kicking your heels back rather than lifting your knees forward to properly target the hamstrings','Maintain an upright torso and avoid leaning forward as you perform the movement','Start at a moderate pace and gradually increase speed as you become more comfortable with the coordination','Keep the movement controlled to prevent overstretching your quadriceps and maintain proper form','This exercise serves as an excellent dynamic warm-up and cardiovascular conditioning tool']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ed1451e4-ceef-4aa9-a883-24b733b83edd','Butterfly crunches','butterfly-crunches','Starting position: Lie on your back with the soles of your feet pressed together and knees bent outward, forming a diamond shape with your legs, hands placed lightly behind your head. Execution: Contract your abdominal muscles to lift your shoulder blades off the ground while keeping your lower back pressed into the floor, then slowly lower back down with control.',ARRAY['Lie flat on your back and bring the soles of your feet together, allowing your knees to fall outward naturally','Place your hands lightly behind your head with fingers interlaced, keeping your elbows wide','Press your lower back firmly into the floor and engage your core muscles before beginning the movement','Slowly lift your shoulder blades off the ground by contracting your abs, bringing your chest toward your knees','Hold the contraction briefly at the top of the movement','Lower your shoulders back down to the starting position with slow, controlled movement']::text[],ARRAY['Keep your lower back pressed against the floor throughout the entire movement to protect your spine','Avoid pulling on your neck with your hands - let your abdominal muscles do the work','Focus on lifting your shoulder blades rather than just your head to maximize core engagement','Maintain steady breathing and avoid holding your breath during the exercise','The butterfly leg position increases the challenge by reducing stability compared to regular crunches']::text[],'core','{}'::text[],'bodyweight','chest','intermediate',ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','22bf3fc2-d7a0-41d0-9a1a-5e0d149d2b7a','Butterfly Jumps','butterfly-jumps','Starting position: Stand with feet together, arms at your sides, and engage your core. Execution: Jump up while simultaneously spreading your legs wide and bringing your arms overhead, then immediately jump back to the starting position with feet together and arms at your sides.',ARRAY['Stand with feet together and arms relaxed at your sides on a flat, non-slip surface','Bend your knees slightly and engage your core muscles before beginning the movement','Jump up explosively while spreading your legs wide apart and raising both arms overhead','Land softly on the balls of your feet with legs wide and arms extended above your head','Immediately jump again to return to the starting position with feet together and arms at your sides','Maintain a steady rhythm while keeping your movements controlled throughout the exercise']::text[],ARRAY['Land softly on the balls of your feet to reduce impact on your joints and prevent injury','Keep your core engaged throughout the entire movement to maintain proper posture and stability','Start with shorter durations and gradually increase intensity as your cardiovascular fitness improves','Maintain proper breathing by exhaling during the jump phase and inhaling during the brief pause between jumps']::text[],'full_body','{}'::text[],'bodyweight','chest','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f96ea3ee-fb2f-4a0f-bc3b-7e63959450c5','Butterfly Stretch','butterfly-stretch','Starting position: Sit on the floor with the soles of your feet pressed together and knees bent out to the sides, holding your ankles or feet with your hands. Execution: Gently lean forward from your hips while keeping your back straight, allowing your knees to move closer to the floor to stretch the hip flexors and inner thighs.',ARRAY['Sit tall with your spine straight and shoulders relaxed','Press the soles of your feet together and pull them comfortably close to your body','Hold your ankles or feet with both hands for support','Slowly hinge forward from your hips while maintaining a straight back','Breathe deeply and hold the stretch for 15-30 seconds','Return to the starting position slowly and controlled']::text[],ARRAY['Keep your back straight throughout the movement to avoid rounding your spine','Never force your knees down or bounce during the stretch','The stretch should feel gentle and comfortable, not painful','Focus on breathing deeply to help your muscles relax and deepen the stretch','If you have knee issues, place cushions under your thighs for support']::text[],'glutes','{}'::text[],'bodyweight','chest','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5e751b08-c767-4a40-8ef7-62d271995c86','Cable Bicep Curl bar','cable-bicep-curl-bar-1dc79d','Starting position: Stand upright facing a low cable pulley with a straight bar attachment, feet shoulder-width apart, and grip the bar with an underhand (supinated) grip at shoulder width, arms fully extended down. Execution: Keeping your elbows pinned to your sides, curl the bar upward toward your chest by contracting the biceps, then slowly lower it back to the starting position under control.',ARRAY['Attach a straight bar to a low cable pulley and grip it with an underhand grip at shoulder width.','Stand tall with elbows tucked against your torso and arms fully extended.','Curl the bar upward toward your chest by flexing the biceps, keeping elbows stationary.','Squeeze the biceps at the top of the movement.','Lower the bar slowly and under control to full arm extension.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your elbows fixed at your sides throughout the movement.','Avoid swinging or using momentum from the back or hips.','Maintain constant tension by controlling both the lifting and lowering phases.','Keep wrists straight and neutral to protect the joints.']::text[],'biceps',ARRAY['forearm_flexors','brachialis','front_deltoids']::text[],'cable','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f03c074c-398c-4c33-abd9-980ec883fdbd','Cable Bicep Curl rope','cable-bicep-curl-rope-23790c','Starting position: Stand upright facing a low cable pulley with a rope attachment gripped in both hands, arms extended down, elbows tucked at your sides, and feet shoulder-width apart. Execution: Curl the rope upward by flexing at the elbows, squeezing the biceps at the top, then slowly lower back to the starting position under control.',ARRAY['Attach a rope to a low pulley and grip both ends with palms facing each other.','Stand tall with elbows pinned to your sides and a slight bend in your knees.','Curl the rope upward toward your shoulders, keeping elbows stationary.','Squeeze your biceps hard at the top of the movement.','Lower the rope slowly and under control back to full extension.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your elbows fixed at your sides throughout the movement.','Avoid swinging or using momentum from the torso.','Control the eccentric phase to maximize muscle tension.','Maintain an upright posture with a braced core.']::text[],'biceps',ARRAY['brachialis','brachioradialis','forearm_flexors']::text[],'cable','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3adef0aa-9687-4cd0-acf6-410c9fa4ba76','Cable Crossover (Mid)','cable-crossover-mid-b24dfe','Starting position: Stand centered between cable machine pulleys with arms extended holding handles at mid-chest height. Execution: Pull handles together in a horizontal arc across your chest, squeezing pecs at peak contraction.',ARRAY['Set cable pulleys to mid-chest height position','Grab handles with palms facing forward','Step forward creating tension in the cables','Pull handles together across your chest','Squeeze chest muscles at the center position','Slowly return to starting position with control']::text[],ARRAY['Keep a slight bend in your elbows throughout the movement','Maintain upright posture with core engaged and chest up','Focus on squeezing chest muscles rather than just moving weight','Control the negative portion to maximize muscle engagement','Step forward enough to maintain constant tension on the cables']::text[],'chest',ARRAY['front_deltoids','biceps','pectoralis_minor']::text[],'machine','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6cecf804-dcf6-484b-8e1d-57e0d152bbb7','Cable Crunch kneeling','cable-crunch-kneeling-3c7549','Starting position: Kneel facing a high cable pulley with a rope attachment held at the sides of your head or behind your neck, hips stacked over knees and torso upright. Execution: Contract your abs to crunch your torso downward, bringing your elbows toward your thighs, then slowly return to the upright position under control.',ARRAY['Set the cable to a high position, attach a rope, and kneel facing the machine.','Grip the rope and position your hands beside your head with elbows bent.','Brace your core and flex your spine to curl your torso down toward the floor.','Squeeze your abs hard at the bottom of the crunch.','Slowly reverse the movement, resisting the weight until your torso is upright.','Repeat for the desired repetitions maintaining constant tension.']::text[],ARRAY['Round your spine and crunch with your abs, not your hips or arms.','Keep your hips fixed in place throughout the movement.','Control the eccentric phase rather than letting the weight pull you back up.','Exhale forcefully as you crunch down to maximize contraction.']::text[],'rectus_abdominis',ARRAY['obliques','hip_flexors','serratus_anterior']::text[],'cable','core','intermediate',ARRAY['strength','core']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b2073383-2f4c-419e-95f3-0e1cd4f02c34','Cable Deadlift','cable-deadlift','Starting position: Stand facing a low pulley with an attached bar and feet shoulder-width apart. Execution: Hinge at the hips to lower the bar toward the floor while keeping your back straight and knees slightly bent, then slowly return to the starting position.',ARRAY['Set the cable pulley to the lowest position and attach a straight bar or rope handle','Stand 2-3 feet away from the machine with feet hip-width apart, toes pointing slightly outward','Grab the handle with both hands using an overhand grip, arms fully extended','Begin the movement by pushing your hips back while keeping your chest up and spine neutral','Lower the weight in a controlled manner until you feel a stretch in your hamstrings','Drive through your heels and thrust your hips forward to return to the upright position']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Focus on the hip hinge movement rather than squatting down - your knees should only bend slightly','Maintain tension in the cable throughout the entire range of motion, never letting it go slack','Keep your shoulders pulled back and down to maintain proper posture and prevent rounding of the upper back','Control the eccentric (lowering) portion of the movement to maximize muscle engagement and prevent injury']::text[],'full_body','{}'::text[],'cable','full body','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f6fa126f-2811-454f-a542-39780209c9ec','Cable Diagonal Kickback','cable-diagonal-kickback','Starting position: Stand facing a low pulley with a strap around your ankle and foot slightly forward. Execution: Extend your leg backward diagonally while keeping the leg straight, then slowly return to the starting position and repeat with the other leg.',ARRAY['Attach the ankle cuff to your working leg and position yourself facing the cable machine with the pulley set to the lowest position','Stand with your supporting leg slightly bent and lean forward slightly, gripping the machine frame for stability','Keep your core engaged and maintain a neutral spine throughout the movement','Initiate the movement by contracting your glutes and kicking your working leg back and diagonally across your body','Squeeze your glutes firmly at the peak of the movement and hold for one second','Slowly control the weight back to the starting position without letting the weight stack touch']::text[],ARRAY['Focus on initiating the movement from your glutes rather than your lower back to avoid injury','Keep your hips square and avoid rotating your pelvis during the kickback motion','Maintain constant tension on the cable throughout the entire range of motion','Use a weight that allows you to complete the full range of motion with proper form','Keep your working leg straight but not locked to maximize glute activation']::text[],'glutes','{}'::text[],'cable','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9ddd0baa-fa4b-4f5a-8dd4-3a68dc557563','Cable Fly - High to Low','cable-fly-high-to-low-22680d','Starting position: Stand centered between high cable pulleys with arms extended wide holding handles. Execution: Pull handles down and together in an arc motion across your chest.',ARRAY['Set cable pulleys to highest position with handles attached','Stand in center with one foot slightly forward','Grasp handles with arms extended wide at shoulder height','Pull handles down and together across your chest','Slowly return to starting position with controlled movement','Repeat the arc motion maintaining slight elbow bend']::text[],ARRAY['Keep a slight bend in your elbows throughout the entire movement','Focus on squeezing your chest muscles as handles meet in front','Maintain upright posture without leaning forward or backward','Control the weight on both the pulling and returning phases','Stop when handles reach mid-chest level to avoid shoulder strain']::text[],'chest',ARRAY['front_deltoids','serratus_anterior','biceps']::text[],'machine','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','aa3d8f09-8870-4ec1-aada-7760020dfeaa','Cable Fly Low to High','cable-fly-low-to-high-397dee','Starting position: Stand tall between two low cable pulleys with a handle in each hand, arms extended down and slightly out to your sides, palms facing forward, feet shoulder-width apart with a slight staggered stance for stability. Execution: Sweep both arms upward and inward in an arcing motion until your hands meet in front of your upper chest/face level, squeezing the chest, then slowly reverse back to the start under control.',ARRAY['Set both cable pulleys to the lowest position and grasp a handle in each hand.','Step forward to create tension, keeping a slight bend in the elbows and chest lifted.','Sweep your arms up and in along an arc until the handles meet at upper chest or face height.','Squeeze the upper chest at the top of the movement.','Slowly lower the handles back along the same path until you feel a stretch across the chest.','Repeat for the desired number of repetitions maintaining control throughout.']::text[],ARRAY['Keep a soft, fixed bend in the elbows. Avoid turning it into a press.','Drive the movement from the chest, not the arms or shoulders.','Maintain an upright torso and braced core; avoid leaning back excessively.','Control the eccentric and get a full stretch at the bottom without shrugging the shoulders.']::text[],'chest',ARRAY['front_deltoids','serratus_anterior','biceps']::text[],'cable','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','20500648-961e-4344-bb9b-c775ffc1fe71','Cable Front Kick','cable-front-kick','Starting position: Stand facing a low pulley with a strap around your ankle and foot slightly forward. Execution: Extend your leg forward while keeping it straight, then slowly return to starting position and repeat with the other leg.',ARRAY['Attach the ankle strap to the low cable pulley and secure it firmly around your ankle','Stand feet hip-width apart, holding the machine frame for balance','Engage your core and maintain an upright posture with slight bend in your supporting leg','Drive your attached leg forward in a smooth kicking motion, focusing on using your quadriceps','Pause briefly at the top of the movement when your leg is fully extended','Slowly lower your leg back to the starting position with control, resisting the weight']::text[],ARRAY['Keep your torso upright and avoid leaning backward during the kicking motion','Focus on controlled movement rather than speed to maximize muscle engagement and prevent injury','Ensure the ankle strap is securely fastened to prevent it from slipping during the exercise','Start with lighter weight to master the movement pattern before progressing to heavier resistance','Maintain constant tension in your core to protect your lower back throughout the movement']::text[],'quads','{}'::text[],'cable','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','697ec8a9-34fe-419e-a1b8-825456a3b335','Cable Front Raise','cable-front-raise','Starting position: Stand facing a cable pulley with both handles gripped and arms extended downward. Execution: Raise both handles to the front until they reach shoulder height, then slowly lower.',ARRAY['Set the cable pulley to the lowest position and attach a straight bar or rope handle','Stand 2-3 feet away from the machine with feet shoulder-width apart for stability','Grasp the handle with an overhand grip, keeping a slight bend in your elbows throughout the movement','Engage your core and maintain upright posture with shoulders back','Raise the handle forward and up until your arms reach shoulder height, focusing on controlled movement','Lower the weight slowly back to starting position, maintaining tension throughout the entire range of motion']::text[],ARRAY['Keep your core engaged and avoid using momentum or swinging the weight up','Maintain a slight bend in your elbows throughout the entire movement to protect the joint','Stop the upward motion when your arms reach parallel to the floor to avoid shoulder impingement','Focus on slow, controlled movement both on the way up and down to maximize muscle activation','Start with lighter weight to master the form before progressing to heavier resistance']::text[],'shoulders','{}'::text[],'cable','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d3f23ea3-a3d3-46cd-940b-707efea0df5c','Cable Glute Kickback','cable-glute-kickback','Starting position: Stand facing a low pulley with an ankle strap attached and foot slightly forward. Execution: Extend your leg backward while keeping it straight, then slowly return to starting position and repeat with the other leg.',ARRAY['Attach the ankle cuff to the low pulley and secure it around your ankle','Stand facing the cable machine with your working leg slightly behind your body','Grip the machine with both hands for stability and engage your core','Keep your torso upright and kick your leg straight back by contracting your glute','Hold the peak contraction for one second','Slowly return your leg to the starting position with control']::text[],ARRAY['Keep your hips square and avoid rotating your pelvis during the movement','Focus on squeezing your glute at the top of the movement rather than just lifting your leg','Maintain a slight bend in your supporting leg throughout the exercise','Control the weight on both the lifting and lowering phases to maximize muscle engagement','Keep your torso upright and avoid leaning forward excessively']::text[],'glutes','{}'::text[],'cable','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','86a5f361-6b81-4ab7-a769-c32ca56d5ae4','Cable Hip Abduction','cable-hip-abduction-86a5f361','Starting position: Stand facing a low pulley with a strap around your ankle and foot slightly inward. Execution: Abduct your leg to the side while keeping it straight, then slowly return to the starting position and repeat with the other leg.',ARRAY['Attach the ankle cuff to your outside leg and position yourself arm''s length from the cable machine','Stand with feet hip-width apart, slight knee bend, and hold the machine for stability with your inside hand','Engage your core and keep your torso upright throughout the entire movement','Lift your outside leg directly to the side until you feel a strong contraction in your glutes','Slowly lower your leg back to the starting position, maintaining tension in the cable','Perform all repetitions on one side before switching to the other leg']::text[],ARRAY['Keep your torso stable and avoid leaning away from the machine during the movement','Focus on lifting the leg from the hip rather than just moving the foot outward','Control the eccentric portion of the movement to maximize glute activation','Maintain a slight forward lean of the torso to better target the gluteus medius','Start with lighter weight to master the movement pattern before progressing']::text[],'glutes','{}'::text[],'cable','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8503592c-a179-456b-9417-5fb5e84fad1a','Cable Hip Abduction','cable-hip-abduction','Starting position: Stand facing a low pulley with a strap around your ankle and foot slightly forward. Execution: Abduct your leg outward while squeezing your glutes, then slowly return to the starting position and repeat with the other leg.',ARRAY['Attach the ankle cuff to your outer leg and position yourself sideways to the cable machine','Stand tall with your inner hand holding the machine for support and your feet hip-width apart','Engage your core and maintain a straight posture throughout the movement','Lift your outer leg straight out to the side until you feel tension in your outer glute','Hold briefly at the top position then slowly lower your leg back to starting position','Complete all repetitions on one side before switching to the other leg']::text[],ARRAY['Keep your torso upright and avoid leaning away from the machine during the movement','Focus on lifting from your hip rather than swinging your leg to ensure proper glute activation','Control the eccentric portion by slowly lowering your leg rather than letting the cable pull it back','Maintain tension in your glutes throughout the entire range of motion','Start with lighter resistance to master the movement pattern before increasing weight']::text[],'glutes','{}'::text[],'cable','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','db7c0708-ea39-47cb-89c8-73e749abcfa6','Cable Hip Extension','cable-hip-extension','Starting position: Stand facing a low pulley with a strap around your ankle and foot slightly behind you. Execution: Extend your leg backward while squeezing the glutes, then slowly return to starting position. Repeat with the other leg.',ARRAY['Attach the ankle cuff to your working leg and face the cable machine','Hold onto the machine with both hands for stability and stand tall','Position your working leg slightly forward with a soft knee','Drive your leg straight back by contracting your glutes, keeping your torso upright','Squeeze your glutes at the top of the movement for one second','Slowly return your leg to the starting position with control']::text[],ARRAY['Keep your core engaged throughout the movement to prevent lower back arching','Focus on moving only at the hip joint while keeping your knee relatively straight','Avoid leaning forward or using momentum to swing your leg back','Control the weight on both the lifting and lowering phases of the movement','Start with lighter weight to master the form before progressing']::text[],'glutes','{}'::text[],'cable','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cd2bfdbe-71d7-4d3e-8b03-fc4a5ed73bf4','Cable Kickback','cable-kickback','Starting position: Stand facing a low pulley with an ankle strap attached and foot slightly forward. Execution: Extend your leg backward while squeezing your glutes, then slowly return to starting position and repeat with the other leg.',ARRAY['Attach the ankle cuff to your working leg and position yourself facing the cable machine','Hold onto the machine or handles for balance and stability','Keep a slight bend in your standing leg and engage your core','Drive your working leg straight back by squeezing your glutes, keeping the leg straight','Pause briefly at the top of the movement when you feel maximum glute contraction','Slowly lower your leg back to starting position with control, maintaining tension']::text[],ARRAY['Keep your torso upright and avoid leaning forward or arching your back excessively','Focus on moving only at the hip joint while keeping your working leg straight','Control the weight on both the lifting and lowering phases to maximize muscle activation','Avoid swinging your leg or using momentum to complete the movement','Keep your hips square and facing forward throughout the entire exercise']::text[],'glutes','{}'::text[],'cable','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a6a9ea7b-c868-4924-842a-9c3232698c3b','Cable Lateral Raise','cable-lateral-raise','Starting position: Stand facing a cable pulley with a handle in each hand, arms extended downward. Execution: Raise the arms to the sides until they reach shoulder height, then slowly lower.',ARRAY['Set the cable pulley to the lowest position and attach a single handle','Stand with your side to the machine, feet shoulder-width apart, and grasp the handle with your outside hand','Keep a slight bend in your elbow and maintain good posture with your core engaged','Raise your arm out to the side until it reaches shoulder height, leading with your pinky finger','Hold briefly at the top, then slowly lower the weight back to the starting position']::text[],ARRAY['Keep your torso upright and avoid leaning away from the machine during the movement','Use a controlled tempo, taking 2-3 seconds to raise and lower the weight','Stop at shoulder height to avoid impingement and maintain tension on the deltoids','Focus on lifting with your shoulder muscles rather than using momentum or your back','Start with lighter weight to master the form before progressing to heavier resistance']::text[],'shoulders','{}'::text[],'cable','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ca7a2f9d-3af1-40cd-a33f-431f437a2902','Cable Preacher Curl','cable-preacher-curl','Starting position: Stand facing a low pulley with a straight bar attached, arms resting on a preacher bench. Execution: Bend your elbows to lift the bar toward your shoulders, then lower in a controlled manner.',ARRAY['Adjust the preacher bench so your chest is firmly against the pad and your armpits align with the top edge','Set the cable pulley to the lowest position and attach a straight bar or EZ-curl bar handle','Grasp the handle with an underhand grip, hands shoulder-width apart, and position your upper arms flat against the angled pad','Keep your feet planted firmly on the floor and maintain a straight back throughout the movement','Curl the weight up using only your biceps while keeping your wrists straight and upper arms pressed against the pad','Lower the weight slowly and under control, stopping just short of full arm extension to maintain tension']::text[],ARRAY['Keep your upper arms completely stationary against the preacher pad throughout the entire range of motion','Avoid letting the weight pull your arms into full extension at the bottom to prevent elbow hyperextension','Use a controlled tempo with a 2-second lift and 3-second lowering phase for optimal muscle engagement','Select a weight that allows you to maintain proper form for the entire set without using momentum or body swing','Stop the exercise immediately if you feel any sharp pain in your elbows or shoulders']::text[],'biceps','{}'::text[],'cable','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','95fb26cd-a80a-4d69-92a0-af6bf54128bc','Cable Pull-Through','cable-pull-through-554c58','Starting position: Stand facing away from cable machine with rope between legs, hips hinged back. Execution: Drive hips forward explosively to standing position, then return to hip-hinged start.',ARRAY['Set cable at lowest pulley position with rope attachment','Stand facing away from machine with feet shoulder-width apart','Grab rope with both hands between your legs','Hinge at hips pushing glutes back until torso parallel','Drive hips forward explosively to full standing position','Control the weight back to starting hip-hinged position']::text[],ARRAY['Keep knees slightly bent throughout the entire movement','Focus on hip hinge movement rather than squatting down','Maintain neutral spine by keeping chest up and core engaged','The movement should be driven by your glutes and hamstrings','Avoid using your arms to pull the weight']::text[],'legs',ARRAY['adductors','abs','forearms']::text[],'machine','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d237c00f-e6f3-44f0-953b-5db4c970f873','Cable Rear Delt Fly','cable-rear-delt-fly','Starting position: Stand facing a low pulley with a cable in each hand, palms facing down. Execution: Raise the cables backward while keeping your elbows slightly bent, then slowly lower to starting position.',ARRAY['Set both cable pulleys to shoulder height and attach single handles to each side','Stand in the center with feet shoulder-width apart, grab the left handle with your right hand and right handle with your left hand','Step back until there is tension in the cables with your arms extended forward at shoulder height','Pull both handles back simultaneously in a wide arc, leading with your pinkies and keeping a slight bend in your elbows','Squeeze your shoulder blades together at the end range of motion, feeling the contraction in your rear delts','Slowly return to the starting position with control, maintaining tension throughout the entire range of motion']::text[],ARRAY['Keep your core engaged and maintain a slight forward lean to prevent using momentum','Focus on initiating the movement from your rear delts rather than your arms by thinking about pulling your shoulder blades together','Use a weight that allows you to control the eccentric portion of the movement for maximum muscle activation','Avoid letting your shoulders roll forward at the starting position to maintain proper posture','Keep your wrists neutral and lead the pull with your pinkies to better target the rear deltoids']::text[],'shoulders','{}'::text[],'cable','shoulders','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7665b7ae-4cea-4591-bafe-e73cdaa5beac','Cable Rope Face Pull','cable-rope-face-pull','Starting position: Stand facing a high pulley with a rope attached to the pulley. Execution: Pull the rope toward your chest while keeping elbows high, then slowly return to the starting position.',ARRAY['Set the cable machine to upper chest height and attach a rope handle','Stand arm''s length from the machine with feet shoulder-width apart for stability','Grasp the rope handles with palms facing down and step back until there is tension in the cable','Pull the rope straight toward your face while squeezing your shoulder blades together','Separate the rope handles as they reach your face, leading with your elbows','Slowly return to the starting position with control, maintaining tension throughout the movement']::text[],ARRAY['Keep your elbows higher than your wrists throughout the entire movement to properly target the rear delts','Focus on squeezing your shoulder blades together rather than just pulling with your arms','Use a weight that allows you to maintain perfect form - this exercise is about activation, not heavy loading','Pull the rope to your face level, not to your chest or neck, to maximize rear deltoid engagement','Maintain a slight forward lean and engaged core to prevent using momentum']::text[],'shoulders','{}'::text[],'cable','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b4824ea0-4d0a-418e-b22d-462b11dc9992','Cable Rope Pullover','cable-rope-pullover','Starting position: Stand facing a high pulley with a rope attached to the cable. Execution: Pull the rope down toward your thighs while keeping elbows slightly bent, then slowly return to the starting position.',ARRAY['Set the cable machine to the highest position and attach a rope handle','Stand approximately 2-3 feet away from the machine facing the cable stack','Grasp the rope with both hands using a neutral grip, arms fully extended overhead','Engage your core and maintain a slight forward lean throughout the movement','Pull the rope down and back toward your hips in a smooth arc while keeping arms straight','Slowly return to the starting position with controlled resistance']::text[],ARRAY['Keep your arms straight throughout the entire movement to properly target the lats','Maintain a slight forward lean and engaged core to protect your lower back','Focus on pulling with your lats rather than using your arms or shoulders','Control the weight on both the lowering and raising phases of the movement','Avoid using momentum or swinging your body to complete the repetition']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b35c3787-5974-4cca-b3d5-c28f7efa1472','Cable Rope Tricep Pushdown','cable-rope-tricep-pushdown','Starting position: Stand facing a high pulley with a rope attached to the cable. Execution: Extend your elbows to push the rope ends downward, keeping your elbows fixed in place.',ARRAY['Set the cable pulley to the highest position and attach a rope handle','Stand facing the cable machine with feet shoulder-width apart for stability','Grasp the rope with both hands using an overhand grip, keeping your upper arms pressed against your sides','Begin the movement by pushing the rope downward, focusing on extending only your forearms','Continue pushing until your arms are fully extended and the rope reaches your thighs','Slowly return to the starting position by allowing your forearms to rise back up with control']::text[],ARRAY['Keep your upper arms stationary throughout the entire movement to isolate the triceps effectively','Maintain an upright posture with your core engaged to prevent using momentum','Use a controlled tempo on both the downward and upward phases of the movement','At the bottom of the movement, pull the rope ends slightly apart to maximize tricep contraction','Start with lighter weight to master proper form before progressing to heavier loads']::text[],'triceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','646f354b-3790-4796-bfd9-cd9df04bcc16','Cable Step-Ups','cable-step-ups','Starting position: Stand facing a cable machine with one foot on a bench or step, holding the cable handle at your side. Execution: Step up onto the bench by driving through your elevated leg, bringing your other leg up to meet it, then step back down with control.',ARRAY['Position yourself facing the cable machine with one foot planted firmly on the bench or step','Hold the cable handle with the arm opposite to your stepping leg, maintaining tension in the cable','Drive through your heel on the elevated leg to step up onto the bench, bringing your trailing leg up','Keep your torso upright and core engaged throughout the movement','Step back down with control, lowering your trailing leg first followed by your stepping leg','Maintain constant tension in the cable throughout the entire range of motion']::text[],ARRAY['Keep your weight centered over your stepping leg to maintain balance and maximize quad activation','Control the descent phase to prevent bouncing and maintain muscle tension','Ensure the bench height allows your knee to be at roughly 90 degrees when your foot is planted','Keep your core tight and avoid leaning too far forward or backward during the movement','Use the cable resistance to add challenge while maintaining proper stepping form']::text[],'quads','{}'::text[],'cable','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','21dda23e-d221-4800-924e-498f4398f203','Cable Straight Leg Kickback','cable-straight-leg-kickback','Starting position: Stand facing a low pulley with a strap around your ankle and foot slightly forward. Execution: Extend your leg straight back in a line while keeping it straight, then slowly return to starting position and repeat with the other leg.',ARRAY['Attach the ankle strap to your working leg and set the cable to the lowest pulley position','Stand facing the cable machine with feet hip-width apart, holding the frame for stability','Keep your core engaged and maintain a slight forward lean from your hips throughout the movement','Kick your leg straight back without arching your lower back, focusing on moving only at the hip joint','Squeeze your glutes at the top of the movement and hold for a brief pause','Lower your leg back to the starting position with control, maintaining tension on the cable']::text[],ARRAY['Keep your working leg completely straight throughout the entire range of motion to maximize glute activation','Avoid arching your lower back by keeping your core tight and maintaining a neutral spine position','Focus on the glute squeeze at the top rather than kicking as high as possible','Control both the lifting and lowering phases of the movement to maintain constant tension on the glutes','Start with lighter resistance to master the form before progressing to heavier weights']::text[],'glutes','{}'::text[],'cable','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','207924a2-ae75-4371-be43-49c3cc62b4e1','Cable Tricep Pushdown','cable-tricep-pushdown','Starting position: Stand facing a high pulley with a straight bar attached to the pulley. Execution: Extend your elbows to push the bar downward while keeping your elbows fixed in place.',ARRAY['Set the cable pulley to the highest position and attach your preferred handle (straight bar, rope, or V-bar)','Stand close to the machine with feet shoulder-width apart and slight forward lean','Grip the attachment with palms facing down, keeping elbows pinned to your sides throughout the movement','Push the weight down using only your forearms until your arms are completely extended','Slowly return to starting position, stopping when your forearms are parallel to the floor','Maintain constant tension on the triceps by controlling both the downward and upward phases']::text[],ARRAY['Keep your elbows stationary and pressed against your sides to isolate the triceps effectively','Use a full range of motion by fully extending at the bottom and returning to forearm-parallel position at the top','Control the weight during the eccentric (returning) phase rather than letting it snap back quickly','Start with lighter weight to master proper form before progressing to heavier loads','Avoid using momentum or swinging your body to move the weight']::text[],'triceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ab522399-6b5e-4a37-aa7a-47d2ec862631','Cable Tricep Pushdown','cable-tricep-pushdown-ab522399','Starting position: Stand facing a high cable pulley with a straight bar attached to the pulley. Execution: Extend the elbows to push the bar downward, keeping elbows fixed in place.',ARRAY['Set the cable pulley to the highest position and attach your chosen handle','Stand with feet hip-width apart, core engaged, and maintain a slight forward lean','Grip the attachment with palms facing down, keeping elbows close to your ribcage','Push the weight down by extending your forearms until your arms are fully straight','Squeeze your triceps at the bottom of the movement for one second','Slowly return to starting position, maintaining control throughout the entire range of motion']::text[],ARRAY['Keep your elbows stationary and close to your body throughout the entire movement to properly isolate the triceps','Focus on controlling the weight on both the downward and upward phases to maximize muscle engagement','Avoid using your shoulders or swinging your body to move the weight','Start with lighter weight to master proper form before progressing to heavier resistance','Maintain a neutral spine and avoid arching your back during the exercise']::text[],'triceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','56c25b1f-91f4-4fd1-99b9-89e4da81ecdc','Cable Upright Row','cable-upright-row-5bd938','Starting position: Stand facing cable machine with rope or bar attachment at low position, arms extended downward. Execution: Pull attachment vertically upward along body to chest level, then lower with control.',ARRAY['Set cable attachment at lowest pulley position','Grasp rope or bar with overhand grip','Stand upright with feet shoulder-width apart','Pull attachment straight up to upper chest','Lower slowly back to starting position']::text[],ARRAY['Keep elbows higher than wrists throughout the movement','Stop pulling when hands reach upper chest level to avoid shoulder impingement','Maintain upright posture without leaning backward during the pull','Use a controlled tempo especially during the lowering phase']::text[],'shoulders',ARRAY['upper_traps','biceps','forearms','rhomboids']::text[],'machine','strength','intermediate','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','23d6cf5e-2f9a-4f78-a962-d22e6fe36aa9','Cable Woodchop (High to Low)','cable-woodchop-high-to-low-842bc7','Starting position: Stand with feet shoulder-width apart, grasping cable handle with both hands at high position. Execution: Pull cable diagonally down and across body while rotating torso.',ARRAY['Set cable at high position above shoulder height','Grasp handle with both hands using interlocked grip','Stand sideways to machine with feet shoulder-width apart','Pull cable diagonally down across body toward opposite hip','Rotate torso while keeping arms relatively straight','Control the weight back to starting position']::text[],ARRAY['Keep core engaged throughout the entire movement','Pivot on back foot to allow proper hip rotation','Move from your core rather than just your arms','Maintain straight back posture throughout the exercise','Control both the pulling and returning phases']::text[],'core',ARRAY['rectus_abdominis','serratus_anterior','erector_spinae']::text[],'machine','core','intermediate',ARRAY['strength','core']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','25ec2936-1aa7-4fb9-86a3-e3b73ab94e7c','Cable Woodchop low to high','cable-woodchop-low-to-high-d2e19e','Starting position: Stand side-on to a low cable pulley with feet shoulder-width apart, knees slightly bent, and grasp the handle with both hands near the hip closest to the machine. Execution: Rotate the torso and pull the handle diagonally across the body from low to high, finishing above the opposite shoulder while pivoting the trailing foot, then return under control.',ARRAY['Set the cable pulley to the lowest position and grip the handle with both hands beside your hip.','Adopt an athletic stance with knees bent and core braced.','Drive through your hips and rotate your torso to pull the handle diagonally up and across your body.','Extend your arms as the handle finishes above the opposite shoulder.','Slowly reverse the motion, controlling the load back to the starting hip.','Complete all reps on one side before switching.']::text[],ARRAY['Initiate the movement from your hips and core, not just your arms.','Keep your arms relatively straight to emphasize rotation through the trunk.','Pivot the back foot to allow full hip rotation and protect the knees.','Control the eccentric phase rather than letting the cable pull you back.']::text[],'obliques',ARRAY['front_deltoids','glutes','quads','serratus_anterior']::text[],'cable','core','intermediate',ARRAY['strength','functional','core']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8577f8c3-283b-472b-b5cf-d0eaa8e84762','Calf gas peddlers','calf-gas-peddlers','Starting position: Begin in a downward dog position with hands planted firmly on the ground, hips elevated, and feet positioned hip-width apart. Execution: Perform alternating heel raises by lifting one heel up while keeping the other foot grounded, simulating a pedaling motion while maintaining the downward dog position.',ARRAY['Start in downward dog position with hands firmly planted on the mat shoulder-width apart','Keep your hips elevated and create an inverted V-shape with your body','Place feet hip-width apart with toes pointing forward','Lift one heel up toward the ceiling while keeping the other foot grounded','Alternate between feet in a controlled pedaling motion','Maintain steady breathing throughout the movement']::text[],ARRAY['Keep your core engaged to maintain stability in the inverted position','Distribute weight evenly between your hands to avoid wrist strain','Focus on controlled movements rather than speed to maximize calf engagement','Keep your head in neutral alignment with your spine','Ensure both hands remain firmly planted throughout the exercise']::text[],'calves','{}'::text[],'bodyweight','legs','intermediate',ARRAY['mobility','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6a20f987-50aa-4023-9d0a-723759a24d55','Calf Raise Intervals','calf-raise-intervals-74d788','Starting position: Stand upright with feet hip-width apart, hands resting on the hips, and weight balanced over the balls of the feet. Execution: Rise onto the toes by extending the ankles, then lower the heels back toward the floor in a rhythmic, continuous fashion for timed intervals.',ARRAY['Stand tall with feet hip-width apart and place your hands on your hips for stability.','Push through the balls of your feet to lift both heels off the ground.','Squeeze your calves at the top of the movement.','Lower your heels back down under control without fully resting between reps.','Repeat the raises continuously for the prescribed time interval.','Keep a steady, rhythmic tempo throughout the set.']::text[],ARRAY['Keep your knees soft and your torso upright throughout.','Rise as high as possible on the toes to fully contract the calves.','Control the lowering phase rather than dropping the heels.','Maintain balance by engaging your core and keeping weight centered.']::text[],'calves',ARRAY['soleus','tibialis_anterior','peroneals']::text[],'bodyweight','plyometric','beginner',ARRAY['cardio','plyometric','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','43946d04-02aa-4dc8-9a67-3cb759440c22','Calf Raises','calf-raises-b3f02c','Starting position: Stand upright with the balls of your feet on the edge of a raised box or step, heels hanging off the edge, using a wall for light balance support. Execution: Push through the balls of your feet to raise your heels as high as possible, then lower under control to a deep stretch below the box level.',ARRAY['Position the balls of both feet on the edge of the box with heels hanging off.','Rest a hand lightly on the wall for balance and keep your torso upright.','Press up onto your toes, lifting your heels as high as possible.','Pause briefly at the top and squeeze the calves.','Lower your heels slowly below the box level to feel a full stretch.','Repeat for the desired number of repetitions.']::text[],ARRAY['Move slowly and controlled through the full range of motion.','Fully extend at the top and stretch at the bottom for maximum calf activation.','Keep knees relatively straight to emphasize the gastrocnemius.','Avoid bouncing or using momentum.']::text[],'calves',ARRAY['gastrocnemius','soleus','peroneals']::text[],'box','strength','beginner',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','90924318-0ca7-46ec-9e87-36b80e02196f','Calf stretch (left)','calf-stretch-left','Starting position: Begin in a plank position with hands planted firmly on the ground, body in a straight line, and feet positioned with one foot slightly forward. Execution: Hold this static position to create a deep stretch through the calf muscle of the back leg while maintaining proper plank form.',ARRAY['Start in a high plank position with hands shoulder-width apart and arms straight','Step your left foot slightly forward while keeping your right leg extended behind you','Press your right heel down toward the ground to intensify the calf stretch','Keep your core engaged and maintain a straight line from head to heels','Hold the position for 20-30 seconds while breathing steadily','Switch sides to stretch the opposite calf']::text[],ARRAY['Keep your hands firmly planted and shoulders directly over your wrists for stability','Focus on pressing the heel of the back leg down to maximize the calf stretch','Maintain core engagement throughout to prevent sagging hips or arching back','Breathe deeply and avoid holding your breath during the stretch','If the stretch feels too intense, slightly bend the back knee to reduce tension']::text[],'calves','{}'::text[],'bodyweight','legs','beginner',ARRAY['stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5ce9ef64-7527-4321-997b-1d1bc071f91a','Calf stretch (right)','calf-stretch-right','Starting position: Begin in a bear crawl position with hands on the ground, one foot placed on top of a massage ball or similar prop, and the other foot planted on the ground. Execution: Hold this static stretch position to target the calf muscle of the elevated leg while maintaining stability through your arms and supporting leg.',ARRAY['Start in a bear crawl position with hands planted firmly on the ground shoulder-width apart','Place one foot on top of a massage ball or foam roller while keeping the other foot flat on the ground','Keep your arms straight and core engaged to maintain stability','Hold the stretch position, allowing the elevated leg''s calf to lengthen over the ball','Breathe deeply and maintain the position for the desired duration','Switch legs to stretch the opposite calf']::text[],ARRAY['Keep your hands firmly planted and arms straight to provide stable support','Maintain core engagement throughout the stretch to prevent lower back strain','The supporting leg should remain planted with knee slightly bent for balance','Focus on feeling the stretch in the calf of the elevated leg rather than forcing the position','Start with shorter hold times and gradually increase as flexibility improves']::text[],'calves','{}'::text[],'bodyweight','legs','beginner',ARRAY['stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cb06c2a3-ef02-4e60-b9ab-7d692fa97bc4','Camel pose','camel-pose','Starting position: Kneel on the floor with shins parallel, hips directly over knees, and hands on lower back for support. Execution: Slowly arch backward, reaching one hand at a time toward your heels while lifting the chest and opening the heart center.',ARRAY['Kneel on the mat with knees hip-width apart and thighs perpendicular to the floor.','Place your hands on your lower back with fingers pointing down.','Inhale, lift your chest, and slowly lean back.','If comfortable, reach your hands back to your heels.']::text[],ARRAY['Press your hips forward to protect your lower back.','Keep your neck neutral or gently extend it back.','Engage your core throughout the backbend.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','675fab33-9f21-4386-8a43-a319d0684841','Cat cow pose','cat-cow-pose','Starting position: Begin on your hands and knees in a tabletop position with wrists directly under shoulders and knees under hips. Execution: Alternate between arching your back and looking up (cow pose) and rounding your spine while tucking your chin to chest (cat pose).',ARRAY['Start on all fours with wrists under shoulders and knees under hips.','Inhale, drop your belly toward the mat, lift your chest and tailbone (Cow).','Exhale, round your spine toward the ceiling, tuck your chin and tailbone (Cat).','Continue flowing between Cat and Cow with each breath.']::text[],ARRAY['Keep arms straight throughout the movement.','Initiate the movement from your pelvis.','Move slowly and synchronize with your breath.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','mobility','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8e75c181-9db4-4e20-8fa7-be744f820f95','Cat pose','cat-pose','Starting position: Begin on your hands and knees in a tabletop position with wrists under shoulders and knees under hips. Execution: Slowly round your spine upward toward the ceiling while dropping your head and tailbone down, creating a curved arch like an angry cat.',ARRAY['Start on all fours with wrists under shoulders and knees under hips.','Exhale and round your spine toward the ceiling.','Tuck your chin toward your chest and your tailbone under.','Hold for a few breaths, then release.']::text[],ARRAY['Press firmly through your hands.','Draw your navel toward your spine.','Keep arms straight throughout.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d749fe82-c106-48d7-9508-7ab1cb88ec1b','Chair Leg Extension','chair-leg-extension','Starting position: Sit tall on a sturdy chair with both feet flat on the floor and hands holding the sides of the seat. Execution: Extend one knee until the leg is straight and parallel to the floor, pause briefly, then lower the foot back down with control and repeat before switching legs.',ARRAY['Sit tall on a sturdy chair with feet flat and hands holding the sides of the seat.','Brace the core and extend one knee until the leg is straight and roughly parallel to the floor.','Pause at the top and squeeze the front of the thigh.','Lower the foot back down slowly without letting it slam.','Complete all reps on one leg, then switch sides.']::text[],ARRAY['Keep the back tall against the chair, do not lean back as the leg lifts.','The movement happens at the knee only, thighs stay on the seat.','Pause and squeeze at full extension, that is the working moment.','Lower under control, the way down is half the exercise.']::text[],'quads',ARRAY['hip flexors','core']::text[],'chair','strength','beginner',ARRAY['strength','rehabilitation']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','46f8865d-24c2-4c81-a886-aa458c5653c5','Chair pose','chair-pose','Starting position: Stand with feet hip-width apart, arms at your sides. Execution: Lower your hips back and down as if sitting into an imaginary chair while raising your arms overhead, creating a squat-like position that primarily targets the quadriceps.',ARRAY['Stand with feet together or hip-width apart.','Bend your knees and lower your hips as if sitting in a chair.','Raise your arms overhead alongside your ears.','Hold, keeping weight in your heels.']::text[],ARRAY['Keep knees behind your toes.','Engage your core and lengthen your spine.','Shift weight into your heels.']::text[],'quads','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f8255cfd-7c0e-4451-89a5-947009e4fd13','Chair running chair step knee touch','chair-running-chair-step-knee-touch-4ff1ca','Starting position: Sit tall toward the front edge of a sturdy chair, hands gripping the sides of the seat for support and feet flat on the floor. Execution: Alternately drive each knee up toward the chest in a running motion, keeping the torso stable and engaging the core throughout.',ARRAY['Sit upright on the edge of the chair holding the seat sides for stability.','Lift one knee up toward your chest while keeping the opposite foot planted.','Lower that leg and immediately raise the other knee in a running rhythm.','Continue alternating knees at a controlled, steady pace.','Keep your chest up and core braced for the entire set.']::text[],ARRAY['Maintain an upright posture and avoid rounding the lower back.','Engage the abdominals to lift the knees rather than swinging.','Keep movements controlled and rhythmic to sustain the cardio effect.','Grip the chair firmly for stability but do not hunch over.']::text[],'hip_flexors',ARRAY['core','rectus_femoris','adductors']::text[],'chair','cardio','beginner',ARRAY['cardio','core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','89b62000-867f-4f98-b24c-ad9b5708d015','Chair sit ups','chair-sit-ups','Starting position: Lie on your back with knees bent at 90 degrees, feet elevated and legs positioned as if sitting in a chair. Execution: Perform a crunching motion by lifting your shoulders and upper back off the ground while keeping your legs in the chair position.',ARRAY['Lie flat on your back on a mat with your arms positioned alongside your head for support','Bend your knees to 90 degrees and lift your feet off the ground, positioning your legs as if sitting in an invisible chair','Engage your core muscles and slowly lift your shoulders and upper back off the ground','Crunch upward while keeping your lower back pressed against the mat and maintaining the chair leg position','Lower your shoulders back down with control, maintaining tension in your core throughout','Keep your legs stable in the elevated position throughout all repetitions']::text[],ARRAY['Keep your lower back pressed firmly against the mat to protect your spine','Focus on lifting with your abdominal muscles rather than pulling on your neck','Maintain the 90-degree bend in your knees throughout the entire exercise','Control both the upward and downward phases of the movement for maximum effectiveness','Breathe out as you crunch up and breathe in as you lower down']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','af0e7c20-cd4a-4c26-ac10-1ef6bdaaf35e','chair Twists','chair-twists-a1be89','Starting position: Sit upright on a chair with feet flat on the floor, hip-width apart, and bring your hands together or bent at chest height. Execution: Rotate your torso from side to side in a controlled manner, keeping your hips and lower body stable while engaging your obliques and core throughout the movement.',ARRAY['Sit tall on the chair with feet flat and core engaged.','Bring your hands together in front of your chest with elbows bent.','Rotate your upper body to one side while keeping hips facing forward.','Return to center, then rotate to the opposite side.','Continue alternating sides in a smooth, controlled rhythm.']::text[],ARRAY['Keep your spine tall and avoid slouching during rotations.','Move from your waist and core, not just your arms.','Keep hips and legs stable to isolate the twist through the trunk.']::text[],'obliques',ARRAY['external_obliques','internal_obliques','hip_flexors']::text[],'chair','core','beginner',ARRAY['core','mobility','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','55bd4c71-78c6-49bd-aaaa-8c03b7528342','Chameleon push up','chameleon-push-up','Starting position: Begin in a downward dog position with hands planted firmly on the ground, knees tucked under the torso, and hips elevated. Execution: Perform a push-up movement while maintaining the tucked knee position throughout the entire range of motion.',ARRAY['Start in a downward dog position with hands shoulder-width apart and knees tucked underneath your torso','Keep your knees bent and pulled toward your chest throughout the entire movement','Lower your chest toward the ground by bending your elbows while maintaining the tucked position','Press back up to the starting position by extending your arms','Maintain core engagement to keep the knees stable and tucked','Repeat the movement while keeping the same body position throughout']::text[],ARRAY['Keep knees consistently tucked toward the chest to maintain the chameleon position','Engage your core muscles to stabilize the unusual body position during the push-up','Maintain proper hand placement and wrist alignment to support the modified push-up angle','Focus on controlled movement rather than speed due to the challenging balance requirements','This exercise combines upper body strength with core stability and hip flexor engagement']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a97c208e-1c40-4410-b51a-a86e5cc37a04','Chameleon push up to mountain climbers','chameleon-push-up-to-mountain-climbers','Starting position: Begin in a standard push-up position with hands slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Perform a push-up, then immediately transition into mountain climbers by alternating bringing each knee toward the chest in a running motion before returning to the starting position.',ARRAY['Start in push-up position','Drive one knee toward chest','Quickly switch legs','Continue alternating at pace']::text[],ARRAY['Keep hips down (don''t pike)','Core stays engaged','Speed up for more cardio','Slow down for more control','Full body exercise']::text[],'chest','{}'::text[],'bodyweight','core',null,ARRAY['strength','cardio','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9225c7c5-66a0-42c5-8de4-866389741736','Chest and shoulder','chest-and-shoulder','Starting position: Sit on a mat with knees bent, feet flat on the floor, leaning back slightly with hands placed behind you for support. Execution: Hold this seated position while maintaining proper posture and breathing steadily.',ARRAY['Sit on a mat with your knees bent and feet flat on the floor','Place your hands behind you on the mat with fingers pointing away from your body','Lean back slightly while keeping your chest open and shoulders down','Engage your core muscles to maintain stability','Keep your feet firmly planted on the ground','Breathe steadily while holding the position']::text[],ARRAY['Keep your shoulders away from your ears to avoid tension','Engage your core throughout the exercise to protect your lower back','Maintain steady breathing rather than holding your breath','Keep your chest open and avoid rounding your shoulders forward','Place hands in a comfortable position that allows proper wrist alignment']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ee4ec1d3-6f4c-42bf-b338-ac175213a4e7','Chest Press Machine flat','chest-press-machine-flat-fc68fc','Starting position: Sit upright on the chest press machine with your back flat against the pad, feet planted on the floor, and grasp the handles at chest height with elbows bent. Execution: Press the handles forward until your arms are almost fully extended, squeezing your chest, then slowly return to the starting position under control.',ARRAY['Adjust the seat so the handles align with the middle of your chest and sit with your back against the pad.','Grip the handles firmly with a neutral or pronated grip and keep your elbows at chest level.','Press the handles forward smoothly until your arms are nearly straight without locking the elbows.','Squeeze your chest at the end of the movement, then slowly return the handles to the start.','Maintain steady breathing, exhaling on the press and inhaling on the return.']::text[],ARRAY['Keep your back and head against the pad throughout the movement.','Avoid fully locking out the elbows to maintain tension on the chest.','Control the return phase rather than letting the weight drop.','Keep your shoulders down and away from your ears.']::text[],'chest',ARRAY['front_deltoids','triceps','serratus_anterior']::text[],'machine','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','926f4125-2676-45a8-96ee-2b6ace422494','Chest Supported Row Machine','chest-supported-row-machine-19ed1d','Starting position: Sit on the machine with your chest firmly against the pad, feet planted on the platform, and grasp the handles with arms extended. Execution: Pull the handles toward your torso by driving your elbows back and squeezing your shoulder blades together, then slowly return to the starting position under control.',ARRAY['Sit down and adjust the seat so your chest rests against the support pad.','Grasp the handles with a neutral or overhand grip and extend your arms fully.','Pull the handles toward your torso by retracting your shoulder blades and driving your elbows back.','Squeeze your back muscles at the peak contraction.','Slowly release and return the handles to the starting position with control.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your chest pressed against the pad throughout the movement.','Initiate the pull with your back, not just your arms.','Avoid jerking or using momentum to move the weight.','Fully extend arms at the bottom for a complete range of motion.']::text[],'back',ARRAY['rear_deltoids','biceps','forearms']::text[],'machine','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e6bd8a96-cc6e-4805-bb2d-6755c9350dd9','Child_s pose -Lower back','childs-pose-lower-back','Starting position: Begin on your hands and knees in a tabletop position on the floor. Execution: Slowly sit back onto your heels while extending your arms forward and lowering your torso toward the ground, creating a gentle stretch through the lower back and hips.',ARRAY['Start in a tabletop position with hands directly under shoulders and knees under hips','Slowly shift your weight back, sitting your hips toward your heels','Extend your arms forward on the ground while lowering your chest and forehead toward the floor','Allow your lower back to gently round and relax into the stretch','Hold the position while breathing deeply and slowly','To exit, slowly roll up vertebra by vertebra back to the starting position']::text[],ARRAY['Keep your knees comfortably apart if you experience any knee discomfort or have a larger midsection','Focus on deep, relaxed breathing to enhance the stress-relieving benefits of this restorative pose','Avoid forcing the stretch - let gravity naturally deepen the position over time','If you cannot sit back on your heels, place a pillow or bolster between your calves and thighs for support','This pose should feel relaxing and never cause pain in the knees, hips, or lower back']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['stretching','cooldown']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a61479a9-fc68-4b4b-9e4d-2f65cd41defa','Child''s pose','childs-pose','Starting position: Begin on your hands and knees in a tabletop position on the floor. Execution: Sit back onto your heels while extending your arms forward and lowering your forehead toward the ground, creating a gentle stretch through your back and shoulders.',ARRAY['Kneel on the floor with big toes touching and knees apart.','Sit back on your heels.','Fold forward, extending your arms in front of you on the mat.','Rest your forehead on the floor and relax.']::text[],ARRAY['Breathe deeply into your back body.','Widen knees for more space if needed.','This is a resting pose - relax completely.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching','cooldown']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ea7d466a-ecd9-4fcb-9a52-53716b513417','Chin-Up (Underhand)','chin-up-underhand-26410f','Starting position: Hang from a pull-up bar with underhand grip, arms fully extended. Execution: Pull your body upward until chin clears the bar, then lower with control.',ARRAY['Grip the bar with palms facing toward you','Hang with arms fully extended and shoulders engaged','Pull your body up until chin passes the bar','Squeeze shoulder blades together at the top','Lower yourself slowly to starting position']::text[],ARRAY['Keep your core tight throughout the entire movement','Avoid swinging or using momentum to complete reps','Focus on pulling with your back muscles rather than just arms','Don''t let shoulders roll forward at the bottom position']::text[],'bodyweight',ARRAY['biceps_long_head','brachialis','lower_traps','core']::text[],'bodyweight','strength','intermediate','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d48bc33d-8daa-456a-9f07-32b42a3798e5','Clams side lying with knee lifts','clams-side-lying-with-knee-lifts-aceab1','Starting position: Lie on your side with your head resting on your extended lower arm, hips and knees stacked and bent to about 45 degrees, with the top hand supporting on the mat or thigh. Execution: Keeping your feet together, rotate the top knee upward like a clam opening, then lift the top leg as a knee raise, control the movement back down, and repeat.',ARRAY['Lie on your side with legs stacked and knees bent to roughly 45 degrees, keeping your spine long.','Brace your core and keep your feet together as you rotate the top knee open toward the ceiling.','Lift the top knee further into a controlled knee lift, squeezing the outer hip and glute.','Pause briefly at the top without rolling your hips backward.','Lower the knee slowly back to the starting position with control.','Complete all reps, then switch to the other side.']::text[],ARRAY['Keep your hips stacked vertically and avoid rocking backward as the knee opens.','Move slowly and with control rather than using momentum.','Keep your core engaged to stabilize the pelvis throughout.','Feel the effort in the outer hip and glute, not the lower back.']::text[],'glute_med',ARRAY['glute_max','hip_flexors','obliques','abductors']::text[],'bodyweight','pilates','beginner',ARRAY['strength','core','rehabilitation']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','705b3080-cf01-42f4-be0f-ea9e3f83599f','Close Grip Bench Barbell','close-grip-bench-barbell','Starting position: Lie flat on a bench with feet firmly planted on the floor, gripping the barbell with hands positioned closer than shoulder-width apart, typically 6-12 inches between hands. Execution: Lower the barbell in a controlled manner to the lower chest while keeping elbows close to your sides, then press the weight back up by extending your arms through your triceps.',ARRAY['Position yourself on the bench with a narrow grip on the barbell, hands closer than shoulder-width apart','Keep your core engaged and feet flat on the floor for stability','Lower the barbell slowly to your lower chest or upper abdomen while keeping elbows tucked close to your sides','Pause briefly at the bottom position without bouncing the bar off your chest','Press the barbell back up by extending through your triceps until arms are fully extended','Maintain control throughout the entire range of motion']::text[],ARRAY['Keep elbows close to your body throughout the movement to maximize triceps engagement and reduce shoulder stress','Use a grip width that feels comfortable but narrow enough to target the triceps effectively','Control the descent and avoid bouncing the bar off your chest','Start with lighter weight than regular bench press as this variation is more challenging for the triceps','Ensure proper warm-up of shoulders, elbows, and wrists before performing this exercise']::text[],'triceps',ARRAY['pectoralis_major','front_deltoids','forearms']::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4668a912-ef55-4b3e-8d9c-53359d6aba29','Close Grip Dumbbell Press','close-grip-dumbbell-press','Starting position: Lie on a flat bench with a dumbbell in each hand, palms facing each other. Execution: Push dumbbells up from chest until arms are fully extended, then lower slowly to starting position.',ARRAY['Lie flat on a bench with feet firmly planted on the floor','Hold dumbbells with a neutral grip, positioning them close together above your chest with arms fully extended','Keep your core engaged and maintain a slight arch in your lower back','Lower the dumbbells slowly toward the center of your chest, keeping elbows tucked close to your sides','Press the dumbbells back up to starting position following the same path','Maintain control throughout the entire range of motion']::text[],ARRAY['Keep elbows closer to your body compared to regular dumbbell press to emphasize triceps and inner chest','Maintain constant tension by keeping the dumbbells close together throughout the movement','Use a controlled tempo with a 2-3 second lowering phase for optimal muscle activation','Start with lighter weight than your regular dumbbell press as this variation is more challenging','Avoid letting the dumbbells drift apart during the movement to maintain proper form']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d18679b0-3ce0-409b-9955-584976544f45','Close Grip Incline Dumbbell Press','close-grip-incline-dumbbell-press','Starting position: Lie on an incline bench with a dumbbell in each hand, arms extended upward with palms facing each other. Execution: Lower the dumbbells to your chest while keeping your elbows close to your torso, then press upward to return to starting position.',ARRAY['Set the incline bench to a 30-45 degree angle and lie back with your head, shoulders, and glutes firmly pressed against the pad','Hold dumbbells with a neutral grip, positioning them close together above your chest with arms fully extended','Slowly lower the dumbbells toward the center of your chest, keeping them close together throughout the descent','Pause briefly when the dumbbells reach chest level, feeling a stretch in your chest muscles','Press the dumbbells back up along the same path, focusing on squeezing your chest muscles at the top','Maintain control throughout the entire range of motion and avoid letting the dumbbells drift apart']::text[],ARRAY['Keep the dumbbells close together throughout the entire movement to maximize inner chest activation','Maintain a neutral spine and avoid arching your back excessively during the press','Control the eccentric (lowering) portion of the lift to maximize muscle tension and prevent injury','Focus on squeezing your chest muscles at the top of each repetition for optimal muscle engagement','Keep your feet flat on the floor and core engaged for stability throughout the exercise']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','10a31695-e218-4819-b7d3-b67b1b5ac79d','Close Grip Lat Pulldown','close-grip-lat-pulldown','Starting position: Sit at a lat pulldown machine with a pronated grip and hands separated at shoulder width. Execution: Pull the bar toward your chest, keeping your elbows close to your body, then slowly return to the starting position.',ARRAY['Sit at the lat pulldown machine with your thighs secured under the pads and feet flat on the floor','Grasp the bar with an overhand grip, hands positioned about shoulder-width apart or slightly narrower','Lean back slightly and pull your shoulder blades down and together to engage your lats','Pull the bar down smoothly toward your upper chest while keeping your elbows close to your body','Squeeze your back muscles at the bottom of the movement, then slowly return the bar to the starting position with control']::text[],ARRAY['Keep your core engaged throughout the movement to maintain proper posture','Avoid using momentum or swinging your torso to pull the weight','Focus on pulling with your back muscles rather than your arms','Don''t allow the weight to slam back up between repetitions']::text[],'back','{}'::text[],'cable','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1e99855d-fbf5-433e-9273-6f4e318a6ffe','Close Grip Lat Pulldown','close-grip-lat-pulldown-1e99855d','Starting position: Sit at a lat pulldown machine with a close grip and hands in a supinated grip (palms facing up). Execution: Pull the bar down to your chest while keeping your torso upright, then slowly return to starting position.',ARRAY['Adjust the knee pad to secure your thighs and prevent your body from lifting during the movement','Grasp the bar with an overhand grip, hands positioned slightly closer than shoulder-width apart','Sit tall with your chest up, shoulders back, and core engaged throughout the exercise','Pull the bar down smoothly toward your upper chest while squeezing your shoulder blades together','Focus on driving your elbows down and back rather than just pulling with your arms','Control the weight back to the starting position, maintaining tension in your lats']::text[],ARRAY['Keep your torso upright and avoid leaning back excessively to prevent lower back strain','Focus on initiating the movement with your lats rather than your biceps by thinking about pulling your elbows down','Maintain a controlled tempo, especially during the eccentric (returning) phase of the movement','Avoid pulling the bar behind your neck as this can cause shoulder impingement','Stop the bar at chest level rather than pulling it to your lap to maintain proper lat engagement']::text[],'back','{}'::text[],'cable','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5ce18079-7df5-48e0-828e-63005b8eb3d1','Close Grip Lat Pulldown to Waist','close-grip-lat-pulldown-to-waist','Starting position: Sit at a lat pulldown machine with a close grip and hands in a supinated grip (palms facing up). Execution: Pull the handle toward your waist while keeping your torso upright, then slowly return to the starting position.',ARRAY['Adjust the knee pad to secure your legs and prevent your body from lifting during the exercise','Grasp the bar with hands positioned closer than shoulder-width apart using an overhand grip','Sit upright with your chest out and shoulders pulled back to establish proper posture','Pull the bar down smoothly to your waist while leaning back slightly and squeezing your shoulder blades together','Hold the contraction briefly at the bottom position','Slowly return the bar to the starting position with control, allowing your arms to fully extend']::text[],ARRAY['Keep your chest up and avoid rounding your shoulders forward throughout the entire movement','Focus on pulling with your back muscles rather than just your arms by initiating the movement with your shoulder blades','Maintain a slight backward lean to optimize the pulling angle and target the lower portion of the latissimus dorsi','Control the weight on both the pulling and returning phases to maximize muscle engagement and prevent injury','Avoid using momentum or swinging your torso to complete the repetition']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','10d2c91e-60e8-416d-8c91-def45954009c','Close Grip Plate Press','close-grip-plate-press','Starting position: Sit on a bench holding a weight plate with both hands using a close grip, arms extended in front of your chest. Execution: Lower the plate toward your chest by bending your elbows, then press it back to the starting position by extending your arms.',ARRAY['Sit upright on a bench with your back supported and feet planted firmly on the floor','Grip the weight plate with both hands using your palms, keeping your hands close together','Start with arms extended in front of your chest, holding the plate securely','Lower the plate slowly toward your chest by bending your elbows outward','Press the plate back up to the starting position by straightening your arms','Maintain control throughout the entire range of motion']::text[],ARRAY['Keep your core engaged and maintain good posture throughout the movement','Use a secure grip on the plate to prevent it from slipping','Focus on squeezing your chest muscles as you press the weight up','Keep your elbows at a controlled angle rather than flaring them too wide','Start with a lighter weight to master the form before progressing']::text[],'chest','{}'::text[],'barbell','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bb30b96e-da77-44d7-aabe-d02a7bdcaa23','Cobbler''s pose','cobblers-pose','Starting position: Sit on the floor with your knees bent and the soles of your feet pressed together, allowing your knees to fall out to the sides. Execution: Gently hold your feet with your hands and lean forward from your hips while keeping your spine straight, feeling a stretch through your hips and glutes.',ARRAY['Sit on the floor with the soles of your feet together.','Let your knees drop open to the sides.','Hold your feet or ankles with your hands.','Sit tall, lengthening your spine.']::text[],ARRAY['Do not force your knees down.','Sit on a cushion if your hips are tight.','Keep your spine long and shoulders relaxed.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1e381fba-eedc-410c-ba1f-1c9c255f4d0f','Cobra pose','cobra-pose','Starting position: Lie face down on the floor with your palms flat on the ground directly under your shoulders, legs extended straight behind you. Execution: Press through your palms to lift your chest and upper torso off the ground while keeping your hips in contact with the floor, creating a gentle backbend through your spine.',ARRAY['Lie face down with hands under your shoulders.','Press your pelvis and legs into the floor.','Inhale and straighten your arms to lift your chest.','Keep a slight bend in the elbows.']::text[],ARRAY['Do not push up too high - keep it comfortable.','Roll your shoulders back and down.','Engage your back muscles, not just your arms.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','22880d49-67f2-4f14-9510-046c32da166b','Concentration Curl','concentration-curl','Starting position: Sit on a bench with a dumbbell in one hand, resting your arm against the inside of your thigh. Execution: Curl your elbow to lift the dumbbell toward your shoulder, then lower slowly.',ARRAY['Sit on the edge of a bench with your feet planted firmly on the floor about shoulder-width apart','Hold a dumbbell in your working hand with an underhand grip and let your arm hang straight down','Place the back of your upper arm against the inside of your thigh on the same side, just above the knee','Slowly curl the weight up by contracting your bicep, focusing on squeezing at the top of the movement','Lower the dumbbell back down in a controlled manner until your arm is nearly straight','Complete all repetitions on one arm before switching to the other side']::text[],ARRAY['Keep your upper arm pressed firmly against your thigh throughout the entire movement to isolate the bicep','Focus on slow, controlled movements rather than using momentum to lift the weight','Avoid fully locking out your elbow at the bottom to maintain constant tension on the muscle','Breathe out during the lifting phase and breathe in during the lowering phase','Choose a weight that allows you to maintain proper form for all repetitions']::text[],'biceps','{}'::text[],'dumbbell','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','372da9df-3ee6-450c-ae97-743968d27d71','Concentration Hammer Curl','concentration-hammer-curl','Starting position: Sit on a bench with a dumbbell in one hand and your arm resting on your thigh. Execution: Flex your elbow to lift the dumbbell toward your shoulder, then lower in a controlled manner.',ARRAY['Sit on the edge of a bench with your feet firmly planted on the floor about shoulder-width apart','Hold a dumbbell in one hand with a neutral grip, palm facing inward','Rest your working arm''s elbow against the inside of your same-side thigh for support','Curl the weight up in a controlled motion, focusing on contracting the bicep','Squeeze at the top of the movement, then slowly lower the dumbbell back to the starting position','Complete all repetitions on one arm before switching to the other side']::text[],ARRAY['Keep your wrist in a neutral position throughout the entire movement to avoid strain','Focus on slow, controlled movements rather than using momentum to lift the weight','Maintain the elbow position against your thigh to isolate the bicep and prevent swinging','Don''t allow your shoulder to roll forward during the curl - keep your chest up and shoulders back','Breathe out during the lifting phase and breathe in during the lowering phase']::text[],'biceps','{}'::text[],'dumbbell','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','658fa4e6-8b1d-48f4-b97d-7c576783ad73','Corpse pose','corpse-pose','Starting position: Lie flat on your back with legs slightly apart, arms at your sides with palms facing up, and eyes closed. Execution: Remain completely still while focusing on deep, natural breathing and progressive muscle relaxation throughout the entire body.',ARRAY['Lie flat on your back with legs extended and arms at your sides.','Let your feet fall open naturally.','Close your eyes and relax every part of your body.','Breathe naturally and stay for 5-10 minutes.']::text[],ARRAY['Release all muscular effort.','Let your breath return to its natural rhythm.','This is the most important pose for integration and relaxation.']::text[],'full_body','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','cooldown']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','513d039d-e6d0-459e-9ae7-4847a586871b','Cow face pose (left)','cow-face-pose-left','Starting position: Sit with legs crossed or in a comfortable position, bring your left arm overhead and bend at the elbow, reaching your left hand down your back. Execution: Reach your right arm behind your back from below, attempting to clasp your hands together while maintaining an upright posture.',ARRAY['Sit on the floor and stack your knees on top of each other.','Reach one arm overhead and bend it behind your back.','Reach the other arm behind your back from below.','Clasp your fingers or use a strap between your hands.']::text[],ARRAY['Sit evenly on both sit bones.','Keep your spine tall and chest lifted.','Use a strap if your hands do not reach.']::text[],'shoulders','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4d433881-e521-45e3-a36e-8672953714c0','Cow face pose (right)','cow-face-pose-right','Starting position: Kneel on the mat with your legs positioned to one side, sitting back on your heels. Execution: Reach your right arm up and bend it behind your head while bringing your left arm behind your back, attempting to clasp your hands together behind your torso.',ARRAY['Kneel on your mat and position your legs to one side, sitting back comfortably','Raise your right arm straight up toward the ceiling','Bend your right elbow and reach your right hand down behind your head toward your upper back','Bring your left arm behind your back and reach your left hand up toward your right hand','Attempt to clasp your hands together behind your back, or use a strap if needed','Hold the position while breathing steadily, then slowly release']::text[],ARRAY['Keep your spine straight and avoid leaning forward during the stretch','Don''t force your hands to touch if flexibility doesn''t allow it - use a towel or strap as assistance','Focus on lifting through the crown of your head to maintain good posture','Breathe deeply throughout the hold to help deepen the shoulder stretch','Switch sides to ensure balanced flexibility development']::text[],'shoulders','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3d8fe08e-93ba-49ac-b5f9-92dbac0d39b2','Cow pose','cow-pose','Starting position: Begin on your hands and knees in a tabletop position with wrists directly under shoulders and knees under hips. Execution: Gently arch your back by dropping your belly toward the floor while lifting your chest and tailbone toward the ceiling.',ARRAY['Start on all fours with wrists under shoulders and knees under hips.','Inhale, drop your belly toward the mat.','Lift your chest and tailbone toward the ceiling.','Hold for a few breaths, then release.']::text[],ARRAY['Keep arms straight throughout.','Broaden your chest and collarbones.','Initiate the movement from your pelvis.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fd93f455-3544-4c89-afa2-bcdf980aa53d','Crab hold to to taps','crab-hold-to-to-taps','Starting position: Begin in a deep squat position with feet shoulder-width apart, arms extended forward for balance. Execution: Hold the squat position while performing alternating toe taps or small movements to engage the core and maintain stability.',ARRAY['Start in a deep squat with thighs parallel to the floor and arms extended forward','Keep your chest up and core engaged throughout the movement','Maintain your weight evenly distributed across both feet','Hold the squat position while performing small controlled movements or toe taps','Keep your knees tracking over your toes and avoid letting them cave inward','Breathe steadily while maintaining the squat hold']::text[],ARRAY['Keep your core tight and engaged to maintain proper posture during the hold','Ensure your knees stay aligned with your toes and don''t collapse inward','Maintain steady breathing even while holding the challenging squat position','Keep your chest lifted and avoid rounding your back forward','Focus on controlled movements rather than speed when performing any additional motions']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1abe4475-eab9-4532-a583-68cc06681462','Crab hold toe tap','crab-hold-toe-tap','Starting position: Begin in a deep squat position with feet shoulder-width apart, arms extended forward for balance, and weight on your heels. Execution: Maintain the squat position while alternately lifting one foot to tap the toe forward, then return to starting position and repeat with the other foot.',ARRAY['Start in a deep squat with thighs parallel to the floor and arms extended forward','Keep your weight on your heels and maintain proper squat form throughout','Lift one foot and extend it forward to tap the toe on the ground','Return the foot to starting position while staying in the squat','Repeat the toe tap with the opposite foot','Continue alternating feet while holding the squat position']::text[],ARRAY['Keep your chest up and back straight to maintain proper posture','Engage your core muscles to help stabilize your body during the movement','Focus on keeping most of your weight on the supporting leg''s heel','Control the toe tap movement - don''t rush or lose balance','Maintain the squat depth consistently throughout all repetitions']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d7078f6a-a0eb-47e6-9396-98b250afff34','Crab Walk','crab-walk-6fdc31','Starting position: Sit on the floor with your knees bent, feet flat, and hands placed behind you with fingers pointing toward your body. Lift your hips off the ground so your weight is supported on hands and feet in a reverse tabletop position. Execution: Move forward and backward by simultaneously stepping with opposite hand and foot, keeping your hips elevated throughout the movement.',ARRAY['Sit on the floor and place your hands behind you with fingers facing your body, feet flat and knees bent.','Lift your hips off the floor to create a stable tabletop position balancing on hands and feet.','Step forward by moving your right hand and left foot, then your left hand and right foot.','Continue crawling in a coordinated crab-like pattern, then reverse direction backward.','Keep your hips elevated and core braced throughout the entire movement.']::text[],ARRAY['Keep your hips lifted and avoid letting your glutes sag toward the floor.','Point your fingers toward your body to protect your wrists and engage your triceps.','Move opposite hand and foot together for smooth coordination.','Maintain a braced core and neutral neck throughout.']::text[],'glutes',ARRAY['front_deltoids','calves','hip_flexors']::text[],'bodyweight','cardio','beginner',ARRAY['cardio','functional','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','85a71ed6-caf0-4b0c-aa70-0419d8f81157','Crab walk to squat','crab-walk-to-squat','Starting position: Begin in a crab walk position with hands planted behind you, knees bent, and hips lifted off the ground. Execution: Walk laterally in the crab position for several steps, then transition into a deep squat position before returning to crab walk.',ARRAY['Start in crab position with hands behind you, fingers pointing toward your feet, knees bent and hips elevated','Keep your core engaged and maintain a straight line from knees to shoulders throughout the crab walk','Take 3-4 steps laterally while maintaining proper crab form and keeping hips up','Transition smoothly by bringing feet together and rotating to face forward','Lower into a deep squat with chest up, knees tracking over toes, and weight in your heels','Return to crab position and repeat the sequence in the opposite direction']::text[],ARRAY['Keep wrists directly under shoulders and avoid letting hips sag during the crab walk portion','Maintain control during the transition between crab walk and squat to prevent injury','Focus on proper squat depth with thighs parallel to the ground while keeping knees aligned with toes','Engage your glutes and quads throughout both movements for maximum muscle activation','Start with shorter distances and fewer repetitions until you build strength and coordination']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['functional','strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','10be21b8-de6f-4c33-9101-eadca351e663','Crab walks into squats','crab-walks-into-squats','Starting position: Begin in a crab walk position with hands planted behind you, fingers pointing toward your feet, knees bent and hips lifted off the ground. Execution: Walk sideways in the crab position for 3-4 steps, then transition into a standing position and immediately perform a bodyweight squat before returning to crab position.',ARRAY['Start in a crab position with hands planted behind you, fingers pointing away from your body, and feet flat on the ground with knees bent','Engage your core and lift your hips off the ground, supporting your weight on your hands and feet','Take small steps sideways while maintaining the crab position, moving your opposite hand and foot together','After taking several lateral steps, lower your hips and transition to standing by bringing your feet together','Immediately perform a bodyweight squat by pushing your hips back, bending your knees, and lowering until your thighs are parallel to the ground','Return to standing and repeat the sequence by going back into crab position for the next set']::text[],ARRAY['Keep your hips elevated throughout the crab walk portion to maximize glute and core engagement','Maintain proper squat form with knees tracking over your toes and weight in your heels','Take controlled steps during the crab walk rather than rushing through the movement','Keep your wrists strong and shoulders engaged to protect your joints during the crab position']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['functional','strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8dcf57f2-24d8-4f4d-802c-2eacbe9d578f','Crescent lunge (left)','crescent-lunge-left','Starting position: Stand tall, then step your left foot forward into a long lunge position with your right knee hovering just above the ground and arms at your sides. Execution: Hold this static position while engaging your left quadriceps to support your body weight, maintaining proper alignment throughout the hold.',ARRAY['From a standing position, step one foot back into a lunge.','Bend your front knee to 90 degrees over the ankle.','Raise your arms overhead with palms facing each other.','Lift your chest and gaze forward or slightly up.']::text[],ARRAY['Keep your front knee aligned over the ankle.','Engage your back leg and press through the ball of the back foot.','Square your hips toward the front of the mat.']::text[],'quads','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','strength','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','db4a932d-2e11-4809-843e-cb3c1df4535b','Crescent lunge (right)','crescent-lunge-right','Starting position: Stand in a deep lunge position with right foot forward, left leg extended back, and arms raised overhead. Execution: Hold this static position while maintaining proper alignment and breathing steadily.',ARRAY['Step your right foot forward into a deep lunge position with your knee directly over your ankle','Extend your left leg straight back, keeping the back heel lifted and leg active','Raise both arms straight up overhead with palms facing each other','Keep your torso upright and engage your core muscles','Hold the position while breathing deeply and maintaining balance','Focus on sinking deeper into the lunge while keeping proper form']::text[],ARRAY['Keep your front knee aligned over your ankle, not pushing forward past your toes','Maintain an upright torso rather than leaning forward over your front leg','Engage your back leg and keep it straight to create stability and activate the hip flexors','Press through your front heel and keep your weight evenly distributed','Keep your arms active and reaching upward to enhance the stretch through your torso']::text[],'quads','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','strength','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0e43c62b-bcf6-4115-8fa4-3049a4d8f24a','Criss-cross jumping jacks','criss-cross-jumping-jacks','Starting position: Stand upright with feet together and arms at your sides. Execution: Jump while crossing one leg in front of the other and simultaneously crossing your arms in front of your chest, then jump back to starting position and repeat on the opposite side.',ARRAY['Start standing with feet hip-width apart, arms at your sides','Jump up while simultaneously crossing your right leg in front of your left leg and bringing your arms overhead in an X-pattern (right arm crosses over left)','Jump back to the starting position with feet hip-width apart and arms at your sides','Jump up again, this time crossing your left leg in front of your right leg and crossing your left arm over your right arm overhead','Continue alternating the crossing pattern with both legs and arms in a rhythmic jumping motion','Land softly on the balls of your feet with slightly bent knees throughout the movement']::text[],ARRAY['Keep your core engaged throughout to maintain balance and stability','Land with bent knees to absorb impact and protect your joints','Maintain an upright posture with your chest up and shoulders back','Start at a slower pace to master the coordination before increasing speed','Stop if you feel dizzy or lose proper form']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup','plyometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b8fb88dc-d819-4e65-86c8-7ea13703afdb','Cross Body Hammer Curl','cross-body-hammer-curl','Starting position: Stand upright with feet shoulder-width apart, arms at your sides in a neutral grip position as if holding dumbbells. Execution: Curl one arm across your body toward the opposite shoulder while maintaining a hammer grip position, then lower with control and repeat on the other side.',ARRAY['Stand with feet shoulder-width apart, core engaged, and maintain good posture throughout','Position your arms at your sides with palms facing your body in a neutral hammer grip position','Curl your right arm up and across your body toward your left shoulder, keeping your elbow close to your torso','Squeeze your bicep at the top of the movement and hold for a brief pause','Lower your arm slowly back to the starting position with control','Repeat the movement with your left arm crossing toward your right shoulder']::text[],ARRAY['Keep your core tight and avoid swaying or using momentum to complete the movement','Maintain the neutral hammer grip position throughout the entire range of motion','Focus on the cross-body motion to engage the biceps from a different angle than traditional curls','Control both the lifting and lowering phases of the movement for maximum muscle engagement','Keep your shoulders stable and avoid rolling them forward during the exercise']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6362bdab-a7d7-49e8-85ab-fe1eb610cb4e','Cross body pulls to hamstring kicks','cross-body-pulls-to-hamstring-kicks','Starting position: Stand tall with feet hip-width apart, arms extended out to the sides at shoulder height. Execution: Cross one arm across your body while simultaneously lifting the opposite leg behind you in a hamstring kick, then return to starting position and repeat on the other side.',ARRAY['Stand with feet hip-width apart and extend both arms out to the sides at shoulder height','Cross your right arm across your body toward your left side while keeping it straight','Simultaneously kick your left leg back behind you, bending at the knee to bring your heel toward your glutes','Return your arm and leg to the starting position in a controlled manner','Repeat the movement on the opposite side, crossing your left arm while kicking back with your right leg','Continue alternating sides for the desired number of repetitions']::text[],ARRAY['Keep your core engaged throughout the movement to maintain balance and stability','Focus on controlled movements rather than speed to maximize hamstring activation','Maintain an upright torso and avoid leaning forward when performing the hamstring kick','Keep the standing leg slightly bent to improve balance and reduce knee stress','Squeeze your glutes at the top of each hamstring kick for additional muscle activation']::text[],'hamstrings','{}'::text[],'bodyweight','legs','intermediate',ARRAY['functional','mobility','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','068d316f-52b0-4438-a7c9-ee21ceca2c2f','Crunches','crunches','Starting position: Lie on your back with knees bent, feet flat on the floor, and hands placed lightly behind your head or crossed over your chest. Execution: Lift your shoulder blades off the ground by contracting your abdominal muscles, then slowly lower back down with control.',ARRAY['Lie on your back with knees bent at 90 degrees, feet flat on the floor hip-width apart','Place your hands lightly behind your head with elbows wide, or cross arms over your chest','Engage your core and slowly lift your shoulder blades off the ground, curling your upper body toward your knees','Hold briefly at the top, feeling the contraction in your abs','Slowly lower back down with control until your shoulder blades lightly touch the floor','Repeat for desired repetitions while maintaining steady breathing']::text[],ARRAY['Keep your lower back pressed into the floor throughout the movement','Avoid pulling on your neck with your hands - let your abs do the work','Focus on quality over quantity - slow, controlled movements are more effective','Keep your chin slightly tucked and maintain a small gap between chin and chest','Stop if you feel any neck or lower back pain']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['core','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5f84b3d2-daff-4fc1-bb8c-c9524689af7d','Cuads Belt Squat Machine','cuads-belt-squat-machine-a1210a','Starting position: Stand on the belt squat machine platform with the loaded belt secured around your hips, feet shoulder-width apart, and hands lightly grasping the front support bar for balance. Execution: Lower your hips down and back into a squat by bending your knees and hips, then drive through your heels to return to standing, keeping tension on the quadriceps throughout.',ARRAY['Secure the weighted belt around your hips and position your feet shoulder-width apart on the platform.','Grip the front support bar lightly for balance and brace your core.','Lower your hips down and back by bending the knees until thighs are near parallel.','Drive through your heels and extend the knees and hips to return to standing.','Maintain an upright torso and controlled tempo throughout the set.']::text[],ARRAY['Keep your chest up and spine neutral, avoiding excessive forward lean.','Push your knees out in line with your toes as you descend.','Drive through the heels and midfoot, not the toes.','Use the handle only for balance, not to pull yourself up.']::text[],'quads',ARRAY['glutes','hamstrings','adductors','core']::text[],'machine','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b3d44ba8-5fdd-4a7e-ace2-1b12d5901b0b','Cuban Press','cuban-press','Starting position: Stand with feet shoulder-width apart, arms extended out to sides at shoulder height with palms facing down. Execution: Rotate your arms upward so palms face forward, then press arms overhead, reverse the movement by lowering arms back to shoulder height and rotating palms back down.',ARRAY['Stand tall with core engaged and feet planted firmly on the ground','Extend arms out to sides at shoulder height with palms facing down','Slowly rotate your arms so palms face forward while keeping arms at shoulder level','Press both arms straight up overhead while maintaining palm-forward position','Lower arms back to shoulder height with controlled movement','Rotate palms back to face down position to complete one repetition']::text[],ARRAY['Keep shoulders pulled back and down throughout the entire movement to avoid impingement','Move slowly and deliberately through each phase to maximize shoulder stability benefits','Maintain neutral spine and avoid arching your back when pressing overhead','Stop immediately if you feel any sharp pain or discomfort in the shoulder joint','Focus on smooth transitions between each position rather than rushing through the movement']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ea1016da-2d73-4ff8-ad2a-9b36150d2f85','Dead Bug','dead-bug-5419c7','Starting position: Lie on back with arms extended toward ceiling and knees bent at 90 degrees. Execution: Slowly extend opposite arm and leg while maintaining core stability.',ARRAY['Lie on back with arms reaching toward ceiling','Bend knees to 90 degrees with shins parallel','Slowly lower right arm overhead while extending left leg','Return to starting position with control','Repeat with opposite arm and leg','Continue alternating sides for desired repetitions']::text[],ARRAY['Keep lower back pressed firmly against the floor throughout','Move slowly and with control to maximize core engagement','Stop immediately if you feel lower back arching','Breathe out as you extend limbs, inhale as you return']::text[],'bodyweight','{}'::text[],'bodyweight',null,null,'{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7c9e7503-35f4-4dd3-a515-3b7ad96e21da','Dead Bug with Dumbbells','dead-bug-with-dumbbells-cadc7a','Starting position: Lie flat on your back on a mat holding a dumbbell in each hand, arms extended straight up toward the ceiling, and legs raised into a tabletop position with knees bent at 90 degrees. Execution: Bracing your core, lower one arm and the opposite leg toward the floor simultaneously, keeping your lower back pressed into the mat, then return to the start and alternate sides.',ARRAY['Lie on your back holding dumbbells with arms extended straight above your chest.','Lift your legs so hips and knees are bent at 90 degrees in tabletop position.','Slowly extend one leg out and lower the opposite arm overhead toward the floor.','Keep your lower back flat against the mat throughout the movement.','Return the arm and leg to the starting position under control.','Alternate sides for the desired number of repetitions.']::text[],ARRAY['Keep your lower back pressed into the mat to protect the spine.','Move slowly and with control rather than using momentum.','Exhale as you extend the limbs and brace the abs tightly.','Only lower the limbs as far as you can maintain core stability.']::text[],'core',ARRAY['hip_flexors','front_deltoids','obliques']::text[],'dumbbell','core','intermediate',ARRAY['core','strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8f2f2d63-4e39-408b-b450-f88c27d8ae1a','Deadlift with Kettlebell','deadlift-with-kettlebell','Starting position: Stand with feet hip-width apart, kettlebell placed on the floor between your feet, and hinge at the hips to reach down and grip the kettlebell handle with both hands. Execution: Drive through your heels and extend your hips and knees simultaneously to lift the kettlebell up to standing position, then reverse the movement to lower it back down with control.',ARRAY['Position feet hip-width apart with the kettlebell centered between your feet','Hinge at the hips by pushing your hips back and bending your knees to reach the kettlebell','Grip the kettlebell handle firmly with both hands using an overhand grip','Keep your chest up, shoulders back, and maintain a neutral spine throughout the movement','Drive through your heels and squeeze your glutes to return to standing position','Lower the kettlebell back down by reversing the hip hinge movement with control']::text[],ARRAY['Keep the kettlebell close to your body throughout the entire movement','Initiate the movement from your hips, not your knees or back','Maintain a neutral spine and avoid rounding your back during the lift','Focus on hip extension and glute activation at the top of the movement','Control the descent - don''t just drop the weight down']::text[],'full_body',ARRAY['adductors','traps','calves']::text[],'kettlebell','core','beginner',ARRAY['strength','functional']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f67b5c4a-a959-4b13-933e-633d4faeab95','Deadstop push up','deadstop-push-up','Starting position: Begin in a standard push-up position with hands placed slightly wider than shoulder-width apart, body forming a straight line from head to heels. Execution: Lower your body until your chest touches the ground, pause completely for 1-2 seconds, then press back up to the starting position.',ARRAY['Position hands slightly wider than shoulder-width with fingers spread for stability','Lower your body in a controlled manner until your chest makes contact with the floor','Come to a complete stop on the ground for 1-2 seconds, removing all momentum','Press through your palms to push your body back to the starting position','Maintain a straight line from head to heels throughout the entire movement','Keep your core engaged and avoid letting your hips sag or pike upward']::text[],ARRAY['The complete stop eliminates momentum and forces you to generate power from the bottom position','Keep your elbows at approximately a 45-degree angle from your torso to protect your shoulders','Focus on controlled movement rather than speed to maximize muscle engagement','If you cannot maintain proper form, modify by performing the exercise from your knees','Breathe in during the lowering phase and exhale forcefully when pushing up from the bottom']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e8a79472-7809-42d4-89cc-c3c351d86982','Deadstop push up into superman crunches','deadstop-push-up-into-superman-crunches','Starting position: Begin in a standard push-up position with hands slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Perform a push-up, pause briefly at the bottom with chest touching the ground, push back up, then immediately flip onto your back and perform a superman crunch by lifting your shoulders and legs simultaneously.',ARRAY['Start in a plank position with hands planted firmly on the ground and core engaged','Lower your body slowly until your chest touches the floor, maintaining a straight body line','Pause for 1-2 seconds at the bottom position with your chest on the ground','Push explosively back up to the starting position','Immediately roll onto your back and perform a superman crunch by lifting your shoulders and legs off the ground simultaneously','Return to the starting push-up position and repeat the sequence']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your lower back','Maintain proper push-up form with elbows at a 45-degree angle to your body','Control the transition between exercises to avoid injury and maintain proper form','Focus on quality over quantity - perform fewer reps with perfect technique rather than many with poor form','Breathe out during the exertion phase of both the push-up and the superman crunch']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','76741ca2-8960-4323-a495-c595291e3c56','Deadstop push ups','deadstop-push-ups','Starting position: Begin in a standard push-up position with hands placed slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Lower your chest completely to the floor, pause briefly while relaxing your hands and lifting them slightly off the ground, then press your hands back down and push up explosively to the starting position.',ARRAY['Set up in a standard push-up position with hands slightly wider than shoulders and body forming a straight line','Lower your body slowly and under control until your chest touches the floor','Once at the bottom, briefly lift your hands 1-2 inches off the ground while keeping your body rigid','Press your hands firmly back to the floor and push up explosively to return to starting position','Maintain proper body alignment throughout the entire movement','Rest briefly between repetitions to maintain form quality']::text[],ARRAY['The brief pause with hands lifted eliminates momentum and forces you to generate power from a complete stop','Keep your core engaged throughout to prevent sagging hips or arching your back excessively','This variation is significantly more challenging than regular push-ups, so reduce repetitions accordingly','Focus on explosive upward movement while maintaining control during the descent','Ensure full range of motion by actually touching your chest to the floor each repetition']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b9e7733d-fbba-413a-98d9-71803ae1edb4','Deadstop pushup to superman crunch','deadstop-pushup-to-superman-crunch','Starting position: Begin in a standard push-up position with hands placed shoulder-width apart, body in a straight line from head to heels. Execution: Perform a push-up, pause at the bottom with chest touching the ground, push back up, then immediately flip onto your back and perform a superman crunch by bringing knees to chest while lifting shoulders off the ground.',ARRAY['Start in a plank position with hands directly under shoulders and engage your core','Lower your body slowly until your chest touches the ground, maintaining a straight body line','Pause for one second at the bottom position with complete body contact to the floor','Push explosively back up to the starting plank position','Carefully roll onto your back and immediately bring your knees toward your chest while lifting your shoulders off the ground','Return to the starting push-up position and repeat the sequence']::text[],ARRAY['Keep your core engaged throughout both movements to protect your lower back','The dead stop eliminates momentum, making the push-up more challenging and effective','Focus on controlled movement during the transition from push-up to superman crunch','Maintain proper breathing by exhaling during the exertion phases of both exercises','Start with fewer repetitions until you master the coordination between both movements']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8796655f-6390-4ae1-a143-1fe6cde817cb','Decline Chest Press Machine','decline-chest-press-machine-f533ec','Starting position: Sit upright on the machine with your back flat against the pad and feet planted firmly on the floor. Grip the handles at chest level with elbows bent and pointing slightly downward. Execution: Press the handles forward and slightly downward until your arms are nearly extended, squeezing your chest, then slowly return to the start under control.',ARRAY['Adjust the seat so the handles align with your lower chest and sit with your back firmly against the pad.','Grasp the handles with a firm grip and keep your elbows slightly below shoulder height.','Press the handles forward and inward along a downward decline path until arms are nearly straight.','Squeeze your chest at full extension without locking the elbows.','Slowly return the handles to the starting position, keeping tension in the chest.','Repeat for the desired number of repetitions with controlled tempo.']::text[],ARRAY['Keep your back and shoulders pressed against the pad throughout the movement.','Avoid fully locking the elbows to maintain tension on the chest.','Control the eccentric phase rather than letting the weight snap back.','Exhale as you press, inhale as you return.']::text[],'chest',ARRAY['front_deltoids','triceps','serratus_anterior']::text[],'machine','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4c5c90fd-01a3-45f6-a952-712743be9c81','Decline Close Grip Dumbbell Press','decline-close-grip-dumbbell-press','Starting position: Lie on a decline bench with a dumbbell in each hand, arms extended upward with palms facing each other. Execution: Lower dumbbells toward chest keeping elbows close to torso, then push up to return to starting position.',ARRAY['Secure your feet firmly in the foot pads and adjust the decline bench to approximately 15-30 degrees','Hold dumbbells with a neutral grip, positioning them close together above your chest with arms extended','Lower the weights slowly toward your chest, keeping elbows tucked close to your sides rather than flaring them out','Pause briefly when the dumbbells reach chest level, feeling a stretch in your chest muscles','Press the dumbbells back up to starting position in a controlled motion, focusing on squeezing your chest muscles','Maintain constant tension throughout the movement and avoid locking out your elbows completely at the top']::text[],ARRAY['Keep your core engaged throughout the exercise to maintain stability on the decline bench','Focus on keeping the dumbbells close together and elbows tucked to maximize triceps and inner chest activation','Control the negative portion of the movement to prevent shoulder strain and maximize muscle engagement','Use a weight that allows you to maintain proper form throughout all repetitions rather than going too heavy','Ensure proper breathing by inhaling during the lowering phase and exhaling during the pressing phase']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','426861d9-64ac-40f6-bf3e-f7ebc05ba6af','Decline Push Up','decline-push-up-899f0b','Starting position: Assume a push-up position with your hands on the floor slightly wider than shoulder-width and your feet elevated on a plyo box, forming a straight line from head to heels. Execution: Lower your chest toward the floor by bending your elbows, then press back up to the starting position while keeping your core tight and body rigid.',ARRAY['Place your feet on the plyo box and set your hands on the floor slightly wider than shoulder-width apart.','Brace your core and maintain a straight line from head to heels.','Bend your elbows to lower your chest toward the floor in a controlled manner.','Descend until your chest is just above the ground.','Press through your palms to push your body back up to full arm extension.','Repeat for the desired number of repetitions without letting your hips sag.']::text[],ARRAY['Keep your body in a straight line and avoid sagging or piking your hips.','Lower under control and keep elbows at roughly a 45-degree angle to your torso.','Engage your core and glutes throughout to protect your lower back.','Do not let your head drop; keep your neck neutral.']::text[],'chest',ARRAY['triceps','front_deltoids','core']::text[],'box','strength','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8bbcc469-9283-4776-a12c-882060dd396c','Declined Push up - 56','declined-push-up-56','Starting position: Place your feet on an elevated surface (bench, step, or chair) and your hands on the ground in a plank position, creating a declined angle with your body. Execution: Lower your chest toward the ground by bending your elbows, then push back up to the starting position while maintaining the declined body angle.',ARRAY['Position your feet on a stable elevated surface that is 12-24 inches high','Place your hands on the ground slightly wider than shoulder-width apart with fingers spread','Create a straight line from your head to your heels in the declined plank position','Lower your chest toward the ground by bending your elbows at a 45-degree angle from your body','Push through your palms to return to the starting position while maintaining body alignment','Perform the movement in a controlled manner throughout the full range of motion']::text[],ARRAY['Ensure the elevated surface is stable and secure before beginning the exercise','Keep your core engaged throughout the movement to prevent your hips from sagging','The declined angle increases the difficulty and places greater emphasis on the upper chest muscles','Start with a lower elevation if you''re new to declined push-ups and gradually increase the height','Stop immediately if you experience any wrist, shoulder, or lower back discomfort']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ffef6f38-6074-43b9-9256-2edc78dcf698','Deficit Calf Raise','deficit-calf-raise-fac058','Starting position: Stand on a raised surface with heels hanging off the edge. Execution: Rise up onto toes then lower heels below platform level.',ARRAY['Stand on platform edge with balls of feet supported','Let heels drop below platform level to stretch calves','Rise up onto toes as high as possible','Squeeze calf muscles at the top position','Lower heels back down below platform slowly','Repeat the movement maintaining controlled tempo']::text[],ARRAY['Keep knees straight throughout the entire movement to properly target the gastrocnemius','Use a full range of motion by dropping heels well below the platform level','Rise onto toes as high as possible to maximize muscle contraction','Control the lowering phase to increase time under tension']::text[],'bodyweight','{}'::text[],'bodyweight',null,null,'{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9d5a2722-801b-4741-8d9b-11e9a3a4ae2d','Devil press','devil-press','Starting position: Stand with feet hip-width apart, holding a dumbbell in each hand at your sides. Execution: Drop into a burpee by placing the dumbbells on the ground, jump back into plank position, perform a push-up, jump feet back to dumbbells, then explosively lift the dumbbells overhead in one fluid motion.',ARRAY['Place dumbbells on the ground and jump or step back into a plank position with hands gripping the dumbbell handles','Perform a push-up while maintaining grip on the dumbbells, keeping core engaged','Jump or step feet back toward the dumbbells, landing in a low squat position','Explosively stand up while lifting the dumbbells from the ground to overhead in one smooth motion','Lower the dumbbells back to the starting position with control','Repeat the entire sequence for the prescribed number of repetitions']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your lower back','Use your hips and legs to generate power for the overhead lift portion, not just your arms','Maintain proper grip on the dumbbells throughout all phases of the movement','Land softly when jumping back and forth to reduce impact on joints','Start with lighter weight to master the complex movement pattern before progressing']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength','cardio','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2930d41f-177c-4f36-bd91-4867afb85a3b','Dips','dips','Starting position: Grip parallel bars or the edge of a sturdy bench with arms fully extended, supporting your body weight with feet off the ground or extended forward. Execution: Lower your body by bending your elbows until your shoulders drop below your elbows, then press back up to the starting position.',ARRAY['Grip parallel bars, arms straight','Lower body by bending elbows','Go until upper arms parallel or comfortable depth','Push up to starting position']::text[],ARRAY['Lean forward for more chest, upright for more triceps','Don''t go too deep (shoulder strain)','Control the descent','Full lockout at top','Add weight when bodyweight is easy']::text[],'chest','{}'::text[],'bodyweight','push',null,ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','60ec7728-577b-4dea-a5e9-4b8ac16b6038','Dips - Triceps Version','dips-triceps-version','Starting position: Sit on the floor with legs extended, hands placed on the ground beside your hips gripping a stable surface or handles, supporting your body weight on your arms. Execution: Lower your body by bending your elbows, then press back up to the starting position by straightening your arms.',ARRAY['Position yourself sitting on the floor with legs extended straight in front of you','Place your hands on the ground or grip handles beside your hips, fingers pointing forward','Support your body weight on your arms with shoulders directly over your hands','Lower your body by bending your elbows, keeping them close to your sides','Descend until you feel a stretch in your triceps or chest','Press through your palms to straighten your arms and return to starting position']::text[],ARRAY['Keep your core engaged throughout the movement to maintain proper posture','Control the descent - avoid dropping down too quickly','Keep your shoulders down and back, avoiding hunching forward','Focus on using your triceps and chest muscles rather than momentum','If too difficult, bend your knees or place feet on the ground for assistance']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fcc15585-b472-487f-8367-7459ee909832','Dips on bench','dips-on-bench','Starting position: Sit on the edge of a bench with hands gripping the edge beside your hips, legs extended forward with heels on the ground. Execution: Lower your body by bending your elbows until your upper arms are parallel to the floor, then push back up to the starting position.',ARRAY['Hands on bench behind you, legs extended','Lower body by bending elbows','Go until upper arms parallel to floor','Push up to start']::text[],ARRAY['Easier than parallel bar dips','Keep back close to bench','Don''t go too deep','Feet closer = easier, farther = harder','Tricep-focused movement']::text[],'back','{}'::text[],'bodyweight','pull',null,ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3add251e-6e58-4f80-902c-ab32e0b61966','Dips on bench 2','dips-on-bench-2','Starting position: Sit on the edge of a bench with hands gripping the bench beside your hips, legs extended forward with heels on the ground. Execution: Lower your body by bending your elbows until your upper arms are parallel to the floor, then push back up to the starting position.',ARRAY['Position hands firmly on the bench edge with fingers pointing forward and arms fully extended','Slide your body off the bench while keeping your back close to the bench edge','Lower your body slowly by bending your elbows, keeping them close to your sides','Descend until your upper arms are parallel to the floor or you feel a stretch in your chest','Push through your palms to raise your body back to the starting position','Maintain control throughout the entire range of motion']::text[],ARRAY['Keep your shoulders down and back to prevent shoulder impingement','Avoid letting your elbows flare out too wide to maintain focus on chest muscles','Stop the descent if you feel excessive strain in your shoulders','Bend your knees and place feet closer to the bench to make the exercise easier','Ensure the bench is stable and can support your full body weight before beginning']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','95640151-0b58-4872-94de-a14680227a66','Dips parallel bars','dips-parallel-bars-ab67c1','Starting position: Grip the parallel bars with arms fully extended, supporting your bodyweight, torso leaning slightly forward. Execution: Lower your body by bending the elbows until they reach roughly 90 degrees, then press back up to full extension while keeping the chest engaged.',ARRAY['Grasp the parallel bars and support your body with arms locked out.','Lean the torso slightly forward and keep the core braced.','Bend your elbows to lower the body under control until elbows reach about 90 degrees.','Press through the palms to extend the arms and return to the top.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep the torso leaning forward to emphasize the chest.','Avoid flaring the elbows excessively to protect the shoulders.','Lower with control and do not bounce at the bottom.','Keep the shoulders down and away from the ears throughout.']::text[],'lower_chest',ARRAY['triceps_long_head','front_deltoids','serratus_anterior']::text[],'machine','strength','intermediate',ARRAY['strength','calisthenics']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b219f35b-9bca-4eb5-a010-e0ded6208942','Dive bombers','dive-bombers','Starting position: Begin in a downward dog position with hands shoulder-width apart, feet hip-width apart, and hips raised high forming an inverted V-shape. Execution: Dive forward and down in a swooping motion, transitioning through a low push-up position, then arch your back and chest upward into an upward dog position before reversing the movement back to start.',ARRAY['Start in downward dog with straight arms and legs, creating a strong inverted V-shape with your body','Initiate the dive by shifting your weight forward and lowering your head toward the ground between your hands','Continue the swooping motion by bringing your chest low to the ground, similar to the bottom of a push-up','Push through your hands and arch your back to lift your chest and head up into upward dog position','Reverse the movement by tucking your chin and pushing your hips back up to return to the starting downward dog position','Maintain control throughout the entire fluid movement sequence']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back from hyperextension','Move slowly and controlled, especially when learning the movement pattern to avoid injury','Ensure adequate wrist mobility and strength before attempting, as this exercise places significant load on the wrists','Focus on the smooth, flowing transition between positions rather than rushing through the movement','Stop immediately if you experience any lower back pain and consider modifying the range of motion']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','mobility','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fbffd9c1-bffd-4fb0-ae4c-258834c5fcd2','Donkey Kick with Dumbbell','donkey-kick-with-dumbbell','Starting position: Get into a four-point position (hands and knees) on the floor with a dumbbell placed behind one knee. Execution: Lift your leg upward pushing the dumbbell toward the ceiling while keeping the knee bent, then slowly lower to the starting position and repeat with the other leg.',ARRAY['Position yourself on hands and knees with wrists under shoulders and knees under hips','Secure a light dumbbell behind one knee by bending your leg and gripping the weight between your hamstring and calf','Engage your core and maintain a neutral spine throughout the movement','Lift the leg with the dumbbell up and back, driving through your heel while keeping the knee bent','Squeeze your glute at the top of the movement, then slowly lower back to starting position','Complete all reps on one side before switching to the other leg']::text[],ARRAY['Keep your hips square and avoid rotating your pelvis during the movement','Focus on using your glute muscles rather than momentum to lift the weight','Maintain steady breathing and avoid holding your breath during the exercise','Start with a lighter weight to master the form before progressing to heavier dumbbells','Keep your supporting arm straight and avoid sagging through your lower back']::text[],'glutes','{}'::text[],'dumbbell','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','45c93c0a-c64e-4f27-a694-ab9fb396cd46','DOT Drill','dot-drill-454686','Starting position: Stand in an athletic stance with feet shoulder-width apart, knees slightly bent, hands up near the chest in a ready position, eyes focused on an imaginary dot pattern on the floor. Execution: Rapidly hop between designated dot positions, driving off the balls of your feet and landing softly with bent knees, changing direction quickly while keeping the core braced and staying light on your feet.',ARRAY['Set up in a low athletic stance with knees bent and weight on the balls of your feet.','Fix your gaze on the dot pattern and keep hands up near your chest for balance.','Explosively hop from one dot to the next, driving through your legs.','Land softly with knees bent to absorb impact and immediately rebound to the next position.','Maintain a quick tempo, following the sequence forward, backward, and diagonally.','Keep your core engaged and torso stable throughout the drill.']::text[],ARRAY['Stay on the balls of your feet to allow quick, reactive movements.','Land softly with bent knees to protect your joints and store elastic energy.','Keep your chest up and core braced to maintain balance during direction changes.','Move as fast as possible while maintaining control and accurate foot placement.']::text[],'quads',ARRAY['cardiovascular_system','tibialis_anterior','abductors']::text[],'bodyweight','plyometric','intermediate',ARRAY['plyometric','cardio','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','03be228e-9483-470b-ad6c-cdf3d43f7415','Double Box Single Leg Lateral Hop','double-box-single-leg-lateral-hop-1e51c0','Starting position: Stand on one leg beside a low box with hands on hips and torso slightly hinged forward for balance. Execution: Explosively hop laterally over and onto the box on the same leg, absorbing the landing softly, then hop back to the start, maintaining single-leg control throughout.',ARRAY['Balance on one leg next to the box with your supporting knee slightly bent.','Drive off the ground and hop laterally onto the box, staying on the same leg.','Land softly with a bent knee to absorb the impact and stabilize.','Immediately hop back down to the starting side on the same leg.','Repeat for the prescribed reps, then switch legs.']::text[],ARRAY['Land softly with a bent knee to protect the joints.','Keep your core braced and hips level to maintain balance.','Control each landing before initiating the next hop.','Keep your chest slightly forward and eyes focused for stability.']::text[],'quads',ARRAY['core','adductors','tibialis_anterior']::text[],'box','plyometric','advanced',ARRAY['plyometric','cardio','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e3c47861-bcfa-41cf-a191-3524d8679a1c','Downward dog','downward-dog','Starting position: Begin on hands and knees with wrists under shoulders and knees under hips. Execution: Tuck toes under and lift hips up and back, straightening legs to form an inverted V-shape while pressing hands firmly into the ground.',ARRAY['Start on all fours, then tuck your toes and lift your hips up and back.','Straighten your legs as much as possible, pressing heels toward the floor.','Spread your fingers wide and press firmly through your palms.','Let your head hang naturally between your arms.']::text[],ARRAY['Create an inverted V-shape with your body.','Keep a slight bend in your knees if your hamstrings are tight.','Rotate your upper arms outward to broaden the shoulders.']::text[],'full_body','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4eaaeaca-6966-4b55-94a0-4a34520bb5b9','Downward facing dog split (left)','downward-facing-dog-split-left','Starting position: Begin in a traditional downward facing dog pose with hands planted shoulder-width apart, feet hip-width apart, and body forming an inverted V-shape. Execution: Lift your left leg straight up toward the ceiling while maintaining the downward dog position, creating a three-limbed dog pose that targets the hamstrings of both the standing leg and the elevated leg.',ARRAY['Start in Downward-Facing Dog.','Shift your weight into both hands evenly.','Lift one leg high toward the ceiling.','Keep your hips square and your standing leg strong.']::text[],ARRAY['Press evenly through both hands.','Keep the raised leg straight and engaged.','Avoid opening the hip of the raised leg.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','dee6b124-faf4-4d03-a659-e49456892af1','Downward facing dog split (right)','downward-facing-dog-split-right','Starting position: Begin in downward facing dog pose with hands planted firmly on the ground, hips raised high, and both feet grounded. Execution: Lift your right leg straight up toward the ceiling while maintaining the downward dog position, creating a straight line from your hands through your raised leg.',ARRAY['Start in Downward-Facing Dog.','Shift your weight into both hands evenly.','Lift one leg high toward the ceiling.','Keep your hips square and your standing leg strong.']::text[],ARRAY['Press evenly through both hands.','Keep the raised leg straight and engaged.','Avoid opening the hip of the raised leg.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cfa3229b-10a2-42cd-bdf0-4fa80ce51fd3','Drop dead push up into knee in','drop-dead-push-up-into-knee-in','Starting position: Begin standing upright with feet hip-width apart and arms at your sides. Execution: Drop down into a push-up position, perform one push-up, then explosively bring one knee toward your chest before returning to standing position.',ARRAY['Start in a standing position with feet hip-width apart','Drop down by placing hands on the ground and jumping feet back into plank position','Perform one controlled push-up with proper form','After pushing up, explosively drive one knee toward your chest while in plank position','Return the knee back to plank position','Jump feet forward toward hands and return to standing position']::text[],ARRAY['Keep your core engaged throughout the entire movement to maintain stability','Land softly when dropping down and jumping back up to protect your joints','Maintain proper push-up form with straight line from head to heels','Alternate which knee you bring to chest with each repetition','Control the tempo during the push-up portion while allowing explosive movement during transitions']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','eda711dc-d4c5-49e6-b323-d8180e41a871','Dumbbel calf raises','dumbbel-calf-raises','Starting position: Stand upright holding dumbbells at your sides with feet hip-width apart, weight evenly distributed on both feet. Execution: Rise up onto your toes by contracting your calf muscles, hold briefly at the top, then slowly lower your heels back to the starting position.',ARRAY['Hold dumbbells with a secure grip at your sides throughout the entire movement','Keep your core engaged and maintain an upright posture with shoulders back','Rise up slowly and deliberately onto your toes, focusing on squeezing your calf muscles','Pause for 1-2 seconds at the top of the movement when on your toes','Lower your heels back down in a controlled manner, taking 2-3 seconds for the descent','Maintain balance by keeping your weight centered over your feet']::text[],ARRAY['Focus on the full range of motion by going as high as possible on your toes and lowering completely','Avoid bouncing or using momentum - the movement should be slow and controlled','Keep your knees slightly bent but stable throughout the exercise to prevent strain','If balance is an issue, perform the exercise near a wall or sturdy surface for support','Start with lighter weights to master the form before progressing to heavier dumbbells']::text[],'calves',ARRAY['gastrocnemius','soleus','forearm_flexors']::text[],'dumbbell','legs','beginner',ARRAY['strength','calisthenics']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','383d7e55-3ec7-4908-8298-96bc42aeebe9','Dumbbell Arnold Press','dumbbell-arnold-press-4db2d1','Starting position: Sit on an upright bench with back support, holding a dumbbell in each hand at shoulder height with palms facing your body and elbows tucked in front. Execution: Press the dumbbells overhead while simultaneously rotating your palms to face forward, extending the arms fully, then reverse the motion to return to the start.',ARRAY['Sit tall against the bench with feet planted and core braced, dumbbells at shoulder level with palms facing you.','Press the dumbbells upward while rotating your wrists outward so palms face forward at the top.','Extend arms fully overhead without locking the elbows aggressively.','Pause briefly at the top with the weights aligned over your shoulders.','Lower under control while rotating palms back toward your body.','Return to the starting position and repeat for the desired reps.']::text[],ARRAY['Keep your core engaged and avoid arching your lower back excessively.','Control the rotation smoothly rather than jerking the wrists.','Do not lock out or slam the elbows at the top.','Keep the dumbbells stacked over the shoulders, not drifting forward.']::text[],'shoulders',ARRAY['triceps_long_head','upper_chest','serratus_anterior']::text[],'dumbbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a0395420-b67f-4ddd-965d-30d4a489f489','Dumbbell Bench Press','dumbbell-bench-press','Starting position: Lie on a flat bench with a dumbbell in each hand, arms extended upward with palms facing forward. Execution: Lower the dumbbells toward your chest, then press upward to return to the starting position.',ARRAY['Lie on bench, dumbbells at sides of chest','Palms facing forward','Press dumbbells up until arms extended','Lower with control to sides of chest']::text[],ARRAY['Greater range of motion than barbell','Keep shoulder blades squeezed','Don''t clang dumbbells together at top','Control the descent','Feet flat on floor']::text[],'chest','{}'::text[],'dumbbell','chest',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9eb19f30-37d0-4aca-9e2d-c90a65f7b07b','Dumbbell Bench Press incline','dumbbell-bench-press-incline-e51818','Starting position: Lie back on an incline bench set to roughly 30-45 degrees, holding a dumbbell in each hand at chest level with palms facing forward and feet flat on the floor. Execution: Press the dumbbells upward until your arms are nearly fully extended, then lower them under control back toward the upper chest.',ARRAY['Set the bench to a 30-45 degree incline and lie back with a dumbbell in each hand.','Position the dumbbells at chest level with elbows bent and palms facing forward.','Press both dumbbells up and slightly inward until arms are nearly extended.','Pause briefly at the top without locking the elbows.','Lower the dumbbells slowly and under control to the starting position.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your back and glutes in contact with the bench throughout.','Avoid flaring the elbows excessively to protect the shoulders.','Control the descent rather than dropping the weights.','Keep wrists straight and stacked over the elbows.']::text[],'upper_chest',ARRAY['front_deltoids','triceps','serratus_anterior']::text[],'dumbbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','57c79553-d2e3-41e9-97d5-3fe8c0d59fe9','Dumbbell Bicep Curl seated incline','dumbbell-bicep-curl-seated-incline-251ef1','Starting position: Sit back on an incline bench set to roughly 45-60 degrees with a dumbbell in each hand, arms hanging straight down and slightly behind the torso, palms facing forward. Execution: Curl the dumbbells upward by flexing the elbows while keeping the upper arms stationary, squeeze the biceps at the top, then lower under control to full extension.',ARRAY['Set an incline bench to about 45-60 degrees and sit back with your head and back supported.','Let both arms hang straight down holding dumbbells with palms facing forward.','Curl the dumbbells toward your shoulders by bending only at the elbows.','Squeeze the biceps at the top of the movement without swinging the upper arms.','Lower the weights slowly back to full arm extension.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your upper arms fixed and back against the bench throughout.','Avoid swinging or using momentum to lift the weight.','Fully extend the arms at the bottom for a complete stretch on the biceps.','Control the negative portion rather than dropping the dumbbells.']::text[],'biceps',ARRAY['brachialis','brachioradialis','forearm_flexors']::text[],'dumbbell','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f34b7615-bfcc-4cd4-88f7-d7c68e910fe9','Dumbbell Bicep Curl Standing','dumbbell-bicep-curl-standing','Starting position: Stand upright with feet shoulder-width apart, holding a dumbbell in each hand with arms fully extended at your sides and palms facing forward. Execution: Slowly curl the weights up by contracting your biceps until your forearms touch your biceps, then lower back to the starting position with control.',ARRAY['Stand holding dumbbells at sides','Palms facing forward','Curl both dumbbells toward shoulders','Squeeze biceps at top','Lower with control']::text[],ARRAY['Keep elbows at sides','Don''t swing or use momentum','Full extension at bottom','Can alternate arms or curl together','Control the negative']::text[],'biceps',ARRAY['brachialis','brachioradialis','forearm_flexors']::text[],'dumbbell','arms - biceps','beginner',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a921697a-e1ec-4941-bffd-f99e69b305b4','Dumbbell Concentration Curl','dumbbell-concentration-curl-01fa72','Starting position: Sit on a bench with feet planted wide, holding a dumbbell in one hand with your elbow braced against the inner thigh and arm extended toward the floor. Execution: Curl the dumbbell upward by flexing the elbow, squeezing the biceps at the top, then lower under control back to the starting position.',ARRAY['Sit on a bench and spread your legs, bracing your working arm''s elbow against the inner thigh.','Grip the dumbbell with the arm fully extended toward the floor.','Curl the dumbbell up toward your shoulder by contracting the biceps.','Pause and squeeze hard at the top of the movement.','Lower the weight slowly and fully extend the arm.','Complete all reps, then switch to the other arm.']::text[],ARRAY['Keep the upper arm and elbow fixed against the thigh throughout.','Avoid swinging or using momentum to lift the weight.','Control the lowering phase to maximize muscle tension.','Fully extend the arm at the bottom for a complete range of motion.']::text[],'biceps',ARRAY['brachialis','brachioradialis','forearm_flexors']::text[],'dumbbell','strength','beginner',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bbac448a-df15-415e-a391-8b1d400df2bf','Dumbbell deadlift','dumbbell-deadlift','Starting position: Stand with feet shoulder-width apart and a dumbbell in each hand in front of your thighs. Execution: Hinge forward at the hips, lowering the dumbbells toward the floor while keeping your back straight and knees slightly bent, then slowly return to the starting position.',ARRAY['Hold dumbbells in front of thighs','Feet hip-width, soft knee bend','Push hips back, lowering dumbbells down legs','Feel hamstring stretch','Drive hips forward to stand']::text[],ARRAY['Same pattern as barbell RDL','Keep dumbbells close to legs','Don''t round lower back','Feel hamstring stretch','Squeeze glutes at top']::text[],'quads','{}'::text[],'dumbbell','legs',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','097903be-beaa-4283-9493-19eb90b59762','Dumbbell deltoid fly','dumbbell-deltoid-fly','Starting position: Stand with feet hip-width apart, holding dumbbells at your sides, then hinge forward at the hips into a bent-over position with a slight bend in your knees. Execution: Lift the dumbbells out to the sides with a slight bend in your elbows, raising them to shoulder height, then slowly lower back to the starting position.',ARRAY['Stand with feet hip-width apart holding a dumbbell in each hand','Hinge forward at the hips while maintaining a neutral spine and slight knee bend','Let the dumbbells hang naturally with arms slightly bent','Lift the weights out to the sides in a wide arc until they reach shoulder height','Squeeze your shoulder blades together at the top of the movement','Slowly lower the dumbbells back to the starting position with control']::text[],ARRAY['Keep your core engaged throughout the movement to protect your lower back','Maintain a slight bend in your elbows rather than keeping arms completely straight','Focus on lifting with your rear deltoids rather than using momentum','Keep your head in a neutral position and avoid rounding your shoulders','Use a weight that allows you to maintain proper form throughout all repetitions']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4426c121-33b6-42c1-aa78-8d295d8fd687','Dumbbell Discus','dumbbell-discus','Starting position: Stand with feet shoulder-width apart, holding a dumbbell with both hands at chest level, arms extended. Execution: Rotate your torso and hips to one side while keeping the dumbbell at chest height, then explosively rotate through your core to the opposite side in a controlled discus-throwing motion.',ARRAY['Hold the dumbbell securely with both hands using an overhand grip at chest level','Plant your feet firmly shoulder-width apart and engage your core muscles','Rotate your torso and hips to one side while keeping the dumbbell close to your body','Explosively rotate through your midsection to the opposite side in a smooth arc motion','Control the movement on both the rotation and return phases','Complete the specified number of repetitions alternating directions or perform all reps to one side first']::text[],ARRAY['Keep the dumbbell close to your body throughout the entire movement to maintain control','Focus on generating power from your core and hips rather than just your arms','Maintain a stable base with your feet planted firmly on the ground','Start with lighter weight to master the rotational movement pattern before progressing','Keep your movements smooth and controlled to avoid injury to the spine']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a46c036e-f0f6-4c03-8216-cc80da58ee3d','Dumbbell Discus (L)','dumbbell-discus-l','Starting position: Stand with feet shoulder-width apart, holding a dumbbell with both hands at chest level, arms extended. Execution: Rotate your torso to the right, then explosively swing the dumbbell in a circular motion across your body to the left side, mimicking a discus throwing motion.',ARRAY['Hold the dumbbell securely with both hands using an overhand grip at chest height','Plant your feet firmly shoulder-width apart and engage your core muscles','Rotate your torso to the right side while keeping the dumbbell close to your body','Explosively swing the dumbbell in a smooth arc across your body toward the left side','Control the movement as you return to the starting position','Maintain proper posture throughout the entire range of motion']::text[],ARRAY['Keep your core engaged throughout the movement to protect your spine and generate power','Use a weight that allows you to maintain control throughout the full range of motion','Focus on smooth, controlled movements rather than speed to prevent injury','Ensure adequate space around you before performing this dynamic exercise','Breathe out during the explosive phase and breathe in during the return movement']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f49f3159-4eed-4d0d-a640-497886c309b0','Dumbbell double snatch','dumbbell-double-snatch','Starting position: Stand with feet shoulder-width apart, holding two dumbbells on the floor between your feet with an overhand grip. Execution: Explosively lift both dumbbells from the ground to overhead in one fluid motion by driving through your hips and legs while pulling the weights up and catching them with arms extended above your head.',ARRAY['Begin in a squat position with dumbbells on the floor, keeping your chest up and back straight','Initiate the movement by driving powerfully through your heels and extending your hips and knees','As the dumbbells reach hip level, explosively shrug your shoulders and pull your elbows high','Continue the upward momentum by pulling yourself under the weights as they reach shoulder height','Catch the dumbbells overhead with arms fully extended and feet planted firmly','Lower the weights back to the starting position in a controlled manner']::text[],ARRAY['Keep the dumbbells close to your body throughout the entire movement to maintain control and efficiency','Focus on generating power from your legs and hips rather than relying solely on your arms','Maintain a neutral spine position and avoid rounding your back during the lift','Practice the movement with lighter weights first to master the coordination before progressing to heavier loads','Ensure adequate shoulder mobility before attempting this exercise to prevent injury']::text[],'full_body','{}'::text[],'dumbbell','full body','advanced',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3433c651-a0f5-40cb-bdd8-3029f3ba15c5','Dumbbell External Rotation','dumbbell-external-rotation','Starting position: Lie on your side with your working arm''s elbow bent at 90 degrees, holding a light dumbbell with your forearm resting across your torso. Execution: Keeping your elbow against your side, rotate your forearm upward and outward until it''s perpendicular to the floor, then slowly return to starting position.',ARRAY['Lie on your side with your head supported and knees slightly bent for stability','Hold a light dumbbell in your top hand with your elbow bent at 90 degrees against your side','Keep your wrist straight and maintain the 90-degree elbow angle throughout the movement','Slowly rotate your forearm upward until it''s vertical, focusing on controlled movement','Pause briefly at the top position before slowly lowering back to the starting position','Complete all repetitions on one side before switching to the other arm']::text[],ARRAY['Start with very light weight (2-5 pounds) as the rotator cuff muscles are small and can be easily injured','Keep your elbow pressed against your side throughout the entire movement to isolate the external rotators','Move slowly and controlled - this exercise is about muscle activation and shoulder health, not speed or heavy weight','Stop immediately if you feel any pain in your shoulder joint','Focus on feeling the work in the back of your shoulder rather than using momentum']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength','rehabilitation']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9696321a-6d49-4d1b-a42d-08fb34bb8323','Dumbbell floor chest press','dumbbell-floor-chest-press','Starting position: Lie flat on the floor with knees bent and feet planted, holding dumbbells at chest level with arms extended upward and palms facing forward. Execution: Lower the dumbbells until your upper arms touch the floor, then press the weights back up to the starting position by contracting your chest muscles.',ARRAY['Lie on your back with knees bent and feet flat on the floor for stability','Hold dumbbells with an overhand grip, arms extended above your chest with a slight bend in your elbows','Slowly lower the dumbbells out to the sides in a wide arc until your upper arms gently touch the floor','Pause briefly when your arms reach the floor, feeling a stretch in your chest','Press the dumbbells back up along the same arc path, squeezing your chest muscles at the top','Maintain control throughout the entire range of motion, avoiding bouncing off the floor']::text[],ARRAY['Keep your core engaged and maintain a neutral spine throughout the movement','The floor acts as a natural safety stop, preventing overstretching of the shoulder joint','Focus on squeezing your chest muscles rather than just moving the weight','Use a controlled tempo with a 2-3 second lowering phase for maximum muscle engagement','Start with lighter weights than you would use for bench press since the floor limits your range of motion']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','97f48a58-e7a9-4179-88e2-f1a16feb68ca','Dumbbell fly','dumbbell-fly','Starting position: Lie on an inclined bench with a dumbbell in each hand, arms extended upward. Execution: Open your arms out to the sides until parallel to the floor, then return to the starting position.',ARRAY['Lie on bench, dumbbells above chest','Slight bend in elbows','Lower dumbbells out to sides in arc','Stop when you feel chest stretch','Squeeze chest to bring dumbbells back up']::text[],ARRAY['Keep slight elbow bend throughout','Don''t go too deep (shoulder strain)','Movement is an arc, not a press','Feel stretch at bottom, squeeze at top','Control the weight']::text[],'chest','{}'::text[],'dumbbell','chest',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c60450d9-862c-4dd3-87b1-82f80349964d','Dumbbell fly - v2','dumbbell-fly-v2','Starting position: Lie on a flat bench with a dumbbell in each hand, arms extended above your chest with a slight bend in your elbows and palms facing each other. Execution: Lower the dumbbells in a wide arc until you feel a stretch in your chest, then reverse the movement to bring the weights back to the starting position.',ARRAY['Lie flat on the bench with your feet firmly planted on the floor and your back pressed against the bench','Hold dumbbells with a neutral grip, arms extended above your chest with a slight bend in your elbows','Slowly lower the dumbbells in a controlled arc motion, keeping the slight bend in your elbows constant','Lower until you feel a good stretch in your chest muscles or the dumbbells reach chest level','Squeeze your chest muscles and reverse the arc motion to return dumbbells to starting position','Maintain control throughout the entire range of motion, avoiding any jerky movements']::text[],ARRAY['Keep a consistent slight bend in your elbows throughout the movement to protect your shoulder joints','Focus on feeling the stretch and contraction in your chest muscles rather than moving heavy weight','Control the eccentric (lowering) portion of the movement to maximize muscle activation','Avoid lowering the dumbbells too far below chest level to prevent shoulder strain','Maintain proper breathing by inhaling during the lowering phase and exhaling during the lifting phase']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4581a423-5d2d-4cf1-89a0-fea026ef116d','Dumbbell Fly incline','dumbbell-fly-incline-94dccc','Starting position: Lie back on an incline bench set to roughly 30-45 degrees, holding a dumbbell in each hand pressed above the chest with palms facing each other and a slight bend in the elbows. Execution: Open the arms out to the sides in a wide arc, lowering the dumbbells until you feel a stretch across the upper chest, then squeeze the pecs to bring the weights back together over the chest.',ARRAY['Set the bench to a 30-45 degree incline and lie back with feet planted firmly on the floor.','Press two dumbbells up over your chest with palms facing each other and elbows slightly bent.','Lower the dumbbells in a wide arc out to the sides until you feel a stretch in the upper chest.','Keep the slight elbow bend fixed throughout the movement.','Squeeze the chest to bring the dumbbells back up together in a controlled arc.','Repeat for the desired number of repetitions.']::text[],ARRAY['Maintain a soft, fixed bend in the elbows to protect the joints and keep tension on the chest.','Move slowly and control the eccentric to maximize the stretch and avoid shoulder strain.','Do not lower the weights too far past chest level to protect the shoulder joint.','Keep shoulder blades retracted and back flat against the bench.']::text[],'upper_chest',ARRAY['front_deltoids','biceps','serratus_anterior']::text[],'dumbbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d8a67e85-0c9f-483d-b7fe-be049247ab1c','Dumbbell forward lunge','dumbbell-forward-lunge','Starting position: Stand upright holding a dumbbell in each hand at your sides, feet hip-width apart, core engaged. Execution: Step forward with one leg into a lunge position, lowering your hips until both knees are bent at approximately 90 degrees, then push through the front heel to return to starting position.',ARRAY['Hold dumbbells with a firm grip at your sides, maintaining neutral wrists throughout the movement','Take a controlled step forward, landing on your heel first then rolling onto the full foot','Lower your body by bending both knees until your front thigh is parallel to the floor and rear knee nearly touches the ground','Keep your torso upright and avoid leaning forward or backward during the descent','Push through your front heel to drive yourself back to the starting position','Complete all repetitions on one leg before switching to the other side']::text[],ARRAY['Keep most of your weight on your front leg and avoid pushing off with your back toe','Maintain a straight back throughout the movement and engage your core to prevent forward lean','Ensure your front knee tracks in line with your toes and doesn''t cave inward','Control the descent and avoid dropping too quickly into the lunge position','Start with lighter weights to master the movement pattern before progressing to heavier loads']::text[],'quads','{}'::text[],'dumbbell','legs','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3e668a4f-2aac-42ae-b8db-58fc179d20d2','Dumbbell Front Raise','dumbbell-front-raise','Starting position: Stand holding a dumbbell in each hand with palms facing your body. Execution: Raise one dumbbell to the front until it reaches shoulder height, alternating with the other hand each repetition.',ARRAY['Stand with feet shoulder-width apart and maintain a slight bend in your knees throughout the movement','Hold dumbbells with a neutral grip, arms straight but not locked, positioned in front of your thighs','Engage your core and keep your back straight with shoulders pulled back','Lift the weights forward and up in a smooth arc until your arms reach shoulder height','Pause briefly at the top position, then slowly lower the dumbbells back to the starting position','Keep the movement controlled and avoid using momentum or swinging the weights']::text[],ARRAY['Use a weight that allows you to maintain proper form throughout all repetitions','Keep your wrists straight and avoid lifting the dumbbells higher than shoulder level to prevent shoulder impingement','Focus on initiating the movement from your shoulders rather than using your back or legs for momentum','Maintain tension in your core to protect your lower back and improve stability','Control the eccentric (lowering) portion of the movement to maximize muscle engagement and prevent injury']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','beee4955-3dbc-4aa1-be35-d01666713f72','Dumbbell get ups (R)','dumbbell-get-ups-r','Starting position: Lie on your back holding a dumbbell in your right hand with arm extended straight up toward the ceiling, left arm at your side for stability. Execution: Roll to your left side, use your left hand to push up to sitting, then step your left foot forward and stand up while keeping the dumbbell overhead throughout the entire movement.',ARRAY['Lie flat on your back holding the dumbbell in your right hand with arm fully extended overhead','Keep your eyes on the dumbbell throughout the entire movement to maintain balance and control','Roll onto your left side and use your left hand to push yourself up to a seated position','Bring your left leg forward and plant your left foot firmly on the ground','Push through your left heel to stand up while maintaining the dumbbell overhead','Reverse the movement to return to the starting position with control']::text[],ARRAY['Keep the dumbbell arm locked out and vertical throughout the entire exercise to prevent shoulder injury','Move slowly and deliberately through each phase to maintain proper form and control','Keep your core engaged throughout the movement to provide stability and support','Start with a lighter weight to master the movement pattern before progressing to heavier loads','Maintain visual contact with the dumbbell to help with balance and proprioception']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','dadea1de-c228-4e36-99de-db68578de515','Dumbbell glute bridge','dumbbell-glute-bridge','Starting position: Lie on your back with knees bent, feet flat on the floor hip-width apart, holding a dumbbell securely on your hips with both hands. Execution: Drive through your heels to lift your hips up, creating a straight line from knees to shoulders, then lower back down with control.',ARRAY['Lie on back, knees bent, feet flat','Drive hips up by squeezing glutes','Form straight line from shoulders to knees','Lower with control']::text[],ARRAY['Squeeze glutes hard at top','Don''t hyperextend lower back','Drive through heels','Hold at top briefly','Foundation for hip thrusts']::text[],'quads','{}'::text[],'dumbbell','legs',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ff6872ae-e894-4e72-b5f8-59a55b576a6f','Dumbbell Goblet Squat','dumbbell-goblet-squat-202e4f','Starting position: Stand tall with feet shoulder-width apart, holding a single dumbbell vertically against your chest with both hands cupped under the top end. Execution: Brace your core, push your hips back and bend your knees to lower into a squat until thighs are at least parallel to the floor, then drive through your heels to stand back up.',ARRAY['Hold a dumbbell vertically at chest height with both hands, keeping elbows tucked in.','Set feet shoulder-width apart with toes slightly turned out.','Brace your core and lower by bending knees and pushing hips back until thighs reach parallel.','Keep your chest up and torso upright throughout the descent.','Drive through your heels to return to the standing position.','Squeeze your glutes at the top and repeat for the desired reps.']::text[],ARRAY['Keep the dumbbell close to your chest and elbows tucked to maintain an upright torso.','Track your knees in line with your toes and avoid caving inward.','Maintain a neutral spine and braced core to protect your lower back.','Push through your heels rather than the balls of your feet.']::text[],'quadriceps',ARRAY['calves','forearms','abs']::text[],'dumbbell','strength','beginner',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','44a83578-5681-4a1a-99c3-f8742857bf66','Dumbbell Lateral Raise','dumbbell-lateral-raise-27a4de','Starting position: Stand tall with feet shoulder-width apart, holding a dumbbell in each hand at your sides with palms facing your body and a slight bend in the elbows. Execution: Raise both arms out to the sides until they reach shoulder height, keeping elbows slightly bent, then lower them back down under control.',ARRAY['Stand upright with a dumbbell in each hand and arms hanging at your sides.','Keep a slight bend in your elbows and brace your core.','Raise both arms out to the sides until they are parallel to the floor.','Pause briefly at the top with wrists level with your shoulders.','Slowly lower the dumbbells back to the starting position under control.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep a soft bend in the elbows throughout the movement.','Avoid using momentum or swinging the torso to lift the weights.','Do not raise the arms above shoulder height to protect the shoulder joint.','Keep shoulders down and avoid shrugging the traps.']::text[],'lateral_deltoids',ARRAY['traps','supraspinatus','serratus_anterior']::text[],'dumbbell','strength','beginner',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','57c55853-176e-4bad-aced-1032c63f4652','Dumbbell Lunges','dumbbell-lunges','Starting position: Stand upright holding a dumbbell in each hand at your sides with feet hip-width apart. Execution: Step forward into a lunge position, lowering your hips until both knees are bent at approximately 90 degrees, then push through your front heel to return to the starting position.',ARRAY['Hold dumbbells at sides','Step forward into lunge','Lower until back knee near floor','Push back to start','Alternate legs or complete one side']::text[],ARRAY['Keep torso upright','Front knee tracks over toes','Control the descent','Don''t let front knee shoot forward','Arms hang naturally']::text[],'quads',ARRAY['glute_med','hip_flexors','erector_spinae']::text[],'dumbbell','legs','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f181cc8e-9816-4205-b025-3b23cb30720b','Dumbbell Lying Rear Lateral Raise','dumbbell-lying-rear-lateral-raise','Starting position: Lie prone on an inclined bench with your chest supported, holding dumbbells with arms hanging down and a slight bend in your elbows. Execution: Raise the dumbbells out to the sides in a wide arc until your arms are parallel to the floor, then slowly lower back to the starting position.',ARRAY['Position yourself face down on an inclined bench with your chest fully supported and feet planted firmly on the floor','Hold a dumbbell in each hand with arms hanging straight down and maintain a slight bend in your elbows throughout the movement','Initiate the movement by lifting the dumbbells out to your sides in a wide arc, leading with your pinkies','Raise the weights until your arms are parallel to the floor and you feel a strong contraction in your rear deltoids','Slowly lower the dumbbells back to the starting position with control, maintaining the same arc path']::text[],ARRAY['Keep your chest pressed firmly against the bench throughout the entire movement to maintain proper form and prevent using momentum','Maintain a slight bend in your elbows and avoid straightening your arms completely to protect your joints','Focus on squeezing your shoulder blades together at the top of the movement to maximize rear deltoid activation','Use a controlled tempo, especially on the lowering phase, to maintain tension on the target muscles','Start with lighter weights as this exercise requires precise form and the rear deltoids are typically weaker muscles']::text[],'shoulders','{}'::text[],'dumbbell','shoulders',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fa0fd12d-1fd4-448f-9e21-ceda7b8f18eb','Dumbbell Lying Rear Lateral Raise - One arm','dumbbell-lying-rear-lateral-raise-one-arm','Starting position: Lie face down on an inclined bench set to 30-45 degrees, holding a dumbbell in one hand with your arm hanging straight down and palm facing backward. Execution: Raise the dumbbell out to the side until your arm is parallel to the floor, then slowly lower it back to the starting position.',ARRAY['Set an inclined bench to 30-45 degrees and lie face down with your chest supported','Hold a light dumbbell in one hand and let your arm hang straight down with palm facing backward','Keep your core engaged and maintain contact between your chest and the bench throughout the movement','Raise the dumbbell out to the side in a controlled arc until your arm is parallel to the floor','Pause briefly at the top position, then slowly lower the weight back to starting position','Complete all repetitions on one side before switching to the other arm']::text[],ARRAY['Use a lighter weight than you think you need as the rear deltoids are small muscles that fatigue quickly','Keep a slight bend in your elbow throughout the entire movement to protect the joint','Focus on squeezing your shoulder blades together as you lift to maximize rear deltoid activation','Avoid using momentum or swinging the weight up as this reduces effectiveness and increases injury risk','Maintain proper breathing by exhaling during the lifting phase and inhaling during the lowering phase']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','af545111-e56a-4731-ba48-2d4ce750bc8e','Dumbbell One-Arm Shoulder Press (L)','dumbbell-one-arm-shoulder-press-l','Starting position: Stand with feet shoulder-width apart, holding a dumbbell in your left hand at shoulder height with palm facing forward and elbow bent at 90 degrees. Execution: Press the dumbbell straight up overhead until your arm is fully extended, then slowly lower back to the starting position.',ARRAY['Stand with feet shoulder-width apart and engage your core for stability','Hold the dumbbell in your left hand at shoulder height with palm facing forward','Keep your elbow directly under the dumbbell and maintain a neutral wrist position','Press the weight straight up overhead in a controlled motion until your arm is fully extended','Slowly lower the dumbbell back to shoulder height, maintaining control throughout the descent','Complete all repetitions on the left side before switching to the right arm']::text[],ARRAY['Keep your core engaged throughout the movement to prevent arching your back','Avoid pressing the weight forward or backward - maintain a straight vertical path','Use your non-working arm for balance but avoid leaning to one side','Control the descent phase as much as the pressing phase to maximize muscle engagement','Stop immediately if you feel any sharp pain in your shoulder joint']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e8aacdde-8fce-438b-878b-3af1a611f2be','Dumbbell One-Arm Shoulder Press (R)','dumbbell-one-arm-shoulder-press-r','Starting position: Stand with feet shoulder-width apart, holding a dumbbell in your right hand at shoulder level with palm facing forward and elbow directly under the weight. Execution: Press the dumbbell straight up overhead until your arm is fully extended, then slowly lower it back to the starting position at shoulder level.',ARRAY['Stand with feet shoulder-width apart and engage your core to maintain a stable base','Hold the dumbbell in your right hand at shoulder level with palm facing forward and elbow positioned directly under the weight','Keep your left hand on your hip or extended out to the side for balance','Press the dumbbell straight up overhead in a controlled motion until your arm is fully extended','Slowly lower the weight back down to shoulder level, maintaining control throughout the descent','Complete all repetitions on the right arm before switching to the left']::text[],ARRAY['Keep your core engaged throughout the movement to prevent arching your back','Press the weight straight up rather than forward to avoid shoulder impingement','Maintain a neutral wrist position and avoid letting the dumbbell tilt','Use a weight that allows you to maintain proper form for all repetitions','Avoid locking out your elbow aggressively at the top of the movement']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ac7982bb-1a81-4870-ae78-ce37bb485601','Dumbbell One-Arm Upright Row (L)','dumbbell-one-arm-upright-row-l','Starting position: Stand upright with feet hip-width apart, holding a dumbbell in your left hand with an overhand grip, arm extended down by your side. Execution: Pull the dumbbell straight up along your body by lifting your elbow high and wide until the weight reaches chest level, then slowly lower back to starting position.',ARRAY['Stand with feet hip-width apart and core engaged, holding the dumbbell in your left hand with palm facing your body','Keep your torso upright and shoulders square, avoiding any leaning or rotating movements','Initiate the movement by pulling your left elbow up and out to the side, leading with the elbow rather than the hand','Pull the dumbbell straight up along your torso until it reaches chest level, keeping the weight close to your body','Pause briefly at the top position, then slowly lower the dumbbell back to the starting position with control','Complete all repetitions on the left side before switching to the right arm']::text[],ARRAY['Keep the dumbbell close to your body throughout the entire movement to maintain proper form and reduce shoulder strain','Lead with your elbow and keep it higher than your wrist at the top of the movement to properly target the upper back and rear deltoids','Avoid using momentum or swinging the weight - maintain slow, controlled movements throughout the exercise','Stop the upward movement when the dumbbell reaches chest level to prevent shoulder impingement','Maintain neutral spine alignment and avoid leaning away from the working side during the exercise']::text[],'back','{}'::text[],'dumbbell','back','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bda6ae04-2619-43a7-8261-490d85444eb2','Dumbbell One-Arm Upright Row (R)','dumbbell-one-arm-upright-row-r','Starting position: Stand with feet hip-width apart, holding a dumbbell in your right hand with an overhand grip, arm extended down at your side. Execution: Pull the dumbbell straight up along your body by lifting your elbow high and out to the side until it reaches chest level, then slowly lower back to starting position.',ARRAY['Stand with feet hip-width apart and core engaged, holding the dumbbell in your right hand with palm facing your body','Keep your torso upright and shoulders back throughout the entire movement','Pull the dumbbell up by leading with your elbow, keeping it close to your body as it travels upward','Lift until your elbow reaches shoulder height and the dumbbell is at chest level','Pause briefly at the top position, then slowly lower the weight back to starting position with control','Complete all repetitions on the right side before switching to the left arm']::text[],ARRAY['Keep the dumbbell close to your body throughout the movement to maintain proper form and prevent shoulder impingement','Lead with your elbow rather than your hand to ensure proper muscle activation in the rear deltoids and upper traps','Avoid lifting the weight too high above shoulder level as this can cause shoulder joint stress','Control the lowering phase of the movement to maximize muscle engagement and prevent injury','Maintain a neutral spine and avoid leaning or swaying to compensate for the unilateral load']::text[],'back','{}'::text[],'dumbbell','back','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0b4d6477-e8d8-4ae1-aff6-d935a77b3fe1','Dumbbell Overhead Tricep Extension','dumbbell-overhead-tricep-extension-47c5a2','Starting position: Sit upright on a bench with feet planted, holding a single dumbbell overhead with both hands behind the head, elbows pointing forward and close to the ears. Execution: Extend the elbows to press the dumbbell up overhead until the arms are nearly straight, then lower the weight back behind the head under control to stretch the triceps.',ARRAY['Sit tall on a bench and grip one dumbbell with both hands, raising it overhead.','Keep your elbows pointing forward and tucked close to your head.','Lower the dumbbell behind your head by bending only at the elbows.','Extend your arms to press the weight back up until nearly straight.','Squeeze the triceps at the top, then repeat under control.']::text[],ARRAY['Keep your upper arms stationary and elbows pointing forward throughout.','Move only at the elbow joint to isolate the triceps.','Avoid arching your lower back by bracing your core.','Control the lowering phase and get a full stretch behind the head.']::text[],'triceps',ARRAY['front_deltoids','forearm_flexors','core']::text[],'dumbbell','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','35b16467-8817-4c28-b84c-a1f47b1734cd','Dumbbell pistol squats','dumbbell-pistol-squats','Starting position: Stand on one leg holding a dumbbell at chest level with both hands, with the non-working leg extended straight out in front of you. Execution: Lower your body by bending the standing leg until your glutes nearly touch your heel, then drive through your heel to return to the starting position while keeping the extended leg off the ground throughout the movement.',ARRAY['Start with bodyweight only until you can perform 5-8 clean repetitions per leg','Hold a light dumbbell (5-10 lbs) at chest level with both hands once you''ve mastered the bodyweight version','Keep your extended leg straight and parallel to the floor throughout the entire movement','Lower down slowly and controlled, aiming to get your glutes as close to your heel as possible','Drive through your heel and engage your glutes to push back up to the starting position','Complete all repetitions on one leg before switching to the other leg']::text[],ARRAY['This is an advanced exercise that requires significant leg strength, balance, and ankle mobility','Use a box or bench behind you initially to limit your range of motion and build confidence','Keep your torso as upright as possible and avoid leaning forward excessively','Focus on controlling the descent rather than rushing through the movement','Consider holding onto a stable surface with your free hand if balance is challenging']::text[],'quads','{}'::text[],'dumbbell','legs','advanced',ARRAY['strength','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b5869e95-3109-43ad-b7b5-34e6dad882f0','Dumbbell plank row','dumbbell-plank-row','Starting position: Begin in a plank position with hands gripping dumbbells directly under your shoulders, feet slightly wider than hip-width apart for stability. Execution: While maintaining the plank position, row one dumbbell up toward your ribcage by pulling your elbow back, then lower with control and repeat on the opposite side.',ARRAY['Forearms on floor, elbows under shoulders','Body straight from head to heels','Hold position','Keep core tight, don''t let hips sag']::text[],ARRAY['Squeeze glutes','Keep neck neutral','Breathe normally','Don''t raise hips too high','Build time gradually']::text[],'back','{}'::text[],'dumbbell','core',null,ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c90444fe-fd21-40d1-923f-5adba83e35bc','Dumbbell Pullover','dumbbell-pullover-240b42','Starting position: Lie perpendicular or lengthwise on a flat bench with your upper back supported, hips lowered, and feet planted firmly on the floor. Hold a single dumbbell overhead with both hands cupping the top plate, arms nearly straight. Execution: Keeping a slight bend in the elbows, lower the dumbbell in an arc behind your head until you feel a stretch across the chest and lats, then pull it back over your chest by contracting the lats and pecs.',ARRAY['Set up on a flat bench supporting your upper back and shoulders, feet flat on the floor.','Grip one dumbbell with both hands and press it above your chest with arms nearly straight.','Slowly lower the dumbbell in an arc behind your head, maintaining a slight elbow bend.','Lower until you feel a deep stretch in the lats and chest without overextending.','Pull the dumbbell back over your chest using your lats and pecs.','Control the movement throughout and repeat for the desired reps.']::text[],ARRAY['Keep the elbows slightly bent and fixed throughout the arc.','Move only at the shoulder joint, not the arms or elbows.','Avoid arching the lower back excessively; keep the core braced.','Control the eccentric to protect the shoulders.']::text[],'lats',ARRAY['triceps_long_head','core','rhomboids']::text[],'dumbbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f6d6ac54-751d-416e-8c9d-bc4b675cd505','Dumbbell Pullover','dumbbell-pullover-8dd09f','Starting position: Lie supine across or along a flat bench with the upper back and shoulders supported, feet planted firmly on the floor, and hips slightly lowered. Hold a single dumbbell with both hands cupped under the top plate, arms extended above the chest with a slight elbow bend. Execution: Keeping the slight elbow bend fixed, lower the dumbbell in an arc back over and behind the head until a deep stretch is felt across the chest and lats, then pull the weight back over the chest by contracting the pecs and lats.',ARRAY['Position your upper back on the bench and set your feet flat on the floor for a stable base.','Grip a single dumbbell with both hands and press it up over your chest with elbows slightly bent.','Slowly lower the dumbbell in an arc behind your head until you feel a stretch across the chest and lats.','Contract your chest and lats to pull the dumbbell back up over your chest along the same arc.','Control the tempo throughout and repeat for the desired repetitions.']::text[],ARRAY['Maintain a fixed slight bend in the elbows to protect the shoulder joint.','Lower only as far as your shoulder mobility allows without arching the lower back excessively.','Keep the movement slow and controlled, avoiding momentum.','Breathe in as you lower the weight and exhale as you pull it back over your chest.']::text[],'chest',ARRAY['lats','triceps_long_head','serratus_anterior','teres_major']::text[],'dumbbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ad241fc8-3d05-4ce7-a950-45380497cdc0','Dumbbell Pulse Squat','dumbbell-pulse-squat-d1ae1a','Starting position: Stand with feet shoulder-width apart holding a single dumbbell vertically at chest height in a goblet grip. Execution: Lower into a deep squat until thighs are parallel or below, then perform small pulsing movements at the bottom of the squat before returning to standing.',ARRAY['Stand tall holding a dumbbell at chest level with both hands, feet shoulder-width apart and toes slightly turned out.','Bend at the hips and knees to lower into a deep squat, keeping your chest upright and core braced.','At the bottom of the squat, pulse up and down through a small range of motion.','Keep tension in the quads and glutes throughout the pulses.','Complete the prescribed pulses, then drive through your heels to stand back up.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your chest lifted and back straight to avoid rounding.','Track your knees over your toes and prevent them from caving inward.','Maintain weight through your heels and mid-foot during pulses.','Keep the core engaged to stabilize the spine throughout the movement.']::text[],'quads',ARRAY['hamstrings','adductors','calves','core']::text[],'dumbbell','strength','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9690f31a-ed99-446e-88db-2934b832f497','Dumbbell Rear Lunge','dumbbell-rear-lunge','Starting position: Stand upright holding a dumbbell in each hand at your sides, feet hip-width apart with core engaged. Execution: Step one foot backward into a lunge position, lowering your hips until both knees are bent at approximately 90 degrees, then push through the front heel to return to starting position.',ARRAY['Hold dumbbells with a secure grip at your sides, maintaining neutral wrists throughout the movement','Step backward with one leg, landing on the ball of your foot while keeping your torso upright','Lower your body until your front thigh is parallel to the floor and your rear knee nearly touches the ground','Keep your front knee aligned over your ankle, not pushing forward past your toes','Push through your front heel to drive back to the starting position','Complete all repetitions on one leg before switching to the other side']::text[],ARRAY['Keep most of your weight on your front leg throughout the entire movement','Maintain an upright torso and avoid leaning forward, which can strain your lower back','Control the descent slowly rather than dropping quickly into the lunge position','Ensure your front knee tracks in line with your toes to prevent knee strain','Start with lighter weights to master the movement pattern before progressing to heavier dumbbells']::text[],'quads','{}'::text[],'dumbbell','legs','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','54d04b7e-3a7d-4d04-a0b2-adaab8f8f466','Dumbbell Romanian Deadlift','dumbbell-romanian-deadlift-8f7fca','Starting position: Stand tall holding a dumbbell in each hand in front of your thighs, feet hip-width apart, knees softly bent, shoulders back and core braced. Execution: Hinge at the hips by pushing your glutes back, keeping a slight bend in the knees and lowering the dumbbells along the front of your legs until you feel a stretch in the hamstrings, then drive your hips forward to return to standing.',ARRAY['Hold a dumbbell in each hand in front of your thighs with a neutral spine and soft knees.','Push your hips back and hinge forward, sliding the dumbbells down the front of your legs.','Lower until you feel a stretch in the hamstrings while keeping your back flat.','Drive through your heels and extend your hips to return to the upright position.','Squeeze your glutes at the top and repeat for the desired reps.']::text[],ARRAY['Keep your back flat and avoid rounding the lower spine.','Initiate the movement from the hips, not the knees.','Keep the dumbbells close to your body throughout the range.','Maintain a slight, fixed knee bend rather than squatting.']::text[],'hamstrings',ARRAY['glute_max','erector_spinae','forearm_flexors']::text[],'dumbbell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e91bd54f-f605-491d-90e6-16515787389c','Dumbbell Row two arm bent over','dumbbell-row-two-arm-bent-over-15f4f2','Starting position: Stand with feet hip-width apart holding a dumbbell in each hand, hinge forward at the hips until your torso is roughly parallel to the floor, keeping a slight bend in the knees and a flat, neutral spine, arms hanging straight down. Execution: Pull both dumbbells up toward your lower ribcage by driving your elbows back and squeezing your shoulder blades together, then lower under control to the starting position.',ARRAY['Hinge forward at the hips with a flat back until your torso is near parallel to the floor.','Let the dumbbells hang directly below your shoulders with arms extended.','Row both dumbbells up toward your lower ribs, leading with your elbows.','Squeeze your shoulder blades together at the top of the movement.','Lower the dumbbells slowly back to full arm extension.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your spine neutral and avoid rounding your lower back.','Drive with your elbows and squeeze the shoulder blades, not just the arms.','Maintain a stable hip hinge and braced core throughout.','Avoid jerking or using momentum to lift the weights.']::text[],'back',ARRAY['biceps','rear_deltoids','forearms','erector_spinae']::text[],'dumbbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1575dc75-93ab-4c7f-b924-4ed4eda2adc8','Dumbbell Russian Twist','dumbbell-russian-twist-1f195c','Starting position: Sit on the floor with knees bent and heels lightly touching or hovering above the ground, torso leaning back at roughly 45 degrees, holding a single dumbbell with both hands in front of your chest. Execution: Rotate your torso to bring the dumbbell toward one side of your hips, then twist across to the opposite side in a controlled rhythm, keeping your core braced throughout.',ARRAY['Sit on the floor with knees bent and lean your torso back to engage the core.','Hold a dumbbell with both hands close to your chest.','Twist your torso to move the weight toward one hip.','Rotate through the midline and bring the weight to the opposite hip.','Continue alternating sides in a smooth, controlled manner.','Keep your chest up and avoid rounding the lower back.']::text[],ARRAY['Rotate from the waist, not just the arms, to target the obliques.','Keep your core braced and back straight to protect the spine.','Move in a controlled tempo rather than swinging the weight.','Elevate your feet to increase difficulty.']::text[],'obliques',ARRAY['hip_flexors','erector_spinae','shoulders']::text[],'dumbbell','core','intermediate',ARRAY['core','strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d4210b5a-f583-4039-8566-ed5a20e46eab','Dumbbell Scaption','dumbbell-scaption','Starting position: Stand with feet hip-width apart, holding a dumbbell in each hand at your sides with arms straight and palms facing your body. Execution: Raise both arms simultaneously in a Y-shape (approximately 30-45 degrees forward from your sides) until they reach shoulder height, then slowly lower back to starting position.',ARRAY['Stand with feet hip-width apart and core engaged, holding dumbbells with arms at your sides','Position your thumbs pointing upward and arms slightly forward from your body at about a 30-45 degree angle','Raise both arms simultaneously in a smooth Y-pattern until dumbbells reach shoulder height','Pause briefly at the top while maintaining control of the weights','Slowly lower the dumbbells back to starting position with the same controlled motion','Keep your torso upright and avoid using momentum throughout the movement']::text[],ARRAY['Keep your thumbs pointing up throughout the movement to properly target the supraspinatus muscle','Use lighter weights than typical shoulder exercises as this targets smaller stabilizing muscles','Maintain a slight bend in your elbows and avoid locking out your arms completely','Focus on controlled movement rather than speed to maximize muscle activation and prevent injury','Stop immediately if you feel any pinching or pain in the shoulder joint']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0d0368ee-f03d-4ef9-95db-06a56434ea55','Dumbbell Scissors','dumbbell-scissors','Starting position: Stand with feet hip-width apart, holding a dumbbell in each hand at shoulder height with arms extended overhead. Execution: Jump and switch leg positions back and forth in a scissor-like motion while maintaining the overhead dumbbell position, alternating which leg is forward and back.',ARRAY['Stand with feet hip-width apart, holding a dumbbell in each hand at shoulder height with arms bent at 90 degrees','Step your right foot forward into a lunge position while simultaneously pressing the left dumbbell overhead','Push off your right foot and immediately step your left foot forward into a lunge while lowering the left arm and pressing the right dumbbell overhead','Continue alternating legs in a scissor-like motion while alternating overhead presses with each step','Maintain an upright torso throughout the movement and control the descent into each lunge','Complete the desired number of repetitions, ensuring equal work on both sides']::text[],ARRAY['Keep your core engaged throughout to maintain balance and protect your lower back','Don''t let your front knee extend past your toes during the lunge portion','Use a controlled tempo rather than rushing through the movement to maintain proper form','Start with lighter weights until you master the coordination between the lower and upper body movements','Ensure you have adequate space around you before beginning this dynamic exercise']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0ff5e9fe-9d15-426a-8c06-fd62a198dc47','Dumbbell shadow box','dumbbell-shadow-box','Starting position: Stand with feet shoulder-width apart, holding light dumbbells in both hands with arms in a boxing guard position near your chest. Execution: Perform alternating punching movements (jabs, crosses, hooks, uppercuts) while maintaining proper boxing stance and footwork.',ARRAY['Stand with feet shoulder-width apart, holding a light dumbbell in each hand at chest level','Bend your knees slightly and engage your core while maintaining an upright posture','Begin throwing alternating punches forward, extending one arm fully while keeping the other at chest level','Add in hooks by punching across your body, rotating your torso with each movement','Incorporate uppercuts by punching upward in an arcing motion from your hip level','Continue alternating between jabs, hooks, and uppercuts for the desired duration']::text[],ARRAY['Use lighter weights than usual since this is a cardio-focused movement','Keep your core engaged throughout to protect your lower back','Maintain control of the dumbbells at all times to prevent injury','Focus on smooth, controlled movements rather than aggressive punching','Keep your feet moving and stay light on your toes like a real boxer']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d6c2798d-a077-41b9-9769-d5bd1a57caaa','Dumbbell Shoulder Press','dumbbell-shoulder-press','Starting position: Sit on a bench with a dumbbell in each hand, arms extended upward with palms facing each other. Execution: Lower the dumbbells to your shoulders, then press upward to return to the starting position.

Note: the exercise can also be done standing.',ARRAY['Sit on bench with back support; the exercise can also be done standing','Hold dumbbells at shoulder height, palms forward','Press straight up until arms extended','Lower with control to shoulders']::text[],ARRAY['Keep core tight, back against pad','Don''t clang dumbbells at top','Full range of motion','Control the negative','Don''t arch back excessively']::text[],'shoulders','{}'::text[],'dumbbell','shoulders',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0af648a1-1d2e-438b-b687-b522c9eaa8bd','Dumbbell shoulder punches','dumbbell-shoulder-punches','Starting position: Stand with feet shoulder-width apart, holding a light dumbbell in each hand at shoulder height with elbows bent and palms facing forward. Execution: Alternate punching forward with each arm, extending the dumbbell straight out while rotating the wrist so palm faces down, then return to starting position.',ARRAY['Stand with feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with palms facing forward','Engage your core and maintain a slight bend in your knees throughout the movement','Punch one arm straight forward, fully extending the arm while keeping the dumbbell controlled','Return the punching arm back to starting position at shoulder height','Immediately punch forward with the opposite arm in an alternating pattern','Continue alternating arms at a controlled, rhythmic pace']::text[],ARRAY['Keep your core tight to prevent back arching and maintain stability','Don''t overextend or lock out your elbows completely to avoid joint stress','Control the weight on both the punch forward and the return movement','Start with lighter weights to master the form before increasing resistance','Maintain proper posture with shoulders back and chest up throughout']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b150868d-c9c5-4f0f-a407-93d7e34b6ddc','Dumbbell Shrug','dumbbell-shrug','Starting position: Stand upright with feet hip-width apart, holding a dumbbell in each hand with arms fully extended at your sides and palms facing your body. Execution: Lift your shoulders straight up toward your ears by contracting your trapezius muscles, hold briefly at the top, then slowly lower your shoulders back to the starting position.',ARRAY['Stand holding dumbbells at sides','Arms straight, palms facing body','Shrug shoulders straight up','Hold at top','Lower with control']::text[],ARRAY['Don''t roll shoulders','Hold the squeeze at top','Let traps stretch at bottom','Keep arms straight','Heavier weight okay for this exercise']::text[],'back',ARRAY['forearm_flexors','rear_deltoids','neck']::text[],'dumbbell','back','beginner',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','71304f37-af11-4c9f-aa53-ef04cbc9bb29','Dumbbell Side Bend','dumbbell-side-bend-cb0503','Starting position: Stand upright holding a dumbbell in one hand at your side. Execution: Lean sideways away from the weight, then return to starting position.',ARRAY['Stand with feet shoulder-width apart holding dumbbell','Keep opposite hand on hip or behind head','Bend slowly to the weighted side only','Contract obliques to return to starting position','Complete all reps before switching sides']::text[],ARRAY['Only bend to the side holding the weight to target obliques effectively','Keep your back straight and avoid leaning forward or backward','Control the movement slowly to prevent momentum from taking over','Use lighter weight initially as this exercise can stress the spine']::text[],'abs','{}'::text[],'dumbbell',null,null,ARRAY['strength','core']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f66596ba-3a70-406c-8ffa-ed6641a10e19','Dumbbell Side Bend (L)','dumbbell-side-bend-l','Starting position: Stand upright with feet hip-width apart, holding a dumbbell in your right hand while your left hand rests on your hip. Execution: Slowly bend laterally to the right side, allowing the dumbbell to lower toward your knee, then return to the upright starting position.',ARRAY['Stand with feet hip-width apart and hold a dumbbell in your right hand at your side','Place your left hand on your hip for stability and maintain an upright posture','Slowly bend your torso to the right side, letting the dumbbell lower toward your right knee','Keep your core engaged and avoid leaning forward or backward during the movement','Return to the starting position by contracting your left side obliques','Complete all repetitions on one side before switching the dumbbell to the other hand']::text[],ARRAY['Keep the movement strictly in the lateral plane - avoid rotating or leaning forward','Maintain a neutral spine throughout the exercise and avoid excessive bending','Control the weight on both the lowering and lifting phases for maximum effectiveness','Only bend as far as your flexibility allows without compromising form','Focus on feeling the stretch and contraction in your oblique muscles']::text[],'core','{}'::text[],'dumbbell','core',null,ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8dcb1591-348a-4809-9abf-0a1679a7a52a','Dumbbell Side Bend (R)','dumbbell-side-bend-r','Starting position: Stand upright with feet hip-width apart, holding a dumbbell in your right hand with your left hand placed on your hip or behind your head. Execution: Slowly lean your torso to the right side, lowering the dumbbell toward your knee, then return to the starting position by contracting your left oblique muscles.',ARRAY['Stand with feet hip-width apart and hold a dumbbell in your right hand at your side','Place your left hand on your hip or behind your head for stability','Keep your core engaged and maintain a straight back throughout the movement','Slowly lean your torso to the right side, allowing the dumbbell to lower toward your right knee','Focus on feeling the stretch in your left oblique muscles as you descend','Contract your left obliques to return to the starting upright position']::text[],ARRAY['Keep the movement controlled and avoid using momentum or bouncing','Only lean directly to the side - avoid twisting or leaning forward or backward','Maintain neutral spine alignment throughout the entire range of motion','Focus on feeling the stretch and contraction in the oblique muscles rather than just moving the weight','Start with lighter weight to master the form before progressing to heavier loads']::text[],'core','{}'::text[],'dumbbell','core',null,ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','af494781-9fba-41df-b403-79d04db6deae','Dumbbell Side lunge','dumbbell-side-lunge','Starting position: Stand tall with feet hip-width apart, holding a dumbbell with both hands at chest level or one dumbbell in each hand at your sides. Execution: Step one leg out to the side into a wide stance, lower your body by bending the stepping leg while keeping the other leg straight, then push back to the starting position.',ARRAY['Stand with feet hip-width apart and hold dumbbells securely with a firm grip','Take a large step to one side, keeping your torso upright and core engaged','Lower your body by bending the knee of the stepping leg while keeping the opposite leg straight','Descend until your thigh is parallel to the floor or as low as comfortable','Push through the heel of the bent leg to return to the starting position','Repeat for desired reps then switch to the other side']::text[],ARRAY['Keep your chest up and avoid leaning forward excessively to maintain proper spinal alignment','Ensure the knee of the lunging leg tracks in line with your toes and doesn''t cave inward','Control the descent and avoid bouncing at the bottom of the movement','Keep most of your weight on the heel of the working leg rather than the toes','Start with lighter weight to master the movement pattern before progressing to heavier loads']::text[],'quads','{}'::text[],'dumbbell','legs','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bfce2271-bf6b-4a45-9038-5c9fa1935990','Dumbbell Side lunge (L)','dumbbell-side-lunge-l','Starting position: Stand upright with feet hip-width apart, holding a dumbbell with both hands at chest level or a single dumbbell in each hand at your sides. Execution: Step your left foot out to the side into a wide stance, bend your left knee and push your hips back to lower into a lateral lunge, then push through your left heel to return to the starting position.',ARRAY['Stand with feet hip-width apart, holding dumbbells securely with a firm grip','Step your left foot out to the side approximately 2-3 feet, keeping your right leg straight','Lower your body by bending your left knee and pushing your hips back, keeping your chest up and core engaged','Descend until your left thigh is parallel to the floor or as low as your mobility allows','Push through your left heel to return to the starting position','Complete all repetitions on the left side before switching to the right']::text[],ARRAY['Keep your weight on the heel of your lunging leg to properly activate the quadriceps and glutes','Maintain a straight back throughout the movement and avoid letting your knee cave inward','Only descend as far as your hip mobility allows while maintaining proper form','Keep the non-lunging leg straight and planted firmly on the ground for stability','Control the movement on both the descent and ascent to maximize muscle engagement and prevent injury']::text[],'quads','{}'::text[],'dumbbell','legs','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fef72790-359f-4f3f-9fcd-a80fb2c63b5f','Dumbbell Single leg deadlift','dumbbell-single-leg-deadlift','Starting position: Stand upright holding a dumbbell in one hand, with feet hip-width apart and core engaged. Execution: Hinge at the hips while lifting one leg behind you, lowering the dumbbell toward the ground while maintaining a straight back, then return to starting position.',ARRAY['Hold a dumbbell in the hand opposite to the leg you will be lifting','Stand tall with feet hip-width apart and engage your core','Begin the movement by hinging at the hips, pushing your hips back while lifting one leg straight behind you','Lower the dumbbell toward the ground while keeping your back straight and chest up','Keep the standing leg slightly bent and maintain balance throughout the movement','Return to starting position by driving through the standing heel and bringing the lifted leg back down']::text[],ARRAY['Keep your hips square and avoid rotating your pelvis during the movement','Maintain a neutral spine throughout the entire range of motion','Focus on the hip hinge movement rather than just bending forward','Start with lighter weight to master the balance and movement pattern before progressing','Keep the dumbbell close to your body throughout the exercise']::text[],'back','{}'::text[],'dumbbell','back','intermediate',ARRAY['strength','balance','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','14a3a8fe-dc12-4c4b-865b-d5e0514c54d4','Dumbbell Skull Crushers','dumbbell-skull-crushers-b8b89d','Starting position: Lie flat on a bench holding a dumbbell in each hand with arms extended above the chest and palms facing each other. Execution: Bend at the elbows to lower the dumbbells toward the sides of your head, then extend the elbows to press back up to the start.',ARRAY['Lie flat on a bench and hold a dumbbell in each hand with arms extended above your chest.','Keeping upper arms stationary, bend your elbows to lower the dumbbells toward your ears or forehead.','Pause briefly when your forearms reach the stretched position.','Extend your elbows to press the dumbbells back to the starting position.','Squeeze the triceps at the top and repeat for the desired reps.']::text[],ARRAY['Keep your elbows tucked and pointing toward the ceiling throughout.','Move only at the elbow joint, keeping upper arms fixed.','Control the descent to protect the elbows and maximize tension.','Avoid flaring the elbows outward as you press.']::text[],'triceps',ARRAY['forearm_flexors','forearm_extensors','shoulders']::text[],'dumbbell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0de79ddc-e829-4543-942c-e385cc76ac5e','Dumbbell Squat','dumbbell-squat','Starting position: Stand with feet shoulder-width apart, holding a dumbbell with both hands at your sides. Execution: Lower your body by bending at the hips and knees until thighs are parallel to the floor, then drive through your heels to return to the starting position.',ARRAY['Stand with feet shoulder-width apart and hold a dumbbell securely with both hands at your sides.','Keep your chest up, shoulders back, and core engaged throughout the movement','Initiate the squat by pushing your hips back and bending your knees','Lower your body until your thighs are parallel to the floor or as low as your mobility allows','Drive through your heels and squeeze your glutes to return to the starting position','Maintain control of the dumbbell throughout the entire movement']::text[],ARRAY['Keep your knees tracking in line with your toes to prevent inward collapse','Maintain a neutral spine and avoid rounding your back','Keep most of your weight on your heels rather than your toes','Control the descent and avoid bouncing at the bottom of the movement','Keep the dumbbell close to your body to maintain proper balance']::text[],'quads','{}'::text[],'dumbbell','legs',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1b4146bc-1c96-4f05-88cf-72a72783122d','Dumbbell Step Ups','dumbbell-step-ups-62cf41','Starting position: Stand facing a sturdy box holding a dumbbell in each hand at your sides, feet hip-width apart. Execution: Step one foot onto the box, drive through the heel to stand up fully, then control the descent back down and repeat, alternating or completing reps on one leg.',ARRAY['Stand tall in front of the box holding a dumbbell in each hand with arms extended at your sides.','Place one foot fully on top of the box, keeping the knee tracking over the toes.','Drive through the heel of the top foot to press your body up until both legs are near-straight on the box.','Slowly lower the trailing leg back down to the floor with control.','Complete the desired reps then switch legs, keeping your torso upright throughout.']::text[],ARRAY['Drive through the heel of the working leg to emphasize the glutes and quads.','Keep your chest up and core braced to avoid leaning too far forward.','Ensure the entire foot is planted on the box before pushing up.','Control the lowering phase rather than dropping down quickly.']::text[],'quads',ARRAY['glute_max','hamstrings','calves']::text[],'dumbbell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ccd60696-7e2f-4611-b3b9-e5f11ddf4e78','Dumbbell Sumo Squat','dumbbell-sumo-squat-bbef20','Starting position: Stand with feet wider than shoulder-width apart, toes pointed outward at roughly 45 degrees, holding a single dumbbell vertically with both hands in front of your hips. Execution: Bend at the hips and knees to lower into a deep squat until your thighs are parallel to the floor, keeping your chest upright, then drive through your heels to return to standing.',ARRAY['Set your feet wider than shoulder-width with toes turned out and hold the dumbbell with both hands.','Brace your core and keep your chest lifted throughout the movement.','Push your hips back and bend your knees to lower until thighs are parallel to the ground.','Keep your knees tracking in line with your toes as you descend.','Drive through your heels and squeeze your glutes to return to the standing position.','Repeat for the prescribed number of repetitions.']::text[],ARRAY['Keep knees aligned with your toes and prevent them from caving inward.','Maintain a neutral spine with chest up and shoulders back.','Push hips back and keep weight in your heels, not your toes.','Descend to at least parallel for full glute and adductor engagement.']::text[],'glutes',ARRAY['adductors','hamstrings','core']::text[],'dumbbell','strength','beginner',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c3d00969-0a33-4a3f-b603-938c1014ca9f','Dumbbell Thruster','dumbbell-thruster','Starting position: Hold a dumbbell in each hand at shoulder height with elbows bent, feet shoulder-width apart, and core engaged. Execution: Perform a squat by lowering your hips back and down, then explosively drive through your heels to stand while simultaneously pressing the dumbbells overhead in one fluid movement.',ARRAY['Hold dumbbells at shoulder height with palms facing forward and elbows slightly in front of your body','Position feet shoulder-width apart with toes slightly turned out','Lower into a squat by pushing hips back and bending knees until thighs are parallel to the floor','Keep your chest up and weight distributed evenly across your feet throughout the squat','Drive explosively through your heels to stand while simultaneously pressing dumbbells straight overhead','Lower dumbbells back to shoulder height as you prepare for the next repetition']::text[],ARRAY['Maintain a neutral spine throughout the entire movement to prevent back injury','Use your legs to generate power for the overhead press rather than relying solely on your shoulders','Keep the dumbbells close to your body during the transition from squat to press','Ensure full hip extension at the top before pressing the weights overhead','Control the descent of both the squat and the weight return to maintain proper form']::text[],'quads','{}'::text[],'dumbbell','legs','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f1c43226-fa20-4c2e-af66-0cd680f937df','Dumbbell Tricep Kickback','dumbbell-tricep-kickback-6f482a','Starting position: Stand with feet hip-width apart, hinge forward at the hips with a flat back, holding a dumbbell in one hand with the upper arm pinned against your side and the elbow bent at 90 degrees. Execution: Extend the elbow to straighten the arm behind you, squeezing the triceps at full extension, then return under control to the starting bent position.',ARRAY['Hinge forward at the hips keeping your back flat and core braced.','Pin your upper arm against your torso with the elbow bent at 90 degrees.','Extend the elbow to press the dumbbell back until the arm is straight.','Squeeze the triceps hard at full extension.','Slowly lower the dumbbell back to the starting position.','Complete all reps on one arm before switching sides.']::text[],ARRAY['Keep the upper arm stationary and parallel to the floor throughout.','Move only at the elbow joint, avoiding swinging or momentum.','Maintain a neutral spine and braced core to protect the lower back.','Fully extend and squeeze at the top for maximum triceps activation.']::text[],'triceps',ARRAY['rear_deltoids','forearm_extensors','core']::text[],'dumbbell','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','01924d84-4c88-4476-b0dc-8fd92616b362','Dumbbell upper cuts','dumbbell-upper-cuts','Starting position: Stand with feet shoulder-width apart, holding a dumbbell in each hand at chest level with palms facing up and elbows bent at 90 degrees. Execution: Alternate punching upward in a diagonal motion while rotating your torso, extending one arm at a time as if throwing an uppercut punch.',ARRAY['Stand with feet shoulder-width apart, holding a dumbbell in each hand at chest level with palms facing your body','Engage your core and slightly bend your knees in an athletic stance','Rotate your torso to the right while simultaneously driving your left hand upward in an uppercut motion, extending through your legs and core','Return to starting position with control, then rotate left while driving your right hand up in an uppercut','Continue alternating sides in a smooth, controlled rhythm while maintaining proper form','Complete the desired number of repetitions, ensuring equal work on both sides']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Generate power from your legs and torso rotation, not just your arms','Maintain control during both the upward drive and return phases to maximize muscle engagement','Start with lighter weights to master the coordination before progressing to heavier dumbbells','Keep your non-working hand close to your body for balance and protection']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3175c898-09fe-4d02-82c2-de2a3834fdd4','Dumbbell waiter curls','dumbbell-waiter-curls','Starting position: Stand upright holding a dumbbell vertically with both hands underneath the top weight plate, arms extended in front of your body. Execution: Curl the dumbbell up by flexing your biceps while keeping your elbows stationary, then slowly lower back to the starting position.',ARRAY['Stand with feet shoulder-width apart and core engaged for stability','Grip the dumbbell with both hands under the top weight plate, palms facing up','Keep your elbows close to your sides and stationary throughout the movement','Curl the weight up by contracting your biceps until your forearms are vertical','Slowly lower the dumbbell back to the starting position with control','Maintain the vertical position of the dumbbell throughout the entire movement']::text[],ARRAY['Keep the dumbbell in a vertical position at all times to maintain proper grip and safety','Focus on controlled movement rather than speed to maximize muscle engagement','Avoid swinging or using momentum - the movement should come from your biceps only','Keep your wrists straight and grip secure to prevent the dumbbell from slipping','Maintain good posture with shoulders back and core tight throughout the exercise']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6891aa71-6e1f-4ea4-b9ac-f38ea207216a','Dumbbell wrist curls','dumbbell-wrist-curls1','Starting position: Stand upright holding dumbbells at your sides with arms extended down and palms facing forward. Execution: Keep your upper arms and body stationary while flexing your wrists upward to curl the weights, then slowly lower back to the starting position.',ARRAY['Stand with feet shoulder-width apart, holding a dumbbell in each hand with arms hanging naturally at your sides','Keep your upper arms pressed against your torso and avoid swinging or using momentum','Flex your wrists upward by curling the dumbbells as high as possible while keeping your forearms stationary','Hold the contracted position briefly to maximize muscle engagement','Slowly lower the weights back to the starting position with control','Maintain proper posture throughout the movement with shoulders back and core engaged']::text[],ARRAY['Keep all movement isolated to the wrists and forearms - avoid using your biceps or shoulders','Use a controlled tempo, especially on the lowering phase to maximize muscle development','Start with lighter weights as forearm muscles fatigue quickly and proper form is crucial','Maintain a firm grip on the dumbbells throughout the entire range of motion','Keep your wrists in a neutral position at the bottom to avoid hyperextension']::text[],'forearms','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9a8e40b3-446f-4362-9df4-461931927889','Dumbbell wrist curls','dumbbell-wrist-curls','Starting position: Sit on a bench with your forearms resting on your thighs, holding a dumbbell in each hand with your wrists hanging over your knees and palms facing up. Execution: Slowly curl your wrists upward by flexing your forearms, then lower the weight back down in a controlled manner.',ARRAY['Sit on a bench with your feet flat on the floor and forearms resting comfortably on your thighs','Hold dumbbells with an underhand grip, allowing your wrists to extend beyond your knees','Keep your forearms pressed against your thighs throughout the entire movement','Curl your wrists upward as high as possible while squeezing your forearms','Lower the dumbbells slowly back to the starting position with your wrists extended','Maintain constant tension and avoid using momentum or bouncing motions']::text[],ARRAY['Keep your forearms stationary and pressed against your thighs to isolate the forearm muscles','Use light weight initially as forearm muscles are smaller and can be easily strained','Focus on the full range of motion from complete wrist extension to maximum flexion','Perform the movement slowly and controlled to maximize muscle activation and prevent injury','Stop immediately if you experience any sharp pain or numbness in your wrists or hands']::text[],'forearms','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1b670f12-2b3b-4046-8fb8-379450db6f52','Dumbell Bench Press','dumbell-bench-press-220b34','Starting position: Lie flat on a bench with feet planted on the floor, holding a dumbbell in each hand at chest level with palms facing forward. Execution: Press the dumbbells upward until arms are fully extended, then lower them back to chest level under control.',ARRAY['Lie flat on the bench with your back supported and feet firmly planted on the ground.','Hold a dumbbell in each hand at chest height with palms facing toward your feet.','Press the dumbbells upward until your arms are nearly fully extended over your chest.','Pause briefly at the top without locking out the elbows.','Lower the dumbbells slowly back to the starting position at chest level.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your wrists straight and directly above your elbows throughout the movement.','Maintain contact between your back and the bench, avoiding excessive arching.','Control the descent rather than letting the weights drop.','Keep your feet flat on the floor for a stable base.']::text[],'chest',ARRAY['front_deltoids','triceps','serratus_anterior']::text[],'dumbbell','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','75f26166-ba61-48cf-ba27-0709fbdbb34b','Dumbell Straight Leg Raise','dumbell-straight-leg-raise-1ceacd','Starting position: Lie flat on your back on a mat with your arms extended straight up toward the ceiling holding a dumbbell, and your legs extended straight out along the floor. Execution: Keeping your legs straight, raise one or both legs upward toward the ceiling while maintaining the dumbbell held stable overhead, then lower with control back toward the floor without letting the feet touch down.',ARRAY['Lie supine on the mat with arms extended vertically holding a dumbbell and legs straight.','Brace your core and press your lower back into the mat.','Raise your legs upward keeping them as straight as possible until near vertical.','Lower your legs slowly under control without touching the floor.','Repeat for the desired number of repetitions maintaining the dumbbell stable overhead.']::text[],ARRAY['Keep your lower back pressed into the mat to protect your spine.','Move your legs slowly and avoid using momentum.','Keep your legs as straight as possible throughout the movement.','Maintain a stable, locked-out arm position with the dumbbell.']::text[],'lower_abs',ARRAY['obliques','iliopsoas','transverse_abdominis']::text[],'dumbbell','core','intermediate',ARRAY['core','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4f756a6f-51a5-4afe-8cf8-975f3748c4f9','Elbow Plank to Side Plank','elbow-plank-to-side-plank-524950','Starting position: Begin in a forearm plank with elbows directly under the shoulders, forearms parallel, legs extended, and body forming a straight line from head to heels. Execution: Rotate onto one forearm while stacking the feet and hips, lifting the top arm toward the ceiling into a side plank, then return to the elbow plank and repeat on the opposite side.',ARRAY['Set up in an elbow plank with elbows under your shoulders and body in a straight line.','Brace your core and shift your weight onto one forearm.','Rotate your hips and stack your feet as you turn into a side plank.','Extend the top arm upward and hold briefly, keeping hips lifted.','Return to the center elbow plank with control.','Repeat on the opposite side, alternating evenly.']::text[],ARRAY['Keep your body in a straight line without sagging or piking the hips.','Engage your obliques to control the rotation rather than swinging.','Keep the supporting shoulder stable and away from your ear.','Breathe steadily and avoid holding your breath during transitions.']::text[],'core',ARRAY['rectus_abdominis','erector_spinae','quads']::text[],'bodyweight','core','intermediate',ARRAY['core','isometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f2224eab-4368-4bab-80a3-e0bddbed5a23','Elbow to knee plank','elbow-to-knee-plank','Starting position: Begin in a forearm plank position with elbows directly under shoulders, forearms on the ground, and body in a straight line from head to heels. Execution: Alternately bring each knee toward the same-side elbow while maintaining the plank position, then return to starting position and repeat on the opposite side.',ARRAY['Start in a forearm plank with elbows under shoulders and body in a straight line','Engage your core and maintain neutral spine alignment','Bring your right knee toward your right elbow in a controlled motion','Return your right leg to starting position maintaining stability','Alternate by bringing your left knee toward your left elbow','Continue alternating sides while keeping your core engaged throughout']::text[],ARRAY['Keep your hips level and avoid rotating your torso during the knee-to-elbow movement','Maintain a strong plank position throughout - don''t let your hips sag or pike up','Focus on controlled movements rather than speed to maximize core engagement','Keep your supporting leg straight and engaged while performing the knee drive','Breathe steadily and avoid holding your breath during the exercise']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b958f3b6-db0c-492a-8895-445af0989161','Elevated Calf Raises','elevated-calf-raises-c8df17','Starting position: Stand on an elevated surface with balls of feet on edge, heels hanging off. Execution: Rise up onto toes by contracting calves, then lower heels below platform level.',ARRAY['Stand on elevated surface with forefoot on edge','Let heels drop below the platform level','Rise up high onto your toes','Squeeze calf muscles at the top position','Lower heels slowly below starting position','Repeat the movement in controlled manner']::text[],ARRAY['Keep your body straight and avoid bouncing during the movement','Use a wall or railing for balance if needed','Focus on getting full range of motion by dropping heels low','Control the lowering phase to maximize muscle engagement','Stop if you feel sharp pain in your Achilles tendon']::text[],'bodyweight','{}'::text[],'bodyweight',null,null,ARRAY['calisthenics','strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3b3e0a86-56b7-4d15-92ff-11dfaf108147','Elevated push up','elevated-push-up','Starting position: Place your feet on an elevated surface like a bench or step, with hands on the ground shoulder-width apart in a plank position. Execution: Lower your chest toward the ground by bending your elbows, then push back up to the starting position.',ARRAY['Position your feet on a stable elevated surface 12-24 inches high with toes pointing down','Place your hands on the ground shoulder-width apart, directly under your shoulders','Maintain a straight line from your head to your heels throughout the movement','Lower your chest toward the ground until your elbows reach about 90 degrees','Push through your palms to return to the starting position with control','Keep your core engaged and avoid letting your hips sag or pike up']::text[],ARRAY['This variation increases the difficulty by shifting more weight to your upper body and targeting the upper chest','Start with a lower elevation and gradually increase height as you build strength','Maintain proper form over speed - focus on controlled movements rather than rushing through repetitions','Stop immediately if you feel shoulder pain or cannot maintain proper body alignment','Ensure the elevated surface is stable and won''t slip during the exercise']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0501fca5-dd00-4948-8874-40cc851daaee','Explosive jump squats','explosive-jump-squats','Starting position: Stand with feet shoulder-width apart, toes slightly turned out, and arms at your sides or positioned in front of your chest. Execution: Lower into a squat position then explosively jump straight up, extending through your hips and knees, landing softly back into the squat position.',ARRAY['Start in squat position','Explode up, jumping off floor','Land softly with bent knees','Immediately descend into next squat']::text[],ARRAY['Land softly (quiet landings)','Absorb impact with legs','Don''t lock knees on landing','Power comes from legs and hips','Great for explosive power']::text[],'quads',ARRAY['calves','core','hamstrings']::text[],'bodyweight','legs','intermediate',ARRAY['plyometric','cardio']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4c22f102-513b-4fe4-a271-389c006fbb9f','Explosive knee drive','explosive-knee-drive','Starting position: Stand with feet hip-width apart, arms at your sides, with one foot slightly behind the other in a staggered stance. Execution: Explosively drive the back knee up toward your chest while simultaneously pumping your arms, then return to starting position and repeat before switching legs.',ARRAY['Begin in a staggered stance with your right foot forward and left foot back, maintaining good posture with core engaged','Explosively drive your left knee up toward your chest as high as possible while pumping your right arm forward and left arm back','Land softly on the ball of your standing foot while controlling the descent of the driving leg','Immediately repeat the explosive knee drive for the prescribed repetitions on one side','Switch leg positions and perform the same number of repetitions with the opposite knee driving up','Maintain a steady rhythm while focusing on maximum height and speed with each knee drive']::text[],ARRAY['Keep your core tight throughout the movement to maintain balance and proper posture','Focus on explosive power rather than speed - each knee drive should be performed with maximum effort','Land softly on the ball of your standing foot to reduce impact and maintain control','Pump your arms in opposition to create momentum and improve coordination','Start with shorter sets and gradually increase repetitions as your cardiovascular fitness and leg strength improve']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','74658f21-21bb-40f6-bf66-54aa7b499622','Explosive push','explosive-push','Starting position: Begin in a standard push-up position with hands placed slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Lower your chest toward the ground, then explosively push up with maximum force so your hands leave the ground, land softly and immediately transition into the next repetition.',ARRAY['Start in a proper push-up position with core engaged and body aligned','Lower yourself slowly and under control until chest nearly touches the ground','Explosively push through your palms with maximum force to launch your upper body off the ground','Keep your body rigid and hands ready to catch yourself as you land','Land softly with slightly bent elbows to absorb impact','Immediately lower into the next repetition without pausing']::text[],ARRAY['Only attempt this exercise if you can perform at least 15 standard push-ups with proper form','Focus on explosive upward movement while maintaining control during the lowering phase','Land with soft elbows and engaged core to prevent injury upon impact','Start with lower repetitions and build up gradually as this is highly demanding on joints and muscles','Stop immediately if you cannot maintain proper landing form or feel joint discomfort']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','67b6f81b-3bca-4b91-8cd8-4c4dd6194d6e','Explosive push ups','explosive-push-ups','Starting position: Begin in a standard push-up position with hands slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Lower your chest toward the ground, then explosively push up with enough force that your hands leave the ground briefly before catching yourself and returning to the starting position.',ARRAY['Start in a standard push-up position with proper form and engage your core','Lower your body slowly and under control until your chest nearly touches the ground','Explosively push up through your hands with maximum force to propel your upper body off the ground','Keep your hands ready to catch yourself as you land softly back in the starting position','Maintain straight body alignment throughout the entire movement','Rest adequately between repetitions to maintain explosive power']::text[],ARRAY['Land softly with slightly bent elbows to absorb impact and protect your joints','Focus on generating maximum power from the bottom position rather than rushing through repetitions','Master regular push-ups with perfect form before attempting explosive variations','Stop immediately if you experience any wrist, shoulder, or chest discomfort','Progress gradually by starting with smaller explosive movements before attempting full airtime']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['plyometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d9df1e94-1051-407d-9c34-87720d1557a9','Explosive side to side push up','explosive-side-to-side-push-up','Starting position: Begin in a standard push-up position with hands placed wider than shoulder-width apart, body in a straight line from head to heels. Execution: Explosively push up from the bottom position while shifting your body laterally to one side, land softly, then immediately transition to the other side with each repetition.',ARRAY['Start in a wide push-up position with hands placed wider than shoulder-width apart','Lower your chest toward the ground while maintaining a straight body line','Explosively push up from the bottom position, generating enough force to shift your body to one side','Land softly with control, absorbing the impact through your arms and core','Immediately transition into the next push-up, shifting to the opposite side','Maintain proper push-up form throughout the lateral movement']::text[],ARRAY['Keep your core engaged throughout the entire movement to maintain body alignment','Land softly to reduce impact on wrists and shoulders','Start with smaller lateral movements and progress to larger shifts as you build strength','Ensure you have adequate space on both sides before beginning the exercise','Focus on explosive power during the push phase while maintaining control during the landing']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['plyometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','022ea5f2-88f3-4d42-b99d-c1026d6bc343','Explosive sprinter lunge (left)','explosive-sprinter-lunge-left','Starting position: Begin in a low lunge position with your left foot forward, right knee down, and hands on the ground for support. Execution: Explosively drive through your left leg while simultaneously extending your right arm up and back, creating a dynamic stretching movement through the hip flexors and engaging the core.',ARRAY['Start in a low lunge with left foot forward, right knee on the ground, and both hands placed on the mat for stability','Keep your left knee aligned over your ankle and maintain a straight back throughout the movement','Explosively drive up through your left leg while simultaneously reaching your right arm up and back','Feel the stretch through your right hip flexor as you extend upward','Control the movement back to the starting position','Repeat for desired repetitions before switching sides']::text[],ARRAY['Keep your front knee tracking over your toes to protect the knee joint','Engage your core throughout the movement to maintain balance and stability','Focus on the explosive upward drive while maintaining control on the return','Ensure your back leg''s hip flexor gets a good stretch during the extension phase','Land softly when returning to the starting position to minimize impact on the joints']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d5dff683-d9a5-42ca-b325-47f7275f7def','Explosive sprinter lunge (right)','explosive-sprinter-lunge-right','Starting position: Stand tall with feet hip-width apart, hands at your sides or in front of your chest. Execution: Explosively jump forward into a deep lunge position with your right foot forward, land softly with control, then powerfully drive back to the starting position.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Take a large explosive jump forward, landing with your right foot ahead and left foot behind','Land in a deep lunge position with your right thigh parallel to the ground and left knee hovering just above the floor','Keep your torso upright and weight evenly distributed between both legs','Push explosively off your right foot to return to the starting position','Land softly on both feet before repeating the movement']::text[],ARRAY['Focus on landing softly with bent knees to absorb impact and protect your joints','Keep your front knee aligned over your ankle, never allowing it to cave inward','Maintain an upright torso throughout the movement to prevent excessive forward lean','Generate power from your glutes and quads when exploding back to the starting position','Start with smaller jumps and gradually increase distance as you master the movement pattern']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','61ef551f-2db3-4ab9-978d-9e5712b873de','Extended side angle pose (left)','extended-side-angle-pose-left','Starting position: Begin in a wide-legged standing position with left foot turned out 90 degrees and right foot slightly angled inward, then bend the left knee into a side lunge position. Execution: Lower your left forearm to rest on your left thigh while extending your right arm overhead, creating a long line from your right fingertips to your right heel.',ARRAY['From Warrior II, bring your front forearm to rest on your front thigh.','Extend your top arm overhead, creating a line from back foot to fingertips.','Turn your chest toward the ceiling.','Hold and breathe deeply.']::text[],ARRAY['Keep your front knee over the ankle.','Press firmly through the outer edge of your back foot.','Do not collapse onto the front thigh.']::text[],'quads','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5f8e2c01-66eb-4f23-b3ad-c87c631e257f','Extended side angle pose (right)','extended-side-angle-pose-right','Starting position: Stand with feet wide apart, turn right foot out 90 degrees and left foot slightly inward, then bend right knee into a side lunge while keeping left leg straight. Execution: Lower right forearm to right thigh and extend left arm over head, creating a straight line from left fingertips to left heel while holding the stretched position.',ARRAY['From Warrior II, bring your front forearm to rest on your front thigh.','Extend your top arm overhead, creating a line from back foot to fingertips.','Turn your chest toward the ceiling.','Hold and breathe deeply.']::text[],ARRAY['Keep your front knee over the ankle.','Press firmly through the outer edge of your back foot.','Do not collapse onto the front thigh.']::text[],'quads','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5a86b7dd-04a3-47fc-b92d-910f61b184c6','EZ Bar Curl','ez-bar-curl-10f0eb','Starting position: Stand upright holding an EZ curl bar with a shoulder-width underhand grip on the angled portions, arms extended down and elbows close to your torso. Execution: Curl the bar upward by flexing the elbows, keeping the upper arms stationary, then lower under control back to the starting position.',ARRAY['Grip the EZ bar on the angled sections with palms facing up and stand tall with feet shoulder-width apart.','Keep your elbows pinned close to your sides and brace your core.','Curl the bar toward your shoulders by contracting the biceps without swinging.','Pause and squeeze at the top of the movement.','Lower the bar slowly back to full extension.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your elbows fixed and avoid swinging or using momentum.','Maintain a neutral spine and engaged core throughout.','Control the lowering phase for maximum muscle tension.','The angled grip reduces wrist strain compared to a straight bar.']::text[],'biceps',ARRAY['brachialis','brachioradialis','forearm_flexors']::text[],'barbell','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b78e6b13-cc46-49d6-a205-f71b65e6090e','EZ Bar Reverse Curl','ez-bar-reverse-curl-cdf9c6','Starting position: Stand upright holding an EZ bar with a pronated (overhand) grip on the angled sections, arms extended down, elbows tucked close to your torso. Execution: Curl the bar upward by flexing the elbows while keeping the palms facing down, squeeze at the top, then lower under control back to the start.',ARRAY['Grip the EZ bar overhand with palms facing down and stand tall with feet shoulder-width apart.','Keep your elbows pinned to your sides and core braced.','Curl the bar up toward your chest by flexing the elbows without swinging.','Pause briefly and squeeze the forearms and brachialis at the top.','Lower the bar slowly and under control to full arm extension.','Repeat for the desired number of repetitions.']::text[],ARRAY['Maintain a pronated grip throughout to target the brachioradialis and forearm extensors.','Keep elbows stationary and avoid using momentum or leaning back.','Control the eccentric lowering phase for maximum tension.','Keep wrists firm and neutral to protect the joints.']::text[],'brachioradialis',ARRAY['biceps','forearm_flexors','front_deltoids']::text[],'barbell','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9ad86735-3149-48fa-add4-705598dc149e','Farmers walk','farmers-walk','Starting position: Stand upright with feet hip-width apart, holding heavy objects (water jugs, bags, or suitcases) at your sides with arms fully extended. Execution: Walk forward in a controlled manner while maintaining grip on the objects and keeping your core engaged throughout the movement.',ARRAY['Find two heavy household objects of equal weight such as water jugs, heavy bags, or suitcases','Stand tall with the objects at your sides, arms straight and shoulders pulled back','Engage your core and maintain neutral spine alignment before beginning movement','Walk forward with normal stride length while gripping the objects tightly','Focus on maintaining upright posture throughout the entire walking distance','Set objects down safely by bending at hips and knees, not rounding your back']::text[],ARRAY['Keep shoulders back and avoid letting them roll forward as grip strength fatigues','Maintain a firm grip throughout the exercise to maximize forearm engagement','Start with lighter weights and shorter distances, gradually increasing as strength improves','Stop immediately if you feel your grip failing to prevent dropping the objects','Breathe normally and avoid holding your breath during the movement']::text[],'forearms','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','53339dca-7ed1-4edf-b88c-1f4b618b4d57','Figure 4 Squats','figure-4-squats-dfd222','Starting position: Stand tall on one leg with the opposite ankle crossed over the standing thigh just above the knee, forming a figure-4 shape, hands clasped at chest for balance. Execution: Hinge at the hips and bend the standing knee to lower into a single-leg squat, then drive through the heel to return to standing while maintaining the crossed-leg position.',ARRAY['Balance on one leg and cross the opposite ankle over your standing thigh above the knee.','Clasp your hands at chest level and brace your core for stability.','Push your hips back and bend the standing knee to lower into a squat.','Descend until your thigh approaches parallel while keeping the chest lifted.','Drive through the standing heel to extend the hip and knee back to the start.','Complete all reps, then switch to the other leg.']::text[],ARRAY['Keep the standing knee tracking over the toes, not caving inward.','Maintain an upright chest and engaged core throughout the movement.','Push the hips back to load the glutes rather than dropping straight down.','Control the descent and avoid rushing to keep balance stable.']::text[],'glutes',ARRAY['adductors','calves','abductors']::text[],'bodyweight','strength','intermediate',ARRAY['strength','functional','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f3d25890-dcd5-42b3-8246-a5f596029cc0','Figure Four Stretch (L)','figure-four-stretch-l','Starting position: Lie on your back with knees bent and feet flat on the floor, then place your left ankle on top of your right thigh just above the knee. Execution: Thread your hands behind your right thigh and gently pull your right leg toward your chest while keeping your left knee pressed away from your body.',ARRAY['Lie on your back with both knees bent and feet flat on the floor','Place your left ankle on top of your right thigh, just above the knee','Thread your hands behind your right thigh, interlacing your fingers','Gently pull your right leg toward your chest while keeping your back flat on the ground','Use your left elbow to gently press your left knee away from your body to deepen the stretch','Hold the stretch for 20-30 seconds while breathing deeply']::text[],ARRAY['Keep your lower back pressed against the floor throughout the entire stretch','Never force the stretch - only pull to a comfortable tension level','Focus on pressing the knee of the crossed leg away from your body rather than pulling harder with your arms','Breathe steadily and relax into the stretch rather than holding your breath','Stop immediately if you feel any sharp pain in your hip or lower back']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','005ba868-d8b1-499f-9a88-b2cf722e6bdf','Figure Four Stretch (R)','figure-four-stretch-r','Starting position: Lie on your back with knees bent and feet flat on the floor, then place your right ankle on top of your left knee creating a figure-four shape. Execution: Reach through the gap between your legs to grasp behind your left thigh and gently pull your left knee toward your chest while keeping your head and shoulders relaxed on the ground.',ARRAY['Lie on your back with both knees bent and feet flat on the floor','Lift your right leg and place your right ankle on top of your left thigh, just above the knee','Reach through the gap between your legs and clasp your hands behind your left thigh','Gently pull your left thigh toward your chest while keeping your head and shoulders relaxed on the ground','Hold the stretch for 20-30 seconds, feeling the stretch in your right hip and glute','Release slowly and repeat on the opposite side']::text[],ARRAY['Keep your right foot flexed to protect your knee joint','Don''t force the stretch - use gentle, steady pressure','Keep your lower back pressed against the floor throughout the movement','If you can''t reach behind your thigh, use a towel or strap for assistance','Stop immediately if you feel any knee pain']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','05b2ec0e-92d4-4a93-bfed-c371747c072d','Fire Hydrant','fire-hydrant-9808a0','Starting position: Begin on all fours in a quadruped position with hands stacked under the shoulders and knees under the hips, maintaining a neutral spine and braced core. Execution: Keeping the knee bent at 90 degrees, lift one leg out to the side up to hip height, then lower it back down with control without shifting the torso.',ARRAY['Set up on all fours with hands under shoulders and knees under hips.','Brace your core and keep a flat, neutral back.','Keeping the knee bent, raise one leg out to the side toward hip height.','Pause briefly at the top and squeeze the glute.','Lower the leg back to the start with control.','Complete all reps on one side before switching legs.']::text[],ARRAY['Keep hips level and avoid rotating the torso as you lift.','Maintain a 90-degree bend in the working knee throughout.','Move slowly and control the motion rather than swinging the leg.','Keep the supporting arms firm and shoulders stable.']::text[],'glutes',ARRAY['obliques','tensor_fasciae_latae','quads']::text[],'bodyweight','strength','beginner',ARRAY['strength','functional','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f79d8c98-d6ca-4d46-9704-6d89cf436808','Fire Hydrant Circles','fire-hydrant-circles-c96225','Starting position: Begin on all fours in a quadruped position with hands stacked under shoulders and knees under hips, keeping a neutral spine and braced core. Execution: Lift one knee out to the side keeping it bent at 90 degrees, then draw circles with the knee in a controlled circular motion while maintaining a stable torso, completing the reps before switching sides.',ARRAY['Set up on all fours with hands beneath shoulders and knees beneath hips.','Brace your core and keep your spine neutral throughout the movement.','Raise one bent knee out to the side to hip height.','Move the raised leg in a slow, controlled circular motion.','Complete the desired reps then reverse the direction of the circles.','Lower the leg and repeat on the opposite side.']::text[],ARRAY['Keep your hips square and avoid rotating the torso as you circle.','Maintain a 90-degree bend in the working knee throughout.','Move slowly and with control rather than using momentum.','Keep the core engaged to protect the lower back.']::text[],'glute_med',ARRAY['obliques','quads','erector_spinae']::text[],'bodyweight','mobility','beginner',ARRAY['mobility','strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','623b2443-bc73-4c61-986c-412545c33aed','Fire log pose (left)','fire-log-pose-left','Starting position: Sit on the mat with both legs bent and positioned parallel to each other, creating a ''fire log'' or double pigeon shape with your shins stacked. Execution: Hold this static hip-opening position while maintaining an upright torso and breathing deeply.',ARRAY['Sit on your mat with your left leg in front, knee bent at 90 degrees with the shin parallel to the front edge of your mat','Place your right leg on top, stacking the right shin directly over the left shin with both knees bent','Keep both feet flexed to protect your knee joints','Sit tall with your spine straight and hands resting on your shins or the floor','Hold the position for 30-60 seconds while breathing deeply','To release, carefully lift the top leg and extend both legs forward']::text[],ARRAY['Keep both feet flexed throughout the pose to protect your knees from strain','If your hips are tight, sit on a bolster or folded blanket to elevate your pelvis','Never force your knees down - let gravity and time create the opening','Stop immediately if you feel any sharp pain in your knees or hips','Focus on sitting tall rather than folding forward to maintain proper alignment']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e0a7528b-5d24-4ddf-9d4c-d61958dc504c','Fire log pose (right)','fire-log-pose-right','Starting position: Sit on the mat with both legs bent, right shin parallel to the front edge of the mat and left shin parallel to the left side of the mat, creating a stacked log position. Execution: Maintain this seated position while breathing deeply and allowing the hips to relax and open.',ARRAY['Sit on your mat and bend both knees, positioning your right shin parallel to the front edge of the mat','Place your left leg so the shin is parallel to the left side of your mat, creating two parallel lines like stacked logs','Rest your hands on the mat in front of you for support','Keep your spine tall and shoulders relaxed','Hold the position while taking slow, deep breaths','Focus on allowing your hips to gradually release and open']::text[],ARRAY['Keep both sitting bones grounded on the mat throughout the pose','Avoid forcing the stretch - let gravity naturally deepen the hip opening','If you feel discomfort in the knees, place a cushion or block under the elevated hip','Maintain an upright posture rather than collapsing forward','This pose targets deep hip flexors and external rotators for improved mobility']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','87820d5e-9377-493c-a924-cc1d4750859b','First Toe Curl with Towel','first-toe-curl-with-towel-644f3e','Starting position: Sit upright in a chair with your feet flat on the floor and a small towel laid flat under your toes. Keep your posture tall and hands resting on your thighs. Execution: Curl your toes to grip and scrunch the towel, drawing it toward you, then relax and repeat to strengthen the intrinsic foot muscles.',ARRAY['Sit tall in a chair with both feet flat on the floor and place a towel under your toes.','Keep your heel planted and curl your toes to grip and pull the towel toward you.','Scrunch the towel gradually, gathering it under the arch of your foot.','Release the towel and flatten it back out, then repeat the curling motion.','Perform the desired repetitions on one foot before switching sides.']::text[],ARRAY['Keep your heel firmly planted throughout the movement.','Focus on curling from the toes, not sliding the whole foot.','Move slowly and with control to fully engage the foot muscles.','Maintain an upright posture and avoid leaning forward.']::text[],'forearm_flexors',ARRAY['tibialis_anterior','peroneals','soleus']::text[],'towel','physio','beginner',ARRAY['rehabilitation','mobility','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3b45e42a-963f-4b79-ae1d-b1b5e8eb9add','Flat Cable Fly','flat-cable-fly','Starting position: Lie flat on a bench positioned between two cable towers, grasping the cable handles with arms extended above your chest. Execution: Lower the handles in a wide arc out to your sides until you feel a stretch in your chest, then bring them back together above your chest in a controlled flying motion.',ARRAY['Position the bench centered between two cable towers and set the cables at chest height','Lie flat on the bench and grasp both cable handles with a neutral grip','Start with arms extended above your chest, maintaining a slight bend in your elbows','Lower the handles out to your sides in a wide arc, keeping the elbow bend constant','Stop when you feel a good stretch in your chest muscles','Bring the handles back together above your chest using your chest muscles']::text[],ARRAY['Keep a slight bend in your elbows throughout the entire movement to protect your joints','Control the weight on both the lowering and lifting phases - avoid letting the cables snap back','Focus on squeezing your chest muscles as you bring the handles together at the top','Don''t lower the weight too far - stop when you feel a comfortable stretch in your chest','Maintain proper shoulder blade positioning by keeping them pulled back against the bench']::text[],'chest','{}'::text[],'cable','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','704e9540-7bdd-4dbd-bdd3-7341b3563693','Floor Mantis','floor-mantis-7c297d','Starting position: Lie face down on the mat with your legs extended, feet together, and arms bent so your hands are near your head or reaching forward along the mat. Keep your forehead close to the ground and your neck neutral. Execution: Simultaneously lift your chest, arms, and legs off the mat by contracting your lower back and glutes, sweeping your arms in a controlled mantis-like motion, then lower back down with control and repeat.',ARRAY['Lie prone with legs extended and arms bent alongside your head.','Engage your core and squeeze your glutes to stabilize your spine.','Lift your chest, arms, and thighs off the mat by contracting your lower back.','Sweep your arms forward and back in a controlled motion at the top.','Hold briefly, then lower everything back down with control.','Repeat for the desired number of repetitions without jerking.']::text[],ARRAY['Keep your neck in line with your spine to avoid straining the cervical area.','Initiate the lift from your lower back and glutes, not by yanking with your arms.','Move slowly and avoid using momentum to raise your torso.','Keep your legs together and toes pointed for consistent tension.']::text[],'lower_back',ARRAY['hamstrings','glute_max','lats']::text[],'bodyweight','core','beginner',ARRAY['strength','core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d536723e-7e3f-460d-a6c5-e9993bfbec4c','Floor Press','floor-press','Starting position: Lie flat on your back with knees bent, feet flat on the floor, and arms extended straight up toward the ceiling with palms facing forward. Execution: Lower your arms out to the sides until your upper arms touch the floor, then press back up to the starting position by squeezing your chest muscles.',ARRAY['Lie on your back with knees bent and feet planted firmly on the floor for stability','Extend your arms straight up toward the ceiling with palms facing forward and hands positioned slightly wider than shoulder-width','Slowly lower your arms out to the sides in a controlled arc motion until your upper arms gently touch the floor','Keep a slight bend in your elbows throughout the entire movement to protect your joints','Press your arms back up to the starting position by squeezing your chest muscles together','Maintain steady breathing, exhaling as you press up and inhaling as you lower down']::text[],ARRAY['Keep your core engaged and lower back pressed against the floor throughout the movement','Focus on feeling the stretch in your chest muscles at the bottom position without forcing the range of motion','Maintain control during both the lowering and pressing phases - avoid bouncing off the floor','Keep your shoulders pulled back and down to maintain proper shoulder blade position','Start with a comfortable range of motion and gradually increase as flexibility improves']::text[],'chest','{}'::text[],'barbell','chest','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b867d101-cc16-42ff-a057-fe0de4a2d8c6','Flutter kicks','flutter-kicks','Starting position: Lie flat on your back with legs extended, hands placed under your lower back or by your sides for support, and shoulders slightly lifted off the ground. Execution: Alternately lift and lower each leg in small, quick movements while keeping your core engaged and maintaining the flutter motion.',ARRAY['Lie on back, hands under hips','Legs straight, slightly off floor','Kick legs up and down alternately','Keep lower back pressed to floor']::text[],ARRAY['Small controlled movements','Lower back stays down','Keep legs straight','Breathe throughout','Targets lower abs']::text[],'core',ARRAY['hip_flexors','quads','obliques']::text[],'bodyweight','core','beginner',ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b3fdc5d4-1225-4f12-8b42-86fc0617aeb6','Forward and backward lunge','forward-and-backward-lunge','Starting position: Stand upright with feet hip-width apart, hands on hips or at sides for balance. Execution: Step one leg forward or backward into a lunge position, lower your body until both knees are bent at 90 degrees, then push back to the starting position and repeat with the other leg.',ARRAY['Stand tall with feet hip-width apart and engage your core for stability','For forward lunge, step one foot forward 2-3 feet, keeping your torso upright','Lower your body by bending both knees until your front thigh is parallel to the floor and back knee nearly touches the ground','Push through your front heel to return to the starting position','For backward lunge, step one foot back 2-3 feet and follow the same lowering and rising motion','Alternate legs or complete all reps on one side before switching']::text[],ARRAY['Keep your front knee aligned over your ankle, never allowing it to push forward past your toes','Maintain an upright torso throughout the movement to avoid leaning forward','Distribute weight evenly between both legs during the lowering phase','Control the descent and avoid bouncing at the bottom of the movement','Start with shorter steps and gradually increase range of motion as flexibility improves']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','18dda540-eca8-40ad-aca4-9e5f80f574d7','Forward Backward Hop over Cone','forward-backward-hop-over-cone-4ac1d9','Starting position: Stand upright with feet together behind a cone, knees slightly bent, hands held up near the chest and core braced. Execution: Explosively hop forward over the cone with both feet, land softly, then immediately hop backward over the cone to return to the starting position, maintaining a quick continuous rhythm.',ARRAY['Stand tall behind the cone with feet together, knees soft and hands up at chest height.','Bend your knees and swing your arms to load for the jump.','Explosively hop forward over the cone landing softly on the balls of your feet.','Immediately reverse the motion and hop backward over the cone to the start.','Keep a steady, rapid rhythm and repeat for the desired number of reps.']::text[],ARRAY['Land softly with bent knees to absorb impact and protect your joints.','Keep your core braced and torso upright throughout the movement.','Use your arms to generate momentum and stay balanced.','Maintain a quick, controlled tempo without sacrificing landing control.']::text[],'calves',ARRAY['tibialis_anterior','hip_flexors','soleus']::text[],'cone','plyometric','intermediate',ARRAY['plyometric','cardio','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','706ac77a-70f7-4532-a3c5-f1ce1bd2f079','Forward lunge with lateral flexion','forward-lunge-with-lateral-flexion','Starting position: Stand tall with feet hip-width apart, hands on hips or at sides for balance. Execution: Step forward into a lunge while simultaneously bending your torso laterally toward the forward leg, then return to starting position and repeat on the opposite side.',ARRAY['Stand with feet hip-width apart and engage your core muscles','Step forward with your right foot approximately 2-3 feet, keeping your torso upright initially','Lower your body by bending both knees to 90 degrees while simultaneously leaning your torso to the right side','Keep your weight evenly distributed between both feet and maintain balance','Push through your right heel to return to starting position while straightening your torso','Repeat the movement stepping forward with your left foot and leaning left']::text[],ARRAY['Keep your front knee aligned over your ankle and avoid letting it cave inward','Maintain control during the lateral flexion movement to avoid overstretching','Keep your core engaged throughout the entire movement to protect your spine','Ensure your back leg remains straight and strong during the lunge phase','Start with small lateral movements and gradually increase range of motion as flexibility improves']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','548f86e7-ee60-46ce-a482-c2b1c16e4441','Forward Lunges (Bodyweight)','forward-lunges-bodyweight-508f49',null,'{}'::text[],'{}'::text[],'bodyweight','{}'::text[],'free weights',null,null,'{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0df165d9-3c63-4506-a2f1-6f64544fda5d','Forward to Reverse Bear Crawl','forward-to-reverse-bear-crawl','Starting position: Begin in a tabletop position with hands directly under shoulders, knees under hips, and toes tucked under for support. Execution: Lift knees 1-2 inches off the ground and crawl forward for several steps, then immediately transition to crawling backward while maintaining the hovering position.',ARRAY['Start in a bear crawl position with hands under shoulders, knees under hips hovering 2-3 inches off the ground, and core engaged.','Move forward by stepping your right hand and left foot forward simultaneously, followed by your left hand and right foot.','Take 3-4 steps forward maintaining the low bear crawl position throughout the movement.','Reverse the movement by stepping your right hand and left foot backward simultaneously, followed by your left hand and right foot.','Take 3-4 steps backward to return to your starting position.','Repeat the forward-to-reverse sequence for the desired number of repetitions.']::text[],ARRAY['Keep your knees hovering just above the ground throughout the entire movement to maintain tension','Maintain a neutral spine by engaging your core and avoiding sagging hips or raised buttocks','Move with control and coordination, ensuring opposite hand and foot move together','Keep your weight evenly distributed between hands and feet to prevent excessive strain on wrists','Start with shorter distances and gradually increase range as you build strength and coordination']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['functional','cardio','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f7458e9c-56f8-4604-ba58-636ead67ffe2','Foward Lunges Bodyweight','foward-lunges-bodyweight-f38df9','Starting position: Stand tall with feet hip-width apart, hands on your hips, core braced, and chest lifted. Execution: Step forward with one leg and lower your body until both knees form roughly 90-degree angles, then push through the front heel to return to standing and repeat with the opposite leg.',ARRAY['Stand upright with feet hip-width apart and hands on your hips.','Take a controlled step forward with one leg, keeping your torso tall.','Lower your hips until both knees are bent to about 90 degrees, front knee tracking over the toes.','Drive through the front heel to push back to the starting position.','Alternate legs and repeat for the desired number of repetitions.']::text[],ARRAY['Keep your torso upright and core engaged throughout the movement.','Ensure the front knee stays aligned over the foot and does not cave inward.','Lower the back knee toward the floor without letting it slam down.','Take a step long enough to allow both knees to bend to 90 degrees.']::text[],'quads',ARRAY['glute_med','adductors','erector_spinae']::text[],'bodyweight','strength','beginner',ARRAY['strength','functional','balance']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','db1a9d2c-5386-41aa-a84f-dad06ac7ea7c','Frog pose','frog-pose','Starting position: Begin in a prone position with knees wide apart, shins parallel to each other, and forearms resting on the ground for support. Execution: Hold this static stretch position, allowing gravity to gently open the hips and stretch the inner thighs and hip flexors.',ARRAY['Begin by kneeling on your mat and gradually lower down to your forearms','Spread your knees wide apart while keeping your shins parallel to each other','Rest your forearms on the ground and allow your hips to sink toward the floor','Breathe deeply and hold the position, focusing on relaxing into the stretch','Only go as deep as feels comfortable and avoid forcing the stretch','Hold for 30 seconds to 2 minutes depending on your flexibility level']::text[],ARRAY['Keep your knees and ankles aligned to protect your knee joints','Only sink as low as your body naturally allows without pain or discomfort','Focus on breathing deeply to help your muscles relax and deepen the stretch gradually','Place a pillow or bolster under your torso if you need additional support','Stop immediately if you feel any sharp pain in your knees, hips, or lower back']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fefcff8a-f513-48bd-9e6d-0c38de0e4a6b','Frog Stretch','frog-stretch','Starting position: Begin on your hands and knees with knees wider than hip-width apart and feet turned outward. Execution: Slowly lower your forearms to the ground and gently rock back and forth while gradually widening your knees to deepen the stretch through your hips and groin.',ARRAY['Start on hands and knees with knees spread wider than your hips and toes pointed outward','Lower your forearms to the ground while keeping your back straight and core engaged','Slowly shift your weight backward toward your heels while maintaining the wide knee position','Gently rock forward and backward to find areas of tension and gradually deepen the stretch','Hold the deepest comfortable position for 30-60 seconds while breathing deeply','Return to starting position slowly by pressing through your forearms and bringing knees closer together']::text[],ARRAY['Never force the stretch - progress gradually over time to avoid injury to the hip joints and groin muscles','Keep your spine neutral and avoid rounding your back excessively during the movement','Stop immediately if you feel sharp pain in your knees, hips, or lower back','This stretch targets the hip adductors, hip flexors, and can help improve overall hip mobility and flexibility']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','df37b949-000b-4b09-90a3-482d868ee55a','Froggers','froggers','Starting position: Begin in a plank position with hands planted firmly on the ground, arms straight, and body in a straight line from head to heels. Execution: Jump both feet forward toward your hands into a deep squat position, then immediately jump back to the starting plank position in one fluid motion.',ARRAY['Start in a strong plank position with hands shoulder-width apart and core engaged','Keep your hands planted firmly on the ground throughout the entire movement','Jump both feet forward simultaneously, landing in a low squat position with feet outside your hands','Pause briefly in the squat position to maintain control','Jump both feet back to the starting plank position, landing softly on the balls of your feet','Maintain a neutral spine and avoid letting your hips sag during the plank phases']::text[],ARRAY['Keep your core tight throughout the movement to protect your lower back','Land softly on the balls of your feet to reduce impact on joints','Maintain steady breathing and avoid holding your breath during the exercise','Start with slower movements to master the form before increasing speed','If you experience wrist discomfort, perform the exercise on your fists or use push-up handles']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['functional','cardio','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e75d29c0-7af3-4e83-a351-6fff23443379','Front Barbell Squat','front-barbell-squat','Starting position: Place a barbell across the front of your shoulders, held with crossed arms or a clean grip, with feet shoulder-width apart. Execution: Lower your body into a deep squat while keeping your back straight, then push up to return to the starting position.',ARRAY['Bar on front delts, elbows high','Cross-arm or clean grip','Feet shoulder-width','Squat down, keeping torso upright','Drive up through whole foot']::text[],ARRAY['Requires more mobility than back squat','Keep elbows high throughout','More quad-dominant','Torso stays more vertical','If bar rolls forward, elbows are too low']::text[],'quads',ARRAY['core','erector_spinae','upper_back','hamstrings']::text[],'barbell','legs','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a04b709a-b24b-497b-af41-66544e152b4b','Front Raise','front-raise-ab4105','Starting position: Stand tall with feet hip-width apart, holding a dumbbell in each hand with arms extended down in front of the thighs, palms facing the body. Execution: Raise the dumbbells forward and upward to shoulder height with a slight bend in the elbows, then lower under control back to the start.',ARRAY['Stand upright with feet hip-width apart and dumbbells resting against the front of your thighs.','Keep a slight bend in your elbows and brace your core.','Raise both dumbbells forward until your arms are parallel to the floor at shoulder height.','Pause briefly at the top without leaning back.','Lower the dumbbells slowly and under control to the starting position.','Repeat for the desired number of repetitions.']::text[],ARRAY['Avoid swinging or using momentum to lift the weights.','Keep your torso stable and core engaged throughout the movement.','Raise only to shoulder height, not higher.','Maintain a slight elbow bend to protect the joints.']::text[],'front_deltoids',ARRAY['lateral_deltoids','traps','core']::text[],'dumbbell','strength','beginner',ARRAY['strength','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','50aafd34-960f-4967-ae4b-03430a734f10','front raises','front-raises-a19aea','Starting position: Sit upright on a chair holding a dumbbell in each hand with arms extended down at your sides, palms facing your thighs. Execution: Raise both dumbbells forward and up to shoulder height with arms straight, then lower them back down under control.',ARRAY['Sit tall on the chair with feet flat and core engaged, holding a dumbbell in each hand at your sides.','Keep your arms straight with a slight bend in the elbows and palms facing down.','Raise the dumbbells forward until they reach shoulder height.','Pause briefly at the top without swinging or arching your back.','Lower the weights slowly back to the starting position.','Repeat for the desired number of repetitions.']::text[],ARRAY['Avoid using momentum or leaning back to lift the weights.','Keep your shoulders relaxed and away from your ears.','Maintain an upright torso with a braced core throughout.','Control the descent rather than letting the weights drop.']::text[],'front_deltoids',ARRAY['lateral_deltoids','traps','serratus_anterior']::text[],'dumbbell','strength','beginner',ARRAY['strength','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','dc848ac2-ca46-4c70-a8cc-dd2a76e546cf','Front Two-Dumbbell Raise','front-two-dumbbell-raise','Starting position: Stand with feet hip-width apart, holding a dumbbell in each hand with arms extended down at your sides, palms facing your body. Execution: Simultaneously raise both dumbbells forward and up to shoulder height with straight arms, then slowly lower back to the starting position.',ARRAY['Stand with feet hip-width apart and engage your core muscles for stability','Hold one dumbbell in each hand with a neutral grip, arms fully extended at your sides','Keep a slight bend in your elbows and maintain this angle throughout the movement','Raise both dumbbells simultaneously in front of your body until they reach shoulder height','Pause briefly at the top position, then slowly lower the weights back to starting position','Maintain controlled movement throughout both the lifting and lowering phases']::text[],ARRAY['Keep your core engaged and avoid arching your back or using momentum to lift the weights','Use a weight that allows you to maintain proper form throughout all repetitions','Stop at shoulder height to avoid impingement and maintain tension on the target muscles','Focus on slow, controlled movements rather than speed to maximize muscle activation','Breathe out during the lifting phase and inhale during the lowering phase']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fb48eccb-7f51-4de3-97f0-dc5ef75a6cee','Full range push ups','full-range-push-ups','Starting position: Begin in a plank position with hands placed slightly wider than shoulder-width apart, arms fully extended, and body forming a straight line from head to heels. Execution: Lower your chest toward the ground until it nearly touches the floor, then push back up to the starting position with full arm extension.',ARRAY['Position hands flat on the floor slightly wider than shoulder-width with fingers spread for stability','Engage your core and maintain a straight line from head to heels throughout the entire movement','Lower your body slowly and controlled until your chest nearly touches the ground','Keep your elbows at a 45-degree angle to your torso rather than flaring them straight out','Push through your palms to return to starting position with full arm extension','Breathe in on the way down and exhale as you push back up']::text[],ARRAY['Maintain proper body alignment by keeping hips level and avoiding sagging or piking','Focus on the full range of motion by going as low as possible while maintaining good form','Keep your core engaged throughout to protect your lower back and maintain stability','Control the tempo with a slow descent and powerful push back to starting position','If unable to perform with proper form, modify by elevating hands on a bench or performing on knees']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','928d2978-b0a4-4619-858d-106a5c99e507','Garland pose','garland-pose','Starting position: Stand with feet slightly wider than hip-width apart, toes turned out at a 45-degree angle. Execution: Lower into a deep squat position, bringing your hips as close to the ground as possible while keeping your torso upright and pressing your elbows against your inner thighs.',ARRAY['Stand with feet slightly wider than hip-width, toes turned out.','Bend your knees and lower into a deep squat.','Bring your palms together at your chest.','Press your elbows against your inner knees to open the hips.']::text[],ARRAY['Keep your heels on the floor (place a rolled mat under them if needed).','Lengthen your spine and lift your chest.','Engage your core for balance.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fa3347f7-0e8f-446b-a7f0-fbb0f6b22206','Gate pose (left)','gate-pose-left','Starting position: Kneel on the floor with your knees hip-width apart, then extend your left leg straight out to the side with your foot flat on the floor. Execution: Lean your torso to the left while sliding your left hand down your extended leg, then return to the starting position with control.',ARRAY['Kneel on the mat and extend one leg out to the side.','Place the extended foot flat on the floor, toes pointing sideways.','Inhale and raise the arm on the kneeling side overhead.','Exhale and lean toward the extended leg, sliding the other hand down the leg.']::text[],ARRAY['Keep your hips stacked over the kneeling knee.','Open your chest toward the ceiling.','Do not collapse forward.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ad7e4bc7-a8d8-4aa7-978f-e130aeb49e8b','Gate pose (right)','gate-pose-right','Starting position: Kneel on the floor with your knees hip-width apart, then extend your right leg straight out to the side with your foot flat on the floor. Execution: Lean your torso to the right while sliding your right hand down your extended leg, reaching your left arm overhead to create a side bend stretch.',ARRAY['Kneel on the mat and extend one leg out to the side.','Place the extended foot flat on the floor, toes pointing sideways.','Inhale and raise the arm on the kneeling side overhead.','Exhale and lean toward the extended leg, sliding the other hand down the leg.']::text[],ARRAY['Keep your hips stacked over the kneeling knee.','Open your chest toward the ceiling.','Do not collapse forward.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b2eabe7f-7b04-456e-95b2-7aa3eaa88b9d','Get ups (no jump)','get-ups-no-jump','Starting position: Begin in a deep squat position with feet shoulder-width apart, arms positioned in front of your body for balance. Execution: Rise up from the squat position by driving through your heels and extending your hips and knees, then return to the starting squat position in a controlled manner.',ARRAY['Start in a deep squat with your thighs parallel to the floor and arms extended forward for balance','Keep your feet firmly planted shoulder-width apart with toes slightly turned out','Drive through your heels to stand up, extending your hips and knees simultaneously','Maintain an upright torso throughout the movement, avoiding excessive forward lean','Lower back down to the starting squat position with control','Repeat the movement for the desired number of repetitions']::text[],ARRAY['Keep your weight distributed evenly across your feet, focusing on pushing through your heels','Maintain proper knee alignment by ensuring your knees track over your toes','Engage your core throughout the entire movement to maintain stability and protect your lower back','Control the descent back to the squat position rather than dropping down quickly','Keep your chest up and shoulders back to maintain good posture throughout the exercise']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['functional','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','38530004-f20d-4895-8deb-ab02ebac1edf','Get ups with Jump','get-ups-with-jump','Starting position: Lie flat on your back with arms at your sides and legs extended. Execution: Rise from the lying position to standing without using your hands for support, then immediately perform a vertical jump with arms overhead before returning to the starting position.',ARRAY['Lie flat on your back with arms relaxed at your sides and legs straight','Engage your core and sit up by bringing your knees toward your chest while swinging your arms forward for momentum','Rock forward and plant your feet firmly on the ground while maintaining balance','Stand up completely without using your hands for assistance, keeping your chest up and core engaged','Immediately perform a vertical jump, driving through your heels and reaching your arms overhead','Land softly with bent knees and controlled descent back to the lying position']::text[],ARRAY['Keep movements controlled and avoid using excessive momentum that could cause you to lose balance','Land softly from the jump with bent knees to absorb impact and protect your joints','Maintain core engagement throughout the entire movement to protect your lower back','Start slowly and focus on smooth transitions between each phase of the movement before increasing speed','Stop immediately if you experience dizziness or discomfort during the getting up phase']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bae56fcf-a610-45e8-a577-238c5ee6567b','Glute bridge','glute-bridge','Starting position: Lie on your back with knees bent at 90 degrees, feet flat on the floor hip-width apart, and arms at your sides for stability. Execution: Drive through your heels to lift your hips up by squeezing your glutes, creating a straight line from knees to shoulders, then slowly lower back down.',ARRAY['Lie on back, knees bent, feet flat','Drive hips up by squeezing glutes','Form straight line from shoulders to knees','Lower with control']::text[],ARRAY['Squeeze glutes hard at top','Don''t hyperextend lower back','Drive through heels','Hold at top briefly','Foundation for hip thrusts']::text[],'quads','{}'::text[],'bodyweight','legs',null,ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a62f7e6f-99b3-49cf-a02e-c5146db97da3','Glute Bridge (Bodyweight)','glute-bridge-bodyweight-49ce34','Starting position: Lie on your back with knees bent and feet flat on the floor. Execution: Drive through your heels to lift your hips up into a bridge position, then lower back down.',ARRAY['Lie on your back with knees bent','Place feet flat on floor hip-width apart','Drive through heels to lift hips up','Squeeze glutes at the top position','Lower hips back down with control']::text[],ARRAY['Keep your core engaged throughout the entire movement','Avoid arching your lower back excessively at the top','Focus on squeezing your glutes rather than pushing with your lower back','Ensure your knees stay aligned and don''t cave inward']::text[],'bodyweight','{}'::text[],'bodyweight',null,'beginner',ARRAY['calisthenics','strength']::text[],true,false,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bc2f34f4-07e6-4001-9dfe-8724be0d9d7e','Glute Kickback','glute-kickback-275c9a','Starting position: Stand upright with feet hip-width apart, knees slightly bent, arms bent and held at your sides in a running posture. Execution: Perform rapid, small hops off the balls of your feet while pumping your arms as if jogging in place, maintaining a light and quick bouncing rhythm.',ARRAY['Stand tall with feet hip-width apart and elbows bent at 90 degrees.','Bounce lightly off the balls of your feet, keeping the hops small and quick.','Pump your arms rhythmically in a running motion to build momentum.','Land softly through the balls of your feet with knees slightly bent.','Maintain a steady, continuous pace throughout the set.']::text[],ARRAY['Stay on the balls of your feet for quick, springy repetitions.','Keep your core engaged and torso upright throughout.','Land softly to reduce impact on your joints.','Maintain a consistent breathing pattern to sustain the pace.']::text[],'cardiovascular_system',ARRAY['gastrocnemius','soleus','hip_flexors','tibialis_anterior']::text[],'bodyweight','cardio','beginner',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4d9ad82c-1799-4340-b973-c269c901d0e5','Glute Kickback','glute-kickback-f13e0d','Starting position: Stand tall with feet hip-width apart, knees softly bent, arms bent at the sides in a running posture. Execution: Bounce lightly on the balls of your feet while pumping the arms, maintaining a quick, rhythmic cadence to elevate the heart rate.',ARRAY['Stand upright with feet hip-width apart and elbows bent at 90 degrees.','Push off the balls of your feet to perform small, quick bounces.','Pump your arms in a controlled running motion to keep rhythm.','Land softly through the balls of the feet and immediately rebound.','Maintain an upright torso and steady breathing throughout.']::text[],ARRAY['Stay light on the balls of your feet and avoid heavy heel landings.','Keep the core engaged and torso upright to protect the lower back.','Maintain a consistent, controlled pace rather than rushing.','Keep knees soft to absorb impact and reduce joint stress.']::text[],'cardiovascular_system',ARRAY['gastrocnemius','soleus','tibialis_anterior','core']::text[],'bodyweight','cardio','beginner',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','32baa994-5bfa-4fb6-9ff0-07f682410778','Glute Leg Lift','glute-leg-lift-cef0f1','Starting position: Lie on your back on a mat with one knee bent and foot flat on the floor, arms resting at your sides for stability, and the opposite leg extended and raised toward the ceiling. Execution: Drive through the planted heel to lift your hips into a bridge position while keeping the extended leg straight and elevated, then lower under control and repeat before switching sides.',ARRAY['Lie on your back with one knee bent, foot flat, and the other leg extended straight up.','Press your arms into the mat for support and brace your core.','Drive through the heel of the planted foot to raise your hips until your torso and thigh form a straight line.','Keep the lifted leg extended and hips level throughout the movement.','Lower your hips back toward the floor with control without fully resting.','Complete all reps, then switch to the other leg.']::text[],ARRAY['Squeeze your glutes at the top and avoid arching the lower back.','Keep your hips level and prevent them from dropping to one side.','Move slowly and controlled rather than using momentum.','Maintain the raised leg straight and aligned with your torso.']::text[],'glutes',ARRAY['hamstrings','core','lower_back']::text[],'bodyweight','strength','intermediate',ARRAY['strength','core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ddfa0774-6077-4c9c-a590-1547fa987640','Goal Post Squeeze','goal-post-squeeze-8c5980','Starting position: Sit upright on a chair with feet flat, spine tall, and both arms raised to shoulder height with elbows bent at 90 degrees forming a goal-post shape. Execution: Squeeze the shoulder blades together and back while holding the goal-post arm position, hold the contraction, then release and repeat.',ARRAY['Sit tall on the edge of a chair with feet flat on the floor and core engaged.','Raise both arms to shoulder height and bend elbows 90 degrees to create a goal-post position.','Draw the shoulder blades down and together, keeping arms in position.','Hold the squeeze for a couple of seconds without shrugging the shoulders.','Slowly release and return to the start, then repeat for the desired reps.']::text[],ARRAY['Keep the spine tall and avoid arching the lower back.','Squeeze from the shoulder blades, not by shrugging the neck.','Keep elbows at shoulder height throughout the movement.','Breathe steadily and control both the squeeze and the release.']::text[],'middle_traps',ARRAY['rear_deltoids','rhomboids','upper_back']::text[],'chair','posture','beginner',ARRAY['isometric','mobility','rehabilitation']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b1c0e80d-329c-4910-8b23-37daa8ea17da','Goblet squat','goblet-squat','Starting position: Stand with feet slightly wider than shoulder-width apart, holding your hands at chest level in front of your body as if holding a goblet. Execution: Lower your body by bending at the hips and knees until your thighs are parallel to the floor, then drive through your heels to return to the starting position.',ARRAY['Hold one dumbbell vertically at chest','Feet shoulder-width or wider','Squat down between legs','Keep chest up, elbows inside knees','Drive up through heels']::text[],ARRAY['Great for learning squat pattern','Counterbalance helps depth','Keep chest up throughout','Elbows can push knees out at bottom','Good for mobility']::text[],'quads','{}'::text[],'dumbbell','legs',null,ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','54df7bb8-18f9-4b69-8561-f369f06632ee','Goblet Squat with Kettlebell','goblet-squat-with-kettlebell','Starting position: Stand with feet slightly wider than shoulder-width apart, holding a kettlebell by the horns at chest level with both hands, elbows pointing down. Execution: Lower your body by pushing your hips back and bending your knees until your thighs are parallel to the floor, then drive through your heels to return to the starting position.',ARRAY['Hold kettlebell at chest by horns','Feet shoulder-width or wider','Squat down between legs','Keep chest up, elbows inside knees','Drive up through heels']::text[],ARRAY['Same as dumbbell goblet squat','Counterbalance helps depth','Elbows can push knees out','Keep chest proud','Great for beginners']::text[],'quads',ARRAY['core','adductors','erector_spinae','hamstrings']::text[],'kettlebell','core','beginner',ARRAY['strength','functional']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c38b24ea-e65d-4561-a0ca-8d578fa6bd32','Goddess pose','goddess-pose','Starting position: Stand with feet wider than hip-width apart, toes turned out at 45-degree angles, hands on hips or in prayer position at chest. Execution: Lower into a deep squat by bending knees and tracking them over toes, then rise back to starting position while engaging glutes.',ARRAY['Stand with feet wide apart, toes turned out at 45 degrees.','Bend your knees deeply, sinking your hips toward knee height.','Bring your arms to a goal-post position or palms together at chest.','Hold and breathe steadily.']::text[],ARRAY['Keep knees tracking over your toes.','Engage your core and keep your spine tall.','Press evenly through both feet.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','89fffd4f-96b2-4833-8b3c-817a0aadb507','Good mornings','good-mornings','Starting position: Stand with feet hip-width apart, hands placed behind your head with elbows out wide, maintaining a tall posture with engaged core. Execution: Hinge at the hips by pushing your hips back and lowering your torso forward while keeping your back straight, then return to the starting position by driving your hips forward.',ARRAY['Bar on upper back like squat','Feet hip to shoulder-width','Soft knee bend','Hinge at hips, pushing butt back','Lower torso until parallel or comfortable stretch','Drive hips forward to stand']::text[],ARRAY['Keep back flat, not rounded','Movement is hip hinge, not squat','Feel stretch in hamstrings','Don''t go too heavy - technique is key','Great for posterior chain']::text[],'full_body','{}'::text[],'bodyweight','deadlifts',null,ARRAY['strength','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','88116de4-0c5d-4985-8905-156fd03d7eb9','Good Mornings with barbell','good-mornings-with-barbell','Starting position: Stand with feet shoulder-width apart, barbell resting across your upper trapezius muscles (high bar position), core engaged and chest up. Execution: Hinge at the hips by pushing your glutes back while maintaining a neutral spine, lower your torso until you feel a stretch in your hamstrings, then drive your hips forward to return to the starting position.',ARRAY['Bar on upper back like squat','Feet hip to shoulder-width','Soft knee bend','Hinge at hips, pushing butt back','Lower torso until parallel or comfortable stretch','Drive hips forward to stand']::text[],ARRAY['Keep back flat, not rounded','Movement is hip hinge, not squat','Feel stretch in hamstrings','Don''t go too heavy - technique is key','Great for posterior chain']::text[],'full_body','{}'::text[],'barbell','deadlifts',null,ARRAY['strength','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','24b76364-0eec-4035-b3e0-b7451a94db9f','Hack Squat','hack-squat','Starting position: Position yourself in a hack squat machine with feet on the platform at shoulder-width. Execution: Lower your body into a deep squat while keeping your back straight, then push up to return to starting position.',ARRAY['Adjust the machine so the shoulder pads sit comfortably on your shoulders and your back is fully supported against the pad','Place your feet shoulder-width apart on the footplate with toes slightly pointed outward','Release the safety handles and slowly lower your body by bending your knees while keeping your core engaged','Descend until your thighs are parallel to the footplate or as far as your mobility allows','Push through your heels to drive back up to the starting position while maintaining control','Re-engage the safety handles when your set is complete']::text[],ARRAY['Keep your knees aligned with your toes throughout the entire movement to prevent knee stress','Maintain a neutral spine by keeping your back pressed against the pad and avoiding rounding','Control the descent phase slowly to maximize muscle engagement and prevent injury','Avoid locking your knees completely at the top of the movement to maintain constant tension on the quadriceps','Focus on pushing through your heels rather than your toes to properly activate the quadriceps']::text[],'quads','{}'::text[],'machine','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','46989ad6-9ec2-40b0-929d-54893160b1af','Hack Squat Wide Stance','hack-squat-wide-stance','Starting position: Position yourself in a hack squat machine with feet in a wide stance, beyond shoulder width. Execution: Lower body into a deep squat while keeping back straight, then push up to return to starting position.',ARRAY['Position yourself on the hack squat machine with your back flat against the backrest and shoulders firmly under the shoulder pads','Place your feet wider than shoulder-width apart on the platform with toes pointed slightly outward','Release the safety handles and slowly lower your body by bending at the knees and hips while keeping your core engaged','Descend until your thighs are parallel to the platform or as low as your mobility allows','Push through your heels and drive upward to return to the starting position while maintaining control','Re-engage the safety handles when finished with your set']::text[],ARRAY['Keep your knees tracking in line with your toes throughout the entire movement to prevent knee stress','Maintain constant tension in your core and avoid rounding your lower back against the pad','The wide stance targets the inner quadriceps and glutes more than a narrow stance variation','Control the descent and avoid bouncing at the bottom of the movement to maximize muscle engagement','Ensure full foot contact with the platform and avoid rising onto your toes during the ascent']::text[],'quads','{}'::text[],'machine','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a4bd22f6-d98f-47da-9523-ceb6894b9922','Half boat pose','half-boat-pose','Starting position: Sit on the floor with knees bent, feet flat, and hands placed behind your thighs for support. Execution: Lean back slightly while lifting your feet off the ground, balancing on your sit bones with shins parallel to the floor.',ARRAY['Sit on the floor with knees bent and feet flat.','Lean back slightly and lift your feet off the floor.','Keep your shins parallel to the floor (knees bent at 90 degrees).','Extend your arms forward, parallel to the floor.']::text[],ARRAY['Keep your spine straight, avoid rounding your back.','Engage your core throughout.','This is a modification of full Boat Pose.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b126da42-0645-491c-83ae-e058822e074b','Half burpee','half-burpee-9d2137','Starting position: Stand upright with feet hip-width apart and arms ready at your sides. Execution: Drop into a squat, place your hands on the floor, jump or step your feet back into a plank, then quickly return your feet toward your hands and stand back up, repeating in a fluid rhythm without the push-up or jump portions of a full burpee.',ARRAY['Begin standing tall with feet hip-width apart and core engaged.','Bend your knees and lower your hands to the floor in front of you.','Jump or step both feet back into a high plank position keeping your body straight.','Immediately jump or step your feet back toward your hands into a low squat.','Stand or hop up to the starting position and repeat continuously.']::text[],ARRAY['Keep your core braced and back flat during the plank to protect your spine.','Land softly through the balls of your feet to reduce joint impact.','Maintain a steady, controlled pace rather than rushing sloppy reps.','Keep hands firmly planted and shoulders over wrists in the plank phase.']::text[],'full_body',ARRAY['hamstrings','calves','triceps','abs']::text[],'bodyweight','cardio','beginner',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','90f429f5-8d29-4ff7-a993-a904d378803d','Half frog pose (left)','half-frog-pose-left','Starting position: Lie face down on the ground with your left leg bent at 90 degrees, bringing your left knee up toward your left elbow while keeping your right leg straight. Execution: Hold this static stretch position while breathing deeply, allowing gravity to help open the hip flexors and activate the glutes.',ARRAY['Lie on your stomach and prop yourself up on your forearms.','Bend one knee and reach back with the same-side hand to hold your foot.','Gently press your foot toward your hip.','Hold and breathe, then switch sides.']::text[],ARRAY['Keep both hip bones pressing into the floor.','Do not force the stretch.','Engage your core to protect your lower back.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','39e71f53-4d30-4cb0-a6dc-16411d33bff0','Half frog pose (right)','half-frog-pose-right','Starting position: Lie face down with your left leg straight and your right knee bent at 90 degrees, bringing your right heel toward your right glute. Execution: Press your right heel toward your glute while lifting your right hip slightly off the ground, creating a stretch through the right hip flexor and engaging the right glute.',ARRAY['Lie on your stomach and prop yourself up on your forearms.','Bend one knee and reach back with the same-side hand to hold your foot.','Gently press your foot toward your hip.','Hold and breathe, then switch sides.']::text[],ARRAY['Keep both hip bones pressing into the floor.','Do not force the stretch.','Engage your core to protect your lower back.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3f916ec5-151e-4b3c-bdd2-011621f259fe','Half lord of the fishes pose (left)','half-lord-of-the-fishes-pose-left','Starting position: Sit with legs extended, then bend your left knee and place your left foot on the outside of your right thigh, keeping your right leg straight. Execution: Twist your torso to the left, placing your right elbow against your left knee for leverage while your left hand supports you behind your back.',ARRAY['Sit with legs extended. Bend one knee and place the foot outside the opposite thigh.','Bend the bottom leg and bring the foot near the opposite hip.','Twist your torso toward the bent knee.','Use the opposite elbow against the outside of the bent knee for leverage.']::text[],ARRAY['Sit tall before you twist - lengthen your spine first.','Twist from your mid-back, not just your shoulders.','Keep both sit bones grounded.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','58178205-37e9-489c-8322-f40b15d7b992','Half lord of the fishes pose (right)','half-lord-of-the-fishes-pose-right','Starting position: Sit on the floor with both legs extended straight in front of you, spine tall and shoulders relaxed. Execution: Bend your right knee and cross your right foot over your left leg, placing it flat on the floor beside your left knee, then twist your torso to the right while keeping your left leg straight and using your left elbow against your right knee for leverage.',ARRAY['Sit with legs extended. Bend one knee and place the foot outside the opposite thigh.','Bend the bottom leg and bring the foot near the opposite hip.','Twist your torso toward the bent knee.','Use the opposite elbow against the outside of the bent knee for leverage.']::text[],ARRAY['Sit tall before you twist - lengthen your spine first.','Twist from your mid-back, not just your shoulders.','Keep both sit bones grounded.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','37e6d334-06b4-4068-a9e4-5b806cbec2b6','Half moon (left)','half-moon-left','Starting position: Stand on your left leg in a forward fold position with your right hand placed on the ground for support and your right leg lifted behind you. Execution: Maintain the balanced position while extending your left arm upward toward the ceiling, creating a straight line from your lifted leg through your torso to your raised arm.',ARRAY['Begin in a standing forward fold and shift your weight onto your left leg','Place your right hand on the ground directly under your shoulder for support','Lift your right leg behind you until it''s parallel to the floor','Engage your core and find your balance on your standing leg','Slowly extend your left arm up toward the ceiling','Hold the position while maintaining alignment from your lifted leg through your extended arm']::text[],ARRAY['Keep your standing leg slightly bent to maintain stability and prevent knee strain','Engage your core throughout the entire movement to maintain balance and protect your lower back','Focus on creating one straight line from your lifted leg through your torso to your raised arm','Keep your hips square to the ground rather than allowing them to open up','Start with your hand on the ground for support before attempting to lift your arm']::text[],'full_body','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0852e58d-42d4-4e7a-b612-a6d79e93e895','Half moon (right)','half-moon-right','Starting position: Stand with feet together, arms at your sides, then step your left foot back about 3-4 feet while extending both arms overhead. Execution: Lean your torso to the right while lifting your left leg off the ground, creating a curved line from your left fingertips through your left leg, balancing on your right leg.',ARRAY['From Triangle Pose, bend your front knee and place your front hand on the floor.','Shift your weight onto your front foot and lift your back leg parallel to the floor.','Open your top hip and extend your top arm toward the ceiling.','Gaze up at your top hand if your balance allows.']::text[],ARRAY['Use a block under your bottom hand if needed.','Keep your standing leg strong with a micro-bend in the knee.','Stack your hips and shoulders.']::text[],'full_body','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fe06e1be-c429-485f-b36a-5e210ef03bc8','Half Roll Backs','half-roll-backs-873d90','Starting position: Sit toward the front of a sturdy chair with feet flat on the floor, spine tall, and arms extended straight in front at shoulder height with hands clasped. Execution: Engage your abdominals and slowly roll your pelvis and lower back backward, curving the spine into a C-shape, then draw yourself back up to the upright seated position with control.',ARRAY['Sit upright on the chair with feet hip-width apart and arms reaching forward, hands clasped.','Draw your navel toward your spine and tuck your pelvis under as you roll the lower back backward into a C-curve.','Pause briefly at the bottom of the range while keeping the abdominals engaged.','Reverse the motion by stacking the spine and returning to a tall seated position.','Repeat for the desired number of controlled repetitions, exhaling as you roll back.']::text[],ARRAY['Move slowly and use your core rather than momentum to control the roll.','Keep the arms extended and shoulders relaxed away from the ears.','Maintain steady breathing, exhaling on the roll back and inhaling on the return.','Only roll back as far as you can control without losing the abdominal contraction.']::text[],'abs',ARRAY['obliques','transverse_abdominis','hip_flexors']::text[],'chair','pilates','beginner',ARRAY['core','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','476cf5d3-e211-4650-84ec-7a3e89c08639','Half split (left)','half-split-left','Starting position: Begin in a kneeling lunge position with your left leg extended straight forward, heel on the ground and toes pointing up, while your right knee remains on the floor directly under your hip. Execution: Slowly hinge forward at the hips while keeping your spine straight, reaching toward your left foot to deepen the stretch in your left hamstring.',ARRAY['From a low lunge, straighten your front leg and flex your front foot.','Shift your hips back over your back knee.','Fold forward over the straight leg with a flat back.','Place your hands on the floor or on blocks.']::text[],ARRAY['Keep a micro-bend in the straight knee to protect the joint.','Hinge from the hips, not the waist.','Breathe deeply into the hamstring stretch.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b1b1d4cd-c4eb-47cc-a3f8-478eb474999f','Half split (right)','half-split-right','Starting position: Begin in a low lunge position with your right leg extended straight in front of you and your left knee on the ground behind you, hands placed on either side of your right leg for support. Execution: Slowly lean forward over your extended right leg while keeping your back straight, feeling a stretch along the back of your right thigh.',ARRAY['From a low lunge, straighten your front leg and flex your front foot.','Shift your hips back over your back knee.','Fold forward over the straight leg with a flat back.','Place your hands on the floor or on blocks.']::text[],ARRAY['Keep a micro-bend in the straight knee to protect the joint.','Hinge from the hips, not the waist.','Breathe deeply into the hamstring stretch.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c0386f57-3cd2-42e9-9c19-d2d3dc9aa3cb','Half squat get up )','half-squat-get-up','Starting position: Begin in a seated position on a chair or bench with feet flat on the floor, hip-width apart, and arms crossed over your chest or extended forward for balance. Execution: Rise up from the seated position by driving through your heels and engaging your quadriceps, stopping halfway up in a squat position, then slowly lower back down to the starting seated position.',ARRAY['Sit on a sturdy chair or bench with your back straight and feet planted firmly on the ground','Cross your arms over your chest or extend them forward for balance','Engage your core and shift your weight slightly forward over your feet','Drive through your heels and push up using your leg muscles until you reach a half-standing squat position','Hold the position briefly, then slowly control the descent back to the seated position','Repeat the movement maintaining proper form throughout']::text[],ARRAY['Keep your knees aligned with your toes and avoid letting them cave inward during the movement','Focus on using your leg muscles rather than momentum to rise up from the seated position','Maintain control during the lowering phase to maximize muscle engagement and prevent dropping back onto the seat','Start with a higher surface if you have difficulty with the movement and progress to lower surfaces as you get stronger','Keep your chest up and avoid rounding your back throughout the entire exercise']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a07157e6-32c0-4380-ad71-55afc02369ec','Halo with dumbbell (L)','halo-with-dumbbell-l','Starting position: Stand with feet shoulder-width apart, holding a dumbbell with both hands at chest level, arms extended in front of you. Execution: Move the dumbbell in a circular motion around your head to the left, passing it behind your head and returning to the starting position.',ARRAY['Hold the dumbbell securely with both hands using an overhand grip','Keep your core engaged and maintain an upright posture throughout the movement','Slowly move the dumbbell to your left side, then behind your head in a smooth circular motion','Control the weight as you bring it around to complete the circle back to the starting position','Maintain tension in your shoulders and avoid letting the weight pull you off balance','Complete all repetitions in the left direction before switching to the right if desired']::text[],ARRAY['Start with a lighter weight to master the movement pattern and avoid injury','Keep your head in a neutral position and avoid following the weight with your eyes','Maintain control throughout the entire range of motion - never let momentum take over','Keep your core tight to protect your lower back as you move the weight around your head','Stop immediately if you feel any neck or shoulder discomfort during the exercise']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','05c60c96-4b0d-4e83-8797-9e3eb9a9cab0','Halo with dumbbell (R)','halo-with-dumbbell-r','Starting position: Stand with feet shoulder-width apart, holding a dumbbell vertically by one end with both hands at chest level. Execution: Move the dumbbell in a circular motion around your head clockwise (right direction), keeping your core engaged and maintaining control throughout the movement.',ARRAY['Stand with feet shoulder-width apart, holding one dumbbell by one end with both hands at chest level','Lift the dumbbell overhead and slowly circle it around your head in a clockwise direction, keeping the weight close to your head','Pass the dumbbell behind your head, then around to the left side, maintaining control throughout the movement','Continue the circular motion, bringing the dumbbell around to the front and back to starting position','Complete the desired repetitions in one direction, then reverse to counterclockwise for equal repetitions']::text[],ARRAY['Keep your core engaged and maintain good posture throughout the entire movement','Start with a lighter weight to master the movement pattern before progressing','Move slowly and controlled - this is not a momentum-based exercise','Keep the dumbbell close to your head to maintain proper shoulder positioning','Stop immediately if you feel any shoulder impingement or discomfort']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3901065d-a926-4d63-9306-0f14eb731d7c','Hammer Curls','hammer-curls','Starting position: Stand upright with feet shoulder-width apart, holding dumbbells at your sides with arms fully extended and palms facing inward toward your body. Execution: Curl the weights up by flexing your biceps while keeping your palms facing inward throughout the movement, then slowly lower back to the starting position.',ARRAY['Stand with feet shoulder-width apart and hold a dumbbell in each hand with arms at your sides','Keep your palms facing inward toward your body throughout the entire movement','Engage your core and maintain an upright posture with shoulders back','Curl the weights up by bending at the elbows, lifting until your forearms are nearly vertical','Squeeze your biceps at the top of the movement','Slowly lower the weights back to the starting position with control']::text[],ARRAY['Keep your elbows close to your sides and avoid swinging them forward or backward','Maintain the neutral grip with palms facing inward - this targets the brachialis muscle differently than regular bicep curls','Focus on controlled movement both up and down to maximize muscle engagement','Avoid using momentum or swinging your body to lift the weights','Keep your wrists straight and aligned throughout the exercise']::text[],'biceps',ARRAY['brachialis','brachioradialis','forearm_flexors']::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','71ea41d9-e931-46dc-8a6c-731a7ee3e742','Hang clean','hang-clean','Starting position: Stand with feet hip-width apart, gripping a barbell with hands slightly wider than shoulder-width using an overhand grip, bar positioned over the mid-foot. Execution: Explosively pull the bar from the floor to shoulder height while simultaneously dropping into a partial squat to catch the bar at the shoulders with elbows pointing forward.',ARRAY['Set up with the barbell over mid-foot, maintaining a straight back and engaged core','Initiate the lift by driving through your heels and extending your hips and knees simultaneously','As the bar passes your knees, explosively extend your hips and shrug your shoulders upward','Pull yourself under the bar by dropping into a partial squat while rotating your elbows forward','Catch the bar at shoulder level with elbows pointing forward and stand up to complete the movement','Lower the bar back to the starting position with control']::text[],ARRAY['Keep the bar close to your body throughout the entire movement to maintain proper leverage','Focus on explosive hip extension rather than pulling with your arms to generate maximum power','Practice the catching position separately to develop proper elbow and wrist flexibility','Start with lighter weights to master the technique before progressing to heavier loads','Maintain a neutral spine throughout the movement to prevent lower back injury']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','plyometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8180c05c-73e5-4de1-bb90-0b5e0d80c4c9','Hang Snatch','hang-snatch','Starting position: Stand with feet hip-width apart, arms hanging at your sides in a relaxed position. Execution: Explosively jump upward while simultaneously pulling your arms overhead and dropping into a deep squat position, then stand up to complete the movement.',ARRAY['Begin in a standing position with feet hip-width apart and arms relaxed at your sides','Initiate the movement by bending at the hips and knees while swinging your arms back','Explosively extend your hips and knees while jumping upward','As you reach peak height, quickly pull your arms overhead and drop your body into a deep squat position','Land softly in the squat position with arms extended overhead','Stand up from the squat position to return to the starting stance']::text[],ARRAY['Focus on explosive hip and knee extension during the jumping phase','Keep your core engaged throughout the entire movement to maintain stability','Land softly on the balls of your feet to reduce impact on joints','Practice the squat position separately before attempting the full movement','Start with slower, controlled movements before progressing to full explosive speed']::text[],'full_body','{}'::text[],'barbell','full body','advanced',ARRAY['strength','plyometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','19a378bd-eec2-4950-b8f2-c4179ef28294','Hanging Leg Raise','hanging-leg-raise-699a98','Starting position: Hang from a pull-up bar with arms fully extended and legs straight. Execution: Lift your legs up toward your chest by flexing at the hips and core.',ARRAY['Hang from pull-up bar with overhand grip','Keep arms straight and shoulders engaged','Lift legs up by contracting your core muscles','Raise knees toward chest in controlled motion','Lower legs back to starting position slowly','Maintain constant tension throughout the movement']::text[],ARRAY['Keep shoulders pulled down and back to avoid swinging','Control the lowering phase to maximize core engagement','Start with bent knees if straight legs are too difficult','Avoid using momentum or swinging your body','Stop if you feel excessive strain in your shoulders']::text[],'core',ARRAY['hip_flexors','obliques','forearms']::text[],'bodyweight','core','intermediate','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','00cfe51b-59a3-4d61-b712-61ae99c1ca57','Hanging Scapular Pull','hanging-scapular-pull-73920c','Starting position: Hang from a pull-up bar with arms fully extended and body still. Execution: Pull shoulder blades down and together while maintaining straight arms, then return to starting position.',ARRAY['Grab pull-up bar with overhand grip shoulder-width apart','Hang with arms completely straight and feet off ground','Keep core engaged and body in straight line','Pull shoulder blades down and back without bending arms','Hold briefly then slowly return to starting position','Repeat the scapular movement while maintaining dead hang']::text[],ARRAY['Focus on moving only the shoulder blades, not the arms','Keep arms completely straight throughout the entire movement','Engage your core to prevent excessive swinging or momentum','Start with short holds and gradually increase time under tension','This exercise builds foundational strength for pull-ups and chin-ups']::text[],'bodyweight','{}'::text[],'bodyweight',null,null,ARRAY['calisthenics','strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','aefc423a-3e4b-4ca0-89c8-62484e13f3c0','Happy baby pose','happy-baby-pose','Starting position: Lie on your back with knees bent toward your chest, grabbing the outside edges of your feet with your hands. Execution: Gently pull your knees toward your armpits while keeping your lower back pressed into the floor, creating a gentle stretch through the glutes and hips.',ARRAY['Lie on your back and bring your knees toward your chest.','Grab the outsides of your feet with your hands.','Open your knees wider than your torso.','Gently pull your feet down, keeping your lower back on the mat.']::text[],ARRAY['Keep your lower back and sacrum on the floor.','Rock gently side to side for a spinal massage.','Relax your shoulders and neck.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8f35f8d8-b982-44af-8b71-4254b5be2532','Head Turns Neck stretches','head-turns-neck-stretches-cd06c2','Starting position: Sit tall on a chair with feet flat on the floor, hands resting on your thighs, spine neutral and shoulders relaxed. Execution: Slowly rotate your head to one side until you feel a gentle stretch along the neck, hold briefly, then return to center and rotate to the opposite side, keeping the movement smooth and controlled.',ARRAY['Sit upright on the chair with your back straight and shoulders relaxed down.','Keeping your chin level, slowly turn your head to look over one shoulder.','Hold the end range for a few seconds, feeling a gentle stretch on the side of the neck.','Return your head to the center facing forward.','Slowly turn your head to the opposite side and hold.','Repeat, alternating sides for the prescribed number of repetitions.']::text[],ARRAY['Move slowly and avoid forcing the rotation beyond a comfortable range.','Keep shoulders down and relaxed, avoiding any shrugging.','Maintain a tall spine and level chin throughout the movement.','Breathe steadily and stop if you feel sharp pain or dizziness.']::text[],'neck',ARRAY['sternocleidomastoid','cervical_extensors','upper_traps']::text[],'chair','face-neck','beginner',ARRAY['stretching','mobility','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2608b96f-dbaa-493f-9332-f1bfee45c5d4','Heel Raises toe raises','heel-raises-toe-raises-04e2bc','Starting position: Stand upright behind a chair with feet hip-width apart, lightly holding the backrest for balance and weight evenly distributed. Execution: Rise onto the balls of your feet lifting your heels, pause, lower back down, then lift your toes off the floor rocking onto your heels, alternating in a controlled manner.',ARRAY['Stand tall behind the chair and rest your hands on the backrest for support.','Push through the balls of your feet to raise your heels as high as possible.','Pause briefly at the top and squeeze your calves.','Lower your heels back to the floor with control.','Shift weight to your heels and lift your toes off the ground.','Return to the starting position and repeat for the desired reps.']::text[],ARRAY['Keep your knees straight but not locked throughout the movement.','Move slowly and avoid bouncing at the top or bottom.','Use the chair only for balance, not to bear your weight.','Maintain an upright posture with engaged core.']::text[],'calves',ARRAY['tibialis_anterior','soleus','hamstrings']::text[],'chair','strength','beginner',ARRAY['strength','balance','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','649d45cb-6e06-4b5b-890a-9ea4043ed7d9','Heel to toe walk','heel-to-toe-walk','Starting position: Stand upright with feet together, arms at your sides or extended out for balance. Execution: Walk forward in a straight line, placing the heel of one foot directly in front of the toes of the other foot with each step.',ARRAY['Stand tall with good posture and engage your core muscles','Take a small step forward, placing your heel directly against the toes of your back foot','Maintain contact between heel and toes for a moment before transferring weight','Continue walking forward heel-to-toe for the desired distance or number of steps','Keep your eyes focused on a fixed point ahead to help maintain balance','If you feel unsteady, extend your arms out to the sides for additional stability']::text[],ARRAY['Keep steps small and controlled rather than rushing through the movement','Focus on maintaining a straight line of travel rather than veering side to side','Breathe normally throughout the exercise and avoid holding your breath','Start near a wall or sturdy surface for support if you''re new to balance training','This exercise improves proprioception, coordination, and dynamic balance']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['balance','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','44067253-a8d5-4b0f-9008-02c2e56624b1','Heel touches','heel-touches','Starting position: Lie on your back with knees bent, feet flat on the floor hip-width apart, and arms extended straight down by your sides with palms facing down. Execution: Lift your shoulders slightly off the ground and alternate reaching your hands toward your heels by crunching your obliques side to side.',ARRAY['Lie flat on your back with knees bent at 90 degrees and feet planted firmly on the floor','Place your arms straight down by your sides with palms facing the floor','Engage your core and lift your shoulder blades slightly off the ground','Crunch to your right side and reach your right hand toward your right heel','Return to center then crunch to your left side reaching your left hand toward your left heel','Continue alternating sides in a controlled manner while keeping your core engaged']::text[],ARRAY['Keep your lower back pressed against the floor throughout the entire movement','Focus on using your oblique muscles to create the side-to-side crunching motion rather than just moving your arms','Maintain tension in your core and avoid letting your shoulders completely rest on the ground between reps','Keep your neck in a neutral position and avoid pulling on your head or straining your neck','Perform the movement slowly and controlled to maximize muscle engagement and prevent momentum from taking over']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f7d6b197-e10b-45bf-848b-e4be88299c28','Heel touches - v2','heel-touches-v2','Starting position: Lie on your back with knees bent, feet flat on the floor hip-width apart, and arms extended at your sides. Execution: Lift your shoulders slightly off the ground and alternately reach your hands toward your heels, engaging your core throughout the movement.',ARRAY['Lie on your back with knees bent at 90 degrees and feet flat on the floor','Place your arms straight at your sides with palms facing down','Engage your core and lift your shoulder blades slightly off the ground','Reach your right hand toward your right heel by crunching your torso to the side','Return to center and immediately reach your left hand toward your left heel','Continue alternating sides in a controlled rhythm while keeping shoulders elevated']::text[],ARRAY['Keep your lower back pressed into the floor throughout the entire movement','Focus on lateral flexion of the spine rather than just moving your arms','Maintain constant tension in your core by keeping shoulders off the ground between reps','Move slowly and controlled to maximize muscle engagement and prevent momentum','Exhale as you crunch to each side and maintain steady breathing throughout']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a16a574a-28bd-4010-bcda-b9f066b381e4','Heels to Butt','heels-to-butt','Starting position: Stand tall with feet hip-width apart, arms at your sides or hands on hips for balance. Execution: Alternately kick your heels up toward your glutes by bending your knees while maintaining an upright posture and pumping your arms.',ARRAY['Stand with feet hip-width apart and maintain good posture throughout the movement','Begin by lifting one heel toward your glutes by bending the knee, keeping thighs parallel','Quickly alternate legs in a running motion while staying in place','Pump your arms naturally as if running to maintain balance and rhythm','Land softly on the balls of your feet with each step','Continue for the desired duration while maintaining proper form']::text[],ARRAY['Keep your core engaged and avoid leaning forward or backward during the movement','Focus on bringing heels close to glutes rather than just lifting knees up','Maintain a quick but controlled tempo to maximize cardiovascular benefits','Land softly to reduce impact on joints and prevent injury','This exercise serves as an excellent dynamic warm-up or cardio interval movement']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0087bb08-f325-4401-9b37-66dd93871570','High Cable Curl','high-cable-curl','Starting position: Stand facing a high pulley with the handle in your hands, arms extended downward. Execution: Flex your elbows to bring the handle toward your shoulders, keeping your elbows fixed in place.',ARRAY['Set the cable machine to the highest position and attach D-handles to both sides','Stand in the center between the cables, grasp both handles with an underhand grip, and step forward slightly','Position your arms parallel to the floor with elbows slightly bent and shoulders pulled back','Curl both handles toward your temples by flexing your biceps while keeping your upper arms stationary','Squeeze your biceps at the peak contraction, then slowly return to the starting position with control','Repeat for desired repetitions while maintaining constant tension throughout the movement']::text[],ARRAY['Keep your core engaged and maintain an upright posture throughout the exercise','Your upper arms should remain parallel to the floor - avoid letting your elbows drop','Focus on squeezing your biceps rather than using momentum or swinging the weight','Control the eccentric (lowering) portion of the movement to maximize muscle engagement','Start with lighter weight to master the form before progressing to heavier resistance']::text[],'biceps','{}'::text[],'cable','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ec545ed7-4724-454a-b730-37a425e80080','High Cable Fly','high-cable-fly','Starting position: Adjust the pulleys to a height above your head and grasp the handles with palms facing down. Execution: Open your arms in a controlled motion, focusing on squeezing the chest, then return to starting position.',ARRAY['Set cable pulleys at shoulder height or slightly above and select appropriate weight','Stand in the center with one foot slightly forward for stability','Grasp handles with palms facing forward and arms extended in a wide arc','Keep a slight bend in your elbows and maintain this angle throughout','Bring handles together in front of your chest using a smooth arcing motion','Slowly return to starting position with control, feeling a stretch in your chest']::text[],ARRAY['Maintain a slight forward lean and engage your core for stability','Keep your shoulders down and back to avoid shoulder impingement','Focus on squeezing your chest muscles rather than using your arms to pull','Control the eccentric portion of the movement to maximize muscle engagement','Avoid letting the weight stack touch between repetitions to maintain constant tension']::text[],'chest','{}'::text[],'cable','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','109aec41-eaeb-4963-908a-e53b560789ee','High Cable Row','high-cable-row-d112fe','Starting position: Kneel in a half-kneeling stance facing a high cable pulley, gripping a straight bar attachment with an overhand grip and arms extended overhead. Execution: Pull the bar down and toward your chest by driving your elbows down and back, squeezing your shoulder blades together, then control the bar back to the starting overhead position.',ARRAY['Set the cable to a high position and attach a straight bar, then assume a half-kneeling stance facing the machine.','Grip the bar overhand with arms fully extended overhead and brace your core.','Pull the bar down and toward your upper chest by driving your elbows back and down.','Squeeze your shoulder blades together at the bottom of the movement.','Slowly extend your arms back to the overhead starting position under control.','Repeat for the desired number of repetitions while maintaining an upright torso.']::text[],ARRAY['Keep your torso upright and core braced to avoid leaning back excessively.','Lead the pull with your elbows, not your hands, to engage the lats.','Control the eccentric phase rather than letting the weight snap back.','Retract and depress the scapulae fully at the bottom for maximum back engagement.']::text[],'lats',ARRAY['rear_deltoids','biceps','forearms']::text[],'cable','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a9f277ce-cbc2-4223-96e5-baab4a926f92','High Knees','high-knees','Starting position: Stand tall with feet hip-width apart, arms at your sides, and core engaged. Execution: Alternate lifting each knee toward your chest while pumping your arms in a running motion, maintaining an upright posture throughout the movement.',ARRAY['Stand with feet hip-width apart and maintain an upright posture with shoulders back','Begin by lifting your right knee toward your chest as high as comfortable while keeping your left foot planted','Simultaneously pump your left arm forward as your right knee rises, mimicking a running motion','Lower your right leg and immediately lift your left knee while pumping your right arm forward','Continue alternating legs in a controlled, rhythmic pattern while staying light on your feet','Maintain steady breathing throughout the exercise and keep your core engaged']::text[],ARRAY['Keep your torso upright and avoid leaning forward or backward during the movement','Drive your knees up toward your chest rather than just lifting your heels toward your glutes','Land softly on the balls of your feet to reduce impact on your joints','Coordinate your arm movement opposite to your legs to maintain proper running form','Start at a moderate pace and gradually increase speed as your coordination improves']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5d55105e-04cc-4493-a7e8-302a5653e58c','High Knees v1','high-knees-v1','Starting position: Stand upright with feet hip-width apart, arms at your sides, and core engaged. Execution: Rapidly alternate lifting each knee toward your chest while pumping your arms in a running motion, maintaining an upright posture throughout the movement.',ARRAY['Stand tall with feet hip-width apart and engage your core muscles','Begin by lifting your right knee up toward your chest as high as comfortable','Quickly lower your right foot and immediately lift your left knee toward your chest','Pump your arms in opposition to your legs, as if you were running in place','Maintain a rapid alternating pattern between legs while staying in one spot','Continue the movement for the prescribed time or repetition count']::text[],ARRAY['Keep your torso upright and avoid leaning forward or backward during the exercise','Aim to lift your knees to at least hip height for maximum effectiveness','Land softly on the balls of your feet to reduce impact on your joints','Maintain a quick tempo but prioritize proper form over speed','Keep your core engaged throughout to maintain stability and protect your lower back']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8be51cd5-3ed1-489e-9975-5d9141880055','High plank alternating single leg knee tuck','high-plank-alternating-single-leg-knee-tuc','Starting position: Begin in a high plank position with hands planted firmly on the ground, arms straight, and body in a straight line from head to heels. Execution: Alternate bringing each knee toward the chest while maintaining the plank position, then return the leg to starting position before switching sides.',ARRAY['Start in a high plank position with hands directly under shoulders and body in a straight line','Engage your core and keep hips level throughout the movement','Bring one knee toward your chest in a controlled motion','Return the leg to starting position with control','Alternate legs, bringing the opposite knee toward chest','Maintain steady breathing throughout the exercise']::text[],ARRAY['Keep your core engaged to prevent sagging hips or arching your back','Maintain a straight line from head to heels throughout the movement','Control the movement rather than rushing to prevent losing form','Keep hands firmly planted and shoulders stable over wrists','Avoid letting hips pike up or drop down during the knee tucks']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f21fa91d-22fb-4b78-bc6a-50165e5cb8ad','High plank to low plank','high-plank-to-low-plank','Starting position: Begin in a high plank position with arms extended, hands placed directly under shoulders, and body forming a straight line from head to heels. Execution: Lower down to a low plank by bringing forearms to the ground one arm at a time, then return to high plank by pressing back up one arm at a time.',ARRAY['Start in a high plank position with hands flat on the ground directly under your shoulders','Keep your core engaged and body in a straight line throughout the entire movement','Lower down to forearm plank by placing one forearm down at a time where your hands were positioned','Press back up to high plank by placing one hand at a time back on the ground where your forearms were','Alternate which arm leads the movement to work both sides evenly','Maintain controlled movements throughout, avoiding any rushing or momentum']::text[],ARRAY['Keep your hips level and avoid rotating your torso as you transition between positions','Maintain a tight core throughout to protect your lower back and stabilize your body','Place your hands and forearms in the same spots to maintain proper alignment','Control the tempo of the movement rather than rushing through the transitions','Keep your feet hip-width apart for better stability during the exercise']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9d525d35-2c5f-45c9-a88c-56f8526d2177','High plank to side plank','high-plank-to-side-plank','Starting position: Begin in a high plank position with hands directly under shoulders, body forming a straight line from head to heels. Execution: Rotate your body to one side, lifting the top arm toward the ceiling while maintaining the plank position, then return to center and repeat on the other side.',ARRAY['Forearms on floor, elbows under shoulders','Body straight from head to heels','Hold position','Keep core tight, don''t let hips sag']::text[],ARRAY['Squeeze glutes','Keep neck neutral','Breathe normally','Don''t raise hips too high','Build time gradually']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0f14071c-279d-4926-b41a-cb4dc900bb1d','High plank toe touches','high-plank-toe-touches','Starting position: Begin in a high plank position with hands directly under shoulders, arms straight, and body in a straight line from head to heels. Execution: Lift one foot and reach it forward to touch the same-side hand, then return to plank and repeat on the opposite side.',ARRAY['Forearms on floor, elbows under shoulders','Body straight from head to heels','Hold position','Keep core tight, don''t let hips sag']::text[],ARRAY['Squeeze glutes','Keep neck neutral','Breathe normally','Don''t raise hips too high','Build time gradually']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0d3505ae-ce8d-4ad5-b8d0-8c172dd08969','High Row Machine','high-row-machine','Starting position: Sit in a rowing machine with a high grip, adjusting the seat height so the handles are at chest level. Execution: Pull the handles toward your chest while keeping your torso upright, then slowly return to the starting position.',ARRAY['Adjust the seat height so your arms are parallel to the floor when gripping the handles','Sit with your chest up, shoulders back, and feet firmly planted on the floor or footrests','Grip the handles with an overhand grip, arms fully extended forward','Pull the handles back toward your lower chest/upper abdomen by squeezing your shoulder blades together','Pause briefly at the peak contraction, feeling the squeeze in your mid-back','Slowly return to the starting position with control, maintaining tension throughout']::text[],ARRAY['Keep your chest up and avoid rounding your shoulders forward during the movement','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Maintain a slight arch in your lower back and avoid leaning too far forward or backward','Use a full range of motion but don''t allow the weight stack to crash down between reps','Exhale as you pull the weight toward you, inhale as you return to the starting position']::text[],'back','{}'::text[],'machine','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','95334bcd-2aa9-4c42-a846-4944c08b9a66','High toe touches','high-toe-touches','Starting position: Lie flat on your back with arms extended straight up toward the ceiling and legs raised with knees bent at 90 degrees. Execution: Crunch up by lifting your shoulder blades off the ground while reaching your hands toward your toes, then slowly lower back to starting position.',ARRAY['Lie on your back with arms straight up and legs in tabletop position with knees at 90 degrees','Press your lower back into the floor and engage your core muscles','Exhale as you crunch up, lifting your shoulder blades off the ground while reaching hands toward toes','Keep your neck in neutral position and avoid pulling on your head','Slowly lower back down with control, keeping your core engaged throughout','Maintain the tabletop leg position throughout the entire movement']::text[],ARRAY['Keep your lower back pressed against the floor to protect your spine','Focus on using your abdominal muscles rather than momentum to lift up','Maintain steady breathing and avoid holding your breath during the movement','Keep your legs stable in tabletop position rather than letting them drop or swing','Quality over quantity - perform controlled repetitions rather than rushing through the exercise']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','774856a2-01b1-492b-a955-18d166bde3b4','hip abduction','hip-abduction-678cc7','Starting position: Lie on your side on a mat with your body in a straight line, propping your head on your hand with the elbow bent, and place your top foot on the seat of a chair for support. Execution: Keeping the leg straight, lift your top leg upward toward the ceiling, engaging the outer hip, then lower it back down with control while maintaining a stable torso.',ARRAY['Lie on your side with legs stacked and body aligned, supporting your head on your bottom hand.','Rest your top foot lightly on the chair for stability and place your top hand on the mat in front.','Exhale and raise your top leg upward, leading with the heel and keeping the leg straight.','Pause briefly at the top, feeling the contraction in the outer hip.','Inhale and slowly lower the leg back toward the starting position without resting fully.','Complete all reps, then switch sides and repeat.']::text[],ARRAY['Keep your hips stacked and avoid rolling forward or backward.','Move the leg through a controlled range without swinging or using momentum.','Engage your core to keep the torso stable throughout the movement.','Lead with the heel and keep the toes pointing forward, not upward.']::text[],'abductors',ARRAY['glute_max','obliques','quads']::text[],'chair','strength','beginner',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6426c762-dd1d-4e44-b9c0-89875c81553a','Hip Abduction Machine','hip-abduction-machine','Starting position: Sit in a hip abduction machine with legs slightly bent and knees resting on the pads. Execution: Push your legs outward against the resistance, then slowly return to the starting position.',ARRAY['Adjust the machine so the leg pads rest comfortably against your outer thighs just above the knees','Sit with your back flat against the backrest and grip the handles for stability','Set your feet flat on the footrests with knees slightly bent','Push your legs apart by squeezing your glutes and driving through your outer thighs','Hold the peak contraction briefly then slowly return to starting position','Complete the full range of motion without letting the weight stack touch between repetitions']::text[],ARRAY['Keep your core engaged and avoid arching your back during the movement','Focus on initiating the movement with your glutes rather than just pushing with your legs','Control the return phase - don''t let the weight slam back to the starting position','Avoid leaning forward or using momentum to complete the repetition','Start with lighter weight to master the form before progressing to heavier resistance']::text[],'glutes',ARRAY['glute_max','glute_med','tensor_fasciae_latae']::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','af606d87-c83f-46cd-b72f-e554708eb94e','Hip Adduction Machine','hip-adduction-machine','Starting position: Sit on the hip adduction machine with legs slightly separated and knees resting on the pads. Execution: Bring your legs together against the resistance, then slowly return to the starting position.',ARRAY['Adjust the seat height so your thighs are parallel to the floor when seated','Set the leg pads to a comfortable starting width that provides a gentle stretch in your inner thighs','Sit with your back firmly pressed against the backrest and grip the side handles for stability','Engage your core and squeeze your inner thighs to bring your legs together in a smooth, controlled motion','Pause briefly at the peak contraction when your legs are together','Slowly return to the starting position, resisting the weight on the way back']::text[],ARRAY['Keep your back pressed against the pad throughout the entire movement to maintain proper spinal alignment','Avoid using momentum or bouncing motions - focus on slow, controlled movements to maximize muscle engagement','Don''t start with too wide of a range of motion if you feel excessive stretching in your inner thighs','Select a weight that allows you to complete the full range of motion without compensation patterns','Breathe out during the squeezing phase and breathe in during the return phase']::text[],'quads',ARRAY['glute_med','hamstrings','transverse_abdominis']::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','83b448e2-7782-42ff-bcf6-1ce7a7e9a5a4','Hip Circle hops','hip-circle-hops','Starting position: Stand with feet hip-width apart, hands on hips or at your sides for balance. Execution: Hop in a circular pattern around an imaginary clock face, landing softly on both feet while engaging your glutes to control each landing and takeoff.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Begin hopping in small circular motions, moving clockwise around an imaginary circle','Land softly on the balls of your feet with slight knee bend to absorb impact','Keep your torso upright and avoid leaning forward or backward during hops','Complete the full circle clockwise, then reverse direction to move counterclockwise','Start with smaller circles and progress to larger movements as you build strength']::text[],ARRAY['Focus on soft landings with bent knees to protect your joints from impact','Squeeze your glutes at each landing to maximize muscle activation and stability','Keep circles small initially and gradually increase size as your balance and strength improve','Maintain controlled movements rather than rushing through the exercise for better muscle engagement','Stop immediately if you feel any knee or ankle discomfort']::text[],'glutes','{}'::text[],'bodyweight','legs','intermediate',ARRAY['plyometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','abfd0396-b9b3-41b3-b8ec-88ce2faf0462','Hip flexor stretch','hip-flexor-stretch-da1af5','Starting position: Kneel upright on the floor with your knees hip-width apart, tops of the feet resting down, torso tall and arms relaxed at your sides. Execution: Engage your core, tuck the pelvis slightly, and gently press the hips forward while keeping the torso upright to feel a stretch along the front of the hips and thighs, holding the position before returning.',ARRAY['Kneel tall on the floor with knees hip-width apart and feet flat behind you.','Draw your navel in and tuck your tailbone under to flatten the lower back.','Slowly push your hips forward while keeping your chest lifted and upright.','Hold the stretch across the front of the hips and thighs for the prescribed time.','Breathe steadily and avoid arching the lower back.','Return to the upright kneeling position and relax.']::text[],ARRAY['Keep the torso tall and avoid leaning back or overarching the spine.','Squeeze the glutes to deepen the stretch and protect the lower back.','Move slowly and only to a comfortable range of tension.','Use a mat or padding under the knees for comfort.']::text[],'hip_flexors',ARRAY['rectus_abdominis','erector_spinae','tensor_fasciae_latae']::text[],'bodyweight','stretching','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','033964cc-ed58-4fe3-8850-cf78c66a85b9','Hip hinge','hip-hinge-d90a01','Starting position: Stand tall with feet hip-width apart, knees slightly bent, and hands resting at your sides or on your thighs. Execution: Push your hips backward while keeping your back flat, allowing your torso to tip forward from the hips until you feel a stretch in your hamstrings, then drive your hips forward to return to standing.',ARRAY['Stand with feet hip-width apart and a soft bend in the knees.','Brace your core and keep your spine in a neutral, flat position.','Hinge at the hips by pushing your buttocks backward while lowering your torso.','Lower until you feel tension in the hamstrings, keeping the back straight.','Drive through your heels and squeeze your glutes to return to a standing position.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep the movement at the hips, not the lower back or knees.','Maintain a neutral spine throughout. Avoid rounding the back.','Shift weight into the heels as the hips travel backward.','Keep the knees soft but not deeply bent to isolate the hip hinge.']::text[],'hamstrings',ARRAY['spinal_erectors','obliques','quadriceps']::text[],'bodyweight','mobility','beginner',ARRAY['functional','mobility','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','610855b2-2eb1-440a-9645-9598f0a46766','Hip stretch (left)','hip-stretch-left','Starting position: Stand with feet hip-width apart, then step your right foot forward into a lunge position while keeping your left leg extended behind you. Execution: Lower your hips toward the ground while maintaining an upright torso, feeling the stretch through your left hip flexor and surrounding muscles.',ARRAY['Step your right foot forward approximately 2-3 feet while keeping your left foot planted behind you','Lower your body into a lunge position by bending your right knee to 90 degrees','Keep your left leg straight and press your left heel toward the ground','Place your hands on your right thigh or on the ground for support and balance','Gently push your hips forward and down to deepen the stretch in your left hip','Hold the position for 20-30 seconds while breathing deeply']::text[],ARRAY['Keep your front knee aligned over your ankle to prevent injury','Maintain an upright torso throughout the stretch rather than leaning forward','Feel the stretch primarily in the front of your left hip and thigh','Gradually ease into the stretch rather than forcing the position','Stop immediately if you experience any sharp pain or discomfort']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','322a5b58-ed0d-4d37-8d09-c48a606484fe','Hip stretch (right)','hip-stretch-right','Starting position: Stand with feet hip-width apart, then step your left foot forward into a lunge position with your right knee on the ground. Execution: Lean forward and sink your hips down while keeping your torso upright to stretch the right hip flexor.',ARRAY['Step your left foot forward into a lunge position and lower your right knee to the ground','Place your hands on your left thigh or on the ground for support and stability','Keep your torso upright and engage your core muscles throughout the stretch','Gently push your hips forward and down to deepen the stretch in your right hip flexor','Hold the position for 20-30 seconds while breathing deeply','Slowly return to standing position before switching sides']::text[],ARRAY['Keep your front knee aligned over your ankle and avoid letting it cave inward','Focus on pushing your hips forward rather than just dropping down to target the hip flexors effectively','Maintain steady breathing throughout the stretch and avoid bouncing or jerky movements','Place a towel or mat under your back knee for comfort if needed','Stop immediately if you feel sharp pain and only stretch to a comfortable tension']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6378a159-2d36-4fb3-b972-2862f81433e8','Hip Thrust Machine','hip-thrust-machine-5e45a2','Starting position: Sit on hip thrust machine with back against pad and feet flat on footplate. Execution: Drive hips upward by squeezing glutes until full hip extension.',ARRAY['Position back against pad with shoulder blades supported','Place feet shoulder-width apart on the footplate','Engage core and maintain neutral spine alignment','Drive hips upward by squeezing glutes powerfully','Pause briefly at the top position','Lower hips slowly back to starting position']::text[],ARRAY['Keep knees aligned over toes throughout the movement','Focus on glute activation rather than pushing through heels','Avoid overextending the lower back at the top','Maintain consistent tempo with controlled lowering phase','Position the pad across your hip crease for comfort']::text[],'legs',ARRAY['hamstrings','quads','lower_back']::text[],'machine','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','98f659d5-466b-4c23-803c-85cf32f2377c','Hollow Body Hold','hollow-body-hold-25ec7b','Starting position: Lie supine with arms overhead and legs extended. Execution: Hold the hollow body position by pressing lower back into floor while lifting shoulders and legs.',ARRAY['Lie on back with arms extended overhead','Press lower back firmly into the floor','Lift shoulders and upper back off ground','Raise legs while keeping knees straight','Hold position while breathing steadily','Lower down slowly to complete the hold']::text[],ARRAY['Keep lower back pressed against the floor throughout the entire hold','Avoid arching the neck by keeping chin slightly tucked toward chest','Start with shorter holds and gradually increase duration as core strength improves','If too difficult, bend knees or place arms by sides instead of overhead']::text[],'bodyweight','{}'::text[],'free weights',null,null,ARRAY['isometric','core']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7829eabb-e6e5-467a-807a-0c5c65ebf49e','Hollow body skullcrushers','hollow-body-skullcrushers','Starting position: Lie on your back with arms extended overhead, lower back pressed to the floor, and legs lifted with knees bent at 90 degrees, creating a hollow body position. Execution: Bring your arms forward in an arc motion toward your knees while maintaining the hollow body position, then slowly return arms overhead while keeping core engaged throughout.',ARRAY['Lie flat on your back and press your lower back firmly into the floor','Extend your arms straight overhead and lift your legs with knees bent at 90 degrees','Engage your core to create a hollow body position with shoulders and feet off the ground','Bring your arms forward in a controlled arc motion toward your knees without letting your back arch','Slowly return your arms overhead while maintaining the hollow body position','Keep your core tight and breathing steady throughout the entire movement']::text[],ARRAY['Keep your lower back pressed to the floor at all times to prevent injury and maximize core engagement','Move your arms slowly and with control to maintain proper form and increase time under tension','Maintain the hollow body position throughout the entire exercise without letting your shoulders or feet touch the ground','If you experience neck strain, focus on keeping your head in a neutral position rather than lifting it toward your knees','Start with shorter holds and fewer repetitions, gradually increasing as your core strength improves']::text[],'core','{}'::text[],'bodyweight','core','advanced',ARRAY['core','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bc8a31d3-6f32-4f5d-a0c9-9935e76b2071','Horizontal Leg Press','horizontal-leg-press','Starting position: Sit on a horizontal leg press machine with feet positioned on the platform and knees bent. Execution: Push the platform upward by fully extending your legs, then slowly lower to the starting position.',ARRAY['Adjust the seat and backrest so your knees form a 90-degree angle when feet are positioned on the footplate','Place feet shoulder-width apart on the footplate with toes pointing slightly outward','Grip the side handles for stability and keep your core engaged throughout the movement','Push through your heels to extend your legs, avoiding locking your knees completely at the top','Lower the weight slowly and under control until your knees return to the 90-degree starting position','Maintain steady breathing, exhaling during the push phase and inhaling during the return']::text[],ARRAY['Keep your knees aligned with your toes throughout the entire range of motion to prevent knee strain','Avoid placing your feet too high or too low on the footplate as this can shift emphasis away from the quadriceps','Never allow your lower back to round or lift off the backrest during the movement','Control the negative portion of the lift rather than allowing the weight to drop quickly','Start with lighter weight to master proper form before progressively increasing the load']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','abd551ed-0fb5-4db7-a9d3-e9a2466da469','How to get out of bed','how-to-get-out-of-bed-23eb6b','Starting position: Lie on your back near the edge of the bed with knees bent and feet flat. Execution: Roll onto your side, drop your feet off the edge, and use your arm to push your torso upright into a seated position, protecting your back throughout.',ARRAY['Bend both knees while lying on your back with feet flat on the surface.','Roll onto your side toward the edge of the bed, keeping knees together.','Lower your feet off the edge as you push your upper body up with your bottom arm.','Press through the supporting arm to bring your torso fully upright into sitting.','Pause seated to steady yourself before standing.']::text[],ARRAY['Move as a single unit to avoid twisting the spine.','Use your arm strength rather than jerking up with your neck or trunk.','Keep the movement slow and controlled to protect your lower back.','Let your legs act as a counterweight as your torso rises.']::text[],'core',ARRAY['obliques','hip_flexors','erector_spinae']::text[],'bodyweight','physio','beginner',ARRAY['functional','rehabilitation','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c6e3375f-ad53-425b-9313-72265c9212e2','In and out Shoulder tap push ups','in-and-out-shoulder-tap-push-ups','Starting position: Begin in a high plank position with hands placed shoulder-width apart, core engaged, and body in a straight line from head to heels. Execution: Jump feet wide apart, perform a push-up, jump feet back together, then lift one hand to tap the opposite shoulder before repeating the sequence.',ARRAY['Start in a high plank position with hands directly under shoulders and feet together','Jump both feet out wide to about shoulder-width apart while maintaining the plank position','Lower your chest toward the ground in a push-up motion, keeping elbows at a 45-degree angle','Push back up to the starting position and immediately jump feet back together','Lift one hand off the ground and tap the opposite shoulder, then return hand to the ground','Repeat the entire sequence, alternating which hand performs the shoulder tap']::text[],ARRAY['Keep your core tight throughout the entire movement to prevent hip sagging or pike position','Land softly when jumping feet in and out to minimize impact on joints','Maintain a straight line from head to heels during all phases of the exercise','Keep minimal weight shift when performing shoulder taps to challenge core stability','Control the tempo rather than rushing through the movement for better form and effectiveness']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0bc5f89b-dec0-483a-b98d-655998f8849d','Inchworm','inchworm','Starting position: Stand tall with feet hip-width apart and arms at your sides. Execution: Hinge at the hips to place hands on the floor, walk hands forward into plank position, perform a push-up if desired, then walk hands back to feet and return to standing.',ARRAY['Stand tall with feet hip-width apart and arms at your sides','Hinge at the hips and bend forward, placing your hands flat on the floor in front of your feet','Walk your hands forward one at a time until you reach a high plank position with straight arms','Hold the plank briefly, keeping your body in a straight line from head to heels','Walk your hands back toward your feet, maintaining straight legs as much as possible','Return to standing position and repeat']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','If you can''t touch the floor with straight legs, bend your knees slightly when reaching down','Maintain proper plank form with shoulders directly over wrists and avoid sagging hips','Move slowly and controlled - this isn''t a race, focus on form over speed','Stop if you feel any pain in your lower back or shoulders']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['warmup','mobility','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e7fa2b6f-4d2b-478a-a1c0-8bca51b04a13','Inchworm to pike push ups','inchworm-to-pike-push-ups','Starting position: Stand tall with feet hip-width apart and arms at your sides. Execution: Walk your hands forward into a plank, perform a pike push-up by lifting your hips high and lowering your head toward the ground, then walk your hands back to standing.',ARRAY['Stand with feet hip-width apart and hinge forward at the hips to place your hands on the ground','Walk your hands forward one at a time until you reach a high plank position with straight arms','Lift your hips up and back into a downward dog position while keeping your hands planted','Lower your head toward the ground by bending your elbows, creating a pike push-up movement','Press back up to the pike position, then walk your hands back toward your feet','Return to standing by lifting your torso and bringing your arms back to your sides']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Maintain straight legs during the walking phases and pike position for maximum hamstring and calf stretch','Focus on controlled movement rather than speed to maximize muscle activation and prevent injury','Keep your shoulders directly over your wrists in the plank position to avoid wrist strain','If the full pike push-up is too challenging, simply hold the pike position without lowering your head']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','21ce1e16-e426-466b-b8cf-9d4b1fce7227','Inchworms to push ups to pike push up','inchworms-to-push-ups-to-pike-push-up','Starting position: Stand tall with feet hip-width apart and arms at your sides. Execution: Walk your hands forward into a plank, perform a push-up, then walk your feet toward your hands while keeping legs straight to form a pike position, perform a pike push-up, then return to standing.',ARRAY['Begin standing with feet hip-width apart, then hinge at the hips and place your hands on the floor','Walk your hands forward into a high plank position, keeping your core engaged and body in a straight line','Perform one standard push-up by lowering your chest to the floor and pressing back up','Walk your feet forward toward your hands while keeping your legs straight until you reach a pike position','Perform one pike push-up by lowering the top of your head toward the floor and pressing back up','Walk your hands back out to plank, then walk your feet back to return to standing position']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your lower back','Maintain proper push-up form with hands positioned slightly wider than shoulder-width','In the pike position, focus on pressing your hips up and back to create an inverted V shape','Start with slower, controlled movements and gradually increase pace as you build strength and coordination','If standard push-ups are too challenging, drop to your knees during the push-up portions']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ac256206-2279-44dc-ab5e-94d6e7d9e8a6','Incline Barbell Front Raise','incline-barbell-front-raise','Starting position: Lie on an incline bench with a barbell in your hands, arms extended downward. Execution: Raise the bar forward until it reaches shoulder height, then slowly lower.',ARRAY['Set an incline bench to a 30-45 degree angle and lie back with your feet firmly planted on the floor','Grasp the barbell with both hands using an overhand grip, hands positioned slightly wider than shoulder-width apart','Begin with arms extended and the barbell positioned above your lower chest with a slight bend in your elbows','Raise the barbell in a smooth arc upward until it reaches shoulder height, maintaining the slight elbow bend throughout','Pause briefly at the top position, then slowly lower the barbell back to the starting position with control','Keep your core engaged and maintain contact between your back and the bench throughout the entire movement']::text[],ARRAY['Use a lighter weight than you would for other shoulder exercises as this movement places significant stress on the shoulder joint in a vulnerable position','Maintain a slight bend in your elbows throughout the movement to reduce stress on the elbow joints and maintain better control','Focus on slow, controlled movements rather than momentum to maximize muscle engagement and minimize injury risk','Keep your shoulders pulled back and down against the bench to maintain proper shoulder blade positioning and prevent impingement']::text[],'shoulders','{}'::text[],'barbell','shoulders','intermediate',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','25be107f-a9ec-4007-bb9f-c0a5088e19b5','Incline Barbell Press','incline-barbell-press','Starting position: Lie on an incline bench with a barbell in your hands and arms extended upward with a pronated grip. Execution: Lower the bar to your chest, then push upward to return to starting position.',ARRAY['Set the incline bench to a 30-45 degree angle and position yourself with your back flat against the pad','Grip the barbell with hands slightly wider than shoulder-width apart using an overhand grip','Unrack the barbell and position it directly above your upper chest with arms extended','Lower the barbell slowly and under control until it lightly touches your upper chest near the collarbone','Press the barbell back up to the starting position by driving through your chest and shoulders','Re-rack the barbell safely when your set is complete']::text[],ARRAY['Keep your shoulder blades pulled back and down throughout the entire movement to maintain stability','Focus on controlling the weight during the lowering phase rather than letting it drop quickly','Press the barbell in a slight arc motion rather than straight up and down to follow the natural movement pattern','Maintain tension in your core and keep your feet planted firmly on the ground for stability','Avoid bouncing the barbell off your chest or using excessive momentum to complete repetitions']::text[],'chest',ARRAY['front_deltoids','triceps','serratus_anterior']::text[],'barbell','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4a608293-5863-4517-b03d-a46398066e32','Incline Cable Fly','incline-cable-fly','Starting position: Position yourself on an incline bench facing a cable pulley with handles adjusted to chest height. Execution: Open arms to the sides maintaining a slight elbow bend, then return to starting position.',ARRAY['Position incline bench at 30-45 degree angle between low cable pulleys and select appropriate weight','Lie back on bench and grasp cable handles with palms facing up, arms extended to sides with slight elbow bend','Plant feet firmly on floor and maintain neutral spine against the bench pad','Bring handles together in smooth arc motion above upper chest while maintaining elbow position','Squeeze chest muscles at the top for one second, then slowly lower handles back to starting position','Complete all repetitions with controlled tempo before releasing handles']::text[],ARRAY['Keep a slight bend in your elbows throughout the entire movement to protect shoulder joints','Focus on feeling the stretch in your chest muscles at the bottom position without going too deep','Maintain tension in the cables throughout the full range of motion and avoid letting weights touch the stack','Use a weight that allows you to control the movement in both directions without momentum','Keep your core engaged and avoid arching your back excessively during the exercise']::text[],'chest','{}'::text[],'cable','chest','intermediate',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6a3ac67c-fa0f-4ef1-91c7-aa2503d11844','Incline Dumbbell Crossover','incline-dumbbell-crossover','Starting position: Lie on an incline bench with a dumbbell in each hand. Execution: Cross the dumbbells in front of your chest while contracting your chest muscles, then return to the starting position.',ARRAY['Set the incline bench to a 30-45 degree angle and select appropriate weight dumbbells','Lie back on the bench with your feet firmly planted on the floor and core engaged','Hold dumbbells above your chest with arms extended and palms facing each other, maintaining a slight bend in your elbows','Lower the weights in a controlled arc motion by opening your arms wide until you feel a good stretch in your chest muscles','Squeeze your chest muscles to bring the dumbbells back together in a hugging motion above your chest','Complete the desired number of repetitions while maintaining control throughout the entire range of motion']::text[],ARRAY['Keep a slight bend in your elbows throughout the movement to protect your joints and maintain tension on the chest muscles','Focus on feeling the stretch in your chest at the bottom of the movement rather than trying to touch the dumbbells to your shoulders','Control the weight on both the lowering and lifting phases to maximize muscle engagement and prevent injury','Keep your shoulders pulled back and down against the bench to maintain proper positioning and prevent shoulder impingement','Use a weight that allows you to maintain proper form throughout all repetitions rather than going too heavy']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d1faa0c0-7eac-4a49-8b40-9b3fa923d091','Incline Dumbbell Curl','incline-dumbbell-curl','Starting position: Sit on an incline bench with a dumbbell in each hand, arms hanging down. Execution: Bend your elbows to lift the dumbbells toward your shoulders, then lower in a controlled manner.',ARRAY['Set the incline bench to a 45-60 degree angle and sit with your back firmly pressed against the pad','Hold a dumbbell in each hand with arms hanging straight down and palms facing forward','Keep your shoulders back and core engaged throughout the movement','Curl the weights up by contracting your biceps while keeping your upper arms pressed against the bench','Squeeze your biceps at the top of the movement for a brief pause','Slowly lower the dumbbells back to the starting position with control']::text[],ARRAY['Keep your upper arms stationary and pressed against the bench to isolate the biceps effectively','Avoid swinging or using momentum - focus on slow, controlled movements','Don''t let your shoulders roll forward or come off the bench during the exercise','The incline position provides a greater stretch on the biceps compared to standard curls','Start with lighter weights as this position makes the exercise more challenging than regular curls']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a9ab8609-e40c-44e1-9e0f-a86c3794662c','Incline Dumbbell Lateral Raise','incline-dumbbell-lateral-raise','Starting position: Lie on your side on an incline bench with a dumbbell in the upper hand. Execution: Raise the dumbbell to the side until it reaches shoulder height, then slowly lower.',ARRAY['Set the incline bench to a 45-60 degree angle and sit with your back pressed firmly against the pad','Hold a dumbbell in each hand with a neutral grip, arms hanging at your sides with a slight bend in your elbows','Engage your core and maintain a straight spine throughout the movement','Lift the dumbbells out to your sides in a controlled arc motion until your arms are parallel to the floor','Pause briefly at the top position while squeezing your shoulder blades','Slowly lower the weights back to the starting position with control']::text[],ARRAY['Keep a slight bend in your elbows throughout the entire movement to protect your joints','Focus on lifting with your shoulders rather than swinging the weights with momentum','The incline position helps isolate the middle deltoids while reducing strain on the lower back','Start with lighter weights as this exercise can be more challenging than standard lateral raises due to the inclined position','Avoid raising the dumbbells higher than shoulder level to prevent shoulder impingement']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8ef75730-0d30-4063-b6ff-242725cf8c29','Incline Dumbbell Press','incline-dumbbell-press','Starting position: Lie on an incline bench with a dumbbell in each hand, arms extended upward with palms facing forward. Execution: Lower the dumbbells toward your chest, then press upward to return to the starting position.',ARRAY['Set the incline bench to a 30-45 degree angle and sit with your back firmly pressed against the pad','Hold a dumbbell in each hand and position them at chest level with palms facing forward','Plant your feet firmly on the floor and engage your core for stability','Lower the dumbbells slowly in an arc motion until they reach chest level, feeling a stretch in your chest','Press the weights back up along the same path, focusing on squeezing your chest muscles','Complete the desired number of repetitions while maintaining controlled movement throughout']::text[],ARRAY['Keep your shoulder blades retracted and pressed against the bench throughout the entire movement','Avoid bouncing the weights at the bottom position to prevent injury and maintain muscle tension','Use a full range of motion but don''t lower the weights beyond a comfortable stretch in your chest','Maintain a slight bend in your elbows at the top position rather than locking them out completely','Choose a weight that allows you to complete all repetitions with proper form rather than using maximum weight']::text[],'chest','{}'::text[],'dumbbell','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','094f1299-cd52-4da7-b97f-c159208ed7d1','Incline Dumbbell Rear Delt Raise','incline-dumbbell-rear-delt-raise','Starting position: Lie face down on an incline bench with a dumbbell in each hand hanging downward. Execution: Raise the dumbbells out to the sides until they reach shoulder height, then slowly lower.',ARRAY['Set an incline bench to 45-60 degrees and lie face down with your chest against the pad, feet firmly planted on the floor','Hold a dumbbell in each hand with arms hanging straight down, palms facing each other','Keeping a slight bend in your elbows, raise the dumbbells out to your sides until your arms are parallel to the floor','Squeeze your shoulder blades together at the top of the movement, focusing on contracting your rear delts','Slowly lower the weights back to the starting position with control','Repeat for desired repetitions while maintaining proper form throughout']::text[],ARRAY['Use lighter weights than you think you need - the rear delts are smaller muscles and don''t require heavy resistance','Keep your core engaged and avoid arching your back excessively against the bench','Focus on squeezing your shoulder blades together rather than just lifting your arms up','Maintain the slight elbow bend throughout the entire movement to protect your joints','Control the lowering portion of the exercise - don''t let gravity drop the weights']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e60ce7d6-d899-4620-ac42-faa079614220','Incline Dumbbell Reverse Fly','incline-dumbbell-reverse-fly','Starting position: Lie face down on an incline bench with a dumbbell in each hand hanging downward. Execution: Raise the dumbbells out to the sides until they reach shoulder height, then slowly lower.',ARRAY['Set an incline bench to 30-45 degrees and lie face down with your chest pressed against the pad','Hold a dumbbell in each hand with a neutral grip, allowing your arms to hang straight down','Keep a slight bend in your elbows throughout the entire movement','Raise the dumbbells out to your sides in a controlled arc motion until your arms are parallel to the floor','Squeeze your shoulder blades together at the top of the movement','Slowly lower the weights back to the starting position with control']::text[],ARRAY['Keep your core engaged and maintain contact between your chest and the bench throughout the exercise','Focus on initiating the movement from your rear deltoids rather than using momentum','Use lighter weights than you think you need as this exercise targets smaller muscle groups','Avoid lifting your head or arching your back excessively during the movement','Control the eccentric portion of the lift to maximize muscle activation']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','812f7c37-8718-4fa6-8ad2-9c1080da9873','Incline Dumbbell Row','incline-dumbbell-row','Starting position: Lie face down on an incline bench with a dumbbell in each hand hanging downward. Execution: Pull the dumbbells toward the sides of your chest while keeping your back straight, then slowly lower to the starting position.',ARRAY['Set an adjustable bench to a 30-45 degree incline and lie face down with your chest supported against the pad','Hold a dumbbell in each hand with a neutral grip, allowing your arms to hang straight down','Plant your feet firmly on the floor for stability and engage your core','Pull the dumbbells up by driving your elbows back and squeezing your shoulder blades together','Hold the contraction briefly at the top, then slowly lower the weights back to the starting position','Maintain control throughout the entire range of motion']::text[],ARRAY['Keep your chest pressed against the bench throughout the movement to maintain proper spinal alignment','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Avoid using momentum or swinging the weights - control the tempo on both the lifting and lowering phases','Keep your shoulders down and back, avoiding any shrugging motion during the exercise','Choose a weight that allows you to maintain proper form for all repetitions']::text[],'back','{}'::text[],'dumbbell','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','00a92c05-9865-489d-8495-a8f72af802a6','Incline Machine Press','incline-machine-press','Starting position: Sit in an incline press machine, adjusting the seat height so the handles are at chest level. Execution: Push the handles forward until your arms are fully extended, then slowly return to the starting position.',ARRAY['Adjust the incline bench to 30-45 degrees and set the appropriate weight on the machine','Sit on the bench with your back flat against the pad and feet firmly planted on the floor','Grip the handles with hands slightly wider than shoulder-width apart, palms facing forward','Press the handles up and slightly forward in a smooth arc until your arms are fully extended','Slowly lower the weight back to the starting position with control, feeling a stretch in your chest','Repeat for desired number of repetitions without locking out your elbows completely']::text[],ARRAY['Keep your core engaged and maintain contact between your back and the bench throughout the movement','Focus on squeezing your chest muscles at the top of the movement for maximum muscle activation','Control the negative (lowering) portion of the lift - don''t let the weight drop quickly','Breathe out during the pressing phase and breathe in while lowering the weight','Start with lighter weight to master the form before progressing to heavier loads']::text[],'chest','{}'::text[],'machine','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','da022ba5-3a51-4861-9b25-232529d5de8e','Incline Machine Shoulder Press','incline-machine-shoulder-press','Starting position: Sit on an incline shoulder press machine, adjusting the seat height so the handles are at shoulder level. Execution: Push the handles upward until arms are fully extended, then slowly return to starting position.',ARRAY['Adjust the seat height so the handles align with your shoulders when seated','Set your back firmly against the pad and plant your feet flat on the floor for stability','Grasp the handles with a full grip, positioning your hands slightly wider than shoulder-width','Press the weight up in a smooth, controlled motion without locking your elbows aggressively','Lower the weight slowly with control, stopping when your elbows reach about 90 degrees','Maintain steady breathing throughout the movement, exhaling on the press and inhaling on the descent']::text[],ARRAY['Keep your core engaged and avoid arching your lower back excessively during the press','Focus on pressing the weight up and slightly forward following the natural arc of shoulder movement','Use a full range of motion but avoid lowering the weight too far to prevent shoulder impingement','Start with lighter weight to master the movement pattern before progressing to heavier loads','Maintain control throughout the entire range of motion, especially during the lowering phase']::text[],'shoulders','{}'::text[],'machine','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','95a95a22-308a-4804-af36-7190b48b1ae5','Inclined diamond push up','inclined-diamond-push-up','Starting position: Place hands on an inclined surface (bench, step, or sturdy platform) forming a diamond shape with thumbs and index fingers touching, body in straight plank position with feet on the ground. Execution: Lower your chest toward the diamond formed by your hands, then press back up to starting position while maintaining rigid body alignment.',ARRAY['Find a stable inclined surface at an appropriate height for your fitness level','Place hands on the surface forming a diamond shape with thumbs and index fingers touching','Step feet back until your body forms a straight line from head to heels','Lower your chest slowly toward the diamond formed by your hands until chest nearly touches','Press through your palms to return to starting position while keeping core engaged','Maintain controlled movement throughout the entire range of motion']::text[],ARRAY['Keep your core tight and body in a straight line throughout the movement to prevent sagging hips','The diamond hand position targets the triceps more than regular push-ups while still working the chest','Start with a higher incline and progress to lower angles as you build strength','Avoid flaring elbows too wide - keep them at roughly 45 degrees from your torso','Control the descent to maximize muscle engagement and prevent injury']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','204d2666-432a-400b-bf88-0b47203101ee','Inclined push up','inclined-push-up','Starting position: Place hands on an elevated surface like a bench or step, slightly wider than shoulder-width apart, with body in a straight line from head to heels. Execution: Lower your chest toward the elevated surface by bending your elbows, then push back up to the starting position.',ARRAY['Position hands on a stable elevated surface with fingers pointing forward and arms fully extended','Step feet back until your body forms a straight line from head to heels','Keep your core engaged and maintain neutral spine alignment throughout the movement','Lower your body by bending elbows until chest nearly touches the elevated surface','Push through your palms to return to starting position with control','Maintain steady breathing throughout the entire range of motion']::text[],ARRAY['Keep your body in a straight plank position without letting hips sag or pike upward','The higher the surface, the easier the exercise becomes for beginners','Maintain a controlled tempo rather than rushing through repetitions','Keep elbows at approximately 45-degree angle from your torso to protect shoulders','Ensure the elevated surface is stable and can support your body weight safely']::text[],'chest','{}'::text[],'bodyweight','chest','beginner',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0ba53212-9702-4b66-bb9d-d7b9fa12abf2','Inclined wide push up','inclined-wide-push-up',null,ARRAY['Place your hands on an elevated surface (bench, step, or sturdy chair) wider than shoulder-width apart, with fingers pointing forward','Step your feet back until your body forms a straight line from head to heels, engaging your core','Lower your chest toward the elevated surface by bending your elbows outward at roughly 45 degrees from your body','Descend until your chest nearly touches the surface or you feel a stretch across your chest','Push through your palms to return to the starting position, keeping your body in a straight line','Repeat for desired repetitions while maintaining proper form throughout']::text[],ARRAY['Keep your core tight and avoid letting your hips sag or pike upward','The higher the surface, the easier the exercise becomes - adjust height based on your fitness level','Focus on controlled movement rather than speed, taking 2-3 seconds to lower and 1-2 seconds to push up','Stop if you feel pain in your wrists, shoulders, or lower back','Wide hand placement targets the outer chest muscles more than standard push-ups']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0bc74c4c-d382-46a4-95a8-d6229062aaf1','inverted row','inverted-row-ce1cdb','Starting position: Set a barbell in a rack at about waist height, grip it slightly wider than shoulder-width with an overhand grip, and hang underneath with your body straight and heels on the floor. Execution: Pull your chest up toward the bar by driving your elbows back and squeezing your shoulder blades together, then lower under control to full arm extension.',ARRAY['Position the bar at waist height and grip it slightly wider than shoulder-width with an overhand grip.','Extend your arms and hang beneath the bar with your body in a straight line from head to heels.','Pull your chest toward the bar by retracting the shoulder blades and driving the elbows down and back.','Pause briefly when your chest nears the bar, squeezing your back muscles.','Lower yourself under control until your arms are fully extended.','Repeat for the desired number of repetitions, keeping your body rigid throughout.']::text[],ARRAY['Keep your body in a straight line from head to heels; avoid sagging at the hips.','Lead with your chest and squeeze the shoulder blades together at the top.','Control the descent rather than dropping quickly.','Keep your neck neutral and avoid shrugging your shoulders toward your ears.']::text[],'back',ARRAY['biceps','rear_deltoids','forearms','core']::text[],'barbell','strength','intermediate',ARRAY['strength','calisthenics','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','18a33c56-c0b1-4f28-bb78-4b4cad53372b','Jacks with high knees','jacks-with-high-knees','Starting position: Stand upright with feet together and arms at your sides. Execution: Alternate between jumping jacks and high knee marches, combining the arm movements of jumping jacks with alternating knee lifts to chest height.',ARRAY['Stand with feet together, arms at your sides, and engage your core','Jump feet apart while raising arms overhead, then immediately bring feet back together while lowering arms','Without pausing, lift your right knee up toward your chest while keeping arms in jumping jack motion','Lower right leg and immediately lift left knee toward chest, continuing the arm movements','Continue alternating between jumping jacks and high knee lifts in a fluid, rhythmic pattern','Maintain controlled breathing throughout the entire movement sequence']::text[],ARRAY['Keep your core engaged throughout to protect your lower back and maintain balance','Land softly on the balls of your feet to reduce impact on joints','Drive knees up to at least hip height for maximum effectiveness','Maintain an upright posture and avoid leaning forward during knee lifts','Start at a moderate pace and increase speed only when you can maintain proper form']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','hiit','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','703cabb7-a8d3-4fe8-a4e0-a5f931c7ddde','Jump get ups','jump-get-ups','Starting position: Lie flat on your back with arms at your sides and legs extended. Execution: Explosively sit up while simultaneously bringing your knees to your chest, then place your feet on the ground and jump straight up with arms overhead before returning to the starting position.',ARRAY['Lie flat on your back with arms relaxed at your sides and legs fully extended','Engage your core and explosively sit up while pulling your knees toward your chest','Plant your feet firmly on the ground shoulder-width apart as you transition to a squat position','Drive through your heels and jump straight up, reaching your arms overhead','Land softly with bent knees and immediately lower back down to the starting lying position','Control the descent to avoid jarring your back against the floor']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Land softly on the balls of your feet with knees slightly bent to absorb impact','Maintain smooth, controlled transitions between each phase of the movement','Start slowly to master the coordination before increasing speed or intensity','Stop immediately if you experience any back pain or dizziness']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['plyometric','cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','028fd0e4-baf8-4633-9891-20613bdea1e8','Jump knee tucks','jump-knee-tucks',null,ARRAY['Stand with feet hip-width apart, arms at your sides, and engage your core','Jump straight up explosively while simultaneously bringing both knees toward your chest','Grab your shins or knees briefly with your hands at the peak of the jump','Release your legs and extend them downward to prepare for landing','Land softly on the balls of your feet with knees slightly bent to absorb impact','Immediately reset to starting position and repeat for desired repetitions']::text[],ARRAY['Land softly with bent knees to protect your joints and reduce impact stress','Keep your core engaged throughout the entire movement to maintain stability','Focus on jumping straight up rather than forward to maintain proper form','Start with lower intensity and gradually increase speed as you master the technique','Stop immediately if you experience knee or ankle pain']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','921feb95-16c7-4fbc-88e7-472f35ffae2e','Jump squat to backward lunge','jump-squat-to-backward-lunge','Starting position: Stand with feet shoulder-width apart, arms extended forward for balance. Execution: Perform a jump squat by squatting down and explosively jumping up, then immediately transition into a backward lunge upon landing.',ARRAY['Stand with feet shoulder-width apart and extend arms forward for balance','Lower into a squat position by bending knees and pushing hips back','Explosively jump straight up from the squat position','Land softly on the balls of your feet with knees slightly bent','Immediately step one foot back into a lunge position','Return to starting position and repeat the sequence']::text[],ARRAY['Keep your chest up and core engaged throughout the entire movement','Land softly to reduce impact on joints and maintain control','Maintain proper squat depth with knees tracking over toes','Use your arms for balance and momentum during the jump phase','Control the transition between jump squat and lunge to prevent injury']::text[],'quads','{}'::text[],'bodyweight','legs',null,ARRAY['plyometric','strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
