insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4aa034b9-f826-4b1b-a259-45144fca1074','Jumping Jack','jumping-jack-2fb335','Starting position: Stand upright with feet together, arms relaxed at your sides. Execution: Simultaneously jump your feet out wide while swinging your arms overhead, then jump back to the starting position, repeating in a continuous rhythm.',ARRAY['Stand tall with feet together and arms by your sides.','Bend your knees slightly and jump, spreading your feet wider than shoulder-width.','Simultaneously raise your arms out and up overhead.','Jump again, bringing your feet back together and lowering your arms to your sides.','Repeat the movement at a steady, controlled pace.']::text[],ARRAY['Land softly on the balls of your feet to absorb impact.','Keep your core engaged and maintain an upright posture throughout.','Coordinate arm and leg movements for a smooth rhythm.','Breathe steadily and avoid locking your knees on landing.']::text[],'full_body',ARRAY['lateral_deltoids','hip_flexors','core']::text[],'bodyweight','cardio','beginner',ARRAY['cardio','plyometric','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8bc22d59-cc73-483b-b12c-515e974f39a6','Jumping jacks','jumping-jacks','Starting position: Stand upright with feet together, arms at your sides, and core engaged. Execution: Jump while simultaneously spreading your feet shoulder-width apart and raising your arms overhead, then jump back to the starting position in one fluid motion.',ARRAY['Stand tall with feet together and arms relaxed at your sides','Jump up while spreading your feet wider than shoulder-width apart','Simultaneously raise both arms out to the sides and overhead in an arc motion','Land softly on the balls of your feet with knees slightly bent','Jump again while bringing feet back together and lowering arms to starting position','Maintain a steady rhythm throughout the exercise']::text[],ARRAY['Land softly on the balls of your feet to reduce impact on joints','Keep your core engaged throughout the movement to maintain stability','Start at a comfortable pace and gradually increase speed as you build endurance','Avoid locking your knees when landing to prevent joint stress','Breathe rhythmically - exhale on the jump out, inhale on the jump in']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','55ce943e-c8ad-479b-bd92-10ba1d01889e','Jumping lunges','jumping-lunges','Starting position: Stand with feet hip-width apart, then step one foot back into a lunge position with both knees bent at 90 degrees. Execution: Explosively jump up while switching leg positions mid-air, landing softly in a lunge with the opposite leg forward.',ARRAY['Begin in a standard lunge position with your front knee directly over your ankle and back knee hovering just above the ground','Engage your core and prepare for an explosive upward movement by loading through both legs','Jump straight up powerfully, driving through your front heel and back toe simultaneously','While airborne, quickly switch your leg positions so the back leg moves forward and the front leg moves back','Land softly on the balls of your feet, immediately sinking into the lunge position with the opposite leg now forward','Maintain control throughout the movement and pause briefly before repeating the jump']::text[],ARRAY['Land softly with bent knees to absorb impact and protect your joints from excessive stress','Keep your torso upright and core engaged throughout the entire movement to maintain proper alignment','Ensure your front knee tracks over your toes and doesn''t cave inward during landing','Start with smaller jumps and focus on form before progressing to higher, more explosive movements','Allow adequate rest between sets as this is a high-intensity plyometric exercise that requires full recovery']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['plyometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ba7727ee-e0bb-402c-99fb-c27eadd440f7','Jumping Ropes  skips','jumping-ropes-skips','Starting position: Stand upright with feet together, holding the jump rope handles at your sides with elbows close to your body. Execution: Rotate the rope overhead using wrist movement while jumping lightly off both feet, landing softly on the balls of your feet as the rope passes underneath.',ARRAY['Hold rope handles with a relaxed grip, positioning hands at hip level with elbows bent at your sides','Start with the rope behind your heels and swing it overhead using primarily wrist rotation rather than arm movement','Jump only high enough for the rope to pass under your feet, maintaining a slight bend in your knees','Land softly on the balls of your feet with each jump, keeping your core engaged and posture upright','Begin with short intervals of 30-60 seconds and gradually increase duration as coordination improves','If you miss or trip, simply restart the rhythm without stopping your workout momentum']::text[],ARRAY['Keep jumps low and controlled - only lift feet 1-2 inches off the ground to reduce impact on joints','Focus on wrist rotation rather than using your entire arms to turn the rope for better efficiency and less fatigue','Maintain an upright posture with shoulders relaxed and eyes looking forward, not down at your feet','Start slowly to develop rhythm and coordination before increasing speed or attempting advanced footwork patterns','Choose appropriate rope length by standing on the center - handles should reach approximately armpit height']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cf5916de-b5e4-434c-9cc3-20d729baec1e','Kettlebell Clean','kettlebell-clean-e4c789','Starting position: Stand with feet hip-width apart, kettlebell on floor between feet. Execution: Explosively drive hips forward to pull kettlebell up and catch it at shoulder level.',ARRAY['Stand over kettlebell with feet hip-width apart','Hinge at hips and grab kettlebell handle','Drive hips forward explosively while pulling kettlebell upward','Guide kettlebell around wrist as it rises','Catch kettlebell in rack position at shoulder','Lower kettlebell back to starting position with control']::text[],ARRAY['Keep your back straight and chest up throughout the movement','Use hip drive, not arm pull, to generate power','Let the kettlebell flip around your wrist smoothly into rack position','Keep your core engaged to protect your lower back','Practice the hip hinge movement before adding explosive power']::text[],'ketllebell',ARRAY['lats','front_deltoids','calves']::text[],'kettlebell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','94e15f81-eee6-418c-9c25-6201b6c9f23e','Kettlebell Deadlift','kettlebell-deadlift-b4f285','Starting position: Stand with feet hip-width apart, kettlebell on floor between feet. Execution: Hinge at hips to grip kettlebell, then drive through heels to stand tall.',ARRAY['Stand with feet hip-width apart behind the kettlebell','Hinge at hips and bend knees to grip kettlebell handle','Keep chest up and shoulders back throughout the movement','Drive through heels and extend hips to lift kettlebell','Lower kettlebell by pushing hips back and bending knees','Return to starting position with control']::text[],ARRAY['Keep the kettlebell close to your body throughout the entire movement','Initiate the movement by pushing your hips back, not by bending your knees first','Maintain a neutral spine and avoid rounding your back','Squeeze your glutes at the top of the movement for full hip extension','Your knees should track in line with your toes during the movement']::text[],'ketllebell','{}'::text[],'kettlebell',null,null,ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','98543b7d-bf77-48b2-b0e1-f17ae61e3fc2','Kettlebell Farmer Carry','kettlebell-farmer-carry-91419a','Starting position: Stand tall holding kettlebells at your sides with arms straight. Execution: Walk forward maintaining upright posture while gripping the kettlebells.',ARRAY['Grip kettlebells firmly with neutral wrists','Stand tall with shoulders back and core engaged','Begin walking with controlled, deliberate steps','Keep kettlebells close to your body','Maintain steady breathing throughout the walk','Set kettlebells down with control when finished']::text[],ARRAY['Keep your shoulders level and avoid leaning to one side','Maintain a tight grip to prevent the kettlebells from slipping','Walk with your normal stride length to avoid compensation patterns','Stop immediately if your grip begins to fail for safety']::text[],'ketllebell',ARRAY['obliques','calves','upper_back']::text[],'kettlebell','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fa5618bb-f1c9-4911-aa11-f971d99b9fc2','Kettlebell Farmer Carry','kettlebell-farmer-carry-108ca4','Starting position: Stand upright holding kettlebells at your sides with arms extended. Execution: Walk forward in a straight line while maintaining proper posture and grip.',ARRAY['Grip kettlebells firmly with neutral wrists','Stand tall with shoulders back and core engaged','Begin walking forward with controlled steady steps','Keep kettlebells close to your body sides','Maintain upright posture throughout the walk','Set kettlebells down gently when finished']::text[],ARRAY['Keep your shoulders pulled back to prevent rounding forward','Engage your core throughout to protect your lower back','Take controlled steps rather than rushing the movement','Grip strength will fatigue before other muscles typically do']::text[],'ketllebell','{}'::text[],'kettlebell',null,null,ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d921fc6e-a678-468b-9500-740437cb0265','Kettlebell Figure-8','kettlebell-figure-8-bad71d','Starting position: Stand with feet wider than shoulder-width, holding kettlebell in one hand between legs. Execution: Pass the kettlebell in a figure-8 pattern around and between your legs.',ARRAY['Stand with feet wider than shoulder-width apart','Hold kettlebell in right hand between your legs','Pass kettlebell around right leg to back','Switch hands behind right leg','Bring kettlebell forward around left leg','Switch hands in front and repeat pattern']::text[],ARRAY['Keep your back straight and chest up throughout the movement','Bend at hips and knees to maintain proper posture','Control the kettlebell smoothly without letting it swing wildly','Keep the kettlebell close to your body during hand switches','Start with lighter weight to master the coordination pattern']::text[],'ketllebell',ARRAY['forearm_flexors','adductors','rectus_abdominis','lower_back']::text[],'kettlebell','strength','intermediate',ARRAY['functional','core']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','78f8c25f-32b2-4d60-a331-a756f793a892','Kettlebell Goblet Squat','kettlebell-goblet-squat-3bab23','Starting position: Hold kettlebell at chest with both hands, feet shoulder-width apart. Execution: Lower into squat position then drive through heels to return to standing.',ARRAY['Hold kettlebell by horns against your chest','Position feet shoulder-width apart with toes slightly outward','Lower body by pushing hips back and bending knees','Descend until thighs are parallel to floor','Drive through heels to return to starting position','Keep kettlebell close to chest throughout movement']::text[],ARRAY['Keep your chest up and core engaged throughout the entire movement','Ensure knees track in line with your toes during descent and ascent','The kettlebell should remain close to your body at chest level','Focus on sitting back with your hips rather than just bending knees','Maintain neutral spine position and avoid rounding your back']::text[],'ketllebell','{}'::text[],'kettlebell',null,null,ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bc6934d4-fe50-45ff-a40f-9d751f75c4a2','Kettlebell Halo','kettlebell-halo-11bb27','Starting position: Hold kettlebell by the handle with both hands at chest level. Execution: Circle the kettlebell around your head in a controlled halo motion.',ARRAY['Grip kettlebell handle with both hands at chest height','Keep core engaged and feet shoulder-width apart','Slowly circle kettlebell around your head clockwise','Maintain control as kettlebell passes behind your head','Complete the circle returning to starting position','Reverse direction for counterclockwise rotations']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your spine','Use a light weight initially to master the movement pattern','Maintain upright posture and avoid leaning forward or backward','Control the kettlebell at all times, especially behind your head','Start with small circles and gradually increase range of motion']::text[],'ketllebell',ARRAY['rotator_cuff','triceps','core','upper_back']::text[],'kettlebell','strength','intermediate',ARRAY['strength','mobility']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "update