insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','516ed8ba-873f-441b-a5a6-c52ab7fc048a','Kettlebell Lunge','kettlebell-lunge-424813','Starting position: Hold kettlebell at chest level with both hands, standing tall with feet hip-width apart. Execution: Step back into a lunge while maintaining kettlebell position, then return to standing.',ARRAY['Hold kettlebell at chest with both hands','Step one foot back into lunge position','Lower back knee toward the ground','Push through front heel to return upright','Alternate legs or complete set per side']::text[],ARRAY['Keep your torso upright and core engaged throughout the movement','Ensure your front knee tracks over your ankle, not past your toes','Step back far enough so your front thigh becomes parallel to the ground','Maintain a firm grip on the kettlebell close to your chest','Control the descent and avoid letting your back knee slam into the ground']::text[],'kettlebell-exercises',ARRAY['hip_flexors','erector_spinae','forearms']::text[],'kettlebell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4f5c0add-7a97-4c69-ad76-e2d87c8d1cc1','Kettlebell Press','kettlebell-press-eab406','Starting position: Hold kettlebell at shoulder level with clean grip. Execution: Press kettlebell overhead in straight vertical path.',ARRAY['Clean kettlebell to shoulder position with neutral wrist','Engage core and maintain upright torso position','Press kettlebell straight up overhead until arm locks','Lower kettlebell back to starting shoulder position','Repeat movement maintaining control throughout range']::text[],ARRAY['Keep wrist straight and aligned with forearm throughout the movement','Avoid arching your back excessively when pressing overhead','Press the kettlebell in a straight vertical line directly above your shoulder','Engage your core muscles to maintain stability and proper posture','Lower the weight under control to maximize muscle engagement']::text[],'ketllebell',ARRAY['triceps_long_head','serratus_anterior','upper_back']::text[],'kettlebell','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2e95c001-ef00-4ecc-85a9-b97841927a29','Kettlebell Row','kettlebell-row-b11845','Starting position: Stand with feet hip-width apart holding kettlebell in one hand. Execution: Pull kettlebell up to ribs while hinging at hips.',ARRAY['Stand with feet hip-width apart holding kettlebell','Hinge forward at hips keeping back straight','Let kettlebell hang at arm''s length','Pull kettlebell up toward your ribs','Squeeze shoulder blade back at top','Lower kettlebell with control']::text[],ARRAY['Keep your core engaged throughout the entire movement','Avoid rotating your torso as you pull the kettlebell','Focus on pulling with your back muscles not your arm','Maintain a neutral spine position during the hip hinge','Keep your elbow close to your body during the pull']::text[],'ketllebell',ARRAY['biceps','rear_deltoids','forearms','erector_spinae']::text[],'kettlebell','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','46832c7a-fd0e-49ab-9961-11726b8b9064','Kettlebell Snatch','kettlebell-snatch-739b2c','Starting position: Stand with feet hip-width apart, kettlebell between legs. Execution: Explosively drive hips forward while pulling kettlebell overhead in one fluid motion.',ARRAY['Hinge at hips and grasp kettlebell with one hand','Pull kettlebell back between legs in hiking motion','Explosively drive hips forward and stand tall','Guide kettlebell overhead while rotating wrist under','Catch kettlebell with arm fully extended overhead','Lower kettlebell back to starting position with control']::text[],ARRAY['Keep the kettlebell close to your body throughout the movement','Generate power from your hips and legs, not your arms','Maintain a neutral spine and avoid leaning back at the top','Practice the hip hinge pattern before attempting full snatches','Start with lighter weight to master timing and coordination']::text[],'ketllebell',ARRAY['front_deltoids','erector_spinae','lats','forearm_flexors']::text[],'kettlebell','strength','advanced',ARRAY['strength','plyometric','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3bbed598-16f4-4683-a751-10cc264b4bd6','Kettlebell swing','kettlebell-swing','Starting position: Stand with feet shoulder-width apart, holding a kettlebell with both hands, hinging at the hips with knees slightly bent and torso leaning forward. Execution: Drive through the hips to swing the kettlebell up while maintaining a neutral spine and engaged core.',ARRAY['Stand with feet shoulder-width apart and grip the kettlebell handle with both hands','Hinge at the hips by pushing your hips back and bending knees slightly, keeping your back straight','Allow the kettlebell to swing between your legs while maintaining control','Drive your hips forward explosively to propel the kettlebell upward','Keep your arms straight and let the momentum from your hips power the movement','Control the kettlebell as it swings back down and repeat the hip hinge motion']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','The power comes from your hips, not your arms - focus on the hip thrust motion','Maintain a neutral spine and avoid rounding your back during the movement','Keep your shoulders back and chest up throughout the exercise','Land softly on your heels when the kettlebell swings back down between your legs']::text[],'core','{}'::text[],'kettlebell','core',null,ARRAY['strength','functional','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1a3c2a1d-eb55-4199-8f9c-6d332c824c5d','Kettlebell swing - American style','kettlebell-swing-american-style','Starting position: Stand with feet hip-width apart, holding the kettlebell handle with both hands, arms extended overhead. Execution: Swing the kettlebell down between your legs in a controlled arc, then explosively drive through your hips to swing it back up overhead in one fluid motion.',ARRAY['Stand with feet hip-width apart and grip the kettlebell handle with both hands using an overhand grip','Begin with the kettlebell overhead with arms fully extended and core engaged','Initiate the downswing by hinging at the hips and allowing the kettlebell to swing down between your legs in a controlled manner','Keep your back straight and chest up throughout the entire movement','Explosively drive your hips forward and squeeze your glutes to propel the kettlebell back up to the overhead position','Allow the kettlebell to swing back down naturally and repeat the movement in a smooth rhythm']::text[],ARRAY['The power comes from your hips and glutes, not your arms - focus on the hip hinge movement','Keep your core tight throughout the entire range of motion to protect your lower back','Control the descent but be explosive on the upward drive to maintain proper momentum','Ensure the kettlebell reaches full overhead extension with arms straight at the top of each rep','Start with a lighter weight to master the technique before progressing to heavier kettlebells']::text[],'full_body','{}'::text[],'kettlebell','full body','intermediate',ARRAY['strength','functional','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','210c81cd-983c-4267-8514-b14090b038be','Kettlebell Swing (Single Arm)','kettlebell-swing-single-arm-13640c','Starting position: Stand with feet hip-width apart, kettlebell between legs, gripping handle with one hand. Execution: Drive hips forward explosively to swing kettlebell to shoulder height, then control the descent.',ARRAY['Stand with feet hip-width apart over the kettlebell','Hinge at hips and grip kettlebell handle with one hand','Engage core and drive hips forward explosively','Swing kettlebell up to shoulder height using hip momentum','Control the kettlebell back down between your legs','Switch hands at the bottom or complete set before switching']::text[],ARRAY['Keep your back straight and chest up throughout the movement','Power comes from hip drive, not arm lifting','The kettlebell should float momentarily at the top of the swing','Maintain a firm grip and keep wrist neutral','Land softly on each rep to protect your lower back']::text[],'ketllebell',ARRAY['erector_spinae','front_deltoids','obliques','forearm_flexors']::text[],'kettlebell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7cbbde6d-73c7-4f94-a217-927d3bbdfd2b','Kettlebell Swing (Two Hand)','kettlebell-swing-two-hand-d5e8c3','Starting position: Stand with feet shoulder-width apart, kettlebell on floor between feet. Execution: Drive hips forward explosively to swing kettlebell to chest height.',ARRAY['Stand with feet shoulder-width apart over the kettlebell','Hinge at hips and grip kettlebell with both hands','Drive hips forward explosively while standing up tall','Let kettlebell swing up to chest height naturally','Control the kettlebell back down between your legs','Repeat the hip hinge and explosive hip drive']::text[],ARRAY['Keep your back straight and chest up throughout the movement','The power comes from your hips, not your arms or shoulders','Let the kettlebell float at the top rather than lifting it','Maintain a firm grip but relaxed arms during the swing','Land softly on your heels when the kettlebell swings back down']::text[],'ketllebell',ARRAY['front_deltoids','erector_spinae','adductors','forearm_flexors']::text[],'kettlebell','strength','intermediate',ARRAY['strength','hiit']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
