insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','75a4cce2-a779-4b2e-b5e1-94f8587eda7b','Kettlebell Windmill','kettlebell-windmill-762fe6','Starting position: Stand with feet wide, holding kettlebell overhead in one hand. Execution: Hinge at hip while keeping kettlebell arm vertical, reaching opposite hand toward floor.',ARRAY['Hold kettlebell overhead with straight arm','Stand with feet wider than shoulder width','Turn feet slightly away from kettlebell side','Hinge at hip and reach free hand down','Keep eyes on kettlebell throughout movement','Return to standing position by driving hips forward']::text[],ARRAY['Keep the overhead arm completely straight and locked throughout the entire movement','Focus on hip hinge movement rather than lateral bending of the spine','Maintain tight core engagement to protect the lower back','Start with lighter weight to master the movement pattern before progressing','Keep your eyes on the kettlebell to maintain proper shoulder stability']::text[],'ketllebell',ARRAY['rotator_cuff','transverse_abdominis','hip_flexors']::text[],'kettlebell','strength','advanced',ARRAY['strength','balance','mobility']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = exclu