insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9b0e714f-6b42-40d9-941c-71bca4da5eef','Knee pseudo pushups','knee-pseudo-pushups','Starting position: Begin in a standard push-up position, then lower your knees to the ground while keeping your hands planted firmly on the floor shoulder-width apart. Execution: Lower your chest toward the ground by bending your elbows, then push back up to the starting position while maintaining a straight line from your knees to your head.',ARRAY['Position your hands on the floor shoulder-width apart with fingers spread wide for stability','Lower your knees to the ground and cross your ankles behind you','Create a straight line from your knees through your hips to the top of your head','Lower your chest toward the floor by bending your elbows at a 45-degree angle from your body','Push through your palms to return to the starting position','Maintain control throughout both the lowering and pushing phases']::text[],ARRAY['Keep your core engaged throughout the entire movement to prevent your hips from sagging','Focus on a controlled tempo rather than speed to maximize muscle engagement','Position your hands directly under your shoulders to optimize force distribution','Avoid flaring your elbows too wide as this can strain the shoulder joints','Progress gradually by increasing repetitions before attempting standard push-ups']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d33da8f6-37a9-4730-8399-c4c5be3a7f00','Knee push ups','knee-push-ups','Starting position: Kneel on the floor with hands placed shoulder-width apart on the ground, forming a straight line from your head to your knees. Execution: Lower your chest toward the floor by bending your elbows, then push back up to the starting position while maintaining proper body alignment.',ARRAY['Position yourself on your knees with hands flat on the floor directly under your shoulders','Keep your core engaged and maintain a straight line from your head to your knees throughout the movement','Lower your body slowly by bending your elbows until your chest nearly touches the floor','Push through your palms to return to the starting position with control','Keep your elbows at roughly a 45-degree angle from your torso rather than flaring them straight out','Breathe in as you lower down and exhale as you push up']::text[],ARRAY['Avoid letting your hips sag or pike up during the movement to maintain proper form','Focus on controlled movement rather than speed to maximize muscle engagement and prevent injury','Keep your head in a neutral position by looking slightly ahead rather than straight down','Start with fewer repetitions and gradually increase as your strength improves','Place a towel under your knees for comfort if needed']::text[],'chest','{}'::text[],'bodyweight','chest','beginner',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','36034a77-8bbc-46c9-bf91-1c310704bf3b','Knee raise marches','knee-raise-marches','Starting position: Stand tall with feet hip-width apart, arms at your sides, and core engaged. Execution: Alternately lift each knee up toward your chest while maintaining an upright posture, creating a controlled marching motion.',ARRAY['Stand with feet hip-width apart and engage your core muscles','Lift your right knee up toward your chest to about hip level while keeping your torso upright','Lower your right foot back to the starting position with control','Immediately lift your left knee up toward your chest to the same height','Continue alternating legs in a smooth, controlled marching pattern','Maintain steady breathing throughout the movement']::text[],ARRAY['Keep your core tight throughout the entire movement to maximize abdominal engagement','Avoid leaning backward or forward as you lift each knee','Lift knees to hip level or as high as comfortable while maintaining good form','Control the descent of each leg rather than letting it drop down quickly','Start with shorter duration sets and gradually increase time as your core strength improves']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f50de65b-ab30-4b37-a472-d4cab681916c','Knee raises','knee-raises','Starting position: Stand upright with feet hip-width apart, hands on hips or hanging at your sides for balance. Execution: Lift one knee up toward your chest as high as comfortable, then lower it back down with control and repeat on the opposite side.',ARRAY['Stand tall with your core engaged and shoulders back','Lift your right knee up toward your chest, aiming to bring your thigh parallel to the floor','Hold briefly at the top of the movement','Lower your leg back down with control to the starting position','Repeat the movement with your left leg','Continue alternating legs for the desired number of repetitions']::text[],ARRAY['Keep your core tight throughout the entire movement to maintain stability and maximize effectiveness','Avoid leaning backward or using momentum to lift your knees higher','Focus on controlled movements rather than speed to properly engage the abdominal muscles','Maintain good posture with chest up and shoulders back throughout the exercise','If balance is challenging, perform the exercise near a wall or chair for light support']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0b7f1b84-6cb0-4875-824b-e86272668a2a','Knee raises (Hanging)','knee-raises-hanging',null,ARRAY['Hang from a pull-up bar with an overhand grip, arms fully extended and feet off the ground','Engage your core and keep your shoulders pulled down and back to maintain stability','Slowly lift your knees toward your chest by flexing your hip and abdominal muscles','Pause briefly when your thighs reach parallel to the ground or higher','Lower your legs back to the starting position with control, avoiding swinging','Repeat for desired repetitions while maintaining proper form throughout']::text[],ARRAY['Keep your grip secure and avoid swinging or using momentum to lift your legs','Focus on controlled movements rather than speed to maximize core engagement','If you can''t maintain proper form, try bent-knee raises or use straps to assist your grip','Keep your shoulders engaged and avoid hanging passively to protect your shoulder joints','Start with shorter holds and fewer reps, progressing gradually as your core strength improves']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c8b7a380-562e-4ad2-8dfc-7a29b5c56418','Knee to Chest Stretch (L)','knee-to-chest-stretch-l','Starting position: Stand upright with feet hip-width apart, maintaining good posture with shoulders back and core engaged. Execution: Lift your left knee up toward your chest while grasping it with both hands, holding the stretch to feel a gentle pull in your hip flexors and lower back.',ARRAY['Stand tall with feet hip-width apart and arms at your sides','Slowly lift your left knee up toward your chest as high as comfortable','Grasp your left knee with both hands, interlacing your fingers around your shin','Gently pull your knee closer to your chest while maintaining balance on your right leg','Hold the stretch for 20-30 seconds while breathing deeply','Slowly release your hands and lower your left leg back to the starting position']::text[],ARRAY['Keep your standing leg slightly bent and engage your core for better balance','Avoid pulling too aggressively on your knee - the stretch should feel gentle and comfortable','Maintain upright posture throughout the movement, avoiding leaning backward','If you have difficulty balancing, perform this stretch near a wall or sturdy surface for support','Focus on steady breathing during the hold to enhance the stretching benefit']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','dd76f6bd-dddd-4f97-bf96-29048ec2547e','Knee to Chest Stretch (R)','knee-to-chest-stretch-r','Starting position: Stand upright with feet hip-width apart and arms at your sides. Execution: Lift your right knee up toward your chest while grasping it with both hands, gently pulling it closer to stretch the hip and glute muscles.',ARRAY['Stand tall with your feet hip-width apart and maintain good posture','Slowly lift your right knee up toward your chest as high as comfortably possible','Grasp your right shin or knee with both hands and gently pull it closer to your body','Hold the stretch position while keeping your standing leg straight and stable','Breathe deeply and relax into the stretch','Slowly release your hands and lower your leg back to the starting position']::text[],ARRAY['Keep your standing leg straight and engage your core for better balance','Avoid bouncing or forcing the stretch - use gentle, steady pressure','Focus on feeling the stretch in your hip flexors and glute muscles','Maintain an upright posture and avoid leaning backward','Hold the stretch for 15-30 seconds for optimal benefit']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e73256fc-b329-4dfa-834b-d0c485bcad72','Knee tucked Side plank up and downs (Left)','knee-tucked-side-plank-up-and-downs-left','Starting position: Begin in a modified side plank position with knees tucked, supporting your body weight on your forearm and knees while lying on your left side. Execution: Lower your hip toward the ground then lift back up to the starting position, maintaining the knee-tucked side plank throughout the movement.',ARRAY['Position yourself on your left side with your left forearm planted firmly on the ground, elbow directly under your shoulder','Tuck both knees up toward your chest while maintaining a side plank position on your forearm and knees','Engage your core and lift your hips up to create a straight line from your head to your knees','Lower your hip down toward the ground in a controlled manner','Press back up to the starting side plank position by engaging your obliques and core muscles','Maintain steady breathing throughout the up and down movement']::text[],ARRAY['Keep your supporting elbow directly under your shoulder to prevent strain','Maintain core engagement throughout the entire movement to protect your spine','Control both the lowering and lifting phases - avoid dropping your hip quickly','Keep your knees tucked consistently rather than extending them during the movement','Focus on using your oblique muscles to initiate the lifting motion rather than momentum']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['strength','core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c9d2b9a8-7f3e-4b5f-9012-e8c17b80de07','Knee tucked Side plank up and downs (right','knee-tucked-side-plank-up-and-downs-right','Starting position: Begin in a side plank position lying on your right side with your right forearm on the ground, elbow directly under your shoulder, and knees bent with both knees touching the mat for support. Execution: Lower your hips down to the mat and then press back up to the side plank position while maintaining the knee-tucked position throughout the movement.',ARRAY['Lie on your right side with your right forearm planted firmly on the mat, elbow positioned directly under your shoulder','Bend both knees and keep them in contact with the mat for stability throughout the exercise','Engage your core and lift your hips up into a side plank position while keeping your knees bent','Slowly lower your hips down to touch the mat while maintaining control','Press back up to the starting side plank position by engaging your obliques and core muscles','Maintain the knee-bent position throughout all repetitions for consistent support']::text[],ARRAY['Keep your supporting elbow directly under your shoulder to prevent strain and maintain proper alignment','The bent-knee modification makes this exercise more accessible while still effectively targeting the obliques','Focus on controlled movement rather than speed to maximize core engagement','Keep your core tight throughout the entire range of motion to protect your lower back','Ensure your hips move in a straight up and down pattern rather than rolling forward or backward']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['strength','core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ac6026af-173a-4357-ac12-2c7440a71a5d','Kneeling jump squat','kneeling-jump-squat','Starting position: Begin in a deep squat position with feet shoulder-width apart, arms extended forward for balance, and weight shifted back onto your heels. Execution: Explosively jump up from the squat position, land softly back into the starting squat position, and immediately prepare for the next repetition.',ARRAY['Start in a deep squat with thighs parallel to the floor and arms extended forward','Keep your chest up and core engaged throughout the movement','Explosively drive through your heels to jump straight up','Land softly on the balls of your feet, immediately sinking back into the squat position','Maintain control during the landing phase to absorb impact','Continue the jumping motion in a rhythmic, controlled manner']::text[],ARRAY['Focus on landing softly to reduce impact on knees and joints','Keep your knees aligned with your toes during both takeoff and landing','Maintain an upright torso position throughout the entire movement','Use your arms for momentum and balance during the explosive phase','Control the landing by engaging your core and leg muscles']::text[],'quads','{}'::text[],'bodyweight','legs',null,ARRAY['plyometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7f8e01f5-2b17-487f-aa3a-5614b629ade2','L dumbbell raises','l-dumbbell-raises','Starting position: Stand with feet hip-width apart, holding a dumbbell in each hand at your sides with arms straight and palms facing your body. Execution: Simultaneously raise one arm out to the side and the other arm forward to shoulder height, creating an ''L'' shape, then lower both arms back to starting position and repeat with opposite arm positions.',ARRAY['Stand tall with core engaged and shoulders pulled back, holding dumbbells with a neutral grip','Begin with lighter weights to master the coordination of the dual-plane movement','Raise one arm laterally to the side while simultaneously raising the other arm forward, both to shoulder height','Hold briefly at the top position while maintaining control of both dumbbells','Lower both arms slowly and with control back to the starting position','Alternate which arm goes forward and which goes lateral with each repetition']::text[],ARRAY['Keep a slight bend in your elbows throughout the entire movement to protect the joints','Avoid using momentum or swinging the weights - focus on controlled, deliberate movements','Maintain proper posture with chest up and avoid leaning forward or backward during the exercise','Start with lighter weights than you would use for single-arm raises due to the increased coordination and stability demands','Stop immediately if you experience any shoulder pain or discomfort']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bb2079e0-031b-4b5c-873d-8c5202fc33d7','L-sit hold (dip bar or paralettes)1','l-sit-hold-dip-bar-or-paralettes1','Starting position: Grip dip bars or paralettes with arms fully extended, shoulders directly over hands, and legs hanging straight down. Execution: Lift your legs up to hip level creating an ''L'' shape with your body while maintaining straight arms and holding this position for the desired duration.',ARRAY['Grip the bars firmly with hands shoulder-width apart and arms completely straight','Engage your core and lift your legs up until they are parallel to the floor','Keep your shoulders depressed and away from your ears throughout the hold','Maintain straight legs and pointed toes while holding the L position','Breathe steadily and avoid holding your breath during the exercise','Lower your legs slowly and controlled when you can no longer maintain proper form']::text[],ARRAY['This exercise primarily targets the core and hip flexors rather than the chest despite the listed muscle group','Start with shorter holds of 10-15 seconds and gradually increase duration as strength improves','Keep shoulders actively depressed to prevent shoulder impingement and maintain proper form','If unable to perform full L-sit, progress by bending knees toward chest or performing supported holds','Stop immediately if you experience shoulder pain or cannot maintain straight arm position']::text[],'chest','{}'::text[],'bodyweight','chest','advanced',ARRAY['isometric','core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','92d81e10-c495-4bf9-b205-a079f8711097','L-sit to tucked L-sit','l-sit-to-tucked-l-sit','Starting position: Sit on the floor with legs extended straight in front of you, hands placed on the floor beside your hips with fingers pointing forward. Execution: Press through your hands to lift your entire body off the ground, then alternately hold the straight-leg L-sit position and tuck your knees toward your chest while maintaining the lift.',ARRAY['Warm up your wrists, shoulders, and core thoroughly before attempting this exercise','Start in the L-sit position by pressing firmly through your hands and lifting your body and straight legs off the ground','Hold the full L-sit for 2-3 seconds, keeping your legs parallel to the floor','Slowly draw your knees toward your chest to transition into the tucked position while maintaining the hand support','Hold the tucked L-sit for 2-3 seconds with knees close to your chest','Extend your legs back out to return to the full L-sit position and repeat the cycle']::text[],ARRAY['Keep your shoulders pulled down and away from your ears throughout the entire movement','Maintain strong arm and core engagement to prevent dropping to the floor during transitions','Focus on controlled movements rather than speed when transitioning between positions','If you cannot hold a full L-sit yet, practice the tucked position first to build strength','Stop immediately if you experience wrist or shoulder pain and consider using parallettes or push-up handles for wrist comfort']::text[],'core','{}'::text[],'bodyweight','core','advanced',ARRAY['strength','core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','920d96cd-7857-4720-9bea-21b23b124b64','Lat Pulldown','lat-pulldown','Starting position: Sit at a lat pulldown machine with a grip on the high pulleys. Execution: Pull the pulleys toward your chest, keeping elbows close to your body, then slowly return to the starting position.',ARRAY['Adjust the thigh pads so they rest comfortably on your legs to prevent your body from lifting during the movement','Sit upright with your chest out and maintain a slight lean back of about 15-20 degrees throughout the exercise','Grip the bar with your hands positioned wider than your shoulders using an overhand grip','Initiate the pull by drawing your shoulder blades down and back, then pull the bar toward your upper chest','Control the weight on the way up, allowing your arms to fully extend while maintaining tension in your lats','Keep your core engaged throughout the entire movement to maintain proper posture']::text[],ARRAY['Avoid pulling the bar behind your neck as this can cause shoulder impingement and injury','Focus on using your back muscles rather than your arms by thinking about pulling your elbows down and back','Don''t lean too far back or use momentum to complete the movement - this reduces effectiveness and increases injury risk','Maintain a controlled tempo with a 2-second pull down and 3-second return to maximize muscle engagement','Keep your shoulders down and away from your ears throughout the exercise to properly target the latissimus dorsi']::text[],'back','{}'::text[],'cable','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6f53a194-8a37-42ec-87f1-2bfed82e9006','Lat Pulldown (Reverse Grip)','lat-pulldown-reverse-grip-696301','Starting position: Sit at lat pulldown machine with reverse (underhand) grip on bar. Execution: Pull bar down to upper chest while squeezing shoulder blades together.',ARRAY['Sit upright at lat pulldown machine','Grasp bar with underhand grip shoulder-width apart','Pull bar straight down toward upper chest','Squeeze shoulder blades together at bottom position','Control the weight back to starting position','Keep chest up throughout entire movement']::text[],ARRAY['Keep your torso upright and avoid leaning back excessively','Focus on pulling with your lats rather than just your arms','Maintain a controlled tempo on both the pulling and lowering phases','Keep your shoulders down and back throughout the movement']::text[],'back',ARRAY['biceps','rhomboids','rear_deltoids','forearms']::text[],'machine','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1dfe9e16-f3bf-45c3-9536-b818c03d8bb8','Lat Pulldown with V-Grip','lat-pulldown-with-v-grip-5db2a5','Starting position: Sit at the lat pulldown machine with the V-grip attachment positioned at chest level. Execution: Pull the handle down toward your upper chest while squeezing your shoulder blades together.',ARRAY['Sit upright on the lat pulldown machine bench','Grasp the V-grip handle with both hands using neutral grip','Pull your shoulder blades down and back to engage','Draw the handle down toward your upper chest smoothly','Squeeze your lats at the bottom of the movement','Control the weight back to starting position slowly']::text[],ARRAY['Keep your torso upright and avoid leaning back excessively during the pull','Focus on pulling with your lats rather than using your biceps to dominate the movement','Maintain a slight arch in your lower back throughout the entire exercise','Control the eccentric portion of the lift to maximize muscle activation']::text[],'back','{}'::text[],'machine',null,null,ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b2ad9e74-2fdf-4cd2-b748-1449f2622216','Lateral leg swing','lateral-leg-swing-966946','Starting position: Stand tall beside a chair, placing one hand on the backrest for support with your weight shifted onto the supporting leg. Execution: Swing the outside leg out to the side and back across the body in a controlled, pendulum-like motion, keeping the torso upright and core engaged throughout.',ARRAY['Stand next to a chair and rest one hand lightly on it for balance.','Shift your weight onto the inside leg and keep it slightly bent.','Swing the outer leg laterally away from the body up to a comfortable height.','Return the leg across the midline of your body in a smooth arc.','Keep the movement controlled and repeat for the desired reps, then switch sides.']::text[],ARRAY['Keep your torso upright and avoid leaning to compensate for the swing.','Engage your core to stabilize the pelvis and control the motion.','Swing only as far as your mobility allows without pain or momentum-driven jerking.']::text[],'hip_flexors',ARRAY['abductors','adductors','tensor_fasciae_latae']::text[],'chair','mobility','beginner',ARRAY['mobility','warmup','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','50f6c403-a7eb-4c43-9723-c9c4ee7defc7','Lateral neck stretch (left)','lateral-neck-stretch-left','Starting position: Stand or sit upright with shoulders relaxed and spine neutral. Execution: Gently tilt your head to the left, bringing your left ear toward your left shoulder while keeping your right shoulder down.',ARRAY['Stand or sit with your back straight and shoulders relaxed','Place your left hand gently on the left side of your head above your ear','Slowly tilt your head to the left, bringing your left ear toward your left shoulder','Keep your right shoulder pressed down and avoid lifting it toward your ear','Hold the stretch for 15-30 seconds while breathing normally','Return to the starting position slowly and controlled']::text[],ARRAY['Never force the stretch or pull aggressively on your head with your hand','Keep the movement slow and controlled to avoid neck injury','Maintain proper posture by keeping your shoulders down and back straight','Stop immediately if you feel any sharp pain or discomfort','Focus on feeling a gentle stretch along the right side of your neck']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','dfbfc890-af85-4be4-a8c6-782f666f538d','Lateral neck stretch (right)','lateral-neck-stretch-right','Starting position: Stand or sit tall with shoulders relaxed and head in neutral position. Execution: Gently tilt your head to the right, bringing your right ear toward your right shoulder while keeping your left shoulder down.',ARRAY['Stand or sit with good posture, keeping your spine straight and shoulders relaxed','Place your right hand gently on the left side of your head above your ear','Slowly tilt your head to the right, using light pressure from your hand to deepen the stretch','Keep your left shoulder pressed down and avoid lifting it toward your ear','Hold the stretch for 15-30 seconds while breathing normally','Return to starting position slowly and repeat as needed']::text[],ARRAY['Never force the stretch or use excessive pressure with your hand','Keep the opposite shoulder down to maximize the stretch along the neck','Move slowly and smoothly to avoid sudden neck movements','Stop immediately if you experience any sharp pain or dizziness','Focus on feeling the stretch along the left side of your neck and upper trapezius']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','af2d3f82-2917-4e21-8df6-7acaf5f78ad5','Laying leg raises to windshield wipers','laying-leg-raises-to-windshield-wipers','Starting position: Lie flat on your back with arms extended out to your sides for stability, legs straight and together. Execution: Lift your legs to 90 degrees, then lower them side to side in a windshield wiper motion while keeping your upper back pressed to the floor.',ARRAY['Lie on your back with arms spread wide at shoulder height for support','Keep your legs straight and together, engaging your core muscles','Lift both legs straight up to a 90-degree angle with your torso','Slowly lower your legs to one side while keeping your shoulders pressed to the floor','Return legs to center position, then lower to the opposite side','Control the movement throughout the entire range of motion']::text[],ARRAY['Keep your shoulders and upper back firmly planted on the ground throughout the movement','Move slowly and controlled to maximize core engagement and prevent momentum','Stop the side-to-side motion before your lower back begins to arch off the floor','Bend your knees slightly if you experience lower back discomfort','Breathe steadily throughout the exercise, exhaling as you move your legs to each side']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3941270c-ad35-40bf-9906-e9c6d24ba777','Leg Extension','leg-extension','Starting position: Sit on a leg extension machine with knees bent and ankles secured under the pads. Execution: Extend your legs upward until fully straight, then lower slowly to the starting position.',ARRAY['Adjust the machine so the pivot point aligns with your knee joint and the ankle pad sits comfortably above your feet','Sit with your back flat against the backrest and grip the side handles for stability','Set your feet hip-width apart with toes pointing forward','Extend your legs in a smooth, controlled motion until knees are almost fully straight','Pause briefly at the top position while squeezing your quadriceps','Lower the weight slowly taking 2-3 seconds to return to starting position']::text[],ARRAY['Keep your core engaged and avoid arching your back during the movement','Don''t lock your knees completely at the top to prevent joint stress','Control the eccentric portion of the lift rather than letting the weight drop quickly','Start with lighter weight to master the form before progressing to heavier loads','Avoid using momentum or swinging your legs to lift the weight']::text[],'quads',ARRAY['hip_flexors','tibialis_anterior','core']::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','753a6d81-dbea-453c-8daf-c8b56f366409','Leg Extension','leg-extension-b8b2f9','Starting position: Sit on leg extension machine with back against pad and ankles behind lower pad. Execution: Extend legs upward by contracting quadriceps until knees are straight.',ARRAY['Adjust seat so knees align with machine''s pivot point','Position ankles securely behind the lower padding','Grip side handles and keep back pressed against pad','Slowly extend both legs until knees are straight','Lower weight with control back to starting position']::text[],ARRAY['Keep your back firmly pressed against the seat pad throughout the movement','Avoid locking knees aggressively at the top of the extension','Control the weight on both the lifting and lowering phases','Stop if you feel knee pain and adjust the seat position']::text[],'legs','{}'::text[],'machine',null,null,'{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','954de3a1-ff07-403b-9ad3-c172b2d90171','Leg Extensions','leg-extensions-d221cf','Starting position: Sit on leg extension machine with back against pad and ankles behind lower pads. Execution: Extend legs upward in controlled arc until knees are straight, then lower slowly.',ARRAY['Sit with back firmly pressed against backrest','Position ankles securely behind the lower pads','Grip side handles for stability','Extend both legs upward until knees straighten','Lower legs slowly to starting position','Repeat movement with controlled tempo']::text[],ARRAY['Keep your back pressed against the pad throughout the movement','Avoid locking knees aggressively at the top position','Control the weight during both lifting and lowering phases','Stop if you feel knee pain or discomfort','Adjust seat height so knees align with machine''s pivot point']::text[],'legs',ARRAY['hip_flexors','tensor_fasciae_latae']::text[],'machine','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bcd8c3d9-5c9b-4a97-8b30-0e85de2488ff','Leg Press','leg-press','Starting position: Sit on a horizontal leg press with feet positioned on the platform and knees bent. Execution: Push the platform forward by fully extending your legs, then slowly lower to the starting position.',ARRAY['Adjust the seat and backrest so your knees form a 90-degree angle when feet are placed on the footplate','Position feet shoulder-width apart in the middle of the footplate with toes pointing slightly outward','Grip the side handles for stability and keep your core engaged throughout the movement','Push through your heels to extend your legs, avoiding locking your knees completely at the top','Lower the weight slowly and under control until your knees return to the 90-degree starting position','Maintain steady breathing, exhaling during the push phase and inhaling during the lowering phase']::text[],ARRAY['Keep your knees aligned with your toes throughout the entire range of motion to prevent injury','Avoid placing your hands on your knees as this can interfere with proper movement mechanics','Never allow your lower back to round by letting your knees come too close to your chest','Focus on pushing through your heels rather than your toes to maximize quadriceps activation','Start with lighter weight to master the form before progressively increasing the load']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','844b8994-0c7a-477d-ab48-91b2d8ef75b0','Leg Press','leg-press-b91089','Starting position: Sit in leg press machine with back flat against pad and feet on platform. Execution: Lower weight by bending knees then press through heels to extend legs.',ARRAY['Position feet shoulder-width apart on platform','Lower the weight slowly until knees reach 90 degrees','Press through heels to extend legs back up','Control the weight throughout the entire movement','Keep core engaged and back pressed against pad']::text[],ARRAY['Keep knees aligned with toes throughout the movement','Avoid locking knees completely at the top position','Place feet in middle of platform for optimal leverage','Never hold your breath during the pressing motion']::text[],'legs',ARRAY['glute_max','hamstrings','adductors']::text[],'machine','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','68814908-0678-4931-af0e-0fced0d2022a','Leg Press Calf Raise','leg-press-calf-raise-31e0dc','Starting position: Sit on leg press machine with balls of feet on platform edge, knees extended. Execution: Push through toes to raise heels up, then lower controlled.',ARRAY['Position balls of feet on bottom edge of platform','Keep knees fully extended throughout the movement','Push through toes to raise heels as high as possible','Lower heels below platform level in controlled motion','Squeeze calves at the top of each repetition']::text[],ARRAY['Keep knees locked out to isolate the calf muscles effectively','Use full range of motion from deep stretch to peak contraction','Control the eccentric portion to maximize muscle activation','Position feet shoulder-width apart with toes pointing slightly outward']::text[],'legs',ARRAY['gastrocnemius','soleus','peroneals']::text[],'machine','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','952c06b0-359b-4e38-adfd-c352723ab865','Leg Press Calf Raise','leg-press-calf-raise','Starting position: Sit on a leg press machine with feet on the platform and knees slightly bent. Execution: Raise the heels upward by squeezing the calves, then slowly lower to starting position.',ARRAY['Adjust the leg press machine seat so your knees are at approximately 90 degrees when feet are positioned','Place only the balls of your feet on the bottom edge of the footplate with heels hanging freely','Keep your knees slightly bent and maintain this position throughout the movement','Press through the balls of your feet to raise your heels as high as possible','Hold the peak contraction briefly then slowly lower your heels below the footplate level','Maintain control throughout both the lifting and lowering phases']::text[],ARRAY['Keep your knees slightly bent throughout the entire movement to maintain tension on the calves','Focus on achieving a full range of motion by getting a deep stretch at the bottom and maximum contraction at the top','Use slow, controlled movements rather than bouncing to prevent injury and maximize muscle activation','Position your feet straight ahead rather than angled to ensure balanced calf development','Start with lighter weight to master the form before progressing to heavier loads']::text[],'calves','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bbc9368f-e232-4081-bd5c-235c928eccb3','Leg Press Close Stance','leg-press-close-stance','Starting position: Sit on a horizontal leg press with feet close together on the platform and knees bent. Execution: Push the platform forward by fully extending your legs, then slowly lower to the starting position.',ARRAY['Adjust the seat and back pad to ensure proper alignment with knees tracking over toes','Place feet close together on the footplate with toes pointing slightly outward','Grip the side handles firmly and maintain a neutral spine against the back pad','Release the safety handles and slowly lower the weight until knees reach approximately 90 degrees','Press through your heels to extend legs fully without locking knees completely','Re-engage safety handles before exiting the machine']::text[],ARRAY['Keep knees aligned with toes throughout the entire movement to prevent inward collapse','Maintain constant tension by not fully locking out knees at the top of the movement','Control the eccentric phase by lowering weight slowly rather than letting it drop','Focus on pressing through heels rather than toes to maximize quadriceps activation','Never allow knees to cave inward as this can cause injury and reduces exercise effectiveness']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','13351b5d-ef3f-4c6b-9f47-df62202d32b2','Leg Press Close Stance - Glute Focus','leg-press-close-stance-glute-focus','Starting position: Sit in a leg press machine with your feet together on the platform and knees bent. Execution: Push the platform forward by fully extending your legs while focusing the effort on your glutes, then slowly lower to the starting position.',ARRAY['Adjust the seat back to a comfortable angle and ensure your back is firmly pressed against the pad','Place your feet close together on the lower third of the footplate with toes pointing slightly outward','Release the safety handles and slowly lower the weight by bending at the knees and hips','Descend until your knees reach approximately 90 degrees or as deep as your mobility allows','Press through your heels and drive the weight back up while focusing on glute activation','Control the movement on both the lowering and pressing phases']::text[],ARRAY['Keep your feet positioned lower on the footplate to increase glute activation and reduce quad dominance','Maintain constant tension on your glutes throughout the entire range of motion','Avoid locking your knees completely at the top to keep continuous tension on the muscles','Focus on pressing through your heels rather than your toes to maximize glute engagement','Keep your core engaged and lower back pressed against the seat pad throughout the exercise']::text[],'glutes','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','639e71b2-5c79-4125-ad31-1c073b8b073f','Leg Press Medium Stance','leg-press-medium-stance','Starting position: Sit in a horizontal leg press with feet in a medium, shoulder-width position on the platform and knees bent. Execution: Push the platform forward by fully extending your legs, then slowly lower to the starting position.',ARRAY['Adjust the seat and back pad so your knees align with your chest when lowered','Place feet shoulder-width apart on the footplate with toes pointing slightly outward','Release the safety handles and slowly lower the weight until your knees reach 90 degrees','Press through your heels to return to starting position without locking knees completely','Keep your core engaged and back pressed firmly against the pad throughout the movement','Re-engage safety handles when completing your set']::text[],ARRAY['Keep your knees aligned with your toes to prevent inward collapse','Avoid placing hands on knees as this can cause injury if the weight shifts unexpectedly','Control the descent slowly rather than letting the weight drop quickly','Stop at 90 degrees knee bend to protect your lower back from excessive flexion','Breathe in during the lowering phase and exhale while pressing the weight up']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5894b913-11b8-47b6-8f0f-63b8ad0bd469','Leg Press Wide Stance','leg-press-wide-stance','Starting position: Sit in a leg press machine with feet positioned wider than shoulder width and knees bent. Execution: Push the platform forward by fully extending legs, then lower slowly to starting position.',ARRAY['Position yourself in the leg press machine with your back completely flat against the backrest','Place your feet on the platform wider than shoulder-width apart with toes pointing slightly outward','Release the safety handles and slowly lower the weight by bending your knees toward your chest','Stop when your knees reach approximately 90 degrees or when you feel a stretch in your glutes','Press through your heels to push the weight back up to the starting position','Maintain control throughout the entire range of motion and avoid locking your knees at the top']::text[],ARRAY['Keep your knees aligned with your toes throughout the movement to prevent inward collapse','Maintain constant tension on your quads by not fully locking out your knees at the top','The wide stance targets the inner portion of your quadriceps and engages your glutes more than a narrow stance','Keep your core engaged and back pressed firmly against the pad to maintain proper spinal alignment','Control the descent to maximize muscle engagement and prevent injury from dropping the weight too quickly']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a97548ad-e559-4380-a6b0-50cc210031b2','Leg raises','leg-raises','Starting position: Lie flat on your back with legs extended straight and arms at your sides for stability. Execution: Lift both legs together in a controlled motion until they form a 90-degree angle with your torso, then slowly lower them back down without touching the floor.',ARRAY['Lie flat on your back on a mat with your legs extended straight and arms placed at your sides or under your lower back for support','Keep your lower back pressed against the floor throughout the entire movement to protect your spine','Lift both legs together in a slow, controlled motion until they reach approximately 90 degrees with your torso','Pause briefly at the top position while maintaining tension in your core muscles','Slowly lower your legs back down in a controlled manner, stopping just before your heels touch the floor','Repeat the movement while maintaining proper form and breathing rhythm']::text[],ARRAY['Keep your lower back flat against the floor at all times to prevent strain and maintain proper core engagement','Control the descent phase of the movement as this provides the greatest challenge and benefit to your core muscles','If you experience lower back discomfort, bend your knees slightly or place your hands under your lower back for additional support','Focus on using your abdominal muscles rather than momentum to lift and lower your legs','Start with fewer repetitions and gradually increase as your core strength improves']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b7c0fca8-8f01-4c48-bea3-b691939e92bc','Lever Squat (Medium Stance)','lever-squat-medium-stance','Starting position: Position yourself on a lever squat machine with feet in a medium stance at shoulder width. Execution: Lower your body into a deep squat while keeping your back straight, then push upward to return to the starting position.',ARRAY['Position yourself on the machine with your back flat against the pad and shoulders securely under the shoulder pads','Place feet shoulder-width apart on the platform with toes slightly pointed outward','Release the safety handles and slowly lower yourself by bending at the knees and hips','Descend until your thighs are parallel to the platform or as low as your mobility allows','Drive through your heels and push the platform away to return to starting position','Re-engage safety handles when finished with your set']::text[],ARRAY['Keep your core engaged and back pressed against the pad throughout the entire movement','Ensure knees track in line with your toes and don''t cave inward during the movement','Control the descent and avoid bouncing at the bottom of the movement','Focus on driving through your heels rather than the balls of your feet during the ascent','Maintain steady breathing by inhaling on the way down and exhaling on the way up']::text[],'quads','{}'::text[],'machine',null,'beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2b82f2db-8edd-4904-af32-6fcf4c0d24d9','Lotus pose','lotus-pose',null,ARRAY['Sit on the floor with legs extended.','Bend one knee and place the foot on top of the opposite thigh.','Bend the other knee and place that foot on top of the first thigh.','Rest your hands on your knees and sit tall.']::text[],ARRAY['Only attempt if you have sufficient hip flexibility.','Never force the knees - this can cause injury.','Use Half Lotus as a modification if needed.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8f181782-a135-49c5-91df-de5985c69ac7','Low Cable Crossover','low-cable-crossover','Starting position: Stand facing low pulleys with handles adjusted to hip height. Execution: Cross the cables in front of your chest while maintaining a slight bend in your elbows, then return to the starting position.',ARRAY['Set cable pulleys to the lowest position and select appropriate weight','Stand in the center with one foot slightly forward for stability','Grasp handles with palms facing up and arms extended down at your sides','Pull cables up and inward in a smooth arc until hands meet at chest height','Squeeze chest muscles at the top of the movement','Lower cables slowly back to starting position with control']::text[],ARRAY['Keep a slight bend in your elbows throughout the entire movement to protect your joints','Focus on squeezing your chest muscles rather than using momentum','Maintain good posture with chest up and shoulders back','Control the weight on both the lifting and lowering phases','Start with lighter weight to master the movement pattern before progressing']::text[],'chest','{}'::text[],'cable','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cf8eef3a-8539-410a-9dac-da29caf914d6','Low Cable Curl V-Bar','low-cable-curl-v-bar','Starting position: Stand facing a low pulley with a V-bar attachment. Execution: Bend your elbows to lift the V-bar toward your shoulders, then lower in a controlled manner.',ARRAY['Attach the V-bar to the low pulley and select an appropriate weight','Stand with feet shoulder-width apart, maintaining a slight bend in your knees for stability','Grasp the V-bar with both hands using a neutral grip, keeping your wrists straight and strong','Keep your elbows pinned to your sides throughout the entire movement','Curl the weight up by contracting your biceps until your forearms are nearly vertical','Lower the weight slowly and under control, maintaining tension in the biceps throughout the descent']::text[],ARRAY['Keep your core engaged and avoid swaying or using momentum to lift the weight','Focus on squeezing your biceps at the top of the movement for maximum muscle activation','Maintain constant tension on the cable throughout the entire range of motion','Use a controlled tempo with a 2-second lift and 3-second lowering phase','Avoid letting your elbows drift forward or backward during the curl']::text[],'biceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','40811c61-7369-4803-afc0-fa7b90f90522','Low Cable Rope Curl','low-cable-rope-curl','Starting position: Stand facing a low cable pulley with a rope attachment. Execution: Flex elbows to bring the rope toward shoulders, separating the rope ends at the top of the movement.',ARRAY['Set the cable pulley to the lowest position and attach a rope handle','Stand 2-3 feet from the machine with feet hip-width apart for stable base','Grasp the rope with both hands using an underhand grip, palms facing up','Keep your core engaged and shoulders back throughout the movement','Curl the rope up by bending your elbows, stopping when your forearms are vertical','Lower the weight slowly and under control back to the starting position']::text[],ARRAY['Keep your upper arms pressed against your sides throughout the entire movement','Focus on squeezing your biceps at the top of the curl for maximum muscle activation','Use a slow and controlled tempo, especially during the lowering phase','Avoid swinging your body or using momentum to lift the weight','Maintain tension in the cable throughout the full range of motion']::text[],'biceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','412c612e-1822-4a22-aa3c-2461fd23a211','Low Cable Row','low-cable-row-a1e10c','Starting position: Kneel in a half-kneeling stance facing a low cable pulley, grasping the handle with both hands and arms extended forward. Maintain an upright torso with a neutral spine and engaged core. Execution: Pull the handle toward your torso by driving the elbows back and retracting the shoulder blades, then slowly return to the extended position under control.',ARRAY['Set the cable to a low position and attach a handle, then assume a half-kneeling stance facing the machine.','Grasp the handle with both hands and extend your arms fully forward while keeping your torso upright.','Pull the handle toward your midsection by driving your elbows back and squeezing your shoulder blades together.','Pause briefly at the contracted position, feeling the squeeze in your upper back.','Slowly extend your arms back to the starting position, controlling the resistance.','Repeat for the desired number of repetitions while maintaining a stable core.']::text[],ARRAY['Keep your torso upright and avoid leaning back to generate momentum.','Retract the shoulder blades fully to maximize back engagement.','Control both the pulling and returning phases of the movement.','Keep your core braced and spine neutral throughout the exercise.']::text[],'back',ARRAY['biceps','forearms','erector_spinae']::text[],'cable','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b0cc57d7-7d6b-48ad-a9bc-a3dc309ea72b','Low lunge (left)','low-lunge-left',null,ARRAY['From Downward Dog, step one foot forward between your hands.','Lower your back knee to the mat.','Stack your front knee over the ankle.','Raise your arms overhead or keep hands on the floor.']::text[],ARRAY['Pad your back knee with a blanket if needed.','Sink your hips forward and down for a deeper stretch.','Keep your core engaged and spine tall.']::text[],'quads','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','579695a3-b21a-4fe5-83fd-1bd47bfd2592','Low lunge (right)','low-lunge-right',null,ARRAY['From Downward Dog, step one foot forward between your hands.','Lower your back knee to the mat.','Stack your front knee over the ankle.','Raise your arms overhead or keep hands on the floor.']::text[],ARRAY['Pad your back knee with a blanket if needed.','Sink your hips forward and down for a deeper stretch.','Keep your core engaged and spine tall.']::text[],'quads','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','51f8b5e9-3c10-4727-820a-ba77857a46b2','Lunge matrix','lunge-matrix','Starting position: Stand tall with feet hip-width apart, hands on hips or at sides for balance. Execution: Perform lunges in multiple directions including forward, reverse, lateral, and diagonal movements to create a comprehensive movement pattern.',ARRAY['Stand with feet hip-width apart and engage your core muscles','Step forward into a lunge, lowering your hips until both knees are bent at 90 degrees','Return to starting position and immediately step backward into a reverse lunge','Step laterally to one side, sitting back into the hip while keeping the other leg straight','Perform diagonal lunges by stepping at 45-degree angles forward and backward','Complete the full sequence on one leg before switching to the other side']::text[],ARRAY['Keep your torso upright throughout all lunge variations to maintain proper spine alignment','Ensure your front knee tracks over your ankle and doesn''t collapse inward during any movement','Land softly on the balls of your feet when stepping to reduce impact on joints','Maintain control during transitions between different lunge directions rather than rushing through the movements','Keep most of your weight on your front leg during forward and diagonal lunges for maximum quad activation']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e6286746-6da7-492e-9dc2-0688edeff3a9','Lunge With Spinal Twist','lunge-with-spinal-twist','Starting position: Stand tall with feet hip-width apart, hands clasped together at chest level. Execution: Step one foot forward into a lunge position while simultaneously rotating your torso toward the front leg, then return to starting position and repeat on the opposite side.',ARRAY['Step forward with your right foot into a deep lunge, ensuring your front knee tracks over your ankle','Lower your body until both knees are bent at approximately 90 degrees','Keep your torso upright and rotate your upper body toward your front leg while keeping your hips square','Hold the twisted position briefly, then rotate back to center','Push through your front heel to return to starting position','Repeat the movement stepping forward with your left foot and twisting in the opposite direction']::text[],ARRAY['Keep your front knee aligned over your ankle to prevent knee strain','Maintain an upright torso throughout the movement and avoid leaning forward','Rotate from your core and mid-spine rather than forcing the twist from your lower back','Ensure your back knee points toward the ground and doesn''t cave inward','Control the descent and ascent phases of the lunge to maximize quad engagement']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bcfe96da-42de-445b-85bc-44afa2789f77','Lunges','lunges','',ARRAY['Set bar at shoulder height','Position bar on upper back','Step one foot forward, one back','Unrack and lower into lunge','Front thigh parallel, then push up','Complete reps, switch legs']::text[],ARRAY['Keep torso upright','Front knee tracks over toes','Don''t let back knee slam floor','Control the descent','Good for beginners learning lunge pattern']::text[],'full_body','{}'::text[],'bodyweight','full body',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4eed07c2-fe85-409d-9f81-a4872e8ffb9e','Lunges (Left)','lunges-left','Starting position: Stand tall with feet hip-width apart, hands on hips or at your sides. Execution: Step your left foot forward into a lunge position, lowering your body until both knees are bent at 90-degree angles, then push back to the starting position.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Step your left foot forward approximately 2-3 feet, keeping your torso upright','Lower your body by bending both knees until your left thigh is parallel to the floor and right knee nearly touches the ground','Ensure your left knee tracks directly over your ankle, not extending past your toes','Push through your left heel to return to the starting position','Complete all repetitions on the left leg before switching sides']::text[],ARRAY['Keep most of your weight on your front heel rather than your toes','Maintain an upright torso throughout the movement to avoid leaning forward','Your back knee should drop straight down toward the floor, not drift inward or outward','Control the descent and avoid bouncing at the bottom of the movement','If you feel unstable, practice the movement holding onto a wall or chair for support']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','de1d910d-89b5-4f79-9459-6fefa1dbf525','Lunges (Right)','lunges-right','Starting position: Stand tall with feet hip-width apart, hands on hips or at your sides. Execution: Step your right foot forward into a lunge position, lowering your body until both knees are bent at 90 degrees, then push through your right heel to return to the starting position.',ARRAY['Stand with feet hip-width apart and engage your core muscles','Step your right foot forward about 2-3 feet, keeping your torso upright','Lower your body by bending both knees until your right thigh is parallel to the floor','Ensure your right knee stays directly above your ankle, not extending past your toes','Push through your right heel to return to the starting position','Complete all repetitions on the right leg before switching sides']::text[],ARRAY['Keep most of your weight on your front heel rather than your toes','Maintain an upright torso throughout the movement to avoid leaning forward','Your back knee should nearly touch the ground but not rest on it','Step far enough forward so your front shin remains vertical at the bottom position','Keep your core engaged to maintain balance and protect your lower back']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5aea090d-1bca-427b-8960-c01f7a6f0211','Lunges body weight','lunges-body-weight','Starting position: Stand tall with feet hip-width apart, hands on hips or at your sides for balance. Execution: Step one foot forward into a lunge position, lowering your body until both knees are bent at approximately 90 degrees, then push through the front heel to return to starting position.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Take a large step forward with one leg, keeping your torso upright','Lower your body by bending both knees until your front thigh is parallel to the floor and back knee nearly touches the ground','Keep your front knee aligned over your ankle, not pushing forward past your toes','Push through your front heel to return to the starting position','Complete all repetitions on one leg before switching to the other leg']::text[],ARRAY['Maintain an upright torso throughout the movement to avoid leaning forward','Keep most of your weight on your front leg and use your back leg primarily for balance','Control the descent slowly rather than dropping down quickly to maximize muscle engagement','Ensure your front knee tracks in line with your toes to prevent knee strain','Step far enough forward so your front shin remains vertical when in the bottom position']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','497b7319-b2dc-4886-8ced-fdf14a08bb97','Lying Barbell Front Raise','lying-barbell-front-raise','Starting position: Sit on an inclined bench with your back supported, holding a barbell with both hands using an overhand grip, arms extended upward above your chest. Execution: Lower the barbell in a controlled arc toward your upper chest, then press it back up to the starting position while maintaining the inclined angle.',ARRAY['Sit securely on an inclined bench with your back firmly pressed against the pad for support','Grip the barbell with both hands using an overhand grip, hands positioned slightly wider than shoulder-width','Start with arms extended upward above your chest, maintaining a slight bend in your elbows','Lower the barbell slowly in a controlled arc motion toward your upper chest area','Press the barbell back up to the starting position following the same arc path','Maintain control throughout the entire range of motion, avoiding any bouncing or jerky movements']::text[],ARRAY['Keep your core engaged and back pressed firmly against the bench throughout the movement','Maintain a controlled tempo on both the lowering and lifting phases to maximize muscle engagement','Avoid locking out your elbows completely at the top to maintain constant tension on the muscles','Choose an appropriate weight that allows you to maintain proper form throughout all repetitions','Keep your feet planted firmly on the ground for additional stability during the exercise']::text[],'shoulders','{}'::text[],'barbell','shoulders','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','babede27-efe6-473b-85a8-6ef01ce3fab7','Lying Barbell Skull Crusher','lying-barbell-skull-crusher','Starting position: Lie on a flat bench with a barbell in your hands, arms extended upward with palms facing forward. Execution: Lower the bar toward your forehead by bending your elbows, then extend your arms to return to the starting position.',ARRAY['Lie flat on a bench with feet firmly planted on the floor for stability','Grip the barbell with hands about shoulder-width apart using an overhand grip','Start with arms fully extended above your chest, keeping your shoulders stable','Lower the weight slowly by bending only at the elbows until the bar approaches your forehead','Keep your upper arms stationary throughout the entire movement','Press the weight back up by extending your elbows to return to starting position']::text[],ARRAY['Keep your upper arms perpendicular to the floor and avoid letting them drift backward','Use a controlled tempo, especially on the lowering phase, to maintain muscle tension','Start with lighter weight to master the form before progressing to heavier loads','Keep your core engaged and maintain natural arch in your lower back','Stop the descent when you feel a good stretch in your triceps, typically when the bar is near your forehead']::text[],'triceps','{}'::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cfa05b32-b753-4e84-a73f-1c2a92606930','Lying Dumbbell Skull Crusher','lying-dumbbell-skull-crusher','Starting position: Lie on a flat bench with a dumbbell in each hand, arms extended upward with palms facing each other. Execution: Lower the dumbbells toward your forehead by bending your elbows, then extend your arms to return to starting position.

Note: can also be performed with one dummbell.',ARRAY['Lie flat on a bench with feet planted firmly on the floor and maintain a neutral spine throughout the movement','Grip both dumbbells.','Start with arms fully extended directly over your chest, keeping your upper arms stationary throughout the exercise','Lower the dumbbell slowly by bending only at the elbows until the weight nearly touches your forehead','Press the dumbbell back up to the starting position by extending your elbows while keeping your upper arms vertical','Control the weight on both the lowering and lifting phases to maintain proper form']::text[],ARRAY['Keep your upper arms completely stationary and perpendicular to the floor - only your forearms should move','Lower the weight slowly and under control to avoid hitting yourself in the face','Use a secure grip with both hands on the same end of the dumbbell to prevent it from slipping','Keep your core engaged and avoid arching your back excessively during the movement','Start with lighter weight to master the form before progressing to heavier loads']::text[],'triceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ff106b50-02bd-4962-b9f0-ddbe247b8b3e','Lying Dumbbell Tricep Extension','lying-dumbbell-tricep-extension',null,ARRAY['Stand or sit, hold one dumbbell with both hands','Raise overhead, arms extended','Lower behind head by bending elbows','Keep upper arms vertical','Extend back to start']::text[],ARRAY['Keep elbows close to head','Don''t flare elbows','Full stretch at bottom','Full lockout at top','Targets long head of triceps']::text[],'triceps','{}'::text[],'dumbbell','arms - triceps',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a1b684f7-6cf3-41a7-9c1f-2321a8e0847a','Lying Dumbbell Tricep Extension - One arm','lying-dumbbell-tricep-extension-one-arm','Starting position: Lie flat on a bench holding a dumbbell in one hand with your arm extended straight up above your shoulder, palm facing inward. Execution: Lower the dumbbell by bending only at the elbow until your forearm is parallel to the floor, then extend back to the starting position.',ARRAY['Lie flat on a bench with your feet planted firmly on the floor','Hold a dumbbell in one hand and extend your arm straight up above your shoulder','Keep your upper arm stationary and slowly lower the weight by bending only at the elbow','Lower until your forearm is parallel to the floor or you feel a stretch in your tricep','Press the weight back up to the starting position by straightening your elbow','Complete all repetitions on one arm before switching to the other side']::text[],ARRAY['Keep your upper arm completely still throughout the movement to isolate the tricep','Use your free hand to support and stabilize your working arm if needed','Control the weight on both the lowering and lifting phases to maximize muscle engagement','Start with lighter weight than you would use for both arms to ensure proper form','Stop the movement if you feel any elbow pain or discomfort']::text[],'triceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3e840d86-0fd5-4ac2-b152-2bcc8ecc67c3','Lying elbow to knee crunch','lying-elbow-to-knee-crunch','Starting position: Lie on your back with hands behind your head, knees bent at 90 degrees with feet lifted off the floor. Execution: Simultaneously crunch up while bringing one elbow toward the opposite knee, then alternate sides in a controlled manner.',ARRAY['Lie flat on your back with your lower back pressed into the floor','Place your hands lightly behind your head without interlocking fingers','Lift your feet off the ground with knees bent at 90 degrees','Contract your core and lift your shoulder blades off the floor while bringing your right elbow toward your left knee','Return to starting position and repeat on the opposite side, bringing left elbow toward right knee','Continue alternating sides while maintaining controlled movement throughout']::text[],ARRAY['Keep your lower back pressed against the floor throughout the entire movement','Avoid pulling on your neck with your hands - let your core muscles do the work','Focus on bringing your elbow toward your knee rather than your knee toward your elbow','Maintain steady breathing and avoid holding your breath during the exercise','Keep your core engaged even when returning to the starting position between reps']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fd2a8e1f-3efb-4e11-89fb-a479b7bf4a06','Lying EZ Bar Curl','lying-ez-bar-curl','Starting position: Lie on a flat bench with an EZ bar in your hands, arms extended upward. Execution: Flex your elbows to bring the bar toward your forehead, then extend your arms to return to the starting position.',ARRAY['Lie flat on a bench with feet planted firmly on the floor for stability','Grip the EZ bar with an underhand grip, hands positioned on the angled portions of the bar','Extend arms overhead with the bar positioned above your chest, maintaining a slight bend in your elbows','Slowly curl the bar toward your forehead by bending at the elbows while keeping upper arms still','Squeeze your biceps at the top of the movement, then slowly lower the bar back to starting position','Maintain control throughout the entire range of motion without using momentum']::text[],ARRAY['Keep your upper arms stationary throughout the movement to isolate the biceps effectively','Use the angled grips of the EZ bar to reduce wrist strain compared to a straight barbell','Control the eccentric lowering phase for maximum muscle activation and safety','Avoid lowering the bar too far past your head to prevent shoulder strain','Start with lighter weight to master the form before progressing to heavier loads']::text[],'biceps','{}'::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','49ec0843-8680-48cd-bdf2-e871d435b583','Lying knee tucks','lying-knee-tucks','Starting position: Lie flat on your back with arms extended alongside your body for support and legs straight out. Execution: Simultaneously lift your knees toward your chest while raising your upper body to meet them, then lower back to starting position with control.',ARRAY['Lie flat on your back on a mat with arms at your sides and legs extended straight','Keep your core engaged and press your lower back into the floor','Simultaneously lift your knees toward your chest while crunching your upper body forward','Squeeze your abdominals at the top when knees meet chest','Lower your upper body and legs back to starting position with slow, controlled movement','Maintain constant tension in your core throughout the entire range of motion']::text[],ARRAY['Keep movements slow and controlled to maximize muscle engagement and prevent momentum','Focus on exhaling as you crunch up and inhaling as you lower down','Avoid pulling on your neck or using your arms to generate momentum','Keep your lower back pressed against the floor throughout the exercise to protect your spine','Start with shorter ranges of motion if you''re a beginner and gradually increase as strength improves']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','23b96196-f154-4450-a2cd-fdc35af2e60c','Lying Leg Curl','lying-leg-curl','Starting position: Lie face down on a leg curl machine with your ankles secured under the pads. Execution: Bend your knees to bring the pads toward your glutes, then slowly lower to starting position.',ARRAY['Adjust the machine so the pad sits comfortably above your ankles and your knees align with the pivot point','Lie face down on the bench with your hips pressed firmly against the pad and grip the side handles','Keep your core engaged and maintain a neutral spine throughout the movement','Curl your heels toward your glutes in a smooth, controlled motion while exhaling','Squeeze your hamstrings at the top of the movement for a brief pause','Lower the weight slowly back to starting position while inhaling, maintaining tension in your hamstrings']::text[],ARRAY['Avoid using momentum or swinging the weight - focus on slow, controlled movements','Keep your hips pressed down against the bench to prevent lower back compensation','Don''t allow your knees to lift off the pad during the exercise','Control the eccentric (lowering) portion of the movement to maximize muscle activation','Stop just short of full knee extension to maintain constant tension on the hamstrings']::text[],'hamstrings',ARRAY['gastrocnemius','glutes','calves']::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','73f9f38e-cd72-4e0c-995a-e7698aab8408','Lying leg raises with crunch','lying-leg-raises-with-crunch','Starting position: Lie flat on your back with arms at your sides or hands behind your head, legs extended straight out. Execution: Simultaneously lift your legs up to 90 degrees while crunching your upper body forward, then lower both back to starting position with control.',ARRAY['Lie flat on your back on a mat with your legs extended straight and arms either at your sides for support or lightly behind your head','Keep your lower back pressed against the floor throughout the entire movement to protect your spine','Simultaneously lift your straight legs up toward the ceiling while crunching your shoulders and upper back off the ground','Squeeze your core at the top when your legs reach about 90 degrees and your shoulder blades are lifted off the floor','Slowly lower both your legs and upper body back to the starting position with complete control','Maintain constant tension in your core muscles and avoid using momentum to swing your legs up']::text[],ARRAY['Keep your lower back pressed firmly against the floor to prevent hyperextension and potential injury','Focus on using your core muscles rather than hip flexors by initiating the leg raise from your lower abdominals','Avoid pulling on your neck if hands are behind your head - let your core do the work for the crunch portion','Control the descent phase as much as the lifting phase to maximize muscle engagement and prevent strain','If too challenging, bend your knees slightly or perform leg raises and crunches separately until you build sufficient core strength']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b2a0896a-3900-4a82-bd7d-30e4b74687e9','Lying oblique crunch','lying-oblique-crunch','Starting position: Lie on your side with your bottom arm extended for support and your top hand placed behind your head. Execution: Contract your obliques to bring your top elbow toward your hip while simultaneously lifting your legs slightly off the ground.',ARRAY['Lie on your side with your legs stacked and slightly bent at the knees','Place your bottom arm straight out in front for stability and support','Position your top hand gently behind your head without interlacing fingers','Engage your core and slowly crunch your top elbow down toward your hip','Simultaneously lift your top leg slightly while contracting your obliques','Lower back to starting position with control and repeat before switching sides']::text[],ARRAY['Keep your neck in neutral alignment and avoid pulling on your head with your hand','Focus on slow, controlled movements rather than speed or momentum','Breathe out during the crunch phase and inhale as you return to starting position','Maintain stability through your bottom arm and avoid rolling forward or backward','Feel the contraction specifically in your side muscles rather than your hip flexors']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','48700743-f688-42d8-99ed-8c1b223d1f55','Lying Overhead Triceps Extension','lying-overhead-triceps-extension','Starting position: Lie on a flat bench with a bar or dumbbell in hands, arms extended upward. Execution: Lower the weight behind head by bending elbows, then extend arms to return to starting position.',ARRAY['Lie flat on a bench and grip the barbell with hands shoulder-width apart using an overhand grip','Start with arms fully extended above your chest, keeping your core engaged and feet flat on the floor','Slowly lower the barbell by bending at the elbows only, keeping your upper arms stationary and perpendicular to the floor','Lower the weight until you feel a stretch in your triceps, typically when the barbell is just behind your head','Press the weight back up by extending your elbows, focusing on using only your triceps to lift the barbell','Return to the starting position with arms fully extended, maintaining control throughout the entire movement']::text[],ARRAY['Keep your upper arms stationary throughout the movement to isolate the triceps effectively','Use a controlled tempo and avoid letting the weight drop quickly to prevent elbow injury','Start with lighter weight to master the form before progressing to heavier loads','Maintain a firm grip on the barbell and avoid letting your elbows flare out excessively']::text[],'triceps','{}'::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5e98b09d-e4aa-4ddb-aadf-02e18b6c16ac','Lying toe reaches','lying-toe-reaches','Starting position: Lie flat on your back with arms extended overhead and legs straight, creating a long line from fingertips to toes. Execution: Simultaneously lift your torso and legs, reaching your hands toward your toes while keeping your core engaged, then slowly return to the starting position.',ARRAY['Lie flat on your back on a mat with arms extended overhead and legs straight','Keep your lower back pressed gently against the floor before beginning the movement','Simultaneously lift your shoulders and legs off the ground while reaching your hands toward your toes','Focus on using your core muscles to initiate the movement rather than momentum','Hold the top position briefly when your hands are closest to your toes','Slowly lower both your torso and legs back to the starting position with control']::text[],ARRAY['Keep your neck in a neutral position and avoid straining it forward during the reach','Move slowly and controlled to maximize core engagement and prevent injury','If you cannot reach your toes, reach as far as comfortable while maintaining proper form','Breathe out during the lifting phase and breathe in as you lower back down','Stop immediately if you feel any lower back pain and consider modifying the range of motion']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2dbfdf97-301b-423d-a27c-7485137e50f4','Machine Bicep Curl','machine-bicep-curl','Starting position: Sit on a bicep curl machine with your arms resting on the pads and hands gripping the handles. Execution: Flex your elbows to lift the weight toward your shoulders, then lower slowly.',ARRAY['Adjust the seat height so your arms are parallel to the floor when extended','Grip the handles with palms facing up, hands shoulder-width apart','Keep your back pressed firmly against the pad throughout the movement','Curl the weight up smoothly without using momentum or swinging','Squeeze your biceps at the top of the movement for one second','Lower the weight slowly taking 2-3 seconds to return to starting position']::text[],ARRAY['Keep your wrists straight and avoid bending them during the curl','Don''t let your elbows flare out to the sides - keep them stationary','Focus on controlled movement rather than heavy weight to prevent injury','Avoid fully locking out your elbows at the bottom to maintain tension on the biceps','Breathe out during the lifting phase and breathe in during the lowering phase']::text[],'biceps','{}'::text[],'machine','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bf22d9ad-1aac-47e5-8e6f-f6072b868a6d','Machine Chest Fly','machine-chest-fly','Starting position: Adjust the machine to chest height and sit with your back straight. Execution: Bring the handles or levers forward until they touch, then slowly return to the starting position.',ARRAY['Adjust the seat height so your upper arms are parallel to the floor when grasping the handles','Sit with your back firmly pressed against the pad and plant both feet flat on the floor','Select an appropriate weight that allows you to maintain proper form throughout the entire range of motion','Grasp the handles with a neutral grip and keep a slight bend in your elbows throughout the movement','Bring your arms together in front of your chest by squeezing your pectoral muscles, avoiding momentum','Slowly return to the starting position by controlling the weight back to the initial stretch position']::text[],ARRAY['Keep your shoulders back and down against the pad to prevent shoulder impingement','Maintain a slight bend in your elbows throughout the entire movement to protect your shoulder joints','Focus on squeezing your chest muscles rather than just moving the weight from point A to point B','Control the negative portion of the movement just as much as the positive to maximize muscle engagement','Avoid letting the weight stack touch between repetitions to maintain constant tension on the chest muscles']::text[],'chest','{}'::text[],'machine','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ae4a7149-9cfb-481e-bece-49ec526c8487','Machine Glute Kickback Both Legs','machine-glute-kickback-both-legs','Starting position: Sit on the glute kickback machine with your torso leaning forward against the chest pad, gripping the handles for stability, with your legs positioned behind you against the leg pads. Execution: Push both legs back simultaneously in a controlled kicking motion, squeezing your glutes at the peak of the movement before slowly returning to the starting position.',ARRAY['Position yourself on the machine with your chest against the pad and grip the handles firmly','Place both legs against the leg pads with your knees slightly bent','Lean your torso forward and maintain a stable core throughout the movement','Push both legs back simultaneously using your glutes, not your lower back','Squeeze your glutes at the top of the movement and hold briefly','Slowly return your legs to the starting position with control']::text[],ARRAY['Keep your core engaged to prevent excessive arching of the lower back','Focus on using your glute muscles rather than momentum to power the movement','Maintain a controlled tempo on both the pushing and returning phases','Keep your chest pressed against the pad for stability and proper form','Avoid using your lower back to initiate the movement']::text[],'glutes','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7c8e22b4-159b-4f19-8100-e05428bf1b1f','Machine Glute Kickback Single Leg','machine-glute-kickback-single-leg','Starting position: Position yourself in a glute kickback machine with one foot secured on the platform. Execution: Push your leg backward squeezing your glutes, then slowly return to the starting position. Repeat with the other leg.',ARRAY['Adjust the machine height so the footplate aligns with your ankle when standing upright','Position your non-working leg firmly on the ground with a slight bend in the knee for stability','Grip the handles with both hands and lean your torso slightly forward to maintain balance','Place your working foot securely on the footplate with your knee slightly bent','Drive your leg back in a smooth arc motion, focusing on squeezing your glute at the peak contraction','Lower your leg back to the starting position with control, maintaining tension throughout the movement']::text[],ARRAY['Keep your core engaged throughout the entire movement to prevent lower back compensation','Avoid using momentum or swinging your leg - focus on controlled muscle contraction','Maintain a neutral spine position and avoid excessive arching of the lower back','Start with lighter weight to master the movement pattern before progressing to heavier loads','Ensure equal repetitions on both legs to maintain muscular balance']::text[],'glutes','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3ffba4ed-c3ae-4727-b5dc-31823f5d3358','Machine Lateral Raise','machine-lateral-raise','Starting position: Sit on a lateral raise machine with your arms at your sides and hands gripping the handles. Execution: Raise your arms out to the sides until they reach shoulder height, then lower slowly.',ARRAY['Adjust the seat height so your upper arms are parallel to the floor when holding the handles','Position your back firmly against the backrest and engage your core','Grasp the handles or position your arms under the padded levers with a neutral grip','Lift your arms out to the sides in a smooth arc until they reach shoulder height','Pause briefly at the top of the movement','Lower the weight slowly and under control back to the starting position']::text[],ARRAY['Keep your torso upright and avoid leaning forward or backward during the movement','Stop at shoulder height to prevent impingement and protect the shoulder joint','Use a controlled tempo with a 2-second lift and 3-second lowering phase','Avoid using momentum or swinging the weight up','Start with lighter weight to master proper form before increasing resistance']::text[],'shoulders','{}'::text[],'machine','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','23781248-d4d6-418e-a5a0-932abb0ca32b','Machine Reverse Fly','machine-reverse-fly','Starting position: Sit at a reverse fly machine with arms at your sides and hands gripping the handles. Execution: Raise your arms back until they reach shoulder height, then lower slowly.',ARRAY['Adjust the seat height so your arms are parallel to the floor when grasping the handles','Set your chest firmly against the pad and maintain good posture throughout the movement','Select an appropriate weight that allows you to complete the full range of motion with proper form','Grip the handles with a neutral wrist position and keep a slight bend in your elbows','Pull your arms back in a smooth arc until you feel a strong contraction in your rear delts','Lower the weight slowly and under control, taking twice as long as the pulling phase']::text[],ARRAY['Keep your chest pressed against the pad throughout the entire movement to maintain stability and proper alignment','Focus on initiating the movement from your rear deltoids rather than using your arms or back muscles','Avoid using momentum or bouncing at the bottom of the movement to prevent injury','Maintain a slight bend in your elbows throughout the exercise to protect your joints','Squeeze your shoulder blades together at the peak contraction for maximum muscle activation']::text[],'shoulders','{}'::text[],'machine','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d93f6d37-76e1-4cdc-a39e-d39beabf97d5','Machine Shoulder Press','machine-shoulder-press','Starting position: Sit on a shoulder press machine, adjusting the seat height so the handles are at shoulder level. Execution: Push the handles upward until arms are fully extended, then slowly return to starting position.',ARRAY['Adjust the seat height so the handles align with your shoulders when seated','Sit with your back flat against the pad and engage your core muscles','Grasp the handles with a firm grip, keeping your wrists straight and neutral','Press the weight up in a straight line overhead without arching your back excessively','Lower the weight slowly and under control until your upper arms are parallel to the floor','Maintain steady breathing throughout the movement, exhaling on the press up']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Avoid pressing the weight behind your head or lowering too far below shoulder level','Use a full range of motion but stop when your upper arms reach parallel to prevent shoulder impingement','Focus on pressing straight up rather than forward to maximize shoulder muscle activation','Start with lighter weight to master proper form before progressing to heavier loads']::text[],'shoulders','{}'::text[],'machine','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6f402009-67c2-484f-bc92-6090cc9a7ed4','Machine Shoulder Press Neutral Grip','machine-shoulder-press-neutral-grip','Starting position: Sit in a shoulder press machine with a neutral grip (palms facing each other), adjusting the seat height so handles are at shoulder level. Execution: Push the handles upward until arms are fully extended, then slowly return to the starting position.',ARRAY['Adjust the seat height so the handles align with your shoulders when seated','Position your back flat against the backrest and engage your core muscles','Grasp the handles with a neutral grip, keeping your wrists straight and aligned','Press the weight up in a smooth, controlled motion without locking out your elbows completely','Lower the weight slowly back to shoulder level, maintaining control throughout the descent','Keep your feet firmly planted on the ground throughout the entire movement']::text[],ARRAY['Avoid pressing the weight behind your head as this can strain the shoulder joint','Keep your core engaged throughout the movement to maintain proper spinal alignment','Use a full range of motion but stop at shoulder level on the descent to prevent overstretching','Breathe out during the pressing phase and breathe in during the lowering phase','Start with lighter weight to master the form before progressing to heavier loads']::text[],'shoulders','{}'::text[],'machine','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','26f5654e-6c1f-4418-b336-0317edc13415','Medicine Ball Reverse Crunch','medicine-ball-reverse-crunch-03536c','Starting position: Lie supine on a mat with legs extended vertically toward the ceiling, holding a medicine ball between your hands overhead reaching up toward your feet. Execution: Contract the lower abdominals to curl the hips and pelvis off the mat, lifting the legs and hips upward while keeping the ball reaching toward the toes, then lower with control back to the start.',ARRAY['Lie flat on your back with legs raised straight up and hold the medicine ball with both hands reaching toward your feet.','Brace your core and press your lower back into the mat.','Exhale and curl your pelvis upward, lifting your hips off the mat toward the ceiling.','Reach the ball toward your toes as your hips elevate at the top of the movement.','Inhale and lower your hips slowly back to the starting position under control.','Repeat for the prescribed number of repetitions without swinging.']::text[],ARRAY['Initiate the movement from the abdominals, not by kicking the legs.','Keep the motion slow and controlled to avoid momentum.','Maintain a neutral neck and relaxed shoulders throughout.','Exhale fully as you lift the hips to maximize core engagement.']::text[],'lower_abs',ARRAY['hip_flexors','obliques','transverse_abdominis']::text[],'stability ball','core','intermediate',ARRAY['core','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','94e2b3e2-d8e5-4f3b-8b77-5368023e25eb','Mid Row Machine','mid-row-machine','Starting position: Sit on a rowing machine with a medium grip, adjusting seat height so handles are at abdomen level. Execution: Pull the handles toward the abdomen while maintaining an upright torso, then slowly return to starting position.',ARRAY['Adjust the seat height so your arms are parallel to the floor when gripping the handles','Position your chest firmly against the pad and maintain an upright posture throughout the movement','Grip the handles with a neutral grip, keeping your wrists straight and aligned','Pull the handles back by driving your elbows behind your body and squeezing your shoulder blades together','Hold the contracted position briefly, then slowly return to the starting position','Maintain tension in your core and avoid using momentum or swinging motions']::text[],ARRAY['Keep your shoulders down and back throughout the entire movement to avoid shoulder impingement','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Avoid letting the weight stack touch between repetitions to maintain constant tension on the target muscles','Keep your chest pressed against the pad to prevent your torso from moving and ensure proper form','Control both the pulling and lowering phases of the movement for maximum muscle activation']::text[],'back','{}'::text[],'machine','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7ade83ba-d8c1-4947-aab0-8a15506c70e5','Mountain climber cross body tuck','mountain-climber-cross-body-tuck','Starting position: Begin in a high plank position with hands directly under shoulders, body in a straight line from head to heels. Execution: Alternate bringing each knee across your body toward the opposite elbow while maintaining the plank position, creating a twisting motion through the core.',ARRAY['Start in a high plank position with hands flat on the ground directly under your shoulders','Keep your core engaged and maintain a straight line from head to heels throughout the movement','Bring your right knee across your body toward your left elbow, then return to plank position','Immediately bring your left knee across your body toward your right elbow, then return to plank position','Continue alternating sides in a controlled, rhythmic motion','Maintain steady breathing throughout the exercise']::text[],ARRAY['Keep your hips level and avoid rotating them excessively during the cross-body movement','Maintain strong wrist and shoulder stability by pressing firmly through your palms','Focus on controlled movement rather than speed to maximize core engagement','Avoid letting your hips pike up or sag down during the exercise','Stop if you feel strain in your lower back and reassess your form']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['cardio','core','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4dd34460-26de-41b4-ba9f-66bcf4ed8e63','Mountain Climbers','mountain-climbers-6fb7f3','Starting position: Begin in a high plank position with hands under shoulders and body in straight line. Execution: Alternately drive knees toward chest in running motion while maintaining plank position.',ARRAY['Start in high plank with straight body alignment','Drive right knee toward chest explosively','Return right foot to starting position','Drive left knee toward chest explosively','Continue alternating legs in rapid succession','Maintain steady breathing throughout the movement']::text[],ARRAY['Keep hips level and avoid bouncing up and down','Maintain tight core to prevent lower back sagging','Land softly on balls of feet to reduce joint impact','Keep hands firmly planted and shoulders stable over wrists']::text[],'bodyweight',ARRAY['obliques','front_deltoids','triceps','calves']::text[],'bodyweight','cardio','beginner','{}'::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
