insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','be5fae80-4b05-4196-8f3f-61d2c106ab32','Mountain pose','mountain-pose',null,ARRAY['Stand with feet together or hip-width apart.','Distribute your weight evenly across both feet.','Engage your thighs, tuck your tailbone slightly, and lift your chest.','Let your arms hang naturally with palms facing forward.']::text[],ARRAY['Stand tall through the crown of your head.','Relax your shoulders away from your ears.','This is the foundation for all standing poses.']::text[],'full_body','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1b83ce89-e537-4d37-be07-af8b5c192edd','My Side Bend Stretch (L)','my-side-bend-stretch-l','Starting position: Stand with feet hip-width apart, left hand on hip, and right arm extended overhead. Execution: Slowly lean your torso to the left side while reaching your right arm over your head, creating a gentle stretch along the right side of your body.',ARRAY['Stand tall with feet hip-width apart and engage your core muscles','Place your left hand on your left hip for support and stability','Extend your right arm straight up overhead, reaching toward the ceiling','Slowly lean your entire torso to the left while reaching your right arm over your head','Hold the stretch for 15-30 seconds while breathing deeply','Return to starting position slowly and controlled']::text[],ARRAY['Keep both feet planted firmly on the ground throughout the movement','Avoid leaning forward or backward - maintain the side bend in the frontal plane only','Focus on lengthening through the spine rather than compressing downward','Breathe steadily and avoid holding your breath during the stretch','Stop immediately if you feel any sharp pain or discomfort']::text[],'core','{}'::text[],'bodyweight','core','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','697e0018-b1bd-4035-9ced-5a446cd66caa','narrow squats chair','narrow-squats-chair-fae991','Starting position: Sit on the front edge of a sturdy chair with feet positioned close together (narrow stance), flat on the floor, torso leaning slightly forward and hands clasped in front of the chest. Execution: Press through the feet to stand up fully, extending the hips and knees, then slowly lower back down to lightly touch the chair before repeating.',ARRAY['Sit on the edge of the chair with your feet close together and flat on the floor.','Lean your torso slightly forward and clasp your hands in front of your chest.','Drive through your feet and extend your hips and knees to stand up tall.','Slowly bend at the hips and knees to lower back down under control.','Lightly touch the chair seat and immediately press back up to repeat.']::text[],ARRAY['Keep your knees tracking in line with your toes throughout the movement.','Maintain a neutral, upright spine and avoid rounding your lower back.','Control the descent rather than dropping onto the chair.','Push through your whole foot, emphasizing your heels, to engage the glutes.']::text[],'quads',ARRAY['hamstrings','core','calves']::text[],'chair','strength','beginner',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3bb357f4-d722-42e5-9c1f-166f2a2e91f2','neck stretch','neck-stretch-18aa8c','Starting position: Stand tall with feet hip-width apart, shoulders relaxed down and back, arms resting at your sides, and gaze forward. Execution: Slowly tilt or rotate the head through gentle ranges of motion, holding each end position to lengthen the muscles of the neck without forcing the movement.',ARRAY['Stand upright with feet hip-width apart and shoulders relaxed away from the ears.','Gently tilt your head toward one shoulder until you feel a mild stretch along the side of the neck.','Hold the position for 15-30 seconds while breathing steadily.','Return the head to center, then repeat toward the opposite shoulder.','Add gentle forward and rotational tilts to stretch the back and sides of the neck.','Keep movements slow and controlled throughout, avoiding any bouncing.']::text[],ARRAY['Keep shoulders down and relaxed to isolate the neck muscles.','Move slowly and never force the stretch to the point of pain.','Maintain steady breathing and an upright posture.','Avoid rolling the head fully backward to protect the cervical spine.']::text[],'neck',ARRAY['upper_traps','traps','sternocleidomastoid']::text[],'bodyweight','stretching','beginner',ARRAY['stretching','mobility','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fa6a3579-8bbe-47ab-b0dc-4d0545f16a34','Negative pull ups','negative-pull-ups','Starting position: Begin at the top of a pull-up position with your chin above the bar, either by jumping up or using assistance to reach this position. Execution: Slowly lower your body in a controlled manner until your arms are fully extended, focusing on the eccentric (negative) portion of the pull-up movement.',ARRAY['Jump or use assistance to reach the top position with chin above the bar and arms fully contracted','Grip the bar with hands shoulder-width apart using an overhand grip','Engage your core and maintain a straight body line throughout the movement','Slowly lower yourself down taking 3-5 seconds to reach full arm extension','Control the descent by actively engaging your back muscles and biceps','Once arms are fully extended, either drop safely to the ground or jump back up to repeat']::text[],ARRAY['Focus on controlling the lowering phase rather than just dropping down quickly','Keep your shoulders pulled back and down to properly engage the latissimus dorsi','Maintain tension in your core to prevent excessive swaying or kipping','Start with shorter time periods and gradually increase the lowering duration as strength improves','This exercise is excellent for building strength to eventually perform full pull-ups']::text[],'back','{}'::text[],'bodyweight','back','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b93996af-6946-4cf8-88e0-792b1f545750','Neutral Grip Lat Pulldown','neutral-grip-lat-pulldown','Starting position: Sit at a lat pulldown machine with a neutral grip (palms facing each other). Execution: Pull the bar toward your chest while keeping elbows close to your body, then slowly return to the starting position.',ARRAY['Adjust the knee pad to secure your legs and prevent your body from lifting during the movement','Grasp the neutral grip handles with arms fully extended overhead, maintaining a slight forward lean of your torso','Initiate the pull by depressing your shoulder blades and drawing your elbows down and back toward your sides','Pull the handles to your upper chest level while keeping your chest up and shoulders back','Squeeze your lat muscles at the bottom of the movement for a brief pause','Slowly return the weight to the starting position, maintaining tension throughout the eccentric phase']::text[],ARRAY['Keep your shoulders down and back throughout the entire movement to prevent shoulder impingement','Focus on pulling with your back muscles rather than your arms by thinking about driving your elbows behind your body','Maintain a controlled tempo, especially during the return phase, to maximize muscle engagement and prevent injury','Avoid leaning back excessively or using momentum to complete the movement','Keep your wrists straight and in line with your forearms to prevent strain']::text[],'back','{}'::text[],'cable','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3b69631f-65b9-4af3-9c65-5739375e3dfb','Normal grip pull ups (Full range of motion','normal-grip-pull-ups-full-range-of-motion','Starting position: Hang from a pull-up bar with hands shoulder-width apart using an overhand grip, arms fully extended, and feet off the ground. Execution: Pull your body upward until your chin clears the bar, then lower yourself back to the full dead hang position with control.',ARRAY['Grip the bar with hands shoulder-width apart using an overhand grip, ensuring a secure hold','Hang with arms fully extended in a dead hang position, engaging your core and keeping shoulders active','Pull yourself up by driving your elbows down and back, leading with your chest','Continue pulling until your chin clears the bar completely','Lower yourself slowly and under control back to the starting dead hang position','Maintain tension throughout your body during both the ascending and descending phases']::text[],ARRAY['Avoid swinging or using momentum - maintain strict form throughout the entire movement','Achieve full range of motion by reaching complete arm extension at the bottom and chin over bar at the top','Keep your core engaged and maintain a slight forward lean to optimize lat activation','Focus on controlled eccentric lowering as this builds strength and prevents injury','Progress gradually by using assistance bands or negatives if unable to perform full bodyweight repetitions']::text[],'back','{}'::text[],'bodyweight','back','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','85d78505-04b8-4cf6-b277-c215eeb462a7','Oblique Crunches','oblique-crunches','Starting position: Lie on your back with knees bent and feet flat on the floor, hands placed lightly behind your head or crossed over your chest. Execution: Crunch up and to one side, bringing your elbow toward the opposite knee while keeping the other shoulder blade on the ground, then lower back down with control.',ARRAY['Lie on your back with knees bent at 90 degrees and feet flat on the floor','Place hands lightly behind your head without interlacing fingers, or cross arms over your chest','Engage your core and lift your shoulder blades slightly off the ground','Crunch up and rotate to one side, bringing your right elbow toward your left knee','Lower back down to the starting position with control','Complete all repetitions on one side before switching to the other side']::text[],ARRAY['Keep your lower back pressed against the floor throughout the movement to protect your spine','Focus on rotating through your torso rather than just moving your arms','Avoid pulling on your neck with your hands - let your core muscles do the work','Exhale as you crunch up and inhale as you lower down to maintain proper breathing','Move slowly and controlled to maximize muscle engagement and prevent injury']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','93e53831-f499-4d0b-b266-120445c24555','Oblique Crunches','oblique-crunches-93e53831','Starting position: Lie on your back with knees bent and feet flat on the floor, hands behind your head with elbows wide. Execution: Lift your shoulder blades off the ground while bringing one elbow toward the opposite knee, alternating sides with each repetition.',ARRAY['Lie on your back with knees bent at 90 degrees and feet flat on the floor','Place hands lightly behind your head with elbows pointed out to the sides','Engage your core and lift your shoulder blades off the ground','Rotate your torso to bring your right elbow toward your left knee while keeping the right elbow stationary','Return to center and repeat on the opposite side, bringing left elbow toward right knee','Continue alternating sides in a controlled manner']::text[],ARRAY['Keep your lower back pressed against the floor throughout the movement','Avoid pulling on your neck with your hands - let your core do the work','Focus on rotating through your torso rather than just moving your elbows','Maintain tension in your abs even when returning to the starting position','Breathe out as you crunch up and in as you lower back down']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','70ac8f96-201b-4bd7-9ac5-f72e3aca2748','One Arm Dumbbell Bench Press - with rotation','one-arm-dumbbell-bench-press-with-rotation','Starting position: Lie on a flat bench with one dumbbell held in your right hand directly above your shoulder, arm extended, while your left arm rests at your side or holds the bench for stability. Execution: Lower the dumbbell toward your chest while simultaneously rotating your torso slightly toward the working arm, then press back up while rotating back to center.',ARRAY['Set up on a flat bench with feet firmly planted on the floor and core engaged for stability','Hold one dumbbell with a neutral grip, starting with arm fully extended above your shoulder','Lower the weight slowly toward the outside of your chest while allowing a slight torso rotation toward the working side','Keep your shoulder blade pulled back and down throughout the movement','Press the dumbbell back up to starting position while rotating your torso back to center','Complete all repetitions on one side before switching to the other arm']::text[],ARRAY['Keep the non-working arm either resting on your torso or gripping the bench for additional stability','Control the rotational movement - it should be subtle and natural, not forced or excessive','Maintain tension in your core throughout to prevent excessive twisting or losing balance on the bench','Use a lighter weight than you would for bilateral dumbbell bench press until you master the coordination and balance required']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4e6181e0-c20f-4449-91e7-48d1eef1f268','One arm Dumbbell Floor Press alternating','one-arm-dumbbell-floor-press-alternating','Starting position: Lie flat on your back on the floor with knees bent and feet flat, holding a dumbbell in one hand with arm extended straight up over your chest while the other arm rests at your side. Execution: Lower the dumbbell slowly until your upper arm touches the floor, then press it back up to the starting position, alternating arms after each repetition.',ARRAY['Lie flat on the floor with your back pressed against the ground and knees bent at 90 degrees','Hold one dumbbell with a firm grip, arm fully extended above your chest while keeping your shoulder blade pulled back','Lower the weight in a controlled motion until your upper arm gently touches the floor','Press the dumbbell back up to the starting position using your chest muscles','Switch the dumbbell to the opposite hand and repeat the movement','Maintain constant tension in your core throughout the entire exercise']::text[],ARRAY['Keep your shoulder blades pulled back and down against the floor to maintain proper shoulder positioning','Control the descent phase slowly to maximize muscle activation and prevent injury','Avoid bouncing your arm off the floor - just lightly touch and immediately press back up','Keep your core engaged and avoid arching your lower back excessively','Focus on feeling the stretch in your chest at the bottom position before pressing up']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d30b1013-b7ae-47da-847e-e58e9ea770cc','One arm dumbbell fly','one-arm-dumbbell-fly','Starting position: Lie on a flat bench holding a dumbbell in one hand with arm extended above your chest, palm facing inward, while your other hand grips the bench for stability. Execution: Lower the dumbbell in a wide arc out to the side until you feel a stretch in your chest, then bring it back up along the same path to the starting position.',ARRAY['Lie flat on a bench with feet planted firmly on the floor for stability','Hold one dumbbell with a neutral grip, arm extended directly above your chest','Keep a slight bend in your elbow throughout the entire movement to protect the joint','Lower the weight slowly in a wide arc until you feel a deep stretch in your chest muscle','Squeeze your chest muscle as you bring the dumbbell back up along the same curved path','Complete all repetitions on one side before switching to the other arm']::text[],ARRAY['Maintain the same elbow angle throughout the movement to avoid turning this into a pressing motion','Use a weight that allows you to control the movement completely, as this exercise puts the shoulder in a vulnerable position','Focus on feeling the stretch and contraction in your chest rather than simply moving the weight from point A to point B','Keep your core engaged and maintain contact between your back and the bench throughout the exercise','Never lower the weight below the level of your torso to prevent excessive shoulder strain']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c5a9becd-0051-47b0-9e75-ed52fedd6d44','One-Arm Dumbbell Row bench','one-arm-dumbbell-row-bench','Starting position: Place one knee and same-side hand on a flat bench for support, with the opposite foot planted firmly on the floor and a dumbbell in the free hand hanging straight down. Execution: Pull the dumbbell up toward your hip in a rowing motion, squeezing your shoulder blade back, then lower with control to the starting position.',ARRAY['Position yourself with one knee and matching hand on the bench, keeping your back straight and parallel to the floor','Plant your opposite foot firmly on the ground for stability and hold the dumbbell with a neutral grip','Initiate the movement by pulling your shoulder blade back and driving your elbow toward the ceiling','Pull the dumbbell up toward your hip, keeping it close to your body throughout the movement','Squeeze your back muscles at the top of the movement for a brief pause','Lower the dumbbell slowly and with control back to the starting position']::text[],ARRAY['Keep your core engaged and spine neutral throughout the entire movement to protect your lower back','Focus on pulling with your back muscles rather than your arm by initiating the movement with your shoulder blade','Avoid rotating your torso or using momentum to lift the weight','Keep your wrist straight and maintain a firm grip on the dumbbell throughout the exercise','Ensure full range of motion by allowing a complete stretch at the bottom and full contraction at the top']::text[],'back','{}'::text[],'dumbbell','back','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','eff7ae70-1117-4d71-a35f-15db81a16242','One-Arm Kettlebell Military Press','one-arm-kettlebell-military-press','Starting position: Stand with feet shoulder-width apart, holding a kettlebell at shoulder height in one hand with the bell resting on the back of your wrist and forearm. Execution: Press the kettlebell straight overhead in a controlled motion until your arm is fully extended, then lower it back to the starting position.',ARRAY['Clean the kettlebell to shoulder height with the bell resting on the back of your wrist and your elbow tucked close to your ribs','Engage your core and maintain a neutral spine with feet planted firmly shoulder-width apart','Press the kettlebell straight up overhead following a slight arc path, keeping your wrist straight and strong','Fully extend your arm at the top while keeping your shoulder packed down and back','Lower the kettlebell with control back to the starting position at shoulder height','Complete all repetitions on one side before switching to the other arm']::text[],ARRAY['Keep the non-working arm relaxed at your side or place it behind your back for better stability and core engagement','Avoid leaning away from the working side - maintain an upright torso throughout the entire movement','Focus on a smooth pressing path that moves slightly back over your head rather than straight up to maintain proper shoulder mechanics','Breathe out forcefully during the pressing phase and inhale during the lowering phase','Start with lighter weight to master the movement pattern before progressing to heavier kettlebells']::text[],'shoulders','{}'::text[],'kettlebell','shoulders','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','79b0e11d-db13-4542-a7ac-7f666485f1fa','One-Arm Kettlebell Snatch - From ground','one-arm-kettlebell-snatch-from-ground',null,ARRAY['Kettlebell between feet','Hinge, grip with one hand','Swing back, then explosively drive hips','Pull kettlebell overhead in one motion','Punch through at top, catch overhead']::text[],ARRAY['Advanced movement - learn swing and clean first','Don''t flip kettlebell onto wrist','One smooth motion from floor to overhead','Lock out completely at top','Control the descent']::text[],'full_body','{}'::text[],'kettlebell','core',null,ARRAY['strength','functional','plyometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4fcd55ed-a563-4f9f-b43c-4b4ea35e5cc4','One-Arm Kettlebell Snatch from ground','one-arm-kettlebell-snatch-from-ground-4fcd55ed',null,ARRAY['Kettlebell between feet','Hinge, grip with one hand','Swing back, then explosively drive hips','Pull kettlebell overhead in one motion','Punch through at top, catch overhead']::text[],ARRAY['Advanced movement - learn swing and clean first','Don''t flip kettlebell onto wrist','One smooth motion from floor to overhead','Lock out completely at top','Control the descent']::text[],'full_body','{}'::text[],'kettlebell','core',null,ARRAY['strength','functional','plyometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2e6e0a8a-ab5d-4f00-a6b4-c1f025190b79','One-Arm Side Laterals (L)','one-arm-side-laterals-l','Starting position: Stand with feet shoulder-width apart, core engaged, and left arm hanging naturally at your side while right hand is placed on hip or behind back. Execution: Raise your left arm out to the side until it reaches shoulder height, then slowly lower it back to the starting position with control.',ARRAY['Stand tall with feet shoulder-width apart and engage your core muscles','Place your right hand on your hip or behind your back for stability','Keep your left arm straight but not locked, with a slight bend in the elbow','Raise your left arm out to the side until it reaches shoulder height, leading with your pinky finger','Hold briefly at the top position, then slowly lower your arm back to starting position','Complete all repetitions on the left side before switching to the right arm']::text[],ARRAY['Keep your torso upright and avoid leaning away from the working arm during the movement','Control the descent phase of the movement to maximize muscle engagement and prevent momentum','Avoid raising your arm above shoulder height to prevent shoulder impingement','Focus on initiating the movement from your shoulder rather than using your back or torso to swing the arm','Maintain steady breathing throughout the exercise, exhaling as you raise your arm and inhaling as you lower it']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','40e40492-ae55-417f-8391-2e6ea6c170d9','One-Arm Side Laterals (R)','one-arm-side-laterals-r','Starting position: Stand with feet shoulder-width apart, left hand on hip for stability, right arm hanging at your side. Execution: Raise your right arm out to the side until it reaches shoulder height, then slowly lower back to starting position.',ARRAY['Stand tall with core engaged and feet planted firmly on the ground','Place your left hand on your hip to maintain balance and stability','Keep your right arm straight but not locked, with a slight bend at the elbow','Raise your right arm out to the side in a controlled arc until it reaches shoulder height','Hold briefly at the top position, feeling the contraction in your shoulder','Lower your arm slowly back to the starting position, maintaining control throughout the movement']::text[],ARRAY['Keep your torso upright and avoid leaning away from the working arm','Focus on lifting with your shoulder muscles rather than swinging or using momentum','Maintain a controlled tempo with a 2-second lift and 3-second lowering phase','Stop at shoulder height to avoid impingement and maintain proper form','Complete all repetitions on the right side before switching to the left arm']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4001ef61-57a1-4f18-8c0b-8167e15c6832','Open and close jumping jacks','open-and-close-jumping-jacks','Starting position: Stand upright with feet together and arms at your sides. Execution: Jump while simultaneously spreading your legs shoulder-width apart and raising your arms overhead, then jump back to the starting position.',ARRAY['Stand tall with feet together, arms relaxed at your sides, and engage your core','Jump up while spreading your feet apart to shoulder-width distance and simultaneously raise both arms overhead','Land softly on the balls of your feet with knees slightly bent to absorb impact','Immediately jump again while bringing your feet back together and lowering your arms to your sides','Maintain a steady rhythm and controlled breathing throughout the movement','Continue for the desired number of repetitions or time duration']::text[],ARRAY['Land softly on the balls of your feet to reduce joint impact and prevent injury','Keep your core engaged throughout the exercise to maintain proper posture and stability','Maintain a controlled pace rather than rushing through the movements to ensure proper form','If you experience knee or ankle discomfort, step side to side instead of jumping','Keep your knees slightly bent during landing to act as natural shock absorbers']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','601cae63-a0d3-4f10-9a7f-114a5eb033e0','Over and under','over-and-under','Starting position: Stand facing an imaginary horizontal barrier at waist height with feet shoulder-width apart and arms at your sides. Execution: Alternate between stepping over the imaginary barrier by lifting one knee high, then immediately ducking under by squatting low and stepping forward, creating a continuous over-under movement pattern.',ARRAY['Stand with feet shoulder-width apart and establish your imaginary waist-high barrier in front of you','Lift your right knee up high as if stepping over the barrier, then step forward','Immediately squat down low and take another step forward as if ducking under a barrier','Rise back to standing position and repeat the sequence with your left leg leading the over movement','Continue alternating the over-under pattern while moving forward in a controlled manner','Maintain steady breathing throughout the movement sequence']::text[],ARRAY['Keep your core engaged throughout both the high knee lift and low squat portions','Land softly on the balls of your feet to reduce impact on joints','Maintain good posture even when squatting low - avoid rounding your back','Control the tempo to ensure proper form rather than rushing through the movement','Visualize the actual barriers to maintain consistent movement heights']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['functional','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','acaa8104-8a71-43bb-83ca-6a5c8085a3d8','Over and under (Left)','over-and-under-left','Starting position: Stand with feet shoulder-width apart, facing an imaginary or real obstacle at waist height. Execution: Step over the obstacle with your left leg leading, then immediately duck under by bending at hips and knees, alternating between stepping over and ducking under in a continuous flowing motion.',ARRAY['Begin in an athletic stance with knees slightly bent and core engaged','Step over the imaginary obstacle by lifting your left knee high toward your chest, then step through','Immediately transition to ducking under by bending at your hips and knees while keeping your back straight','Return to standing position and repeat the over-under sequence','Maintain a steady rhythm throughout the movement','Keep your head up and eyes forward to maintain balance and coordination']::text[],ARRAY['Focus on smooth transitions between the over and under movements to maximize coordination benefits','Engage your core throughout the entire exercise to maintain stability and protect your lower back','Start slowly to master the movement pattern before increasing speed or intensity','Ensure adequate clearance when stepping over to avoid losing balance','Keep your weight centered over your feet during the ducking motion']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['functional','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','037a9f51-9b02-4404-979a-6ad18f62fc9d','Overhead Cable Curl','overhead-cable-curl-09be90','Starting position: Stand between two cable pulleys set at or above shoulder height, grasping a handle in each hand with palms facing up and arms extended out to the sides in a T-position. Execution: Keeping your upper arms fixed and elbows high, curl both handles toward your head by contracting your biceps, then slowly return to the extended starting position.',ARRAY['Set both cable pulleys to a high position and select a moderate weight.','Grasp a handle in each hand with palms up, arms extended out to your sides.','Keep your upper arms parallel to the floor and elbows stationary.','Curl both handles toward your head by flexing your elbows and squeezing your biceps.','Pause briefly at peak contraction, then slowly return to the starting position.','Maintain tension throughout and avoid dropping your elbows.']::text[],ARRAY['Keep your elbows high and fixed throughout the movement to isolate the biceps.','Squeeze the biceps hard at the top for maximum peak contraction.','Control the eccentric phase and avoid using momentum.','Maintain an upright torso and braced core to prevent swaying.']::text[],'biceps',ARRAY['brachialis','brachioradialis','forearm_flexors']::text[],'cable','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','26098d10-600c-4876-ac19-e9fcac2ef835','Overhead Cable Rope Extension','overhead-cable-rope-extension','Starting position: Stand with your back to a high pulley with a rope attachment, elbows bent overhead. Execution: Extend your elbows to bring the rope forward, keeping your elbows fixed in place.',ARRAY['Set the cable machine to the highest pulley position and attach a rope handle','Stand facing away from the machine with feet shoulder-width apart for stability','Grasp the rope with both hands using a neutral grip, positioning your hands at the end knots','Lean slightly forward at the hips and position your upper arms parallel to the floor','Extend your forearms forward and down in a controlled arc until your arms are fully straight','Slowly return to the starting position by allowing your forearms to bend back overhead']::text[],ARRAY['Keep your upper arms completely stationary throughout the movement to isolate the triceps','Maintain a slight forward lean and engage your core to prevent excessive back arching','Control the weight on both the extending and returning phases to maximize muscle engagement','Avoid using momentum or swinging the weight to prevent injury and ensure proper muscle activation','Keep your wrists straight and maintain a firm grip on the rope throughout the entire exercise']::text[],'triceps','{}'::text[],'cable','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6413b465-6df0-4e2c-9f4b-ae36dc70ebbf','Overhead Cable Tricep Extension','overhead-cable-tricep-extension-26a54f','Starting position: Stand facing away from a cable machine set to a low pulley, holding a rope attachment overhead with both hands, elbows bent and arms alongside your head. Execution: Extend your elbows to press the rope straight up overhead until your arms are fully locked out, then slowly lower back to the starting stretched position.',ARRAY['Attach a rope to a low cable pulley and grip it with both hands, raising your arms overhead.','Position your elbows close to your head with forearms bent behind you.','Extend your elbows to drive the rope upward until your arms are fully straight.','Squeeze your triceps at the top, then slowly bend your elbows to return to the start.','Keep your torso upright and core braced throughout the movement.']::text[],ARRAY['Keep your upper arms stationary and elbows pointing forward, not flaring out.','Avoid arching the lower back by bracing your core.','Control the eccentric to maximize the triceps stretch.','Fully lock out at the top for peak contraction.']::text[],'triceps',ARRAY['core','front_deltoids','forearms']::text[],'cable','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','36aec113-771d-4ec9-854f-81f29e00cdd2','Overhead Lunge','overhead-lunge','Starting position: Stand tall with feet hip-width apart, arms extended straight overhead. Execution: Step one foot forward into a lunge position while maintaining arms overhead, then return to starting position and alternate legs.',ARRAY['Stand with feet hip-width apart and extend both arms straight up toward the ceiling','Keep your core engaged and shoulders pulled back throughout the entire movement','Step forward with one leg, lowering your body until both knees are bent at approximately 90-degree angles','Keep your front knee aligned over your ankle and avoid letting it drift inward','Push through your front heel to return to the starting position with arms still overhead','Alternate legs with each repetition, maintaining controlled movement']::text[],ARRAY['Keep your torso upright and avoid leaning forward as you lunge','Maintain straight arms overhead to challenge your core stability and shoulder mobility','Land softly on your front foot and control the descent rather than dropping quickly','Keep most of your weight on your front leg during the lunge phase','If balance is challenging, start without the overhead arm position until you master the movement pattern']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','24c4168e-f900-4e8b-8969-cd32dba34d6c','Overhead Squat','overhead-squat','Starting position: Stand with feet shoulder-width apart, arms extended overhead with hands slightly wider than shoulder-width, palms facing forward. Execution: Lower into a squat by pushing hips back and bending knees while keeping arms overhead and chest up, then return to starting position.',ARRAY['Stand with feet shoulder-width apart and raise both arms straight overhead with palms facing forward','Keep your core engaged and chest up throughout the entire movement','Initiate the squat by pushing your hips back and bending at the knees while maintaining arm position','Lower until your thighs are parallel to the floor or as low as your mobility allows','Drive through your heels to return to the starting position while keeping arms overhead','Maintain control throughout both the descent and ascent phases']::text[],ARRAY['Keep your arms locked out overhead throughout the entire movement to challenge stability and core strength','Focus on pushing your knees out in line with your toes to prevent knee valgus','Maintain an upright torso position - avoid leaning forward excessively as this indicates mobility restrictions','Start with partial range of motion if you lack the flexibility to perform a full overhead squat safely','This exercise requires significant shoulder and ankle mobility - warm up thoroughly before attempting']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','371215cb-72ef-4039-8192-472234289504','Pec Deck Fly','pec-deck-fly','Starting position: Sit on the pec deck machine with your back firmly supported and grip the handles with slightly bent elbows. Execution: Bring the handles together in front of your chest, then return slowly to the starting position.',ARRAY['Adjust the seat height so your upper arms are parallel to the floor when grasping the handles','Sit with your back flat against the pad and plant both feet firmly on the ground','Grasp the vertical handles with a neutral grip or position your forearms against the arm pads','Keep a slight bend in your elbows throughout the entire movement','Bring your arms together by squeezing your chest muscles, not pulling with your arms','Control the weight on the return phase, resisting the machine''s pull back to starting position']::text[],ARRAY['Keep your shoulders back and down against the pad to prevent shoulder impingement','Focus on squeezing your chest muscles rather than just moving the weight','Maintain consistent tension throughout the full range of motion without locking out completely','Use a weight that allows you to control the movement in both directions','Keep your core engaged to maintain proper posture throughout the exercise']::text[],'chest','{}'::text[],'machine','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','27be2ac3-3b68-4ef8-94ab-e6bfb5ba4076','Pendlay Rows','pendlay-rows-3423f1','Starting position: Stand with feet hip-width apart, bend at the hips until the torso is nearly parallel to the floor, keeping a flat back and knees slightly bent. Grip the barbell with an overhand grip, wider than shoulder-width, with the bar resting on the floor. Execution: Explosively pull the barbell from the floor to the lower chest, driving the elbows up and squeezing the shoulder blades together, then lower the bar back to the floor under control before each rep.',ARRAY['Set up with a hip-hinge, torso near parallel to the floor and back flat.','Grip the barbell overhand, slightly wider than shoulder-width.','Pull the bar explosively from the floor to your lower chest, driving elbows up.','Squeeze your shoulder blades together at the top of the movement.','Lower the bar completely back to the floor under control.','Reset your position and repeat for the desired reps.']::text[],ARRAY['Keep your back flat and core braced throughout to protect the spine.','Let the bar rest on the floor between each rep for a dead-stop start.','Avoid using momentum from the lower back or legs to heave the weight.','Keep the torso angle fixed and horizontal during the pull.']::text[],'back',ARRAY['biceps','forearms','erector_spinae']::text[],'barbell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','04fccb0f-58a7-44b2-8676-573faad17634','Pike hold knee bends','pike-hold-knee-bends',null,ARRAY['Start in a pike position with hands planted firmly on the ground, arms straight, and hips raised high to form an inverted V-shape','Engage your core and maintain straight legs with feet hip-width apart','Slowly bend one knee and draw it toward your chest while keeping your weight balanced on your hands','Hold the knee bend for 2-3 seconds, maintaining the pike position with your hips elevated','Slowly extend the leg back to the starting position with control','Repeat with the opposite leg, alternating sides for the desired number of repetitions']::text[],ARRAY['Keep your shoulders directly over your wrists and maintain straight arms throughout the movement','Engage your core muscles to prevent your hips from dropping or swaying','Start with shorter hold times and fewer repetitions, gradually increasing as you build strength','If you experience wrist discomfort, perform the exercise on your fists or use push-up handles','Focus on controlled movements rather than speed to maximize muscle engagement and maintain proper form']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['calisthenics','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3882e700-1ad7-4b71-932a-6ee8983e50b2','Pike push ups','pike-push-ups','Starting position: Begin in a downward dog position with hands shoulder-width apart on the floor and feet elevated on a bench or box, creating an inverted V-shape with your body. Execution: Lower your head toward the floor by bending your elbows, then press back up to the starting position, focusing the movement on your shoulders and upper chest.',ARRAY['Position your hands shoulder-width apart on the floor with fingers spread wide for stability','Elevate your feet on a sturdy bench or box, walking your hands closer to create a steep downward angle','Keep your core engaged and maintain a straight line from your hips to your head throughout the movement','Lower your head toward the floor by bending your elbows until your head nearly touches the ground','Press through your palms to return to the starting position, maintaining control throughout the entire range of motion','Keep your legs straight and avoid sagging at the hips during the exercise']::text[],ARRAY['This exercise primarily targets the anterior deltoids and upper chest rather than the full chest like traditional push-ups','Start with feet on a lower surface and gradually increase height as you build strength and mobility','Maintain proper shoulder blade stability by keeping them pulled down and back throughout the movement','Stop immediately if you experience any neck pain or dizziness from the inverted position','Progress slowly as this exercise places significant load on the shoulders and requires good shoulder flexibility']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','61410917-4fb1-41f8-86d5-16dc88fe380b','Plank','plank','Starting position: Begin in a plank position with hands placed directly under shoulders, body forming a straight line from head to heels, and feet hip-width apart. Execution: Hold this static position while maintaining proper alignment and engaging the core muscles throughout the duration of the exercise.',ARRAY['Place hands directly under shoulders with fingers spread wide for stability','Position feet hip-width apart with toes tucked under','Create a straight line from head to heels by engaging your core and glutes','Keep your neck in neutral position by looking down at the mat','Breathe steadily while holding the position for the desired duration','Lower to knees when you can no longer maintain proper form']::text[],ARRAY['Keep hips level and avoid sagging or piking up','Engage your core muscles throughout the entire hold','Distribute weight evenly between hands to avoid wrist strain','Stop the exercise if you feel lower back pain or cannot maintain proper form','Start with shorter holds and gradually increase duration as strength improves']::text[],'core',ARRAY['front_deltoids','triceps','serratus_anterior','lower_back']::text[],'bodyweight','core','beginner',ARRAY['core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7e35442f-7c48-4d32-8e18-2761542f9b17','Plank','plank-32e108','Starting position: Lie face down then rise onto forearms and toes. Execution: Hold static position maintaining straight body line.',ARRAY['Position forearms on ground with elbows under shoulders','Rise onto toes creating straight line from head to heels','Engage core muscles and squeeze glutes tight','Hold position while breathing normally','Lower to knees when form begins to break']::text[],ARRAY['Keep hips level with shoulders to avoid sagging or piking','Maintain neutral spine by looking at floor slightly ahead','Breathe steadily throughout the hold rather than holding breath','Start with shorter holds and gradually increase duration as strength improves']::text[],'abs','{}'::text[],'bodyweight',null,null,'{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2640441e-fc3e-46e7-87ee-77f25ed81d32','Plank elbow to knee','plank-elbow-to-knee','Starting position: Begin in a plank position with hands planted firmly on the ground, body in a straight line from head to heels. Execution: Bring one knee forward toward the corresponding elbow while maintaining the plank position, then return to starting position and repeat on the other side.',ARRAY['Start in a high plank position with hands directly under shoulders and body forming a straight line','Keep your core engaged and hips level throughout the movement','Draw one knee forward toward the same-side elbow in a controlled motion','Return the leg back to plank position without letting the foot touch the ground','Alternate legs and maintain steady breathing throughout the exercise','Keep your weight evenly distributed between your hands and supporting leg']::text[],ARRAY['Maintain a neutral spine and avoid letting your hips sag or pike up','Keep your shoulders stable and directly over your wrists','Focus on controlled movements rather than speed to maximize core engagement','Breathe steadily and avoid holding your breath during the movement','Stop if you feel strain in your lower back and check your form']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','364dc379-ca4e-4fe2-9d95-684619a8b693','Plank in and outs','plank-in-and-outs','Starting position: Begin in a plank position with hands planted firmly on the ground, body in a straight line from head to heels. Execution: Pull both knees toward your chest simultaneously, then extend them back out to return to the starting plank position.',ARRAY['Start in a high plank position with hands directly under shoulders and body forming a straight line','Engage your core and keep your back flat throughout the movement','Pull both knees toward your chest simultaneously while maintaining upper body stability','Pause briefly when knees are pulled in toward your torso','Extend both legs back out to return to the starting plank position','Maintain control throughout the entire range of motion']::text[],ARRAY['Keep your hands firmly planted and avoid shifting weight during the knee pull','Maintain a neutral spine and avoid letting your hips pike up or sag down','Focus on controlled movement rather than speed to maximize core engagement','Keep your shoulders stable and directly over your wrists throughout the exercise','Breathe steadily and avoid holding your breath during the movement']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ac0cb7cb-0988-4591-9d99-716502691f26','Plank jack into jumping jacks','plank-jack-into-jumping-jacks','Starting position: Stand upright on a mat with feet together and arms at your sides. Execution: Perform continuous jumping jacks by jumping your feet apart while simultaneously raising your arms overhead, then jumping back to the starting position with feet together and arms at your sides.',ARRAY['Stand with feet together and arms relaxed at your sides','Jump both feet out to shoulder-width apart while simultaneously raising both arms overhead','Land softly on the balls of your feet with knees slightly bent','Immediately jump feet back together while lowering arms to your sides','Maintain a steady rhythm and continue the jumping motion','Keep your core engaged throughout the entire movement']::text[],ARRAY['Land softly on the balls of your feet to reduce impact on joints','Keep knees slightly bent when landing to absorb shock','Maintain an upright posture with chest up and shoulders back','Coordinate arm and leg movements in a smooth, rhythmic pattern','Start at a comfortable pace and gradually increase intensity as you warm up']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','cardio','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','39a6eaa7-efb4-455f-942f-e53ed5a9b526','Plank jacks','plank-jacks','Starting position: Begin in a plank position with hands planted firmly on the ground, arms straight, and feet together. Execution: Jump both feet apart to shoulder-width distance, then immediately jump them back together while maintaining the plank position throughout the movement.',ARRAY['Start in a high plank position with hands directly under shoulders and body in a straight line','Keep your core engaged and maintain a neutral spine throughout the entire movement','Jump both feet out wide to about shoulder-width apart, landing softly on the balls of your feet','Immediately jump your feet back together to the starting position','Maintain steady breathing and keep your upper body stable during the jumping motion','Continue the jumping motion for the desired number of repetitions or time duration']::text[],ARRAY['Keep your core tight and avoid letting your hips sag or pike up during the movement','Land softly on your feet to reduce impact on joints','Maintain proper plank form with hands firmly planted and shoulders stable','Start with a slower pace and gradually increase speed as you master the movement','Stop immediately if you feel strain in your lower back or cannot maintain proper form']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f93fa069-3b1d-41f0-bb26-2322bc4ea1c1','Plank kick out','plank-kick-out','Starting position: Begin in a plank position with hands placed directly under shoulders, body in a straight line from head to heels, and feet hip-width apart. Execution: While maintaining the plank position, alternate bringing each knee toward the chest in a controlled kicking motion, then return to starting position.',ARRAY['Start in a high plank position with hands directly under shoulders and body in a straight line','Engage your core and maintain neutral spine alignment throughout the movement','Bring one knee toward your chest in a controlled motion while keeping the other leg extended','Return the working leg back to starting position with control','Alternate legs, bringing the opposite knee toward chest','Maintain steady breathing and avoid rushing the movement']::text[],ARRAY['Keep hips level and avoid rotating the pelvis during the knee drive','Maintain strong plank form throughout - don''t let hips sag or pike up','Focus on controlled movement rather than speed to maximize core engagement','Keep hands firmly planted and shoulders stable over wrists','Engage core muscles continuously to protect the lower back']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','49739b94-19b6-4ec3-aa93-53e7c4824918','Plank on elbows','plank-on-elbows',null,ARRAY['Forearms on floor, elbows under shoulders','Body straight from head to heels','Hold position','Keep core tight, don''t let hips sag']::text[],ARRAY['Squeeze glutes','Keep neck neutral','Breathe normally','Don''t raise hips too high','Build time gradually']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1eab35ce-2d24-4908-8d60-082cf1f7ab74','Plank pose','plank-pose',null,ARRAY['Start on all fours, then step your feet back to straighten your legs.','Align your body in a straight line from head to heels.','Stack your shoulders directly over your wrists.','Hold, engaging your core and legs.']::text[],ARRAY['Do not let your hips sag or pike up.','Press firmly through your hands and spread your fingers.','Keep your neck neutral, gazing at the floor.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f6489ee0-7630-4041-ae1d-8e620b58883b','Plank SeeSaw','plank-seesaw','Starting position: Begin in a plank position with forearms on the ground, elbows under shoulders, and body in a straight line from head to heels. Execution: Rock forward and backward in a controlled seesaw motion while maintaining the plank position and core engagement.',ARRAY['Start in a forearm plank with elbows directly under shoulders and forearms flat on the ground','Keep your body in a straight line from head to heels with core engaged','Slowly rock your body forward, shifting weight toward your hands and moving shoulders past your elbows','Rock back to the starting position by shifting weight back toward your feet','Continue the seesaw motion in a slow, controlled rhythm','Maintain the plank position throughout without letting hips sag or pike up']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your lower back','Move slowly and with control - avoid quick or jerky motions','Breathe steadily and don''t hold your breath during the rocking motion','Stop if you feel your form breaking down or if your hips start to sag','Focus on the quality of movement rather than speed or duration']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2c7167fd-5e7e-444f-b7a8-291e362e638c','Plank shoulder taps','plank-shoulder-taps','Starting position: Begin in a high plank position with arms extended, hands directly under shoulders, and body in a straight line from head to heels. Execution: Alternately lift one hand to tap the opposite shoulder while maintaining plank position and core stability.',ARRAY['Start in a high plank position with hands placed directly under your shoulders and feet hip-width apart','Engage your core and maintain a straight line from your head to your heels','Shift your weight slightly to one side and lift the opposite hand to tap the opposite shoulder','Return the hand to the starting position and repeat the movement with the other hand','Continue alternating shoulder taps while keeping your hips as stable as possible','Maintain steady breathing throughout the entire movement']::text[],ARRAY['Keep your hips level and avoid rotating or swaying from side to side during the shoulder taps','Maintain a strong plank position with engaged core muscles throughout the entire exercise','Place hands directly under shoulders to maintain proper alignment and stability','Keep the movement controlled and deliberate rather than rushing through the taps','Distribute weight evenly when lifting one hand to prevent excessive stress on the supporting arm']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','73368005-c7ae-4086-b7e5-31963e96af4d','Plank shoulder taps into reaches','plank-shoulder-taps-into-reaches','Starting position: Begin in a high plank position with hands planted firmly on the ground, arms straight, and body in a straight line from head to heels. Execution: Lift one hand to tap the opposite shoulder, then extend that same arm forward in a reach before returning to plank and repeating on the other side.',ARRAY['Start in a high plank position with hands shoulder-width apart and body in a straight line','Engage your core and keep hips level as you lift your right hand','Tap your left shoulder briefly, then extend that same arm straight forward','Return your right hand to the starting position and repeat the movement with your left hand','Continue alternating sides while maintaining proper plank form','Keep your feet slightly wider than hip-width apart for better stability']::text[],ARRAY['Keep your hips square and avoid rotating your torso during the shoulder taps and reaches','Maintain a strong plank position throughout the entire movement without sagging or piking','Move with control rather than speed to maximize core engagement','Distribute weight evenly on your supporting hand when performing the tap and reach','Keep your core tight to prevent excessive hip movement or swaying']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','38ef796b-7e3c-4370-9452-72b924837216','Plank Side Arm Reach Dynamic','plank-side-arm-reach-dynamic-838196','Starting position: Lie on your side propped on your forearm with knees bent and stacked, top hand reaching along the mat in front of your torso. Execution: Engage your core and reach the top arm forward and around, rotating slightly through the trunk while keeping the hips lifted and stable, then return to the start and repeat.',ARRAY['Set up on your side resting on your bottom forearm with knees bent and stacked.','Place your top hand on the mat in front of you and lift your hips into a modified side plank.','Reach the top arm forward and across, rotating gently through the torso.','Control the movement back to the starting position without dropping the hips.','Complete the reps on one side, then switch to the other side.']::text[],ARRAY['Keep your core braced to protect the lower back throughout.','Move slowly and control the rotation rather than swinging the arm.','Maintain a straight line from head to hips, avoiding sagging.','Keep the supporting shoulder stacked over the elbow for stability.']::text[],'obliques',ARRAY['front_deltoids','glute_med','triceps']::text[],'bodyweight','core','beginner',ARRAY['core','strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c2b2d15f-5841-45a2-87e4-503101f3422e','Plank to knee tap','plank-to-knee-tap','Starting position: Begin in a plank position with hands planted firmly on the ground, body in a straight line from head to heels. Execution: While maintaining the plank position, alternate bringing each knee down to lightly tap the ground beneath your torso, then return to the starting plank position.',ARRAY['Start in a high plank position with hands directly under shoulders and body in a straight line','Engage your core and keep hips level throughout the movement','Slowly lower one knee down to lightly tap the ground beneath your torso','Return the knee back to the starting plank position with control','Alternate to the opposite knee and repeat the tapping motion','Maintain steady breathing and avoid rocking the hips side to side']::text[],ARRAY['Keep your core engaged throughout to prevent sagging in the lower back','Maintain a neutral spine and avoid lifting your hips too high','Control the movement - don''t drop the knee heavily to the ground','Keep your hands firmly planted and shoulders stable over your wrists','Focus on minimal hip movement to maximize core activation']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e4241c30-f7d8-4051-85d7-7a95e221bf8c','Plank toe touches','plank-toe-touches','Starting position: Begin in a plank position with forearms on the ground, body in a straight line from head to heels. Execution: While maintaining the plank position, alternately bring each knee toward the opposite elbow in a controlled twisting motion.',ARRAY['Start in a forearm plank with elbows directly under shoulders and body in a straight line','Engage your core muscles and maintain neutral spine alignment','Bring your right knee toward your left elbow while rotating your torso slightly','Return to plank position with control, then bring left knee toward right elbow','Continue alternating sides in a slow, controlled rhythm','Keep hips level and avoid excessive rotation or sagging']::text[],ARRAY['Maintain a strong plank position throughout the entire movement','Focus on controlled movement rather than speed to maximize core engagement','Keep your hips as stable as possible while performing the knee-to-elbow motion','Breathe steadily and avoid holding your breath during the exercise','Stop if you feel lower back strain and check your form']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','980a6af6-f72f-4e21-bfcf-4253622d507d','Plate Front Raise','plate-front-raise','Starting position: Stand holding a weight plate with both hands in front of the thighs. Execution: Raise the plate forward until it reaches shoulder height, then slowly lower.',ARRAY['Stand with feet shoulder-width apart and core engaged, holding the weight plate with both hands using an overhand grip','Keep your arms slightly bent throughout the movement to reduce stress on the elbow joints','Raise the plate smoothly in front of your body until it reaches shoulder height, maintaining control','Pause briefly at the top position without swinging or using momentum','Lower the plate back to the starting position in a slow, controlled manner','Maintain proper posture with shoulders back and chest up throughout the entire movement']::text[],ARRAY['Keep the movement slow and controlled to maximize muscle engagement and prevent injury','Avoid using momentum or swinging the plate, as this reduces effectiveness and increases injury risk','Stop the upward motion at shoulder height to prevent impingement of the shoulder joint','Choose an appropriate weight that allows you to maintain proper form throughout all repetitions','Keep your core tight and avoid arching your back during the lifting phase']::text[],'shoulders','{}'::text[],'barbell','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6d78b4e0-d8b4-4cd2-8e0b-ab6d559b717d','Plie Dumbbell Squat','plie-dumbbell-squat','Starting position: Stand with feet wider than shoulder-width apart, toes turned out at 45-degree angles, holding a dumbbell with both hands at chest level. Execution: Lower into a squat by bending at the hips and knees while keeping the dumbbell close to your body, then drive through your heels to return to starting position.',ARRAY['Stand with feet wider than shoulder-width apart and turn your toes out at approximately 45-degree angles','Hold a dumbbell vertically with both hands at chest level, gripping the top weight plate securely','Keep your chest up and core engaged as you begin to lower by pushing your hips back and bending your knees','Descend until your thighs are parallel to the floor or as low as your mobility allows while maintaining proper form','Drive through your heels and squeeze your glutes to return to the starting position','Maintain the wide stance and turned-out toe position throughout the entire movement']::text[],ARRAY['Keep your knees tracking in line with your toes throughout the movement to prevent knee valgus','Maintain an upright torso and avoid leaning forward excessively to protect your lower back','Focus on pushing your knees out and engaging your inner thighs due to the wide stance','Control the descent and avoid bouncing at the bottom of the squat to maximize muscle engagement']::text[],'quads','{}'::text[],'dumbbell','legs','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8e7c3c00-5f0b-40b1-b64d-84b78fa6ec93','Plow pose','plow-pose',null,ARRAY['Lie on your back and lift your legs over your head.','Lower your toes to the floor behind your head.','Support your back with your hands or extend arms on the floor.','Hold for several breaths, then roll down slowly.']::text[],ARRAY['Do not turn your head while in this pose.','Keep your weight on your shoulders, not your neck.','Skip this pose if you have neck issues.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cbe360e8-fa98-4793-b327-c2769ac69943','Plyo Push-up','plyo-push-up','Starting position: Begin in a standard push-up position with hands slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Lower into a push-up, then explosively push up with enough force to lift your hands off the ground, land softly, and immediately transition into the next repetition.',ARRAY['Start in a standard push-up position with proper alignment and engage your core','Lower your body slowly and controlled until your chest nearly touches the floor','Explosively push up through your palms with maximum force to propel your hands off the ground','Keep your body rigid during the airborne phase and prepare for landing','Land softly with hands returning to starting position and absorb the impact through your arms','Immediately transition into the next repetition or rest briefly if needed']::text[],ARRAY['Land softly on your palms to reduce impact on wrists and shoulders','Maintain proper push-up form throughout the entire movement to prevent injury','Start with small explosive movements and gradually increase the height as you build strength','Avoid this exercise if you have wrist, shoulder, or elbow issues','Focus on quality over quantity - fewer perfect reps are better than many poor ones']::text[],'chest','{}'::text[],'bodyweight','chest','advanced',ARRAY['plyometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f8d7664f-01f0-4a79-abd8-85bbe9f067ac','Posterior upper arm (left)','posterior-upper-arm-left','Starting position: Stand with feet hip-width apart, extend your left arm overhead, then bend the elbow to lower your left hand behind your head toward your upper back. Execution: Use your right hand to gently pull the left elbow across your body while pressing the left hand down your back to stretch the posterior upper arm muscles.',ARRAY['Stand tall with feet hip-width apart and shoulders relaxed','Raise your left arm straight overhead, then bend the elbow to drop your left hand behind your head','Place your right hand on your left elbow and gently pull it across toward the right side of your head','Keep your left hand reaching down your back as far as comfortable','Hold the stretch for 20-30 seconds while breathing normally','Repeat on the right side for balanced flexibility']::text[],ARRAY['Apply gentle, steady pressure rather than bouncing or forcing the stretch','Keep your core engaged and avoid arching your back excessively','Stop immediately if you feel pain in your shoulder or elbow joint','Focus on feeling the stretch along the back of your upper arm, not in the joints','Maintain proper posture throughout the movement with chest up and shoulders square']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ded0fb25-cb67-47a2-9a29-23e7f14ae6ac','Posterior upper arm stretch (right)','posterior-upper-arm-stretch-right','Starting position: Stand tall with feet hip-width apart, raise your right arm overhead and bend the elbow so your right hand reaches toward your upper back between your shoulder blades. Execution: Use your left hand to gently pull the right elbow toward the center of your head, creating a stretch along the back of your right upper arm.',ARRAY['Stand with good posture and engage your core muscles','Raise your right arm straight up overhead','Bend your right elbow and let your right hand drop down behind your head toward your upper back','Reach your left hand over and gently grasp your right elbow','Apply gentle, steady pressure pulling the right elbow toward your head''s center','Hold the stretch for 15-30 seconds while breathing normally']::text[],ARRAY['Keep your head in neutral position and avoid pushing it forward during the stretch','Apply only gentle pressure - never force the stretch or cause sharp pain','Keep your torso upright and avoid leaning to compensate for tight muscles','Focus on feeling the stretch along the triceps muscle at the back of your upper arm','Stop immediately if you experience any shoulder joint discomfort']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','18b57d25-5597-4b00-8237-cc359e4609c8','Power Snatch (ISSUE_ back on pick up a bit bend)','power-snatch-issue-back-on-pick-up-a-bit-bend','Starting position: Stand with feet hip-width apart, arms at sides, preparing to simulate the explosive snatch movement without equipment. Execution: Explosively jump upward while simultaneously pulling arms overhead in one fluid motion, landing softly in a partial squat with arms extended above head.',ARRAY['Begin in athletic stance with feet hip-width apart and slight bend in knees','Initiate movement by explosively extending hips and knees while jumping upward','Simultaneously pull arms up and overhead in one continuous motion','Land softly on balls of feet with knees bent to absorb impact','Finish with arms fully extended overhead and body in stable squat position','Return to starting position by lowering arms and standing upright']::text[],ARRAY['Keep back straight throughout the entire movement to prevent injury during the pickup phase','Focus on explosive hip extension rather than using your back to generate power','Land with knees bent and weight evenly distributed to protect joints','Maintain core engagement throughout to support proper spinal alignment','Practice the movement slowly first before adding explosive speed']::text[],'full_body','{}'::text[],'barbell','full body','advanced',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8d3afa33-7191-4f69-a9f6-81b20f55dd38','Preacher Curl','preacher-curl','Starting position: Sit on a preacher bench with your chest against the inclined pad and arms extended over it, holding a barbell (or dumbbells) with a supinated grip (palms up). Execution: Flex your elbows to lift the barbell (or dumbbells) toward your shoulders, keeping your arms in contact with the bench throughout, then slowly lower back to the starting position with controlled movement.',ARRAY['Adjust the preacher bench height so the angled pad sits comfortably under your armpits when seated','Grip the barbell with an underhand grip, hands positioned shoulder-width apart','Press your chest firmly against the pad and plant your feet flat on the floor for stability','Keep your wrists straight and avoid locking out your elbows completely at the bottom of the movement','Curl the weight up smoothly by squeezing your biceps, pausing briefly at the top','Lower the barbell slowly and with control, maintaining tension throughout the descent']::text[],ARRAY['Keep your shoulders down and back throughout the movement to prevent compensation','Avoid using momentum or swinging the weight - focus on slow, controlled movements','Don''t fully extend your arms at the bottom as this can put excessive stress on the elbow joint','Maintain constant tension on the biceps by not resting the weight at the bottom of the movement','Use a weight that allows you to complete the full range of motion with proper form']::text[],'biceps','{}'::text[],'machine','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','339d8f8f-18e3-452a-ae66-f2b098382a84','Preacher Curl Dumbbell','preacher-curl-dumbbell','Starting position: Sit on a preacher bench with a dumbbell in one hand, resting your arm on the bench pad. Execution: Flex your elbow to lift the dumbbell toward your shoulder, then lower slowly.',ARRAY['Adjust the preacher bench height so the pad sits comfortably under your armpits when seated','Hold the dumbbell with an underhand grip, allowing your working arm to extend naturally over the angled pad','Keep your chest firmly pressed against the pad throughout the entire movement','Curl the weight up smoothly by squeezing your bicep, avoiding any jerking or swinging motions','Lower the dumbbell slowly and with control, stopping just short of full arm extension','Complete all repetitions on one arm before switching to the other side']::text[],ARRAY['Never fully lock out your elbow at the bottom of the movement to avoid hyperextension and joint stress','Focus on the eccentric (lowering) portion of the movement as this provides significant muscle-building benefits','Keep your wrist straight and strong throughout the exercise to prevent strain and maximize bicep engagement','Use a weight that allows you to maintain strict form rather than going too heavy and compromising technique','Position yourself so your armpit aligns with the top edge of the preacher pad for optimal biomechanics']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','34d8d81b-5883-4a90-bc74-4f1ec0cbce91','Preacher Curl EZ-Bar','preacher-curl-ez-bar','Starting position: Sit on a preacher bench with an EZ-bar in your hands, resting your arms on the bench pad. Execution: Flex your elbows to lift the EZ-bar toward your shoulders, then lower in a controlled manner.',ARRAY['Adjust the preacher bench height so the pad sits comfortably under your armpits when seated','Grip the EZ-bar with an underhand grip, hands positioned on the angled portions for wrist comfort','Press your chest firmly against the pad and plant your feet flat on the floor for stability','Begin with arms extended but maintain a slight bend in your elbows to protect the joint','Curl the weight up smoothly by squeezing your biceps, avoiding any swinging or momentum','Lower the weight slowly and under control, taking twice as long to lower as you did to lift']::text[],ARRAY['Keep your wrists straight and aligned with your forearms throughout the entire movement','Never fully lock out your elbows at the bottom position to prevent hyperextension injury','Focus on the negative portion of the lift by controlling the weight as you lower it','Avoid lifting your shoulders or leaning back during the curl to maintain proper form','Start with lighter weight than regular barbell curls since the preacher position provides less mechanical advantage']::text[],'biceps','{}'::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','554adc08-afea-40c8-bf33-d4276e2d73d9','Preacher Hammer Curl','preacher-hammer-curl','Starting position: Sit at a preacher bench with your chest against the pad, holding a dumbbell with a neutral (hammer) grip and your arm extended down the angled pad. Execution: Curl the dumbbell up by flexing your bicep while maintaining the neutral grip position, then slowly lower back to the starting position.',ARRAY['Position yourself at the preacher bench with your chest firmly against the pad and feet flat on the floor','Hold the dumbbell with a neutral grip (thumb up) and place your arm against the angled pad with a slight bend in your elbow','Slowly curl the weight up by contracting your bicep, keeping your wrist straight and grip neutral throughout','Squeeze your bicep at the top of the movement for a brief pause','Lower the dumbbell back down in a controlled manner, maintaining tension in the muscle','Stop just short of full arm extension to keep constant tension on the bicep']::text[],ARRAY['Keep your wrist in a neutral position throughout the entire movement to prevent strain','Maintain contact between your chest and the preacher pad to ensure proper positioning and support','Control the eccentric (lowering) portion of the movement to maximize muscle engagement and prevent injury','Avoid letting your elbow completely lock out at the bottom to maintain continuous tension on the bicep','Use a weight that allows you to maintain proper form throughout the entire range of motion']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','430ce933-5f38-44b9-8b43-810da4ec536e','Preacher Hammer Curl Dumbbells','preacher-hammer-curl-dumbbells','Starting position: Sit on a preacher bench with a dumbbell in each hand in hammer position (palms facing body). Execution: Flex elbows to lift dumbbells toward shoulders, then lower slowly.',ARRAY['Adjust the preacher bench seat height so your armpits align with the top of the angled pad','Hold dumbbells with a neutral grip, palms facing each other throughout the entire movement','Press your chest firmly against the pad and keep your feet flat on the floor for stability','Curl the weights up smoothly by contracting your biceps, stopping just short of full contraction','Lower the dumbbells slowly and under control, taking twice as long as the lifting phase','Maintain slight bend in your elbows at the bottom position to avoid hyperextension']::text[],ARRAY['Keep your wrists straight and aligned with your forearms to prevent injury','Focus on squeezing your biceps at the top of the movement for maximum muscle activation','Avoid using momentum or swinging the weights - maintain strict form throughout','The neutral grip targets the brachialis muscle more effectively than traditional curls','Control the eccentric (lowering) portion of the movement to maximize muscle growth']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e30e5898-057a-48f9-b667-010ed488c3ea','Prone W to lifts','prone-w-to-lifts-8ce672','Starting position: Lie face down (prone) on a mat with arms bent to form a ''W'' shape, elbows tucked toward the ribs and hands near shoulder level, forehead resting down. Execution: Squeeze the shoulder blades down and together to lift the arms and chest off the mat, holding briefly before lowering with control.',ARRAY['Lie prone on the mat with legs extended and forehead resting down.','Bend your elbows and position your arms to form a ''W'' shape with hands near shoulder height.','Retract and depress your shoulder blades as you lift your arms and upper chest off the floor.','Hold the top position briefly, focusing on the squeeze between your shoulder blades.','Lower back down slowly with control and repeat for the desired repetitions.']::text[],ARRAY['Keep your neck long and gaze down to avoid straining the cervical spine.','Initiate the movement from the shoulder blades rather than the arms.','Avoid over-arching the lower back by gently engaging your core and glutes.','Move slowly and controlled rather than using momentum.']::text[],'lower_traps',ARRAY['rotator_cuff','teres_minor','infraspinatus']::text[],'bodyweight','posture','beginner',ARRAY['strength','rehabilitation','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bf3b7d97-363c-45d7-91a3-43491c5a6f2a','Pseudo push ups','pseudo-push-ups','Starting position: Begin in a push-up position with hands placed wider than shoulder-width apart and positioned lower on the torso, closer to the ribcage area. Execution: Lower your body by bending the elbows while keeping them close to your sides, then press back up to the starting position.',ARRAY['Position hands wider than shoulders and lower on the torso near the ribcage area','Keep your body in a straight line from head to heels throughout the movement','Lower your chest toward the ground by bending your elbows, keeping them close to your sides','Press through your palms to return to the starting position','Maintain core engagement to prevent sagging hips','Control the descent and ascent with steady, deliberate movement']::text[],ARRAY['Hand placement is crucial - positioning hands lower and wider changes the muscle emphasis and difficulty','Keep elbows tucked close to your body rather than flaring them out wide','Maintain proper plank position throughout to protect your lower back','This variation places more emphasis on the triceps and requires greater strength than standard push-ups','Stop the movement if you cannot maintain proper form']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d0fe829c-d734-4429-bcc1-7ac15f2e92e4','Psoas stretch','psoas-stretch-a4009a','Starting position: Kneel on a mat in a half-kneeling position with the front foot flat and the back knee down, using a chair beside you for balance and support. Execution: Gently shift your hips forward while keeping the torso upright, feeling a stretch through the front of the back-leg hip, then hold and repeat on the other side.',ARRAY['Kneel in a half-kneeling stance with one foot forward and the opposite knee resting on the mat.','Hold the chair with one hand for balance and place the other hand on your front thigh.','Keep your torso tall and core engaged as you gently push your hips forward.','Hold the stretch, feeling tension along the front of the rear hip and thigh.','Ease back to the start and repeat for the prescribed duration, then switch sides.']::text[],ARRAY['Keep the torso upright and avoid arching the lower back.','Tuck the pelvis slightly to deepen the stretch through the hip flexor.','Move slowly and hold at a comfortable, non-painful range.']::text[],'hip_flexors',ARRAY['abs','adductors','erector_spinae']::text[],'chair','stretching','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a95a735d-411f-4edd-abd5-5f00e79874d4','Pull Up (Neutral Grip)','pull-up-neutral-grip-411a3a','Starting position: Hang from pull-up bar with palms facing each other, shoulder-width apart. Execution: Pull body up until chin clears bar, then lower with control.',ARRAY['Grip the bar with palms facing each other','Hang with arms fully extended and shoulders engaged','Pull your body up by driving elbows down','Rise until your chin clears the bar','Lower yourself slowly to starting position']::text[],ARRAY['Keep your core tight throughout the entire movement','Avoid swinging or using momentum to complete reps','Focus on pulling with your back muscles rather than arms','Maintain a slight forward lean to engage lats effectively','Don''t let shoulders roll forward at the bottom position']::text[],'back',ARRAY['biceps','forearms','rear_deltoids','middle_traps']::text[],'bodyweight','strength','intermediate','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7194a0b3-ce5e-4aab-81dc-b6b2354c916b','Pull Up overhand','pull-up-overhand-95eeae','Starting position: Grip the pull-up bar with an overhand (pronated) grip, hands slightly wider than shoulder width, arms fully extended, and body hanging with core braced. Execution: Pull your body up by driving your elbows down and back until your chin clears the bar, then lower under control to full extension.',ARRAY['Grasp the bar with an overhand grip slightly wider than shoulder width.','Hang with arms fully extended and engage your core and shoulder blades.','Pull your chest toward the bar by driving your elbows down and back.','Continue until your chin rises above the bar.','Lower yourself slowly and with control to the full hang position.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your core tight to avoid excessive swinging or kipping.','Initiate the movement by depressing and retracting the scapula.','Avoid using momentum; control both the up and down phases.','Do not shrug your shoulders toward your ears at the top.']::text[],'lats',ARRAY['biceps','forearms','rear_deltoids','core']::text[],'bodyweight','strength','intermediate',ARRAY['strength','calisthenics']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','874ef2ee-909f-44db-bd03-25ffd1e24a0d','Puppy pose','puppy-pose',null,ARRAY['Start on all fours with hips stacked over knees.','Walk your hands forward, lowering your chest toward the floor.','Keep your hips over your knees.','Rest your forehead on the mat and melt your chest down.']::text[],ARRAY['Keep your arms active and shoulder-width apart.','Do not let your elbows touch the floor.','Breathe into the stretch across your chest and shoulders.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c2410e7d-79c4-4593-82df-c42e8fd3450e','Push up burpees','push-up-burpees','Starting position: Stand tall with feet shoulder-width apart, arms at your sides. Execution: Drop into a squat, place hands on the floor, jump feet back into plank position, perform a push-up, jump feet back to squat, then explosively jump up with arms overhead.',ARRAY['Begin standing with feet shoulder-width apart and core engaged','Drop into a deep squat and place both hands firmly on the floor in front of you','Jump or step both feet back simultaneously into a high plank position','Lower your chest to the floor in a controlled push-up, keeping your body in a straight line','Push back up to plank position, then jump or step feet back toward your hands','Explosively jump straight up with arms reaching overhead, then land softly to complete one rep']::text[],ARRAY['Maintain a straight line from head to heels during the plank and push-up phases','Keep your core tight throughout the entire movement to protect your lower back','Land softly on both the jump back and jump up portions to reduce impact on joints','If you''re a beginner, step back and forward instead of jumping to reduce intensity','Focus on proper push-up form rather than speed - chest should touch the ground and arms should fully extend']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','206a3084-ab16-4115-b18e-93c6c44e6cc4','Push up Circles','push-up-circles-db60ec','Starting position: Begin in a high plank position with hands placed slightly wider than shoulder-width apart, arms extended, body forming a straight line from head to heels, and feet together. Execution: Lower your chest toward the floor while moving your torso in a circular motion, then press back up and continue the circular path with each repetition, alternating direction as desired.',ARRAY['Set up in a high plank with hands slightly wider than shoulders and body in a straight line.','Bend your elbows to lower your chest toward the mat while shifting your weight in a circular arc.','Continue the circular motion smoothly as you reach the bottom of the push up.','Press through your palms to push back up while completing the circle.','Keep your core braced and hips level throughout the movement.','Alternate the direction of the circles on subsequent reps.']::text[],ARRAY['Maintain a rigid, straight line from head to heels. Avoid sagging hips.','Keep elbows tracking at roughly 45 degrees to protect the shoulders.','Move in a controlled, deliberate circular path rather than rushing.','Keep your neck neutral by gazing slightly ahead of your hands.']::text[],'chest',ARRAY['front_deltoids','triceps','core']::text[],'bodyweight','strength','advanced',ARRAY['strength','calisthenics','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9c454a78-ff62-49a9-9879-127b48d6f2ea','Push up hold','push-up-hold','Starting position: Begin in a high plank position with hands placed slightly wider than shoulder-width apart, arms fully extended, and body forming a straight line from head to heels. Execution: Hold this static position while maintaining proper plank form and engaging the chest, shoulders, and core muscles throughout the duration.',ARRAY['Position hands flat on the ground slightly wider than shoulder-width apart with fingers spread for stability','Extend legs behind you and balance on your toes, creating a straight line from head to heels','Engage your core muscles and squeeze your glutes to maintain proper body alignment','Keep your arms fully extended and locked out at the elbows','Hold the position for the prescribed time while breathing steadily','Lower to your knees when you can no longer maintain proper form']::text[],ARRAY['Keep your body in a straight line throughout the hold - avoid sagging hips or raised buttocks','Distribute weight evenly between your hands and avoid letting wrists collapse inward','Engage your chest muscles by slightly pressing the ground away from you during the hold','Stop the exercise immediately if you experience wrist pain or cannot maintain proper form','Start with shorter hold times and gradually increase duration as strength improves']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['isometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e6348f43-b8ab-4e91-a211-0d766e35c9fe','Push up jack plank into toe touches','push-up-jack-plank-into-toe-touches','Starting position: Begin in a high plank position with hands placed shoulder-width apart, arms extended, and body in a straight line from head to heels. Execution: Jump both feet wide apart while maintaining the plank position, then jump feet back together, creating a jumping jack motion with the legs while keeping the upper body stable.',ARRAY['Start in a high plank position with hands directly under shoulders and body in a straight line','Engage your core and keep your back flat throughout the entire movement','Jump both feet out wide to the sides while maintaining the plank position','Immediately jump both feet back to the starting position','Keep your hands firmly planted and avoid letting your hips sag or pike up','Maintain steady breathing and controlled movements throughout the exercise']::text[],ARRAY['Keep your core engaged throughout to prevent lower back strain','Land softly on the balls of your feet to reduce impact','Maintain proper plank form even during the jumping motion','Keep your shoulders stable and avoid shifting weight forward or backward','Start slowly and increase speed only when you can maintain proper form']::text[],'chest','{}'::text[],'bodyweight','core',null,ARRAY['strength','plyometric','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1cecbe87-d29e-43af-bb44-5e1f409cd018','Push up to breakdancer','push-up-to-breakdancer','Starting position: Begin in a standard push-up position with hands placed slightly wider than shoulder-width apart, arms extended, and body in a straight line from head to heels. Execution: Perform a push-up by lowering your chest toward the ground, then as you press back up, shift your weight to one hand while lifting the opposite hand and sweeping the same-side leg under your body in a breakdancing freeze motion.',ARRAY['Start in a proper push-up position with core engaged and body aligned','Lower your chest toward the ground in a controlled push-up motion','Push back up explosively while preparing to shift your weight','As you reach the top, shift your weight to your left hand and lift your right hand','Sweep your right leg under your body while balancing on your left hand and right foot','Return to starting push-up position and repeat on the opposite side']::text[],ARRAY['Master standard push-ups before attempting this advanced variation','Keep your supporting arm strong and locked during the breakdancer transition','Engage your core throughout the entire movement to maintain balance and control','Start slowly and focus on smooth transitions rather than speed','Ensure adequate wrist warm-up as this exercise places significant stress on the supporting wrist']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','functional','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c809dc45-6a40-4060-a8ac-24f3c62358f7','Push up to toe touches','push-up-to-toe-touches','Starting position: Begin in a standard push-up position with hands placed slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Perform a push-up, then at the top position, pike your hips up and reach one hand toward the opposite foot, return to push-up position and repeat on the other side.',ARRAY['Start in a plank position with hands firmly planted and core engaged','Lower your chest toward the floor while maintaining a straight body line','Press back up to the starting push-up position with control','Pike your hips up toward the ceiling while keeping legs straight','Reach your right hand toward your left toe, then return to push-up position','Alternate reaching your left hand toward your right toe on the next repetition']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your lower back','Maintain proper push-up form before adding the toe touch component','Control the transition between push-up and pike positions to avoid momentum','If you cannot reach your toes, reach toward your shins or ankles instead','Focus on the quality of movement rather than speed to maximize muscle engagement']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','functional','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cbedc7e1-a023-41fb-938e-f62e0ffdb7d2','Push Up Wide','push-up-wide-d8f0f4','Starting position: Place hands wider than shoulder-width apart on the ground in plank position. Execution: Lower chest toward ground then push back up to starting position.',ARRAY['Position hands wider than shoulders in plank position','Keep body straight from head to heels','Lower chest toward ground until comfortable depth','Push through palms to return to starting position','Maintain tight core throughout the movement','Repeat for desired number of repetitions']::text[],ARRAY['Keep wrists aligned under hands to prevent injury','Engage core muscles to prevent lower back sagging','Wide hand placement targets chest muscles more than triceps','Stop lowering if you feel shoulder discomfort','Breathe in during descent and out during push phase']::text[],'chest','{}'::text[],'bodyweight',null,null,'{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b41a30a8-8a02-4101-a0a9-589efdbf786b','Push ups','push-ups','Starting position: Begin in a plank position with hands placed slightly wider than shoulder-width apart, arms fully extended, and body forming a straight line from head to heels. Execution: Lower your body by bending your elbows until your chest nearly touches the floor, then push back up to the starting position by straightening your arms.',ARRAY['Position hands flat on the floor slightly wider than shoulder-width with fingers spread for stability','Keep your core engaged and maintain a straight line from head to heels throughout the movement','Lower your body slowly and controlled until your chest is about 1-2 inches from the floor','Keep your elbows at a 45-degree angle to your body rather than flaring them straight out','Push through your palms to return to the starting position with full arm extension','Breathe in as you lower down and exhale as you push back up']::text[],ARRAY['Maintain proper body alignment by keeping your head in neutral position and avoiding sagging hips or raised buttocks','Start with modified versions like knee push-ups or incline push-ups if you cannot perform full push-ups with proper form','Focus on controlled movement rather than speed to maximize muscle engagement and reduce injury risk','Stop the exercise if you experience wrist pain and consider using push-up handles or making fists instead of flat palms','Progress gradually by increasing repetitions or trying more challenging variations once you can perform 15-20 perfect push-ups']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','61654261-7fa6-4bd5-9cf1-04ab8c638e4f','Push Ups','push-ups-5e29de','Starting position: Begin in a plank position with hands placed slightly wider than shoulder-width apart. Execution: Lower your body until your chest nearly touches the floor, then push back up to starting position.',ARRAY['Place hands on floor slightly wider than shoulders','Keep body straight from head to heels','Lower chest toward floor in controlled motion','Push through palms to return to start','Maintain tight core throughout movement']::text[],ARRAY['Keep your body in a straight line to prevent lower back strain','Your hands should be positioned under your chest, not your shoulders','Lower until your chest is 1-2 inches from the floor','Engage your core muscles throughout the entire movement','If too difficult, modify by dropping to your knees']::text[],'chest',ARRAY['front_deltoids','triceps','core']::text[],'bodyweight','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','284b839e-ec4c-4551-ba9d-afbf32b60330','Push ups to toe touches','push-ups-to-toe-touches','Starting position: Begin in a standard push-up position with hands placed slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Perform a push-up, then at the top position, shift your weight back and lift your hips up while reaching one hand toward the opposite toe, alternating sides with each repetition.',ARRAY['Start in a plank position with hands firmly planted on the ground and core engaged','Lower your body by bending your elbows until your chest nearly touches the floor','Push back up to the starting plank position with control','Shift your weight back and lift your hips up into a pike position','Reach your right hand toward your left toe while keeping legs as straight as possible','Return to plank position and repeat the sequence, alternating which hand reaches for the opposite toe']::text[],ARRAY['Maintain a tight core throughout the entire movement to protect your lower back','Keep your movements controlled and avoid rushing through the transitions','If you cannot reach your toes, reach as far as comfortable and gradually improve flexibility','Ensure proper push-up form before adding the toe touch component','Breathe steadily throughout the exercise, exhaling during the push-up phase']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','functional','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c5f49fc9-4673-4cae-8a12-6c5a4e4934a4','Push-Up (Decline)','push-up-decline-817504','Starting position: Place feet elevated on a bench or platform with hands on the ground in plank position. Execution: Lower chest toward ground then push back up.',ARRAY['Place feet on elevated surface, hands on ground','Position hands slightly wider than shoulder width','Lower chest toward ground with controlled movement','Push through palms to return to starting position','Keep body in straight line throughout movement','Maintain core engagement during entire exercise']::text[],ARRAY['Keep core tight to prevent lower back sagging','The higher the elevation, the more challenging the exercise becomes','Hands should be positioned directly under shoulders for optimal alignment','Control the descent to maximize muscle activation and prevent injury']::text[],'bodyweight',ARRAY['triceps_long_head','front_deltoids','abs']::text[],'bodyweight','strength','intermediate',ARRAY['calisthenics','strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','67f7b774-4b0f-4252-b5df-2555e9f5d0c8','Push-Up Wide','push-up-wide','Starting position: Begin in a high plank position with hands placed wider than shoulder-width apart, fingers pointing forward, and body forming a straight line from head to heels. Execution: Bend the elbows to lower the chest toward the floor, keeping the core braced, then press through the palms to extend the arms and return to the starting position.',ARRAY['Hands wider than shoulder-width','Lower chest toward floor','Elbows flare out more','Push up to start']::text[],ARRAY['More chest emphasis','Don''t go too wide (shoulder strain)','Keep body straight','Control the movement','Harder on shoulders']::text[],'chest',ARRAY['front_deltoids','triceps','core']::text[],'bodyweight','push','intermediate',ARRAY['strength','calisthenics']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9d46942e-53df-455c-a996-8936145ab8d2','Push-Ups - Close Triceps Position (Diamond push ups)','push-ups-close-triceps-position-diamond-push-ups','Starting position: Begin in a plank position with hands placed close together directly under your chest, forming a diamond or triangle shape with your thumbs and index fingers touching. Execution: Lower your body until your chest nearly touches your hands, then press back up to the starting position while maintaining the diamond hand formation.',ARRAY['Position hands directly under your chest with thumbs and index fingers touching to form a diamond shape','Keep your body in a straight line from head to heels, engaging your core throughout the movement','Lower your body slowly and controlled until your chest nearly touches your hands','Press through your palms to push your body back to the starting position','Maintain the diamond hand position throughout the entire range of motion','Keep your elbows close to your body as you move up and down']::text[],ARRAY['This variation primarily targets the triceps while still engaging the chest and shoulders','Keep elbows tucked close to your sides rather than flaring them out wide','If too difficult, modify by performing on your knees or elevating your hands on a bench','Maintain a rigid plank position throughout to protect your lower back','Focus on controlled movement rather than speed for maximum muscle activation']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c6453fa8-f869-43ed-8314-9fc093dc7351','Push-Ups (Decline)','push-up-decline-1394cb','Starting position: Place feet elevated on bench or surface, hands on floor in plank position. Execution: Lower chest toward floor then push back up.',ARRAY['Position hands shoulder-width apart on floor','Place feet elevated on bench behind you','Lower chest toward floor with controlled movement','Push through palms to return to start','Keep body in straight line throughout movement']::text[],ARRAY['Keep core engaged to prevent lower back sagging','Maintain neutral head position looking slightly forward','Control the descent to avoid dropping too quickly','Ensure hands are directly under shoulders for proper alignment','Stop lowering when chest nearly touches the floor']::text[],'chest','{}'::text[],'bodyweight',null,null,'{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f860eed0-1645-401e-bfe0-ddbc4ba2df90','Pushups','pushups','Starting position: Begin in a plank position with hands placed slightly wider than shoulder-width apart, arms fully extended, and body forming a straight line from head to heels. Execution: Lower your body by bending your elbows until your chest nearly touches the floor, then push back up to the starting position by straightening your arms.',ARRAY['Position hands flat on the floor slightly wider than shoulder-width with fingers pointing forward','Keep your body in a straight line from head to heels, engaging your core throughout the movement','Lower your body slowly and controlled until your chest is about 2-3 inches from the floor','Keep your elbows at a 45-degree angle from your torso as you descend','Push through your palms to return to the starting position with full arm extension','Maintain steady breathing, inhaling on the way down and exhaling as you push up']::text[],ARRAY['Keep your core tight and avoid letting your hips sag or pike up during the movement','Maintain a neutral neck position by looking at the floor about 6 inches in front of your hands','If standard pushups are too difficult, modify by performing them on your knees or against an elevated surface','Focus on controlled movement rather than speed to maximize muscle engagement and prevent injury','Ensure full range of motion by going down until your chest nearly touches the floor and pushing up to complete arm extension']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','396dee3e-b0b6-409b-a331-47d3bd121ac8','Pyramid pose (left)','pyramid-pose-left',null,ARRAY['Stand with one foot stepped back about 3 feet.','Square your hips toward the front of the mat.','Fold forward over your front leg with a flat back.','Place your hands on the floor or on blocks beside your front foot.']::text[],ARRAY['Keep both legs straight with a micro-bend in the front knee.','Hinge from the hips.','Press evenly through both feet.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
