insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cc3a2bb8-efcf-440d-9357-887ce0b04346','Quadriceps Roll','quadriceps-roll-72debb','Starting position: Lie face down in a forearm plank with a foam roller positioned under the front of your thighs. Execution: Using your forearms and elbows to control movement, roll your body forward and backward so the roller travels along your quadriceps from just above the knees to the hip region, pausing on tender spots.',ARRAY['Set up in a forearm plank with the foam roller placed beneath the front of your thighs.','Support your upper body on your forearms and keep your core engaged.','Slowly drive with your arms to roll the foam roller down toward your knees.','Reverse the motion, rolling back up toward your hip flexors.','Pause and hold on any tight or tender spots for several seconds.','Continue rolling smoothly for the desired duration.']::text[],ARRAY['Keep your core braced to avoid sagging or arching the lower back.','Move slowly and controlled, roughly one inch per second.','Breathe steadily and relax into tender areas rather than tensing up.','Avoid rolling directly over the knee joint.']::text[],'quadriceps',ARRAY['hip_flexors','core','shoulders']::text[],'foam roller','mobility','beginner',ARRAY['mobility','rehabilitation']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a2ad1f3d-ac82-4d67-915c-6bd4f83e3813','Rack Pull','rack-pull-f95e8b','Starting position: Stand with feet hip-width apart, barbell positioned on rack pins at knee height. Execution: Lift the barbell by extending hips and knees simultaneously until standing upright.',ARRAY['Set barbell on rack pins at knee height','Stand with feet hip-width apart behind the bar','Grip the bar with overhand grip outside legs','Engage core and lift chest with neutral spine','Drive through heels while extending hips and knees','Lower bar back to rack pins with control']::text[],ARRAY['Keep the bar close to your body throughout the entire movement','Maintain a neutral spine and avoid rounding your back','Drive through your heels rather than lifting on your toes','Start with lighter weight than your regular deadlift to learn the movement']::text[],'back',ARRAY['glutes','hamstrings','forearms','quads']::text[],'barbell','strength','intermediate','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','24846377-a8c6-4955-86e6-00528b6e2b31','Rack Pulls','rack-pulls','Starting position: Stand with a barbell resting on a rack at knee height. Execution: Lift the bar until you are fully upright while keeping your back straight, then lower the bar back to the rack.',ARRAY['Set the safety pins or rack position at knee to mid-thigh height depending on your mobility and strength level','Position your feet hip-width apart with the bar over the middle of your feet','Grip the bar with hands just outside your legs, keeping your arms straight and shoulders directly over the bar','Engage your core and maintain a neutral spine throughout the entire movement','Drive through your heels and pull the bar up by extending your hips and squeezing your glutes at the top','Lower the bar back to the pins in a controlled manner, maintaining proper form throughout the descent']::text[],ARRAY['Keep your shoulders pulled back and down throughout the movement to protect your spine and maximize back engagement','Focus on hip hinge movement rather than squatting to properly target the posterior chain muscles','Use a weight that allows you to maintain perfect form as rack pulls can handle heavier loads than conventional deadlifts','Avoid hyperextending your back at the top of the movement - simply stand tall with neutral spine alignment','Start with pins at knee height if you''re new to the exercise and gradually lower the starting position as mobility improves']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','843c04e2-6344-48ad-8641-0321a60dbb63','Reclined butterfly','reclined-butterfly',null,ARRAY['Lie on your back and bring the soles of your feet together.','Let your knees fall open to the sides.','Rest your arms at your sides with palms up.','Close your eyes and relax for several minutes.']::text[],ARRAY['Place pillows or blocks under your knees for support.','Let gravity do the work - do not force the stretch.','This is a restorative pose - focus on deep breathing.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1523b6fd-d8b9-4406-b188-5d1545dd0cb2','Reclined pigeon pose (left)','reclined-pigeon-pose-left',null,ARRAY['Lie on your back with knees bent and feet flat.','Cross one ankle over the opposite knee.','Thread your hands behind the supporting thigh.','Gently pull the thigh toward your chest.']::text[],ARRAY['Keep your head and shoulders on the floor.','Flex the crossed foot to protect the knee.','Breathe deeply into the hip stretch.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
