insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1f636f46-0bc3-417d-a3ac-93108ecc26ec','Reclined windshield wipers','reclined-windshield-wipers',null,ARRAY['Lie on your back with knees bent and feet flat, wider than hip-width.','Extend your arms out to the sides.','Let both knees drop to one side, then the other.','Move slowly with your breath.']::text[],ARRAY['Keep both shoulders on the floor.','Move gently and do not force the knees down.','This is a gentle spinal twist and hip release.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ad8f28d1-cf33-4e80-9686-0742404566e3','Resistance Band Row','resistance-band-row-fc3cb2','Starting position: Sit tall on a mat with legs extended straight in front of you, looping the resistance band around the soles of your feet and holding an end in each hand with arms extended forward. Execution: Pull the band toward your torso by driving your elbows back and squeezing your shoulder blades together, then slowly return to the start under control.',ARRAY['Sit upright with legs extended and loop the band securely around your feet.','Grip the band ends with arms straight and a slight tension already present.','Row by pulling your elbows back close to your ribs, drawing your hands toward your waist.','Squeeze your shoulder blades together at the end of the pull.','Slowly extend your arms back to the starting position, maintaining tension.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your spine tall and chest lifted throughout the movement.','Lead with the elbows and avoid shrugging your shoulders up toward your ears.','Control the return phase rather than letting the band snap back.','Engage your core to keep your torso stable and avoid rocking.']::text[],'back',ARRAY['biceps','rear_deltoids','forearms']::text[],'band','strength','beginner',ARRAY['strength','rehabilitation','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7cfe78ab-8d77-4142-8199-51d3f48b9430','Reverse Cable Preacher Curl','reverse-cable-preacher-curl','Starting position: Stand facing a low pulley with an overhand grip attached to the pulley. Execution: Flex your elbows to lift the grip toward your shoulders, then slowly lower.',ARRAY['Set the cable pulley to its lowest position and attach a straight bar or EZ-curl bar','Adjust the preacher bench so the angled pad supports your forearms comfortably when seated','Grip the bar with an overhand grip, hands shoulder-width apart, and rest your forearms flat against the pad','Keep your chest up and core engaged while maintaining contact between your upper arms and the pad throughout the movement','Curl the weight up by contracting your forearms and wrists, focusing on the squeeze at the top','Lower the weight slowly and under control, feeling the stretch in your forearms at the bottom']::text[],ARRAY['Use a light to moderate weight as forearms are smaller muscles that fatigue quickly','Focus on controlled movements rather than speed to maximize muscle engagement and prevent injury','Keep your wrists in a neutral position throughout the exercise to avoid strain','Maintain constant tension on the forearms by not allowing the weight stack to rest between repetitions','Stop the exercise if you experience any sharp pain in your wrists or elbows']::text[],'forearms','{}'::text[],'cable','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f77e760b-7f45-45b2-a34b-e8e8b3b1ab45','Reverse Fly','reverse-fly-806f37','Starting position: Stand with feet hip-width apart, knees slightly bent, and hinge forward at the hips with a flat back while holding a dumbbell in each hand hanging beneath the chest. Execution: Raise both arms out to the sides in a wide arc until they reach shoulder height, squeezing the shoulder blades together, then lower under control back to the start.',ARRAY['Hinge forward at the hips keeping your back flat and knees soft, letting the dumbbells hang below your chest.','Maintain a slight bend in the elbows throughout the movement.','Raise the dumbbells out to the sides until arms are parallel to the floor.','Squeeze your shoulder blades together at the top of the movement.','Lower the weights slowly and with control back to the starting position.','Repeat for the prescribed number of repetitions.']::text[],ARRAY['Keep your spine neutral and avoid rounding the lower back.','Lead with the elbows and avoid using momentum to swing the weights.','Focus on squeezing the rear delts and upper back, not the arms.','Keep the neck long and gaze slightly forward or down.']::text[],'rear_deltoids',ARRAY['erector_spinae','teres_major','forearms']::text[],'dumbbell','strength','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c265b4e3-ab8d-4141-9d7e-462e2c329d1b','Reverse fly plank to plank hop','reverse-fly-plank-to-plank-hop','Starting position: Begin in a plank position with hands planted firmly on the ground, body in a straight line from head to heels. Execution: Lift one hand off the ground and sweep it out to the side in a reverse fly motion, then return to plank and perform a small hop or adjustment with the feet.',ARRAY['Start in a high plank position with hands directly under shoulders and body in a straight line','Engage your core and maintain steady breathing throughout the movement','Lift one hand off the ground and sweep it out to the side, opening up the chest','Return the hand back to starting plank position with control','Perform a small hop or step adjustment with your feet while maintaining plank form','Repeat the sequence, alternating arms or maintaining the same pattern']::text[],ARRAY['Keep your core engaged throughout to prevent sagging hips or arching back','Maintain proper plank alignment even when lifting one hand off the ground','Control the reverse fly movement - don''t let momentum take over','Keep the supporting arm strong and stable when performing the single-arm movement','Land softly during any hopping movements to protect joints']::text[],'shoulders','{}'::text[],'bodyweight','core',null,ARRAY['strength','plyometric','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e27c74a9-69aa-4b0f-aa5f-1c675d5fe26e','Reverse grip bent over rows','reverse-grip-bent-over-rows','Starting position: Stand with feet hip-width apart, hinge at the hips to lean forward while maintaining a straight back, arms extended downward with palms facing forward in a reverse grip position. Execution: Pull your elbows back and up toward your ribs while squeezing your shoulder blades together, then slowly return to the starting position with control.',ARRAY['Hinge at your hips and lean forward approximately 45 degrees while keeping your chest up and core engaged','Position your arms straight down with palms facing forward, creating the reverse grip hand position','Initiate the movement by pulling your elbows back toward your ribs while squeezing your shoulder blades together','Focus on lifting your chest and pulling your shoulder blades down and back throughout the movement','Hold the top position briefly before slowly returning to the starting position','Maintain the hip hinge position and avoid rounding your back throughout the entire exercise']::text[],ARRAY['Keep your core engaged throughout the movement to protect your lower back and maintain proper posture','Focus on squeezing your shoulder blades together rather than just moving your arms to maximize back muscle activation','Control the tempo with a slower eccentric phase when returning to starting position for better muscle development','Avoid using momentum or swinging motions as this reduces effectiveness and increases injury risk','Ensure your neck remains in neutral alignment with your spine rather than craning it upward']::text[],'back','{}'::text[],'dumbbell','back','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6b58c0da-6795-4103-bbed-6c3e540c1c16','Reverse Grip Skull Crusher','reverse-grip-skull-crusher','Starting position: Lie on a flat bench with a barbell in hands using a supinated grip (palms facing up). Execution: Lower the bar toward your forehead by bending your elbows, then extend your arms to return to the starting position.',ARRAY['Lie flat on a bench with feet firmly planted on the floor for stability','Grip the barbell with an underhand grip, hands positioned shoulder-width apart','Start with arms fully extended above your chest, keeping your upper arms stationary throughout the movement','Slowly lower the barbell by bending at the elbows until it nearly touches your forehead','Press the weight back up by extending your elbows to return to the starting position','Maintain control of the weight throughout both the lowering and lifting phases']::text[],ARRAY['Keep your upper arms perpendicular to the floor and avoid letting them drift backward during the movement','Use a controlled tempo to maximize muscle tension and reduce risk of injury','Start with lighter weight than regular skull crushers as the reverse grip can feel awkward initially','Keep your wrists straight and maintain a firm grip to prevent the barbell from rolling','Focus on feeling the stretch in your triceps at the bottom position without going too low']::text[],'triceps','{}'::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','55df26c1-83f4-439a-89be-22c156a3e118','Reverse Lunge into Knee Drive','reverse-lunge-into-knee-drive','Starting position: Stand tall with feet hip-width apart, arms at your sides or hands on your hips. Execution: Step one foot back into a reverse lunge, then drive the back knee up toward your chest as you return to standing, alternating legs or completing all reps on one side before switching.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Step your right foot back 2-3 feet, lowering into a lunge until both knees are bent at 90 degrees','Keep your front knee aligned over your ankle and avoid letting it cave inward','Push through your front heel to stand up while simultaneously driving your back knee up toward your chest','Control the knee drive movement and pause briefly at the top before returning to starting position','Complete all repetitions on one side before switching legs, or alternate legs with each rep']::text[],ARRAY['Keep your torso upright throughout the entire movement to maintain proper alignment and maximize quad activation','Control the tempo on both the lunge descent and knee drive to improve balance and muscle engagement','Ensure your front knee tracks in line with your toes during the lunge portion to prevent knee injury','Focus on driving through your front heel when returning to standing to properly activate the quadriceps','Land softly when stepping back into the lunge to reduce impact on your joints']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','808799af-013a-4f71-94e7-3fdea59b9ecf','Reverse lunge to knee drive','reverse-lunge-to-knee-drive','Starting position: Stand tall with feet hip-width apart, arms at your sides or hands on your hips. Execution: Step one foot backward into a reverse lunge, then drive the back knee up toward your chest as you return to standing, alternating legs with each repetition.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Step your right foot back 2-3 feet, lowering your hips until both knees are bent at approximately 90 degrees','Keep your front knee aligned over your ankle and avoid letting it drift inward','Push through your front heel to return to standing while simultaneously driving your back knee up toward your chest','Lower the raised leg back to starting position and repeat the movement with the opposite leg','Maintain an upright torso throughout the entire movement sequence']::text[],ARRAY['Keep most of your weight on your front leg during the lunge portion to maximize quad activation','Drive the knee up with control rather than momentum to maintain balance and proper form','Ensure your front knee tracks in line with your toes and doesn''t cave inward during the lunge','Focus on a smooth transition from the lunge to the knee drive without pausing between movements','Land softly when stepping back into the lunge to reduce impact on your joints']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f8a04b5e-b762-48eb-8528-de28f5c321b7','Reverse Lunge with Kettlebell','reverse-lunge-with-kettlebell-d80193','Starting position: Stand tall holding a kettlebell in one hand at your side, feet hip-width apart, chest up and core engaged. Execution: Step one leg back into a lunge, lowering until both knees form roughly 90-degree angles, then drive through the front heel to return to standing.',ARRAY['Stand upright holding the kettlebell in one hand at arm''s length beside your hip.','Take a controlled step backward with one leg, keeping your torso upright.','Lower your body until the front thigh is parallel to the floor and the back knee hovers just above the ground.','Press firmly through the front heel to drive back up to the starting position.','Complete all reps on one side, then switch the working leg.','Maintain a braced core throughout to stabilize the weighted side.']::text[],ARRAY['Keep your front knee tracking over your toes, not collapsing inward.','Maintain an upright chest and neutral spine throughout the movement.','Control the descent rather than dropping into the bottom position.','Keep weight balanced through the front heel to protect the knee.']::text[],'quads',ARRAY['glute_max','hamstrings','erector_spinae','forearms']::text[],'kettlebell','strength','intermediate',ARRAY['strength','functional','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cea24bde-a9ce-4de1-93e6-3c019e1520d2','Reverse Lunges','reverse-lunges-bd157f','Starting position: Stand tall with feet hip-width apart, arms at sides. Execution: Step one foot backward into a lunge, lower until both knees bend at 90 degrees, then return to start.',ARRAY['Stand with feet hip-width apart and core engaged','Step left foot backward approximately two to three feet','Lower your body until both knees form 90-degree angles','Push through right heel to return to starting position','Repeat movement alternating legs or complete set per side']::text[],ARRAY['Keep your front knee aligned over your ankle, not past your toes','Maintain an upright torso throughout the movement to protect your lower back','Lower your back knee toward the ground without letting it touch the floor','Push through your front heel when returning to the starting position for maximum glute activation']::text[],'bodyweight',ARRAY['glute_max','hamstrings','calves','core']::text[],'bodyweight','strength','beginner',ARRAY['calisthenics','strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','27114339-579a-4a81-a673-52126b81f475','Reverse Plank','reverse-plank-0b31f8','Starting position: Sit on the floor with your legs extended, feet together, and place your hands flat on the ground behind your hips with fingers pointing forward or slightly outward. Execution: Press through your palms and heels to lift your hips upward until your body forms a straight line from head to heels, squeezing your glutes and bracing your core, then hold before lowering back down.',ARRAY['Sit on the floor with legs extended and hands placed behind your hips, fingers pointing toward your feet.','Press firmly through your palms and heels to drive your hips up off the floor.','Raise your hips until your torso and legs form a straight line, squeezing your glutes at the top.','Keep your chest open and gaze forward or slightly up, avoiding neck strain.','Hold the top position while bracing your core, then lower under control back to the start.']::text[],ARRAY['Keep your body in a straight line without letting your hips sag.','Press the shoulder blades down and back to protect the shoulder joints.','Engage the glutes and core rather than relying only on the arms.','Avoid dropping your head back excessively; keep the neck neutral.']::text[],'glutes',ARRAY['rear_deltoids','lower_back','abs']::text[],'bodyweight','core','beginner',ARRAY['strength','isometric','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','90a03a51-07e2-4acd-b893-d5c58a273587','Reverse Preacher Curl','reverse-preacher-curl','Starting position: Stand behind a preacher bench holding a barbell with an overhand grip, forearms resting on the angled pad. Execution: Curl the barbell upward by flexing your wrists and forearms, then slowly lower back to the starting position.',ARRAY['Position yourself standing behind the preacher bench with your chest against the back pad','Place your forearms flat on the angled pad with your wrists just over the edge','Grip the barbell with an overhand grip, hands shoulder-width apart','Keep your forearms pressed against the pad throughout the entire movement','Curl the weight up by flexing your wrists and squeezing your forearms','Lower the weight slowly and under control back to the starting position']::text[],ARRAY['Keep your forearms in constant contact with the preacher pad for stability','Use a controlled tempo, especially on the lowering phase to maximize muscle engagement','Start with lighter weight as this exercise intensely targets the smaller forearm muscles','Maintain proper wrist alignment to avoid strain or injury','Focus on the squeeze at the top of the movement for maximum contraction']::text[],'forearms','{}'::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','07cd2836-405f-4b66-9b80-2d69b1fabb6a','Reverse push ups','reverse-push-ups-c642d0','Starting position: Begin in a high plank position with hands placed directly under the shoulders, arms fully extended, and legs straight behind you with feet together resting on the toes. Execution: Maintain a straight line from head to heels while engaging the core, then perform controlled push-up movements by bending and extending the arms while keeping the body rigid.',ARRAY['Assume a high plank with hands under shoulders and body in a straight line.','Engage your core and glutes to keep the spine neutral.','Bend the elbows to lower the chest toward the floor in a controlled manner.','Press through the palms to push back up to the starting position.','Keep the head in line with the spine throughout the movement.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your body in a straight line from head to heels, avoiding sagging hips.','Position hands directly beneath the shoulders for optimal support.','Control the descent rather than dropping quickly.','Breathe out as you push up and in as you lower.']::text[],'chest',ARRAY['triceps_long_head','front_deltoids','obliques']::text[],'bodyweight','strength','beginner',ARRAY['strength','calisthenics','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4f5e0bcb-7424-4d6b-b837-5c3eda01c15c','Reverse Snow Angels','reverse-snow-angels-fb3efa','Starting position: Lie face down (prone) on the floor with your legs extended, forehead down, and arms stretched overhead close to the floor. Execution: Sweep your arms out to the sides and down toward your hips in a wide arc, keeping them just off the floor, then reverse the motion back overhead, mimicking a snow angel while squeezing the shoulder blades.',ARRAY['Lie prone with arms extended overhead and legs straight, keeping your neck neutral.','Lift your arms slightly off the floor and sweep them out to the sides in a wide arc.','Continue moving your arms down toward your hips, squeezing your shoulder blades together.','Reverse the movement, sweeping your arms back overhead in a controlled arc.','Keep your arms hovering just above the floor throughout the entire range.','Repeat for the desired number of repetitions with steady, controlled tempo.']::text[],ARRAY['Keep your neck long and forehead pointing down to avoid straining the cervical spine.','Move slowly and maintain arm elevation off the floor for constant tension.','Focus on retracting and depressing the shoulder blades rather than using momentum.','Keep your core engaged and hips pressed into the floor to protect the lower back.']::text[],'lower_traps',ARRAY['rotator_cuff','glutes','spinal_erectors']::text[],'bodyweight','strength','beginner',ARRAY['strength','mobility','rehabilitation']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','daeabed2-d92e-4de2-87c0-138bcc0009b4','Reverse Step Up','reverse-step-up-afacc9','Starting position: Stand tall in front of a low step or box with feet hip-width apart, hands on your hips, and core engaged. Execution: Place one foot on top of the box, then drive through that leg to lift your body up onto the step, control the movement, and step back down under control before repeating.',ARRAY['Stand facing the step with feet hip-width apart and hands on hips.','Place one foot firmly on top of the box, keeping the knee tracking over the toes.','Drive through the elevated foot''s heel to lift your body up onto the step.','Lower back down with control to the starting position on the same leg.','Complete the desired reps, then switch legs and repeat.']::text[],ARRAY['Keep your chest up and torso only slightly forward, avoiding excessive lean.','Push through the heel of the stepping leg to engage the glutes.','Control the descent rather than dropping down quickly.','Ensure the knee stays aligned with the toes throughout the movement.']::text[],'quads',ARRAY['glute_max','hamstrings','calves']::text[],'box','strength','beginner',ARRAY['strength','functional','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','87cb06b9-6563-4676-b796-b02f68af48b5','Reverse warrior (left)','reverse-warrior-left',null,ARRAY['From Warrior II, flip your front palm up.','Inhale and reach your front arm up and back overhead.','Let your back hand slide down the back leg.','Open your chest toward the ceiling.']::text[],ARRAY['Keep your front knee bent at 90 degrees.','Do not dump weight into the back hand.','Create a long side-body stretch.']::text[],'quads','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
