insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c0320e6b-e7e0-4cef-ba0d-dd5e66b2ebf1','Revolved triangle pose (left)','revolved-triangle-pose-left',null,ARRAY['From a standing split stance, square your hips to the front.','Hinge forward and place the opposite hand on the floor or a block beside your front foot.','Twist your torso open and extend the top arm toward the ceiling.','Gaze up at your top hand.']::text[],ARRAY['Keep both legs straight.','Square your hips before twisting.','Use a block if you cannot reach the floor.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6347356d-6248-444f-92b2-47de72d5f96e','Revolved triangle pose (right)','revolved-triangle-pose-right',null,ARRAY['From a standing split stance, square your hips to the front.','Hinge forward and place the opposite hand on the floor or a block beside your front foot.','Twist your torso open and extend the top arm toward the ceiling.','Gaze up at your top hand.']::text[],ARRAY['Keep both legs straight.','Square your hips before twisting.','Use a block if you cannot reach the floor.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','73097e75-dc6b-4be4-bf4a-b3f176d8ff10','Rocking horse push up into explosive jump','rocking-horse-push-up-into-explosive-jump','Starting position: Begin in a standard push-up position with hands placed slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Perform a push-up while simultaneously rocking your body weight forward and backward, then explosively push up from the bottom position and jump your feet forward toward your hands before returning to starting position.',ARRAY['Start in a strong plank position with core engaged and hands firmly planted on the ground','Lower into a push-up while shifting your weight slightly forward and backward in a rocking motion','At the bottom of the push-up, explosively press through your hands to lift your upper body','As you push up, simultaneously jump both feet forward toward your hands in one fluid motion','Step or jump your feet back to the starting push-up position','Maintain control throughout the entire movement and reset your form before the next repetition']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your lower back and maintain proper form','Focus on the explosive push-up portion to generate enough power for the jump transition','Land softly on the balls of your feet when jumping forward to reduce impact on joints','Ensure your hands remain firmly planted during the rocking motion to maintain stability','Start with slower movements and build up speed and explosiveness as you master the technique']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','plyometric','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9fb9d7f3-6833-4f8d-97ce-f487f8fd5eca','Romanian Deadlift','romanian-deadlift','Starting position: Stand upright holding a barbell with an overhand grip, arms extended, feet hip-width apart. Execution: Hinge at the hips by pushing your hips back and lowering the barbell while keeping your back straight, then return to the starting position by driving your hips forward.',ARRAY['Stand with feet hip-width apart and grip the barbell with both hands using an overhand grip','Keep your shoulders back and chest up while maintaining a neutral spine throughout the movement','Initiate the movement by pushing your hips back and hinging at the hips, not the knees','Lower the barbell by keeping it close to your body while maintaining straight arms','Feel the stretch in your hamstrings as you lower the weight with control','Drive your hips forward to return to the starting position, squeezing your glutes at the top']::text[],ARRAY['Keep the barbell close to your body throughout the entire range of motion','Focus on hip hinge movement rather than knee bending to properly target the hamstrings','Maintain a neutral spine and avoid rounding your back during the descent','Control the weight on both the lowering and lifting phases of the movement','Stop the descent when you feel a good stretch in your hamstrings, typically around mid-shin level']::text[],'hamstrings','{}'::text[],'barbell','legs',null,ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3ed1db96-1767-4ce2-a245-56b4a2967419','Run','run',null,ARRAY['Sit in machine, select appropriate weight','Grip handles, position pads against chest/shoulders','Contract abs to crunch forward','Squeeze at bottom','Return slowly with control']::text[],ARRAY['Don''t pull with arms','Focus on ab contraction','Don''t go too heavy (neck strain risk)','Controlled movement throughout','Exhale as you crunch']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['cardio']::text[],false,false,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4c257ac2-d310-40aa-8797-33d138519135','Run in place','run-in-place','Starting position: Stand upright with feet hip-width apart, arms at your sides, and core engaged. Execution: Lift your knees alternately while pumping your arms in a natural running motion, maintaining the running rhythm without moving forward.',ARRAY['Stand tall with your feet hip-width apart and arms relaxed at your sides','Begin by lifting your right knee up toward your chest while simultaneously swinging your left arm forward','Lower your right foot back down while lifting your left knee up and swinging your right arm forward','Continue alternating legs in a smooth, rhythmic motion while pumping your arms naturally','Land softly on the balls of your feet with each step to minimize impact','Maintain an upright posture throughout the movement with your core engaged']::text[],ARRAY['Keep your knees lifting to at least hip height for maximum effectiveness','Land softly on the balls of your feet rather than your heels to reduce joint impact','Maintain a steady breathing pattern and avoid holding your breath during the exercise','Keep your core engaged and avoid leaning too far forward or backward','Start at a moderate pace and gradually increase intensity as your endurance improves']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4088ec8b-252e-4444-86ef-9fa59010e9fd','Russian Twist','russian-twist-b032b0','Starting position: Sit with knees bent, feet lifted, leaning back slightly. Execution: Rotate torso side to side while maintaining the lean.',ARRAY['Sit with knees bent and feet off ground','Lean back to create V-shape with torso','Keep chest up and core engaged throughout','Rotate torso left and right in controlled motion','Touch hands to ground beside hips each rotation','Maintain lifted feet position during entire movement']::text[],ARRAY['Keep your core constantly engaged to protect the lower back','Avoid pulling on your neck or using momentum to rotate','Focus on controlled rotation rather than speed','Keep your chest lifted and avoid rounding your shoulders','Breathe steadily throughout the rotational movement']::text[],'abs',ARRAY['internal_obliques','external_obliques','lower_back']::text[],'bodyweight','core','intermediate','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1328cea8-8e8b-4a64-9f6a-10d8031b2f27','Russian Twist - no weight','russian-twist-no-weight',null,ARRAY['Sit on the floor with knees bent and feet flat on the ground, leaning back slightly to engage your core','Lift your feet off the ground a few inches, balancing on your glutes while maintaining the lean-back position','Clasp your hands together in front of your chest or interlace your fingers','Rotate your torso to the right side, bringing your hands toward the floor beside your hip','Return to center then rotate to the left side, bringing your hands toward the floor beside your left hip','Continue alternating sides in a controlled, rhythmic motion']::text[],ARRAY['Keep your chest up and shoulders back throughout the movement to maintain proper posture','Focus on rotating from your core rather than just moving your arms','Maintain steady breathing and avoid holding your breath during the exercise','Keep your feet elevated throughout the set to maintain constant core engagement','Start with shorter sets and gradually increase duration as your core strength improves']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','75649a91-b901-4140-ab80-3052a3afed27','Russian Twist - Weighted','russian-twist-weighted','Starting position: Sit on the floor with knees bent, feet flat, leaning back to balance on your sit bones while holding a weight or medicine ball at chest level. Execution: Rotate your torso from side to side, touching the weight to the floor beside each hip while maintaining the balanced position.',ARRAY['Sit with knees bent and feet flat on the floor, holding your chosen weight with both hands at chest level','Lean back slightly to balance on your sit bones, engaging your core muscles to maintain stability','Lift your feet off the ground if comfortable, or keep them planted for additional stability','Rotate your torso to the right, bringing the weight toward the floor beside your right hip','Return to center, then rotate to the left, touching the weight beside your left hip','Continue alternating sides in a controlled, rhythmic motion while maintaining your balanced position']::text[],ARRAY['Keep your back straight and avoid rounding your spine during the rotation','Focus on rotating from your core rather than just moving your arms','Start with a lighter weight to master the movement pattern before progressing to heavier loads','Maintain steady breathing throughout the exercise, exhaling during each twist','Keep your chest up and shoulders back to prevent hunching forward']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','10affa59-53b8-40a9-a06c-36b70d2bb005','Russian twists','russian-twists',null,ARRAY['Sit on the floor with knees bent and feet flat on the ground','Lean back slightly to engage your core while keeping your back straight','Lift your feet off the ground so your shins are parallel to the floor','Clasp your hands together and rotate your torso to the right, bringing your hands toward the floor beside your hip','Return to center then rotate to the left side, bringing your hands toward the floor beside your left hip','Continue alternating sides in a controlled manner']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Maintain a straight spine and avoid rounding your shoulders forward','Focus on rotating from your torso rather than just moving your arms','Control the movement and avoid using momentum to swing side to side','Keep your feet elevated throughout the exercise to maintain constant core tension']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a5eb6aec-09a0-428e-a5c1-13a0897416a4','Russian twists into seated knee tucks','russian-twists-into-seated-knee-tucks','Starting position: Sit on the floor with knees bent, feet flat on the ground, and lean back slightly while keeping your back straight and core engaged. Execution: Rotate your torso side to side in a twisting motion, then bring your knees up toward your chest while leaning back further, alternating between the two movements in a flowing sequence.',ARRAY['Sit with knees bent and feet flat, leaning back to about 45 degrees while maintaining a straight spine','Engage your core and lift your feet slightly off the ground for added challenge','Rotate your torso to the right, then center, then left to complete one Russian twist','After completing the twist, lean back further and pull your knees toward your chest while keeping your core tight','Lower your feet back down and return to the starting position','Continue alternating between Russian twists and knee tucks in a controlled rhythm']::text[],ARRAY['Keep your back straight throughout the movement and avoid rounding your shoulders forward','Focus on rotating from your core rather than just moving your arms to maximize abdominal engagement','Control the movement speed to maintain proper form and prevent momentum from taking over','Breathe steadily throughout the exercise, exhaling during the most challenging part of each movement','If you experience lower back discomfort, keep your feet on the ground during the Russian twist portion']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ebb04889-8d61-4172-9c51-65ebe6c73c75','Russian twists with flutter kicks','russian-twists-with-flutter-kicks',null,ARRAY['Lie on back, hands under hips','Legs straight, slightly off floor','Kick legs up and down alternately','Keep lower back pressed to floor']::text[],ARRAY['Small controlled movements','Lower back stays down','Keep legs straight','Breathe throughout','Targets lower abs']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b94885af-ac1a-4fd6-ac86-39da579a215d','Sage marichi I pose (left)','sage-marichi-i-pose-left','Starting position: Sit with one leg extended straight and the other leg bent with foot placed flat on the floor near the inner thigh. Execution: Twist the torso toward the bent leg while wrapping the opposite arm around the bent knee and placing the other hand behind you for support.',ARRAY['Sit on the mat with your left leg extended straight and your right knee bent, placing your right foot flat on the floor close to your left inner thigh','Keep your spine tall and shoulders relaxed as you begin to rotate your torso toward your right knee','Wrap your left arm around your right shin or knee, hugging it gently toward your chest','Place your right hand behind you on the mat for support and to help maintain proper spinal alignment','Hold the twist while breathing deeply, keeping your extended leg active and engaged','Release slowly by unwinding the twist and returning to the starting position']::text[],ARRAY['Keep the extended leg active by flexing the foot and engaging the quadriceps to protect the knee','Initiate the twist from your core rather than forcing it with your arms to prevent injury','Maintain length in your spine throughout the movement rather than rounding forward','Breathe steadily during the hold as twisting poses can feel intense','Listen to your body and don''t force the rotation beyond your comfortable range of motion']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6d518c05-cac2-4215-b71d-0b564ced5900','Sage marichi I pose (right)','sage-marichi-i-pose-right',null,ARRAY['Sit with legs extended. Bend one knee and place the foot flat on the floor.','Wrap the same-side arm around the bent knee and reach behind your back.','Clasp hands behind your back or use a strap.','Fold forward over the extended leg.']::text[],ARRAY['Sit tall before folding forward.','Keep the extended leg active with the foot flexed.','Do not round your spine excessively.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','42a043cf-29ba-4e98-a6fe-d9cbc61f7015','Scapula hold','scapula-hold','Starting position: Begin in a plank position with hands placed shoulder-width apart on the mat, arms extended, and body in a straight line from head to heels. Execution: Hold this position while focusing on proper scapular engagement and maintaining core stability throughout the duration of the hold.',ARRAY['Position hands directly under shoulders with fingers spread wide for optimal support','Engage your core muscles and maintain a straight line from your head through your heels','Keep your shoulder blades pulled down and back, avoiding any sagging or elevation','Breathe steadily while holding the position for the prescribed duration','Focus on keeping your neck in a neutral position by looking down at the mat','Maintain the hold without allowing your hips to drop or pike upward']::text[],ARRAY['Keep constant tension in your shoulder blades by pulling them down and away from your ears','Avoid holding your breath - maintain steady breathing throughout the entire hold','Stop immediately if you feel your form breaking down or experience any joint pain','Your body should form one straight line without any sagging in the lower back or hips','Start with shorter hold times and gradually increase duration as your strength improves']::text[],'back','{}'::text[],'bodyweight','back','intermediate',ARRAY['isometric','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','16a76541-f17e-49fe-832c-27776a9ec2e3','Scapula push ups','scapula-push-ups','Starting position: Begin in a high plank position with hands placed shoulder-width apart, arms fully extended, and body in a straight line from head to heels. Execution: Retract and protract your shoulder blades while keeping your arms straight, creating a small up-and-down movement of your torso.',ARRAY['Position yourself in a high plank with hands directly under shoulders and core engaged','Keep your arms completely straight throughout the entire movement','Squeeze your shoulder blades together to lower your chest slightly toward the floor','Push your shoulder blades apart to press your upper back toward the ceiling','Focus on the movement coming from your shoulder blades, not your arms','Maintain a rigid body position without allowing hips to sag or pike up']::text[],ARRAY['Keep arms locked in extension - this exercise targets scapular mobility, not arm strength','The range of motion is small, typically only 2-3 inches of vertical movement','Maintain neutral spine alignment throughout the movement to protect your lower back','Focus on slow, controlled movements rather than speed to maximize scapular engagement','This exercise serves as an excellent warm-up before more intensive pushing movements']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f4f814a7-7f9f-4d09-8c9a-f07c27176967','Sciatic nerve flossing nerve glide with a chair','sciatic-nerve-flossing-nerve-glide-with-a-chair-2e5601','Starting position: Sit upright toward the front edge of a sturdy chair with your hands resting at your sides and both feet flat on the floor, knees bent at about 90 degrees. Execution: Extend one leg forward while simultaneously coordinating neck and ankle movements to glide the sciatic nerve, then return to the bent-knee position and repeat in a smooth, controlled rhythm.',ARRAY['Sit tall on the edge of the chair with feet flat and hands beside your hips for support.','Slowly straighten one knee to extend the leg while dorsiflexing the ankle (toes toward you) and tucking the chin down.','At the same time, extend the neck by looking upward as the leg straightens to mobilise the nerve.','Return the leg to the starting bent position while reversing the neck and ankle movements.','Perform slow, controlled repetitions without forcing into pain, then switch sides.']::text[],ARRAY['Move slowly and rhythmically. This is a gliding motion, not a static stretch.','Keep the movement within a pain-free range; mild tension is acceptable but avoid sharp pain.','Coordinate the neck and ankle movements opposite to the leg extension for proper nerve flossing.','Maintain an upright posture and avoid slouching through the lower back.']::text[],'hamstrings',ARRAY['gastrocnemius','soleus','glutes']::text[],'chair','physio','beginner',ARRAY['rehabilitation','mobility','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c6a81317-685a-4478-b7aa-30743ef15034','Seal jacks','seal-jacks-026b7a','Starting position: Stand tall with feet together and arms extended straight out to the sides at shoulder height, palms facing forward. Execution: Jump both feet out wide while simultaneously bringing your arms together in front of your chest, then jump back to the starting position as you sweep your arms open to the sides. Maintain a steady rhythm throughout.',ARRAY['Stand with feet together and arms extended horizontally to the sides at shoulder height.','Jump your feet out to the sides while bringing your arms forward to clap or meet in front of your chest.','Jump your feet back together as you sweep your arms back out to the sides.','Land softly on the balls of your feet and keep your core engaged.','Repeat continuously at a controlled, rhythmic pace.']::text[],ARRAY['Keep arms at shoulder height, moving horizontally rather than overhead like standard jumping jacks.','Land softly through the feet to absorb impact and protect the knees.','Maintain a steady breathing rhythm throughout the movement.','Keep your core braced and chest lifted to support posture.']::text[],'cardiovascular_system',ARRAY['front_deltoids','pectoralis_major','glutes']::text[],'bodyweight','cardio','beginner',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2b2134be-9f7b-42d9-8739-1b24833c5e11','Seated ankle circles','seated-ankle-circles-ac8508','Starting position: Sit upright on a chair with one leg extended and the foot lifted slightly off the floor. Execution: Slowly rotate the ankle in controlled circular motions, moving through the full available range of motion, then reverse direction.',ARRAY['Sit tall on a chair and lift one foot off the floor by extending the leg slightly.','Point the toes and begin rotating the ankle in a slow, controlled circle.','Complete the desired number of circles in one direction, keeping the leg still.','Reverse direction and perform the same number of circles the opposite way.','Lower the foot and repeat with the other ankle.']::text[],ARRAY['Move only the ankle joint while keeping the leg and knee stable.','Perform the movement slowly through the full range of motion.','Keep the upper body upright and relaxed throughout.','Avoid forcing the movement if you feel pain or discomfort.']::text[],'tibialis_anterior',ARRAY['calves','peroneals','tibialis_anterior']::text[],'chair','mobility','beginner',ARRAY['mobility','warmup','rehabilitation']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ef55de8d-6d24-4983-99e0-0f50286c7a1e','Seated Barbell Military Press','seated-barbell-military-press','Starting position: Sit on a bench with a barbell in your hands, arms extended overhead with a pronated grip. Execution: Lower the bar toward your shoulders, then press upward to return to the starting position.',ARRAY['Sit with your back firmly against the bench pad and feet planted flat on the floor for stability','Grip the barbell with hands slightly wider than shoulder-width apart, positioning it at shoulder level across your upper chest','Engage your core and maintain a neutral spine throughout the entire movement','Press the barbell straight up overhead in a controlled motion, avoiding pressing forward or backward','Lower the weight slowly back to shoulder level, maintaining control and stopping when the bar reaches chin height','Keep your wrists straight and elbows slightly forward throughout the movement']::text[],ARRAY['Keep your core engaged and avoid arching your back excessively during the press','Use a full grip on the barbell rather than a thumbless grip for better control and safety','Lower the weight only to shoulder level to protect your shoulder joints from overextension','Start with lighter weight to master the form before progressing to heavier loads','Breathe out during the pressing phase and inhale while lowering the weight']::text[],'shoulders','{}'::text[],'barbell','shoulders','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','185e82b2-9e20-4021-aa84-65c564aca016','Seated Cable Fly','seated-cable-fly','Starting position: Sit upright on a bench or seat positioned between two cable machines, grasping the cable handles with arms extended out to your sides at chest height. Execution: Bring your arms forward in a controlled arc motion, crossing the cables in front of your chest, then slowly return to the starting position with arms extended wide.',ARRAY['Set up between two cable machines with handles positioned at chest height','Sit with your back straight and feet firmly planted on the ground','Grasp the cable handles with arms extended out to your sides, maintaining a slight bend in your elbows','Bring your arms forward in a smooth arc motion, crossing the cables in front of your chest','Squeeze your chest muscles at the peak contraction when your hands meet','Slowly return to the starting position, controlling the weight as your arms extend back out to your sides']::text[],ARRAY['Keep a slight bend in your elbows throughout the entire movement to protect your joints','Maintain good posture with your chest up and shoulders back during the exercise','Control both the positive and negative portions of the movement - avoid letting the weight snap back','Focus on feeling the stretch in your chest muscles when your arms are extended wide','Use a weight that allows you to maintain proper form throughout all repetitions']::text[],'chest','{}'::text[],'cable','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','60fa33db-7a56-4a6d-88a5-22f98a252ae1','Seated Cable Row Close Neutral Grip','seated-cable-row-close-neutral-grip','Starting position: Sit at a low cable row machine with a close neutral grip. Execution: Pull the handle toward your abdomen while keeping your torso upright, then slowly return to the starting position.',ARRAY['Adjust the cable machine to chest height and attach a close neutral grip handle','Sit with your back straight, core engaged, and feet securely placed on the footrests','Begin with arms extended, feeling a stretch in your lats while maintaining proper posture','Pull the handle toward your lower chest by driving your elbows back and squeezing your shoulder blades','Hold the contraction briefly at the peak of the movement','Slowly return to the starting position with control, maintaining tension throughout the entire range of motion']::text[],ARRAY['Keep your torso upright throughout the movement to avoid using momentum and ensure proper back activation','Focus on initiating the pull with your shoulder blades rather than your arms to maximize lat and rhomboid engagement','Maintain a neutral spine position and avoid rounding your back, especially during the return phase','Use a weight that allows you to control the movement completely rather than letting the weight pull you forward']::text[],'back','{}'::text[],'cable','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c2595904-d93e-4807-a7fe-70019fce408f','Seated Cable Row close V bar','seated-cable-row-close-v-bar-bccf4f','Starting position: Sit on the floor or bench facing the cable machine with feet braced, knees slightly bent, and grasp the close V-bar handle with both hands, arms extended and torso upright. Execution: Pull the handle toward your lower abdomen by driving your elbows back and squeezing your shoulder blades together, then slowly return to the starting position under control.',ARRAY['Sit facing the machine, brace your feet, and grip the V-bar with both hands.','Sit tall with a slight bend in the knees and arms fully extended.','Pull the handle toward your abdomen, driving your elbows straight back.','Squeeze your shoulder blades together at the end of the pull.','Slowly extend your arms to return the weight under control.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your torso upright and avoid excessive leaning back.','Retract the scapulae fully to engage the mid-back.','Control the negative rather than letting the weight snap back.','Keep wrists neutral and avoid shrugging the shoulders up.']::text[],'back',ARRAY['rear_deltoids','biceps','forearms','erector_spinae']::text[],'cable','strength','beginner',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5025051b-e58e-42aa-ae78-5a9b11ef129c','Seated Cable Row Neutral Grip','seated-cable-row-neutral-grip','Starting position: Sit at a low cable pulley machine with a neutral grip (palms facing each other). Execution: Pull the handle toward abdomen while keeping torso upright, then return slowly to starting position.',ARRAY['Adjust the seat height so your arms are parallel to the floor when grasping the handle','Sit with your chest up, shoulders back, and maintain a slight forward lean from your hips','Initiate the pull by retracting your shoulder blades first, then pull your elbows back close to your sides','Pull the handle to your lower ribcage while keeping your torso stable','Squeeze your shoulder blades together at the end of the movement','Slowly extend your arms back to the starting position while maintaining tension']::text[],ARRAY['Keep your core engaged throughout the movement to protect your lower back and maintain proper posture','Focus on pulling with your back muscles rather than your arms by leading with your elbows','Avoid using momentum or leaning too far back during the pulling phase','Maintain a neutral spine position and avoid rounding your shoulders forward','Control the weight on both the pulling and returning phases for maximum muscle engagement']::text[],'back','{}'::text[],'cable','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9632f636-81ae-4951-9830-4970bbd41e42','Seated Cable Row Underhand Grip','seated-cable-row-underhand-grip','Starting position: Sit at a low cable pulley machine with an underhand grip (palms up). Execution: Pull the handle toward the abdomen while maintaining an upright torso, then slowly return to starting position.',ARRAY['Adjust the cable height to chest level and select an appropriate weight','Sit with your chest up, shoulders back, and maintain a slight forward lean from your hips','Grasp the handle with palms facing upward, hands shoulder-width apart','Initiate the pull by retracting your shoulder blades, then drive your elbows straight back','Pull the handle to your lower abdomen while keeping your torso stable','Slowly extend your arms back to the starting position, maintaining tension throughout']::text[],ARRAY['Keep your core engaged and avoid excessive backward lean during the pulling motion','Focus on squeezing your shoulder blades together at the end of each rep for maximum back activation','Maintain a controlled tempo, especially during the eccentric (lowering) phase','Keep your wrists straight and aligned with your forearms throughout the movement','Avoid using momentum or jerky movements to prevent injury and ensure proper muscle engagement']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d39e64fd-25ce-4ab6-9d01-5674d92b5478','Seated Cable Row Wide Grip','seated-cable-row-wide-grip','Starting position: Sit at a low pulley machine with a wide overhand grip (palms down). Execution: Pull the handle toward your chest while keeping your torso upright, then slowly return to starting position.',ARRAY['Adjust the cable height to chest level and select an appropriate weight','Sit with your chest up, shoulders back, and maintain a slight forward lean from your hips','Grasp the wide-grip handle with an overhand grip, arms fully extended','Initiate the pull by retracting your shoulder blades and driving your elbows straight back','Pull the handle to your lower chest, focusing on squeezing your back muscles','Slowly return to starting position, maintaining tension throughout the entire range of motion']::text[],ARRAY['Keep your torso stable and avoid excessive swaying or using momentum to move the weight','Focus on pulling with your back muscles rather than your arms by leading with your elbows','Maintain a neutral spine throughout the movement and avoid rounding your shoulders forward','Use a controlled tempo with a 2-3 second negative phase to maximize muscle engagement','Stop the handle at your lower chest level rather than pulling it into your abdomen']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','86e3a801-0f1c-4424-851f-4826c75d8f48','Seated Calf Raise Machine','seated-calf-raise-machine','Starting position: Sit on a calf raise machine with feet on the platform and knees bent. Execution: Raise your heels upward by squeezing your calves, then slowly lower to the starting position.',ARRAY['Adjust the thigh pad so it sits comfortably across your lower thighs, just above your knees','Place the balls of your feet on the footplate with your feet hip-width apart and parallel','Release the weight by lifting your heels slightly and moving the release handle if applicable','Press up through the balls of your feet to raise your heels as high as possible, squeezing your calves at the top','Lower your heels slowly below the starting position to feel a stretch in your calves','Complete all repetitions before carefully re-engaging the safety handle']::text[],ARRAY['Keep your core engaged and maintain an upright posture throughout the movement to prevent your back from rounding','Focus on a slow, controlled tempo with a 2-second pause at the top and 3-second lowering phase for maximum muscle activation','Ensure full range of motion by lifting as high as possible and lowering until you feel a stretch in your calves','Avoid bouncing at the bottom of the movement as this can reduce effectiveness and increase injury risk','Keep your knees aligned with your toes and avoid letting them cave inward during the exercise']::text[],'calves','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2bdda28c-3fe2-4ecb-9a71-945a051d5bbd','Seated Calf Raises','seated-calf-raises','Starting position: Sit on a calf raise machine with feet on the platform and knees bent. Execution: Raise your heels upward by squeezing your calves, then lower slowly to the starting position.',ARRAY['Sit upright on a sturdy chair or bench with your back straight and core engaged','Place feet flat on the floor with your knees directly above your ankles','Position your hands on your thighs to provide light resistance or support','Slowly lift your heels as high as possible while keeping your toes and balls of feet on the ground','Hold the top position for 1-2 seconds while squeezing your calf muscles','Lower your heels back down slowly and with control to complete one repetition']::text[],ARRAY['Keep your knees stable and avoid bouncing during the movement','Focus on a slow, controlled tempo with a brief pause at the top of each rep','Breathe out as you lift your heels and breathe in as you lower them','Start with higher repetitions since this is a bodyweight exercise, aiming for 15-25 reps per set','Ensure full range of motion by lifting heels as high as possible and lowering them completely']::text[],'calves','{}'::text[],'barbell','legs','beginner',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f5aa2b23-405b-48a1-9538-302a41160cbd','Seated Dumbbell Curl','seated-dumbbell-curl','Starting position: Sit on a bench with back support, holding a dumbbell in each hand with arms extended at your sides and palms facing forward. Execution: Curl the dumbbells up by flexing your biceps, bringing the weights toward your shoulders, then slowly lower back to the starting position.',ARRAY['Sit upright on a bench with your back firmly supported and feet flat on the floor','Hold a dumbbell in each hand with arms hanging at your sides and palms facing forward','Keep your elbows close to your torso throughout the entire movement','Curl the weights up by contracting your biceps until the dumbbells reach shoulder level','Squeeze your biceps at the top of the movement for a brief pause','Slowly lower the dumbbells back to the starting position with control']::text[],ARRAY['Maintain a straight back against the bench support to prevent swaying or using momentum','Keep your elbows stationary at your sides - avoid letting them drift forward or backward','Control the lowering phase of the movement to maximize muscle engagement','Use a weight that allows you to maintain proper form throughout all repetitions','Avoid swinging the weights or using your shoulders to assist the movement']::text[],'biceps','{}'::text[],'dumbbell','arms - biceps',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','29e0d621-73e4-44da-9db7-10302fbe9503','Seated Dumbbell Curl - One Arm - Alternating','seated-dumbbell-curl-one-arm-alternating','Starting position: Sit on a bench with a dumbbell in each hand, arms extended downward. Execution: Curl the dumbbells toward your shoulders by bending your elbows, then lower slowly.',ARRAY['Sit with your back straight and core engaged, feet firmly planted on the floor','Hold dumbbells with a neutral grip, arms fully extended at your sides','Curl one dumbbell up by contracting the bicep while keeping your upper arm stationary','Squeeze the bicep at the top of the movement, then slowly lower the weight back to starting position','Allow the first arm to fully return to starting position before beginning the curl with the opposite arm','Maintain controlled tempo throughout the entire range of motion']::text[],ARRAY['Keep your upper arm and elbow stationary throughout the movement to isolate the bicep','Avoid using momentum or swinging the weight up - focus on controlled muscle contraction','Maintain proper posture with shoulders back and core engaged to prevent back strain','Use a full range of motion by fully extending the arm at the bottom and achieving peak contraction at the top','Control the negative portion of the lift by lowering the weight slowly rather than letting it drop']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ec7c9b41-cfd7-414a-8fbe-8c46f0d3af78','Seated Dumbbell Press','seated-dumbbell-press',null,ARRAY['Sit on bench with back support','Hold dumbbells at shoulder height, palms forward','Press straight up until arms extended','Lower with control to shoulders']::text[],ARRAY['Keep core tight, back against pad','Don''t clang dumbbells at top','Full range of motion','Control the negative','Don''t arch back excessively']::text[],'shoulders','{}'::text[],'dumbbell','shoulders',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','de5de9a5-08ca-462b-b704-eab3f48ab7b5','Seated Dumbbell Triceps Extension','seated-dumbbell-triceps-extension','Starting position: Sit upright on a bench or chair with feet flat on the floor, holding one dumbbell with both hands behind your head, elbows pointing forward and upper arms vertical. Execution: Extend your forearms upward by straightening your elbows, lifting the dumbbell overhead, then slowly lower it back to the starting position behind your head.',ARRAY['Sit with your back straight and core engaged, feet firmly planted on the floor','Grip the dumbbell with both hands around the top weight plate or handle, keeping wrists neutral','Position the dumbbell behind your head with elbows pointing forward and upper arms close to your ears','Slowly extend your forearms upward until your arms are fully extended overhead','Lower the weight back down with control until you feel a stretch in your triceps','Repeat for desired repetitions while maintaining proper elbow position throughout']::text[],ARRAY['Keep your elbows stationary and pointing forward throughout the entire movement to properly isolate the triceps','Use a controlled tempo, especially on the lowering phase, to maximize muscle engagement and prevent injury','Start with lighter weight to master the form since this exercise places the shoulder in a vulnerable overhead position','Avoid arching your back excessively by keeping your core tight and maintaining neutral spine alignment','Stop the range of motion if you feel any shoulder discomfort and consider using a smaller range of motion']::text[],'triceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1f96bb5c-a360-4ab0-83c6-23bdb92dd10c','Seated eagle arm (right)','seated-eagle-arm-right','Starting position: Sit tall in a chair or on the floor with your spine straight, extend both arms out to the sides at shoulder height. Execution: Cross your right arm under your left arm, bend both elbows and attempt to bring your palms together, lifting your elbows up while keeping your shoulders down.',ARRAY['Sit with your back straight and feet flat on the floor if using a chair','Extend both arms out to the sides at shoulder height','Cross your right arm underneath your left arm at the forearms','Bend both elbows and try to bring your palms together, or back of hands if palms don''t reach','Gently lift your elbows up while keeping your shoulders relaxed and away from your ears','Hold the stretch for 15-30 seconds while breathing deeply']::text[],ARRAY['Keep your spine straight and avoid rounding your shoulders forward during the stretch','Don''t force your palms together if flexibility doesn''t allow it - back of hands touching is sufficient','Focus on lifting your elbows up rather than pulling your arms toward your body for a deeper shoulder stretch','Breathe deeply throughout the hold and avoid holding your breath','If you feel any sharp pain, ease out of the position immediately']::text[],'shoulders','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ef8b7a4f-a209-425b-90dd-d20c402c5b0d','Seated eagle arms (left)','seated-eagle-arms-left',null,ARRAY['Sit in a comfortable cross-legged position.','Extend your arms forward and cross one arm under the other.','Bend your elbows and try to bring your palms together.','Lift your elbows to shoulder height and hold.']::text[],ARRAY['If palms do not touch, press the backs of your hands together.','Keep your shoulders relaxed and away from your ears.','Breathe into the stretch between your shoulder blades.']::text[],'shoulders','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0a095165-5eb4-4d96-a98e-d8374391f2cc','Seated EZ Bar Curl','seated-ez-bar-curl','Starting position: Sit on a bench with an EZ bar in your hands, palms facing up. Execution: Flex your elbows to raise the bar toward your shoulders, then slowly lower.',ARRAY['Sit on a bench with feet flat on the floor, holding an EZ bar with an underhand grip, hands shoulder-width apart','Keep your back straight against the bench and let your arms hang naturally at your sides with elbows close to your torso','Slowly curl the bar upward by contracting your biceps, keeping your upper arms stationary','Squeeze your biceps at the top of the movement when the bar reaches chest level','Lower the bar in a controlled manner back to the starting position','Repeat for desired repetitions without swinging or using momentum']::text[],ARRAY['Keep your wrists straight and maintain a firm grip throughout the movement','Avoid swinging your body or using your back to lift the weight','Control the eccentric (lowering) portion of the lift for maximum muscle engagement','Keep your elbows stationary and close to your sides throughout the entire range of motion']::text[],'biceps','{}'::text[],'barbell','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b7a93a70-b9fc-469f-8397-5a2e8a8877c8','Seated flutter kicks','seated-flutter-kicks',null,ARRAY['Lie on back, hands under hips','Legs straight, slightly off floor','Kick legs up and down alternately','Keep lower back pressed to floor']::text[],ARRAY['Small controlled movements','Lower back stays down','Keep legs straight','Breathe throughout','Targets lower abs']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6f54fafe-ff3f-4295-9ec6-031c1dd68e11','Seated forward bend','seated-forward-bend',null,ARRAY['Sit with legs extended straight in front of you.','Inhale and lengthen your spine.','Exhale and fold forward from the hips, reaching for your feet.','Hold your feet, ankles, or shins.']::text[],ARRAY['Hinge from the hips, not the waist.','Keep your spine as long as possible.','Bend your knees slightly if your hamstrings are tight.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','94f48c8b-042f-4df8-9805-43e4eca8573f','Seated front raises','seated-front-raises-0614b0','Starting position: Sit upright on a chair with feet flat on the floor, holding a dumbbell in each hand resting at your sides or on top of the thighs with palms facing down. Execution: Keeping the arms straight, raise both dumbbells forward and upward to shoulder height, then lower them back under control to the starting position.',ARRAY['Sit tall on the chair with feet flat and core engaged, a dumbbell in each hand.','Position arms straight down with palms facing your thighs.','Raise both dumbbells forward to shoulder height, keeping elbows nearly straight.','Pause briefly at the top without shrugging the shoulders.','Lower the weights slowly back to the starting position.','Repeat for the prescribed number of repetitions.']::text[],ARRAY['Keep your torso upright and avoid leaning back or swinging the weights.','Raise only to shoulder height to protect the shoulder joint.','Control the movement on both the lift and the descent.','Keep shoulders relaxed and away from the ears.']::text[],'front_deltoids',ARRAY['upper_chest','traps','serratus_anterior']::text[],'dumbbell','strength','beginner',ARRAY['strength','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0c46de9c-4a97-405c-9fa2-aec5f5da73f0','Seated Hammer Curl','seated-hammer-curl','Starting position: Sit on a bench with a dumbbell in each hand, palms facing your body. Execution: Flex your elbows to raise the dumbbells toward your shoulders in a hammer motion, then lower in a controlled manner.',ARRAY['Sit on a bench with back support, holding a dumbbell in each hand with arms hanging at your sides','Keep your palms facing each other (neutral grip) throughout the entire movement','Slowly curl the weights up by bending at the elbows, keeping your upper arms stationary','Squeeze your biceps at the top of the movement when the dumbbells reach shoulder level','Lower the weights back down in a controlled manner to the starting position','Repeat for the desired number of repetitions']::text[],ARRAY['Keep your core engaged and maintain good posture throughout the exercise','Avoid swinging or using momentum - focus on controlled, deliberate movements','Don''t let your elbows drift forward or flare out to the sides','Use a weight that allows you to maintain proper form for all repetitions','Breathe out during the lifting phase and breathe in during the lowering phase']::text[],'biceps','{}'::text[],'dumbbell','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','78c91035-616b-4b6c-a1b7-5572af8bc647','Seated High Row Machine','seated-high-row-machine','Starting position: Sit in a rowing machine with a high grip, adjusting the seat height so handles are at chest level. Execution: Pull the handles toward your chest while keeping your torso upright, then slowly return to the starting position.',ARRAY['Adjust the seat height so the handles align with your upper chest when seated','Sit with your chest firmly against the pad and maintain an upright posture throughout the movement','Grasp the handles with an overhand grip, hands positioned slightly wider than shoulder width','Pull the handles straight back by driving your elbows behind your body and squeezing your shoulder blades together','Hold the contraction briefly at the back position, feeling the muscles between your shoulder blades engage','Slowly return the handles to the starting position with control, maintaining tension throughout the eccentric phase']::text[],ARRAY['Keep your chest pressed against the pad throughout the entire movement to maintain proper spinal alignment','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Avoid using momentum or jerky movements - maintain a smooth, controlled tempo in both directions','Keep your shoulders down and back, avoiding any shrugging motion during the pull','Ensure your elbows travel straight back rather than flaring out to the sides']::text[],'back','{}'::text[],'machine','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7532f005-9936-49c1-8612-132d874e1ee7','Seated Hip Abduction Machine','seated-hip-abduction-machine','Starting position: Sit in a hip abduction machine with legs slightly bent and knees resting on the pads. Execution: Push your legs outward against the resistance, then slowly return to the starting position.',ARRAY['Adjust the seat height so your thighs are parallel to the floor and the pads rest comfortably above your knees','Set an appropriate weight that allows you to maintain proper form throughout the entire range of motion','Sit tall with your core engaged and grip the side handles lightly for stability','Push your legs outward smoothly by squeezing your glutes, avoiding any jerky or explosive movements','Hold the peak contraction for one second before slowly returning to the starting position','Complete the full range of motion without letting the weight stack touch between repetitions']::text[],ARRAY['Keep your core engaged and maintain an upright posture throughout the movement to prevent lower back strain','Focus on initiating the movement with your glutes rather than just pushing with your legs','Control the eccentric portion of the movement by resisting the weight as your legs return to center','Avoid bouncing at the bottom position or using momentum to complete repetitions','Start with lighter weight to master the movement pattern before progressing to heavier loads']::text[],'glutes','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6f5b8c08-2853-477c-875b-b459d4f98fa9','Seated Incline Press with Machine','seated-incline-press','Starting position: Sit on an incline chest press machine with your back firmly against the pad, feet flat on the floor, and grip the handles with your hands positioned at chest level. Execution: Press the handles forward and upward in a controlled motion until your arms are nearly extended, then slowly return to the starting position.',ARRAY['Adjust the seat height so the handles align with your mid-chest level','Sit with your back flat against the backrest and feet planted firmly on the floor','Grip the handles with a firm, overhand grip and position your hands slightly wider than shoulder-width','Press the handles forward and slightly upward in a smooth, controlled motion','Extend your arms until they are nearly straight but avoid locking out your elbows completely','Slowly lower the handles back to the starting position with control']::text[],ARRAY['Keep your core engaged and maintain contact between your back and the pad throughout the movement','Avoid pressing the handles too high or too low - maintain the natural pressing angle of your chest','Control both the pressing and lowering phases of the movement to maximize muscle engagement','Keep your wrists straight and aligned with your forearms to prevent injury','Breathe out during the pressing phase and breathe in as you lower the weight']::text[],'chest','{}'::text[],'dumbbell','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4a8661d9-eef7-44c6-896b-9ea08b81ac17','Seated Leg Curl','seated-leg-curl-b5ec8c','Starting position: Sit on the leg curl machine with back pad supporting your torso and leg pad positioned behind your ankles. Execution: Curl your heels toward your glutes by flexing your hamstrings, then slowly return to starting position.',ARRAY['Adjust the machine so the leg pad sits behind your ankles','Sit with your back flat against the pad','Grip the side handles for stability','Curl your heels toward your glutes in a smooth motion','Slowly lower the weight back to starting position']::text[],ARRAY['Keep your core engaged and back pressed against the pad throughout the movement','Avoid using momentum or bouncing at the bottom of the movement','Focus on squeezing your hamstrings at the top of the curl','Control the weight on both the lifting and lowering phases']::text[],'legs',ARRAY['calves','gastrocnemius','glutes']::text[],'machine','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','851015b9-546b-425d-81f3-ac6b7493a784','Seated Leg Curl','seated-leg-curl-c7b2fb','Starting position: Sit on the machine with back against pad and legs extended on the leg pad. Execution: Curl your heels toward your glutes by contracting your hamstrings.',ARRAY['Adjust the seat so your knees align with the machine''s pivot point','Position the leg pad just above your ankles','Grip the side handles and keep your back pressed against the pad','Curl your heels toward your glutes in a controlled motion','Slowly return to the starting position with legs extended']::text[],ARRAY['Keep your core engaged and avoid arching your back during the movement','Control the weight on both the lifting and lowering phases','Ensure the machine pad sits on your lower calves, not your Achilles tendon','Stop just short of full knee extension to maintain tension on the hamstrings']::text[],'legs','{}'::text[],'machine',null,null,'{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a097abc2-16ac-413a-86e4-444a7ce1fa43','Seated Leg Curl','seated-leg-curl','Starting position: Sit on a leg curl machine with legs extended and ankles secured under the pads. Execution: Bend the knees to bring the pads toward the glutes, then slowly lower to starting position.',ARRAY['Adjust the machine so your knees align with the pivot point and your back is fully supported against the pad','Position the lower pad just above your ankles and secure the thigh pad snugly against your legs','Grip the side handles and maintain an upright posture throughout the movement','Curl your heels toward your glutes by contracting your hamstrings, avoiding any jerky movements','Pause briefly when your knees reach approximately 90 degrees of flexion','Slowly return to the starting position, maintaining tension in your hamstrings throughout the eccentric phase']::text[],ARRAY['Keep your core engaged and avoid arching your back during the movement','Focus on a slow, controlled eccentric portion lasting 2-3 seconds for maximum muscle development','Avoid using momentum or swinging your torso to assist the movement','Ensure full range of motion while stopping just short of complete knee extension to maintain muscle tension','Breathe out during the curling phase and breathe in during the return phase']::text[],'hamstrings','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','42dc0603-91e8-4a1e-8bf0-ef9478718106','Seated leg raises','seated-leg-raises','Starting position: Sit on a mat with hands placed behind you for support, legs extended straight out in front of you. Execution: Lift both legs up toward your chest by engaging your core muscles, then lower them back down with control.',ARRAY['Sit on a mat with your hands placed behind you for support and stability','Extend both legs straight out in front of you, keeping them together','Engage your core muscles and lift both legs up toward your chest','Keep your back straight and avoid rounding your shoulders forward','Lower your legs back down slowly with control, maintaining tension in your core','Repeat the movement in a smooth, controlled rhythm']::text[],ARRAY['Keep your hands firmly planted behind you to maintain balance and support','Avoid using momentum - the movement should be slow and controlled','Focus on engaging your core muscles rather than using your hip flexors to do all the work','Keep your legs together and straight throughout the entire movement','Don''t let your legs touch the ground between repetitions to maintain constant tension']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9f3f94f9-275b-4c5c-bc97-0e5826023599','Seated Low Cable Curl','seated-low-cable-curl','Starting position: Sit on a bench facing a low cable pulley with a handle attached to the pulley. Execution: Flex the elbows to raise the handle toward the shoulders, keeping elbows fixed in place.',ARRAY['Sit upright on a bench positioned about 2-3 feet from the low cable pulley with feet planted firmly on the floor','Grasp the cable handle or bar with an underhand grip, hands shoulder-width apart','Keep your upper arms stationary against your sides and maintain a straight back throughout the movement','Curl the weight up by contracting your biceps until your forearms are vertical and you feel a strong contraction','Slowly lower the weight back to the starting position with control, maintaining tension on the biceps','Breathe out during the curl up and breathe in during the lowering phase']::text[],ARRAY['Keep your upper arms pressed against your sides to isolate the biceps and prevent shoulder involvement','Use a controlled tempo with a 2-second lift and 3-second lower to maximize muscle tension','Avoid swinging or using momentum by keeping your torso stable and core engaged','Stop just short of full arm extension at the bottom to maintain constant tension on the biceps','Select a weight that allows you to complete all repetitions with proper form while feeling challenged on the last 2-3 reps']::text[],'biceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3e96fcc6-7397-4387-ac5b-92569bd670e5','Seated Machine Chest Press','seated-machine-chest-press','Starting position: Sit on a chest press machine, adjusting the seat height so the handles are at chest level. Execution: Push the handles forward until your arms are fully extended, then return slowly to the starting position.',ARRAY['Adjust the seat height so the handles align with your mid-chest when seated','Position your back flat against the backrest and plant your feet firmly on the floor','Grip the handles with a firm, even grip using your palms','Press the handles forward smoothly while exhaling, extending your arms fully without locking your elbows','Return to the starting position slowly while inhaling, maintaining control throughout the movement','Keep your core engaged and avoid arching your back during the entire exercise']::text[],ARRAY['Keep your wrists straight and aligned with your forearms throughout the movement','Avoid pressing too fast or using momentum to prevent injury and maximize muscle engagement','Don''t allow the weight plates to touch between repetitions to maintain constant tension on the chest muscles','Focus on squeezing your chest muscles at the peak of the press for maximum activation']::text[],'chest',ARRAY['front_deltoids','triceps','core']::text[],'machine','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','16916d8d-2bce-459a-a87f-fa511936260c','Seated Neutral Grip Cable Press','seated-neutral-grip-cable-press','Starting position: Sit on a bench with cables adjusted to chest height in each hand. Execution: Push the cables forward in a pressing movement until arms are fully extended, then slowly return to starting position.',ARRAY['Adjust the cable pulleys to chest height and attach neutral grip handles','Sit with your back firmly against the pad, core engaged, and feet planted on the floor','Grasp the handles with palms facing each other, starting with hands at chest level','Press the handles forward in a smooth arc until arms are fully extended','Slowly return to starting position, controlling the weight throughout the entire range of motion','Maintain consistent tension on the cables and avoid letting the weight stack touch between repetitions']::text[],ARRAY['Keep your shoulders pulled back and down throughout the movement to protect the shoulder joint','Focus on squeezing your chest muscles at the peak contraction when arms are fully extended','Control the eccentric portion of the movement to maximize muscle engagement and prevent injury','Avoid pressing the handles too high or too low - maintain a horizontal pressing angle','Keep your core engaged to maintain proper posture and prevent lower back strain']::text[],'chest','{}'::text[],'cable','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7a9bc5bf-e817-4819-a41b-44a2aee5fb67','Seated Neutral Grip Row Machine','seated-neutral-grip-row-machine','Starting position: Sit in a rowing machine with a neutral grip, adjusting the seat height so handles are at abdomen level. Execution: Pull the handles toward your abdomen while keeping your torso upright, then slowly return to the starting position.',ARRAY['Adjust the chest pad height so it aligns with your mid-chest when seated','Sit with your chest firmly against the pad and maintain a neutral spine throughout the movement','Grasp the neutral grip handles with your arms fully extended and shoulders slightly stretched forward','Initiate the pull by retracting your shoulder blades, then drive your elbows back toward your ribs','Squeeze your shoulder blades together at the end of the movement and pause briefly','Slowly return to the starting position, allowing your shoulders to stretch forward while maintaining control']::text[],ARRAY['Keep your chest pressed against the pad throughout the entire movement to maintain proper spinal alignment','Focus on pulling with your back muscles rather than your arms by initiating the movement with shoulder blade retraction','Avoid using momentum or bouncing at the bottom of the movement to prevent injury and maximize muscle engagement','Maintain a controlled tempo with a 2-second pull and 3-second return to emphasize the eccentric portion','Keep your shoulders down and back to prevent them from rolling forward and compromising your posture']::text[],'back','{}'::text[],'machine','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','72748704-e649-4df7-9e6b-747dd4d225a2','Seated shoulder push downs','seated-shoulder-push-downs','Starting position: Sit tall on the floor or a mat with legs extended in front of you, hands placed on the ground beside your hips with fingers pointing forward. Execution: Press firmly through your palms to lift your hips and body off the ground, engaging your shoulders, core, and legs to maintain a straight line from head to heels.',ARRAY['Sit on the ground with legs straight and hands placed firmly beside your hips, fingers pointing forward','Engage your core and press down through your palms while lifting your hips off the ground','Keep your shoulders directly over your wrists and maintain straight arms throughout the movement','Hold the elevated position for 2-3 seconds while keeping your body in a straight line','Lower your hips back down to the starting position with control','Repeat for the desired number of repetitions, focusing on smooth controlled movements']::text[],ARRAY['Keep your shoulders pulled down and back to avoid hunching forward during the lift','Maintain a neutral spine throughout the movement to protect your lower back','Press firmly through your entire palm, not just your fingertips, to distribute weight evenly','If you cannot lift your hips completely off the ground, focus on pressing down and engaging the muscles without full elevation']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8540be69-f287-4af1-918b-01968b7a48a8','Seated Shoulder Squeeze','seated-shoulder-squeeze','Starting position: Sit tall in a chair with feet flat on the floor, arms at your sides, and shoulder blades in a neutral position. Execution: Squeeze your shoulder blades together by pulling your elbows back while keeping your arms close to your body, hold briefly, then return to starting position.',ARRAY['Sit upright in a sturdy chair with your back straight and feet planted firmly on the floor','Position your arms at your sides with elbows bent at 90 degrees and palms facing forward','Initiate the movement by pulling your shoulder blades together and drawing your elbows backward','Hold the squeeze for 2-3 seconds while maintaining proper posture','Slowly return your arms to the starting position with control','Repeat the movement in a smooth, controlled manner without rushing']::text[],ARRAY['Keep your chest up and avoid arching your lower back excessively during the squeeze','Focus on initiating the movement from your shoulder blades rather than just moving your arms','Maintain steady breathing throughout the exercise and avoid holding your breath','Keep your shoulders down and away from your ears to prevent neck tension','Start with shorter holds and fewer repetitions if you''re new to the exercise']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['mobility','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','00c1f017-3a36-4a42-8866-fda39f906f5d','Seated Side Bends','seated-side-bends-502d85','Starting position: Sit tall on a chair with feet flat on the floor and one hand resting on the seat beside you. Place the opposite hand gently over the top of your head. Execution: Slowly draw your head toward the same side as the reaching hand, applying light pressure to increase the stretch along the side of your neck, hold, then return and repeat on the other side.',ARRAY['Sit upright on the chair with feet flat and spine tall.','Reach one hand over the top of your head to the opposite ear.','Gently guide your head toward that shoulder until you feel a stretch on the opposite side of the neck.','Hold the stretch while breathing slowly and keeping the shoulder relaxed.','Release and return your head to center, then switch sides.','Perform an equal number of holds on each side.']::text[],ARRAY['Apply only light pressure with the hand; let the neck relax into the stretch.','Keep the opposite shoulder down and relaxed, not shrugged.','Maintain an upright torso and avoid leaning to the side.','Breathe steadily and never force the range of motion.']::text[],'neck',ARRAY['upper_traps','sternocleidomastoid']::text[],'chair','stretching','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f749ef2b-7e02-4c5b-94fd-abc1c876b0ee','Seated wide angle straddle','seated-wide-angle-straddle',null,ARRAY['Sit on the floor and open your legs wide to the sides.','Keep your toes and kneecaps pointing up.','Inhale to lengthen your spine, then fold forward from the hips.','Walk your hands forward on the floor in front of you.']::text[],ARRAY['Do not round your back - lead with your chest.','Keep your legs active and feet flexed.','Only go as far as you can with a flat back.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0a7821b6-c36b-4b5f-82b0-5c8ba765baae','Shot Caller Burpee','shot-caller-burpee',null,ARRAY['Start standing with feet hip-width apart, then squat down and place hands on the floor in front of you','Jump or step both feet back into a high plank position, keeping your core engaged','Perform a push-up, lowering your chest to the floor and pressing back up','Jump or step feet back toward your hands, returning to the squat position','Explosively jump up with arms overhead, reaching as high as possible','Land softly and immediately transition into the next repetition']::text[],ARRAY['Maintain a straight line from head to heels during the plank and push-up phases','Keep your core tight throughout the entire movement to protect your lower back','Land softly on the balls of your feet when jumping to reduce impact on joints','Modify by stepping instead of jumping if you have knee or joint concerns','Focus on controlled movement quality over speed, especially when learning the exercise']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a9db8a1f-87ac-45a6-876f-7c76bc4d5d8f','Shoulder press - Overhead press - Military press','shoulder-press-overhead-press-military-press','Starting position: Stand with feet shoulder-width apart, holding a barbell at shoulder level with an overhand grip, arms bent and elbows positioned under the bar. Execution: Press the barbell straight up overhead until arms are fully extended, then slowly lower back to the starting position at shoulder level.',ARRAY['Stand with feet shoulder-width apart for a stable base, holding the barbell with hands slightly wider than shoulder-width','Position the barbell at shoulder level with elbows directly under the bar','Engage your core and maintain a neutral spine throughout the movement','Press the barbell straight up overhead in a controlled motion until arms are fully extended','Slowly lower the barbell back to shoulder level, maintaining control throughout the descent','Keep the barbell path vertical and avoid arching your back excessively']::text[],ARRAY['Maintain a tight core throughout the entire movement to protect your lower back','Keep your wrists straight and grip the bar firmly to prevent it from rolling','Press the bar in a straight vertical line rather than forward or backward','Avoid locking out your elbows too aggressively at the top of the movement','Control the descent - don''t let the weight drop quickly to your shoulders']::text[],'shoulders','{}'::text[],'machine','shoulders',null,ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','eee3eb70-4e2c-430e-9c33-ed646287d9c2','Shoulder Press Machine','shoulder-press-machine-f3bc67','Starting position: Sit upright with back against pad, hands gripping handles at shoulder height. Execution: Press handles straight up overhead, then lower with control back to starting position.',ARRAY['Adjust seat height so handles align with shoulders','Sit with back firmly pressed against the pad','Grip handles with palms facing forward','Press handles straight up until arms are fully extended','Lower handles slowly back to shoulder level','Maintain controlled movement throughout the range of motion']::text[],ARRAY['Keep your core engaged and avoid arching your back excessively','Press in a straight vertical path rather than forward','Don''t allow your shoulders to roll forward during the movement','Stop the descent when your elbows reach shoulder level','Breathe out during the pressing phase and in during the lowering phase']::text[],'shoulders',ARRAY['triceps_long_head','upper_chest','serratus_anterior']::text[],'machine','strength','beginner','{}'::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2964f7d1-8a1f-45b6-887c-a084ceb75072','Shoulder tap burpees','shoulder-tap-burpees','Starting position: Stand tall with feet hip-width apart, arms at your sides. Execution: Perform a standard burpee by squatting down, jumping back into plank position, adding shoulder taps by alternating touching each shoulder with opposite hand, then jump feet back to squat and explosively jump up with arms overhead.',ARRAY['Begin standing with feet hip-width apart and engage your core','Squat down and place hands on the floor, then jump or step both feet back into a high plank position','Maintain plank position while lifting right hand to tap left shoulder, then left hand to tap right shoulder','Keep hips level and avoid rotating during shoulder taps','Jump or step feet back toward hands and return to squat position','Explosively jump up reaching arms overhead, then immediately begin next repetition']::text[],ARRAY['Keep your core engaged throughout the entire movement to maintain stability during shoulder taps','Land softly on the balls of your feet when jumping back and forward to protect your joints','Maintain a strong plank position with straight line from head to heels during shoulder taps','Control the shoulder tap movement to prevent hip rotation and maintain proper form','Modify by stepping instead of jumping if needed to maintain proper technique']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c847178d-3b29-4a76-b8c6-da12de207bbf','Shoulder taps','shoulder-taps','Starting position: Begin in a high plank position with hands directly under shoulders, arms straight, and body forming a straight line from head to heels. Execution: Lift one hand off the ground and tap the opposite shoulder, then return to plank and repeat with the other hand, alternating sides while maintaining core stability.',ARRAY['Start in a high plank position with hands shoulder-width apart and feet hip-width apart for stability','Engage your core muscles and maintain a straight line from head to heels throughout the movement','Lift your right hand and gently tap your left shoulder, keeping your hips square and minimizing rotation','Return your right hand to the starting position with control','Repeat the movement with your left hand tapping your right shoulder','Continue alternating sides for the desired number of repetitions or time duration']::text[],ARRAY['Keep your hips level and avoid rotating your torso or letting your hips sag during the movement','Maintain steady breathing and avoid holding your breath while performing the exercise','Start with slower, controlled movements before progressing to faster tempos','Widen your foot stance if you need additional stability while learning the movement']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','27e866fb-7cdb-4b24-824c-9ce7778c6ac7','Shoulder taps into ankle taps','shoulder-taps-into-ankle-taps','Starting position: Begin in a high plank position with hands directly under shoulders, core engaged, and body in a straight line from head to heels. Execution: Alternate lifting one hand to tap the opposite shoulder, then transition to lifting one foot to tap the opposite ankle behind you, maintaining plank position throughout.',ARRAY['Start in a high plank with hands under shoulders and feet hip-width apart for stability','Lift your right hand and tap your left shoulder, keeping hips square and minimizing body rotation','Return right hand to starting position, then lift left hand to tap right shoulder','After completing shoulder taps, lift your right foot and reach back to tap your left ankle','Return right foot to plank, then lift left foot to tap right ankle','Continue alternating between shoulder taps and ankle taps while maintaining proper plank form']::text[],ARRAY['Keep your core tightly engaged throughout the entire movement to prevent sagging hips or excessive hip elevation','Minimize body rotation and rocking by moving slowly and controlling each tap','Maintain a straight line from head to heels, avoiding pike position when reaching for ankles','Start with fewer repetitions and build up endurance as your core strength improves','If ankle taps are too challenging, perform only shoulder taps until you develop sufficient strength and flexibility']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f324d8f5-3c64-4a97-b4de-2fd60907e7d5','Side bend (left)','side-bend-left','Starting position: Stand upright with feet shoulder-width apart, arms at your sides or one hand on your hip. Execution: Slowly bend your torso to the left side, sliding your left hand down your leg while keeping your core engaged and returning to the starting position.',ARRAY['Stand with feet shoulder-width apart and maintain good posture with shoulders back','Place your right hand on your hip or let it rest at your side for balance','Engage your core muscles and keep your hips facing forward throughout the movement','Slowly bend laterally to the left, sliding your left hand down the outside of your left leg','Lower only as far as comfortable while maintaining control and proper form','Return to the starting position by engaging your right obliques to pull your torso back upright']::text[],ARRAY['Keep the movement strictly in the frontal plane - avoid twisting or rotating your torso','Maintain a neutral spine and avoid collapsing forward or backward during the bend','Focus on controlled movement rather than trying to reach as far down as possible','Keep your head in neutral alignment with your spine throughout the exercise','Breathe steadily and avoid holding your breath during the movement']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','63f5e230-17a6-40df-a2a6-f296bd816501','Side bend (right)','side-bend-right','Starting position: Stand tall with feet hip-width apart, arms at your sides or one hand on your hip. Execution: Slowly lean your torso to the right side by bending at the waist, then return to the starting position in a controlled manner.',ARRAY['Stand with feet hip-width apart and engage your core muscles','Place your left hand on your hip or let it hang naturally at your side','Slowly bend your torso to the right side, sliding your right hand down your leg','Keep your back straight and avoid twisting or rotating your spine','Hold the stretch briefly at the bottom of the movement','Return to the starting position using your core muscles to pull yourself back up']::text[],ARRAY['Keep the movement slow and controlled to avoid straining the spine','Maintain proper posture by keeping your shoulders square and avoiding forward lean','Focus on feeling the stretch along the left side of your torso and obliques','Breathe steadily throughout the movement and avoid holding your breath','Stop immediately if you feel any sharp pain in your back or sides']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7502b225-3aa7-44a1-901f-f02f2f14d58c','Side Bend Stretch (R)','side-bend-stretch-r','Starting position: Stand tall with feet hip-width apart, arms relaxed at your sides, focusing on stretching the right side of your core. Execution: Slowly lean your torso to the left side while reaching your left hand toward the floor, creating a lateral stretch along your right obliques and intercostal muscles.',ARRAY['Stand with feet hip-width apart and maintain a straight spine with shoulders relaxed','Raise your right arm overhead and place your left hand on your left hip for support','Slowly lean your entire torso to the left side, reaching your right arm over your head','Keep your hips facing forward and avoid twisting or rotating your torso','Hold the stretch for 15-30 seconds while breathing deeply','Return to the starting position slowly and with control']::text[],ARRAY['Keep the movement purely lateral - avoid leaning forward or backward during the stretch','Maintain steady breathing throughout the stretch and avoid holding your breath','Feel the stretch along the entire right side of your torso from hip to armpit','Stop immediately if you experience any sharp pain or discomfort in your lower back','Keep your core gently engaged to protect your spine during the movement']::text[],'core','{}'::text[],'bodyweight','core','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3eeee272-7aae-4e5c-8d9c-415a3bf74352','Side Bend with Dumbbells','side-bend-with-dumbbells-380972','Starting position: Stand upright with feet shoulder-width apart, holding a dumbbell in each hand at your sides with arms fully extended and palms facing your body. Keep your chest up, shoulders back, and core engaged. Execution: Slowly bend your torso laterally to one side, lowering the dumbbell down the side of your leg while keeping the opposite side stretched. Pause briefly, then contract your obliques to return to the upright position and repeat on the other side.',ARRAY['Stand tall with feet shoulder-width apart, a dumbbell in each hand at your sides.','Keep your core braced and slowly bend directly sideways at the waist.','Lower the dumbbell along the outside of your leg without rotating your torso.','Pause at the bottom, then contract your obliques to pull yourself back upright.','Repeat on the opposite side, alternating with control.','Maintain even, controlled breathing throughout each repetition.']::text[],ARRAY['Bend laterally only. Avoid leaning forward or twisting the torso.','Keep both arms straight and dumbbells close to your body.','Move slowly and controlled, feeling the stretch and contraction in the obliques.','Keep hips stable and facing forward throughout the movement.']::text[],'obliques',ARRAY['erector_spinae','transverse_abdominis','lower_back']::text[],'dumbbell','core','beginner',ARRAY['strength','core']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','061b3246-322a-41ed-a589-73fb9478651c','Side hurdel jumps to mountain climbers','side-hurdel-jumps-to-mountain-climbers-061b3246','Starting position: Begin in a high plank position with hands planted firmly on the ground, shoulders directly over wrists, and body forming a straight line from head to heels. Execution: Perform lateral jumps by bringing both feet to one side outside the hands, then jumping to the opposite side, followed by alternating mountain climber knee drives while maintaining the plank position.',ARRAY['Start in a high plank position with core engaged and shoulders stable over your wrists','Jump both feet laterally to the right side, landing outside your right hand with knees bent','Immediately jump both feet to the left side, landing outside your left hand','Return to center plank position and perform 4-6 alternating mountain climber knee drives','Keep hips level throughout the lateral jumps and avoid excessive bouncing','Complete the desired number of repetitions maintaining proper form throughout']::text[],ARRAY['Maintain a strong plank position throughout the entire exercise to protect your lower back','Land softly on the balls of your feet during lateral jumps to reduce impact on joints','Keep your core tight and avoid letting hips sag or pike up during transitions','Control the mountain climber tempo to maintain proper form rather than rushing through the movement','Ensure adequate space around you before beginning as this exercise requires lateral movement']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3798bfae-4ad3-404c-969d-0eeb2fcbdd56','Side hurdel jumps to mountain climbers','side-hurdel-jumps-to-mountain-climbers',null,ARRAY['Start in push-up position','Drive one knee toward chest','Quickly switch legs','Continue alternating at pace']::text[],ARRAY['Keep hips down (don''t pike)','Core stays engaged','Speed up for more cardio','Slow down for more control','Full body exercise']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ed54736f-d36d-46fa-ac16-08a44612eded','Side jump skaters','side-jump-skaters','Starting position: Stand with feet hip-width apart, knees slightly bent, and arms at your sides. Execution: Jump laterally to one side while bringing the opposite leg behind in a skating motion, then immediately jump to the other side, alternating sides in a continuous flowing movement.',ARRAY['Stand with feet hip-width apart and engage your core muscles','Jump laterally to your right side, landing on your right foot while sweeping your left leg behind your right leg','Swing your arms naturally to help maintain balance and momentum','Immediately push off your right foot and jump to the left side, landing on your left foot with right leg sweeping behind','Continue alternating sides in a smooth, controlled rhythm','Land softly on the balls of your feet with knees bent to absorb impact']::text[],ARRAY['Keep your chest up and maintain good posture throughout the movement','Land softly with bent knees to protect your joints and maintain control','Focus on lateral distance rather than height for maximum effectiveness','Maintain a steady rhythm and avoid pausing between jumps','Start with smaller jumps and gradually increase range of motion as you build strength and coordination']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','plyometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7384d39b-613f-4c8e-a980-42e2d3bd8a83','Side Lateral Raise with Dumbbells','side-lateral-raise-with-dumbbells','Starting position: Stand upright with feet hip-width apart, holding dumbbells at your sides with arms slightly bent and palms facing your body. Execution: Lift the dumbbells out to your sides until your arms are parallel to the floor, then slowly lower them back to the starting position.',ARRAY['Stand with feet hip-width apart and hold a dumbbell in each hand at your sides with a slight bend in your elbows','Keep your core engaged and maintain a neutral spine throughout the movement','Lift the dumbbells out to your sides, leading with your elbows rather than your hands','Raise the weights until your arms are parallel to the floor, forming a T-shape with your body','Pause briefly at the top of the movement, then slowly lower the dumbbells back to the starting position with control','Maintain the slight bend in your elbows throughout the entire range of motion']::text[],ARRAY['Avoid using momentum or swinging the weights - focus on controlled movement using only your shoulder muscles','Keep your shoulders down and back to prevent shrugging and reduce risk of impingement','Start with lighter weights to master the form before progressing to heavier dumbbells','Stop the upward motion at shoulder height to avoid placing excessive stress on the shoulder joint','Maintain a slight forward lean of the torso to better target the lateral deltoids']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3ad63b44-3e91-44cb-a39d-45aa9d50817c','Side Plank','side-plank-48ec26','Starting position: Lie on your side with elbow directly under shoulder and legs stacked. Execution: Lift hips off ground creating straight line from head to feet.',ARRAY['Lie on your side with elbow under shoulder','Stack your feet and legs on top of each other','Lift your hips off the ground','Create a straight line from head to feet','Hold the position while breathing normally','Lower down with control']::text[],ARRAY['Keep your elbow directly underneath your shoulder to prevent injury','Engage your core muscles to maintain proper spine alignment','Avoid letting your hips sag or pike upward','Keep your head in neutral position aligned with your spine']::text[],'abs',ARRAY['lateral_deltoids','adductors']::text[],'bodyweight','core','intermediate','{}'::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d0b4d724-b764-434e-a595-98c0d1ff76fb','Side plank pose (left)','side-plank-pose-left',null,ARRAY['From Plank Pose, shift your weight onto one hand and the side of the corresponding foot.','Stack your feet and open your top arm toward the ceiling.','Keep your body in a straight line from head to feet.','Hold and breathe steadily.']::text[],ARRAY['Press firmly through your supporting hand.','Engage your core and obliques.','Modify by lowering your bottom knee to the floor.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','84497aca-5092-4038-bf3c-3e9beeae9f8b','Side plank pose (right)','side-plank-pose-right',null,ARRAY['From Plank Pose, shift your weight onto one hand and the side of the corresponding foot.','Stack your feet and open your top arm toward the ceiling.','Keep your body in a straight line from head to feet.','Hold and breathe steadily.']::text[],ARRAY['Press firmly through your supporting hand.','Engage your core and obliques.','Modify by lowering your bottom knee to the floor.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','516a33ee-e1e1-459d-9417-a313b313e1a6','Side plank pulses','side-plank-pulses','Starting position: Lie on your side with your forearm on the ground, elbow directly under your shoulder, and your body in a straight line from head to feet. Execution: Lift your hips up into a side plank position and perform small pulsing movements up and down while maintaining the plank position.',ARRAY['Lie on your side with your bottom forearm flat on the mat, elbow positioned directly under your shoulder','Stack your feet on top of each other or stagger them for better stability','Engage your core and lift your hips off the ground to create a straight line from your head to your feet','Perform small controlled pulses by slightly lowering and raising your hips while maintaining the side plank position','Keep your top hand placed on your hip or extended toward the ceiling for balance','Hold the side plank position throughout the pulsing movement without letting your hips drop to the floor']::text[],ARRAY['Keep your elbow directly under your shoulder to avoid strain on the shoulder joint','Maintain a straight line through your body - avoid letting your hips sag or pike up','Engage your core muscles throughout the entire movement to protect your lower back','Keep the pulsing movements small and controlled rather than large bouncing motions','Breathe steadily throughout the exercise and avoid holding your breath']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','71213402-bffc-41ab-9425-736789fca561','Side plank pulses (Right side)','side-plank-pulses-right-side',null,ARRAY['Forearms on floor, elbows under shoulders','Body straight from head to heels','Hold position','Keep core tight, don''t let hips sag']::text[],ARRAY['Squeeze glutes','Keep neck neutral','Breathe normally','Don''t raise hips too high','Build time gradually']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8d5a28d5-9aa2-4d63-bdc4-3e6e746e9d0d','Side plank up and down (left)','side-plank-up-and-down-left','Starting position: Lie on your left side in a side plank position with your left forearm on the ground, elbow directly under your shoulder, and your body forming a straight line from head to feet. Execution: Lower your hips down to lightly touch the ground, then lift back up to the starting plank position in a controlled manner.',ARRAY['Lie on your left side with your left forearm planted firmly on the ground, elbow positioned directly under your shoulder','Stack your right leg on top of your left leg and engage your core to lift your hips into a straight side plank position','Keep your right hand on your hip or extended along your side for balance','Slowly lower your hips down until they lightly touch the ground while maintaining control','Immediately lift your hips back up to the starting side plank position using your core and oblique muscles','Repeat the up and down movement for the desired number of repetitions']::text[],ARRAY['Keep your supporting elbow directly under your shoulder throughout the entire movement to protect your shoulder joint','Maintain a straight line from your head to your feet - avoid letting your hips sag or pike up','Control the descent and avoid dropping your hips heavily to the ground','Engage your core and breathe steadily throughout the movement rather than holding your breath','Focus on using your obliques to lift your hips rather than pushing off with your legs']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','strength','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c0c8d00e-5640-462e-8cc3-422a14deb2fc','Side plank up and down (right)','side-plank-up-and-down-right','Starting position: Lie on your right side in a side plank position with your right forearm on the ground, elbow directly under your shoulder, and your body forming a straight line from head to feet. Execution: Lower your hips down toward the ground, then lift them back up to the starting plank position, repeating this up and down movement.',ARRAY['Lie on your right side with your right forearm planted firmly on the ground and elbow positioned directly under your shoulder','Stack your feet on top of each other and engage your core to lift your hips into a straight side plank position','Slowly lower your hips down toward the ground while maintaining control and keeping your forearm planted','Drive your hips back up to the starting side plank position by engaging your obliques and core muscles','Keep your body in a straight line throughout the entire movement without allowing your hips to rotate forward or backward','Repeat the up and down movement for the desired number of repetitions before switching to the left side']::text[],ARRAY['Keep your elbow directly under your shoulder throughout the movement to protect your shoulder joint','Maintain a straight line from your head to your feet - avoid letting your hips sag or pike up','Control the descent when lowering your hips rather than just dropping down with gravity','Engage your core muscles throughout the entire exercise to maximize effectiveness and protect your spine','Keep your neck in a neutral position by looking straight ahead rather than up or down']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','strength','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c811aaa0-7aa9-41c3-89f1-647feb729069','Side to side plank walk','side-to-side-plank-walk','Starting position: Begin in a plank position with hands placed on the mat, body in a straight line from head to heels. Execution: Step one hand off the mat followed by the corresponding foot, then step the other hand and foot to move laterally across the floor while maintaining the plank position.',ARRAY['Start in a strong plank position with hands shoulder-width apart on the mat and feet hip-width apart','Step your right hand off the mat to the right, followed immediately by your right foot','Bring your left hand and left foot toward the center to return to plank position','Continue stepping laterally in the same direction for the desired number of steps','Reverse the movement to return to your starting position','Maintain a straight line from head to heels throughout the entire movement']::text[],ARRAY['Keep your core engaged and avoid letting your hips sag or pike up during the movement','Move with control rather than speed to maintain proper form and stability','Keep your hands directly under your shoulders when in the plank position','Avoid crossing your hands or feet over each other during the lateral steps','Breathe steadily throughout the exercise and don''t hold your breath']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','49193da5-2b92-4df3-bca6-f0cd59fa9f03','Side to side plank walk into shoulder taps','side-to-side-plank-walk-into-shoulder-taps','Starting position: Begin in a plank position with hands placed shoulder-width apart and body in a straight line from head to heels. Execution: Walk laterally in plank position by moving one hand and opposite foot simultaneously, then perform shoulder taps by lifting one hand to touch the opposite shoulder while maintaining plank form.',ARRAY['Start in a high plank position with hands directly under shoulders and core engaged','Step your right hand and left foot simultaneously to the right, maintaining plank alignment','Follow with your left hand and right foot to return to shoulder-width hand spacing','Lift your right hand to tap your left shoulder while keeping hips stable','Return right hand to the floor and repeat the tap with your left hand to right shoulder','Continue the lateral walking movement and shoulder tap sequence as desired']::text[],ARRAY['Keep your core tight throughout the entire movement to prevent sagging hips','Minimize hip rotation when performing shoulder taps by engaging your glutes and core','Maintain a straight line from head to heels during both the lateral movement and shoulder taps','Keep your hands directly under your shoulders when in the plank position','Move in a controlled manner rather than rushing through the exercise']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2c525222-75e1-4c05-b8ee-f4d2c7d1799e','Side to side push up','side-to-side-push-up','Starting position: Begin in a standard push-up position with hands placed wider than shoulder-width apart, body in a straight line from head to heels. Execution: Lower your chest toward one hand while shifting your weight to that side, then push back up to center and repeat on the opposite side, alternating the lateral movement with each repetition.',ARRAY['Position hands wider than shoulder-width apart in a plank position with core engaged','Lower your body toward your right hand while shifting weight to the right side','Push back up to the starting center position with control','Lower your body toward your left hand while shifting weight to the left side','Return to center and continue alternating sides for the desired number of repetitions','Maintain proper plank form throughout the entire movement']::text[],ARRAY['Keep your core tight and hips level to prevent sagging or piking during the lateral movement','Focus the weight shift through your arms and shoulders rather than twisting your torso','Start with a smaller range of motion and gradually increase the lateral distance as you build strength','Ensure both hands remain flat on the ground throughout the movement to maintain wrist stability','Control the tempo on both the lowering and pushing phases to maximize muscle engagement']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','857fa3a7-6b75-4329-9bb0-297db6b9f761','Side to side squat','side-to-side-squat','Starting position: Stand with feet wider than shoulder-width apart, toes pointing slightly outward, arms at your sides or crossed over your chest. Execution: Shift your weight to one side while bending that knee and lowering into a squat position, keeping the opposite leg straight, then return to center and repeat on the other side.',ARRAY['Stand with feet positioned wider than shoulder-width apart and toes pointing slightly outward','Keep your chest up and core engaged throughout the entire movement','Shift your weight to your right side while bending your right knee and lowering your hips down and back','Push through your right heel to return to the starting position in the center','Immediately shift to your left side and repeat the squatting motion on that leg','Continue alternating sides in a controlled, rhythmic pattern']::text[],ARRAY['Keep the non-working leg straight but not locked, allowing it to act as a support','Maintain proper squat form by keeping your chest up and knees tracking over your toes','Focus on sitting back into your hips rather than letting your knees drift forward','Start with a smaller range of motion and gradually increase depth as flexibility improves','Keep your weight primarily on the heel of the working leg to maximize quad engagement']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4150a3eb-5b70-4d2e-8cab-a27e70b3ef43','Sideplank','sideplank',null,ARRAY['Forearms on floor, elbows under shoulders','Body straight from head to heels','Hold position','Keep core tight, don''t let hips sag']::text[],ARRAY['Squeeze glutes','Keep neck neutral','Breathe normally','Don''t raise hips too high','Build time gradually']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['core','strength','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b92cf13a-2241-45c5-b2ba-d5043c9b3ea0','Singel arm push up (L)','singel-arm-push-up-l','Starting position: Begin in a plank position with feet slightly wider than shoulder-width apart, with your left hand placed on the mat and your right arm positioned behind your back or to the side. Execution: Lower your body down by bending your left arm until your chest nearly touches the floor, then push back up to the starting position using only your left arm.',ARRAY['Start in a standard plank position then remove your right hand and place it behind your back or out to the side','Position your feet wider than normal to create a stable base of support','Keep your core engaged and body in a straight line from head to heels','Lower your body slowly by bending your left elbow until your chest nearly touches the ground','Push through your left hand to return to the starting plank position','Maintain control throughout the entire range of motion']::text[],ARRAY['Widen your foot stance significantly to provide better stability and balance during the single-arm movement','Keep your core extremely tight to prevent your hips from rotating or dropping during the exercise','Start with partial range of motion if you cannot complete a full single-arm push-up','Ensure your working arm stays close to your body rather than flaring out excessively','Progress gradually by first mastering regular push-ups and then elevated single-arm variations before attempting this advanced movement']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9089468c-a43c-4486-892e-557485a39245','Single Arm Cable Front Raise','single-arm-cable-front-raise','Starting position: Stand facing a cable pulley with a handle in one hand, arm extended downward. Execution: Raise the handle to the front until it reaches shoulder height, then slowly lower.',ARRAY['Set the cable pulley to the lowest position and attach a single handle','Stand facing the cable machine with feet shoulder-width apart, core engaged','Grasp the handle with your working arm using an overhand grip, arm extended down by your side','Keep your torso upright and raise your arm straight forward until it reaches shoulder height','Pause briefly at the top of the movement','Slowly lower your arm back to the starting position with control']::text[],ARRAY['Keep your core tight and avoid using momentum or swaying your body','Maintain a slight bend in your elbow throughout the entire movement','Focus on controlled movement both up and down to maximize muscle engagement','Stop at shoulder height to prevent shoulder impingement','Use your non-working arm to stabilize yourself if needed by holding onto the machine']::text[],'shoulders','{}'::text[],'cable','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ffd0d6dc-27ff-4a99-afcc-673701fa9d3d','Single Arm Cable Tricep Pushdown','single-arm-cable-tricep-pushdown-c51cbd','Starting position: Stand upright facing the cable machine with a single-handle attachment set at the high pulley, grasping the handle with one hand, elbow tucked close to the torso and the forearm bent to roughly 90 degrees. Execution: Keeping the upper arm stationary, extend the elbow to press the handle down toward the thigh, squeeze the triceps at full extension, then slowly return under control.',ARRAY['Set the pulley to a high position and attach a single handle, then grip it with one hand.','Stand tall with feet shoulder-width apart and pin the working elbow to your side.','Extend the elbow to drive the handle down until your arm is fully straight.','Squeeze the triceps briefly at the bottom of the movement.','Slowly bend the elbow to return the handle to the starting position without letting the upper arm move.','Complete all reps on one arm, then switch sides.']::text[],ARRAY['Keep the upper arm and elbow fixed against your torso throughout.','Move only at the elbow joint to isolate the triceps.','Control the eccentric phase rather than letting the weight snap back.','Avoid leaning or using body momentum to move the weight.']::text[],'triceps',ARRAY['forearm_flexors','forearm_extensors','rear_deltoids']::text[],'cable','strength','beginner',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','a299ccb1-0604-4d47-a5c1-19d5ca0e8b42','Single Arm Dumbbell Row','single-arm-dumbbell-row','Starting position: Stand with a dumbbell in one hand and the other hand supported on a bench. Execution: Pull the dumbbell toward the side of the chest while keeping the back straight, then slowly lower to starting position. Repeat with the other arm.',ARRAY['Position yourself with one knee and same-side hand on a bench, keeping your back straight and parallel to the floor','Hold the dumbbell in your free hand with a neutral grip, allowing your arm to hang straight down','Initiate the movement by pulling your shoulder blade back and driving your elbow toward your hip','Squeeze your back muscles at the top of the movement when the dumbbell reaches your lower ribcage','Slowly lower the dumbbell back to the starting position with control','Complete all repetitions on one side before switching to the other arm']::text[],ARRAY['Keep your core engaged and avoid rotating your torso during the movement','Focus on pulling with your back muscles rather than just your arm','Maintain a neutral spine throughout the entire exercise','Use a full range of motion but avoid letting the dumbbell pull your shoulder forward at the bottom','Choose a weight that allows you to maintain proper form for all repetitions']::text[],'back','{}'::text[],'dumbbell','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fc11f2e5-3fcd-4682-bb4b-10c33951335a','Single Arm Lat Pulldown','single-arm-lat-pulldown','Starting position: Stand facing a high pulley with a handle in one hand. Execution: Pull the handle down to the side of your chest, keeping your elbow close to your body, then slowly return to the starting position.',ARRAY['Adjust the knee pad to secure your legs and prevent your body from lifting during the movement','Grasp the handle with one hand using an overhand grip, keeping your arm fully extended overhead','Engage your core and maintain a straight spine throughout the entire exercise','Pull the handle down in a smooth arc toward your side, focusing on squeezing your shoulder blade down and back','Hold the contracted position briefly, then slowly return the handle to the starting position with control','Complete all repetitions on one side before switching to the other arm']::text[],ARRAY['Keep your torso upright and avoid leaning excessively to one side during the movement','Focus on pulling with your lat muscle rather than using your bicep or hand to dominate the movement','Maintain constant tension on the cable and avoid letting the weight stack slam between repetitions','Use your non-working hand to lightly hold onto the machine for stability if needed','Control the eccentric portion of the movement to maximize muscle engagement and prevent injury']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e1b68bd8-a3aa-45db-8d6f-cc470738a85e','Single Arm Lateral Raise','single-arm-lateral-raise','Starting position: Stand with a dumbbell in one hand with arm extended at your side. Execution: Raise the dumbbell laterally until your arm is parallel to the floor, then slowly lower to starting position. Repeat with the other arm.',ARRAY['Stand tall with core engaged and hold the dumbbell with a firm grip at your side','Keep your working arm slightly bent at the elbow throughout the entire movement','Lift the weight out to the side using your shoulder muscles, not momentum','Raise the dumbbell until your arm is parallel to the floor at shoulder height','Pause briefly at the top position, then slowly lower the weight back down','Complete all repetitions on one side before switching to the other arm']::text[],ARRAY['Keep your torso upright and avoid leaning away from the working side during the lift','Control the descent phase as much as the lifting phase to maximize muscle engagement','Stop at shoulder height to avoid shoulder impingement and maintain proper form','Use a weight that allows you to complete all repetitions with perfect technique','Avoid using your legs or back to help lift the weight by maintaining a stable stance']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','efde17d4-3987-4416-9142-825a18329245','Single Arm Low Cable Curl','single-arm-low-cable-curl','Starting position: Stand facing a low pulley with a dumbbell in one hand, arm extended downward. Execution: Flex your elbow to lift the dumbbell toward your shoulder, then lower in a controlled manner.',ARRAY['Set the cable pulley to the lowest position and attach a single handle','Stand 2-3 feet away from the machine with feet shoulder-width apart for stability','Grasp the handle with an underhand grip, keeping your working arm at your side with elbow close to your torso','Curl the weight up by flexing your bicep, bringing your hand toward your shoulder','Squeeze your bicep at the top of the movement for one second','Slowly lower the weight back to starting position, maintaining control throughout the descent']::text[],ARRAY['Keep your elbow stationary at your side throughout the entire movement to isolate the bicep','Maintain a slight bend in your knees and engage your core to prevent swaying or using momentum','Use a full range of motion by fully extending your arm at the bottom and achieving maximum contraction at the top','Control the weight during both the lifting and lowering phases to maximize muscle engagement and prevent injury']::text[],'biceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fee193c5-ec61-4e7f-aca8-a0ab268f6e26','Single Arm Lying Dumbbell Extension','single-arm-lying-dumbbell-extension','Starting position: Lie on a flat bench with a dumbbell in one hand, arm extended upward. Execution: Lower the dumbbell toward your shoulder by flexing your elbow, then extend your arm to return to the starting position and repeat with the other arm.',ARRAY['Lie flat on a bench with feet planted firmly on the floor and core engaged','Hold the dumbbell with one hand and extend that arm straight up above your shoulder','Place your opposite hand on your working arm''s elbow to provide support and stability','Slowly lower the weight behind your head by bending only at the elbow joint while keeping your upper arm stationary','Lower until you feel a stretch in your tricep, then press the weight back to the starting position','Complete all reps on one arm before switching to the other side']::text[],ARRAY['Keep your upper arm perpendicular to the floor throughout the entire movement','Use your supporting hand to stabilize the working arm and prevent shoulder movement','Control the weight during both the lowering and lifting phases to maximize muscle activation','Start with lighter weight than you would use for two-arm variations since single arm work requires more stability','Stop the range of motion if you feel any shoulder discomfort or instability']::text[],'triceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0fed480a-62f6-44d9-a457-787ebcd1395f','Single Arm Preacher Curl','single-arm-preacher-curl','Starting position: Sit at a preacher bench with a dumbbell in one hand, resting your arm on the bench pad. Execution: Flex your elbow to raise the dumbbell toward your shoulder, then slowly lower.',ARRAY['Sit at a preacher bench with your chest pressed against the angled pad and feet flat on the floor','Hold a dumbbell in one hand with an underhand grip, extending your arm over the pad with a slight bend in your elbow','Keep your working arm''s armpit at the top edge of the pad and your shoulder pulled back','Slowly curl the dumbbell up by contracting your bicep until your forearm is nearly vertical','Lower the weight in a controlled manner back to the starting position with a slight bend in your elbow','Complete all repetitions on one arm before switching to the other side']::text[],ARRAY['Keep your wrist straight and in line with your forearm throughout the movement','Avoid letting your elbow fully lock out at the bottom to prevent joint stress','Control the negative portion of the lift to maximize muscle engagement and prevent injury','Keep your core engaged and avoid using momentum or swinging the weight']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','147a7908-fdd3-4f79-94ca-f9a69989e14c','Single arm push up (R)','single-arm-push-up-r','Starting position: Begin in a standard push-up position, then place your left hand behind your back or on your hip, balancing on your right hand with feet spread wider than shoulder-width for stability. Execution: Lower your body by bending your right arm until your chest nearly touches the ground, then press back up to the starting position using only your right arm.',ARRAY['Start with regular push-ups and progress to elevated single-arm push-ups before attempting this advanced variation','Position your right hand directly under your chest center rather than under your right shoulder for better balance','Spread your feet wider than normal and angle your body slightly toward your supporting arm','Keep your core extremely tight throughout the entire movement to prevent rotation','Lower slowly with control and only go as deep as you can while maintaining proper form','Focus on quality over quantity - even partial range of motion is beneficial when learning']::text[],ARRAY['This is an advanced exercise requiring significant upper body and core strength - master regular push-ups first','Maintain a straight line from head to feet without allowing your hips to rotate or sag','Start with partial range of motion and gradually increase depth as strength improves','Keep your supporting hand positioned under the center of your chest for optimal leverage','Stop immediately if you experience wrist, shoulder, or elbow pain']::text[],'chest','{}'::text[],'bodyweight','chest','advanced',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cea594a5-f158-493b-adc2-4016ca1a0bd4','Single Arm Row','single-arm-row-7c8162','Starting position: Stand with feet hip-width apart, hinge forward at the hips with a slight knee bend, keeping the back flat and core braced, holding a dumbbell in one hand with the arm extended. Execution: Pull the dumbbell up toward your hip by driving the elbow back and squeezing the shoulder blade, then lower under control to the starting position.',ARRAY['Hinge forward at the hips with a flat back and slight bend in the knees, letting the dumbbell hang at arm''s length.','Brace your core and keep your neck neutral, gaze slightly forward and down.','Drive your elbow up and back, pulling the dumbbell toward your hip while squeezing your shoulder blade.','Pause briefly at the top with the dumbbell near your ribcage.','Lower the dumbbell slowly and with control back to the fully extended position.','Complete all reps on one side before switching arms.']::text[],ARRAY['Keep your back flat and avoid rounding the spine throughout the movement.','Lead with the elbow and squeeze the shoulder blade rather than pulling with the arm.','Avoid rotating or twisting the torso to lift the weight.','Control the descent instead of letting the weight drop.']::text[],'lats',ARRAY['biceps','rear_deltoids','forearms']::text[],'dumbbell','strength','beginner',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7dd83ed0-59e0-4339-a54a-d3319bdf00ab','Single Arm Seated Cable Row','single-arm-seated-cable-row','Starting position: Sit at a low cable pulley machine with a handle in one hand. Execution: Pull the handle toward the side of your abdomen while keeping your torso upright, then slowly return to the starting position and repeat with the other arm.',ARRAY['Adjust the cable height to chest level and select an appropriate weight','Sit with feet flat on the platform and knees slightly bent for stability','Grasp the handle with your working arm while keeping your non-working hand on your thigh for support','Initiate the pull by retracting your shoulder blade first, then drive your elbow straight back','Squeeze your back muscles at the peak contraction when the handle reaches your ribs','Control the weight back to the starting position, allowing a full stretch in your lat']::text[],ARRAY['Keep your torso upright throughout the movement to prevent lower back strain','Focus on pulling with your back muscles rather than your arm by leading with your elbow','Avoid rotating your torso or using momentum to complete the repetition','Maintain a neutral wrist position and firm grip on the handle','Complete all repetitions on one side before switching to maintain proper form and muscle activation']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0b51bca9-c72f-4fc3-affd-0904de3cf8b4','Single Arm Smith Machine Row','single-arm-smith-machine-row','Starting position: Position yourself at a Smith machine with one hand gripping the bar and the other resting on your leg or a bench. Execution: Pull the bar toward the side of your chest, keeping your torso aligned, then slowly lower to the starting position.',ARRAY['Set the Smith machine bar to about waist height and position a bench perpendicular to the bar','Place your inside knee and hand on the bench for support, with your outside foot planted firmly on the ground','Grip the bar with your outside hand using an overhand grip, allowing your arm to fully extend','Pull the bar up toward your lower ribcage by driving your elbow back and squeezing your shoulder blade toward your spine','Pause briefly at the top, then slowly lower the bar back to the starting position with control','Complete all reps on one side before switching to the other arm']::text[],ARRAY['Keep your back straight and core engaged throughout the movement','Focus on pulling with your back muscles rather than just your arm','Avoid rotating your torso - keep your shoulders square','Control the weight on both the lifting and lowering phases','Start with lighter weight to master the form before progressing']::text[],'back','{}'::text[],'machine','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','63ca895d-601f-4155-b654-1682690d7f1c','Single Arm T-Bar Row','single-arm-t-bar-row','Starting position: Stand at a T-bar row using a single-hand grip. Execution: Pull the bar toward the side of your chest while keeping your back straight, then slowly lower to the starting position. Repeat with the other arm.',ARRAY['Secure one end of the barbell in a corner or landmine attachment and load the opposite end with appropriate weight','Stand with feet shoulder-width apart, straddling the barbell, and hinge forward at the hips while maintaining a neutral spine','Grasp the barbell with one hand using an overhand grip, keeping your arm extended and the weight hanging freely','Pull the weight up by driving your elbow back and squeezing your shoulder blade toward your spine','Slowly lower the weight back to the starting position with control, maintaining tension throughout the movement','Complete all repetitions on one side before switching to the opposite arm']::text[],ARRAY['Keep your core engaged and maintain a neutral spine throughout the entire movement to protect your lower back','Focus on pulling with your back muscles rather than your arm by initiating the movement with your shoulder blade','Use a full range of motion by allowing the weight to stretch your lat at the bottom and pulling until your elbow is behind your torso','Avoid using momentum or swinging the weight, instead maintaining smooth and controlled movement patterns','Keep your non-working arm free for balance or place it on your thigh for additional stability']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f3b5098c-a02d-44ce-941e-2afca2f7329f','Single leg get up into lunge','single-leg-get-up-into-lunge','Starting position: Lie flat on your back with arms at your sides and one leg extended straight up toward the ceiling. Execution: Roll up to sitting, then transition to standing on one leg before stepping back into a reverse lunge position.',ARRAY['Lie on your back with one leg extended toward the ceiling and the other leg bent with foot flat on the floor','Engage your core and use your arms to help roll up to a sitting position while keeping the raised leg elevated','Continue the movement by rolling forward and placing the raised leg down to stand on both feet','Once standing, immediately step the opposite leg back into a reverse lunge position','Lower your back knee toward the ground while keeping your front knee aligned over your ankle','Return to standing position to complete one repetition']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Control the rolling motion rather than using momentum to avoid straining your spine','Ensure your front knee stays aligned over your ankle during the lunge portion','Start with the movement slowly to master the coordination before increasing speed','Focus on smooth transitions between each phase of the exercise']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','functional','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c67b0b0a-c636-4cff-9628-8ecd1e5482ca','Single leg glute bridge','single-leg-glute-bridge-e281e4','Starting position: Lie on your back with one knee bent and foot flat on the floor, the other leg extended straight up toward the ceiling, arms resting alongside your body for stability. Execution: Drive through the heel of the planted foot to lift your hips off the ground until your body forms a straight line from shoulders to knee, then lower under control while keeping the free leg elevated.',ARRAY['Lie on your back with one foot flat on the floor and the opposite leg raised straight up.','Brace your core and press your arms into the floor for support.','Drive through the planted heel to lift your hips toward the ceiling.','Squeeze your glutes at the top, forming a straight line from shoulder to knee.','Lower your hips slowly back toward the floor without fully resting.','Complete all reps on one side, then switch legs.']::text[],ARRAY['Keep your hips level and avoid letting the raised side drop.','Squeeze the glutes at the top rather than arching the lower back.','Drive through the heel, not the toes, of the planted foot.','Maintain a controlled tempo on both the lift and the descent.']::text[],'glutes',ARRAY['erector_spinae','hip_flexors','abs']::text[],'bodyweight','strength','intermediate',ARRAY['strength','core','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c70ad438-dc0a-4933-8c68-81a09c6adaeb','Single-Arm Lat Pulldown','single-arm-lat-pulldown-fcbf75','Starting position: Sit at the lat pulldown machine with one hand gripping the handle overhead. Execution: Pull the handle down to your side while keeping your torso upright.',ARRAY['Sit at the lat pulldown machine facing forward','Grip the handle with one hand using overhand grip','Keep your torso upright and core engaged','Pull the handle down to your side smoothly','Squeeze your lat at the bottom position','Return to starting position with controlled movement']::text[],ARRAY['Keep your torso upright throughout the entire movement to prevent momentum','Focus on pulling with your lat muscle rather than your arm','Maintain a slight lean away from the working side for better range of motion','Control the weight on both the pulling and returning phases']::text[],'back',ARRAY['biceps','rear_deltoids','forearms']::text[],'machine','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','699bd3d1-89e8-449a-be4b-44ebee16d81f','Single-Leg Step Balance','single-leg-step-balance-72ac1e','Starting position: Stand tall in front of a low aerobic step with feet hip-width apart, arms relaxed at the sides, and core engaged. Execution: Place one foot flat on top of the step and shift your weight forward, balancing on the working leg while keeping the torso upright and stabilizing through the hip and ankle.',ARRAY['Stand upright facing the step with feet hip-width apart and core braced.','Place one foot flat on the center of the step surface.','Shift your weight onto the stepping leg while keeping the hips level.','Hold a stable, balanced position with the torso tall and gaze forward.','Lower the trailing foot back to the floor with control and repeat on the other side.']::text[],ARRAY['Keep the knee of the working leg aligned over the toes.','Engage the core to prevent leaning or twisting the torso.','Maintain level hips and avoid dropping to one side.','Press evenly through the whole foot on the step for stability.']::text[],'glutes',ARRAY['abductors','tibialis_anterior','erector_spinae']::text[],'box','balance','beginner',ARRAY['balance','functional','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','65ea17e1-f8ce-465a-ae0c-481bddb4714a','Sit ups','sit-ups','Starting position: Lie on your back with knees bent at 90 degrees, feet flat on the floor, and hands lightly placed behind your head or crossed over your chest. Execution: Contract your abdominal muscles to lift your shoulder blades off the ground, bringing your chest toward your knees, then slowly lower back down with control.',ARRAY['Lie flat on your back with knees bent and feet planted firmly on the floor hip-width apart','Place your hands lightly behind your head without interlacing fingers, or cross arms over your chest','Engage your core muscles and press your lower back into the floor','Slowly curl your upper body forward, lifting your shoulder blades off the ground while keeping your neck neutral','Hold briefly at the top position, then slowly lower back down until your shoulder blades touch the floor','Maintain controlled breathing throughout the movement, exhaling on the way up and inhaling on the way down']::text[],ARRAY['Keep your neck in a neutral position and avoid pulling on your head with your hands to prevent neck strain','Focus on using your abdominal muscles to initiate the movement rather than momentum or hip flexors','Maintain a slow and controlled tempo, taking 2-3 seconds to lift up and 2-3 seconds to lower down','Keep your feet flat on the floor throughout the entire movement to maintain stability and proper form','Only lift your shoulder blades off the ground - you don''t need to sit all the way up to effectively work your core muscles']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['core','strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c1b55b30-7913-4590-87e1-6aac94b23df6','Sitting Pelvic tilts','sitting-pelvic-tilts-08b48b','Starting position: Sit tall on a chair with feet flat on the floor, knees bent about 90 degrees, hands resting on thighs, and spine in a neutral position. Execution: Gently rock the pelvis forward and backward by alternately arching and rounding the lower back, moving smoothly through a comfortable range while keeping the upper body relatively still.',ARRAY['Sit upright on the edge of the chair with feet flat and hands on your thighs.','Slowly tilt your pelvis forward, arching the lower back and lifting the chest.','Reverse the motion by tucking the pelvis under, rounding the lower back gently.','Move rhythmically between the two positions in a controlled manner.','Keep breathing steadily and continue for the desired repetitions.']::text[],ARRAY['Keep the movement slow and controlled, isolating motion to the pelvis.','Avoid using momentum or moving the upper body excessively.','Maintain steady breathing throughout the exercise.','Perform within a pain-free, comfortable range of motion.']::text[],'lower_back',ARRAY['obliques','rectus_abdominis','spinal_erectors']::text[],'chair','mobility','beginner',ARRAY['mobility','rehabilitation','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1c9646ea-e5d6-4aaf-8892-12b331fcc8d2','Slingshot into T-Spine rotation','slingshot-into-t-spine-rotation','Starting position: Begin in a side plank position with one hand planted on the ground, body in a straight line, and the opposite arm extended overhead. Execution: Rotate the extended arm down and under the supporting side of your body, then return to the starting position with arm extended upward.',ARRAY['Start in a side plank position with your supporting hand planted firmly on the ground','Extend your top arm straight up toward the ceiling','Slowly rotate your extended arm down and thread it under your supporting side','Keep your hips elevated and core engaged throughout the movement','Return your arm back to the starting position overhead','Repeat for the desired number of repetitions before switching sides']::text[],ARRAY['Maintain a strong side plank position throughout the entire movement to protect your spine','Move slowly and controlled to maximize the thoracic spine mobility benefits','Keep your supporting shoulder stable and avoid collapsing onto your supporting arm','Focus on rotating through your upper back rather than just moving your arm','Breathe deeply during the movement to enhance the stretch and mobility gains']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['mobility','warmup','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b26cc5dc-4ecf-4e02-9528-02aa561e2b0e','Smith Bench Press (Flat)','smith-bench-press-flat-0fdd63','Starting position: Lie on bench under Smith machine bar positioned over mid-chest. Execution: Press bar straight up from chest to full arm extension and return.',ARRAY['Position bench so bar aligns with mid-chest','Grip bar with hands slightly wider than shoulders','Lower bar slowly to chest with control','Press bar straight up to full extension','Pause briefly at top before lowering again']::text[],ARRAY['Keep feet flat on floor for stable base','Maintain natural arch in lower back throughout movement','Bar should touch chest at nipple line, not neck','Control the weight on both lifting and lowering phases','Engage core muscles to protect spine during press']::text[],'chest','{}'::text[],'machine',null,null,ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3e923378-4af0-4d61-9ce7-263fb0ed3b04','Smith Machine Behind the Back Shrug','smith-machine-behind-the-back-shrug','Starting position: Stand in front of a Smith machine with the bar positioned behind your back at arm''s length, gripping the bar with an overhand grip slightly wider than shoulder-width. Execution: Lift your shoulders straight up toward your ears in a controlled shrugging motion, hold briefly at the top, then lower your shoulders back to the starting position.',ARRAY['Position yourself in the Smith machine with the bar behind your back and grip it with both hands using an overhand grip','Stand with feet shoulder-width apart and maintain a straight, upright posture throughout the movement','Engage your core and keep your arms straight as you lift your shoulders directly upward','Squeeze your trapezius muscles at the top of the movement and hold for a brief pause','Lower your shoulders back down to the starting position in a controlled manner','Complete the desired number of repetitions while maintaining proper form']::text[],ARRAY['Keep your arms straight throughout the entire movement to isolate the trapezius muscles','Focus on lifting your shoulders straight up rather than rolling them forward or backward','Maintain control during both the lifting and lowering phases of the exercise','Keep your core engaged to maintain proper posture and protect your lower back','Use a grip width that feels comfortable and allows for full range of motion']::text[],'back','{}'::text[],'machine','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d2122541-4c46-460f-be6a-7ea35e2d0624','Smith Machine Behind the Neck Press','smith-machine-behind-the-neck-press','Starting position: Position yourself in a Smith machine with the bar resting behind your neck and feet firmly planted on the floor. Execution: Press the bar upward until your arms are fully extended, then slowly lower to starting position.',ARRAY['Set the Smith machine bar at shoulder height and position a bench with back support directly underneath','Sit with your back firmly against the pad and grip the bar with palms facing forward, hands wider than shoulder-width','Position the bar at the base of your neck, ensuring your head is in a neutral position looking straight ahead','Unlock the bar and press it straight up by extending your arms fully overhead','Slowly lower the bar back to the starting position behind your neck with control','Re-rack the bar safely when completing your set']::text[],ARRAY['Only perform this exercise if you have excellent shoulder flexibility and no history of shoulder or neck injuries','Keep your core engaged and maintain the natural arch in your lower back throughout the movement','Use a much lighter weight than you would for standard overhead pressing movements due to the compromised shoulder position','Stop immediately if you feel any pain or discomfort in your shoulders or neck','Consider front military press as a safer alternative that targets the same muscle groups']::text[],'shoulders','{}'::text[],'machine','shoulders','advanced',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2b207100-576f-4029-848e-f71bb05df885','Smith Machine Bent Over Row','smith-machine-bent-over-row','Starting position: Position yourself at a Smith machine with a pronated grip (palms down) at shoulder width, torso bent forward. Execution: Pull the bar toward your chest while keeping your back straight, then lower slowly to the starting position.',ARRAY['Set the Smith machine bar at mid-shin height and add appropriate weight plates','Stand with feet hip-width apart, bend at hips and knees to grip the bar with hands slightly wider than shoulders','Keep your chest up, core engaged, and maintain a neutral spine throughout the movement','Pull the bar toward your lower chest by retracting your shoulder blades and driving elbows back close to your body','Squeeze your back muscles at the top of the movement for one second','Lower the bar slowly and under control back to the starting position without letting it touch the ground']::text[],ARRAY['Keep your core tight and avoid rounding your back to prevent injury','Focus on pulling with your back muscles rather than your arms by initiating the movement with shoulder blade retraction','Maintain a slight bend in your knees throughout the exercise to protect your lower back','Control the weight on both the lifting and lowering phases to maximize muscle engagement']::text[],'back','{}'::text[],'machine','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7afd4594-47c0-4061-97ec-6cf5f5b9ddfe','Smith Machine Bent Over Row','smith-machine-bent-over-row-14ddc3','Starting position: Stand with feet hip-width apart, gripping the Smith machine bar with an overhand grip while hinging at the hips. Execution: Pull the bar toward your lower chest by squeezing your shoulder blades together, then lower with control.',ARRAY['Set the Smith machine bar at mid-thigh height','Position feet hip-width apart under the bar','Hinge at hips and grip bar with overhand grip','Pull bar toward lower chest squeezing shoulder blades','Lower bar slowly to starting position','Repeat for desired number of repetitions']::text[],ARRAY['Keep your back straight and core engaged throughout the movement','Focus on pulling with your back muscles rather than your arms','Maintain a slight bend in your knees during the entire exercise','Avoid using momentum by controlling both the lifting and lowering phases','Keep your head in a neutral position looking slightly forward']::text[],'smith-machine','{}'::text[],'machine',null,null,ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','aeea2f3a-bcd5-44a0-9ca7-57977001e382','Smith Machine Bent Over Row Overhand Grip','smith-machine-bent-over-row-overhand-grip','Starting position: Position yourself at a Smith machine with an overhand grip (palms down) and hands shoulder-width apart. Execution: Pull the bar toward the lower chest while keeping your back straight, then slowly lower to the starting position.',ARRAY['Set the Smith machine bar at an appropriate height where you can maintain proper hip hinge position with the bar at mid-shin level','Position feet hip-width apart and grip the bar with an overhand grip slightly wider than shoulders','Hinge at the hips while maintaining a neutral spine, keeping your chest up and core engaged throughout the movement','Initiate the pull by retracting your shoulder blades first, then drive your elbows back toward your ribs','Squeeze your back muscles at the top of the movement, then slowly lower the bar back to starting position','Maintain the hip-hinged position throughout all repetitions without allowing your torso to rise up']::text[],ARRAY['Keep your core tight and maintain a neutral spine throughout the entire movement to protect your lower back','Focus on pulling with your back muscles rather than your arms by initiating each rep with shoulder blade retraction','Avoid using momentum or swinging the weight, maintaining smooth and controlled movement in both directions','Keep your elbows close to your body rather than flaring them out wide to maximize back muscle activation','Ensure you''re hinging at the hips rather than rounding your back to achieve the bent-over position']::text[],'back','{}'::text[],'machine','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b66b9294-0bfe-494f-b0aa-09602a7b5e41','Smith Machine Bent Over Row Underhand Grip','smith-machine-bent-over-row-underhand-grip','Starting position: Position yourself at a Smith machine with an underhand grip (palms up) and hands shoulder-width apart. Execution: Pull the bar toward the lower chest while keeping your back straight, then slowly lower to the starting position.',ARRAY['Set the Smith machine bar at about mid-thigh height and add appropriate weight','Stand with feet shoulder-width apart and grasp the bar with an underhand grip, hands slightly wider than shoulders','Hinge at the hips and lean forward while keeping your back straight and core engaged','Pull the bar towards your lower chest by driving your elbows back and squeezing your shoulder blades together','Hold the contraction briefly at the top of the movement','Slowly lower the bar back to the starting position with control']::text[],ARRAY['Keep your back straight throughout the entire movement to prevent injury','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Maintain a slight bend in your knees and keep your core tight for stability','Avoid using momentum and control both the lifting and lowering phases of the movement','Keep your head in a neutral position and avoid looking up or down excessively']::text[],'back','{}'::text[],'machine','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c72f4458-a48b-4d9c-bc4f-ddc01f3a8eaf','Smith Machine Deadlift','smith-machine-deadlift','Starting position: Stand in a Smith machine with feet shoulder-width apart and the bar resting on your upper thighs. Execution: Hinge at the hips and lower the bar toward the floor while keeping your back straight and knees slightly bent, then slowly return to starting position.',ARRAY['Set the bar at approximately mid-shin height and add appropriate weight plates','Position yourself with feet hip-width apart directly under the bar, ensuring it''s over your mid-foot','Bend at the hips first, then bend your knees to lower down and grip the bar with an overhand grip, hands shoulder-width apart','Engage your core, keep your chest up and shoulders back, then drive through your heels to lift the bar','Stand up straight by extending your hips and knees simultaneously, keeping the bar close to your body','Lower the weight back down by reversing the movement, hinging at the hips first']::text[],ARRAY['Keep your back straight and chest up throughout the entire movement to protect your spine','The bar should travel in a straight vertical line close to your body, not forward or backward','Focus on driving through your heels and engaging your glutes at the top of the movement','Use the Smith machine''s safety stops to prevent the bar from going too low if you lose control','Start with lighter weight to master the hip hinge movement pattern before progressing to heavier loads']::text[],'full_body','{}'::text[],'machine','full body','beginner',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5b61e155-eda8-4077-854b-bfe331f5fd55','Smith Machine Glute Squat','smith-machine-glute-squat','Starting position: Position yourself in a Smith machine with the bar resting on your upper back and feet slightly forward. Execution: Lower your body into a deep squat while focusing the effort on the glutes, then push up to return to the starting position.',ARRAY['Set the Smith machine bar at shoulder height and load appropriate weight','Position yourself under the bar with feet wider than shoulder-width and toes pointed outward','Unrack the bar by lifting and rotating the hooks, then step back slightly','Lower your body by sitting back into your hips while keeping your knees tracking over your toes','Descend until your thighs are parallel to the floor or as low as your mobility allows','Drive through your heels and squeeze your glutes to return to the starting position']::text[],ARRAY['Keep your weight distributed through your heels rather than your toes to maximize glute activation','Maintain a neutral spine throughout the movement by keeping your chest up and core engaged','Focus on pushing your hips back first rather than bending your knees to emphasize glute recruitment','Ensure your knees track in line with your toes and don''t cave inward during the movement','Control the descent and avoid bouncing at the bottom of the squat']::text[],'glutes','{}'::text[],'machine','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2291338b-1445-4b35-8ebe-d92d7af522e0','Smith Machine Good Morning','smith-machine-good-morning','Starting position: Position yourself in a Smith machine with the bar resting on your upper back and feet shoulder-width apart. Execution: Hinge forward at the hips while keeping your back straight and legs slightly bent, then slowly return to starting position.',ARRAY['Set the Smith machine bar at shoulder height and add appropriate weight plates','Position yourself under the bar with it resting on your upper traps, not your neck','Unlock the bar and step back slightly, placing feet shoulder-width apart with a slight knee bend','Initiate the movement by pushing your hips back and lowering your torso while keeping your back straight','Lower until you feel a good stretch in your hamstrings, typically when your torso is parallel to the floor','Drive your hips forward to return to the starting position and re-engage the safety locks when finished']::text[],ARRAY['Keep your core engaged throughout the entire movement to protect your lower back','Focus on the hip hinge movement rather than squatting down - the knees should only bend slightly','Maintain a neutral spine by keeping your chest up and shoulders pulled back','Control the descent and avoid bouncing at the bottom of the movement','Start with lighter weight to master the movement pattern before progressing to heavier loads']::text[],'hamstrings','{}'::text[],'machine','legs','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ea856b4b-ef97-4fa6-81a1-269f060df9c5','Smith Machine Hip Thrust','smith-machine-hip-thrust','Starting position: Position yourself with your back to a Smith machine, bar resting on your upper back and feet planted on the floor. Execution: Raise your hips upward while squeezing the glutes, then slowly lower to starting position.',ARRAY['Set the Smith machine bar to an appropriate height and add desired weight plates','Position a bench perpendicular to the Smith machine and sit with your upper back against it','Place the barbell across your hips with a pad or towel for comfort and plant feet firmly on the floor','Unrack the bar by lifting slightly and rotating the hooks away from the catches','Drive through your heels and squeeze glutes to lift hips up until your body forms a straight line from knees to shoulders','Lower the weight slowly and under control back to starting position, maintaining tension in the glutes']::text[],ARRAY['Keep your core engaged throughout the movement to prevent lower back hyperextension','Focus on driving the movement through your glutes rather than pushing with your lower back','Maintain a neutral spine position and avoid letting your knees cave inward during the thrust','Use adequate padding across your hips to prevent discomfort from the barbell','Ensure the bench is stable and positioned correctly to support your upper back safely']::text[],'glutes',ARRAY['hamstrings','quads','core','adductors']::text[],'machine','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','43549b73-858b-4225-8fe0-e7d3d32c9535','Smith Machine Incline Press','smith-machine-incline-press','Starting position: Position yourself in a Smith machine with the bench set at an incline and the bar secured at the top. Execution: Lower the bar to chest, then push up to return to starting position.',ARRAY['Set the bench to a 30-45 degree incline and position it so the bar aligns with your upper chest when lying down','Lie back with your shoulder blades squeezed together, core engaged, and feet flat on the floor for stability','Grip the bar with hands slightly wider than shoulder-width apart using an overhand grip','Unrack the bar by rotating it forward, then lower it slowly to your upper chest while keeping your elbows at a 45-degree angle','Press the bar back up in a smooth, controlled motion until your arms are fully extended but not locked out','Rotate the bar back to rack it safely when completing your set']::text[],ARRAY['Keep your wrists straight and aligned with your forearms throughout the entire movement to prevent injury','Maintain constant tension in your chest muscles by not fully locking out your elbows at the top of the movement','Control the negative portion of the lift by taking 2-3 seconds to lower the bar to maximize muscle engagement','Never lift your lower back off the bench pad as this can lead to injury and reduces exercise effectiveness','Always use the safety stops on the Smith machine as a backup in case you cannot complete a repetition']::text[],'chest','{}'::text[],'machine','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','90421a51-69d9-4f27-9076-847dff2d882a','Smith Machine Lunge','smith-machine-lunge','Starting position: Position yourself in a Smith machine with one leg forward and the other back. Execution: Lower your body toward the floor by bending both knees, then push upward to return to the starting position and repeat with the other leg.',ARRAY['Position the Smith machine bar at shoulder height and step under it, resting it across your upper trapezius muscles','Take a large step forward with one foot while keeping the other foot back, creating a staggered stance','Keep your torso upright and core engaged throughout the movement','Lower your body by bending both knees until your back knee is just above the ground','Push through your front heel to return to the starting position','Complete all reps on one leg before switching to the other side']::text[],ARRAY['Keep most of your weight on your front leg and avoid pushing off your back toe','Maintain an upright torso position to maximize quad engagement and prevent lower back strain','Ensure your front knee tracks over your toes and doesn''t cave inward during the movement','Control the descent slowly to maximize muscle activation and prevent injury']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','913dc03f-d923-43c5-9e7f-461c26770ee1','Smith Machine Lunge','smith-machine-lunge-913dc03f','Starting position: Position yourself in a Smith machine with one leg forward and the other back. Execution: Lower your body toward the floor by bending both knees, then push upward to return to the starting position and repeat with the other leg.',ARRAY['Position the Smith machine bar at shoulder height and step under it, resting it on your upper trapezius muscles','Take a large step forward with one foot while keeping the other foot planted behind you, creating a wide stance','Engage your core and maintain an upright torso throughout the movement','Lower your body by bending both knees simultaneously until your front thigh reaches parallel to the floor','Push through your front heel to drive yourself back up to the starting position','Complete all repetitions on one leg before switching to the other side']::text[],ARRAY['Keep most of your weight on your front leg while using the back leg primarily for balance and stability','Ensure your front knee tracks in line with your toes and does not cave inward during the movement','Maintain an upright torso position and avoid leaning too far forward or backward','Descend in a controlled manner and avoid bouncing at the bottom of the movement','The Smith machine provides stability but still requires proper form and core engagement']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','15ae3c6a-9e5c-43c6-a9df-6a1cd454e1c5','Smith Machine Lunges','smith-machine-lunges-14a431','Starting position: Stand under the Smith machine bar with one foot forward in a lunge stance. Execution: Lower into a lunge by bending both knees, then push back up to starting position.',ARRAY['Position the bar across your upper back and shoulders','Step one foot forward into a lunge stance','Lower your body by bending both knees simultaneously','Keep your front knee aligned over your ankle','Push through your front heel to return upright','Complete all reps before switching legs']::text[],ARRAY['Keep your torso upright and core engaged throughout the movement','Ensure your front knee tracks in line with your toes','Lower until your back knee nearly touches the ground','Avoid letting your front knee extend past your toes','Use the Smith machine''s stability to focus on proper form']::text[],'smith-machine',ARRAY['adductors','erector_spinae','abs']::text[],'machine','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','74545eb6-14ac-4017-b275-d1776516419d','Smith Machine Narrow Stance Squat','smith-machine-narrow-stance-squat','Starting position: Position yourself in a Smith machine with the bar resting on your upper back and feet together. Execution: Lower your body into a deep squat while keeping feet together, then push upward to return to the starting position.',ARRAY['Position the bar at chest height on the Smith machine and step underneath it, placing the bar on your upper traps','Take a narrow stance with feet about hip-width apart and toes slightly turned out','Unrack the bar by lifting slightly and rotating the hooks, then brace your core','Initiate the descent by pushing your hips back and bending your knees while keeping your chest up','Lower until your thighs are parallel to the floor or as deep as your mobility allows','Drive through your heels and push the floor away to return to the starting position']::text[],ARRAY['Keep your knees tracking in line with your toes throughout the entire movement to prevent knee valgus','Maintain a neutral spine by keeping your chest up and avoiding excessive forward lean','The narrow stance emphasizes the quadriceps more than a wider stance would','Control the descent speed and avoid bouncing at the bottom of the movement','Ensure full hip extension at the top without locking out aggressively']::text[],'quads','{}'::text[],'machine','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3f9f3976-7e6c-4d69-8801-1b0b5f723a68','Smith Machine Romanian Deadlift','smith-machine-romanian-deadlift-029199','Starting position: Stand with feet hip-width apart, holding the smith machine bar at hip level with an overhand grip. Execution: Hinge at hips while keeping legs relatively straight, lower the bar along your legs, then drive hips forward to return to starting position.',ARRAY['Set the smith machine bar at hip height','Stand with feet hip-width apart under the bar','Grip the bar with both hands shoulder-width apart','Hinge at hips while sliding bar down your legs','Drive hips forward to return to starting position','Unlock and re-rack the bar when finished']::text[],ARRAY['Keep your back straight and chest up throughout the movement','Push your hips back rather than bending your knees excessively','Maintain a slight bend in your knees throughout the exercise','Feel the stretch in your hamstrings at the bottom position','Keep the bar close to your body during the entire movement']::text[],'smith-machine',ARRAY['glute_max','spinal_erectors','forearm_flexors']::text[],'machine','strength','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','691ad2e7-b9f9-4921-8831-4da317451a2c','Smith Machine Shoulder Press','smith-machine-shoulder-press','Starting position: Sit in a Smith machine with the bar held at the top. Execution: Lower the bar toward your shoulders, then push upward to return to the starting position.',ARRAY['Adjust the bench so the bar aligns with your shoulders when seated','Set the safety stops just below shoulder level as a precaution','Grip the bar with palms facing forward, hands slightly wider than shoulders','Keep your core engaged and back pressed firmly against the pad throughout the movement','Press the bar straight up in a controlled motion until arms are fully extended','Lower the bar slowly back to shoulder level, maintaining control throughout the descent']::text[],ARRAY['Keep your wrists straight and aligned with your forearms to prevent injury','Avoid pressing the bar behind your neck as this can strain the shoulder joint','Maintain a slight forward lean of the torso to follow the natural bar path of the Smith machine','Breathe out during the pressing motion and breathe in while lowering the weight','Stop the descent when the bar reaches ear level or when you feel a comfortable stretch in the shoulders']::text[],'shoulders','{}'::text[],'machine','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b3d09e97-408c-4eb9-8900-ddc99a9a4218','Smith Machine Shrug','smith-machine-shrug','Starting position: Position yourself at a Smith machine with the bar resting on your upper back. Execution: Shrug your shoulders upward as high as possible, then slowly lower to the starting position.',ARRAY['Set the Smith machine bar at mid-thigh height and add appropriate weight plates','Stand with feet shoulder-width apart and grip the bar with both hands using an overhand grip','Keep your arms straight and let the bar hang at arm''s length against your thighs','Lift your shoulders straight up as high as possible while keeping your arms extended','Hold the contracted position for 1-2 seconds at the top of the movement','Slowly lower your shoulders back to the starting position in a controlled manner']::text[],ARRAY['Keep your head in a neutral position and avoid rolling your shoulders forward or backward during the movement','Focus on lifting your shoulders straight up rather than pulling with your arms to properly target the trapezius muscles','Use a full range of motion by lifting as high as possible and allowing a complete stretch at the bottom','Maintain proper posture throughout the exercise by keeping your chest up and core engaged','Start with lighter weight to master the form before progressing to heavier loads']::text[],'back','{}'::text[],'machine','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','680f31da-707a-487d-9003-667fb3bbab82','Smith Machine Smith Bench Press flat','smith-machine-smith-bench-press-flat-1cbe39','Starting position: Lie flat on the bench positioned under the Smith machine bar with feet firmly planted on the floor, grip the bar slightly wider than shoulder-width, and unrack it by rotating the wrists. Execution: Lower the bar in a controlled manner to the mid-chest, then press it back up along the fixed vertical track until the arms are fully extended.',ARRAY['Lie flat on the bench and align your eyes under the Smith machine bar.','Grip the bar slightly wider than shoulder-width and rotate to unrack it.','Lower the bar slowly to your mid-chest while keeping elbows at about 45 degrees.','Press the bar back up along the guided track until your arms are extended.','Repeat for the desired reps, then rotate the bar to re-rack safely.']::text[],ARRAY['Keep your shoulder blades retracted and pressed into the bench.','Maintain feet flat on the floor for a stable base.','Do not bounce the bar off your chest; control the descent.','Avoid fully locking out the elbows harshly at the top.']::text[],'chest',ARRAY['front_deltoids','triceps','serratus_anterior']::text[],'machine','strength','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8456ccc7-a3af-4d7d-8524-2ed90c57fc9e','Smith Machine Smith Calf Raise','smith-machine-smith-calf-raise-3ce1b9','Starting position: Stand upright inside the Smith machine with the bar resting across your upper traps or held at the sides, feet hip-width apart with the balls of your feet on a slightly elevated surface or flat floor, heels free to drop. Execution: Press through the balls of your feet to raise your heels as high as possible, squeezing the calves at the top, then lower under control to a full stretch and repeat.',ARRAY['Position yourself under or beside the Smith machine bar with feet hip-width and balls of feet firmly planted.','Unrack the bar and keep your torso upright and core braced.','Drive through the balls of your feet to lift your heels as high as possible.','Pause and squeeze the calves at the top of the movement.','Lower your heels slowly to a full stretch below the platform level.','Repeat for the desired number of repetitions before racking the bar.']::text[],ARRAY['Move slowly through the full range, emphasizing the stretch at the bottom.','Keep knees slightly soft but avoid bending to isolate the calves.','Pause and squeeze hard at the top for maximum contraction.','Maintain an upright torso and braced core throughout.']::text[],'calves',ARRAY['gastrocnemius','soleus','tibialis_anterior']::text[],'machine','strength','beginner',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','427f98b5-d33e-4447-83cd-5cef54f0eb2f','Smith Machine Squat','smith-machine-squat','Starting position: Position yourself in a Smith machine with the bar resting on upper back and feet shoulder-width apart. Execution: Lower body into a deep squat while keeping back straight, then push up to return to starting position.',ARRAY['Set the Smith machine bar at upper chest height and add appropriate weight plates','Position yourself under the bar with feet shoulder-width apart and the bar resting on your upper traps','Grip the bar with hands wider than shoulder-width and unlock the bar by rotating it','Lower your body by pushing hips back and bending knees, keeping chest up and core engaged','Descend until thighs are parallel to the floor or as low as mobility allows','Drive through your heels and push the floor away to return to starting position']::text[],ARRAY['Keep your knees tracking in line with your toes throughout the entire movement','Maintain a neutral spine with chest up and avoid rounding your back','Control the descent and avoid bouncing at the bottom of the squat','Place feet slightly forward of the bar since the Smith machine moves in a fixed vertical path','Engage your core throughout the movement to protect your lower back']::text[],'quads',ARRAY['calves','hip_flexors','abs']::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','75ad8ef1-8f36-47b9-baef-e7efd2b88c9d','Smith Machine Squats','smith-machine-squats-8a8a90','Starting position: Stand under the Smith machine bar with feet shoulder-width apart, bar resting on your upper traps. Execution: Lower into a squat by pushing hips back and bending knees, then drive through heels to return to standing.',ARRAY['Position bar on upper traps and grip handles firmly','Set feet shoulder-width apart with toes slightly outward','Unlock the bar and brace your core','Lower by pushing hips back and bending knees','Descend until thighs are parallel to floor','Drive through heels to return to starting position']::text[],ARRAY['Keep your chest up and maintain a neutral spine throughout the movement','Ensure knees track in line with your toes during the descent','The Smith machine''s fixed bar path provides stability for beginners','Control the descent and avoid bouncing at the bottom position','Re-rack the bar securely by rotating the handles after completing your set']::text[],'smith-machine','{}'::text[],'machine',null,null,ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ab582577-f6d5-4f62-9f5a-220995d7910f','Smith Machine Step-Ups','smith-machine-step-ups','Starting position: Stand facing a Smith machine with one foot on a bench. Execution: Push with the foot on the bench to raise the body, then slowly lower to starting position. Repeat with the other leg.',ARRAY['Set the Smith machine bar at upper chest height and position a stable bench or platform perpendicular to the bar','Load the bar with appropriate weight and step under it, positioning the bar on your upper trapezius muscles','Grasp the bar with hands wider than shoulder-width apart and stand upright facing the bench','Step up onto the bench with your right foot, placing your entire foot firmly on the surface','Drive through your right heel to lift your body up until your right leg is fully extended, bringing your left foot up to meet the platform briefly','Step back down with your left foot first, then your right foot, maintaining control throughout the descent','Complete all repetitions on one leg before switching to the other leg','Re-rack the bar safely when finished with both legs']::text[],ARRAY['Keep your torso upright throughout the movement to maintain proper spinal alignment and maximize quadriceps activation','Drive through the heel of your stepping leg rather than pushing off your toes to ensure proper muscle engagement','Control the descent portion of the movement to prevent jarring impact on your knees and maximize time under tension','Use a platform height that allows your hip to be at or slightly below knee level when your foot is planted to ensure full range of motion','Avoid using momentum or bouncing off the platform, focusing instead on smooth, controlled movements']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e656576b-39d4-4623-a93d-c455bd640b01','Smith Machine Sumo Squat','smith-machine-sumo-squat-e656576b','Starting position: Position yourself in a Smith machine with the bar resting on your upper back and feet wider than shoulder-width apart, toes slightly pointed outward. Execution: Lower your body into a deep squat while keeping your back straight, then push upward to return to starting position.',ARRAY['Adjust the Smith machine bar to upper chest height and add appropriate weight plates','Position yourself under the bar with feet in a wide sumo stance, toes turned out 45 degrees','Unrack the bar by lifting and rotating the safety hooks, keeping your core engaged','Lower your body by sitting back into your hips while keeping knees tracking over toes','Descend until your thighs are parallel to the floor or as low as mobility allows','Drive through your heels and push the floor away to return to starting position']::text[],ARRAY['Keep your knees aligned with your toes throughout the movement to prevent knee valgus','Maintain an upright torso with chest up and shoulders back to protect your lower back','Focus on pushing through your heels rather than your toes to maximize quad and glute activation','Control the descent and avoid bouncing at the bottom of the movement','Engage your core throughout the entire range of motion for spinal stability']::text[],'quads','{}'::text[],'machine','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f7c6095d-b060-48e6-81be-461e81a578a7','Smith Machine Sumo Squat','smith-machine-sumo-squat-f7c6095d','Starting position: Position yourself in a Smith machine with the bar resting on your upper back and feet wider than shoulder-width apart, toes slightly pointed outward. Execution: Lower your body into a deep squat while keeping your back straight, then push upward to return to the starting position.',ARRAY['Set the Smith machine bar at about chest height and add appropriate weight plates','Position yourself under the bar with feet wider than shoulder-width apart and toes angled outward','Grip the bar with hands wider than shoulder-width and unrack by lifting and rotating the bar','Keep your core engaged and chest up as you lower down until your thighs are parallel to the floor','Drive through your heels and inner thighs to push back up to starting position','Re-rack the bar by rotating it back into the safety catches when finished']::text[],ARRAY['Keep your knees aligned with your toes throughout the movement to prevent knee injury','Maintain an upright torso and avoid leaning too far forward to protect your lower back','Focus on pushing through your heels rather than your toes to maximize quad and glute activation','Control the descent and avoid bouncing at the bottom of the movement','Keep your core tight throughout the entire range of motion for stability']::text[],'quads','{}'::text[],'machine','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','252e37ea-e936-42a4-ba76-d7ce35e1baa6','Smith Machine Sumo Squat','smith-machine-sumo-squat','Starting position: Position yourself in a Smith machine with the bar resting on your upper back and feet wider than shoulder-width with toes pointed slightly outward. Execution: Lower your body into a deep squat while keeping your back straight, then push up to return to starting position.',ARRAY['Set the Smith machine bar at shoulder height and add appropriate weight plates','Position yourself under the bar with feet in a wide sumo stance, toes pointed outward','Unrack the bar by lifting slightly and rotating the hooks forward','Lower your body by sitting back into your hips while keeping your chest up and knees tracking over your toes','Descend until your thighs are parallel to the floor or as low as your mobility allows','Drive through your heels and squeeze your glutes to return to the starting position']::text[],ARRAY['Keep your knees aligned with your toes throughout the entire movement to prevent knee injury','Maintain a neutral spine by keeping your chest up and avoiding excessive forward lean','Focus on pushing through your heels rather than your toes to maximize quad and glute activation','Control the descent and avoid bouncing at the bottom of the movement','Engage your core throughout the exercise to maintain stability and protect your lower back']::text[],'quads','{}'::text[],'machine','legs','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','95b3c40f-4a12-44e6-ac2e-cd7ce4a3cc3c','Smith Machine Upright Row','smith-machine-upright-row','Starting position: Position yourself at a Smith machine with a pronated grip and hands shoulder-width apart. Execution: Pull the bar toward the lower chest, keeping elbows close to the body, then slowly lower to starting position.',ARRAY['Set the Smith machine bar to a height where your arms are fully extended when grasping it at thigh level','Position yourself with feet shoulder-width apart and grip the bar with hands closer than shoulder-width using an overhand grip','Engage your core and maintain an upright posture with shoulders back and chest up','Pull the bar straight up by lifting your elbows high and out to the sides, keeping the bar close to your body','Stop when the bar reaches upper chest level with elbows higher than your wrists','Lower the bar slowly and controlled back to the starting position at thigh level']::text[],ARRAY['Keep your grip narrower than shoulder-width to properly target the deltoids and avoid impingement','Lift your elbows higher than your wrists throughout the movement to maximize shoulder activation','Avoid pulling the bar too high above chest level as this can cause shoulder impingement','Maintain control during the lowering phase to maximize muscle engagement and prevent injury','Keep the bar path straight and close to your body throughout the entire range of motion']::text[],'shoulders','{}'::text[],'machine','shoulders','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c490cf34-6f30-421c-9dbb-d30b5f796efd','Sphinx pose','sphinx-pose',null,ARRAY['Lie face down and place your forearms on the floor with elbows under shoulders.','Press your forearms into the floor and lift your chest.','Keep your legs extended and the tops of your feet on the floor.','Hold and breathe, gently lifting through the chest.']::text[],ARRAY['Keep your shoulders away from your ears.','Engage your lower back muscles gently.','This is a gentle backbend - do not force.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bda13030-b09a-4fec-ada4-ec2d528db0d7','Spider Curl','spider-curl','Starting position: Lie face down on an inclined bench with a dumbbell in each hand hanging downward. Execution: Bend your elbows to lift the dumbbells toward your shoulders, then slowly lower.',ARRAY['Set an incline bench to 45-60 degrees and lie face down with your chest against the pad','Allow your arms to hang straight down from your shoulders while gripping a dumbbell in each hand','Keep your upper arms perpendicular to the floor throughout the entire movement','Curl the weights up by contracting your biceps until you achieve peak contraction','Slowly lower the dumbbells back to the starting position with control','Maintain contact between your chest and the bench pad at all times']::text[],ARRAY['Keep your upper arms completely stationary and perpendicular to the floor to isolate the biceps effectively','Use a full range of motion by allowing the arms to fully extend at the bottom and achieving peak contraction at the top','Control the eccentric portion of the movement to maximize muscle tension and prevent momentum','Choose a weight that allows you to maintain proper form throughout all repetitions','Avoid swinging or using your shoulders to assist with the movement']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2fc3cb39-6cf3-4133-89fd-6b140c96110f','Spiderman push up','spiderman-push-up','Starting position: Begin in a standard push-up position with hands placed shoulder-width apart and body in a straight line from head to heels. Execution: Lower into a push-up while simultaneously bringing one knee toward the elbow on the same side, then push up and return the leg to starting position before alternating sides.',ARRAY['Start in a plank position with hands directly under shoulders and core engaged','Lower your chest toward the ground while bringing your right knee toward your right elbow','Keep your hips level and avoid rotating your torso as you bring the knee forward','Push through your palms to return to the starting position while extending your leg back','Repeat the movement on the opposite side, bringing your left knee to your left elbow','Continue alternating sides for the desired number of repetitions']::text[],ARRAY['Maintain a tight core throughout the entire movement to prevent hip sagging or excessive rotation','Keep your supporting leg straight and strong while the other leg performs the knee drive','Focus on controlled movement rather than speed to maximize muscle engagement and maintain proper form','Ensure your knee tracks toward the outside of your elbow rather than across your body','If the full movement is too challenging, modify by performing the push-up and leg movement separately']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d26ca6be-632d-4674-a520-6a2144d76137','Split squat (L)','split-squat-l','Starting position: Stand in a staggered stance with your left foot forward and right foot back, maintaining an upright torso with hands positioned at your sides. Execution: Lower your body by bending both knees until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.',ARRAY['Position your left foot forward and right foot back in a wide staggered stance','Keep your torso upright with your core engaged throughout the movement','Lower your body by bending both knees, dropping your back knee toward the ground','Descend until your front thigh is parallel to the floor','Push through your front heel to drive back up to the starting position','Maintain your weight primarily on your front leg throughout the exercise']::text[],ARRAY['Keep most of your weight on your front leg rather than pushing off the back foot','Maintain an upright torso position and avoid leaning forward during the movement','Control the descent to avoid dropping too quickly into the bottom position','Ensure your front knee tracks in line with your toes and doesn''t cave inward','Focus on pushing through your front heel when returning to the starting position']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2811e435-2e2e-4b25-8fbb-57873e05d90d','Split squat (R)','split-squat-r','Starting position: Stand with your right foot forward and left foot back in a staggered stance, with feet hip-width apart and weight evenly distributed. Execution: Lower your body by bending both knees until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.',ARRAY['Position your right foot forward and left foot back with feet hip-width apart, keeping most of your weight on your front leg','Keep your torso upright and core engaged throughout the movement','Lower your body by bending both knees, dropping your back knee toward the ground while keeping your front knee aligned over your ankle','Descend until your front thigh is parallel to the floor or as low as comfortable','Push through your front heel to return to the starting position','Complete all repetitions on the right leg before switching to the left leg']::text[],ARRAY['Keep your front knee aligned over your ankle and avoid letting it cave inward','Maintain an upright torso position and avoid leaning too far forward','Focus your weight on your front leg while using your back leg primarily for balance','Control the descent and avoid bouncing at the bottom of the movement','Keep your core engaged to maintain stability throughout the exercise']::text[],'quads','{}'::text[],'dumbbell','legs','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3cd37329-4822-44d9-ba76-66a845736ffe','Sprinter Butt bridges','sprinter-butt-bridges','Starting position: Lie on your back with knees bent, feet flat on the floor hip-width apart, and arms at your sides for stability. Execution: Drive through your heels to lift your hips up into a bridge position, then alternate bringing one knee toward your chest while maintaining the bridge, mimicking a sprinting motion.',ARRAY['Lie flat on your back with knees bent at 90 degrees and feet planted firmly on the floor','Engage your core and squeeze your glutes to lift your hips off the ground into a bridge position','Keep your hips elevated while bringing your right knee toward your chest in a controlled motion','Lower your right foot back to the starting position and immediately bring your left knee toward your chest','Continue alternating legs in a rhythmic sprinting motion while maintaining the bridge position throughout','Lower your hips back down to complete the set']::text[],ARRAY['Keep your hips elevated throughout the entire exercise to maintain constant tension on the glutes','Focus on driving through the heel of the planted foot to maximize glute activation','Maintain a neutral spine and avoid overarching your back during the bridge position','Control the knee drive movement rather than letting momentum take over','Squeeze your glutes at the top of each bridge to ensure proper muscle engagement']::text[],'glutes','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','37b88680-2d07-424c-b1cb-8c1a3384e8dc','Squat','squat-904def','Starting position: Stand tall with feet shoulder-width apart, toes pointing slightly outward, and hands clasped in front of the chest for balance. Execution: Push the hips back and bend the knees to lower into a squat, keeping the chest up and back neutral, then drive through the heels to return to standing.',ARRAY['Stand with feet shoulder-width apart and clasp your hands in front of your chest.','Initiate the movement by pushing your hips back and bending your knees.','Lower until your thighs are at least parallel to the floor, keeping your chest lifted.','Keep your knees tracking in line with your toes throughout.','Drive through your heels to extend the hips and knees back to standing.','Squeeze your glutes at the top and repeat for the desired reps.']::text[],ARRAY['Keep your heels flat on the floor and weight centered over the midfoot.','Maintain a neutral spine and avoid rounding the lower back.','Ensure knees stay aligned with toes and do not collapse inward.','Brace your core throughout to protect the spine.']::text[],'quads',ARRAY['calves','hip_flexors','abs']::text[],'bodyweight','strength','beginner',ARRAY['strength','functional','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','31acb39d-e5bd-47f6-8895-0d4a17ff2e67','Squat Pulse on Box','squat-pulse-on-box-d8aa3c','Starting position: Stand in front of a plyo box with feet shoulder-width apart, hands clasped in front of the chest, and hips lowered into a squat until the glutes lightly touch or hover just above the box. Execution: Perform small, controlled up-and-down pulses within the bottom range of the squat while keeping constant tension in the legs and glutes, using the box as a depth guide.',ARRAY['Stand facing away from the box with feet shoulder-width apart and clasp your hands at chest height.','Lower into a squat until your glutes lightly graze the top of the box.','Rise a few inches, then descend again in a small pulsing motion.','Keep the movement shallow and continuous, maintaining tension throughout.','Drive through your heels on each pulse and keep your chest lifted.','Repeat for the prescribed number of reps or time.']::text[],ARRAY['Keep your knees tracking over your toes and avoid caving inward.','Maintain a neutral spine with chest up and core braced.','Keep the pulses small and controlled to sustain muscle tension.','Use the box only as a depth reference, not to fully rest on.']::text[],'quadriceps',ARRAY['hip_flexors','erector_spinae','abs']::text[],'box','strength','beginner',ARRAY['strength','functional','isometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2cb2c89f-5ea0-49f4-8ee3-a24beb2fa192','Squat taps into jump squats','squat-taps-into-jump-squats',null,ARRAY['Start in squat position','Explode up, jumping off floor','Land softly with bent knees','Immediately descend into next squat']::text[],ARRAY['Land softly (quiet landings)','Absorb impact with legs','Don''t lock knees on landing','Power comes from legs and hips','Great for explosive power']::text[],'quads','{}'::text[],'bodyweight','legs',null,ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f4484f32-c4a6-4111-8681-7d3d05a43f81','Squat thruster','squat-thruster','Starting position: Stand with feet shoulder-width apart, arms at your sides or hands clasped in front of your chest. Execution: Lower into a deep squat, then explosively drive through your heels to jump up while extending your arms overhead, landing softly and immediately transitioning into the next repetition.',ARRAY['Stand with feet shoulder-width apart and engage your core throughout the movement','Lower into a squat by pushing your hips back and bending your knees until thighs are parallel to the floor','Keep your chest up and weight distributed evenly across your feet during the squat phase','Explosively drive through your heels to jump up while simultaneously extending your arms overhead','Land softly on the balls of your feet with bent knees to absorb the impact','Immediately flow into the next squat to maintain continuous movement']::text[],ARRAY['Keep your knees tracking in line with your toes throughout the entire movement to prevent injury','Focus on soft landings by bending your knees upon impact to reduce stress on joints','Maintain proper squat depth with thighs parallel to the floor before exploding upward','Use your arms as momentum builders by driving them overhead during the jump phase','Start with slower, controlled movements before progressing to faster, more explosive repetitions']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','89fc3afb-7650-4bcd-9f82-726dd15e6600','Squat to alternating toe taps','squat-to-alternating-toe-taps','Starting position: Stand with feet shoulder-width apart, arms at your sides or crossed over your chest. Execution: Perform a squat, then as you rise, lift one leg and tap your toe to the side, return to center, squat again, and alternate toe taps.',ARRAY['Stand with feet shoulder-width apart and engage your core','Lower into a squat by pushing your hips back and bending your knees while keeping your chest up','Drive through your heels to return to standing position','Lift one leg out to the side and tap your toe on the ground','Return the leg to center and immediately lower into another squat','Rise up and perform a toe tap with the opposite leg, continuing to alternate']::text[],ARRAY['Keep your weight on your standing leg during toe taps and avoid shifting all weight to the tapping foot','Maintain proper squat form with knees tracking over toes and chest lifted throughout the movement','Control the tempo and avoid rushing through the toe taps to maintain balance','Keep your core engaged throughout the entire sequence to stabilize your torso']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','911577a1-55e3-4bf2-b7a0-6456422c3393','Squat to Cable Row','squat-to-cable-row','Starting position: Stand facing a low pulley with a rope attachment and feet shoulder-width apart. Execution: Lower your body into a squat while pulling the rope toward your chest, then push upward to return to the starting position.',ARRAY['Set the cable machine to chest height and select an appropriate weight that allows proper form throughout the movement','Stand facing the cable machine with feet shoulder-width apart, toes slightly pointed outward, and grasp the handle with both hands','Initiate the movement by pushing your hips back and bending your knees to lower into a squat while simultaneously pulling the cable handle toward your chest','Keep your chest up, core engaged, and ensure your knees track over your toes during the squat portion','Pull your shoulder blades together as you row the cable, focusing on squeezing your back muscles','Return to the starting position by standing up from the squat while extending your arms forward in a controlled manner']::text[],ARRAY['Maintain proper squat form by keeping your weight in your heels and avoiding knee collapse inward','Coordinate the timing so that you reach the bottom of your squat at the same time as completing the rowing motion','Keep your core tight throughout the entire movement to protect your lower back and maintain stability','Use a weight that allows you to control both the squat and rowing portions without compromising form','Focus on the eccentric portion of both movements by controlling the descent into the squat and the extension of your arms']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0b7c9826-2501-4938-a921-a6f62e66e890','Squat to toe taps','squat-to-toe-taps',null,ARRAY['Stand with feet hip-width apart, toes pointing slightly outward, arms at your sides','Lower into a squat by pushing your hips back and bending your knees, keeping your chest up and weight in your heels','From the squat position, reach down and lightly tap your toes with your fingertips while maintaining the squat','Return your arms to starting position while staying in the squat','Drive through your heels to return to standing position','Repeat for desired repetitions']::text[],ARRAY['Keep your knees tracking over your toes throughout the movement','Maintain a neutral spine and avoid rounding your back when reaching for your toes','Only lower as deep as your mobility allows while keeping proper form','Focus on controlled movement rather than speed','If you cannot reach your toes, reach as far as comfortable without compromising form']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d9836ac9-8688-41b0-a99c-e03370f53c2c','Squats into fly jacks','squats-into-fly-jacks','Starting position: Stand with feet shoulder-width apart, arms at your sides. Execution: Perform a squat by lowering your hips back and down, then as you stand up, jump and spread your legs wide while bringing your arms out to the sides in a flying motion, then jump back to the starting squat position.',ARRAY['Stand with feet shoulder-width apart and engage your core muscles','Lower into a squat by pushing your hips back and bending your knees while keeping your chest up','Drive through your heels to explosively stand up and immediately jump into the air','While airborne, spread your legs wide and extend your arms out to the sides at shoulder height','Land softly with feet wide apart and arms extended, then quickly jump back to the starting squat position','Maintain control throughout the movement and land with bent knees to absorb impact']::text[],ARRAY['Keep your chest up and avoid rounding your back during the squat portion','Land softly on the balls of your feet to reduce impact on joints','The arm movement during the jump primarily engages the chest muscles through the fly motion','Maintain a steady rhythm but prioritize proper form over speed','Start with shorter sessions and gradually increase intensity as your conditioning improves']::text[],'chest','{}'::text[],'bodyweight','chest','intermediate',ARRAY['cardio','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','83a25d92-34c9-43cd-aeac-6af796aa9c6b','Squats to knee','squats-to-knee','Starting position: Stand with feet shoulder-width apart, toes slightly turned out, and arms at your sides or extended forward for balance. Execution: Lower your body by bending at the hips and knees until your thighs are parallel to the floor, then push through your heels to return to the starting position.',ARRAY['Stand with feet shoulder-width apart and engage your core muscles','Keep your chest up and shoulders back throughout the entire movement','Lower your body by pushing your hips back and bending your knees as if sitting in a chair','Descend until your thighs are parallel to the floor or as low as your mobility allows','Push through your heels and squeeze your glutes to return to the starting position','Maintain control throughout both the lowering and rising phases']::text[],ARRAY['Keep your knees aligned with your toes and avoid letting them cave inward','Maintain a neutral spine by keeping your chest up and avoiding rounding your back','Distribute your weight evenly across your feet, focusing on pushing through your heels','Control the descent to maximize muscle engagement and prevent injury','Stop at a depth that maintains proper form rather than forcing excessive range of motion']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5efb3847-ecf2-4dba-9bc0-cce91af31eac','Squats to knee(1)','squats-to-knee1','Starting position: Stand with feet hip-width apart, arms at your sides or crossed over your chest. Execution: Lower your body by bending at the hips and knees until your thighs are parallel to the floor (knee level), then return to standing position.',ARRAY['Stand with feet hip-width apart, toes pointing slightly outward','Keep your chest up and core engaged throughout the movement','Initiate the movement by pushing your hips back and bending your knees','Lower your body until your thighs are parallel to the floor, ensuring knees track over your toes','Push through your heels to return to the starting position','Maintain control throughout both the lowering and rising phases']::text[],ARRAY['Keep your weight distributed evenly across your feet, focusing on pushing through your heels','Ensure your knees stay aligned with your toes and don''t cave inward','Maintain a neutral spine by keeping your chest up and avoiding rounding your back','Control the descent to maximize muscle engagement and prevent injury','Stop at parallel depth to protect your knees and maintain proper form']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['strength','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','eb57cdf4-30aa-4286-9f5c-a3994414c71d','Stability ball pike','stability-ball-pike-1455b3','Starting position: Begin in a plank position with your shins or feet resting on top of a stability ball and your hands planted on the floor beneath your shoulders, body forming a straight line. Execution: Engage your core and use your abdominals to draw the ball toward your hands, lifting your hips high into an inverted V (pike) position, then slowly roll back out to the starting plank.',ARRAY['Assume a plank with hands under shoulders and shins/feet on the stability ball.','Brace your core and keep your legs straight as you pull the ball toward your hands.','Lift your hips upward into a pike position while maintaining balance.','Pause briefly at the top with hips stacked over shoulders.','Slowly reverse the motion, rolling the ball back to the plank position.','Repeat for the desired number of repetitions with control.']::text[],ARRAY['Keep your arms straight and shoulders directly over your wrists.','Initiate the movement from your abs, not by swinging your hips.','Maintain a neutral spine and avoid letting your lower back sag.','Move slowly and with control to keep the ball stable.']::text[],'abs',ARRAY['front_deltoids','quads','triceps']::text[],'stability ball','core','advanced',ARRAY['core','strength','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c9f7a5b3-9129-444d-817f-94be9a1162db','Stability Ball Plank','stability-ball-plank-79b5d7','Starting position: Kneel in front of a stability ball and place your shins or lower legs on top of it, walking your hands out until your arms are extended directly under your shoulders and your body forms a straight line from head to heels. Execution: Brace your core, keep your hips level, and hold the plank position while maintaining stability on the ball without letting your midsection sag or pike.',ARRAY['Position your shins or feet on top of the stability ball and place both hands on the mat directly under your shoulders.','Extend your arms fully and align your body in a straight line from head to heels.','Engage your abs, glutes, and quads to keep your hips from sagging or rising.','Hold the position while stabilizing against the ball''s movement for the prescribed time.','Keep breathing steadily and maintain a neutral neck by gazing slightly forward.','Carefully lower your knees to exit the position when finished.']::text[],ARRAY['Keep your core tight and avoid letting your lower back arch or hips drop.','Maintain shoulders stacked directly over your wrists to protect the joints.','Do not let your hips pike up toward the ceiling.','Control the ball''s instability with small, steady adjustments rather than jerky movements.']::text[],'core',ARRAY['quads','glutes','erector_spinae']::text[],'stability ball','core','intermediate',ARRAY['core','isometric','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6d8e7e6b-aec2-49b9-8ff6-54918a1cf850','Staggered squats','staggered-squats-60ac3a','Starting position: Stand with feet in a split stance, one foot forward and the other staggered slightly behind, hands clasped in front of the chest for balance. Execution: Bend both knees to lower into a squat, keeping most of the weight on the front leg while the back foot lightly assists, then drive through the front heel to return to standing.',ARRAY['Set your feet in a staggered stance with one foot forward and the other slightly behind on the toes.','Clasp your hands at chest height and brace your core.','Lower down by bending both knees, sinking your hips while keeping your torso upright.','Keep the majority of your weight on the front leg and track the knee over the toes.','Push through the front heel to rise back to the start position.','Complete the set, then switch leg positions.']::text[],ARRAY['Keep your chest lifted and back straight throughout the movement.','Drive through the front heel to emphasize the working leg.','Avoid letting the front knee cave inward.','Control the descent rather than dropping quickly.']::text[],'quads',ARRAY['hip_flexors','erector_spinae','abductors']::text[],'bodyweight','strength','beginner',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f7122b18-1a1a-43a4-bb1c-76170240e7e8','Standing Cable Fly','standing-cable-fly','Starting position: Stand facing a cable machine with the pulley adjusted to chest height. Execution: Grasp the handles and open your arms out to the sides while maintaining a slight bend in the elbows.',ARRAY['Set cable pulleys to shoulder height and select appropriate weight','Stand centered between cables with one foot slightly forward for stability','Grasp handles with palms facing forward and step forward to create tension','Keep slight bend in elbows throughout the entire movement','Bring handles together in front of chest using smooth controlled motion','Slowly return to starting position resisting the weight on the way back']::text[],ARRAY['Maintain slight forward lean and engaged core to prevent back strain','Focus on squeezing chest muscles rather than using arm strength to pull','Control the negative portion of the movement to maximize muscle engagement','Keep shoulders down and back to avoid shoulder impingement','Start with lighter weight to master the movement pattern before progressing']::text[],'chest','{}'::text[],'cable','chest','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e42e2ca3-664b-48bd-8cf7-e8a4313618bb','Standing Dumbbell Straight-Arm Front Delt','standing-dumbbell-straight-arm-front-delt','Starting position: Stand with feet hip-width apart, holding a dumbbell in each hand with arms fully extended down in front of your thighs, palms facing your body. Execution: Keeping your arms straight, raise the dumbbells directly in front of you until they reach shoulder height, then slowly lower back to the starting position.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Hold dumbbells with a neutral grip, arms fully extended in front of your thighs','Keep your shoulders down and back, maintaining good posture throughout the movement','Raise the dumbbells in a controlled arc directly in front of you until they reach shoulder height','Pause briefly at the top, then slowly lower the weights back to starting position','Maintain straight arms throughout the entire range of motion']::text[],ARRAY['Keep your core engaged to prevent swaying or using momentum','Stop at shoulder height to avoid impingement and maintain proper form','Use a weight that allows you to control the movement without swinging','Focus on the front deltoids doing the work rather than using your back or legs','Maintain a slight bend in your knees and avoid locking out your elbows completely']::text[],'shoulders','{}'::text[],'dumbbell','shoulders','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','032ca17e-2678-46e4-baac-b7ef43c283e9','Standing Dumbbell Triceps Extension','standing-dumbbell-triceps-extension',null,ARRAY['Stand with feet shoulder-width apart, holding one dumbbell with both hands behind your head, arms bent at 90 degrees','Keep your elbows close to your head and pointing forward throughout the movement','Slowly extend your arms upward by straightening your elbows, lifting the dumbbell overhead','Pause briefly at the top with arms fully extended','Lower the dumbbell back to the starting position behind your head in a controlled manner','Repeat for desired repetitions while maintaining proper form']::text[],ARRAY['Keep your core engaged and maintain an upright posture throughout the exercise','Only your forearms should move - keep your upper arms stationary and elbows fixed in position','Use a controlled tempo, especially on the lowering phase, to maximize muscle engagement','Start with lighter weight to master the form before progressing to heavier loads','Stop immediately if you feel any shoulder or elbow discomfort']::text[],'triceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5bd45b94-2926-4051-b4cb-51a66f46ecf8','Standing EZ Bar Curl','standing-ez-bar-curl','Starting position: Stand holding an EZ bar with hands in a supinated grip. Execution: Flex your elbows to lift the bar toward your shoulders, then lower in a controlled manner.',ARRAY['Stand with feet shoulder-width apart and grip the EZ bar with an underhand grip, hands positioned on the angled sections','Keep your core engaged and maintain a straight posture with shoulders back and chest up','Position your elbows close to your sides and keep them stationary throughout the movement','Curl the bar up by contracting your biceps until your forearms are vertical and you feel peak contraction','Slowly lower the bar back to the starting position with control, maintaining tension in your biceps','Avoid swinging or using momentum to lift the weight']::text[],ARRAY['Keep your wrists straight and aligned with your forearms to prevent strain','Focus on squeezing your biceps at the top of the movement for maximum muscle activation','Control the negative portion of the lift by taking 2-3 seconds to lower the weight','Avoid leaning back or using your lower back to assist with the lift','The EZ bar''s angled grip reduces wrist stress compared to a straight barbell']::text[],'biceps','{}'::text[],'barbell','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cca9d3bf-daf9-421b-93ca-9e626d682807','Standing forward bend','standing-forward-bend',null,ARRAY['Stand with feet hip-width apart.','Inhale to lengthen your spine.','Exhale and fold forward from the hips, bringing your hands toward the floor.','Let your head hang heavy and relax your neck.']::text[],ARRAY['Bend your knees as much as needed.','Shift your weight slightly toward the balls of your feet.','Relax your upper body completely.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8b749c78-6f8d-46d7-ab75-bb42ed161ae1','Standing Hamstring Stretch (L)','standing-hamstring-stretch-l','Starting position: Stand upright with feet hip-width apart, then step your left foot forward about 2-3 feet with heel on the ground and toes pointed up. Execution: Hinge at the hips and lean forward while keeping your back straight, reaching toward your left toes until you feel a stretch in the back of your left thigh.',ARRAY['Stand with feet hip-width apart and step your left foot forward 2-3 feet','Keep your left heel on the ground and flex your left toes up toward your shin','Place hands on your right thigh for support and keep your back straight','Slowly hinge at the hips and lean forward over your left leg','Reach toward your left toes while maintaining a neutral spine','Hold the stretch for 15-30 seconds then slowly return to starting position']::text[],ARRAY['Keep your back straight throughout the movement to avoid rounding your spine','Focus on hinging at the hips rather than bending at the waist','You should feel the stretch in the back of your left thigh, not your lower back','Breathe deeply and avoid bouncing or forcing the stretch']::text[],'hamstrings','{}'::text[],'bodyweight','legs','beginner',ARRAY['stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','75593cee-6a28-4842-8222-150647b2157b','Standing Hamstring Stretch (R)','standing-hamstring-stretch-r','Starting position: Stand upright with feet hip-width apart, then step your right foot forward about 2-3 feet and flex your right foot so only the heel touches the ground. Execution: Keeping your right leg straight, hinge forward at the hips while maintaining a straight back until you feel a stretch along the back of your right thigh.',ARRAY['Stand with feet hip-width apart and step your right foot forward 2-3 feet','Flex your right foot upward so only the heel remains on the ground','Keep your right leg completely straight and your left leg slightly bent for support','Hinge forward at the hips while keeping your back straight and chest up','Lower your torso until you feel a moderate stretch in your right hamstring','Hold the stretch for 20-30 seconds while breathing normally']::text[],ARRAY['Keep the stretched leg completely straight to effectively target the hamstring muscles','Hinge from your hips rather than rounding your back to prevent lower back strain','Only stretch to the point of mild tension, never to the point of pain','Maintain steady breathing throughout the stretch and avoid bouncing movements','Keep most of your weight on your supporting leg for better balance and control']::text[],'hamstrings','{}'::text[],'bodyweight','legs','beginner',ARRAY['stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e6c47dc5-3924-4b1d-a8ac-deb2ec1730aa','Standing High Cable Row','standing-high-cable-row','Starting position: Stand facing a high pulley with an overhand grip (palms facing down). Execution: Pull the handle toward your upper chest, keeping elbows pointed outward, then slowly return to starting position.',ARRAY['Set the cable pulley to upper chest height and attach a straight bar or rope handle','Stand arm''s length away from the machine with feet shoulder-width apart and slight bend in knees','Grasp the handle with both hands using an overhand grip, arms extended forward','Pull the handle straight back toward your upper chest while squeezing shoulder blades together','Hold the contraction briefly at your chest, feeling the squeeze between your shoulder blades','Slowly return the weight to starting position with controlled movement, maintaining tension']::text[],ARRAY['Keep your chest up and shoulders back throughout the entire movement to maintain proper posture','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Avoid leaning back or using momentum - maintain a stable, upright position','Control the weight on both the pulling and returning phases to maximize muscle engagement','Keep a slight bend in your elbows and avoid fully locking out your arms at the starting position']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bba8482e-3ddd-4c44-9b2a-90af81d040e9','Standing Inner-Biceps Curl','standing-inner-biceps-curl','Starting position: Stand upright with feet shoulder-width apart, holding dumbbells at your sides with arms fully extended and palms facing outward in a supinated grip. Execution: Curl the dumbbells up by flexing at the elbows while keeping your upper arms stationary, then slowly lower back to the starting position.',ARRAY['Stand with feet shoulder-width apart and core engaged for stability','Hold dumbbells with palms facing forward and arms fully extended at your sides','Keep your upper arms pressed against your torso throughout the movement','Curl the weights up by contracting your biceps until your forearms are vertical','Squeeze your biceps at the top of the movement','Slowly lower the dumbbells back to the starting position with control']::text[],ARRAY['Keep your wrists straight and maintain the supinated grip throughout the entire movement','Avoid swinging or using momentum - the movement should be controlled and isolated to the biceps','Maintain proper posture with shoulders back and chest up throughout the exercise','Focus on the eccentric (lowering) portion of the movement for maximum muscle engagement','Keep your elbows stationary and close to your body to maximize bicep activation']::text[],'biceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','339e91e9-a7a1-4ee1-a97b-6a5ec3f71684','Standing knee thrusts','standing-knee-thrusts','Starting position: Stand tall with feet hip-width apart, arms at your sides, and core engaged. Execution: Drive one knee up toward your chest while simultaneously bringing the opposite arm forward, then return to starting position and repeat with the other leg in a controlled, alternating rhythm.',ARRAY['Stand with feet hip-width apart and maintain an upright posture with shoulders back','Engage your core muscles and keep your chest lifted throughout the movement','Drive one knee up toward your chest while bringing the opposite arm forward in a running motion','Lower the leg back to starting position with control, avoiding stomping or slamming the foot down','Immediately repeat the movement with the opposite leg and arm','Continue alternating legs while maintaining proper form and controlled breathing']::text[],ARRAY['Keep your core tight throughout the movement to protect your lower back and maintain balance','Drive your knees up to at least hip height to maximize muscle activation and cardiovascular benefits','Land softly on the balls of your feet to reduce impact on joints and maintain proper form','Coordinate your arm swing with opposite leg movement to enhance balance and simulate natural running mechanics','Start with a moderate pace and gradually increase intensity as your conditioning improves']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','73cb1336-986a-4e65-9010-bcb205da13ce','Standing Leg Curl','standing-leg-curl-f24232','Starting position: Stand upright at the standing leg curl machine, positioning the back of one ankle against the padded roller with the working leg slightly bent and hands stabilizing on the machine or hips. Execution: Curl the heel up toward the glutes by flexing the knee against resistance, squeeze the hamstring at the top, then lower under control back to the starting position.',ARRAY['Position one ankle behind the padded roller and stabilize your torso by holding the machine.','Keep your hips pressed against the support and maintain a slight bend in the standing leg.','Curl the heel up toward your glutes by contracting the hamstring.','Pause and squeeze at the top of the movement.','Lower the roller slowly and under control to full extension.','Complete all reps on one leg before switching sides.']::text[],ARRAY['Avoid swinging or using momentum; move only at the knee joint.','Keep your hips and torso stable throughout the movement.','Control the eccentric phase to maximize hamstring tension.','Do not hyperextend the lower back at the top of the curl.']::text[],'hamstrings',ARRAY['calves','gastrocnemius','glutes']::text[],'machine','strength','beginner',ARRAY['strength','isometric']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','bfa76dd0-298b-4c70-b1fa-e662289d2ebe','Standing Low Cable Curl','standing-low-cable-curl','Starting position: Stand facing a low pulley with a straight bar attached to the cable. Execution: Bend your elbows to lift the bar toward your shoulders, then lower slowly.',ARRAY['Set the cable pulley to the lowest position and attach a straight bar or EZ-curl bar','Stand 2-3 feet away from the machine with feet shoulder-width apart and core engaged','Grasp the attachment with an underhand grip, hands about shoulder-width apart','Keep your elbows close to your sides and curl the weight up until your biceps are fully contracted','Squeeze your biceps at the top of the movement for a brief pause','Slowly lower the weight back to the starting position with control']::text[],ARRAY['Keep your elbows stationary throughout the entire movement to isolate the biceps effectively','Maintain constant tension on the cable by not allowing the weight stack to rest between repetitions','Use a controlled tempo with a 2-second lift and 3-second lowering phase','Avoid swinging your body or using momentum to lift the weight','Keep your wrists straight and in line with your forearms to prevent strain']::text[],'biceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','94b012da-2a8d-449c-8a25-80cc1b0a1ba7','Standing Low Cable Row','standing-low-cable-row','Starting position: Stand facing a low cable pulley with a pronated grip (palms down). Execution: Pull the handle toward the lower abdomen, keeping elbows close to the body, then slowly return to starting position.',ARRAY['Set the cable pulley to the lowest position and attach a straight bar or V-handle','Stand 2-3 feet away from the machine with feet hip-width apart and knees slightly bent','Grasp the handle with both hands using an overhand grip, arms extended but not locked out','Keep your core engaged and maintain a slight forward lean from your hips throughout the movement','Pull the handle toward your lower chest by driving your elbows back and squeezing your shoulder blades together','Slowly return to the starting position with control, maintaining tension in the cable']::text[],ARRAY['Keep your shoulders down and back throughout the entire movement to avoid shoulder impingement','Focus on initiating the pull with your back muscles rather than your arms by thinking about squeezing your shoulder blades together first','Maintain a neutral spine and avoid rounding your back or leaning too far forward during the exercise','Control the negative portion of the movement to maximize muscle engagement and prevent the weight stack from slamming']::text[],'back','{}'::text[],'cable','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3d0e9420-3d5f-4c9d-a002-7ad83f43bbde','Standing Neutral Grip Cable Press','standing-neutral-grip-cable-press','Starting position: Stand facing a cable machine with handles adjusted to chest height. Execution: Push the cables forward in a pressing motion until your arms are fully extended, then return slowly to the starting position.',ARRAY['Set the cable pulleys to chest height and attach handles to each cable','Stand in the center with one foot slightly forward for stability, grasping handles with neutral grip','Position your body so there is tension in the cables when your hands are at chest level','Press the handles forward and slightly inward until your arms are fully extended','Slowly return to starting position, controlling the weight on the eccentric portion','Maintain a slight forward lean throughout the entire movement']::text[],ARRAY['Keep your core engaged and maintain a stable stance to prevent being pulled backward by the cables','Focus on squeezing your chest muscles at the peak contraction when arms are fully extended','Control the negative portion of the movement to maximize muscle engagement and prevent injury','Avoid letting your shoulders roll forward or allowing the cables to pull your arms too far back beyond your torso','Maintain the neutral grip throughout the exercise to reduce wrist strain and target the chest effectively']::text[],'chest','{}'::text[],'cable','chest','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','6744d5a4-41a7-42b5-9383-f7f6eccf43cb','Standing One-Arm DB Triceps ExtensioN (L)','standing-one-arm-db-triceps-extension-l','Starting position: Stand with feet shoulder-width apart, holding a dumbbell in your left hand with arm extended overhead, keeping your upper arm close to your head. Execution: Lower the dumbbell behind your head by bending only at the elbow, then extend back to the starting position.',ARRAY['Stand with feet shoulder-width apart and engage your core for stability','Hold the dumbbell in your left hand and extend your arm straight overhead','Keep your upper arm stationary and close to your head throughout the movement','Slowly lower the dumbbell behind your head by bending only at the elbow until you feel a stretch in your triceps','Press the dumbbell back up to the starting position by extending your elbow','Complete all repetitions on the left arm before switching to the right']::text[],ARRAY['Keep your upper arm vertical and avoid letting it drift forward during the movement','Use your free hand to support your working arm at the elbow if needed for stability','Control the weight during the lowering phase to prevent injury to the elbow joint','Start with lighter weight to master the form before progressing to heavier loads','Maintain neutral spine and avoid arching your back excessively']::text[],'triceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e17c7349-85bc-4608-a897-d8d2841a8b38','Standing One-Arm DBl Triceps Extension (R)','standing-one-arm-dbl-triceps-extension-r','Starting position: Stand with feet shoulder-width apart, holding one dumbbell with your right hand directly overhead, arm fully extended. Execution: Lower the dumbbell behind your head by bending only at the elbow, then press it back to the starting position.',ARRAY['Stand with feet shoulder-width apart and core engaged for stability','Grip the dumbbell firmly with your right hand and press it directly overhead with arm fully extended','Keep your upper arm stationary and close to your head throughout the movement','Slowly lower the dumbbell behind your head by bending only at the elbow until you feel a stretch in your triceps','Press the dumbbell back to the starting position by extending your elbow','Complete all repetitions on the right arm before switching to the left']::text[],ARRAY['Keep your upper arm vertical and stationary - only the forearm should move','Control the weight on both the lowering and lifting phases to prevent injury','Avoid arching your back by maintaining a neutral spine and engaged core','Stop the descent when you feel a comfortable stretch in your triceps, typically when your forearm is parallel to the floor','Use your non-working hand to support your working arm if needed for stability']::text[],'triceps','{}'::text[],'dumbbell','arms','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','faa8cd98-a788-4760-be99-0dfcced0920b','Standing Palm-In One-Arm Dumbbell Press (L','standing-palm-in-one-arm-dumbbell-press-l','Starting position: Stand with feet shoulder-width apart, holding a dumbbell in your left hand at shoulder height with palm facing inward toward your body. Execution: Press the dumbbell straight overhead while maintaining core stability and controlling the weight through the full range of motion.',ARRAY['Stand with feet shoulder-width apart and engage your core muscles for stability','Hold the dumbbell in your left hand at shoulder height with palm facing inward','Keep your elbow directly under the weight and maintain a neutral spine','Press the dumbbell straight up overhead until your arm is fully extended','Lower the weight back to starting position with control','Complete all repetitions on the left side before switching to the right arm']::text[],ARRAY['Keep your core engaged throughout the movement to prevent back arching','Maintain the palm-in grip position throughout the entire exercise','Press the weight in a straight vertical path directly over your shoulder','Control the descent of the weight to maximize muscle engagement','Keep your non-working arm relaxed at your side for balance']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f8e77b58-2e1b-4695-ae24-17249ec2ad74','Standing Palm-In One-Arm Dumbbell Press (R','standing-palm-in-one-arm-dumbbell-press-r','Starting position: Stand with feet shoulder-width apart, holding a dumbbell in your right hand at shoulder height with palm facing toward your body. Execution: Press the dumbbell straight overhead in a controlled motion while maintaining balance and core engagement, then lower back to the starting position.',ARRAY['Stand with feet shoulder-width apart and engage your core muscles for stability','Hold the dumbbell in your right hand at shoulder height with palm facing inward toward your body','Keep your wrist straight and maintain a neutral spine throughout the movement','Press the dumbbell straight up overhead until your arm is fully extended','Lower the weight back to shoulder height in a controlled manner','Complete all repetitions on the right side before switching to the left arm']::text[],ARRAY['Keep your core engaged throughout the entire movement to prevent lower back strain','Avoid leaning to one side or using momentum to press the weight overhead','Maintain the palm-in grip position throughout the entire range of motion','Use a weight that allows you to maintain proper form for all repetitions','Keep your shoulder blade pulled down and back to maintain shoulder stability']::text[],'full_body','{}'::text[],'dumbbell','full body','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','83df9077-41ca-4376-b5de-f4ea0393b6f8','Standing Quad Stretch (L)','standing-quad-stretch-l','Starting position: Stand tall with feet hip-width apart, using a wall or chair for balance if needed. Execution: Bend your left knee and pull your left foot toward your glutes with your left hand, holding the stretch while maintaining an upright posture.',ARRAY['Stand with feet hip-width apart and engage your core for stability','Place your right hand on a wall or chair for balance support','Bend your left knee and grasp your left ankle or foot with your left hand','Gently pull your heel toward your glutes while keeping your thighs parallel','Hold the stretch for 20-30 seconds while breathing normally','Release slowly and repeat on the opposite side']::text[],ARRAY['Keep your standing leg slightly bent to maintain balance and reduce strain on the knee','Avoid pulling your foot too aggressively - use gentle, controlled pressure to prevent muscle strain','Maintain an upright torso position rather than leaning forward to maximize the quadriceps stretch','If you cannot reach your ankle, use a towel or strap around your foot for assistance','Stop immediately if you experience any sharp pain in the knee or hip joint']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ff71c077-37d0-4819-9336-14d4946755f2','Standing Quad Stretch (R)','standing-quad-stretch-r','Starting position: Stand tall with feet hip-width apart, using a wall or chair for balance if needed. Execution: Bend your right knee and pull your right heel toward your glutes, holding your ankle or foot with your right hand while keeping your torso upright.',ARRAY['Stand near a wall or sturdy surface for balance support','Bend your right knee and bring your right heel toward your glutes','Grasp your right ankle or top of your foot with your right hand','Keep your knees close together and avoid pulling your leg out to the side','Hold the stretch for 20-30 seconds while breathing normally','Slowly release and repeat on the left leg']::text[],ARRAY['Keep your standing leg slightly bent to maintain balance and reduce stress on the knee','Avoid arching your back by engaging your core and keeping your pelvis neutral','If you cannot reach your ankle, use a towel or strap around your foot','Stop immediately if you feel any sharp pain in your knee or hip','Focus on pulling your heel straight back rather than forcing your knee into extreme flexion']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ec29a267-b5bc-406d-ae9a-043887d1dc06','Standing Reverse Curl','standing-reverse-curl','Starting position: Stand upright holding a barbell with an overhand grip, arms extended down in front of your body with the bar resting against your thighs. Execution: Curl the barbell upward by flexing your wrists and forearms while keeping your upper arms stationary, then slowly lower back to the starting position.',ARRAY['Stand with feet shoulder-width apart and grip the barbell with an overhand grip, hands about shoulder-width apart','Keep your upper arms pressed against your sides throughout the entire movement','Slowly curl the barbell up by flexing your wrists and contracting your forearms','Pause briefly at the top of the movement when your wrists are fully flexed','Lower the barbell back down in a controlled manner to the starting position','Maintain tension in your forearms throughout the entire range of motion']::text[],ARRAY['Use an overhand grip which is opposite to regular bicep curls to target the forearm extensors','Keep your upper arms completely stationary - only your forearms and wrists should move','Start with lighter weight than you would use for regular curls as this exercise specifically targets smaller forearm muscles','Control the negative portion of the movement to maximize muscle engagement','Avoid using momentum or swinging the weight']::text[],'forearms','{}'::text[],'barbell','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ef04d753-d34b-4457-bcdb-0ec447d55101','Standing Single Leg Curl','standing-single-leg-curl','Starting position: Stand on a leg curl machine with one leg secured and the other slightly lifted. Execution: Bend your knee to bring the pad toward your glutes, then slowly lower to starting position. Repeat with the other leg.',ARRAY['Adjust the machine height so the padded lever sits comfortably against the back of your ankle just above the heel','Stand with your non-working leg firmly planted and grip the support handles for stability','Position your working leg straight with the ankle pad resting against the back of your lower leg','Slowly curl your heel toward your glutes by bending your knee while keeping your thigh stationary','Hold the contraction briefly at the top of the movement','Lower the weight slowly and under control back to the starting position without letting the weight stack touch']::text[],ARRAY['Keep your core engaged and maintain an upright posture throughout the entire movement','Focus on controlling the eccentric portion of the lift to maximize muscle development','Avoid swinging or using momentum to lift the weight','Keep your thigh of the working leg stationary and perpendicular to the floor','Complete all repetitions on one leg before switching to the other leg']::text[],'hamstrings','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3bf0aada-8142-418e-8f7b-f506ecc63afb','Star crunch into Half V- ups','star-crunch-into-half-v-ups','Starting position: Lie on your back with arms and legs extended wide in a star shape, creating an X with your body. Execution: Simultaneously bring your knees toward your chest while lifting your torso and reaching your arms forward, then lower back to the star position and immediately perform a half V-up by lifting your legs and torso to form a V shape.',ARRAY['Lie flat on your back with arms extended overhead and legs spread wide in a star formation','Engage your core and simultaneously bring your knees toward your chest while lifting your shoulders off the ground','Reach your arms forward toward your knees as you crunch up, then slowly lower back to the star position','Immediately transition into a half V-up by keeping your legs straight and lifting them while raising your torso','Reach your arms toward your feet at the top of the V position','Lower with control back to the starting star position and repeat the sequence']::text[],ARRAY['Keep your lower back pressed against the floor during the star crunch portion to protect your spine','Focus on using your core muscles rather than momentum to perform both movements','Breathe out during the exertion phases and inhale as you lower back down','Maintain control throughout both movements rather than rushing through the exercise','If you experience neck strain, place one hand behind your head for support during the crunching motions']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','aa60f379-a493-46d2-8e03-3ba2277f3e78','Star Jump Burpees','star-jump-burpees','Starting position: Stand upright with feet hip-width apart, arms at your sides, and core engaged. Execution: Perform a traditional burpee sequence, but when jumping up from the squat position, extend arms and legs wide into a star shape before landing back in the starting position.',ARRAY['Begin standing tall, then squat down and place both hands firmly on the ground shoulder-width apart','Jump or step both feet back simultaneously into a high plank position with straight arms','Perform a push-up by lowering your chest to the ground, then press back up to plank position','Jump or step both feet forward back into the squat position near your hands','Explosively jump straight up while simultaneously spreading your arms overhead and legs wide apart into a star shape','Land softly with feet hip-width apart and immediately begin the next repetition']::text[],ARRAY['Keep your core tight throughout the entire movement to protect your lower back and maintain proper form','Land softly on the balls of your feet when jumping back to starting position to reduce impact on joints','Maintain a straight line from head to heels during the plank and push-up phases','Control the tempo and focus on quality movement rather than speed, especially when learning the exercise','Breathe consistently throughout the movement, exhaling during the explosive jump phase']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','da74be26-d3ba-403a-a16d-28ff3cf12396','Static Lunge on Machine','static-lunge-on-machine','Starting position: Position yourself on a static lunge machine with one foot forward and the other back. Execution: Lower your body toward the floor by bending both knees, then push upward to return to starting position. Repeat with the other leg.',ARRAY['Position yourself on the machine platform with feet hip-width apart in a split stance','Place your front foot flat on the platform and your back foot on the ball of the foot','Engage your core and maintain an upright torso throughout the movement','Lower your body by bending both knees simultaneously until your front thigh reaches parallel','Push through your front heel to drive back up to the starting position','Complete all repetitions on one leg before switching to the other side']::text[],ARRAY['Keep most of your weight on your front leg throughout the entire movement','Avoid allowing your front knee to drift forward past your toes during the descent','Maintain a straight back and avoid leaning forward or backward during the exercise','Lower yourself in a controlled manner and avoid bouncing at the bottom of the movement','Ensure your front knee tracks in line with your toes to prevent knee strain']::text[],'quads','{}'::text[],'machine','legs','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1121f617-3012-4e15-a6d9-86ed9440acce','Step Calf Raise','step-calf-raise-b97e4d','Starting position: Stand tall on the edge of a step platform with the balls of your feet on the surface and heels hanging off the back edge, hands on hips for balance. Execution: Press through the balls of your feet to raise your heels as high as possible, then lower under control to feel a stretch in the calves before repeating.',ARRAY['Position the balls of both feet on the edge of the step with heels hanging off, standing upright with hands on hips.','Push through the balls of your feet to lift your heels as high as possible.','Squeeze the calves at the top of the movement.','Lower your heels slowly below the level of the step to stretch the calves.','Repeat for the desired number of repetitions maintaining a steady tempo.']::text[],ARRAY['Keep your knees straight but not locked throughout the movement.','Maintain an upright torso and engaged core for balance.','Move slowly and controlled, avoiding bouncing at the bottom.','Achieve a full range of motion by rising high and dropping the heels low.']::text[],'calves',ARRAY['gastrocnemius','soleus','peroneals']::text[],'box','strength','beginner',ARRAY['strength','calisthenics','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ae9e4d04-17ed-4235-930a-89ce847e8507','Step Squat Pulse','step-squat-pulse-1ef5f8','Starting position: Stand with one foot elevated on a step platform and the other foot on the floor in a wide stance, hands clasped at chest height. Execution: Lower into a squat by bending both knees, then perform small pulsing movements at the bottom of the squat while keeping tension in the legs and glutes.',ARRAY['Place one foot on the step platform and the other on the floor in a wide stance.','Clasp your hands in front of your chest for balance.','Bend both knees and lower into a wide squat position.','Perform small pulsing movements up and down at the bottom of the squat.','Keep your chest lifted and core engaged throughout.','Complete the reps then switch sides.']::text[],ARRAY['Keep your knees tracking in line with your toes.','Maintain an upright torso and avoid rounding the lower back.','Keep weight evenly distributed between both legs.','Engage the glutes and core during each pulse.']::text[],'glutes',ARRAY['glute_med','hip_flexors','abductors']::text[],'box','strength','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','9898b03d-3337-4ea6-93d6-812d2004693b','Step Up No Equipment','step-up-no-equipment-e251f2','Starting position: Stand tall facing a step or box with feet hip-width apart, arms relaxed at your sides and core engaged. Execution: Drive one knee up and place the foot on the step, pushing through the heel to stand up onto it, then step back down with control and repeat, alternating or leading with the same leg.',ARRAY['Stand upright in front of a step or box with feet hip-width apart.','Lift one knee and place the entire foot flat on the step surface.','Drive through the leading heel to bring your body up onto the step.','Bring the trailing foot up or tap the step, then step back down with control.','Return to the start position and repeat, alternating legs as needed.']::text[],ARRAY['Push through the heel of the leading leg to engage the glutes.','Keep your chest lifted and core braced throughout the movement.','Control the descent rather than dropping down quickly.','Ensure the whole foot is planted on the step for stability.']::text[],'quads',ARRAY['glute_max','calves','hamstrings']::text[],'box','plyometric','beginner',ARRAY['strength','functional','plyometric']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','742b9b5a-2d25-4321-9769-bdc267ac59f7','Step ups','step-ups-2e7a15','Starting position: Stand upright facing a sturdy box or platform with feet hip-width apart and arms relaxed at your sides. Execution: Drive one knee up and place the foot flat on top of the box, push through that heel to stand tall on the box, then step back down with control and repeat, alternating or leading with the same leg.',ARRAY['Stand tall facing the box with your core engaged and chest lifted.','Lift your leading foot and plant it firmly on the box top.','Push through the heel of the leading leg to stand fully upright on the box.','Step back down under control, returning to the starting position.','Repeat for the desired reps, then switch legs.']::text[],ARRAY['Keep your chest up and avoid leaning too far forward.','Drive through the heel, not the toes, to engage the glutes.','Ensure your whole foot is planted on the box for stability.','Control the descent instead of dropping down quickly.']::text[],'quads',ARRAY['glute_med','hamstrings','calves']::text[],'box','strength','beginner',ARRAY['strength','functional','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2ca49b40-d285-4dfe-8dba-f51448b46c0a','Step-Ups (Bodyweight)','step-ups-bodyweight-78cf87','Starting position: Stand facing a sturdy step or platform with feet hip-width apart. Execution: Step up with one foot, drive through the heel to stand fully on the platform, then step back down with control.',ARRAY['Stand facing a sturdy step or platform','Place right foot completely on the step surface','Drive through right heel to step up','Bring left foot up to meet right foot','Step back down with left foot first','Return right foot to starting position']::text[],ARRAY['Keep your torso upright and core engaged throughout the movement','Place your entire foot on the step, not just the toes','Control the descent to avoid jarring your joints','Use a step height that allows your knee to bend at 90 degrees','Alternate leading legs or complete all reps on one side first']::text[],'bodyweight',ARRAY['glute_med','hamstrings','calves']::text[],'bodyweight','strength','beginner',ARRAY['calisthenics','strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','18c65037-c4d3-4643-b099-c2f129cef229','Straddle Up','straddle-up-378d90','Starting position: Sit tall on the floor or mat with your legs extended wide apart in a straddle position, toes pointing upward and hands resting near your inner thighs. Execution: Hinge forward from the hips, keeping the spine long, reaching your hands along the floor between your legs while feeling a stretch through the inner thighs and hamstrings, then return to upright.',ARRAY['Sit on the mat and open your legs wide into a V-shaped straddle position.','Keep your spine tall, chest lifted, and toes pointing toward the ceiling.','Hinge forward from the hips, sliding your hands along the floor between your legs.','Lower to a comfortable depth and hold the stretch, breathing steadily.','Slowly return to the upright seated position with control.','Repeat for the prescribed duration or number of repetitions.']::text[],ARRAY['Hinge from the hips rather than rounding the lower back.','Keep knees pointing upward and avoid letting them roll inward.','Only stretch to a comfortable range without forcing the movement.','Breathe deeply and relax into the stretch on each exhale.']::text[],'adductors',ARRAY['erector_spinae','semitendinosus','gastrocnemius']::text[],'bodyweight','stretching','beginner',ARRAY['stretching','mobility','cooldown']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8cd64184-db39-4c0d-90fe-859c4661aa95','Straight arm circles','straight-arm-circles-dc1e25','Starting position: Stand tall with feet hip-width apart, core engaged, and arms extended straight out to the sides at shoulder height forming a T shape. Execution: Move both straight arms in controlled circular motions, drawing circles in the air while keeping the elbows locked and shoulders down, then reverse direction.',ARRAY['Stand upright with feet hip-width apart and extend both arms straight out to the sides at shoulder height.','Keep your arms straight and begin making small controlled circles forward.','Gradually increase the size of the circles while maintaining shoulder stability.','Complete the desired repetitions, then reverse and circle backward.','Keep your core tight and posture upright throughout the movement.']::text[],ARRAY['Keep arms fully extended and elbows locked throughout the circles.','Avoid shrugging the shoulders toward the ears; keep them down and relaxed.','Maintain a steady, controlled tempo rather than swinging quickly.','Engage the core to prevent arching the lower back.']::text[],'shoulders',ARRAY['rotator_cuff','upper_back','serratus_anterior']::text[],'bodyweight','warmup','beginner',ARRAY['warmup','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','435a2ddc-bd65-4ca6-a696-eb6a9e812b30','Sumo Deadlift','sumo-deadlift-925b68','Starting position: Stand with a wide stance, toes pointed outward, and the barbell over your mid-foot. Hinge at the hips and bend the knees to grip the bar with hands inside your legs, chest up and back flat. Execution: Drive through the floor with your legs, extending the hips and knees simultaneously to stand tall with the barbell, then lower it under control back to the ground.',ARRAY['Set up with a wide stance and toes turned out, bar over mid-foot.','Grip the bar with arms straight inside your knees, chest up and spine neutral.','Drive your feet into the floor and extend hips and knees together to lift the bar.','Lock out at the top by fully extending the hips and squeezing the glutes.','Lower the bar under control by hinging at the hips and bending the knees.','Reset your position and repeat for the desired repetitions.']::text[],ARRAY['Keep your back flat and chest up throughout the entire movement.','Push knees out in line with your toes to engage the adductors and glutes.','Keep the bar close to your body and drive through the heels.','Avoid rounding the lower back or jerking the weight off the floor.']::text[],'glutes',ARRAY['lats','core','forearm_flexors']::text[],'barbell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','d059f2d7-4a9c-4f56-b754-55966afd5c1c','Sumo squats','sumo-squats-f8a2c3','Starting position: Stand with feet wider than shoulder-width apart, toes pointed outward at roughly 45 degrees, chest up and hands clasped in front. Execution: Bend at the hips and knees to lower your body straight down until thighs are parallel to the floor, keeping knees tracking over toes, then drive through the heels to return to standing.',ARRAY['Set your feet wider than shoulder-width with toes angled outward.','Brace your core, keep your chest tall and clasp your hands in front for balance.','Lower your hips down and back by bending the knees until thighs are parallel to the floor.','Keep your knees pushed out in line with your toes throughout the movement.','Drive through your heels and squeeze your glutes to return to standing.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your chest lifted and back neutral, avoiding forward rounding.','Push your knees outward so they track over your toes, not caving inward.','Keep your heels planted and weight distributed through mid-foot and heels.','Descend to at least parallel while maintaining control.']::text[],'glutes',ARRAY['adductors','hamstrings','core']::text[],'bodyweight','strength','beginner',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0ed37189-d6ea-48c0-83cb-587b44a7b546','Sumo walk','sumo-walk',null,ARRAY['Stand with feet wider than shoulder-width apart and toes pointed slightly outward','Lower into a deep squat position by bending at the hips and knees, keeping your chest up and back straight','Maintain the squat position and take a small step to the right with your right foot','Bring your left foot to meet your right foot, maintaining the wide sumo squat stance','Continue stepping sideways for the desired number of steps, then reverse direction','Keep your core engaged and weight evenly distributed throughout the movement']::text[],ARRAY['Keep your knees tracking in line with your toes to prevent knee strain','Maintain a strong upright torso throughout the entire movement','Focus on keeping your weight in your heels rather than your toes','Take small controlled steps to maintain proper squat depth and form','Engage your glutes and core muscles continuously during the exercise']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4aa2b90d-e5da-47d6-abd5-4e1932324ed2','Super man crunches','super-man-crunches','Starting position: Lie face down on the floor with arms extended overhead and legs straight, forming a straight line from fingertips to toes. Execution: Simultaneously lift your chest, arms, and legs off the ground while bringing your knees toward your elbows in a crunching motion, then return to the starting position.',ARRAY['Lie face down on a mat with arms fully extended overhead and legs straight','Engage your core and glutes before beginning the movement','Simultaneously lift your chest, arms, and legs off the ground as high as comfortably possible','Draw your knees toward your elbows while crunching your torso','Hold the contracted position briefly, then slowly lower back to the starting position','Repeat for the desired number of repetitions while maintaining control throughout']::text[],ARRAY['Keep your neck in neutral alignment by looking down at the floor rather than lifting your head','Focus on squeezing your glutes and engaging your entire core throughout the movement','Avoid using momentum - perform the exercise with slow, controlled movements','Start with smaller ranges of motion and gradually increase as your strength improves','Stop immediately if you experience any lower back pain or discomfort']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['core','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b627fc87-cf16-443b-b87d-d1ba39ed8ca9','Superman crunches','superman-crunches','Starting position: Lie face down on the floor with arms extended overhead and legs straight, maintaining a neutral spine. Execution: Simultaneously lift your chest, arms, and legs off the ground while contracting your lower back and glutes, then lower back down with control.',ARRAY['Lie face down on a mat with arms extended overhead and legs straight','Keep your neck in neutral alignment by looking down at the floor throughout the movement','Simultaneously lift your chest, arms, and legs off the ground by squeezing your glutes and lower back muscles','Hold the top position for 1-2 seconds while maintaining tension','Slowly lower your chest, arms, and legs back to the starting position with control','Repeat for the desired number of repetitions while maintaining proper form']::text[],ARRAY['Keep movements slow and controlled to maximize muscle activation and prevent injury','Focus on squeezing your glutes and lower back muscles rather than straining your neck','Only lift as high as comfortable - excessive range of motion can cause lower back strain','Breathe out during the lifting phase and breathe in while lowering back down','Stop immediately if you experience any sharp pain in your lower back']::text[],'back','{}'::text[],'bodyweight','back','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2a4df469-77c8-4468-92cb-2003c90602dd','Superman extensions','superman-extensions','Starting position: Lie face down on the floor with your arms extended overhead and legs straight, forehead resting on the ground. Execution: Simultaneously lift your chest, arms, and legs off the ground by contracting your back muscles, hold briefly, then slowly lower back to the starting position.',ARRAY['Lie face down on a mat with arms extended overhead and legs straight','Keep your forehead down and maintain a neutral neck position throughout the movement','Simultaneously lift your chest, arms, and legs off the ground by squeezing your glutes and back muscles','Hold the lifted position for 2-3 seconds while breathing normally','Slowly lower your chest, arms, and legs back to the starting position with control','Rest briefly between repetitions to maintain proper form']::text[],ARRAY['Keep movements slow and controlled to avoid straining the lower back','Only lift as high as comfortable - excessive range of motion can cause injury','Engage your core muscles throughout the exercise to support your spine','Avoid holding your breath during the hold phase','Focus on quality over quantity, maintaining proper form throughout all repetitions']::text[],'back','{}'::text[],'bodyweight','back','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','440ff6f0-b3c0-42fd-bcfd-8a85a841d410','Supported shoulder stand','supported-shoulder-stand',null,ARRAY['Lie on your back and lift your legs up toward the ceiling.','Press your hands into your lower back for support.','Walk your hands closer to your shoulders as you straighten your legs overhead.','Hold with your body as vertical as comfortable.']::text[],ARRAY['Support your weight on your shoulders, not your neck.','Do not turn your head while in this pose.','Come out slowly by rolling down one vertebra at a time.']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0ff4b70c-8c21-42a0-83c9-a0aa4fcc4b4a','Swimmers','swimmers-b4f3ca','Starting position: Lie face down on the mat with your legs extended and arms reaching overhead, forehead near the floor. Execution: Lift your arms and legs off the ground and alternate raising opposite arm and leg in a controlled swimming motion while keeping your core engaged and neck neutral.',ARRAY['Lie prone with arms extended overhead and legs straight behind you.','Engage your core and lift your chest, arms, and legs slightly off the floor.','Raise your right arm and left leg higher, then lower and switch sides.','Continue alternating opposite arm and leg in a fluttering, swimming rhythm.','Keep your gaze down and neck long throughout the movement.','Maintain steady breathing and controlled tempo for the set duration.']::text[],ARRAY['Keep your neck neutral by looking at the floor, not lifting the head.','Engage the glutes and core to protect the lower back.','Move in a controlled manner rather than swinging limbs.','Keep limbs long and reach out through fingers and toes.']::text[],'erector_spinae',ARRAY['glute_max','hamstrings','rear_deltoids','lats']::text[],'bodyweight','core','intermediate',ARRAY['core','strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','fa9f64d1-12a1-43be-a15d-45609a706c9c','Switching Lunges','switching-lunges','Starting position: Stand tall with feet hip-width apart, hands on hips or at your sides for balance. Execution: Step one foot forward into a lunge position, then explosively jump up and switch legs mid-air, landing with the opposite foot forward in a lunge position.',ARRAY['Begin in a standing position with your core engaged and shoulders back','Step your right foot forward into a lunge, lowering your body until both knees form 90-degree angles','Push explosively through both feet to jump straight up into the air','While airborne, quickly switch your leg positions so your left foot moves forward and right foot moves back','Land softly with your left foot forward in a lunge position, immediately absorbing the impact by bending both knees','Continue alternating legs with each jump, maintaining proper lunge form throughout the movement']::text[],ARRAY['Land softly on the balls of your feet to reduce impact on your joints and maintain control','Keep your torso upright throughout the movement and avoid leaning forward or backward','Ensure your front knee tracks over your ankle and doesn''t cave inward during the lunge','Start with slower, controlled movements before progressing to faster switching speeds','Maintain a strong core engagement to stabilize your body during the explosive transitions']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['plyometric','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c7dead12-7c46-4533-a0e9-dbc882cc498b','Switching Lunges into Burpees','switching-lunges-into-burpees','Starting position: Stand upright with feet hip-width apart, core engaged, and hands at your sides. Execution: Alternate between jumping lunges for a set number of reps, then immediately drop down into a burpee sequence before returning to the lunge pattern.',ARRAY['Begin with alternating jump lunges, landing softly with your front knee at 90 degrees and back knee hovering above the ground','After completing your desired lunge reps, immediately place both hands on the ground and jump your feet back into plank position','Perform a push-up while maintaining a straight body line from head to heels','Jump your feet back toward your hands and explosively jump up with arms overhead to complete the burpee','Return to the starting standing position and repeat the entire sequence','Maintain controlled breathing throughout the entire movement pattern']::text[],ARRAY['Keep your front knee aligned over your ankle during lunges to prevent knee strain','Land softly on the balls of your feet during jump transitions to reduce impact on joints','Maintain core engagement throughout both movements to protect your lower back','Start with fewer reps and build endurance gradually as this is a high-intensity combination exercise','Ensure proper form over speed - quality movement patterns prevent injury']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['cardio','plyometric','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','909e8b98-9e33-4a45-8bfa-3b0d4a9cef56','Switching lunges into Burpees (no jump)','switching-lunges-into-burpees-no-jump','Starting position: Stand tall with feet hip-width apart, arms at your sides. Execution: Alternate reverse lunges for a specified number of reps, then immediately transition into a burpee by placing hands on the ground, stepping back into plank position, performing a push-up, stepping feet back to hands, and standing up without jumping.',ARRAY['Begin with alternating reverse lunges, stepping one foot back into a lunge position while keeping your front knee aligned over your ankle','Complete the desired number of lunges on each leg, maintaining proper form throughout','After finishing the lunges, place both hands on the ground and step your right foot back, then your left foot back into a plank position','Perform one push-up while maintaining a straight line from head to heels','Step your left foot forward, then your right foot forward to return to a squat position','Stand up straight to complete one full repetition of the exercise combination']::text[],ARRAY['Keep your front knee tracking over your toes during lunges to protect the knee joint','Maintain a strong plank position during the burpee portion to engage your core effectively','Control the transition between exercises to maintain proper form and prevent injury','Focus on landing softly when stepping back and forward to reduce impact on joints','Keep your chest up and shoulders back throughout the entire movement sequence']::text[],'quads','{}'::text[],'bodyweight','legs','intermediate',ARRAY['cardio','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','8735c2a0-5c44-4a2d-ba45-932ba4d372cd','Switching mountain climbers','switching-mountain-climbers',null,ARRAY['Start in push-up position','Drive one knee toward chest','Quickly switch legs','Continue alternating at pace']::text[],ARRAY['Keep hips down (don''t pike)','Core stays engaged','Speed up for more cardio','Slow down for more control','Full body exercise']::text[],'core','{}'::text[],'bodyweight','core',null,ARRAY['cardio','core','hiit']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1c13173b-006e-4bfb-8f57-6c9403915e4d','T press up','t-press-up','Starting position: Begin in a standard push-up position with hands placed slightly wider than shoulder-width apart, body in a straight line from head to heels. Execution: Perform a push-up, then at the top position, lift one hand off the ground and rotate your torso, extending that arm toward the ceiling in a T-shape before returning to starting position and repeating on the opposite side.',ARRAY['Start in a high plank position with hands firmly planted and core engaged','Lower your body in a controlled push-up motion until chest nearly touches the floor','Push back up to the starting position with full arm extension','Lift your right hand and rotate your torso, reaching that arm toward the ceiling','Return the right hand to the ground and repeat the sequence with your left arm','Continue alternating sides for the desired number of repetitions']::text[],ARRAY['Keep your core tight throughout the entire movement to prevent hip sagging or rotation','Maintain a straight line from head to heels during both the push-up and rotation phases','Control the rotational movement - avoid rushing through the T-position','Place your supporting hand directly under your shoulder for optimal stability and joint safety','If full push-ups are too challenging, perform the exercise from your knees while maintaining proper form']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','700ff55b-baeb-41fe-9b1d-b2e046a45de6','T-Bar Row','t-bar-row','Starting position: Stand with a T-bar using an overhand grip (palms facing down). Execution: Pull the bar toward your chest while keeping your back straight, then slowly lower to the starting position.',ARRAY['Position feet firmly on either side of the barbell with knees slightly bent and maintain a neutral spine throughout the movement','Hinge forward at the hips until your torso is at approximately a 45-degree angle to the floor','Grip the barbell with both hands using an overhand grip, hands positioned close together near the weighted end','Engage your core and pull the barbell up toward your lower chest by driving your elbows straight back','Squeeze your shoulder blades together at the top of the movement and pause briefly','Lower the weight slowly and under control back to the starting position']::text[],ARRAY['Keep your chest up and shoulders back to maintain proper spinal alignment and prevent rounding of the upper back','Focus on pulling with your back muscles rather than your arms by initiating the movement with your shoulder blades','Avoid using momentum or swinging the weight as this reduces muscle activation and increases injury risk','Maintain tension in your core throughout the entire range of motion to protect your lower back']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','38c0d9e4-7f97-4e8f-8d26-650ca542e1c2','Tiger pose (left)','tiger-pose-left','Starting position: Begin in a kneeling position on hands and knees with one leg extended behind you and the opposite arm reaching back to grasp the foot. Execution: Hold this balanced pose while maintaining the connection between your hand and foot, creating an arch through your spine.',ARRAY['Start on hands and knees in a tabletop position on your yoga mat','Extend your left leg straight back behind you, keeping it lifted','Reach your right hand back to grasp the top of your left foot','Pull your foot toward your glutes while lifting your chest','Hold the position while breathing steadily','Release slowly and return to starting position before switching sides']::text[],ARRAY['Keep your supporting arm strong and straight to maintain balance','Engage your core muscles throughout the movement to protect your lower back','Pull your foot gently toward your body to create a comfortable stretch without forcing the position','Focus on lifting your chest and opening through the front of your body','Breathe deeply and avoid holding your breath during the pose']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7c07c6f8-b930-436b-9639-a07a49b99b9f','Tiger pose (right)','tiger-pose-right','Starting position: Begin in a tabletop position on hands and knees, then lift and bend your right leg behind you while grasping your right foot with your right hand. Execution: Hold this balanced position while extending through the lifted leg and maintaining core engagement.',ARRAY['Start in tabletop position with hands directly under shoulders and knees under hips','Lift your right leg behind you and bend the knee, bringing your foot toward your glutes','Reach back with your right hand to grasp the top of your right foot','Pull your foot gently toward your body while lifting your chest slightly','Hold the position while maintaining balance on your left hand and left knee','Release the foot and return to tabletop position slowly']::text[],ARRAY['Keep your supporting hand firmly planted and your supporting knee stable for balance','Engage your core throughout the movement to maintain stability and protect your lower back','Pull your foot toward your body gradually - avoid forcing the stretch','Keep your hips square to the ground rather than rotating them open','Breathe steadily throughout the hold and avoid holding your breath']::text[],'core','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','288185df-127a-4112-80df-83313767b80e','Toe touch- Posterior thigh','toe-touch-posterior-thigh','Starting position: Stand tall with feet hip-width apart, arms at your sides, and core engaged. Execution: Hinge at the hips and slowly reach your hands toward your toes while keeping your legs straight, then return to standing position.',ARRAY['Stand with feet hip-width apart and engage your core muscles','Keep your knees straight but not locked throughout the movement','Hinge at the hips by pushing your hips back and lowering your torso forward','Reach your hands toward your toes as far as comfortable without forcing the stretch','Hold the bottom position for 1-2 seconds while maintaining tension in your core','Slowly return to starting position by driving your hips forward and standing tall']::text[],ARRAY['Keep your back straight and avoid rounding your spine during the movement','Focus on the hip hinge movement rather than just bending forward','Only reach as far as your flexibility allows without pain or excessive strain','Breathe steadily throughout the exercise and avoid holding your breath','This exercise targets hamstring flexibility while engaging core stabilizing muscles']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7f2664b3-8108-458d-9535-7d14af3cf955','Toe Touchers','toe-touchers','Starting position: Lie on your back with legs extended straight up toward the ceiling, arms reaching toward your feet. Execution: Lift your shoulder blades off the ground while reaching your hands toward your toes, then lower back down with control.',ARRAY['Lie flat on your back on a mat with your lower back pressed into the floor','Extend both legs straight up toward the ceiling, keeping them as vertical as possible','Reach your arms straight up toward your feet with palms facing your legs','Engage your core and lift your shoulder blades off the ground while reaching toward your toes','Hold the contraction briefly at the top of the movement','Slowly lower your shoulders back to the starting position while maintaining leg position']::text[],ARRAY['Keep your lower back pressed firmly against the floor throughout the entire movement','Focus on lifting with your abdominal muscles rather than pulling with your neck or using momentum','Maintain straight legs throughout the exercise - slight bend in knees is acceptable if hamstrings are tight','Control the lowering phase to maximize muscle engagement and prevent injury','Breathe out during the lifting phase and breathe in as you lower back down']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['core','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','beb4aef0-332a-4be7-9839-d51e65772e33','Toes to bar','toes-to-bar','Starting position: Hang from a pull-up bar with arms fully extended, hands shoulder-width apart, and legs straight down. Execution: Engage your core and lift your legs up in front of you until your toes touch or reach toward the bar, then control the descent back to starting position.',ARRAY['Grip the pull-up bar with an overhand grip, hands positioned shoulder-width apart','Hang with arms fully extended and engage your shoulder blades to create stability','Initiate the movement by contracting your core and hip flexors to lift your knees toward your chest','Continue lifting until your legs are straight and toes reach toward or touch the bar','Control the descent by slowly lowering your legs back to the starting position','Maintain grip strength throughout the entire movement to prevent dropping']::text[],ARRAY['Keep your shoulders engaged and avoid completely relaxing at the bottom to maintain control and prevent injury','Use controlled momentum rather than aggressive swinging to help lift your legs while maintaining proper form','Focus on core engagement throughout the entire range of motion, not just during the lifting phase','Start with bent-knee variations like hanging knee raises if you cannot yet perform the full toes-to-bar movement','Ensure adequate grip strength and consider using lifting straps if grip becomes the limiting factor']::text[],'full_body','{}'::text[],'bodyweight','full body','advanced',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c2266a05-5960-489a-aa74-90ac93c376b1','Toes to Sky','toes-to-sky-a5bb0a','Starting position: Lie flat on your back on a mat with your arms extended alongside your body and legs raised straight toward the ceiling, forming roughly a 90-degree angle at the hips. Execution: Press through your heels and lift your hips off the mat, driving your toes straight up toward the sky, then lower with control back to the start.',ARRAY['Lie on your back with arms flat by your sides for stability and legs pointing straight up toward the ceiling.','Engage your lower abs and press your lower back gently into the mat.','Curl your pelvis upward, lifting your hips off the mat and pushing your toes toward the ceiling.','Pause briefly at the top of the movement squeezing your core.','Lower your hips slowly and with control back to the starting position.','Repeat for the desired number of repetitions without using momentum.']::text[],ARRAY['Keep the movement controlled and avoid swinging your legs for momentum.','Focus on lifting with your lower abs rather than pushing with your hands.','Maintain straight legs and point your toes toward the ceiling throughout.','Keep your neck and shoulders relaxed on the mat.']::text[],'lower_abs',ARRAY['hip_flexors','obliques','quads']::text[],'bodyweight','core','beginner',ARRAY['core','strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ab008d35-2e2f-482e-810a-b2cb6ecf0bde','Trap Bar deadlift','trap-bar-deadlift-33a1aa','Starting position: Stand inside a trap (hex) bar with feet hip-width apart, grip the neutral handles, hinge at the hips with a flat back and chest up. Execution: Drive through the floor with your legs, extend the hips and knees simultaneously to stand tall, then lower the bar under control back to the ground.',ARRAY['Step inside the trap bar and set feet hip-width apart with shins near the handles','Hinge at the hips, bend the knees, and grip both handles with a neutral grip','Brace your core, keep your chest up and back flat','Drive through your heels and mid-foot, extending hips and knees to stand fully upright','Lock out at the top by squeezing the glutes, then lower the bar under control to the floor']::text[],ARRAY['Keep your back flat and neutral throughout the lift','Push the floor away rather than pulling with your lower back','Keep the bar path vertical and close to your center of mass','Fully extend the hips at lockout without hyperextending the spine']::text[],'glutes',ARRAY['core','forearm_flexors','calves']::text[],'barbell','strength','intermediate',ARRAY['strength','functional']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','267b3050-21ec-4d7b-b8b1-d85b88583123','Tree pose (left)','tree-pose-left',null,ARRAY['Stand on one leg and place the other foot on your inner thigh or calf.','Avoid placing your foot on the knee.','Bring your palms together at your chest or raise them overhead.','Focus on a fixed point for balance.']::text[],ARRAY['Press your foot and thigh into each other.','Keep your standing leg strong with a micro-bend.','Engage your core for stability.']::text[],'full_body','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
