insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4513eebe-8fee-42e0-9d60-3101601bdc0a','Triangle pose (left)','triangle-pose-left',null,ARRAY['Stand with feet wide apart, front foot pointing forward, back foot at 90 degrees.','Extend your arms out to the sides at shoulder height.','Hinge at the hip and reach your front hand toward the floor or a block.','Extend your top arm toward the ceiling.']::text[],ARRAY['Keep both legs straight.','Open your chest toward the ceiling.','Engage your core to support the side bend.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','5cdc9847-39af-400f-8354-79e1d24828bd','Triangle pose (right)','triangle-pose-right',null,ARRAY['Stand with feet wide apart, front foot pointing forward, back foot at 90 degrees.','Extend your arms out to the sides at shoulder height.','Hinge at the hip and reach your front hand toward the floor or a block.','Extend your top arm toward the ceiling.']::text[],ARRAY['Keep both legs straight.','Open your chest toward the ceiling.','Engage your core to support the side bend.']::text[],'hamstrings','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','10014d85-339e-4573-876d-87b003c28671','Tricep extension knee ins','tricep-extension-knee-ins','Starting position: Begin in a plank position with forearms on the ground, elbows directly under shoulders, and body in a straight line from head to heels. Execution: While maintaining the plank position, alternate bringing each knee toward the chest in a controlled manner, then return to the starting position.',ARRAY['Start in a forearm plank position with elbows directly under your shoulders','Keep your core engaged and maintain a straight line from head to heels','Bring one knee toward your chest while keeping the other leg extended','Return the working leg to the starting position with control','Alternate legs in a smooth, controlled rhythm','Maintain the plank position throughout the entire movement']::text[],ARRAY['Keep your hips level and avoid rotating your torso as you bring each knee in','Maintain strong core engagement to prevent your lower back from sagging','Control the movement - avoid rushing or using momentum','Keep your forearms firmly planted and shoulders stable throughout the exercise','Breathe steadily and avoid holding your breath during the movement']::text[],'triceps','{}'::text[],'bodyweight','arms','intermediate',ARRAY['strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','044f938a-5772-4a0e-b39a-8a85393830e7','Tucked L-sit hold','tucked-l-sit-hold','Starting position: Sit on parallel bars or dip station with hands gripping the bars beside your hips, arms straight. Execution: Lift your body up by pressing down through your hands while tucking your knees toward your chest, holding this elevated position.',ARRAY['Grip the parallel bars firmly with hands positioned directly beside your hips','Press down through your palms to lift your entire body weight off the bars','Tuck your knees up toward your chest while maintaining the lifted position','Keep your arms straight and shoulders stable throughout the hold','Engage your core muscles to maintain the tucked position','Hold for the desired duration then slowly lower back down']::text[],ARRAY['Keep shoulders down and away from your ears to prevent neck strain','Maintain a strong grip on the bars throughout the entire movement','Focus on pushing down through your palms rather than just hanging','Start with shorter holds and gradually increase duration as strength improves','Keep your core tight to control the tucked leg position']::text[],'core','{}'::text[],'bodyweight','core','advanced',ARRAY['isometric','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','3730e7c4-d50d-4986-88ea-aba97ccf9b8c','Tucked L-sit hold (Hanging)','tucked-l-sit-hold-hanging','Starting position: Hang from a pull-up bar with arms fully extended, shoulders engaged, and legs hanging straight down. Execution: Pull your knees up toward your chest and hold this tucked position while maintaining a strong grip on the bar.',ARRAY['Grip the pull-up bar with hands shoulder-width apart using an overhand grip','Hang with arms fully extended and engage your shoulders by pulling them down and back','Activate your core and slowly pull your knees up toward your chest','Hold your knees as close to your chest as possible while keeping your back straight','Maintain the tucked position for the desired time duration','Lower your legs slowly and controlled back to the starting hanging position']::text[],ARRAY['Keep your shoulders actively engaged throughout the hold to prevent hanging passively from the joints','Focus on pulling your knees toward your chest rather than just lifting your feet up','Maintain a neutral spine and avoid rounding your back excessively','Build up hold time gradually starting with 5-10 seconds before progressing to longer durations','Ensure you have adequate grip strength before attempting longer holds to prevent falling']::text[],'core','{}'::text[],'bodyweight','core','advanced',ARRAY['isometric','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','23058ad3-cf8a-4550-a2bb-cb692999080d','Ultimate Elbow Stretch','ultimate-elbow-stretch-ce9e23','Starting position: Stand tall with feet hip-width apart, core engaged and arms relaxed at your sides. Execution: Raise one arm overhead, bend the elbow to bring your hand down behind your neck, then use the opposite hand to gently push the elbow to deepen the stretch along the back of the upper arm.',ARRAY['Stand upright with feet hip-width apart and shoulders relaxed.','Raise one arm straight overhead, then bend the elbow so your hand drops behind your head.','Reach your opposite hand up to grasp the bent elbow.','Gently pull the elbow inward and downward until you feel a stretch in the triceps.','Hold the stretch for 20-30 seconds while breathing steadily.','Release and repeat on the opposite arm.']::text[],ARRAY['Keep your torso upright and avoid arching the lower back.','Apply gentle, gradual pressure rather than bouncing the elbow.','Relax your shoulders down away from your ears throughout the stretch.']::text[],'triceps',ARRAY['lats','teres_major']::text[],'bodyweight','stretching','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','e5319ad1-2c9a-4442-b502-8ff972fc4dfc','Underhand Grip Cable Pushdown','underhand-grip-cable-pushdown','Starting position: Stand facing a high pulley with a straight bar attached to the pulley. Execution: Extend your elbows to push the bar downward, keeping elbows fixed in place.',ARRAY['Set the cable pulley to the highest position and attach a straight bar or rope handle','Stand facing the machine with feet shoulder-width apart and core engaged','Grasp the attachment with an underhand grip, palms facing up, hands about shoulder-width apart','Keep your elbows tucked close to your sides and position them at a 90-degree angle as your starting position','Push the weight down by extending your forearms until your arms are fully straight','Slowly return to the starting position by allowing your forearms to rise back up with control']::text[],ARRAY['Keep your upper arms completely stationary throughout the movement to properly isolate the triceps','Maintain tension on the cable at all times and avoid letting the weight stack touch between repetitions','Use a controlled tempo with a slightly slower eccentric phase to maximize muscle activation','Avoid using momentum or swinging your body to move the weight','Keep your wrists straight and maintain a firm grip throughout the entire range of motion']::text[],'triceps','{}'::text[],'cable','arms','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','dca87d2f-84de-4a2d-b0d8-2adcf68c10a8','Underhand Lat Pulldown','underhand-lat-pulldown','Starting position: Sit on a lat pulldown machine with an underhand grip (palms facing up). Execution: Pull the bar toward your chest, keeping elbows close to your body, then slowly return to starting position.',ARRAY['Adjust the thigh pad so it sits snugly against your legs to prevent your body from lifting during the movement','Grip the bar with palms facing you, hands positioned slightly wider than shoulder-width apart','Keep your chest up, shoulders back, and maintain a slight backward lean throughout the exercise','Pull the bar down smoothly to your upper chest, focusing on squeezing your shoulder blades together','Hold the contraction briefly at the bottom, then slowly return the bar to the starting position with control','Maintain tension in your lats throughout the entire range of motion']::text[],ARRAY['Keep your shoulders down and back to avoid using your upper traps and ensure proper lat activation','Avoid leaning too far back or using momentum to pull the weight down','Focus on pulling with your back muscles rather than your arms by initiating the movement with your lats','Control the eccentric portion of the movement to maximize muscle engagement and prevent injury','Keep your core engaged throughout the exercise to maintain proper posture and stability']::text[],'back','{}'::text[],'cable','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','cca59a88-a42c-4630-ad1e-335e31c65717','Upper back and shoulder stretch (left)','upper-back-and-shoulder-left','Starting position: Stand upright with feet hip-width apart. Execution: Reach your left arm across your chest and use your right hand to gently pull the left arm closer to your body, stretching the left shoulder and upper back.',ARRAY['Stand with feet hip-width apart and maintain good posture','Extend your left arm straight across your chest at shoulder height','Place your right hand on your left elbow or forearm','Gently pull your left arm closer to your chest using your right hand','Hold the stretch position while keeping your shoulders relaxed','Release slowly and repeat on the opposite side']::text[],ARRAY['Keep your torso upright and avoid rotating your spine during the stretch','Apply gentle, steady pressure rather than forcing the stretch','Feel the stretch in your left shoulder and upper back muscles','Breathe normally throughout the hold period','Stop immediately if you experience any sharp pain']::text[],'full_body','{}'::text[],'bodyweight','full body','intermediate',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','55a30378-1a97-47fd-9f63-0609de03e0b9','Upper back and shoulder stretch (right)','upper-back-and-shoulder-stretch-right','Starting position: Stand tall with feet hip-width apart, extend your right arm across your chest at shoulder height. Execution: Use your left hand to gently pull your right arm closer to your chest while keeping your shoulders relaxed and feeling a stretch through your right upper back and shoulder.',ARRAY['Stand with feet hip-width apart and maintain good posture with shoulders back','Extend your right arm straight across your chest at shoulder height','Place your left hand on your right elbow or forearm','Gently pull your right arm toward your chest until you feel a comfortable stretch','Hold the stretch while breathing normally and keeping your torso upright','Release slowly and repeat on the opposite side']::text[],ARRAY['Keep your shoulders level and avoid lifting the shoulder of the arm being stretched','Apply gentle, steady pressure rather than bouncing or forcing the stretch','Focus the stretch on your upper back and posterior shoulder muscles','Breathe deeply throughout the stretch to help muscles relax','Stop immediately if you feel any sharp pain or discomfort']::text[],'full_body','{}'::text[],'bodyweight','full body','beginner',ARRAY['stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','b0c07cf7-545e-4c74-8224-3355a2669fb2','Upright Barbell Row','upright-barbell-row','Starting position: Stand upright with feet shoulder-width apart, holding a barbell with an overhand grip in front of your thighs, arms fully extended. Execution: Pull the barbell straight up along your body toward your chest by lifting your elbows up and out to the sides, then lower back to the starting position with control.',ARRAY['Stand with feet shoulder-width apart and grip the barbell with hands positioned closer than shoulder-width using an overhand grip','Keep the barbell close to your body throughout the entire movement','Pull the barbell straight up by leading with your elbows, lifting them up and out to the sides','Raise the bar to about chest level, keeping your torso upright and core engaged','Lower the barbell back down to the starting position with slow, controlled movement','Maintain proper posture with shoulders back and avoid using momentum']::text[],ARRAY['Keep your elbows higher than your wrists throughout the movement to properly target the target muscles','Avoid pulling the bar too high above chest level to prevent shoulder impingement','Use a controlled tempo on both the lifting and lowering phases to maximize muscle engagement','Keep your core tight and maintain an upright posture to protect your lower back','Start with lighter weight to master the form before progressing to heavier loads']::text[],'back','{}'::text[],'barbell','back','intermediate',ARRAY['strength']::text[],true,true,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','292b7c17-cc1f-4753-a690-8caad6e28879','Upward facing dog pose','upward-facing-dog-pose',null,ARRAY['Lie face down with hands beside your lower ribs.','Press through your hands to lift your chest and thighs off the floor.','Straighten your arms and roll your shoulders back.','Keep the tops of your feet pressing into the mat.']::text[],ARRAY['Only your hands and tops of feet touch the floor.','Engage your legs and firm your thighs.','Do not compress your lower back.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','2763cb57-a57b-4134-9ae4-979414e5d28c','V-Up','v-up-3c56e4','Starting position: Lie flat on your back on the mat with arms extended overhead and legs straight out. Execution: Simultaneously raise your straight legs and torso, reaching your hands toward your feet to form a V-shape, then lower back down under control.',ARRAY['Lie flat on your back with arms extended overhead and legs straight.','Engage your core and simultaneously lift your legs and upper body off the mat.','Reach your hands toward your feet, balancing on your glutes in a V-shape.','Pause briefly at the top while keeping legs and arms straight.','Lower your torso and legs back down with control to the starting position.','Repeat for the desired number of repetitions.']::text[],ARRAY['Keep your legs as straight as possible throughout the movement.','Engage your core to power the movement rather than swinging.','Lower down slowly and with control to maximize tension.','Avoid straining your neck by keeping your gaze forward and up.']::text[],'rectus_abdominis',ARRAY['hip_flexors','obliques','quadriceps']::text[],'bodyweight','core','intermediate',ARRAY['core','strength','calisthenics']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','14044ef0-8d9d-4d65-9365-0f1bc2dd3c11','Walking knee raises','walking-knee-raises','Starting position: Stand tall with feet hip-width apart, arms at your sides, and core engaged. Execution: Lift one knee up toward your chest while maintaining an upright posture, then lower it back down and repeat with the opposite leg in a controlled walking motion.',ARRAY['Stand with feet hip-width apart and engage your core muscles','Lift your right knee up toward your chest to about hip level while keeping your torso upright','Lower your right foot back to the ground in a controlled manner','Immediately lift your left knee up toward your chest to the same height','Continue alternating legs in a smooth, rhythmic pattern','Maintain steady breathing throughout the movement']::text[],ARRAY['Keep your core engaged throughout the entire movement to maximize abdominal activation','Avoid leaning backward or forward - maintain an upright posture with shoulders over hips','Lift knees to hip level or as high as comfortable while maintaining control','Focus on controlled movements rather than speed to ensure proper form and muscle engagement','Keep your supporting leg slightly bent to maintain balance and reduce strain on the knee joint']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['warmup','cardio']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','620b30ac-bc0d-4b48-bec7-b685cf57f883','Walking Lunges','walking-lunges',null,ARRAY['Step forward into lunge','Push through front foot','Bring back leg through to next lunge','Continue walking forward']::text[],ARRAY['Continuous movement','Keep torso upright','Control each step','Great for leg endurance','Need space to perform']::text[],'quads','{}'::text[],'bodyweight','legs',null,ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
