insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','21beb247-bf6f-41a7-b2d3-58c58d103ba0','Walking lunges - backward','walking-lunges-backward','Starting position: Begin in a low lunge position with your right foot forward and left knee down on the mat, maintaining an upright torso. Execution: Step the back foot forward into a standing position, then step back down into a lunge on the opposite side, alternating legs with each repetition.',ARRAY['Start in a low lunge position with one foot forward and the opposite knee touching the ground','Keep your torso upright and engage your core throughout the movement','Step the back foot forward to bring yourself to a brief standing position','Step back down into a lunge position with the opposite leg now forward','Lower the back knee to lightly touch the mat while keeping most weight on the front leg','Continue alternating legs with each repetition, maintaining control throughout']::text[],ARRAY['Keep your front knee aligned over your ankle and avoid letting it cave inward','Maintain an upright posture with your chest up and shoulders back','Control the descent - don''t drop or slam the back knee onto the mat','Keep most of your weight distributed on your front leg throughout the movement','Focus on smooth, controlled transitions between each lunge position']::text[],'quads','{}'::text[],'bodyweight','legs',null,ARRAY['strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
