insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7e16e5c5-0c92-4e6e-8d3e-aaea74c66778','Wall Assisted Hamstring Walk','wall-assisted-hamstring-walk-bf957c','Starting position: Lie on your back on a mat with your feet planted against a wall, knees bent to roughly 90 degrees and arms crossed over your chest. Execution: Press through your heels and slowly ''walk'' your feet up and down the wall in small controlled steps, engaging the hamstrings and glutes while keeping the hips lifted and core braced.',ARRAY['Lie supine on the mat with knees bent and feet flat against the wall.','Cross your arms over your chest and brace your core, keeping the lower back neutral.','Press your heels into the wall and lift the hips slightly off the ground.','Walk your feet upward along the wall in small steps, maintaining tension in the hamstrings.','Reverse the movement, walking the feet back down under control.','Repeat for the prescribed number of steps or repetitions.']::text[],ARRAY['Keep the movement slow and controlled to maximize hamstring engagement.','Maintain a braced core and neutral spine throughout.','Press through the heels rather than the toes to target the hamstrings and glutes.','Avoid letting the hips sag or over-arching the lower back.']::text[],'hamstrings',ARRAY['lower_back','adductors','gastrocnemius']::text[],'wall','physio','beginner',ARRAY['rehabilitation','strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ceaa0c34-9db0-4642-ad6a-c0125ad88c32','Wall Push Ups','wall-push-ups-c2a05e','Starting position: Stand facing a wall at arm''s length, feet shoulder-width apart, and place both palms flat on the wall at chest height with arms extended. Execution: Bend your elbows to lean your chest toward the wall in a controlled manner, then press back through your palms to return to the starting position.',ARRAY['Stand facing the wall and place both palms flat on it at shoulder height, arms straight.','Step your feet back so your body forms a straight line leaning toward the wall.','Bend your elbows and lower your chest toward the wall while keeping your body rigid.','Pause briefly when your face nears the wall, keeping your core braced.','Push through your palms to straighten your arms and return to the start.','Repeat for the desired number of repetitions maintaining steady tempo.']::text[],ARRAY['Keep your body in a straight line from head to heels, avoiding sagging hips.','Move slowly and controlled, both lowering and pressing.','Keep your core engaged and glutes tight throughout.','Position hands slightly wider than shoulders for chest engagement.']::text[],'chest',ARRAY['front_deltoids','triceps','core']::text[],'wall','strength','beginner',ARRAY['strength','calisthenics','warmup']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','ba260d30-e576-4f0b-8d9b-c14df6d419ee','Wall Sit','wall-sit-67cca0','Starting position: Stand with your back flat against a wall, feet shoulder-width apart and positioned slightly forward. Execution: Slide down the wall until your knees are bent at roughly 90 degrees, keeping your back pressed against the wall and thighs parallel to the floor, then hold the position for the desired time.',ARRAY['Position your back flat against a wall with feet about shoulder-width apart.','Walk your feet forward and slide down until knees are bent to 90 degrees.','Keep your back and shoulders pressed firmly against the wall.','Extend your arms forward for balance and keep thighs parallel to the floor.','Hold the isometric position while breathing steadily.','Push through your heels to slide back up to standing.']::text[],ARRAY['Keep knees aligned over ankles and not past your toes.','Maintain constant contact between your lower back and the wall.','Distribute your weight through your heels, not your toes.','Breathe steadily throughout the hold rather than holding your breath.']::text[],'quadriceps',ARRAY['glute_max','hamstrings','calves','core']::text[],'wall','strength','beginner',ARRAY['isometric','strength','functional']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','0790eb48-18ee-4bae-9c32-b8049dad767f','Wall Sits','wall-sits-6e0edb','Starting position: Stand with your back against a wall, feet shoulder-width apart. Execution: Slide down the wall until thighs are parallel to the floor and hold the position.',ARRAY['Stand with back flat against wall','Place feet shoulder-width apart, two feet from wall','Slide down wall until thighs parallel to floor','Keep knees aligned over ankles','Hold position while breathing normally','Slide back up wall to standing']::text[],ARRAY['Keep your back pressed firmly against the wall throughout the hold','Ensure knees stay aligned over ankles, not extending past toes','Distribute weight evenly between both legs to prevent muscle imbalances','Start with shorter holds and gradually increase duration as strength improves']::text[],'bodyweight',ARRAY['hamstrings','calves','core']::text[],'bodyweight','strength','beginner',ARRAY['isometric','calisthenics']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','865864f7-f65e-4ea1-9e43-47fc0881fc00','Warrior I (left)','warrior-i-left',null,ARRAY['From standing, step one foot back about 4 feet.','Bend your front knee to 90 degrees over the ankle.','Turn your back foot out at 45 degrees and press the heel down.','Raise your arms overhead with palms facing each other.']::text[],ARRAY['Square your hips toward the front of the mat.','Keep your front knee over the ankle, not past the toes.','Lift your chest and gaze forward or up.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
