insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1e43a5c6-7d2f-4c45-a87d-28eec849221c','Warrior III (left)','warrior-iii-left',null,ARRAY['From standing, shift your weight onto one foot.','Hinge forward at the hips while lifting your back leg behind you.','Extend your arms forward or alongside your body.','Create a straight line from fingertips to the lifted foot.']::text[],ARRAY['Keep your standing leg strong with a micro-bend.','Square your hips toward the floor.','Engage your core for balance.']::text[],'full_body','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','f570def7-a724-48f5-87b7-66dfad7cc993','Warrior III (right)','warrior-iii-right',null,ARRAY['From standing, shift your weight onto one foot.','Hinge forward at the hips while lifting your back leg behind you.','Extend your arms forward or alongside your body.','Create a straight line from fingertips to the lifted foot.']::text[],ARRAY['Keep your standing leg strong with a micro-bend.','Square your hips toward the floor.','Engage your core for balance.']::text[],'glutes','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','balance','strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','4e5467d4-898b-4c22-98d0-5000f9b2c1ed','Wheel pose','wheel-pose',null,ARRAY['Lie on your back with knees bent and feet flat on the floor.','Place your hands beside your ears with fingers pointing toward your shoulders.','Press into your hands and feet to lift your body off the floor.','Straighten your arms and legs as much as possible.']::text[],ARRAY['Warm up your spine with Bridge Pose first.','Keep your feet parallel and hip-width apart.','Press evenly through all four limbs.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','1267bc89-80f9-46ad-9f94-e7e542854042','Wide Grip Barbell Curl','wide-grip-barbell-curl','Starting position: Stand upright holding a barbell with an overhand grip wider than shoulder-width apart, arms fully extended and bar resting against your thighs. Execution: Curl the barbell upward by flexing your biceps while keeping your elbows stationary at your sides, then slowly lower back to the starting position.',ARRAY['Stand with feet shoulder-width apart and grip the barbell with hands positioned wider than shoulder-width using an overhand grip','Keep your core engaged and maintain an upright posture with slight bend in your knees','Keep your elbows close to your sides and stationary throughout the entire movement','Curl the barbell up by contracting your biceps until your forearms are vertical','Slowly lower the barbell back to the starting position with control','Maintain tension in your biceps throughout the entire range of motion']::text[],ARRAY['The wider grip targets the inner head of the biceps more than a standard grip','Keep your wrists straight and aligned with your forearms to prevent injury','Avoid swinging or using momentum - the movement should be controlled and deliberate','Don''t let your elbows drift forward during the curl to maintain proper bicep activation','Focus on the eccentric (lowering) portion of the movement for maximum muscle engagement']::text[],'biceps','{}'::text[],'barbell','arms','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c9ff47ce-69d3-4b32-8eb4-6fdac8d8a9f2','Wide Grip Lat Pulldown','wide-grip-lat-pulldown','Starting position: Sit at a lat pulldown machine with an overhand grip (palms down) and hands wider than shoulder-width. Execution: Pull the bar down to your chest while keeping your elbows close to your body, then slowly return to starting position.',ARRAY['Adjust the seat height so your thighs fit snugly under the leg pads to prevent your body from lifting during the exercise','Grasp the bar with both hands using an overhand grip, positioning your hands wider than shoulder-width apart','Lean back slightly from your hips while maintaining a straight spine and engaged core','Pull the bar down smoothly toward your upper chest, leading with your elbows and focusing on squeezing your shoulder blades together','Hold the bottom position briefly, feeling the contraction in your back muscles','Slowly return the bar to the starting position with control, allowing your arms to fully extend without letting the weight stack slam down']::text[],ARRAY['Keep your torso upright with only a slight backward lean to avoid turning this into a rowing movement','Focus on pulling with your back muscles rather than your arms by initiating the movement with your lats and squeezing your shoulder blades','Avoid pulling the bar behind your neck as this can cause shoulder impingement and injury','Maintain control throughout the entire range of motion, especially during the eccentric phase when returning to the starting position','Keep your wrists straight and avoid gripping the bar too tightly to prevent forearm fatigue from limiting your back workout']::text[],'back','{}'::text[],'cable','back','beginner',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','82610c61-8595-4814-a657-662932c9081d','Wide Grip Smith Machine Upright Row','wide-grip-smith-machine-upright-row','Starting position: Stand at a Smith machine with a pronated grip and hands spaced wider than shoulder-width apart. Execution: Pull the bar toward your neck, keeping elbows pointed outward, then slowly lower to the starting position.',ARRAY['Position yourself under the Smith machine bar and grip it with hands placed wider than shoulder-width apart using an overhand grip','Stand with feet shoulder-width apart, core engaged, and shoulders pulled back with the bar resting at upper thigh level','Initiate the movement by pulling your elbows up and out to the sides, keeping the bar close to your body','Continue pulling until the bar reaches chest level, ensuring your elbows remain higher than your wrists throughout the movement','Pause briefly at the top position while squeezing your shoulder blades together','Lower the bar slowly and controlled back to the starting position, maintaining tension in your shoulders']::text[],ARRAY['Keep your core tight and maintain an upright posture throughout the entire movement to protect your lower back','Avoid pulling the bar too high above chest level as this can cause shoulder impingement and injury','Focus on leading the movement with your elbows rather than your hands to properly target the deltoids','Use the Smith machine''s guided bar path to maintain proper form and prevent the bar from drifting away from your body','Start with lighter weight to master the movement pattern before progressing to heavier loads']::text[],'shoulders','{}'::text[],'machine','shoulders','intermediate',ARRAY['strength']::text[],true,false,true,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','65b90fab-d4d0-454e-8cf4-66a953ef982c','Wild thing pose (left)','wild-thing-pose-left',null,ARRAY['From Side Plank, step your top foot behind you.','Press through your bottom hand and lift your hips.','Reach your top arm overhead and open your chest toward the ceiling.','Let your head drop back gently.']::text[],ARRAY['Keep your supporting arm strong.','Open your chest fully.','Press firmly through both feet.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','7e217e49-9603-4d40-ab68-f83ee11b5cf3','Wild thing pose (right)','wild-thing-pose-right',null,ARRAY['From Side Plank, step your top foot behind you.','Press through your bottom hand and lift your hips.','Reach your top arm overhead and open your chest toward the ceiling.','Let your head drop back gently.']::text[],ARRAY['Keep your supporting arm strong.','Open your chest fully.','Press firmly through both feet.']::text[],'back','{}'::text[],'bodyweight','yoga','beginner',ARRAY['yoga','stretching','balance']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','c02cd05c-b615-4b43-a2f5-6c4931e0619b','Wrist rotation','wrist-rotation-ced707','Starting position: Stand tall with feet hip-width apart, elbows bent and raised in front of you with hands closed into loose fists. Execution: Rotate both wrists in controlled circles, cycling the fists through their full range of motion to warm up and mobilize the wrist joints.',ARRAY['Stand upright with feet hip-width apart and core lightly engaged.','Bend both elbows and bring your fists up in front of your torso.','Slowly rotate your wrists in circular motions, keeping fists closed.','Complete the rotations in one direction, then reverse.','Keep the movement smooth and controlled throughout.']::text[],ARRAY['Keep shoulders relaxed and away from the ears.','Move only through the wrists, keeping arms relatively still.','Perform rotations slowly to avoid straining the joint.']::text[],'forearms',ARRAY['biceps','front_deltoids']::text[],'bodyweight','warmup','beginner',ARRAY['warmup','mobility']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','592c2408-5da3-4cca-9453-9dc9cfec6d9f','Y-superman crunch','y-superman-crunch','Starting position: Lie face down on the floor with arms extended overhead in a Y-shape (wider than shoulder-width) and legs straight. Execution: Simultaneously lift your chest, arms, and legs off the ground while crunching your core, creating a superman position with Y-shaped arms.',ARRAY['Lie face down with your forehead resting on the ground and arms extended overhead in a wide Y-shape','Keep your legs straight and together, with toes pointed','Engage your core and glutes before initiating the movement','Simultaneously lift your chest, arms, and legs off the ground while squeezing your shoulder blades together','Hold the top position briefly while maintaining the Y-arm position','Lower back down to starting position with control']::text[],ARRAY['Keep your neck in neutral alignment by looking down at the floor rather than lifting your head','Focus on lifting through your chest and upper back rather than straining your lower back','Maintain the wide Y-arm position throughout the entire movement to target the posterior deltoids','Start with shorter holds and fewer repetitions to build strength gradually','Breathe steadily throughout the exercise and avoid holding your breath']::text[],'core','{}'::text[],'bodyweight','core','intermediate',ARRAY['strength','core']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles", "equipment" = excluded."equipment", "category" = excluded."category", "difficulty" = excluded."difficulty", "exercise_type" = excluded."exercise_type", "has_video" = excluded."has_video", "has_video_white" = excluded."has_video_white", "has_video_gym" = excluded."has_video_gym", "updated_at" = excluded."updated_at";
insert into exercise_catalog ("provider","external_id","name","slug","description","instructions","exercise_tips","primary_muscle","secondary_muscles","equipment","category","difficulty","exercise_type","has_video","has_video_white","has_video_gym","updated_at") values ('your_move','16b4d2da-13c2-419b-aa1a-14a443294762','Zercher Squats','zercher-squats','Starting position: Stand with feet shoulder-width apart, arms crossed in front of your chest with elbows bent at 90 degrees, creating a shelf with your forearms. Execution: Lower into a deep squat by pushing your hips back and bending your knees while keeping your torso upright, then drive through your heels to return to starting position.',ARRAY['Stand with feet shoulder-width apart and toes slightly turned out','Cross your arms in front of your chest, creating a stable shelf with your forearms','Initiate the movement by pushing your hips back and bending at the knees','Lower your body until your thighs are parallel to the floor or as deep as mobility allows','Keep your chest up and core engaged throughout the entire movement','Drive through your heels and push the floor away to return to standing position']::text[],ARRAY['Keep your elbows high and forearms parallel to the floor to maintain proper posture','Focus on sitting back into your hips rather than just bending your knees forward','Maintain a neutral spine and avoid rounding your back during the descent','Control the tempo with a slow descent and powerful upward drive','Your knees should track over your toes without caving inward']::text[],'quads','{}'::text[],'barbell','legs','intermediate',ARRAY['strength']::text[],true,true,false,now()) on conflict (provider, external_id) do update set "name" = excluded."name", "slug" = excluded."slug", "description" = excluded."description", "instructions" = excluded."instructions", "exercise_tips" = excluded."exercise_tips", "primary_muscle" = excluded."primary_muscle", "secondary_muscles" = excluded."secondary_muscles"